@celery_app.task(
    name="hermes_content_factory.continue_producer_benchmark_turn",
    bind=True,
    max_retries=2,
)
def continue_producer_benchmark_turn(self, *, attachment_id: int) -> dict[str, Any]:
    """Continue one durable Producer turn after benchmark analysis completes.

    The user submitted the URL and request in one action.  Keeping the pending
    turn on the server means a browser refresh cannot lose the handoff from the
    Whisper/multimodal worker to Hermes.  ``run_producer_turn`` owns the turn's
    idempotency, so a retry can never append a duplicate user or assistant row.
    """

    from app.data.models.hermes_agent import (
        HermesAgentConversation,
        HermesContentProducerAttachment,
    )
    from app.services.hermes_agent.content_producer import run_producer_turn

    db = SessionLocal()
    try:
        row = db.get(HermesContentProducerAttachment, int(attachment_id))
        if row is None:
            return {"status": "missing", "attachment_id": int(attachment_id)}
        meta = dict(row.meta_json or {})
        analysis = dict(row.analysis_json or {})
        if meta.get("active_for_current_requirement", True) is False:
            analysis["producer_turn_status"] = "superseded"
            row.analysis_json = analysis
            db.add(row)
            db.commit()
            return {"status": "superseded", "attachment_id": int(row.id)}
        if (
            row.analysis_status != "ready"
            or str(analysis.get("multimodal_status") or "") != "success"
        ):
            raise RuntimeError("benchmark multimodal analysis is not ready")
        message = str(meta.get("analysis_request_context") or "").strip()
        client_turn_id = str(meta.get("producer_turn_client_id") or "").strip()
        if not message or not client_turn_id:
            return {"status": "no_pending_turn", "attachment_id": int(row.id)}
        conversation = (
            db.query(HermesAgentConversation)
            .filter(
                HermesAgentConversation.id == int(row.conversation_id),
                HermesAgentConversation.workspace_id == int(row.workspace_id),
                HermesAgentConversation.user_id == int(row.user_id),
            )
            .one_or_none()
        )
        if conversation is None:
            raise RuntimeError("producer conversation is missing")
        analysis.update({
            "producer_turn_status": "processing",
            "producer_turn_started_at": _stage_now().isoformat(),
        })
        row.analysis_json = analysis
        db.add(row)
        db.commit()

        conversation, decision = asyncio.run(
            run_producer_turn(
                db,
                workspace_id=int(row.workspace_id),
                user_id=int(row.user_id),
                message=message,
                session_key=str(dict(conversation.meta_json or {}).get("session_key") or ""),
                product_id=(
                    int(meta["producer_turn_product_id"])
                    if meta.get("producer_turn_product_id") is not None
                    else None
                ),
                product_selection_explicit=True,
                client_turn_id=client_turn_id,
            )
        )
        row = db.get(HermesContentProducerAttachment, int(attachment_id))
        if row is not None:
            analysis = dict(row.analysis_json or {})
            analysis.update({
                "producer_turn_status": "success",
                "producer_turn_completed_at": _stage_now().isoformat(),
                "producer_decision_status": str(decision.status),
            })
            analysis.pop("producer_turn_error", None)
            row.analysis_json = analysis
            db.add(row)
            db.commit()
        return {
            "status": "success",
            "attachment_id": int(attachment_id),
            "decision_status": str(decision.status),
        }
    except Exception as exc:  # noqa: BLE001
        db.rollback()
        row = db.get(HermesContentProducerAttachment, int(attachment_id))
        if int(self.request.retries or 0) < int(self.max_retries or 2):
            if row is not None:
                analysis = dict(row.analysis_json or {})
                analysis.update({
                    "producer_turn_status": "queued",
                    "producer_turn_error": type(exc).__name__[:120],
                })
                row.analysis_json = analysis
                db.add(row)
                db.commit()
            raise self.retry(
                exc=exc,
                countdown=20 * (2 ** int(self.request.retries or 0)),
            )
        if row is not None:
            analysis = dict(row.analysis_json or {})
            analysis.update({
                "producer_turn_status": "failed",
                "producer_turn_error": type(exc).__name__[:120],
                "producer_turn_completed_at": _stage_now().isoformat(),
            })
            row.analysis_json = analysis
            db.add(row)
            db.commit()
        return {"status": "failed", "attachment_id": int(attachment_id)}
    finally:
        db.close()
