def _positive_int(value: Any, fallback: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return int(fallback)
    return parsed if parsed > 0 else int(fallback)


def _content_stage_execution_limits(
    stage: HermesContentFactoryStage | str,
    project: HermesContentFactoryProject | None = None,
) -> tuple[int, int]:
    """Return auditable, project-configurable Celery limits for one stage.

    Whole-series planning scales with the number of pages it must actually
    direct and review.  It is deliberately independent of product, niche,
    content mode, prompt wording, or a campaign mother template.
    """
    stage_name = str(
        stage if isinstance(stage, str) else getattr(stage, "stage", "")
    ).strip().upper()
    generic_soft = _positive_int(
        getattr(settings, "HERMES_CONTENT_STAGE_SOFT_LIMIT_SECONDS", 900),
        900,
    )
    maximum_soft = max(
        generic_soft,
        _positive_int(
            getattr(
                settings,
                "HERMES_CONTENT_MAX_STAGE_SOFT_LIMIT_SECONDS",
                7200,
            ),
            7200,
        ),
    )
    soft_limit = generic_soft
    config = dict(getattr(project, "config_json", None) or {})

    if stage_name == "SERIES_DIRECTOR":
        brief = dict(config.get("director_series_brief") or {})
        policy = dict(config.get("director_loop_policy") or {})
        target_count = _positive_int(
            brief.get("target_count") or config.get("video_count"),
            1,
        )
        page_size = _positive_int(policy.get("series_page_size"), 10)
        page_count = max(1, math.ceil(target_count / page_size))
        # Normal approved path: coverage Director + coverage Critic, one
        # Director/Critic pair per page, and one final global Critic pass.
        expected_model_calls = 3 + (2 * page_count)
        series_base = _positive_int(
            getattr(
                settings,
                "HERMES_CONTENT_SERIES_BASE_BUDGET_SECONDS",
                300,
            ),
            300,
        )
        call_budget = _positive_int(
            getattr(
                settings,
                "HERMES_CONTENT_MODEL_CALL_BUDGET_SECONDS",
                150,
            ),
            150,
        )
        soft_limit = max(
            generic_soft,
            series_base + expected_model_calls * call_budget,
        )
    elif stage_name in {"DIRECTOR", "PRODUCTION_PLAN"}:
        soft_limit = max(
            generic_soft,
            _positive_int(
                getattr(
                    settings,
                    "HERMES_CONTENT_CONTROL_STAGE_SOFT_LIMIT_SECONDS",
                    1800,
                ),
                1800,
            ),
        )

    configured_budgets = config.get("stage_execution_budgets")
    configured_stage = (
        dict(configured_budgets.get(stage_name) or {})
        if isinstance(configured_budgets, dict)
        and isinstance(configured_budgets.get(stage_name), dict)
        else {}
    )
    if configured_stage:
        soft_limit = _positive_int(
            configured_stage.get("soft_seconds"),
            soft_limit,
        )
    soft_limit = max(60, min(maximum_soft, int(soft_limit)))
    hard_grace = _positive_int(
        getattr(
            settings,
            "HERMES_CONTENT_STAGE_HARD_LIMIT_GRACE_SECONDS",
            60,
        ),
        60,
    )
    hard_limit = soft_limit + hard_grace
    if configured_stage:
        hard_limit = _positive_int(
            configured_stage.get("hard_seconds"),
            hard_limit,
        )
    hard_limit = max(soft_limit + 1, min(maximum_soft + hard_grace, hard_limit))
    return int(soft_limit), int(hard_limit)


def _stamp_stage_execution_budget(
    stage: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    *,
    now: datetime | None = None,
) -> tuple[int, int]:
    soft_limit, hard_limit = _content_stage_execution_limits(stage, project)
    current = now or _stage_now()
    lease_grace = _positive_int(
        getattr(
            settings,
            "HERMES_CONTENT_EXECUTION_LEASE_GRACE_SECONDS",
            300,
        ),
        300,
    )
    values = dict(stage.input_json or {})
    values.update({
        "execution_budget_version": "stage-scaled-v1",
        "execution_soft_time_limit_seconds": int(soft_limit),
        "execution_hard_time_limit_seconds": int(hard_limit),
        "execution_lease_expires_at": (
            current + timedelta(seconds=hard_limit + lease_grace)
        ).isoformat(),
    })
    stage.input_json = values
    return soft_limit, hard_limit


def _merge_learning_dict(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    merged = dict(base or {})
    for key, value in dict(override or {}).items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = _merge_learning_dict(dict(merged[key]), value)
        else:
            merged[key] = value
    return merged


def _baseline_hermes_learning() -> dict[str, Any]:
    return {
        "schema_version": "1.0",
        "policy_version": HERMES_LEARNING_POLICY_VERSION,
        "quality_contract": {
            "segment_prompt_only": True,
            "reference_roles_are_authoritative": True,
            "original_product_visual_is_only_package_authority": True,
            "generated_product_panels_are_action_or_composition_only": True,
            "minimal_segment_references": True,
            "copy_delivery_lossless": True,
            "conversion_structure_owned_by_showrunner": True,
            "reject_structured_payload_inside_spoken_copy": True,
            "forbidden_spoken_payload_tokens": [
                "schema_version", "reference_indices", "duration':", "characters':",
                "mandatory_end_copy", "continuity_note",
            ],
        },
        "experience_ledger": {
            "stage_successes": {},
            "stage_failures": {},
            "provider_successes": {},
            "provider_failures": {},
            "observations": [],
        },
    }


def _content_product_for_project(
    db,
    project: HermesContentFactoryProject,
    *,
    for_update: bool = False,
) -> HermesContentProduct | None:
    config = dict(project.config_json or {})
    try:
        product_id = int(config.get("product_id") or project.product_id or 0)
    except (TypeError, ValueError):
        product_id = 0
    if product_id <= 0:
        return None
    query = db.query(HermesContentProduct).filter(
        HermesContentProduct.id == product_id,
        HermesContentProduct.workspace_id == int(project.workspace_id),
    )
    if for_update:
        query = query.with_for_update()
    return query.one_or_none()


def _effective_hermes_learning(db, project: HermesContentFactoryProject) -> dict[str, Any]:
    learning = _baseline_hermes_learning()
    product = _content_product_for_project(db, project)
    if product is not None:
        product_learning = dict(dict(product.meta_json or {}).get("hermes_learning") or {})
        learning = _merge_learning_dict(learning, product_learning)
    project_learning = dict(dict(project.state_json or {}).get("hermes_learning") or {})
    learning = _merge_learning_dict(learning, project_learning)
    learning["policy_version"] = HERMES_LEARNING_POLICY_VERSION
    return learning


def _persist_hermes_learning(
    db,
    project: HermesContentFactoryProject,
    learning: dict[str, Any],
    *,
    persist_to_product: bool = True,
) -> None:
    bounded = _merge_learning_dict(_baseline_hermes_learning(), learning)
    ledger = dict(bounded.get("experience_ledger") or {})
    ledger["observations"] = list(ledger.get("observations") or [])[-HERMES_LEARNING_OBSERVATION_LIMIT:]
    bounded["experience_ledger"] = ledger
    bounded["policy_version"] = HERMES_LEARNING_POLICY_VERSION
    state = dict(project.state_json or {})
    state["hermes_learning"] = bounded
    project.state_json = state
    if not persist_to_product:
        return
    product = _content_product_for_project(db, project, for_update=True)
    if product is None:
        return
    product_meta = dict(product.meta_json or {})
    existing = dict(product_meta.get("hermes_learning") or {})
    product_learning = _merge_learning_dict(existing, bounded)
    product_ledger = dict(product_learning.get("experience_ledger") or {})
    product_ledger["observations"] = list(product_ledger.get("observations") or [])[-HERMES_LEARNING_OBSERVATION_LIMIT:]
    product_learning["experience_ledger"] = product_ledger
    product_learning["policy_version"] = HERMES_LEARNING_POLICY_VERSION
    product_meta["hermes_learning"] = product_learning
    product_meta["hermes_learning_updated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    product.meta_json = product_meta


def _record_hermes_observation(
    db,
    project: HermesContentFactoryProject,
    *,
    category: str,
    outcome: str,
    details: dict[str, Any] | None = None,
    stage: str | None = None,
    provider: str | None = None,
) -> dict[str, Any]:
    # Serialize updates for concurrent projects using the same product library
    # entry; the workspace filter prevents cross-tenant learning leakage.
    _content_product_for_project(db, project, for_update=True)
    learning = _effective_hermes_learning(db, project)
    ledger = dict(learning.get("experience_ledger") or {})
    counter_name = "stage_successes" if outcome == "success" else "stage_failures"
    counter_key = str(stage or category or "unknown")
    if provider:
        counter_name = "provider_successes" if outcome == "success" else "provider_failures"
        counter_key = str(provider)
    counters = dict(ledger.get(counter_name) or {})
    counters[counter_key] = int(counters.get(counter_key) or 0) + 1
    ledger[counter_name] = counters
    observations = list(ledger.get("observations") or [])
    observations.append({
        "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        "category": str(category),
        "outcome": str(outcome),
        "stage": str(stage or ""),
        "provider": str(provider or ""),
        "details": _prompt_safe_value(details or {}, max_string=300, max_items=12),
    })
    ledger["observations"] = observations[-HERMES_LEARNING_OBSERVATION_LIMIT:]
    learning["experience_ledger"] = ledger
    _persist_hermes_learning(db, project, learning)
    return learning


def _stage_now() -> datetime:
    """Use one wall-clock basis for DB lease and retry comparisons.

    The project/stage tables store naive local timestamps. Using utcnow() here
    makes fresh rows look like future rows on the China-hosted server, so
    self-heal never republishes lost queued tasks.
    """
    return datetime.now()


def _safe_revoke_task(task_id: str | None, *, terminate: bool = False, signal: str | None = None) -> bool:
    value = str(task_id or "").strip()
    if not value:
        return False
    try:
        kwargs: dict[str, Any] = {"terminate": terminate}
        if signal:
            kwargs["signal"] = signal
        celery_app.control.revoke(value, **kwargs)
        return True
    except Exception:
        return False


def _target_video_count(project: HermesContentFactoryProject) -> int:
    return max(1, min(50, int(dict(project.config_json or {}).get("video_count") or 1)))


def _variant_pipeline(project: HermesContentFactoryProject) -> dict[str, Any]:
    state = dict(project.state_json or {})
    pipeline = dict(state.get("video_variant_pipeline") or {})
    target = _target_video_count(project)
    active = int(pipeline.get("active_index") or state.get("active_variant_index") or 1)
    active = max(1, min(target, active))
    pipeline.setdefault("target_count", target)
    pipeline["target_count"] = target
    pipeline["active_index"] = active
    pipeline.setdefault("submitted_indices", [])
    pipeline.setdefault("completed_indices", [])
    pipeline.setdefault("failed_indices", [])
    pipeline.setdefault("started_at", datetime.now(timezone.utc).replace(tzinfo=None).isoformat())
    return pipeline


def _authoritative_completed_variant_indices(
    durable_asset_indices: Iterable[int],
    *,
    target: int,
) -> list[int]:
    """Return completion state from durable local-video truth only.

    Pipeline JSON is a scheduling cache, not proof that a deliverable still
    exists.  A quality reset or variant cleanup can legitimately remove an
    earlier video asset.  Unioning that stale cache back into the authoritative
    set makes a target-50 project terminate with fewer than 50 local MP4s.
    """
    return sorted({
        int(value)
        for value in durable_asset_indices
        if str(value).strip().isdigit() and 1 <= int(value) <= int(target)
    })


def _finalize_variant_pipeline_state(
    state: dict[str, Any],
    *,
    completed_indices: Iterable[int],
    target: int,
) -> dict[str, Any]:
    """Remove transient recovery markers once durable target output exists."""
    values = dict(state or {})
    pipeline = dict(values.get("video_variant_pipeline") or {})
    completed = _authoritative_completed_variant_indices(
        completed_indices,
        target=max(1, int(target)),
    )
    pipeline["target_count"] = max(1, int(target))
    pipeline["completed_indices"] = completed
    pipeline["failed_indices"] = [
        int(value)
        for value in list(pipeline.get("failed_indices") or [])
        if str(value).strip().isdigit() and int(value) not in completed
    ]
    pipeline["completion_blocked_missing_indices"] = []
    for key in (
        "awaiting_completed_variant_index",
        "awaiting_completion_since",
        "completion_gate_error",
        "last_completion_gate_requeue_at",
    ):
        pipeline.pop(key, None)
    values["video_variant_pipeline"] = pipeline
    values["ai_video_pending_task_ids"] = []
    values["ai_video_failed_task_ids"] = []
    values["ai_video_wait_task_id"] = None
    values.pop("ai_video_terminal_failure", None)
    return values


def _sequential_variants_enabled(project: HermesContentFactoryProject) -> bool:
    return _target_video_count(project) > 1


def _variant_rollout_authorized(
    project: HermesContentFactoryProject,
    variant_index: int,
) -> bool:
    return rollout_variant_authorized(
        dict(project.config_json or {}),
        target_count=_target_video_count(project),
        variant_index=int(variant_index),
    )


def _reached_variant_rollout_checkpoint(
    project: HermesContentFactoryProject,
    completed_variant_indices: Iterable[int],
):
    return rollout_checkpoint_reached(
        dict(project.config_json or {}),
        target_count=_target_video_count(project),
        completed_variant_indices=completed_variant_indices,
    )


_TERMINAL_VIDEO_TASK_STATES = {
    "success",
    "succeeded",
    "failed",
    "fail",
    "error",
    "timeout",
    "cancelled",
    "canceled",
    "superseded",
    "downloaded",
}


def _clear_terminal_video_work_ledger_at_checkpoint(
    db,
    project: HermesContentFactoryProject,
    state: dict[str, Any],
) -> tuple[dict[str, Any], bool]:
    """Retire a fully terminal provider batch from the active-work ledger.

    Provider task/group ids are operational state, not the durable audit trail.
    The latter remains available in ``ai_video_group_statuses``, video asset
    metadata, and the provider task rows themselves.  Missing or non-terminal
    task rows deliberately fail closed so an automatic quality pause can keep
    draining already-submitted work.
    """
    task_ids = {
        int(value)
        for value in list(state.get("ai_video_task_ids") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    for group in list(state.get("ai_video_groups") or []):
        if not isinstance(group, dict):
            continue
        for segment in list(group.get("segments") or []):
            if not isinstance(segment, dict):
                continue
            value = segment.get("task_id")
            if str(value or "").strip().isdigit() and int(value) > 0:
                task_ids.add(int(value))
    if not task_ids:
        return state, False

    rows = (
        db.query(KieTask.id, KieTask.state)
        .filter(
            KieTask.id.in_(sorted(task_ids)),
            KieTask.workspace_id == int(project.workspace_id),
            KieTask.created_by_user_id == project.user_id,
        )
        .all()
    )
    states_by_id = {
        int(task_id): str(task_state or "").strip().lower()
        for task_id, task_state in rows
    }
    if set(states_by_id) != task_ids or any(
        task_state not in _TERMINAL_VIDEO_TASK_STATES
        for task_state in states_by_id.values()
    ):
        return state, False

    retired = sorted(task_ids)
    state.update({
        "ai_video_task_ids": [],
        "ai_video_groups": [],
        "ai_video_pending_task_ids": [],
        "ai_video_failed_task_ids": [],
        "ai_video_wait_task_id": None,
        "ai_video_retired_task_ids": retired,
        "ai_video_work_ledger_retired_at": _stage_now().isoformat(),
        "ai_video_work_ledger_retire_reason": "variant_rollout_checkpoint_terminal",
    })
    return state, True


def _scoped_content_video_tasks(
    db,
    project: HermesContentFactoryProject,
    task_ids: Iterable[int],
) -> list[KieTask]:
    """Load provider tasks inside the owning project tenant boundary.

    Task ids are persisted in mutable JSON ledgers for recovery.  They are not
    an authorization boundary: a stale or corrupted id must never let one
    project inspect or mutate another workspace/user's provider task.
    """
    normalized_ids = sorted({
        int(value)
        for value in task_ids
        if str(value or "").strip().isdigit() and int(value) > 0
    })
    if not normalized_ids:
        return []
    return (
        db.query(KieTask)
        .filter(
            KieTask.id.in_(normalized_ids),
            KieTask.workspace_id == int(project.workspace_id),
            KieTask.created_by_user_id == project.user_id,
        )
        .all()
    )


def _supersede_untracked_local_content_video_tasks(
    db,
    project: HermesContentFactoryProject,
    *,
    now: datetime | None = None,
) -> list[int]:
    """Fail closed local tasks that lost their project-ledger commit.

    Task rows and the project JSON ledger normally commit atomically.  A
    worker termination can nevertheless expose an already-flushed local retry
    row after the owning stage transaction is interrupted.  Such a row is not
    part of any authoritative media group and must never be released later by
    a generic dependency sweep.  Provider-visible/in-flight rows are left
    untouched so paid results are never destroyed.
    """

    state = dict(project.state_json or {})
    now = (now or _stage_now()).replace(tzinfo=None)
    # A replacement task can become visible through the provider-task commit
    # before the long-running multimodal waiter reaches its final project-ledger
    # commit.  Self-heal runs in another transaction and must not interpret
    # that legitimate commit window as an abandoned task.  The wait heartbeat
    # is the ordering fence: a task created after the currently recorded
    # heartbeat belongs to that in-flight waiter.  The absolute grace also
    # protects a newly created task when an older project has no heartbeat.
    orphan_grace_seconds = max(VIDEO_WAIT_STALE_SECONDS * 2, 120)
    orphan_grace_cutoff = now - timedelta(seconds=orphan_grace_seconds)
    heartbeat_raw = str(state.get("ai_video_wait_heartbeat_at") or "").strip()
    try:
        ledger_heartbeat = datetime.fromisoformat(
            heartbeat_raw.replace("Z", "+00:00")
        ).replace(tzinfo=None)
    except (TypeError, ValueError):
        ledger_heartbeat = None
    authoritative_ids = {
        int(value)
        for value in list(state.get("ai_video_task_ids") or [])
        if str(value or "").strip().isdigit() and int(value) > 0
    }
    for group in list(state.get("ai_video_groups") or []):
        if not isinstance(group, dict):
            continue
        for segment in list(group.get("segments") or []):
            if not isinstance(segment, dict):
                continue
            value = segment.get("task_id")
            if str(value or "").strip().isdigit() and int(value) > 0:
                authoritative_ids.add(int(value))

    candidates = (
        db.query(KieTask)
        .filter(
            KieTask.workspace_id == int(project.workspace_id),
            KieTask.created_by_user_id == project.user_id,
            KieTask.state.in_(("queued_local", "waiting_dependency")),
            KieTask.input_json["content_factory_project_id"].as_integer()
            == int(project.id),
        )
        .all()
    )
    superseded: list[int] = []
    now_iso = _stage_now().isoformat()
    for task in candidates:
        if int(task.id) in authoritative_ids:
            continue
        created_at = getattr(task, "created_at", None)
        if isinstance(created_at, datetime):
            created_at = created_at.replace(tzinfo=None)
            if created_at >= orphan_grace_cutoff:
                continue
            if (
                ledger_heartbeat is not None
                and created_at >= ledger_heartbeat
            ):
                continue
        params = dict(task.input_json or {})
        if int(params.get("content_factory_project_id") or 0) != int(project.id):
            continue
        task.state = "failed"
        task.fail_code = CONTENT_FACTORY_VARIANT_SUPERSEDED_CODE
        task.fail_msg = (
            "Superseded before provider submission because the local task "
            "is not present in the owning project's authoritative media ledger."
        )[:512]
        set_task_local_meta(
            task,
            superseded_at=now_iso,
            superseded_reason="untracked_local_task_after_interrupted_commit",
            poll_owner_task_id=None,
            poll_heartbeat_at=None,
            poll_heartbeat_provider=None,
        )
        db.add(task)
        superseded.append(int(task.id))
    return superseded


def _pause_at_variant_rollout_checkpoint(
    db,
    project: HermesContentFactoryProject,
    *,
    completed_variant_indices: Iterable[int],
) -> dict[str, Any] | None:
    """Stop admission after an explicitly released batch is durable.

    This is an automatic quality checkpoint, not an operator pause.  Already
    submitted provider work may drain, but no new variant is admitted until
    the operator changes the project-owned release manifest and resumes.
    """
    gate = _reached_variant_rollout_checkpoint(
        project,
        completed_variant_indices,
    )
    if gate is None:
        return None
    config = dict(project.config_json or {})
    if bool(config.get("manual_paused", False)):
        return {
            "status": "manual_pause_wins_rollout_checkpoint",
            "batch_id": gate.batch_id,
        }
    state = dict(project.state_json or {})
    state, ledger_cleared = _clear_terminal_video_work_ledger_at_checkpoint(
        db,
        project,
        state,
    )
    existing = dict(state.get("variant_rollout_checkpoint") or {})
    if (
        str(existing.get("batch_id") or "") == gate.batch_id
        and str(project.status or "").lower() == "paused"
    ):
        if ledger_cleared:
            project.state_json = state
            db.add(project)
        return existing

    now = _stage_now().isoformat()
    completed = sorted({
        int(value)
        for value in completed_variant_indices
        if str(value).strip().isdigit()
    })
    checkpoint = {
        "schema_version": "1.0",
        "batch_id": gate.batch_id,
        "authorized_variant_indices": list(gate.authorized_variant_indices),
        "completed_variant_indices": completed,
        "completed_at": now,
        "status": "awaiting_operator_review",
    }
    state.update({
        "variant_rollout_checkpoint": checkpoint,
        "paused_at": now,
        "automatic_quality_paused_at": now,
        "pause_reason_code": "variant_rollout_checkpoint",
        "pause_note": (
            f"Released batch {gate.batch_id} completed; operator review is "
            "required before another variant batch may start."
        ),
        "browser_slot_mode": "dormant",
    })
    project.state_json = state
    project.status = "paused"
    project.last_error = (
        f"并行发布批次 {gate.batch_id} 已完成授权视频 "
        f"{list(gate.authorized_variant_indices)}；系统已自动停在质量检查点，"
        "不会开启下一批。"
    )[:4000]
    from app.services.hermes_agent.content_factory import _release_bridge_for_project

    _release_bridge_for_project(db, project_id=int(project.id))
    db.add(project)
    return checkpoint


def _configured_api_video_variant_parallelism(project: HermesContentFactoryProject) -> int:
    """Return the bounded provider-work concurrency for one project.

    Creative stages remain strictly single-lane because they own the project's
    sticky browser identity.  Only after a variant has submitted its isolated
    API video tasks may the next variant start its browser turn.  Defaulting to
    one keeps every existing project on the established serial behaviour until
    an operator explicitly enables the rollout for that project.
    """
    if not _sequential_variants_enabled(project):
        return 1
    config = dict(project.config_json or {})
    raw = config.get("max_api_video_variants_in_flight")
    # Missing means a pre-policy project. Preserve its serial behaviour until
    # an operator saves a bounded window; newly created projects always persist
    # the manifest-derived recommendation.
    if raw is None:
        return 1
    try:
        requested = int(raw)
    except (TypeError, ValueError):
        requested = 1
    model_id = str(config.get("video_model") or "").strip()
    if not model_id:
        # A missing model is never enough authority to submit media, but it
        # must not crash scheduling/status inspection for a draft or legacy
        # project. Keep the generic provider window conservatively bounded;
        # actual submission still requires a selected registered model.
        return max(1, min(_target_video_count(project), 4, requested))
    return resolve_project_variant_parallelism(
        model_id=model_id,
        requested=requested,
        target_count=_target_video_count(project),
    )


def _inflight_api_video_variant_indices(project: HermesContentFactoryProject) -> set[int]:
    """Return variants with authoritative, non-terminal provider work.

    ``submitted_indices`` is an append-only scheduling ledger.  Older pipeline
    versions could leave an index there after its task group was discarded,
    superseded, or otherwise lost.  Treating ``submitted - completed`` as live
    work permanently consumes the bounded parallel window and blocks every
    later variant.  A slot is live only while a current task group exists and
    its latest group status is non-terminal.
    """
    pipeline = _variant_pipeline(project)
    target = int(pipeline.get("target_count") or _target_video_count(project))
    state = dict(project.state_json or {})
    submitted = {
        int(value) for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit() and 1 <= int(value) <= target
    }
    completed = {
        int(value) for value in list(pipeline.get("completed_indices") or [])
        if str(value).strip().isdigit() and 1 <= int(value) <= target
    }
    group_indices = {
        int(item.get("video_index") or 0)
        for item in list(state.get("ai_video_groups") or [])
        if isinstance(item, dict)
        and 1 <= int(item.get("video_index") or 0) <= target
    }
    latest_status: dict[int, str] = {}
    for item in list(state.get("ai_video_group_statuses") or []):
        if not isinstance(item, dict):
            continue
        index = int(item.get("video_index") or 0)
        if 1 <= index <= target:
            latest_status[index] = str(item.get("status") or "").strip().lower()
    terminal_statuses = {
        "composed", "complete", "completed", "failed", "invalidated",
        "superseded", "cancelled", "canceled",
    }
    live_groups = {
        index for index in group_indices
        if latest_status.get(index, "") not in terminal_statuses
    }
    failed_indices = {
        int(value) for value in list(pipeline.get("failed_indices") or [])
        if str(value).strip().isdigit() and 1 <= int(value) <= target
    }
    invalidated_indices = {
        int(item.get("variant_index") or 0)
        for item in list(state.get("invalidated_video_variants") or [])
        if isinstance(item, dict)
        and 1 <= int(item.get("variant_index") or 0) <= target
    }
    return (
        submitted
        & live_groups
    ) - completed - failed_indices - invalidated_indices


def _terminal_failed_video_variant_indices(
    project: HermesContentFactoryProject,
) -> set[int]:
    """Return submitted variants whose latest provider group is terminally failed.

    A failed provider group has already consumed its bounded same-segment retry
    budget.  Starting a brand-new higher ordinal while such a hole exists
    spends more media budget before the requested complete-video target is
    replenished.  Keep this signal separate from ``pipeline.failed_indices``:
    the latter is written only when the whole variant regeneration begins,
    while group status is the earlier authoritative provider outcome.
    """
    pipeline = _variant_pipeline(project)
    target = int(pipeline.get("target_count") or _target_video_count(project))
    submitted = {
        int(value)
        for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit() and 1 <= int(value) <= target
    }
    completed = {
        int(value)
        for value in list(pipeline.get("completed_indices") or [])
        if str(value).strip().isdigit() and 1 <= int(value) <= target
    }
    latest_status: dict[int, str] = {}
    for item in list(dict(project.state_json or {}).get("ai_video_group_statuses") or []):
        if not isinstance(item, dict):
            continue
        index = int(item.get("video_index") or 0)
        if 1 <= index <= target:
            latest_status[index] = str(item.get("status") or "").strip().lower()
    failed_statuses = {"failed", "invalidated"}
    return {
        index
        for index in submitted - completed
        if latest_status.get(index) in failed_statuses
    }


def _retire_terminal_failed_video_groups_from_active_ledger(
    project: HermesContentFactoryProject,
    *,
    failed_task_ids: Iterable[int],
) -> dict[str, Any] | None:
    """Retire an exhausted group without overwriting newer control work.

    The API-video lane and the next Director/Production Plan lane may run in
    parallel.  A terminal multimodal verdict from the older lane is still an
    authoritative failure for that *variant*, but it no longer owns the
    project-level status once a newer control stage is live.  Keep the failed
    group/status as audit evidence, remove only its task ids from the mutable
    active-work ledger, and let the normal complete-video target gate
    replenish the missing ordinal after the concurrent control stage drains.
    """

    normalized_failed_ids = {
        int(value)
        for value in failed_task_ids
        if str(value or "").strip().isdigit() and int(value) > 0
    }
    if not normalized_failed_ids:
        return None
    state = dict(project.state_json or {})
    failed_group_indices: set[int] = set()
    failed_group_task_ids: set[int] = set()
    for raw_status in list(state.get("ai_video_group_statuses") or []):
        if not isinstance(raw_status, dict):
            continue
        status = dict(raw_status)
        if str(status.get("status") or "").strip().lower() != "failed":
            continue
        status_task_ids = {
            int(value)
            for value in (
                list(status.get("task_ids") or [])
                + list(status.get("failed_task_ids") or [])
            )
            if str(value or "").strip().isdigit() and int(value) > 0
        }
        if not status_task_ids.intersection(normalized_failed_ids):
            continue
        video_index = int(status.get("video_index") or 0)
        if video_index <= 0:
            continue
        failed_group_indices.add(video_index)
        failed_group_task_ids.update(status_task_ids)
    if not failed_group_indices:
        return None

    active_groups = [
        dict(group)
        for group in list(state.get("ai_video_groups") or [])
        if isinstance(group, dict)
    ]
    retired_group_ids = {
        int(segment.get("task_id") or 0)
        for group in active_groups
        if int(group.get("video_index") or 0) in failed_group_indices
        for segment in list(group.get("segments") or [])
        if isinstance(segment, dict)
        and int(segment.get("task_id") or 0) > 0
    }
    retired_task_ids = failed_group_task_ids.union(retired_group_ids)
    state["ai_video_groups"] = [
        group
        for group in active_groups
        if int(group.get("video_index") or 0) not in failed_group_indices
    ]
    state["ai_video_task_ids"] = [
        int(value)
        for value in list(state.get("ai_video_task_ids") or [])
        if str(value or "").strip().isdigit()
        and int(value) > 0
        and int(value) not in retired_task_ids
    ]
    state["ai_video_pending_task_ids"] = [
        int(value)
        for value in list(state.get("ai_video_pending_task_ids") or [])
        if str(value or "").strip().isdigit()
        and int(value) > 0
        and int(value) not in retired_task_ids
    ]
    state["ai_video_failed_task_ids"] = [
        int(value)
        for value in list(state.get("ai_video_failed_task_ids") or [])
        if str(value or "").strip().isdigit()
        and int(value) > 0
        and int(value) not in retired_task_ids
    ]
    history = [
        dict(item)
        for item in list(state.get("ai_video_retired_failed_groups") or [])
        if isinstance(item, dict)
    ]
    history.append({
        "at": _stage_now().isoformat(),
        "video_indices": sorted(failed_group_indices),
        "task_ids": sorted(retired_task_ids),
        "reason": "terminal_segment_execution_qa_while_newer_control_stage_live",
    })
    state["ai_video_retired_failed_groups"] = history[-50:]
    state["ai_video_wait_task_id"] = None
    state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
    state.pop("ai_video_terminal_failure", None)
    project.state_json = state
    return {
        "video_indices": sorted(failed_group_indices),
        "task_ids": sorted(retired_task_ids),
        "remaining_task_ids": list(state["ai_video_task_ids"]),
    }


def _active_variant_index(project: HermesContentFactoryProject) -> int:
    return int(_variant_pipeline(project).get("active_index") or 1)


def _stage_variant_index(stage_row: HermesContentFactoryStage, project: HermesContentFactoryProject) -> int:
    values = dict(stage_row.input_json or {})
    try:
        return max(1, int(values.get("variant_index") or _active_variant_index(project)))
    except (TypeError, ValueError):
        return _active_variant_index(project)


def _set_variant_pipeline(project: HermesContentFactoryProject, pipeline: dict[str, Any]) -> None:
    state = dict(project.state_json or {})
    state["video_variant_pipeline"] = pipeline
    state["active_variant_index"] = int(pipeline.get("active_index") or 1)
    project.state_json = state


def _stage_output_variant(row: HermesContentFactoryStage) -> int | None:
    values = dict(row.input_json or {})
    for source in (dict(row.output_json or {}), dict(dict(row.output_json or {}).get("evidence") or {}), values):
        raw = source.get("content_factory_variant_index") or source.get("variant_index")
        if raw is None:
            # Failed/retrying browser turns commonly persist an error envelope
            # without evidence. Keep walking to input_json, which is the durable
            # dispatch identity for that turn. Returning here makes the waiter
            # misclassify an active variant as missing and publish it twice.
            continue
        try:
            return int(raw)
        except (TypeError, ValueError):
            continue
    return None


def _video_model_policy(project: HermesContentFactoryProject) -> dict[str, Any]:
    config = dict(project.config_json or {})
    generation_mode = str(
        config.get("video_generation_mode") or "image_to_video"
    ).strip().lower()
    return resolve_video_model_policy(
        model_id=str(config.get("video_model") or ""),
        reference_image_limit=int(
            config.get("video_reference_limit") or 7
        ),
        allow_reference_video=bool(
            generation_mode == "video_to_video"
            and config.get("allow_reference_video", False)
        ),
        product_required=_project_uses_product(project),
    )


def _configured_video_generation_mode(
    project: HermesContentFactoryProject | None,
) -> str:
    config = dict(getattr(project, "config_json", None) or {})
    value = str(
        config.get("video_generation_mode") or "image_to_video"
    ).strip().lower()
    return (
        value
        if value in {"text_to_video", "image_to_video", "video_to_video"}
        else "image_to_video"
    )


def _configured_video_resolution(project: HermesContentFactoryProject) -> str:
    config = dict(project.config_json or {})
    raw = str(config.get("video_resolution") or "720p").strip().lower()
    aliases = {
        "480": "480p",
        "480p": "480p",
        "720": "720p",
        "720p": "720p",
        "hd": "720p",
    }
    return aliases.get(raw, "720p")


def _configured_video_aspect_ratio(
    project: HermesContentFactoryProject | None,
) -> str:
    config = dict(getattr(project, "config_json", None) or {})
    raw: Any = config.get("video_aspect_ratio")
    if not raw and isinstance(config.get("director_series_brief"), dict):
        raw = dict(config["director_series_brief"]).get("aspect_ratio")
    if not raw and isinstance(config.get("director_briefs_by_variant"), dict):
        for value in dict(config["director_briefs_by_variant"]).values():
            if isinstance(value, dict) and value.get("aspect_ratio"):
                raw = value["aspect_ratio"]
                break
    text_value = str(raw or "9:16").strip().lower().replace("x", ":").replace("/", ":")
    try:
        width_text, height_text = text_value.split(":", 1)
        width = float(width_text)
        height = float(height_text)
    except (TypeError, ValueError):
        return "9:16"
    if width <= 0 or height <= 0:
        return "9:16"
    return f"{width_text}:{height_text}"


def _configured_video_language(project: HermesContentFactoryProject) -> str:
    config = dict(project.config_json or {})
    raw = str(config.get("video_language") or "en-US").strip().lower().replace("_", "-")
    aliases = {
        "en": "en-US",
        "en-us": "en-US",
        "english": "en-US",
        "us": "en-US",
        "zh": "zh-CN",
        "zh-cn": "zh-CN",
        "cn": "zh-CN",
        "chinese": "zh-CN",
        "中文": "zh-CN",
    }
    return aliases.get(raw, "en-US")


def _video_language_label(project: HermesContentFactoryProject) -> str:
    return {
        "en-US": "English (US)",
        "zh-CN": "Simplified Chinese",
    }.get(_configured_video_language(project), "English (US)")


def _configured_next_stage(project: HermesContentFactoryProject, stage: str) -> str:
    config = dict(project.config_json or {})
    normalized_stage = str(stage or "").upper()
    if (
        normalized_stage == "FACTS"
        and str(config.get("content_director_mode") or "").strip().lower()
        == "enforce"
    ):
        return (
            "SERIES_DIRECTOR"
            if isinstance(config.get("director_series_brief"), dict)
            else "DIRECTOR"
        )
    if (
        normalized_stage == "PRODUCTION_PLAN"
        and _configured_video_generation_mode(project) == "text_to_video"
    ):
        return "VIDEO_PROMPTS"
    return NEXT_STAGE[stage]


def _escape_unescaped_json_string_quotes(text: str) -> str:
    """Escape accidental double quotes inside JSON string values.

    ChatGPT often returns almost-valid JSON with dialogue like
    ``"Female says: "Really?""``. The business envelope is otherwise usable,
    so repair only quotes that cannot be a JSON string terminator.
    """
    source = str(text or "")
    output: list[str] = []
    in_string = False
    escaped = False
    length = len(source)
    for index, char in enumerate(source):
        if char == "\\" and in_string:
            output.append(char)
            escaped = not escaped
            continue
        if char == '"' and not escaped:
            if not in_string:
                in_string = True
                output.append(char)
                continue
            lookahead = index + 1
            while lookahead < length and source[lookahead] in " \t\r\n":
                lookahead += 1
            next_char = source[lookahead] if lookahead < length else ""
            if next_char in {":", ",", "}", "]", ""}:
                in_string = False
                output.append(char)
            else:
                output.append('\\"')
            continue
        escaped = False
        output.append(char)
    return "".join(output)


def _decode_lenient_json_object(text: str) -> dict[str, Any] | None:
    cleaned = str(text or "").strip()
    if not cleaned:
        return None
    attempts = [cleaned]
    repaired = _escape_unescaped_json_string_quotes(cleaned)
    if repaired != cleaned:
        attempts.append(repaired)
    for candidate in attempts:
        try:
            value = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(value, str):
            nested = _decode_lenient_json_object(value)
            if nested is not None:
                return nested
        if isinstance(value, dict):
            return value
    return None


def _extract_envelope(text: str, project_key: str, stage: str) -> dict[str, Any]:
    decoder = json.JSONDecoder()
    found = None
    candidates: list[dict[str, Any]] = []
    cleaned = str(text or "").strip()
    cleaned = cleaned.replace("```json", "```").replace("```JSON", "```")

    def is_stage_request(value: dict[str, Any]) -> bool:
        request_keys = {
            "current_stage",
            "required_result_fields",
            "required_next_stage",
            "browser_asset_paths",
            "previous_outputs",
            "browser_output_path",
        }
        return bool(request_keys.intersection(value.keys()))

    full_value = _decode_lenient_json_object(cleaned)
    if isinstance(full_value, dict) and not is_stage_request(full_value):
        if full_value.get("project_id") == project_key and full_value.get("stage") == stage:
            found = full_value
        elif full_value.get("stage") == stage or isinstance(full_value.get("result"), dict):
            candidates.append(full_value)

    for index, char in enumerate(cleaned):
        if char != "{":
            continue
        try:
            value, _ = decoder.raw_decode(cleaned[index:])
        except json.JSONDecodeError:
            repaired_tail = _escape_unescaped_json_string_quotes(cleaned[index:])
            try:
                value, _ = decoder.raw_decode(repaired_tail)
            except json.JSONDecodeError:
                continue
        if not isinstance(value, dict):
            continue
        if is_stage_request(value):
            continue
        if value.get("project_id") == project_key and value.get("stage") == stage:
            found = value
        elif value.get("stage") == stage or isinstance(value.get("result"), dict):
            candidates.append(value)
    if found is None:
        for candidate in reversed(candidates):
            result = candidate.get("result") if isinstance(candidate.get("result"), dict) else None
            if candidate.get("stage") == stage or result:
                found = candidate
                break
    if found is None:
        raise ValueError("Hermes did not return a valid project JSON envelope")
    found["project_id"] = project_key
    found["stage"] = stage
    if str(found.get("status") or "").upper() in {
        "READY",
        "SUCCESS",
        "SUCCEEDED",
        "OK",
        "DONE",
        "APPROVED",
        "PASS",
        "COMPLETE",
        "COMPLETED",
        "COMPLETE_WITH_VISUAL_QA_GATE",
        "COMPLETED_WITH_CONSTRAINTS",
        "PASS_WITH_CONSTRAINTS",
    }:
        found["status"] = "PASS"
    return found


def _recover_completed_text_from_browser_error(
    error: Exception,
    project_key: str,
    stage: str,
) -> str | None:
    """Keep a complete business response even if the browser collector rejected it.

    Browser-side JSON detection is intentionally conservative while a turn is
    streaming.  A completed ChatGPT turn can nevertheless contain harmless
    unescaped dialogue quotes.  The task layer has the authoritative lenient
    envelope parser, so persist and validate that raw turn before spending a
    recovery cycle or submitting the stage again.
    """
    if not isinstance(error, ChatGPTStageError):
        return None
    raw_text = str(getattr(error, "raw_text", "") or "").strip()
    if not raw_text:
        return None
    try:
        _extract_envelope(raw_text, project_key, stage)
    except ValueError:
        return None
    return raw_text


def _recover_completed_stage_response(
    raw_text: str | None,
    project_key: str,
    stage: str,
) -> str | None:
    """Return a persisted response only when it is a complete stage envelope."""
    candidate = str(raw_text or "").strip()
    if not candidate:
        return None
    try:
        _extract_envelope(candidate, project_key, stage)
    except ValueError:
        return None
    return candidate


def _stage_replay_context_digest(packet: dict[str, Any], stage: str) -> str:
    """Fingerprint the business inputs that make a stage response reusable.

    Attempt ids, browser routing, and recovery flags are intentionally excluded.
    Upstream outputs and the selected asset manifest remain in the fingerprint so
    a review can never be replayed against a newly generated visual board.
    """
    semantic_keys = (
        "content_mode",
        "product_required",
        "product",
        "market",
        "brief",
        "video_variant_index",
        "video_variant_total",
        "video_duration_range_seconds",
        "recommended_video_duration_seconds",
        "video_segment_durations_seconds",
        "video_model",
        "video_resolution",
        "video_language",
        "video_model_policy",
        "marketing_authorization",
        "creative_copy_contract",
        "creative_cast_policy",
        "product_presentation_policy",
        "benchmark_video_analysis",
        "previous_variant_briefs",
        "project_requirements",
        "browser_assets",
        "previous_outputs",
        "visual_repair_instruction",
        "required_result_fields",
        "required_next_stage",
    )
    payload = {
        "stage": stage,
        "context_compiler_version": CONTENT_FACTORY_CONTEXT_COMPILER_VERSION,
    }
    payload.update({key: packet.get(key) for key in semantic_keys if key in packet})
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _recover_prior_stage_attempt_response(
    db: Session,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    replay_context_digest: str,
) -> tuple[str, str | None, int] | None:
    """Find a complete response captured by an earlier attempt of this run.

    Browser completion and business validation are separate events. A worker
    restart or a newly tightened normalizer can therefore leave a complete
    assistant envelope on attempt N while attempt N+1 is already queued. Reuse
    that envelope locally instead of sending the same stage to ChatGPT again.
    Project restarts and video variants are hard isolation boundaries.
    """
    current_input = dict(stage_row.input_json or {})
    current_variant = int(current_input.get("variant_index") or 1)
    current_restart_generation = int(current_input.get("restart_generation") or 0)
    restart_at: datetime | None = None
    restart_value = str(dict(project.state_json or {}).get("last_restart", {}).get("at") or "").strip()
    if restart_value:
        try:
            restart_at = datetime.fromisoformat(restart_value.replace("Z", "+00:00"))
            if restart_at.tzinfo is not None:
                restart_at = restart_at.astimezone(timezone.utc).replace(tzinfo=None)
        except ValueError:
            restart_at = None

    candidates = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == stage_row.project_id,
            HermesContentFactoryStage.stage == stage_row.stage,
            HermesContentFactoryStage.id < stage_row.id,
            HermesContentFactoryStage.response_text.isnot(None),
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .limit(20)
        .all()
    )
    for candidate in candidates:
        candidate_input = dict(candidate.input_json or {})
        # A complete envelope that already failed deterministic business
        # validation is not a late success.  It may be revalidated only on its
        # own durable stage after a code deployment; copying it into a newer
        # stage would erase the invalidation evidence and recreate the same
        # cooldown forever without asking the model for a corrected response.
        if (
            candidate_input.get("captured_response_validation_error")
            or candidate_input.get("captured_response_validation_failed_at")
            or candidate_input.get("semantic_validation_last_error")
            or candidate_input.get("semantic_validation_last_response_sha256")
        ):
            continue
        if int(candidate_input.get("variant_index") or 1) != current_variant:
            continue
        if int(candidate_input.get("restart_generation") or 0) != current_restart_generation:
            continue
        if str(candidate_input.get("replay_context_digest") or "") != replay_context_digest:
            continue
        candidate_created_at = candidate.created_at
        if candidate_created_at and candidate_created_at.tzinfo is not None:
            candidate_created_at = candidate_created_at.astimezone(timezone.utc).replace(tzinfo=None)
        if restart_at is not None and candidate_created_at is not None and candidate_created_at < restart_at:
            continue
        recovered = _recover_completed_stage_response(
            candidate.response_text,
            project.project_key,
            stage_row.stage,
        )
        if recovered is not None:
            # A syntactically complete FAIL envelope is durable evidence for
            # the delivery that produced it, not a reusable business result.
            # Replaying it into a new attempt creates a permanent self-heal
            # loop even after its prompt/compiler inputs have been fixed.
            envelope = _extract_envelope(recovered, project.project_key, stage_row.stage)
            if str(envelope.get("status") or "").upper() != "PASS":
                continue
            return recovered, candidate.chat_url, int(candidate.id)
    return None


def _prefer_chatgpt_response_snapshot(
    persisted_text: str | None,
    incoming_text: str | None,
    project_key: str,
    stage: str,
) -> str:
    """Never let a short streaming fragment overwrite a complete saved turn."""
    persisted = str(persisted_text or "").strip()
    incoming = str(incoming_text or "").strip()
    persisted_complete = _recover_completed_stage_response(persisted, project_key, stage)
    incoming_complete = _recover_completed_stage_response(incoming, project_key, stage)
    if persisted_complete and not incoming_complete:
        return persisted
    if incoming_complete and not persisted_complete:
        return incoming
    if persisted_complete and incoming_complete:
        return incoming if len(incoming) >= len(persisted) else persisted
    return incoming if len(incoming) >= len(persisted) else persisted


def _persist_completed_stage_capture(
    db: Session,
    stage_row: HermesContentFactoryStage,
    *,
    project_key: str,
    stage: str,
    response_text: str | None,
    chat_url: str | None,
    replace_with_incoming_complete: bool = False,
) -> str | None:
    """Durably capture a complete assistant envelope before business validation.

    Schema normalization can evolve independently from browser collection.  A
    response that reached ChatGPT must therefore survive a validation failure
    and be replayed locally instead of submitting the same paid/rate-limited
    browser turn again.
    """
    incoming_complete = _recover_completed_stage_response(
        response_text,
        project_key,
        stage,
    )
    preferred = (
        incoming_complete
        if replace_with_incoming_complete and incoming_complete is not None
        else _prefer_chatgpt_response_snapshot(
            stage_row.response_text,
            response_text,
            project_key,
            stage,
        )
    )
    complete = _recover_completed_stage_response(preferred, project_key, stage)
    if complete is None:
        return None
    # ``response_text`` is MEDIUMTEXT and the upstream stage already has
    # bounded model-token limits.  Do not apply a second character cap here:
    # that silently amputates otherwise valid JSON envelopes, destroys audit
    # evidence and makes a later replay differ from the actual model output.
    stored = complete
    stage_row.response_text = stored
    if chat_url:
        stage_row.chat_url = str(chat_url)
    stage_meta = dict(stage_row.output_json or {})
    stage_meta["durable_response_capture"] = {
        "sha256": hashlib.sha256(stored.encode("utf-8")).hexdigest(),
        "captured_at": _stage_now().isoformat(),
        "chat_url": stage_row.chat_url,
        "validated_envelope": True,
        "replaced_prior_complete_capture": bool(
            replace_with_incoming_complete and incoming_complete is not None
        ),
    }
    stage_row.output_json = stage_meta
    db.commit()
    return stored


def _product_knowledge_result(project: HermesContentFactoryProject) -> dict[str, Any] | None:
    state = dict(project.state_json or {})
    knowledge = dict(state.get("product_knowledge") or {})
    envelope = dict(knowledge.get("facts_envelope") or {})
    result = dict(envelope.get("result") or {})
    if not result:
        return None
    return {
        field: value
        for field, value in result.items()
        if field in {
            "product_passport", "approved_claims", "prohibited_claims", "visual_invariants",
            "application_rules", "source_map", "product_truth_handoff",
        }
    }


def _project_uses_product(project: HermesContentFactoryProject) -> bool:
    """Return the authoritative product-mode flag for every workflow stage."""
    config = dict(project.config_json or {})
    if "product_required" in config:
        return bool(config.get("product_required"))
    # Compatibility for projects created before product_required became an
    # explicit project contract. Content mode names are descriptive and must
    # never decide whether commerce rules run.
    return bool(
        getattr(project, "product_id", None)
        or str(getattr(project, "product_name", None) or "").strip()
    )


def _is_product_facts_project(project: HermesContentFactoryProject) -> bool:
    return dict(project.config_json or {}).get("purpose") == "product_facts"


def _is_promotion_asset(asset: HermesContentFactoryAsset) -> bool:
    name = str(asset.original_name or "").lower()
    return any(token in name for token in ("promotion", "promo", "discount", "coupon", "offer", "促销", "优惠", "折扣"))


def _asset_role(asset: HermesContentFactoryAsset) -> str:
    meta = dict(asset.meta_json or {})
    role = str(meta.get("asset_role") or "").strip().lower()
    name = str(asset.original_name or Path(str(asset.file_path or "")).name or "").lower()
    mime = str(asset.mime_type or "").lower()
    # Explicit product-library/user classification is authoritative. Generic
    # camera filenames (for example ChatGPT_Image_....png) contain no product
    # keyword and were previously downgraded to fact_source here, silently
    # removing the real package image from visual generation.
    if asset.kind == "source" and role in {
        "product_visual", "fact_source", "character_reference",
    }:
        return role
    if asset.kind != "source":
        if mime.startswith("video/"):
            return "reference_video"
        if str(asset.stage or "").upper() == "FINAL_ASSETS":
            return "final_reference"
        if str(asset.stage or "").upper() == "VISUAL_PREVIEW":
            return "visual_preview"
        if role and role not in {"product_visual", "fact_source"}:
            return role
        if mime.startswith("image/"):
            return "generated_visual"
    fact_tokens = (
        "supplement", "facts", "fact", "ingredient", "ingredients", "nutrition", "panel",
        "direction", "warning", "claim", "claims", "guardrail", "handoff", "readme",
        "brand", "promotion", "promo", "control", "sheet", "pri", "成分", "营养",
        "配料", "标签", "说明", "警告", "知识库", "合规", "促销", "优惠",
    )
    product_tokens = (
        "白底", "透明", "主图", "瓶", "罐", "包装", "产品", "product", "bottle",
        "jar", "pack", "package", "main", "hero", "transparent",
    )
    if mime == "application/pdf" or name.endswith(".pdf"):
        return "fact_source"
    if any(token in name for token in fact_tokens):
        return "fact_source"
    if role and role != "product_visual":
        return role
    if mime.startswith("image/") and any(token in name for token in product_tokens):
        return "product_visual"
    if mime.startswith("image/"):
        return "fact_source"
    if mime.startswith("video/"):
        return "reference_video"
    return "fact_source"


def _set_asset_role(asset: HermesContentFactoryAsset) -> str:
    role = _asset_role(asset)
    meta = dict(asset.meta_json or {})
    if meta.get("asset_role") != role:
        meta["asset_role"] = role
        asset.meta_json = meta
    return role


ANCHOR_ROLES = {"character_anchor", "scene_anchor", "action_anchor", "product_anchor"}


def _semantic_roles(asset: HermesContentFactoryAsset) -> list[str]:
    meta = dict(asset.meta_json or {})
    roles = [str(value).strip().lower() for value in list(meta.get("semantic_roles") or [])]
    roles = [value for value in roles if value in ANCHOR_ROLES]
    if asset.kind == "source" and _asset_role(asset) == "product_visual":
        roles.append("product_anchor")
    return list(dict.fromkeys(roles))


def _classify_anchor_roles(description: str, *, index: int, count: int) -> list[str]:
    text = str(description or "").lower()
    roles: list[str] = []
    if any(term in text for term in (
        "person", "people", "character", "couple", "woman", "man", "actor", "face",
        "人物", "角色", "男女", "女性", "男性", "情侣",
    )):
        roles.append("character_anchor")
    if any(term in text for term in (
        "wide", "room", "bedroom", "kitchen", "setting", "environment", "layout", "nightstand",
        "全景", "场景", "房间", "卧室", "环境", "床头",
    )):
        roles.append("scene_anchor")
    if any(term in text for term in (
        "action", "reaction", "gesture", "hold", "holding", "pick", "open", "reach", "turn",
        "slap", "shout", "scroll", "move", "shift", "show", "动作", "反应", "手势", "拿起",
        "展示", "打开", "转身", "争吵", "拍打",
    )):
        roles.append("action_anchor")
    # Generated boards are character/scene/action authorities only. The
    # original uploaded package is attached later as the sole product anchor.
    if not roles:
        roles.append("action_anchor")
    if index == 1:
        roles.extend(("character_anchor", "scene_anchor"))
    elif index <= max(2, count // 2):
        roles.extend(("character_anchor", "action_anchor"))
    else:
        roles.extend(("character_anchor", "action_anchor"))
    if index == count:
        roles.append("scene_anchor")
    return list(dict.fromkeys(
        role for role in roles
        if role in {"character_anchor", "scene_anchor", "action_anchor"}
    ))


def _coerce_segment_number(value: Any, fallback: int) -> int:
    """Accept explicit segment identifiers and ignore human-readable time ranges."""
    if isinstance(value, bool):
        return max(1, int(fallback))
    if isinstance(value, (int, float)):
        return max(1, int(value))
    text = str(value or "").strip()
    if not text:
        return max(1, int(fallback))
    if re.fullmatch(r"\d+(?:\.0+)?", text):
        return max(1, int(float(text)))
    match = re.search(r"(?:segment|seg|片段|镜头)\s*#?\s*(\d+)", text, flags=re.IGNORECASE)
    if match:
        return max(1, int(match.group(1)))
    return max(1, int(fallback))


def _visual_plan_needs_product_reference(plan: list[Any]) -> bool:
    """Derive real product-authority uploads from current panel text.

    Attaching the user's approved product image is independent from permitting
    AI to generate a standalone packshot. Scripted product-only actions such as
    a cleaning tablet appearing or dissolving still need the uploaded product
    authority even when no person is interacting with it.
    """
    for item in plan:
        if not isinstance(item, dict):
            continue
        description = str(item.get("description") or "")
        semantic = _visual_reference_semantic_text(description)
        # A signed plan that names concrete source assets is stronger than a
        # nearby presentation constraint such as "no pasted-card look" or
        # "no text added by the scene generator".  Those constraints describe
        # how the real package should be rendered; treating their word "no"
        # as product exclusion silently removed the authoritative upload and
        # made the image model invent a replacement jar.  Product-free rows
        # are normalized upstream without source_asset_refs.
        if (
            bool(item.get("requires_product_reference"))
            and bool(item.get("source_asset_refs"))
        ):
            return True
        if _visual_reference_excludes_product(semantic):
            continue
        if (
            bool(item.get("requires_product_reference"))
            or bool(item.get("source_asset_refs"))
            or visual_reference_mentions_product(semantic)
        ):
            return True
    return False


def _ensure_reference_plan(result: dict[str, Any], *, product_allowed: bool = True) -> dict[str, Any]:
    normalized = dict(result or {})
    ticket = dict(normalized.get("visual_job_ticket") or {})
    script = dict(normalized.get("complete_video_script") or {})
    script_visual_by_segment: dict[int, str] = {}
    for position, raw_segment in enumerate(list(script.get("segments") or []), 1):
        if not isinstance(raw_segment, dict):
            continue
        segment_number = _coerce_segment_number(
            raw_segment.get("segment_index") or raw_segment.get("index") or raw_segment.get("segment"),
            position,
        )
        description = " ".join(
            str(raw_segment.get(key) or "").strip()
            for key in ("visual_action", "visual", "visuals", "action", "script")
            if str(raw_segment.get(key) or "").strip()
        ).strip()
        if description:
            script_visual_by_segment[segment_number] = description
    existing = ticket.get("reference_plan") or ticket.get("reference_images") or []
    # This is the complete-video reference plan, not a per-segment upload
    # allowance. Long videos legitimately need more than seven ordered panels;
    # the visual renderer partitions them into bounded boards later.
    count = max(1, min(64, int(_reference_count_from_ticket(ticket) or len(existing) or 6)))
    existing_by_index = {
        int(item.get("index") or item.get("panel_index") or position): dict(item)
        for position, item in enumerate(existing, 1)
        if isinstance(item, dict)
    }
    detailed_by_index: dict[int, dict[str, Any]] = {}
    for position, item in enumerate(list(ticket.get("reference_panels") or []), 1):
        if not isinstance(item, dict):
            continue
        raw_id = str(item.get("panel_id") or item.get("id") or "")
        match = re.search(r"(\d+)", raw_id)
        detail_index = int(match.group(1)) if match else position
        detailed_by_index[detail_index] = dict(item)
    structured_by_index: dict[int, dict[str, Any]] = {}
    for block_position, block in enumerate(list(ticket.get("segment_structure") or []), 1):
        if not isinstance(block, dict):
            continue
        segment_number = _coerce_segment_number(block.get("segment"), block_position)
        nested_by_index = {
            int(item.get("index") or 0): dict(item)
            for item in list(block.get("reference_plan") or [])
            if isinstance(item, dict) and int(item.get("index") or 0) > 0
        }
        for raw_index in list(block.get("reference_indices") or nested_by_index.keys()):
            try:
                reference_index = int(raw_index)
            except (TypeError, ValueError):
                continue
            if reference_index <= 0:
                continue
            nested = nested_by_index.get(reference_index, {})
            current = structured_by_index.setdefault(reference_index, {"segment": segment_number})
            if nested.get("description"):
                current["description"] = nested.get("description")
            if nested.get("roles") or nested.get("role"):
                roles = nested.get("roles") or [nested.get("role")]
                current["roles"] = roles
    shots: list[dict[str, Any]] = []
    for block_index, block in enumerate(list(normalized.get("shot_plan") or []), 1):
        if not isinstance(block, dict):
            continue
        nested = list(block.get("shots") or [])
        if nested:
            shots.extend({
                "segment": _coerce_segment_number(block.get("segment"), block_index),
                "description": str(shot),
            } for shot in nested)
            continue
        # API text models commonly return one structured shot per row rather
        # than the legacy {segment, shots:[...]} shape. Preserve that useful
        # visual information instead of replacing every panel with
        # "Reference panel N".
        detailed_visual = " | ".join(
            str(block.get(key) or "").strip()
            for key in (
                "visual_state", "terminal_state", "final_state", "visual_action",
                "visual_story", "visual", "visuals", "action", "shot",
                "description", "composition",
            )
            if str(block.get(key) or "").strip()
        )
        shots.append({
            "segment": _coerce_segment_number(block.get("segment"), block_index),
            # ``purpose`` is a narrative label (for example LOSS HOOK), not a
            # renderable still.  Prefer concrete visual aliases, especially
            # ``visual_story`` returned by text APIs, and use purpose/camera
            # only when the provider supplied no real visual description.
            "description": detailed_visual or " | ".join(
                str(block.get(key) or "").strip()
                for key in ("purpose", "camera", "dialogue", "timecode")
                if str(block.get(key) or "").strip()
            ),
            # A provider's ``visual_state`` is the concrete, renderable
            # single-frame authority for this segment. Keep it separate from
            # narrative labels so an abstract reference-plan description
            # cannot overwrite it later.
            "visual_state": str(
                block.get("visual_state")
                or block.get("terminal_state")
                or block.get("final_state")
                or ""
            ).strip(),
            "reference_panel": block.get("reference_panel"),
            "reference_panels": list(block.get("reference_panels") or []),
        })
    plan: list[dict[str, Any]] = []
    for index in range(1, count + 1):
        existing_item = existing_by_index.get(index, {})
        structured_item = structured_by_index.get(index, {})
        detailed_item = detailed_by_index.get(index, {})
        shot_index = min(len(shots) - 1, round((index - 1) * (len(shots) - 1) / max(1, count - 1))) if shots else 0
        shot = shots[shot_index] if shots else {"segment": 1, "description": f"Reference panel {index}"}
        segment_number = _coerce_segment_number(
            structured_item.get("segment") or existing_item.get("segment"),
            int(shot["segment"]),
        )
        description = str(
            structured_item.get("description")
            or existing_item.get("description")
            or existing_item.get("purpose")
            or shot["description"]
        )
        if not description.strip() or re.fullmatch(r"reference\s+panel\s+\d+", description.strip(), flags=re.IGNORECASE):
            description = ". ".join(
                str(detailed_item.get(key) or "").strip()
                for key in (
                    "name", "purpose", "composition", "camera", "performance",
                    "product_visibility", "ending_action", "final_frame",
                )
                if str(detailed_item.get(key) or "").strip()
            ) or description
        shot_description = str(shot.get("description") or "").strip()
        shot_visual_state = str(shot.get("visual_state") or "").strip()
        script_visual_description = str(script_visual_by_segment.get(segment_number) or "").strip()
        description_semantic = _visual_reference_semantic_text(description)
        # Concrete per-segment state outranks purpose-only phrases such as
        # "reveal the lost ritual" or "knife-twist". Those phrases are useful
        # story functions but cannot specify a usable reference image.
        if shot_visual_state:
            description = shot_visual_state
            description_semantic = _visual_reference_semantic_text(description)
        # The canonical complete script is the authority for a product beat.
        # Some creative providers correctly write the Segment 4 product action
        # but leave the matching reference-plan row as a generic, product-free
        # placeholder. In that case the generated board would never receive the
        # user's authoritative product image. Restore the scripted interaction.
        if (
            script_visual_description
            and visual_reference_requires_product(script_visual_description)
            and not visual_reference_requires_product(description_semantic)
        ):
            description = script_visual_description
            description_semantic = _visual_reference_semantic_text(description)
        # The detailed shot plan owns what happens in this chronological beat.
        # A provider may flatten reference_plan to vague labels such as "Hero
        # ending", then an earlier normalizer appends a product-free suffix.
        # Restore the aligned shot whenever it clearly requires the user's
        # product and the semantic reference description did not explicitly
        # forbid product presence.
        if (
            shot_description
            and visual_reference_mentions_product(shot_description)
            and not visual_reference_requires_product(description_semantic)
        ):
            description = shot_description
        supplied_roles = (
            structured_item.get("roles")
            or existing_item.get("roles")
            or existing_item.get("semantic_roles")
            or structured_item.get("role")
            or existing_item.get("role")
            or []
        )
        if isinstance(supplied_roles, str):
            supplied_roles = [supplied_roles]
        roles = [
            str(value).strip().lower()
            for value in supplied_roles
            if str(value).strip().lower() in {"character_anchor", "scene_anchor", "action_anchor"}
        ]
        if not roles:
            roles = _classify_anchor_roles(description, index=index, count=count)
        static_state = visual_reference_static_state(description, index=index)
        plan.append({
            "index": index,
            # Segment structure is the authoritative per-video binding. The
            # top-level plan is often flattened by ChatGPT and may mark every
            # panel as segment 1.
            "segment": segment_number,
            "description": visual_reference_description(static_state, index=index),
            "single_frame_terminal_state": static_state,
            "roles": roles,
            "requires_product_reference": product_allowed and visual_reference_requires_product(description),
        })
    ticket["final_reference_count"] = count
    ticket["reference_plan"] = plan
    if product_allowed and any(bool(item.get("requires_product_reference")) for item in plan):
        product_rule = (
            "Product may appear only inside a scripted interaction keyframe and must copy the user's uploaded product "
            "reference exactly. Never generate a standalone product-only or white-background packshot panel."
        )
    else:
        product_rule = (
            "This whole board is product-free. Do not show or invent any product, package, bottle, label, logo, "
            "branding, packshot, sales card, or product placeholder in any panel."
        )
    ticket["board_rule"] = (
        f"Generate exactly one board containing {count} ordered panels. Use clear straight gutters; "
        f"panel order must match reference_plan and must not include nested frames. {product_rule}"
    )
    normalized["visual_job_ticket"] = ticket
    return normalized


def _ensure_reference_plan_segment_coverage(
    result: dict[str, Any],
    *,
    product_allowed: bool = True,
) -> dict[str, Any]:
    """Ensure every complete-video segment owns at least one visual anchor.

    Provider models sometimes return a seven-panel plan even for a nine-segment
    story because they confuse the downstream per-request image limit with the
    global storyboard size. Missing segment anchors make later clips reuse the
    wrong people/actions. Preserve all useful supplied panels and append only the
    missing chronological beats; board generation will split the global plan.
    """
    normalized = dict(result or {})
    script = dict(normalized.get("complete_video_script") or {})
    segments = [
        dict(item)
        for item in list(script.get("segments") or [])
        if isinstance(item, dict)
    ]
    if not segments:
        return normalized

    ticket = dict(normalized.get("visual_job_ticket") or {})
    plan = [
        dict(item)
        for item in list(ticket.get("reference_plan") or [])
        if isinstance(item, dict)
    ]
    covered = {
        _coerce_segment_number(item.get("segment"), 1)
        for item in plan
    }
    next_index = max(
        [int(item.get("index") or position) for position, item in enumerate(plan, 1)]
        or [0]
    ) + 1
    for position, segment in enumerate(segments, 1):
        segment_index = _coerce_segment_number(
            segment.get("segment_index") or segment.get("index"),
            position,
        )
        if segment_index in covered:
            continue
        story_function = str(
            segment.get("story_function")
            or segment.get("segment_goal")
            or segment.get("purpose")
            or ""
        ).strip()
        visual_action = str(
            segment.get("visual_action")
            or segment.get("action")
            or segment.get("visual")
            or story_function
        ).strip()
        description = visual_action
        if story_function and story_function.lower() not in visual_action.lower():
            description = f"{story_function}: {visual_action}"
        description = description or f"Segment {segment_index} continuity action"
        plan.append({
            "index": next_index,
            "segment": segment_index,
            "description": visual_reference_description(description, index=next_index),
            "roles": ["character_anchor", "scene_anchor", "action_anchor"],
            "requires_product_reference": (
                product_allowed and visual_reference_requires_product(description)
            ),
        })
        covered.add(segment_index)
        next_index += 1

    # The reference contract for short-form segmented video is one final
    # reference image per provider segment.  A text model may split a segment
    # into separate character/scene/action "anchors" (six panels for a four
    # segment video), while review correctly evaluates four narrative beats.
    # Passing both counts downstream caused an API visual/review regeneration
    # loop and could reveal the product before the final beat. Merge the useful
    # anchor details into the single chronological panel owned by each segment.
    # The one-reference-per-segment binding is specific to short segmented
    # ads.  Longer stories can legitimately need multiple anchors per segment
    # and are rendered as bounded multi-board plans downstream.
    if len(segments) <= 6:
        grouped: dict[int, list[dict[str, Any]]] = {}
        for item in plan:
            segment_index = _coerce_segment_number(item.get("segment"), 1)
            grouped.setdefault(segment_index, []).append(item)
        canonical_plan: list[dict[str, Any]] = []
        for position, segment in enumerate(segments, 1):
            segment_index = _coerce_segment_number(
                segment.get("segment_index") or segment.get("index"),
                position,
            )
            rows = grouped.get(segment_index) or []
            if not rows:
                continue
            descriptions = list(dict.fromkeys(
                str(row.get("description") or "").strip()
                for row in rows
                if str(row.get("description") or "").strip()
            ))
            roles = list(dict.fromkeys(
                str(role).strip().lower()
                for row in rows
                for role in list(row.get("roles") or [])
                if str(role).strip()
            ))
            # The full segment script is the sole chronological authority. A
            # provider may return an otherwise useful reference row under the
            # wrong segment index, reusing a reset action for a knife-twist
            # beat. Merging that row verbatim leaks the product into an early
            # segment and makes two stills depict the same event.
            visual_action = str(
                segment.get("visual_action")
                or segment.get("action")
                or segment.get("visual")
                or ""
            ).strip()
            story_function = str(
                segment.get("story_function")
                or segment.get("segment_goal")
                or segment.get("purpose")
                or ""
            ).strip()
            segment_mentions_product = visual_reference_mentions_product(
                visual_action,
            )
            row_description = ""
            if len(rows) == 1:
                row_description = str(
                    rows[0].get("single_frame_terminal_state")
                    or rows[0].get("description")
                    or ""
                ).strip()
            row_key = re.sub(
                r"[^a-z0-9]+", " ", row_description.lower(),
            ).strip()
            story_key = re.sub(
                r"[^a-z0-9]+", " ", story_function.lower(),
            ).strip()
            ignored_overlap_words = {
                "about", "after", "again", "against", "along", "before",
                "beside", "close", "continuity", "concrete", "frame",
                "from", "into", "moment", "reference", "scene", "segment",
                "state", "story", "their", "there", "these", "those",
                "through", "under", "while", "with",
            }

            def semantic_tokens(value: str) -> set[str]:
                return {
                    token
                    for token in re.findall(r"[a-z0-9']+", value.lower())
                    if len(token) >= 4 and token not in ignored_overlap_words
                }

            row_overlap = (
                semantic_tokens(row_description)
                & semantic_tokens(visual_action)
            )
            row_mentions_product = visual_reference_mentions_product(
                row_description,
            )
            row_is_aligned_static_state = bool(
                row_description
                and row_key != story_key
                and not re.fullmatch(
                    r"(?:concrete\s+)?reference(?:\s+(?:panel|state))?\s+\d*",
                    row_key,
                )
                and len(row_overlap) >= 2
                and row_mentions_product == segment_mentions_product
            )
            if row_is_aligned_static_state:
                # One concrete, semantically aligned provider reference is a
                # better still-image authority than the segment's full motion
                # timeline. Preserve it after verifying product parity and
                # overlap, so a misplaced or product-leaking row still falls
                # back to the canonical script.
                description = row_description
            elif visual_action:
                description = visual_action
                if story_function and story_function.lower() not in visual_action.lower():
                    description = f"{story_function}: {visual_action}"
            else:
                description = " Continuity anchors: ".join(descriptions[:3])
            static_state = visual_reference_static_state(
                description,
                index=position,
            )
            canonical_plan.append({
                "segment": segment_index,
                "description": visual_reference_description(static_state, index=position),
                "single_frame_terminal_state": static_state,
                "roles": roles or ["character_anchor", "scene_anchor", "action_anchor"],
                "requires_product_reference": (
                    product_allowed
                    and (
                        visual_reference_requires_product(description)
                        or any(bool(row.get("requires_product_reference")) for row in rows)
                    )
                ),
            })
        plan = canonical_plan
    else:
        plan = sorted(
            plan,
            key=lambda item: (
                _coerce_segment_number(item.get("segment"), 1),
                int(item.get("index") or 0),
            ),
        )
    # Global indices are authoritative across every generated board.
    for index, item in enumerate(plan, 1):
        item["index"] = index
    count = len(plan)
    board_count = max(1, math.ceil(count / 7))
    ticket["reference_image_count"] = count
    ticket["final_reference_count"] = count
    ticket["reference_plan"] = plan
    ticket["board_count"] = board_count
    ticket["board_rule"] = (
        f"Generate {board_count} ordered storyboard board(s) containing {count} "
        "global chronological panels in total, with at most 7 panels per board. "
        "Every complete-video segment must remain represented; use clear straight "
        "gutters and never add nested frames."
    )
    normalized["visual_job_ticket"] = ticket
    return normalized


def _reference_contract_for_media_execution(
    result: dict[str, Any],
    *,
    product_allowed: bool = True,
) -> dict[str, Any]:
    """Return the media reference contract without rewriting signed plans.

    Legacy creative payloads still need the compatibility normalizers above.
    A ``directed_production_plan`` payload is different: its ordered rows and
    source bindings were already validated and signed by the Production Plan
    compiler. Passing that contract through the legacy one-reference-per-
    segment normalizer discards those bindings and can collapse the reviewer
    contract to a stale row count.

    Signed contracts are therefore validated here but never inferred,
    regrouped, padded, or rewritten.
    """
    normalized = dict(result or {})
    ticket = dict(normalized.get("visual_job_ticket") or {})
    if str(ticket.get("source") or "").strip().lower() != "directed_production_plan":
        return _ensure_reference_plan_segment_coverage(
            _ensure_reference_plan(
                normalized,
                product_allowed=product_allowed,
            ),
            product_allowed=product_allowed,
        )

    plan = [
        dict(item)
        for item in list(ticket.get("reference_plan") or [])
        if isinstance(item, dict)
    ]
    if not plan:
        raise ValueError(
            "PRODUCTION_PLAN_REFERENCE_CONTRACT_EMPTY: signed media design "
            "has no reference rows"
        )
    expected_count = int(
        ticket.get("reference_image_count")
        or ticket.get("final_reference_count")
        or len(plan)
    )
    if expected_count != len(plan):
        raise ValueError(
            "PRODUCTION_PLAN_REFERENCE_COUNT_MISMATCH: signed media design "
            f"declares {expected_count} references but contains {len(plan)} rows"
        )
    indices = [
        int(item.get("index") or position)
        for position, item in enumerate(plan, 1)
    ]
    if indices != list(range(1, len(plan) + 1)):
        raise ValueError(
            "PRODUCTION_PLAN_REFERENCE_ORDER_INVALID: signed reference "
            "indices must be unique, contiguous, and chronological"
        )
    for position, item in enumerate(plan, 1):
        mode = str(item.get("generation_mode") or "").strip().lower()
        if mode != "generate":
            raise ValueError(
                "PRODUCTION_PLAN_REFERENCE_MODE_INVALID: reference "
                f"{position} must be generated before media execution; "
                f"received generation_mode={mode!r}"
            )
        source_refs = [
            str(value).strip()
            for value in list(item.get("source_asset_refs") or [])
            if str(value).strip()
        ]
        if not product_allowed and bool(item.get("requires_product_reference")):
            raise ValueError(
                "PRODUCTION_PLAN_PRODUCT_REFERENCE_FORBIDDEN: product-free "
                f"project contains product reference {position}"
            )

    ticket["reference_image_count"] = len(plan)
    ticket["final_reference_count"] = len(plan)
    ticket["reference_plan"] = plan
    normalized["visual_job_ticket"] = ticket
    return normalized


def _asset_manifest(assets: list[HermesContentFactoryAsset]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for asset in assets:
        meta = dict(asset.meta_json or {})
        row = {
            "id": int(asset.id),
            "name": asset.original_name,
            "stage": asset.stage,
            "kind": asset.kind,
            "role": _asset_role(asset),
            "semantic_roles": _semantic_roles(asset),
            "mime_type": asset.mime_type,
            "reference_index": int(
                meta.get("reference_index")
                or meta.get("global_start_index")
                or 0
            ),
        }
        rows.append(row)
    return rows


def _sync_stage_assets_to_browser_inbox(
    db,
    project: HermesContentFactoryProject,
    assets: list[HermesContentFactoryAsset],
) -> list[HermesContentFactoryAsset]:
    if not assets:
        return assets
    from app.services.hermes_agent.content_factory import ensure_project_assets_in_browser_inbox

    return ensure_project_assets_in_browser_inbox(db, project=project, assets=assets)


def _render_video_prompt_reference_sheet(
    assets: list[HermesContentFactoryAsset],
    target: Path,
) -> Path:
    """Render ordered stage references into one non-cropped inspection board.

    Some ChatGPT accounts temporarily accept only three composer attachments.
    CREATIVE_REVIEW and VIDEO_PROMPTS still need to inspect every reference and
    preserve its authoritative index, so repeatedly selecting four or more
    individual files can never succeed. This internal board is only for
    ChatGPT inspection/planning; downstream stages continue using the original
    split references.
    """
    image_assets = [
        asset for asset in assets
        if str(asset.mime_type or "").startswith("image/")
        and Path(str(asset.file_path or "")).is_file()
    ]
    if not image_assets:
        raise ValueError("VIDEO_PROMPTS_REFERENCE_SHEET_EMPTY: no final reference images are available")
    cell_w, image_h, label_h, gap = 360, 640, 52, 12
    columns = min(3, len(image_assets))
    rows = int(math.ceil(len(image_assets) / columns))
    width = columns * cell_w + (columns + 1) * gap
    height = rows * (image_h + label_h) + (rows + 1) * gap
    canvas = Image.new("RGB", (width, height), (242, 244, 247))
    draw = ImageDraw.Draw(canvas)
    font = ImageFont.load_default()
    for position, asset in enumerate(image_assets, 1):
        row = (position - 1) // columns
        column = (position - 1) % columns
        left = gap + column * cell_w
        top = gap + row * (image_h + label_h)
        with Image.open(str(asset.file_path)) as opened:
            image = opened.convert("RGB")
            image.thumbnail((cell_w, image_h), Image.Resampling.LANCZOS)
            x = left + (cell_w - image.width) // 2
            y = top + (image_h - image.height) // 2
            canvas.paste(image, (x, y))
        meta = dict(asset.meta_json or {})
        reference_index = int(meta.get("reference_index") or position)
        roles = ", ".join(_semantic_roles(asset)[:4]) or "visual anchor"
        label = f"REFERENCE {reference_index} | {roles}"
        draw.rectangle(
            (left, top + image_h, left + cell_w, top + image_h + label_h),
            fill=(20, 27, 39),
        )
        draw.text((left + 10, top + image_h + 17), label[:58], fill="white", font=font)
    target.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(target, "JPEG", quality=90, optimize=True)
    try:
        target.chmod(0o664)
    except OSError:
        pass
    return target


def _browser_reference_sheet_spec(
    stage: str,
    *,
    variant_index: int,
) -> tuple[str, str] | None:
    """Describe stages that must collapse 4+ browser images into one upload."""
    stage_name = str(stage or "").upper()
    if stage_name == "CREATIVE_REVIEW":
        return (
            f"v{int(variant_index):02d}-creative-review-reference-sheet.jpg",
            "The single uploaded contact sheet contains the ordered VISUAL_PREVIEW panels labeled "
            "visual_anchor plus any authoritative product_anchor panels needed only for package comparison. "
            "Return exactly one reference_checks row for each visual_anchor index and no row for a "
            "product_anchor; use product_anchor only to judge product accuracy. The server preserves the "
            "original split images for later stages.",
        )
    if stage_name == "VIDEO_PROMPTS":
        return (
            f"v{int(variant_index):02d}-video-prompt-reference-sheet.jpg",
            "The single uploaded contact sheet contains every FINAL_ASSETS reference in authoritative "
            "REFERENCE index order. Inspect all panels and return reference_indices against browser_assets; "
            "the server uploads the original split files to the video provider.",
        )
    return None


def _wait_for_browser_inbox_sync(
    db,
    *,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
    assets: list[HermesContentFactoryAsset],
) -> None:
    """Give the user's bridge agent time to pull server inbox files locally.

    ChatGPT uploads happen from the user's Windows Chrome profile. A newly
    created project can otherwise start before the agent has copied product
    facts/images to that machine, which shows up as invisible attachments or a
    disabled send button. New bridge agents report a per-slot synced file
    manifest; old agents are still supported by falling back to a fresh
    heartbeat plus a longer settle window.
    """
    if not assets:
        return
    bridge_id = str(stage_input.get("browser_bridge_id") or "").strip()
    if not bridge_id:
        return
    bridge_paths: list[Path] = []
    required_files: dict[str, int] = {}
    for asset in assets:
        meta = dict(asset.meta_json or {})
        bridge_path = str(meta.get("bridge_path") or "").strip()
        if bridge_path:
            path = Path(bridge_path)
            if path.is_file():
                bridge_paths.append(path)
                try:
                    rel_workspace = path.resolve().relative_to(
                        (BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}").resolve()
                    ).as_posix()
                    required_files[rel_workspace] = int(path.stat().st_size)
                except Exception:
                    required_files[path.name] = int(path.stat().st_size)
    if not bridge_paths:
        return
    latest_mtime = max(path.stat().st_mtime for path in bridge_paths)
    deadline = time.monotonic() + int(os.getenv("HERMES_BROWSER_INBOX_SYNC_WAIT_SECONDS", "120"))
    last_detail = ""
    used_manifest = False
    while time.monotonic() < deadline:
        db.expire_all()
        bridge = (
            db.query(HermesBrowserBridge)
            .filter(
                HermesBrowserBridge.bridge_id == bridge_id,
                HermesBrowserBridge.workspace_id == int(project.workspace_id),
                HermesBrowserBridge.user_id == int(project.user_id or 0),
            )
            .one_or_none()
        )
        if bridge is None:
            return
        load = dict(bridge.load_json or {})
        agent_version = str(dict(bridge.meta_json or {}).get("agent_version") or "legacy").strip()
        manifest_capable = agent_version not in {"", "legacy"}
        agent_error = str(load.get("sync_error") or load.get("agent_error") or "").strip()
        if agent_error:
            last_detail = f"agent_error={agent_error}"
        synced_raw = load.get("synced_files") or []
        synced_files: dict[str, int] = {}
        if manifest_capable:
            used_manifest = True
        if isinstance(synced_raw, list) and synced_raw:
            for item in synced_raw:
                if isinstance(item, dict):
                    value = str(item.get("path") or item.get("relative_path") or "").replace("\\", "/").lstrip("/")
                    try:
                        size = int(item.get("size") or -1)
                    except (TypeError, ValueError):
                        size = -1
                else:
                    value = str(item or "").replace("\\", "/").lstrip("/")
                    size = -1
                if value:
                    synced_files[value] = size
                    if value.startswith(f"workspace_{project.workspace_id}/"):
                        synced_files[value.split("/", 1)[1]] = size
            if required_files and all(
                relative in synced_files and synced_files[relative] == expected_size
                for relative, expected_size in required_files.items()
            ):
                return
            last_detail = f"synced_files_missing required={[path.name for path in bridge_paths[:8]]}"
        if not used_manifest and bridge.last_seen_at is not None and bridge.last_seen_at.timestamp() >= latest_mtime:
            # One extra heartbeat interval lets legacy Windows agents finish
            # pulling files after receiving the manifest.
            time.sleep(float(os.getenv("HERMES_BROWSER_INBOX_SYNC_SETTLE_SECONDS", "12")))
            return
        time.sleep(3)
    raise ValueError(
        "BROWSER_INBOX_SYNC_INCOMPLETE: current user's browser bridge did not confirm local file sync; "
        f"bridge_id={bridge_id}, files={[path.name for path in bridge_paths[:8]]}, {last_detail}"
    )


def _reference_count_from_text(text: str | None) -> int | None:
    value = str(text or "")
    lowered = value.lower()
    markers = (
        ("3x2", 6), ("3 x 2", 6), ("2x3", 6), ("2 x 3", 6),
        ("6宫格", 6), ("六宫格", 6), ("six-panel", 6), ("6-panel", 6),
        ("2x2", 4), ("2 x 2", 4), ("4宫格", 4), ("四宫格", 4),
    )
    for marker, count in markers:
        if marker in lowered or marker in value:
            return count
    return None


def _reference_count_from_ticket(ticket: dict[str, Any] | None) -> int | None:
    if not isinstance(ticket, dict):
        return None
    for key in (
        "reference_image_count", "final_reference_count", "required_reference_images",
        "REFERENCE_IMAGE_COUNT", "FINAL_REFERENCE_COUNT", "REQUIRED_REFERENCE_IMAGES",
    ):
        try:
            count = int(ticket.get(key) or 0)
        except (TypeError, ValueError):
            continue
        if count > 0:
            return count
    refs = ticket.get("reference_images") or ticket.get("REFERENCE_IMAGE_PLAN") or ticket.get("asset_manifest") or []
    if isinstance(refs, list) and refs:
        return len(refs)
    return None


def _authoritative_reference_count(
    creative_result: dict[str, Any] | None,
    *,
    review_result: dict[str, Any] | None = None,
    fallback_texts: list[str] | None = None,
    default: int = 6,
) -> int:
    """Resolve board size without letting later prose rewrite the creative plan.

    The ordered creative reference_plan is the contract used for both visual
    generation and downstream reference bindings. Review/preview responses may
    validate that count, but their prose often mentions another grid example
    (for example "2x3") and must not silently increase it.
    """
    creative = dict(creative_result or {})
    ticket = creative.get("visual_job_ticket")
    ticket_count = _reference_count_from_ticket(ticket if isinstance(ticket, dict) else {})
    if ticket_count:
        return max(1, min(12, int(ticket_count)))

    review = dict(review_result or {})
    try:
        review_count = int(review.get("reference_image_count") or 0)
    except (TypeError, ValueError):
        review_count = 0
    if review_count > 0:
        return max(1, min(12, review_count))

    for text in list(fallback_texts or []):
        text_count = _reference_count_from_text(text)
        if text_count:
            return max(1, min(12, int(text_count)))
    return max(1, min(12, int(default or 6)))


def _sanitize_product_facts_envelope(envelope: dict[str, Any]) -> dict[str, Any]:
    cleaned = dict(envelope or {})
    result = dict(cleaned.get("result") or {})
    for key in (
        "promotion_usage", "promotions", "promotion", "promotion_rules", "offer",
        "offers", "discounts", "cta", "cta_options", "campaign",
    ):
        result.pop(key, None)
    cleaned["result"] = result

    def keep_issue(issue: Any) -> bool:
        text = json.dumps(issue, ensure_ascii=False).lower()
        return not any(token in text for token in ("promotion", "promo", "discount", "coupon", "offer", "$5", "35%", "促销", "优惠", "折扣"))

    cleaned["issues"] = [issue for issue in list(cleaned.get("issues") or []) if keep_issue(issue)]
    return cleaned


def _normalize_envelope_shape(envelope: dict[str, Any]) -> dict[str, Any]:
    cleaned = dict(envelope or {})
    if not isinstance(cleaned.get("result"), dict):
        cleaned["result"] = {}
    result = dict(cleaned["result"])
    # Text providers occasionally close ``result`` too early and continue
    # emitting otherwise valid required stage fields at the envelope root.
    # Their JSON is syntactically valid, so a parser cannot flag it, but
    # replaying or regenerating the same complete payload wastes an API turn.
    # Move only known result fields and never override a correctly nested one.
    known_result_fields = {
        field
        for fields in REQUIRED_FIELDS.values()
        for field in fields
    } | {
        "reference_plan", "shot_plan", "continuity_rules", "cta_options",
        "complete_video_script", "voice_bible", "visual_job_ticket",
        "concepts", "selected_concept",
    }
    for field in known_result_fields:
        if result.get(field) in (None, "", [], {}) and cleaned.get(field) not in (None, "", [], {}):
            result[field] = cleaned[field]
    cleaned["result"] = result
    evidence = cleaned.get("evidence")
    if evidence is None:
        cleaned["evidence"] = {}
    elif not isinstance(evidence, dict):
        cleaned["evidence"] = {"items": evidence}
    issues = cleaned.get("issues")
    if issues is None:
        cleaned["issues"] = []
    elif not isinstance(issues, list):
        cleaned["issues"] = [issues]
    return cleaned


def _normalize_edit_package_result(
    result: dict[str, Any],
    project: HermesContentFactoryProject | None = None,
) -> dict[str, Any]:
    normalized = dict(result or {})
    aliases = {
        "edit_guidance": ["editing_guidance", "editor_guidance", "edit_notes", "cut_notes", "editing_notes", "post_edit_notes"],
        "publish_title": ["publishing_title", "video_title", "post_title", "tiktok_title", "pr_title", "headline"],
        "publish_caption": ["caption", "post_caption", "tiktok_caption", "description"],
        "pr_title": ["press_release_title", "release_title", "pr_headline", "headline"],
        "chapter_titles": ["chapters", "video_chapters", "section_titles"],
        "tiktok_titles": ["tiktok_title", "titles", "post_titles", "captions"],
        "hashtags": ["tags", "hash_tags"],
        "cta": ["ctas", "call_to_action", "call_to_actions"],
        "edit_notes": ["editing_notes", "post_edit_notes", "cut_notes"],
        "test_plan": ["testing_plan", "ab_test_plan", "experiment_plan"],
        "compliance_notes": ["compliance", "qa_notes", "risk_notes"],
    }
    for canonical, candidates in aliases.items():
        if normalized.get(canonical) not in (None, "", []):
            continue
        for candidate in candidates:
            value = normalized.get(candidate)
            if value not in (None, "", []):
                normalized[canonical] = value
                break
    if normalized.get("edit_guidance") in (None, "", []):
        notes = normalized.get("edit_notes") or normalized.get("chapter_titles") or []
        if isinstance(notes, list):
            normalized["edit_guidance"] = "\n".join(str(item) for item in notes if str(item).strip())
        elif notes:
            normalized["edit_guidance"] = str(notes)
    if normalized.get("publish_title") in (None, "", []):
        titles = normalized.get("tiktok_titles") or normalized.get("pr_title") or []
        if isinstance(titles, list) and titles:
            normalized["publish_title"] = str(titles[0])
        elif titles:
            normalized["publish_title"] = str(titles)
    if normalized.get("hashtags") in (None, "", []):
        normalized["hashtags"] = (
            _editor_guidance_hashtag_list(
                project,
                _configured_video_language(project),
            )
            if project is not None
            else []
        )
    return normalized


def _compact_video_plan_for_edit_package(value: dict[str, Any] | None) -> dict[str, Any] | None:
    source = dict(value or {})
    videos = source.get("videos") or source.get("prompts") or []
    if not isinstance(videos, list):
        return None
    compact: list[dict[str, Any]] = []
    for index, video in enumerate(videos[:50], 1):
        if not isinstance(video, dict):
            continue
        segments: list[dict[str, Any]] = []
        for segment in list(video.get("segments") or [])[:6]:
            if not isinstance(segment, dict):
                continue
            segments.append({
                "segment_index": segment.get("segment_index"),
                "duration": segment.get("duration"),
                "prompt": str(segment.get("prompt") or "")[:800],
            })
        compact.append({
            "index": index,
            "version_name": video.get("version_name") or f"V{index}",
            "story_arc": str(video.get("story_arc") or "")[:800],
            "aspect_ratio": video.get("aspect_ratio"),
            "segments": segments,
        })
    return {"videos": compact} if compact else None


def _localized_promotion_cta(promotion: str, language: str) -> str:
    text = str(promotion or "").strip()
    if not text:
        return ""
    lowered = text.lower().replace("usd", "$").replace("us$", "$")
    has_five_dollars = any(token in lowered for token in ("$5", "5$", "5 美元", "5美元"))
    amount_match = re.search(r"(?:\$\s*(\d+(?:\.\d{1,2})?)|(\d+(?:\.\d{1,2})?)\s*(?:美元|美金|usd|\$))", lowered)
    dollar_amount = next((value for value in (amount_match.groups() if amount_match else ()) if value), "")
    limited_100 = bool(re.search(r"(?:限量|limited|first)\D{0,12}100|100\D{0,12}(?:单|orders|customers)", text, flags=re.IGNORECASE))
    if language == "zh-CN":
        if "new customer" in lowered or "first order" in lowered:
            return "新客立减 5 美元" if has_five_dollars else "新客专享优惠"
        return text
    if any(token in text for token in ("新人", "新客", "首单")):
        return "New customers get $5 off" if has_five_dollars else "New customer discount available"
    if dollar_amount and limited_100:
        return f"Launch price ${dollar_amount}; limited to 100 orders"
    if dollar_amount and any(token in text for token in ("仅需", "只需", "售价", "价格", "成本价")):
        return f"Only ${dollar_amount}"
    if limited_100:
        return "Limited to 100 orders"
    return text


def _text_has_action_cta(text: str) -> bool:
    value = str(text or "").lower()
    return any(marker in value for marker in (
        "tap to shop", "tap below", "shop now", "click to shop", "order now",
        "buy now", "add to cart", "yellow cart", "click the yellow cart",
        "点击购买", "立即购买", "下方购买", "点下方", "小黄车", "点击视频下方",
    ))


def _shopping_cart_cta(language: str) -> str:
    # Storefront actions are project-owned copy. A generic pipeline must not
    # invent a platform-specific button or cart label.
    return ""


def _non_promotional_video_cta(project: HermesContentFactoryProject, language: str) -> str:
    if not _project_uses_product(project):
        return ""
    product_name = str(project.product_name or "the approved product").strip()
    if language == "zh-CN":
        return f"试试 {product_name}。"
    return f"Try {product_name}."


def _strip_unconfirmed_action_cta(text: str) -> str:
    value = str(text or "")
    value = re.sub(
        r"(?:tap\s+to\s+shop|tap\s+below|shop\s+now|click\s+to\s+shop|order\s+now|buy\s+now|"
        r"add\s+to\s+cart|click\s+the\s+yellow\s+cart(?:\s+below)?(?:\s+to\s+buy)?)\.?",
        "",
        value,
        flags=re.IGNORECASE,
    )
    value = re.sub(
        r"(?:点击购买|立即购买|下方购买|点下方购买|点下方|点击视频下方(?:的)?小黄车(?:购买)?|小黄车购买)[。.!！]?",
        "",
        value,
    )
    return re.sub(r"\s+", " ", value).strip(" ,，。.!！;；|")


def _strip_legacy_action_cta(text: str) -> str:
    value = re.sub(r"\s+", " ", str(text or "")).strip()
    if not value:
        return ""
    value = re.sub(
        r"[\s,，。.!！;；]*(tap\s+to\s+shop|tap\s+below|shop\s+now|click\s+to\s+shop|order\s+now|buy\s+now|add\s+to\s+cart)\.?\s*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"[\s,，。.!！;；]*(点击购买|立即购买|下方购买|点下方购买|点下方|点击视频下方购买)\s*$",
        "",
        value,
    ).strip()
    return value.strip(" ,，。.!！;；")


def _promotion_line_for_speech(promotion: str, language: str) -> str:
    text = _strip_legacy_action_cta(str(promotion or "").strip())
    if not text:
        return ""
    if "小黄车" in text or "yellow cart" in text.lower():
        return text if re.search(r"[。.!！]$", text) else text + ("。" if language == "zh-CN" else ".")
    action = _shopping_cart_cta(language)
    if not action:
        return text if re.search(r"[。.!！]$", text) else text + ("。" if language == "zh-CN" else ".")
    if language == "zh-CN":
        return f"{text}，{action}"
    return f"{text}. {action}"


def _normalized_offer_phrase(text: str) -> str:
    value = re.sub(r"\s+", " ", str(text or "")).strip()
    if not value:
        return ""
    lowered = value.lower().replace("usd", "$").replace("us$", "$")
    amount_match = re.search(
        r"(?:\$\s*(\d+(?:\.\d{1,2})?)|(\d+(?:\.\d{1,2})?)\s*(?:美元|美金|usd|\$))",
        lowered,
        flags=re.IGNORECASE,
    )
    if not amount_match:
        return ""
    amount = next((item for item in amount_match.groups() if item), "")
    if not amount:
        return ""
    if re.search(r"[\u4e00-\u9fff]", value):
        if any(marker in value for marker in ("新客", "新人", "首单", "立减")):
            phrase = f"新客立减 {amount} 美元"
        elif any(marker in value for marker in ("新品", "推新", "品牌推广", "仅需", "只需", "成本价")):
            phrase = f"新品仅需 {amount} 美元"
        else:
            phrase = f"仅需 {amount} 美元"
        return value if _text_has_action_cta(value) else phrase
    if "new customer" in lowered or "first order" in lowered:
        phrase = f"New customers get ${amount} off" if "off" in lowered else f"New customer offer: ${amount}"
    elif "new drop" in lowered or "launch" in lowered:
        phrase = f"Launch price ${amount}"
    elif re.search(r"\b(?:shipped|delivered)\b|\b(?:including|includes)\s+shipping\b", lowered):
        # Shipping inclusion is part of the owner-confirmed commercial fact,
        # not decorative copy. Keep it when compacting an offer so downstream
        # metadata cannot turn "$14.99 shipped" into a different bare-price
        # proposition.
        phrase = f"${amount} shipped"
    elif "off" in lowered:
        phrase = f"${amount} off"
    else:
        phrase = f"Only ${amount}"
    return value if _text_has_action_cta(value) else phrase


def _promotion_candidate_from_text(value: Any) -> str:
    """Extract an owner-approved price/CTA from creative or video prompt text."""
    if isinstance(value, dict):
        preferred_keys = (
            "cta", "primary", "copy", "mandatory_end_copy", "final_cta",
            "promotion", "promo_used", "offer", "publish_caption",
        )
        for key in preferred_keys:
            candidate = _promotion_candidate_from_text(value.get(key))
            if candidate:
                return candidate
        for item in value.values():
            candidate = _promotion_candidate_from_text(item)
            if candidate:
                return candidate
        return ""
    if isinstance(value, list):
        # Never stringify dictionaries into promotion copy. That previously
        # turned fields such as duration=10 and characters=[...] into a fake
        # offer when the same object also contained an action CTA.
        joined_values = [str(item).strip() for item in value if isinstance(item, str) and str(item).strip()]
        joined = " | ".join(joined_values)
        candidate = _promotion_candidate_from_text(joined)
        if candidate:
            return candidate
        for item in value:
            candidate = _promotion_candidate_from_text(item)
            if candidate:
                return candidate
        return ""

    text = str(value or "").strip()
    if not text:
        return ""
    compact = re.sub(r"\s+", " ", text)
    money_pattern = r"(?:\$|usd|us\$|\bonly\b|\bfor\b|仅需|只需|售价|价格|新客|新人|首单|立减)[^。.!?\n|]{0,80}?(?:\$|usd|us\$)?\s*\d+(?:\.\d{1,2})?\s*(?:美元|美金|usd|\$)?"
    # A period is a sentence boundary only when it is not the decimal point in
    # an authorized price.  Splitting ``$14.99 shipped`` at the dot silently
    # downgraded the durable offer to ``Only $14`` in downstream guide
    # metadata even though the signed script still carried the correct price.
    segments = re.split(r"[\n|。!?；;]+|(?<!\d)\.(?!\d)", compact)
    best = ""
    for segment in segments:
        segment = segment.strip(" '\"，,")
        if not segment:
            continue
        if re.search(money_pattern, segment, flags=re.IGNORECASE):
            best = _normalized_offer_phrase(segment) or segment
            break
        # An action CTA plus an arbitrary number is not a monetary offer.
        # Require an actual currency/price marker before extracting it.
        if _text_has_action_cta(segment) and re.search(
            r"(?:\$|usd|us\$|\u7f8e\u5143|\u7f8e\u91d1)\s*\d+(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?\s*(?:\$|usd|\u7f8e\u5143|\u7f8e\u91d1)",
            segment,
            flags=re.IGNORECASE,
        ):
            best = _normalized_offer_phrase(segment) or segment
            break
    if not best:
        match = re.search(money_pattern, compact, flags=re.IGNORECASE)
        if match:
            source = match.group(0).strip(" '\"，,")
            best = _normalized_offer_phrase(source) or source
    return _compact_prompt_text(best, 180) if best else ""



def _confirmed_promotion_from_project(project: HermesContentFactoryProject) -> str:
    """Return an explicitly authorized offer, including one confirmed in the brief."""
    config = dict(project.config_json or {})
    # `confirmed_promotions` may contain internal guardrails such as "do not
    # claim free shipping". Those are authorization facts, not consumer copy.
    # When an explicit CTA exists it is the sole speech authority; concatenating
    # the policy paragraph to it made video providers read internal compliance
    # instructions aloud.
    explicit_cta = str(config.get("promotion_cta") or "").strip()
    if explicit_cta:
        return explicit_cta
    confirmed_promotion = str(config.get("confirmed_promotions") or "").strip()
    if confirmed_promotion:
        speech_candidate = _promotion_candidate_from_text(confirmed_promotion)
        if speech_candidate:
            return speech_candidate
    brief = str(project.product_brief or "").strip()
    if not brief:
        return ""
    # The project brief is entered by the operator as confirmed campaign
    # requirements. If it contains a price or offer, keep it through creative,
    # video prompt, and editor handoff instead of asking ChatGPT to re-approve
    # it as a separate compliance field.
    patterns = (
        r"(?:品牌推广新品[，,。 ]*)?(?:成本价出售[，,。 ]*)?(?:仅需|只需|售价(?:为)?|价格(?:为)?|only|for)\s*(?:usd|us\$|\$)?\s*\d+(?:\.\d{1,2})?\s*(?:美元|美金|usd|\$)?",
        r"(?:新人|新客|首单|new customer|first order)[^。；;\n]{0,40}?(?:立减|优惠|off)[^。；;\n]{0,20}?(?:usd|us\$|\$)?\s*\d+(?:\.\d{1,2})?\s*(?:美元|美金|usd|\$)?",
        r"(?:usd|us\$|\$)\s*\d+(?:\.\d{1,2})?",
        r"\d+(?:\.\d{1,2})?\s*(?:美元|美金|usd)",
    )
    for pattern in patterns:
        match = re.search(pattern, brief, flags=re.IGNORECASE)
        if match:
            return re.sub(r"\s+", " ", match.group(0)).strip(" ，,。;；")
    # Historical model output is not an authorization source. Promotions may
    # only come from explicit project fields or a price/offer in the operator's
    # current brief; otherwise one malformed generation contaminates all later
    # variants.
    return ""


def _marketing_authorization(project: HermesContentFactoryProject) -> dict[str, Any]:
    if not _project_uses_product(project):
        return {
            "confirmed_claims": None,
            "confirmed_selling_points": None,
            "confirmed_promotions": None,
            "promotion_cta": None,
            "allow_promotional_cta": False,
            "user_confirmed_marketing": False,
            "authorization_source": None,
            "rules": [
                "This project does not require a product.",
                "Do not invent a product, package, product claim, price, offer, sales CTA, or shopping action.",
            ],
        }
    config = dict(project.config_json or {})
    promotion = _confirmed_promotion_from_project(project)
    confirmed_promotions = str(config.get("confirmed_promotions") or promotion or "").strip()
    promotion_cta = promotion or str(config.get("promotion_cta") or "").strip()
    user_confirmed = bool(
        config.get("user_confirmed_marketing", False)
        or promotion
        or confirmed_promotions
        or promotion_cta
    )
    allow_promotional_cta = bool(promotion_cta) and (
        bool(config.get("allow_promotional_cta", False))
        or user_confirmed
        or bool(confirmed_promotions)
    )
    return {
        "confirmed_claims": config.get("confirmed_claims"),
        "confirmed_selling_points": config.get("confirmed_selling_points"),
        "confirmed_promotions": confirmed_promotions or None,
        "promotion_cta": promotion_cta or None,
        "allow_promotional_cta": allow_promotional_cta,
        "user_confirmed_marketing": user_confirmed,
        "authorization_source": "explicit_fields" if config.get("promotion_cta") or config.get("confirmed_promotions") else ("confirmed_project_requirement" if promotion else None),
        "rules": [
            "Project requirements are the highest-priority business constraints for creative, video prompts, and publishing handoff.",
            "The exact price or promotion in this authorization is user-confirmed and must not be removed, softened, or rejected as an unconfirmed promotion.",
            "Do not invent prices, discounts, countdowns, scarcity, or promotion terms beyond this authorization.",
        ],
    }


_CREATIVE_COPY_CONTRACT_STOPWORDS = {
    "about", "after", "again", "also", "another", "before", "below", "buy",
    "check", "click", "find", "from", "into", "only", "price", "product",
    "shop", "shopping", "that", "their", "them", "then", "there", "these",
    "they", "this", "those", "through", "under", "where", "which", "while",
    "with", "without", "your",
}


def _creative_cast_policy(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Return only project-owned cast rules; the engine invents no audience."""
    raw = dict(
        dict(getattr(project, "config_json", None) or {}).get(
            "creative_cast_policy"
        )
        or {}
    )
    policy: dict[str, Any] = {}
    for key in (
        "allow_minor_story_characters",
        "minimum_product_actor_age",
        "max_spoken_voices",
        "max_principal_characters",
    ):
        if key in raw and raw.get(key) is not None:
            policy[key] = raw.get(key)
    instructions = [
        re.sub(r"\s+", " ", str(value or "")).strip()[:500]
        for value in list(raw.get("instructions") or [])
        if str(value or "").strip()
    ][:20]
    if instructions:
        policy["instructions"] = instructions
    return policy


def _product_presentation_policy(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Compile package authority and user-configured interaction boundaries."""
    raw = dict(
        dict(getattr(project, "config_json", None) or {}).get(
            "product_presentation_policy"
        )
        or {}
    )
    authority_mode = str(
        raw.get("authority_mode") or "uploaded_source_only"
    ).strip()
    if authority_mode not in {"uploaded_source_only", "generated_allowed"}:
        authority_mode = "uploaded_source_only"
    categories = [
        str(value or "").strip()
        for value in list(
            raw.get("forbidden_interaction_categories") or []
        )
        if str(value or "").strip()
        in {
            "open_package",
            "expose_loose_contents",
            "consume_product",
            "minor_product_interaction",
        }
    ]
    instructions = [
        re.sub(r"\s+", " ", str(value or "")).strip()[:500]
        for value in list(raw.get("presentation_instructions") or [])
        if str(value or "").strip()
    ][:20]
    return {
        "authority_mode": authority_mode,
        "forbidden_interaction_categories": list(dict.fromkeys(categories)),
        "presentation_instructions": instructions,
    }


def _project_creative_duplicate_stopwords(
    project: HermesContentFactoryProject,
) -> set[str]:
    """Compile repeated brand/product/offer vocabulary from saved project data."""
    config = dict(getattr(project, "config_json", None) or {})
    sources = [
        str(config.get("brand_name") or ""),
        str(getattr(project, "product_name", "") or ""),
        str(config.get("confirmed_claims") or ""),
        str(config.get("confirmed_selling_points") or ""),
        str(config.get("confirmed_promotions") or ""),
        str(config.get("promotion_cta") or ""),
    ]
    return {
        token.lower()
        for source in sources
        for token in re.findall(r"[a-z][a-z'-]{3,}", source.lower())
    }


def _creative_copy_contract(
    project: HermesContentFactoryProject,
    marketing_authorization: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Compile project-owned copy rules into a provider-neutral contract.

    Product identity, offer, CTA, segment count, reveal point, and tieback
    behavior all come from the saved project. The generic state machine never
    embeds one brand, price, storefront label, or fixed four-beat campaign.
    Optional structured overrides live in ``config_json.creative_copy_contract``;
    otherwise the compiler derives conservative defaults from the saved brief.
    """
    config = dict(project.config_json or {})
    override = dict(config.get("creative_copy_contract") or {})
    requirements = _project_requirement_text(project)
    lowered = requirements.lower()
    segment_count = len(_segment_durations_for_project(project))

    def bounded_segment(value: Any, fallback: int) -> int:
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            parsed = fallback
        return max(1, min(segment_count, parsed))

    inferred_reveal = 1
    inferred_product_free_through = 0
    explicit_reveal_rule = False
    for line in re.split(r"[\r\n]+", requirements):
        segment_match = re.search(r"\bsegment\s*#?\s*(\d+)\b", line, flags=re.IGNORECASE)
        if not segment_match:
            continue
        segment_index = bounded_segment(segment_match.group(1), segment_count)
        line_lower = line.lower()
        if any(marker in line_lower for marker in (
            "product-free", "product free", "do not show", "do not name",
            "must not mention", "without the product",
        )):
            explicit_reveal_rule = True
            inferred_product_free_through = max(
                inferred_product_free_through,
                segment_index,
            )
        if any(marker in line_lower for marker in (
            "product and conversion", "product enters", "introduce the product",
            "may introduce", "product reveal",
        )):
            explicit_reveal_rule = True
            inferred_reveal = max(inferred_reveal, segment_index)
    inferred_reveal = max(
        inferred_reveal,
        min(segment_count, inferred_product_free_through + 1),
    )
    has_reveal_override = "product_reveal_segment" in override
    product_reveal_segment = bounded_segment(
        override.get("product_reveal_segment"),
        inferred_reveal if explicit_reveal_rule else 1,
    )
    product_free_through_segment = bounded_segment(
        override.get("product_free_through_segment"),
        max(1, product_reveal_segment - 1),
    )
    if product_reveal_segment <= 1:
        product_free_through_segment = 0
    else:
        product_free_through_segment = min(
            product_reveal_segment - 1,
            product_free_through_segment,
        )

    marketing = dict(
        marketing_authorization
        if marketing_authorization is not None
        else _marketing_authorization(project)
    )
    promotion_text = " ".join(
        str(marketing.get(key) or "").strip()
        for key in ("confirmed_promotions", "promotion_cta")
        if str(marketing.get(key) or "").strip()
    )
    price_tokens = list(dict.fromkeys(
        re.sub(r"\s+", "", match.group(0)).lower()
        for match in re.finditer(
            r"(?:\$|usd|us\$)\s*\d+(?:\.\d{1,2})?"
            r"|\d+(?:\.\d{1,2})?\s*(?:美元|美金|usd)",
            promotion_text,
            flags=re.IGNORECASE,
        )
    ))
    product_identity = str(project.product_name or "").strip()
    brand_identity = str(config.get("brand_name") or "").strip()
    identity_source = " ".join(
        value for value in (brand_identity, product_identity) if value
    )
    identity_terms = list(dict.fromkeys(
        token.lower()
        for token in re.findall(r"[a-z0-9][a-z0-9'-]{3,}", identity_source.lower())
        if token.lower() not in _CREATIVE_COPY_CONTRACT_STOPWORDS
    ))
    cta_source = str(marketing.get("promotion_cta") or "").strip()
    cta_sentences = [
        sentence.strip()
        for sentence in re.split(r"(?<=[。.!?！？])\s*", cta_source)
        if sentence.strip()
    ]
    explicit_action_sentences = [
        sentence for sentence in cta_sentences
        if _text_has_action_cta(sentence)
    ]
    if explicit_action_sentences:
        cta_source = " ".join(explicit_action_sentences)
    cta_terms = list(dict.fromkeys(
        token.lower()
        for token in re.findall(r"[a-z][a-z'-]{3,}", cta_source.lower())
        if token.lower() not in _CREATIVE_COPY_CONTRACT_STOPWORDS
        and token.lower() not in identity_terms
    ))
    explicit_forbidden = [
        str(item).strip().lower()
        for item in list(override.get("pre_reveal_forbidden_terms") or [])
        if str(item).strip()
    ]
    pre_reveal_terms = list(dict.fromkeys(
        explicit_forbidden
        or [
            value.lower()
            for value in (brand_identity, product_identity, *identity_terms)
            if str(value).strip()
        ]
    ))
    require_opening_tieback = override.get("require_opening_tieback")
    if require_opening_tieback is None:
        require_opening_tieback = bool(
            any(marker in lowered for marker in (
                "prevention-of-regret", "prevention of regret",
                "answer the exact emotional loss",
            ))
            or re.search(
                r"\btie(?:d)?\b.{0,48}\b(?:back|opening)\b",
                lowered,
                flags=re.IGNORECASE,
            )
        )
    conversion_segment = bounded_segment(
        override.get("conversion_segment"),
        segment_count,
    )
    require_causal_product_bridge = override.get(
        "require_causal_product_bridge"
    )
    if require_causal_product_bridge is None:
        require_causal_product_bridge = bool(
            segment_count > 1
            and any(marker in lowered for marker in (
                "must not feel pasted on",
                "enters naturally",
                "solution bridge",
                "psychological bridge",
                "one step inside",
                "part of that",
            ))
        )
    bridge_source_segment = bounded_segment(
        override.get("bridge_source_segment"),
        max(1, conversion_segment - 1),
    )
    tieback_source_segments = list(dict.fromkeys(
        bounded_segment(value, 1)
        for value in list(override.get("tieback_source_segments") or [])
    ))
    if not tieback_source_segments:
        tieback_source_segments = list(
            range(1, min(2, segment_count) + 1)
        )
    product_role_terms = list(dict.fromkeys(
        str(term).strip().lower()
        for term in list(
            override.get("product_role_terms")
            or ["step", "part", "added", "included", "became", "chose", "fit"]
        )
        if str(term).strip()
    ))
    require_post_cta_agency_ending = bool(
        override.get("require_post_cta_agency_ending", False)
    )
    post_cta_agency_terms = list(dict.fromkeys(
        str(term).strip().lower()
        for term in list(override.get("post_cta_agency_terms") or [])
        if str(term).strip()
    ))
    required_post_cta_agency_term_count = max(
        0,
        min(
            10,
            int(
                override.get("required_post_cta_agency_term_count")
                if override.get("required_post_cta_agency_term_count")
                is not None
                else (1 if require_post_cta_agency_ending else 0)
            ),
        ),
    )
    minimum_post_cta_word_count = max(
        0,
        min(
            50,
            int(override.get("minimum_post_cta_word_count") or 0),
        ),
    )
    enforce_product_reveal = bool(explicit_reveal_rule or has_reveal_override)
    return {
        "version": 2,
        "segment_count": segment_count,
        "product_required": _project_uses_product(project),
        "product_identity": product_identity or None,
        "enforce_product_reveal": enforce_product_reveal,
        "required_product_identity_terms": (
            [brand_identity.lower()]
            if brand_identity
            else identity_terms[:1]
        ),
        "product_reveal_segment": product_reveal_segment,
        "product_identity_segment": (
            product_reveal_segment if enforce_product_reveal else conversion_segment
        ),
        "conversion_segment": conversion_segment,
        "product_free_through_segment": product_free_through_segment,
        "pre_reveal_forbidden_terms": pre_reveal_terms,
        "required_price_tokens": price_tokens,
        "required_cta_terms": cta_terms,
        "required_cta_term_count": min(2, len(cta_terms)),
        "require_causal_product_bridge": bool(require_causal_product_bridge),
        "bridge_source_segment": bridge_source_segment,
        "product_role_terms": product_role_terms,
        "required_product_role_term_count": (
            1 if require_causal_product_bridge and product_role_terms else 0
        ),
        "require_opening_tieback": bool(require_opening_tieback),
        "tieback_source_segments": tieback_source_segments,
        "require_post_cta_agency_ending": require_post_cta_agency_ending,
        "post_cta_agency_terms": post_cta_agency_terms,
        "required_post_cta_agency_term_count": (
            required_post_cta_agency_term_count
        ),
        "minimum_post_cta_word_count": minimum_post_cta_word_count,
        "offer_authority": {
            "confirmed_promotions": marketing.get("confirmed_promotions"),
            "promotion_cta": marketing.get("promotion_cta"),
        },
    }


def _ensure_edit_package_promotion(
    project: HermesContentFactoryProject,
    result: dict[str, Any],
) -> dict[str, Any]:
    marketing = _marketing_authorization(project)
    promotion = _localized_promotion_cta(
        str(marketing.get("promotion_cta") or marketing.get("confirmed_promotions") or "").strip(),
        _configured_video_language(project),
    )
    if not (promotion and bool(marketing.get("allow_promotional_cta"))):
        return result

    patched = dict(result or {})
    guidance = str(patched.get("edit_guidance") or "").strip()
    caption = str(patched.get("publish_caption") or "").strip()
    guidance_has_promo = _result_contains_confirmed_promotion({"edit_guidance": guidance}, promotion)
    caption_has_promo = _result_contains_confirmed_promotion({"publish_caption": caption}, promotion)
    if _configured_video_language(project) == "zh-CN":
        cta_line = f"结尾 CTA：最后 1 秒必须自然加入「{promotion}」，字号醒目但不要遮挡产品包装。"
        if not caption_has_promo:
            patched["publish_caption"] = caption + (f"\n{promotion}" if caption else promotion)
    else:
        cta_line = (
            f"Final CTA: the character must naturally speak \"{promotion}\". "
            "The editor may optionally mirror only that same line as a small subtitle without covering the product label."
        )
        if not caption_has_promo:
            patched["publish_caption"] = caption + (f"\n{promotion}" if caption else promotion)
    if not guidance_has_promo:
        patched["edit_guidance"] = guidance + (f"\n{cta_line}" if guidance else cta_line)
    if not (guidance_has_promo and caption_has_promo):
        patched["promotion_enforced_by_server"] = True
    return patched


def _result_contains_confirmed_promotion(result: dict[str, Any], promotion: str) -> bool:
    rendered = json.dumps(result or {}, ensure_ascii=False).lower().replace("usd", "$").replace("us$", "$")
    offer = str(promotion or "").lower().replace("usd", "$").replace("us$", "$")
    amount_match = re.search(r"(?:\$\s*)?(\d+(?:\.\d{1,2})?)\s*(?:美元|美金|\$)?", offer)
    if amount_match:
        return amount_match.group(1) in rendered
    compact_offer = re.sub(r"\s+", "", offer)
    return bool(compact_offer and compact_offer in re.sub(r"\s+", "", rendered))


def _required_video_promotion(project: HermesContentFactoryProject, video: dict[str, Any] | None = None) -> str:
    """Return only an offer explicitly authorized by the project owner.

    Creative/video output is never an authorization source. Inspecting those
    structures previously mistook timeline durations and character metadata
    for an offer and injected a fabricated yellow-cart CTA.
    """
    language = _configured_video_language(project)
    marketing = _marketing_authorization(project)
    candidates = [
        str(marketing.get("promotion_cta") or "").strip(),
        str(marketing.get("confirmed_promotions") or "").strip(),
    ]
    for candidate in candidates:
        candidate = str(candidate or "").strip()
        lowered = candidate.lower()
        if any(marker in lowered for marker in (
            "duration':", 'duration":', "characters':", 'characters":',
            "segment_index", "reference_indices", "schema_version",
        )):
            continue
        if candidate:
            return _promotion_line_for_speech(_localized_promotion_cta(candidate, language), language)
    return ""


def _product_conversion_points(project: HermesContentFactoryProject, language: str) -> list[str]:
    """Return only compact selling points explicitly stored on the project."""
    if not _project_uses_product(project):
        return []
    config = dict(project.config_json or {})
    confirmed_selling_points = str(
        config.get("confirmed_selling_points") or ""
    ).strip()
    sources = [
        confirmed_selling_points
        or str(config.get("confirmed_claims") or "").strip()
    ]
    knowledge = dict((project.state_json or {}).get("product_knowledge") or {})
    facts = dict(knowledge.get("facts_envelope") or {})
    fact_result = dict(facts.get("result") or {})
    for key in ("approved_claims", "confirmed_selling_points"):
        value = fact_result.get(key)
        if isinstance(value, list):
            sources.extend(str(item).strip() for item in value if str(item).strip())
        elif value:
            sources.append(str(value).strip())
    points: list[str] = []
    product_identity = str(project.product_name or "").strip().lower()
    for source in sources:
        for item in re.split(r"[\r\n;；|]+", str(source or "")):
            point = re.sub(r"\s+", " ", item).strip(" ,，。.!！")
            lowered = point.lower()
            if (
                not point
                or lowered == product_identity
                or any(marker in lowered for marker in (
                    "do not ", "must not ", "not permission", "禁止", "不要", "不得",
                ))
            ):
                continue
            if len(point) > 90:
                point = _compact_prompt_text(point, 90)
            if point and point not in points:
                points.append(point)
    return points[:5]



def _ensure_prompt_conversion_block(
    prompt: str,
    project: HermesContentFactoryProject,
    *,
    language: str,
    promotion: str = "",
    final_segment: bool = False,
) -> str:
    text = str(prompt or "").strip()
    points = _product_conversion_points(project, language)
    if not points:
        return text
    marker = "CONVERSION PAYLOAD:"
    if marker.lower() in text.lower():
        return text
    product_name = str(project.product_name or "the approved product").strip()
    cta = _promotion_line_for_speech(promotion, language) if promotion else ""
    presentation_policy = json.dumps(
        _product_presentation_policy(project),
        ensure_ascii=False,
        separators=(",", ":"),
    )
    if language == "zh-CN":
        point_text = "、".join(points)
        block = (
            f"{marker} 使用独立上传的产品锚点准确展示 {product_name} 包装正面和标签。"
            f"已确认的产品事实仅限：{point_text}；只有创意脚本原本写入的内容才可口播，不新增台词。"
            f"严格遵守项目产品呈现策略：{presentation_policy}。不推断未配置的产品形态、用法或包装状态。"
            "不生成成分气泡、销售卡、二维码、购物界面或电视购物画面。"
        )
    else:
        point_text = ", ".join(points)
        block = (
            f"{marker} Use the separately uploaded product anchor to show the exact {product_name} "
            f"package front and label. Confirmed product facts are limited to: {point_text}; speak only "
            "facts already present in the authoritative creative dialogue and add no dialogue. Obey the "
            f"saved product presentation policy exactly: {presentation_policy}. Do not infer an unconfigured "
            "product form, use, or package state. Use physical product proof only; no ingredient "
            "bubbles, sales cards, QR codes, shopping UI, or TV-shopping frame."
        )
    return text + ("\n" if text else "") + block


def _ensure_prompt_required_promotion(prompt: str, promotion: str, language: str) -> str:
    text = str(prompt or "").strip()
    cta = _promotion_line_for_speech(promotion, language)
    if not cta:
        return text
    if cta.lower() in text.lower():
        return text
    # Creative owns the complete spoken script. If its final line already
    # carries the same authorized price and a shopping action, the conversion
    # requirement is semantically satisfied even when the wording is more
    # natural than the configured CTA. Appending a second "exact" sentence
    # would overrun a ten-second segment and create contradictory dialogue.
    if (
        _result_contains_confirmed_promotion({"prompt": text}, cta)
        and _text_has_action_cta(text)
    ):
        return text
    text = re.sub(
        r"Required final-half spoken CTA:\s*in the final 2 seconds, an adult on camera must naturally say exactly:\s*\"[^\"]*\"\.\s*If any overlay appears, use only that same CTA and do not invent other offers\.\s*",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(
        r"Required spoken(?: short-video)? CTA:\s*in the final 2 seconds, (?:an adult|the on-camera person)(?: on camera)? (?:must naturally say|naturally says) exactly:\s*\"[^\"]*\".*?(?:spoken line\.|sales pitch\.|another offer\.)\s*",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(
        r"强制后半段口播 CTA：最后 2 秒必须由镜头内成年人自然说出「[^」]*」。如果有文字叠加，只能使用同一句 CTA，不要新增未确认优惠。\s*",
        "",
        text,
    ).strip()
    text = re.sub(
        r"强制信息流口播 CTA：最后 2 秒必须由镜头内人物自然说出「[^」]*」。.*?(?:电视购物式叫卖。|同句小字幕。)\s*",
        "",
        text,
    ).strip()
    if language == "zh-CN":
        line = (
            f"强制信息流口播 CTA：最后 2 秒必须由镜头内人物自然说出「{cta}」。"
            "不要展示落地页、购物界面、二维码或电视购物画面，也不要新增未确认优惠。"
        )
    else:
        line = (
            f"Required spoken CTA: in the final 2 seconds, the on-camera person naturally says exactly: \"{cta}\". "
            "Do not show a landing page, shopping UI, QR code, or TV-shopping frame, and do not invent another offer."
        )
    return text + ("\n" if text else "") + line


def _project_requirement_text(project: HermesContentFactoryProject) -> str:
    config = dict(project.config_json or {})
    intent_spec = dict(config.get("producer_intent_spec") or {})
    manifest = dict(intent_spec.get("intent_manifest") or {})
    parts = [
        str(config.get("content_objective") or "").strip(),
        str(getattr(project, "product_brief", None) or "").strip(),
        str(intent_spec.get("user_goal") or "").strip(),
        "；".join(
            str(item.get("interpretation") or item.get("intent") or "").strip()
            for item in list(manifest.get("requirements") or [])
            if isinstance(item, dict)
            and str(item.get("interpretation") or item.get("intent") or "").strip()
        ),
        json.dumps(
            manifest.get("transformation_contract") or {},
            ensure_ascii=False,
            sort_keys=True,
        ) if manifest.get("transformation_contract") else "",
        str(config.get("confirmed_selling_points") or "").strip(),
        str(config.get("confirmed_claims") or "").strip(),
        str(config.get("confirmed_promotions") or "").strip(),
        str(config.get("promotion_cta") or "").strip(),
    ]
    return "；".join(part for part in parts if part)


def _project_intent_authority(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Return the compact user-confirmed authority for semantic reviewers.

    Benchmark analysis is evidence, not an execution contract.  Keeping the
    signed Producer requirements beside that evidence lets multimodal roles
    distinguish an explicitly authorized abstract transfer from a benchmark
    mechanism the user prohibited.  This is deliberately semantic data for
    the model, not a server-side creative keyword gate.
    """
    config = dict(project.config_json or {})
    intent = dict(config.get("producer_intent_spec") or {})
    manifest = dict(intent.get("intent_manifest") or {})
    requirements: list[dict[str, Any]] = []
    for raw in list(manifest.get("requirements") or []):
        if not isinstance(raw, dict):
            continue
        requirements.append({
            key: raw.get(key)
            for key in (
                "requirement_id",
                "kind",
                "scope",
                "intent",
                "interpretation",
                "must_not_reuse",
                "observable_checks",
                "deliverable_ordinals",
                "priority",
            )
            if raw.get(key) not in (None, "", [], {})
        })
    contract = dict(manifest.get("transformation_contract") or {})
    compact_contract = {
        key: contract.get(key)
        for key in (
            "transfer_mode",
            "source_role",
            "protected_requirements",
            "excluded_source_artifacts",
            "creative_freedom",
            "success_checks",
        )
        if contract.get(key) not in (None, "", [], {})
    }
    return {
        "schema_version": manifest.get("schema_version"),
        "manifest_sha256": manifest.get("manifest_sha256"),
        "requirements": requirements,
        "transformation_contract": compact_contract,
    }


def _project_transformation_contract(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    config = dict(project.config_json or {})
    intent = dict(config.get("producer_intent_spec") or {})
    value = dict(intent.get("intent_manifest") or {}).get(
        "transformation_contract"
    )
    return dict(value) if isinstance(value, dict) else {}


def _project_forbids_local_display_overlays(
    project: HermesContentFactoryProject,
) -> bool:
    """Honor a user-owned output ban without confusing it with source reuse.

    Benchmark caption/search strips are frequently watermark-covering artifacts,
    not creative structure. They are never inherited pixel-for-pixel, but a
    user may explicitly retain their *function* with newly authored local
    overlays. ``excluded_source_artifacts`` and phrases such as "do not copy"
    therefore do not constitute an output-wide overlay ban.
    """

    revision = dict(
        dict(getattr(project, "state_json", None) or {}).get(
            "functional_overlay_revision"
        )
        or {}
    )
    if (
        str(revision.get("status") or "").strip().lower()
        == "approved_local_postproduction_revision"
        and str(revision.get("source") or "").strip().lower()
        == "explicit_user_clarification"
    ):
        # A post-execution clarification is deliberately stored outside the
        # immutable production contract.  It may restore the *function* of
        # fresh local watermark-cover copy, but it never authorizes reuse of
        # the benchmark pixels or wording.
        return False

    intent = dict(
        dict(project.config_json or {}).get("producer_intent_spec") or {}
    )
    manifest = dict(intent.get("intent_manifest") or {})
    contract = dict(manifest.get("transformation_contract") or {})
    if str(contract.get("transfer_mode") or "").strip().lower() != (
        "inspiration_only"
    ):
        return False
    values = [
        str(item.get("interpretation") or item.get("intent") or "")
        for item in list(manifest.get("requirements") or [])
        if isinstance(item, dict)
    ]
    text = "\n".join(str(value or "") for value in values)
    return bool(
        re.search(
            r"(?:不得出现|禁止出现|不要任何|不出现任何|without any|no output|"
            r"must not|forbid(?:den)?)"
            r"[^\n。.;]{0,100}"
            r"(?:字幕条|字幕带|搜索栏|遮水印|覆盖层|平台\s*ui|"
            r"caption\s*band|subtitle\s*band|search\s*bar|"
            r"watermark[- ]cover|overlay\s*band|platform\s*ui)",
            text,
            flags=re.IGNORECASE,
        )
    )


def _extract_visual_style_requirement(value: str) -> str:
    """Return only the user-owned visual-medium section of a long brief."""
    match = re.search(
        r"(?:^|\n)VISUAL STYLE:\s*(.*?)(?=\n[A-Z][A-Z /_-]{2,}:|\Z)",
        str(value or ""),
        flags=re.DOTALL,
    )
    return _compact_prompt_text(match.group(1).strip(), 1200) if match else ""


def _project_visual_style_requirement(
    project: HermesContentFactoryProject,
) -> str:
    config = dict(project.config_json or {})
    explicit = str(
        config.get("visual_style_requirement")
        or config.get("visual_style_contract")
        or ""
    ).strip()
    return _compact_prompt_text(explicit, 1200) if explicit else (
        _extract_visual_style_requirement(_project_requirement_text(project))
    )


def _guidance_title(value: Any, *, fallback: str, limit: int = 80) -> str:
    text = str(value or "").replace("_", " ").strip()
    for marker in ("@image", "reference image", "input_reference", "segment_index", "schema_version"):
        index = text.lower().find(marker.lower())
        if index >= 0:
            text = text[:index]
    # Preserve apostrophes inside English words (Mara's, I'll). They carry
    # meaning and must not be flattened into broken overlay copy. Straight
    # double quotes and structural brackets remain non-public metadata noise.
    text = re.sub(r'[\[\]{}"]+', " ", text)
    text = re.sub(r"\s+", " ", text).strip(" ,，。.!！;；:-")
    if not text:
        text = fallback
    if len(text) <= limit:
        return text

    clipped = text[:limit].rstrip(" ,，。.!！;；:-")
    # English titles must not end in a partial word. Chinese text generally has
    # no spaces, so preserve the character-safe slice in that case.
    if re.search(r"[A-Za-z0-9]", clipped) and " " in clipped:
        whole_words = clipped.rsplit(" ", 1)[0].rstrip(" ,，。.!！;；:-")
        if whole_words:
            clipped = whole_words
    return clipped or str(fallback).strip()


def _video_asset_index(asset: HermesContentFactoryAsset) -> int:
    meta = dict(asset.meta_json or {})
    for key in ("content_factory_video_index", "video_index"):
        try:
            value = int(meta.get(key) or 0)
        except (TypeError, ValueError):
            value = 0
        if value > 0:
            return value
    return 0


def _editor_guidance_hashtag_list(
    project: HermesContentFactoryProject,
    language: str,
) -> list[str]:
    config = dict(project.config_json or {})
    profile = dict(config.get("publishing_profile") or {})
    configured = profile.get("hashtags") or config.get("hashtags") or []
    if isinstance(configured, str):
        configured = re.split(r"[\s,，;；]+", configured)
    tags = [
        value if value.startswith("#") else f"#{value}"
        for value in (str(item).strip() for item in list(configured or []))
        if value and value != "#"
    ]
    brand = str(config.get("brand_name") or "").strip()
    brand_tag = "#" + re.sub(r"[^A-Za-z0-9\u4e00-\u9fff]+", "", brand)
    if brand and brand_tag != "#" and brand_tag not in tags:
        tags.insert(0, brand_tag)
    return list(dict.fromkeys(tags))[:5]


def _public_guidance_concept(version_name: str, story_arc: str, language: str) -> str:
    """Return a viewer-facing concept name without internal variant metadata."""
    concept = re.sub(r"^\s*v\d+[\s_:\-|]*", "", str(version_name or ""), flags=re.IGNORECASE)
    concept = _guidance_title(concept, fallback="", limit=64)
    if not concept:
        concept = _guidance_title(story_arc, fallback="故事" if language == "zh-CN" else "Story", limit=64)
    if language != "zh-CN":
        concept = _public_english_title_case(concept)
    return concept


def _public_english_title_case(value: Any) -> str:
    """Title-case ordinary words without corrupting time abbreviations."""
    words: list[str] = []
    for word in str(value or "").split():
        if re.fullmatch(r"[ap]\.m\.?", word, flags=re.IGNORECASE):
            words.append(word.lower())
        else:
            words.append(word.capitalize() if word.islower() else word)
    return " ".join(words)


def _guidance_is_internal_variant_label(value: Any) -> bool:
    text = str(value or "").strip()
    return not text or bool(re.fullmatch(r"(?:v|video|variant)?[\s_-]*\d+", text, flags=re.IGNORECASE))


def _dialogue_texts(segment: dict[str, Any]) -> list[str]:
    lines: list[str] = []
    for item in list(segment.get("dialogue_lines") or []):
        value = item.get("line") if isinstance(item, dict) else item
        # Preserve complete spoken quotations for the overlay selector. The
        # general title sanitizer intentionally removes straight quotes, so
        # convert balanced pairs to typographic quotes before sanitizing.
        quote_safe_value = re.sub(
            r'"([^"\n]{1,160})"',
            lambda match: f"“{match.group(1)}”",
            str(value or ""),
        )
        # Keep enough source text for a later complete-quote extraction. A
        # painful quoted line often follows a short setup sentence.
        text = _guidance_title(quote_safe_value, fallback="", limit=180)
        if text:
            lines.append(text)
    return lines


def _display_texts(segment: dict[str, Any]) -> list[str]:
    """Return only Showrunner-declared visible copy for one segment."""
    lines: list[str] = []
    for item in list(segment.get("display_lines") or []):
        value = item.get("line") if isinstance(item, dict) else item
        text = _guidance_title(value, fallback="", limit=180)
        if text:
            lines.append(text)
    return lines


def _short_overlay_copy(value: Any, *, fallback: str, language: str) -> str:
    raw = str(value or "").strip()
    # When a story line contains a complete spoken quote, the quote is usually
    # a better chapter overlay than an attribution clipped halfway through
    # (for example: ``Ellis said, "I ...``).
    quote_match = re.search(r'[“"]([^”"\n]{3,120})[”"]', raw)
    quote_selected = False
    if quote_match and re.search(
        r"\b(?:said|asked|replied|told|whispered|heard|answered)\b",
        raw[:quote_match.start()],
        flags=re.IGNORECASE,
    ):
        raw = quote_match.group(1)
        quote_selected = True

    # Word/clause selection below is the authoritative public-length limiter.
    # Keep enough source here to avoid chopping the final noun off an otherwise
    # complete nine-word overlay before that semantic trimming runs.
    text = _guidance_title(raw, fallback=fallback, limit=120)
    # A decimal point inside an authorized price is data, not punctuation.
    # Split a period only when it is not between two digits, while retaining
    # the normal sentence/semicolon boundaries used by chapter overlays.
    abbreviation_dot = "\ue000"
    text = re.sub(
        r"\b([ap])\.m\.",
        lambda match: (
            f"{match.group(1)}{abbreviation_dot}m{abbreviation_dot}"
        ),
        text,
        flags=re.IGNORECASE,
    )
    first_sentence = re.split(
        r"(?<!\d)\.|\.(?!\d)|[!?。！？;；]+",
        text,
        maxsplit=1,
    )[0].strip()
    if first_sentence:
        text = first_sentence
    text = text.replace(abbreviation_dot, ".")
    if language == "zh-CN":
        return text[:16].rstrip("，。！？；：") or fallback

    # Drop only very short time-setting openers; retain substantive "When..."
    # clauses that carry the actual story event.
    text = re.sub(
        r"^(?:(?:by|at|before|after)\b[^,]{0,24}),\s*",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip() or text

    # A colon usually separates a strong chapter hook from its explanation.
    # Price lines are the exception: the amount after the colon is mandatory.
    if not re.search(r"(?:[$€£]\s*\d|\bprice\b|\b\d+\.\d{1,2}\b)", text, flags=re.IGNORECASE):
        colon_clause = text.split(":", 1)[0].strip()
        if 3 <= len(colon_clause.split()) <= 9:
            text = colon_clause

    # Prefer a complete leading clause when the source opens with a detailed
    # setup. A dash often marks the intended punch line boundary ("It wasn't
    # fatigue—it was ..."); a sufficiently long comma clause is also safer
    # than cutting the following clause mid-phrase.
    dash_clause = re.split(r"\s*[—–]\s*", text, maxsplit=1)[0].strip()
    if not quote_selected and 2 <= len(dash_clause.split()) <= 7:
        text = dash_clause
    else:
        comma_clause = text.split(",", 1)[0].strip()
        if 4 <= len(comma_clause.split()) <= 12:
            text = comma_clause

    words = text.split()[:9]
    dangling_words = {
        "a", "an", "the", "and", "or", "but", "to", "of", "in", "on", "at",
        "for", "with", "from", "by", "during", "into", "through", "before",
        "after", "while", "because", "that", "this", "my", "your", "her",
        "his", "our", "their", "its",
    }
    while len(words) > 2:
        tail = words[-1].strip(" ,.!?;:()[]{}“”").lower()
        if tail in dangling_words or tail.endswith(("’s", "'s")):
            words.pop()
            continue
        break
    return " ".join(words).rstrip(" ,.!?;:") or fallback


def _segment_story_overlay(
    segment: dict[str, Any],
    *,
    index: int,
    count: int,
    concept: str,
    point_title: str,
    language: str,
) -> str:
    explicit = segment.get("chapter_title") or segment.get("overlay_title")
    if explicit:
        return _short_overlay_copy(explicit, fallback=concept, language=language)
    display = _display_texts(segment)
    if display:
        return _short_overlay_copy(
            display[0],
            fallback=concept,
            language=language,
        )
    dialogue = _dialogue_texts(segment)
    if index == 1:
        source = dialogue[0] if dialogue else segment.get("segment_goal") or concept
        return _short_overlay_copy(source, fallback="今晚怎么了" if language == "zh-CN" else "What Is Keeping You Up", language=language)
    if dialogue:
        return _short_overlay_copy(dialogue[0], fallback=f"Story Turn {index}", language=language)
    if index == count:
        return _short_overlay_copy(
            point_title,
            fallback="收束" if language == "zh-CN" else "Closing Beat",
            language=language,
        )
    timeline = [item for item in list(segment.get("timeline") or []) if isinstance(item, dict)]
    action = timeline[0].get("action") if timeline else ""
    return _short_overlay_copy(
        action,
        fallback=(f"剧情转折 {index}" if language == "zh-CN" else f"Story Turn {index}"),
        language=language,
    )


def _per_video_editor_guidance_markdown(
    project: HermesContentFactoryProject,
    video_asset: HermesContentFactoryAsset,
) -> tuple[str, dict[str, Any]]:
    meta = dict(video_asset.meta_json or {})
    language = _configured_video_language(project)
    resolution = _configured_video_resolution(project)
    duration = int(meta.get("duration") or _configured_video_duration(project))
    video_index = _video_asset_index(video_asset) or 1
    version_name = str(meta.get("version_name") or f"V{video_index}").strip()
    readable_version = _guidance_title(version_name, fallback=f"V{video_index}")
    story_arc = _guidance_title(meta.get("story_arc"), fallback=readable_version, limit=140)
    segment_plan = [item for item in list(meta.get("segment_plan") or []) if isinstance(item, dict)]
    signed_plan = bool(segment_plan) and all(
        str(item.get("compile_source") or "") == "signed_production_plan"
        for item in segment_plan
    )
    marketing = _marketing_authorization(project)
    promotion = _required_video_promotion(project, {}) or _localized_promotion_cta(
        str(marketing.get("promotion_cta") or marketing.get("confirmed_promotions") or "").strip(),
        language,
    )
    promotion = _promotion_line_for_speech(promotion, language)
    promotion_allowed = bool(marketing.get("allow_promotional_cta")) and bool(promotion)
    if signed_plan:
        # Authorization is a ceiling, not permission for runtime code to
        # invent a conversion ending.  Educational, documentary, silent, and
        # non-commercial programs may share a project with reusable offer
        # metadata.  The guide may mention it only when the accepted plan does.
        promotion_allowed = promotion_allowed and _result_contains_confirmed_promotion(
            {"segments": segment_plan},
            promotion,
        )
    points = _product_conversion_points(project, language)
    hashtags = _editor_guidance_hashtag_list(project, language)
    version_is_internal = _guidance_is_internal_variant_label(version_name)
    concept = _public_guidance_concept(version_name, story_arc, language)
    if version_is_internal and segment_plan:
        first_display = _display_texts(segment_plan[0])
        first_dialogue = _dialogue_texts(segment_plan[0])
        concept = _short_overlay_copy(
            (
                first_display[0]
                if first_display
                else first_dialogue[0]
                if first_dialogue
                else segment_plan[0].get("segment_goal")
            ),
            fallback="故事" if language == "zh-CN" else "Story",
            language=language,
        )
        if language != "zh-CN":
            concept = _public_english_title_case(concept)
    point_title = concept if signed_plan else (points[0] if points else concept)

    chapter_ranges: list[tuple[int, int, str]] = []
    cursor = 0
    for index, segment in enumerate(segment_plan, 1):
        segment_duration = max(1, int(segment.get("duration") or 0))
        end = min(duration, cursor + segment_duration)
        goal = _segment_story_overlay(
            segment,
            index=index,
            count=len(segment_plan),
            concept=concept,
            point_title=point_title,
            language=language,
        )
        chapter_ranges.append((cursor, end, goal))
        cursor = end
    if chapter_ranges and chapter_ranges[-1][1] < duration:
        start, _end, goal = chapter_ranges[-1]
        chapter_ranges[-1] = (start, duration, goal)
    if not chapter_ranges:
        chapter_ranges = [(0, duration, concept)]

    normalized_ranges: list[tuple[int, int, str]] = list(chapter_ranges)
    if not signed_plan:
        # Historical assets did not carry immutable display-copy allocation.
        # Retain their bounded fallback, but never apply it to the new signed
        # universal pipeline.
        final_start = max(0, duration - 3)
        final_dialogue_rows = _dialogue_texts(segment_plan[-1]) if segment_plan else []
        final_dialogue = final_dialogue_rows[-1] if final_dialogue_rows else ""
        final_copy = promotion if promotion_allowed else final_dialogue
        if promotion_allowed:
            price_match = re.search(
                r"\$\s*\d+(?:,\d{3})*(?:\.\d{1,2})?",
                final_copy,
            )
            if price_match:
                final_copy = re.sub(r"\s+", "", price_match.group(0))
        if not final_copy:
            final_copy = "收束" if language == "zh-CN" else "Closing Beat"
        normalized_ranges = []
        for index, (start, end, goal) in enumerate(chapter_ranges):
            if index == len(chapter_ranges) - 1 and start < final_start < end:
                normalized_ranges.append((start, final_start, goal))
            elif not (index == len(chapter_ranges) - 1 and start >= final_start):
                normalized_ranges.append((start, end, goal))
        normalized_ranges.append((
            final_start,
            duration,
            _short_overlay_copy(
                final_copy,
                fallback=point_title,
                language=language,
            ),
        ))

    if language == "zh-CN":
        publish_title = f"{concept}：{point_title}" if point_title.lower() not in concept.lower() else concept
        chapters = [f'{start}-{end}秒：「{goal}」' for start, end, goal in normalized_ranges if end > start]
        lines = [
            f"标题：{publish_title}",
            f"话题：{' '.join(hashtags)}",
            "",
            "章节分镜标题：",
            *[f"- {item}" for item in chapters],
        ]
    else:
        publish_title = f"{concept}: {point_title}" if point_title.lower() not in concept.lower() else concept
        chapters = [f'{start}-{end}s: "{goal}"' for start, end, goal in normalized_ranges if end > start]
        lines = [
            f"Title: {publish_title}",
            f"Hashtags: {' '.join(hashtags)}",
            "",
            "Chapter Overlay Titles:",
            *[f"- {item}" for item in chapters],
        ]

    metadata = {
        "policy_version": EDITOR_GUIDANCE_POLICY_VERSION,
        "content_factory_video_index": video_index,
        "video_asset_id": int(video_asset.id or 0),
        "video_asset_name": video_asset.original_name,
        "version_name": version_name,
        "story_arc": story_arc,
        "segment_plan": segment_plan,
        "duration": duration,
        "resolution": resolution,
        "language": language,
        "publish_title": publish_title,
        "hashtags": hashtags,
        "promotion": promotion if promotion_allowed else "",
        "conversion_points": points,
        "source_task_ids": list(meta.get("source_task_ids") or []),
    }
    return "\n".join(lines).strip() + "\n", metadata


def _atomic_write_text_if_changed(target: Path, content: str) -> bool:
    """Atomically publish generated text and avoid churn on every waiter poll."""
    try:
        if target.is_file() and target.read_text(encoding="utf-8") == content:
            return False
    except OSError:
        pass

    temporary = target.with_name(f".{target.name}.{uuid.uuid4().hex}.tmp")
    try:
        temporary.write_text(content, encoding="utf-8")
        temporary.chmod(0o644)
        os.replace(temporary, target)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass
    return True


def _upsert_per_video_editor_guidance(
    db,
    project: HermesContentFactoryProject,
    video_asset: HermesContentFactoryAsset,
) -> HermesContentFactoryAsset:
    content, meta = _per_video_editor_guidance_markdown(project, video_asset)
    video_index = int(meta.get("content_factory_video_index") or 0)
    generated_dir = (
        CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}"
        / project.project_key / "generated" / "editor_guides"
    )
    generated_dir.mkdir(parents=True, exist_ok=True)
    stem = _safe_file_stem(Path(str(video_asset.original_name or f"video-{video_index}")).stem)
    target = generated_dir / f"{stem}-editor-guide.md"
    _atomic_write_text_if_changed(target, content)

    existing = None
    if video_index > 0:
        existing = db.query(HermesContentFactoryAsset).filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.kind == "edit_guidance",
        ).all()
        existing = next(
            (
                asset for asset in existing
                if int(dict(asset.meta_json or {}).get("content_factory_video_index") or 0) == video_index
            ),
            None,
        )
    if existing is None:
        existing = db.query(HermesContentFactoryAsset).filter_by(
            project_id=project.id,
            kind="edit_guidance",
            file_path=str(target),
        ).order_by(HermesContentFactoryAsset.id.asc()).first()

    if existing is None:
        existing = HermesContentFactoryAsset(
            project_id=project.id,
            workspace_id=project.workspace_id,
            user_id=project.user_id,
            stage="EDIT_PACKAGE",
            kind="edit_guidance",
            original_name=target.name,
            file_path=str(target),
            mime_type="text/markdown",
            size_bytes=target.stat().st_size,
            meta_json=meta,
        )
        db.add(existing)
    else:
        existing.stage = "EDIT_PACKAGE"
        existing.original_name = target.name
        existing.file_path = str(target)
        existing.mime_type = "text/markdown"
        existing.size_bytes = target.stat().st_size
        existing.meta_json = {**dict(existing.meta_json or {}), **meta}
    db.flush()
    return existing


def _delete_editor_guidance_for_video_index(
    db,
    project: HermesContentFactoryProject,
    video_index: int,
) -> int:
    if int(video_index or 0) <= 0:
        return 0
    rows = db.query(HermesContentFactoryAsset).filter(
        HermesContentFactoryAsset.project_id == project.id,
        HermesContentFactoryAsset.kind == "edit_guidance",
    ).all()
    deleted = 0
    deleted_asset_ids: set[int] = set()
    for asset in rows:
        if int(dict(asset.meta_json or {}).get("content_factory_video_index") or 0) != int(video_index):
            continue
        try:
            Path(str(asset.file_path or "")).unlink(missing_ok=True)
        except Exception:
            pass
        if asset.id:
            deleted_asset_ids.add(int(asset.id))
        db.delete(asset)
        deleted += 1
    if deleted:
        _prune_project_asset_state(project, deleted_asset_ids)
        db.flush()
    return deleted


def _compact_previous_outputs(rows, current_stage: str, *, variant_index: int | None = None) -> dict[str, Any]:
    outputs: dict[str, dict[str, Any]] = {}
    for row in rows:
        if variant_index and row.stage in VARIANT_STAGES:
            row_variant = _stage_output_variant(row)
            # Legacy rows without variant metadata belong to the first variant.
            if row_variant is None:
                row_variant = 1
            if row_variant != int(variant_index):
                continue
        outputs[row.stage] = dict(row.output_json or {})

    def result(stage: str, fields: list[str]) -> dict[str, Any] | None:
        envelope = outputs.get(stage)
        if not envelope:
            return None
        source = dict(envelope.get("result") or {})
        return {field: source[field] for field in fields if field in source}

    def production_design() -> dict[str, Any] | None:
        production = result(
            "PRODUCTION_PLAN",
            [
                "compiled_media_design",
                "production_plan",
                "asset_registry",
                "audit_row_id",
            ],
        )
        if production:
            compiled = production.get("compiled_media_design")
            if isinstance(compiled, dict) and compiled:
                return dict(compiled)
        # Historical completed variants remain readable. New workflow writers
        # never create a CREATIVE stage after an enforced Director artifact.
        return None

    compiled_design = production_design()

    wanted: dict[str, dict[str, Any] | None]
    if current_stage == "PRODUCTION_PLAN":
        wanted = {
            "FACTS": result(
                "FACTS",
                [
                    "product_passport", "approved_claims",
                    "prohibited_claims", "visual_invariants",
                    "application_rules", "product_truth_handoff",
                ],
            ),
            "DIRECTOR": result(
                "DIRECTOR",
                [
                    "brief_id", "brief_version", "loop_status",
                    "director_artifact",
                ],
            ),
        }
    elif current_stage == "VISUAL_PREVIEW":
        wanted = {
            "FACTS": result("FACTS", ["approved_claims", "prohibited_claims", "visual_invariants", "application_rules"]),
            "MEDIA_DESIGN": compiled_design,
        }
    elif current_stage == "CREATIVE_REVIEW":
        wanted = {
            "FACTS": result("FACTS", ["approved_claims", "prohibited_claims", "visual_invariants", "application_rules"]),
            "MEDIA_DESIGN": compiled_design,
            "VISUAL_PREVIEW": result("VISUAL_PREVIEW", ["preview_canvas", "asset_manifest", "self_check"]),
        }
    elif current_stage == "FINAL_ASSETS":
        wanted = {
            "MEDIA_DESIGN": compiled_design,
            "VISUAL_PREVIEW": result("VISUAL_PREVIEW", ["preview_canvas", "asset_manifest"]),
            "CREATIVE_REVIEW": result("CREATIVE_REVIEW", ["creative_review", "approved_for_split", "reference_image_count", "repair_brief"]),
        }
    elif current_stage == "VIDEO_PROMPTS":
        wanted = {
            "MEDIA_DESIGN": compiled_design,
            "FINAL_ASSETS": result("FINAL_ASSETS", ["reference_images", "continuity_manifest"]),
        }
    elif current_stage == "EDIT_PACKAGE":
        wanted = {
            "FACTS": result("FACTS", ["approved_claims", "prohibited_claims"]),
            "MEDIA_DESIGN": compiled_design,
            "VIDEO_PROMPTS": _compact_video_plan_for_edit_package(result("VIDEO_PROMPTS", ["videos", "prompts"])),
        }
    else:
        wanted = {stage: dict(envelope.get("result") or {}) for stage, envelope in list(outputs.items())[-2:]}
    return {stage: value for stage, value in wanted.items() if value}


def _content_director_enforced(project: HermesContentFactoryProject) -> bool:
    return (
        str(
            dict(project.config_json or {}).get("content_director_mode")
            or ""
        ).strip().lower()
        == "enforce"
    )


def _approved_director_artifact_for_variant(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
):
    """Return the newest audited artifact allowed to authorize media work.

    The project-state pointer is only a recoverable cache.  The newest
    successful DIRECTOR stage for this variant and its immutable accepted audit
    row are the durable authorities.  A concurrent video waiter can commit a
    state snapshot taken before a parallel Director finishes; when that erases
    or stales only the redundant pointer, rebuild it from those two immutable
    authorities instead of paying for another Director turn.
    """
    from app.data.models.hermes_agent import HermesContentDirectorArtifact
    from app.services.hermes_agent.content_director import (
        DirectedContentArtifact,
    )

    if not _content_director_enforced(project):
        return None
    variant = max(1, int(variant_index or 1))
    stage_rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "DIRECTOR",
            HermesContentFactoryStage.status == "success",
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .all()
    )
    matching_stage = next(
        (
            row
            for row in stage_rows
            if int(_stage_output_variant(row) or 1) == variant
        ),
        None,
    )
    if matching_stage is None:
        raise ValueError(
            "DIRECTOR_MEDIA_GATE_MISSING: no successful DIRECTOR stage exists "
            f"for variant {variant}"
        )
    result = dict(dict(matching_stage.output_json or {}).get("result") or {})
    raw_artifact = result.get("director_artifact")
    if not isinstance(raw_artifact, dict):
        raise ValueError(
            "DIRECTOR_MEDIA_GATE_ARTIFACT_MISSING: successful DIRECTOR stage "
            f"{int(matching_stage.id)} has no immutable artifact"
        )
    artifact = DirectedContentArtifact.model_validate(raw_artifact)
    accepted_row = (
        db.query(HermesContentDirectorArtifact)
        .filter(
            HermesContentDirectorArtifact.project_id == project.id,
            HermesContentDirectorArtifact.variant_index == variant,
            HermesContentDirectorArtifact.artifact_sha256
            == artifact.artifact_sha256,
            HermesContentDirectorArtifact.accepted.is_(True),
        )
        .one_or_none()
    )
    if accepted_row is None:
        raise ValueError(
            "DIRECTOR_MEDIA_GATE_AUDIT_MISSING: the Director artifact is not "
            "present as an accepted immutable audit row"
        )
    project_state = dict(project.state_json or {})
    pointers_by_variant = dict(
        project_state.get("approved_director_artifacts_by_variant") or {}
    )
    state_pointer = dict(
        pointers_by_variant.get(str(variant))
        or (
            project_state.get("approved_director_artifact")
            if int(
                dict(
                    project_state.get("approved_director_artifact") or {}
                ).get("variant_index")
                or 0
            )
            == variant
            else {}
        )
        or {}
    )
    expected_pointer = {
        "variant_index": variant,
        "artifact_sha256": artifact.artifact_sha256,
        "script_sha256": artifact.script.canonical_text_sha256,
        "director_stage_id": int(matching_stage.id),
    }
    mismatches = [
        key
        for key, expected in expected_pointer.items()
        if state_pointer.get(key) != expected
    ]
    if mismatches:
        pointers_by_variant[str(variant)] = expected_pointer
        project_state["approved_director_artifacts_by_variant"] = (
            pointers_by_variant
        )
        project_state["approved_director_artifact"] = expected_pointer
        project_state["restored_director_artifact_pointer"] = {
            **expected_pointer,
            "at": _stage_now().isoformat(),
            "reason": "recovered_after_concurrent_video_state_merge",
        }
        project.state_json = project_state
        db.flush()
    return artifact


def _director_locked_creative_result(
    project: HermesContentFactoryProject,
    result: dict[str, Any],
    *,
    artifact,
) -> dict[str, Any]:
    """Merge production design around Director copy without changing copy.

    CREATIVE owns visual actions, shot construction, continuity, and voice
    performance.  The Director owns line identity, text, speaker, order,
    segment allocation, duration, audio mode, and integrity hashes.
    """
    normalized = dict(result or {})
    raw_script = dict(normalized.get("complete_video_script") or {})
    production_segments = [
        dict(item)
        for item in list(raw_script.get("segments") or [])
        if isinstance(item, dict)
    ]
    production_by_index = {
        _coerce_segment_number(
            item.get("segment_index") or item.get("segment"),
            position,
        ): item
        for position, item in enumerate(production_segments, 1)
    }
    line_by_id = {
        line.line_id: line
        for line in artifact.script.lines
    }
    locked_segments: list[dict[str, Any]] = []
    for allocation in artifact.script.segments:
        segment_index = int(allocation.segment_index)
        production = dict(production_by_index.get(segment_index) or {})
        dialogue = [
            {
                "line_id": line_by_id[line_id].line_id,
                "speaker_id": line_by_id[line_id].speaker_id,
                "speaker": line_by_id[line_id].speaker_id,
                "line": line_by_id[line_id].text,
            }
            for line_id in allocation.line_ids
        ]
        purposes = list(dict.fromkeys(
            line_by_id[line_id].purpose
            for line_id in allocation.line_ids
        ))
        story_function = str(
            production.get("story_function")
            or production.get("narrative_function")
            or production.get("segment_goal")
            or " / ".join(purposes)
            or _creative_positional_story_function(
                segment_index,
                len(artifact.script.segments),
            )
        ).strip()
        locked_segments.append(
            {
                **production,
                "segment_index": segment_index,
                "duration_seconds": float(allocation.duration_seconds),
                "story_function": story_function,
                "dialogue_lines": dialogue,
                "director_line_ids": list(allocation.line_ids),
            }
        )

    strategy = dict(artifact.program.creative_strategy or {})
    raw_outline = raw_script.get("story_outline")
    story_outline = (
        dict(raw_outline)
        if isinstance(raw_outline, dict)
        else {}
    )
    if not story_outline:
        strategy_outline = strategy.get("story_outline")
        if isinstance(strategy_outline, dict):
            story_outline = dict(strategy_outline)
    if not story_outline and locked_segments:
        story_outline = {
            "opening": str(locked_segments[0].get("story_function") or ""),
            "development": " ".join(
                str(item.get("story_function") or "")
                for item in (
                    locked_segments[1:-1] or locked_segments[:1]
                )
            ).strip(),
            "resolution": str(
                locked_segments[-1].get("story_function") or ""
            ),
        }

    normalized["complete_video_script"] = {
        **raw_script,
        "script_id": artifact.script.script_id,
        "program_id": artifact.script.program_id,
        "audio_mode": artifact.script.audio_mode,
        "duration_seconds": float(
            artifact.script.target_duration_seconds
        ),
        "target_edit_duration_seconds": float(
            artifact.script.target_duration_seconds
            - artifact.script.edit_headroom_seconds
        ),
        "speech_rate_wpm": float(artifact.script.speech_rate_wpm),
        "primary_speaker_id": artifact.script.primary_speaker_id,
        "canonical_text_sha256": (
            artifact.script.canonical_text_sha256
        ),
        "story_outline": story_outline,
        "segments": locked_segments,
    }
    normalized["director_lock"] = {
        "artifact_id": artifact.artifact_id,
        "artifact_revision": int(artifact.revision),
        "artifact_sha256": artifact.artifact_sha256,
        "script_id": artifact.script.script_id,
        "script_sha256": artifact.script.canonical_text_sha256,
        "audio_mode": artifact.script.audio_mode,
        "line_ids": [line.line_id for line in artifact.script.lines],
        "segment_line_ids": [
            {
                "segment_index": int(item.segment_index),
                "line_ids": list(item.line_ids),
            }
            for item in artifact.script.segments
        ],
    }
    return normalized


def _assert_director_script_lock(
    project: HermesContentFactoryProject,
    creative_result: dict[str, Any],
    *,
    artifact,
) -> None:
    """Fail closed if downstream production design changed Director copy."""
    if not _content_director_enforced(project):
        return
    lock = dict(creative_result.get("director_lock") or {})
    expected_lock = {
        "artifact_sha256": artifact.artifact_sha256,
        "script_sha256": artifact.script.canonical_text_sha256,
        "audio_mode": artifact.script.audio_mode,
    }
    mismatches = [
        key for key, expected in expected_lock.items()
        if lock.get(key) != expected
    ]
    if mismatches:
        raise ValueError(
            "DIRECTOR_SCRIPT_LOCK_IDENTITY_MISMATCH: CREATIVE does not carry "
            f"the accepted Director identity; mismatches={mismatches}"
        )
    script = dict(creative_result.get("complete_video_script") or {})
    segments = [
        dict(item)
        for item in list(script.get("segments") or [])
        if isinstance(item, dict)
    ]
    if len(segments) != len(artifact.script.segments):
        raise ValueError(
            "DIRECTOR_SCRIPT_LOCK_SEGMENT_MISMATCH: CREATIVE changed the "
            "Director segment count"
        )
    actual_rows: list[tuple[str, str, str]] = []
    actual_allocations: list[tuple[int, list[str]]] = []
    for expected_allocation, segment in zip(
        artifact.script.segments,
        segments,
    ):
        segment_index = int(segment.get("segment_index") or 0)
        dialogue = _normalized_dialogue_lines(
            segment.get("dialogue_lines")
        )
        line_ids = [str(item.get("line_id") or "") for item in dialogue]
        actual_allocations.append((segment_index, line_ids))
        for item in dialogue:
            actual_rows.append(
                (
                    str(item.get("line_id") or ""),
                    str(item.get("speaker_id") or ""),
                    str(item.get("line") or ""),
                )
            )
        if (
            segment_index != int(expected_allocation.segment_index)
            or line_ids != list(expected_allocation.line_ids)
        ):
            raise ValueError(
                "DIRECTOR_SCRIPT_LOCK_ALLOCATION_MISMATCH: CREATIVE moved, "
                "lost, duplicated, or reordered a Director line"
            )
    expected_rows = [
        (line.line_id, line.speaker_id, line.text)
        for line in artifact.script.lines
    ]
    if actual_rows != expected_rows:
        raise ValueError(
            "DIRECTOR_SCRIPT_LOCK_TEXT_MISMATCH: CREATIVE changed Director "
            "line text, speaker identity, or order"
        )
    if (
        str(script.get("canonical_text_sha256") or "")
        != artifact.script.canonical_text_sha256
    ):
        raise ValueError(
            "DIRECTOR_SCRIPT_LOCK_HASH_MISMATCH: CREATIVE script hash differs "
            "from the accepted Director script"
        )


def _approved_production_plan_bundle_for_variant(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
) -> dict[str, Any] | None:
    """Return the signed, audited plan and its deterministic media design.

    The successful stage and immutable audit row are authoritative.  The
    project-state pointer is a recoverable cache and may be republished when a
    concurrent video waiter committed an older state snapshot.  Downstream
    media code may consume the compiler output, but it may not recover creative
    authority from a legacy ``CREATIVE`` row.
    """
    if not _content_director_enforced(project):
        return None
    from app.data.models.hermes_agent import (
        HermesContentProductionPlanAudit,
    )
    from app.services.hermes_agent.content_production_plan import (
        DirectedProductionPlan,
    )

    variant = max(1, int(variant_index or 1))
    artifact = _approved_director_artifact_for_variant(
        db,
        project,
        variant_index=variant,
    )
    plan_rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "PRODUCTION_PLAN",
            HermesContentFactoryStage.status == "success",
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .all()
    )
    plan_stage = next(
        (
            row
            for row in plan_rows
            if int(_stage_output_variant(row) or 1) == variant
        ),
        None,
    )
    if plan_stage is None:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_MISSING: no successful signed "
            f"PRODUCTION_PLAN exists for variant {variant}"
        )
    plan_result = dict(
        dict(plan_stage.output_json or {}).get("result") or {}
    )
    raw_plan = plan_result.get("production_plan")
    if not isinstance(raw_plan, dict):
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_ARTIFACT_MISSING: the successful "
            "stage has no signed production plan"
        )
    plan = DirectedProductionPlan.model_validate(raw_plan)
    if plan.visual.director_artifact_sha256 != artifact.artifact_sha256:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_DIRECTOR_MISMATCH: the plan belongs "
            "to another Director artifact"
        )
    compiled = plan_result.get("compiled_media_design")
    if not isinstance(compiled, dict) or not compiled:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_COMPILED_DESIGN_MISSING: the signed "
            "plan has no deterministic media design"
        )
    _assert_director_script_lock(
        project,
        compiled,
        artifact=artifact,
    )
    plan_lock = dict(compiled.get("production_plan_lock") or {})
    expected_plan_lock = {
        "plan_id": plan.plan_id,
        "plan_revision": int(plan.revision),
        "plan_sha256": plan.plan_sha256,
        "director_artifact_sha256": artifact.artifact_sha256,
    }
    lock_mismatches = [
        key
        for key, expected in expected_plan_lock.items()
        if plan_lock.get(key) != expected
    ]
    if lock_mismatches:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_LOCK_MISMATCH: compiled media does "
            f"not match the signed plan; mismatches={lock_mismatches}"
        )
    audit_row = (
        db.query(HermesContentProductionPlanAudit)
        .filter(
            HermesContentProductionPlanAudit.project_id == project.id,
            HermesContentProductionPlanAudit.stage_id == plan_stage.id,
            HermesContentProductionPlanAudit.variant_index == variant,
            HermesContentProductionPlanAudit.plan_sha256 == plan.plan_sha256,
            HermesContentProductionPlanAudit.director_artifact_sha256
            == artifact.artifact_sha256,
            HermesContentProductionPlanAudit.accepted.is_(True),
        )
        .one_or_none()
    )
    if audit_row is None:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_GATE_AUDIT_MISSING: the plan is not "
            "present as an accepted immutable audit row"
        )
    project_state = dict(project.state_json or {})
    pointers_by_variant = dict(
        project_state.get("approved_production_plans_by_variant") or {}
    )
    current_pointer = dict(
        pointers_by_variant.get(str(variant))
        or (
            project_state.get("approved_production_plan")
            if int(
                dict(
                    project_state.get("approved_production_plan") or {}
                ).get("variant_index")
                or 0
            )
            == variant
            else {}
        )
        or {}
    )
    expected_pointer = {
        "variant_index": variant,
        "plan_id": plan.plan_id,
        "plan_sha256": plan.plan_sha256,
        "director_artifact_sha256": artifact.artifact_sha256,
        "production_plan_stage_id": int(plan_stage.id),
        "audit_row_id": int(audit_row.id),
    }
    pointer_mismatches = [
        key
        for key, expected in expected_pointer.items()
        if current_pointer.get(key) != expected
    ]
    if pointer_mismatches:
        pointers_by_variant[str(variant)] = expected_pointer
        project_state["approved_production_plans_by_variant"] = (
            pointers_by_variant
        )
        project_state["approved_production_plan"] = expected_pointer
        project_state["restored_production_plan_pointer"] = {
            **expected_pointer,
            "at": _stage_now().isoformat(),
            "reason": "recovered_after_concurrent_video_state_merge",
        }
        project.state_json = project_state
        db.flush()
    return {
        "variant_index": variant,
        "artifact": artifact,
        "plan": plan,
        "compiled_media_design": dict(compiled),
        "production_plan_stage_id": int(plan_stage.id),
        "production_plan_audit_id": int(audit_row.id),
    }


def _assert_director_media_authorization(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
) -> dict[str, Any] | None:
    """Authorize media spend only from one accepted Production Plan."""
    bundle = _approved_production_plan_bundle_for_variant(
        db,
        project,
        variant_index=variant_index,
    )
    if bundle is None:
        return None
    artifact = bundle["artifact"]
    plan = bundle["plan"]
    return {
        "variant_index": int(bundle["variant_index"]),
        "director_artifact_sha256": artifact.artifact_sha256,
        "director_script_sha256": artifact.script.canonical_text_sha256,
        "production_plan_id": plan.plan_id,
        "production_plan_sha256": plan.plan_sha256,
        "production_plan_stage_id": int(
            bundle["production_plan_stage_id"]
        ),
        "production_plan_audit_id": int(
            bundle["production_plan_audit_id"]
        ),
        "audio_mode": artifact.script.audio_mode,
    }


def _successful_media_design_for_variant(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
) -> dict[str, Any]:
    """Return only the current variant's signed Production Plan design."""
    variant = max(1, int(variant_index or 1))
    bundle = _approved_production_plan_bundle_for_variant(
        db,
        project,
        variant_index=variant,
    )
    if bundle is None:
        raise ValueError(
            "PRODUCTION_PLAN_MEDIA_DESIGN_MISSING: project has no approved "
            f"production plan for variant {variant}"
        )
    return dict(bundle["compiled_media_design"])


def _prompt_safe_value(value: Any, *, max_string: int = 1800, max_items: int = 24, depth: int = 0) -> Any:
    """Bound the packet sent to ChatGPT without mutating server state.

    Long prior responses and project state can make ChatGPT's composer disable
    the send button. Keep structure intact, but trim low-signal bulk.
    """
    if depth > 7:
        text = str(value)
        return text[:max_string] + ("...[truncated]" if len(text) > max_string else "")
    if isinstance(value, str):
        normalized = value.strip()
        return normalized[:max_string] + ("...[truncated]" if len(normalized) > max_string else "")
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    if isinstance(value, list):
        return [
            _prompt_safe_value(item, max_string=max(600, max_string // 2), max_items=max_items, depth=depth + 1)
            for item in value[:max_items]
        ]
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        skip_keys = {
            "raw_response", "response_text", "chat_history", "debug", "trace", "logs",
            "celery_task_id", "ai_video_groups", "ai_video_retry_history",
            "ai_video_task_payloads", "ai_video_completed_segments",
        }
        for index, (key, item) in enumerate(value.items()):
            if index >= max_items:
                out["_truncated_keys"] = max(0, len(value) - max_items)
                break
            if str(key) in skip_keys:
                continue
            out[str(key)] = _prompt_safe_value(
                item,
                max_string=max(600, max_string // 2),
                max_items=max_items,
                depth=depth + 1,
            )
        return out
    return str(value)[:max_string]


def _compact_project_state_for_prompt(state: dict[str, Any], stage: str) -> dict[str, Any]:
    keep = {
        "browser_bridge_id",
        "browser_inbox_root",
        "active_variant_index",
        "product_facts_source",
        "ai_video_ready_video_count",
        "ai_video_failed_task_ids",
        "ai_video_pending_segment_count",
        "ai_video_ready_segment_count",
        "benchmark_video_analysis",
    }
    if stage == "EDIT_PACKAGE":
        keep.update({"ai_video_ready_video_count", "ai_video_failed_task_ids", "ai_video_groups"})
    compact = {key: state.get(key) for key in keep if key in state}
    pipeline = dict(state.get("video_variant_pipeline") or {})
    if pipeline:
        compact["video_variant_pipeline"] = {
            key: pipeline.get(key)
            for key in ("target_count", "active_index", "completed_indices", "failed_indices", "submitted_indices")
            if key in pipeline
        }
    learning = dict(state.get("hermes_learning") or {})
    if learning:
        compact["hermes_learning"] = _prompt_safe_value(learning, max_string=800, max_items=12)
    return _prompt_safe_value(compact, max_string=1000, max_items=18)


def _compact_reference_plan_for_prompt(value: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for fallback_index, raw in enumerate(list(value or [])[:12], 1):
        if not isinstance(raw, dict):
            continue
        row: dict[str, Any] = {
            "index": int(raw.get("index") or fallback_index),
        }
        for key in (
            "reference_id", "segment", "segments", "roles", "semantic_roles",
            "description", "purpose", "action", "shot",
            "single_frame_terminal_state", "requires_product_reference",
            # These are execution authority, not optional prompt decoration.
            # Product source assets are provider identity references, never
            # instructions for a local pixel paste.
            "generation_mode", "source_asset_refs",
            "product_render_mode",
        ):
            if raw.get(key) in (None, "", [], {}):
                continue
            row[key] = _short_prompt_value(raw.get(key), max_chars=260, max_items=6)
        rows.append(row)
    return rows


def _short_prompt_value(value: Any, *, max_chars: int = 220, max_items: int = 8, depth: int = 0) -> Any:
    """Small, predictable model-facing summaries for nested creative data."""
    if depth >= 3:
        text = str(value).strip()
        return text[:max_chars] + ("...[truncated]" if len(text) > max_chars else "")
    if isinstance(value, str):
        text = value.strip()
        return text[:max_chars] + ("...[truncated]" if len(text) > max_chars else "")
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    if isinstance(value, list):
        return [
            _short_prompt_value(item, max_chars=max_chars, max_items=max_items, depth=depth + 1)
            for item in value[:max_items]
        ]
    if isinstance(value, dict):
        return {
            str(key): _short_prompt_value(item, max_chars=max_chars, max_items=max_items, depth=depth + 1)
            for key, item in list(value.items())[:max_items]
        }
    text = str(value).strip()
    return text[:max_chars] + ("...[truncated]" if len(text) > max_chars else "")


def _compact_shot_plan_for_prompt(
    value: Any,
    *,
    max_rows: int = 12,
    visual_max_chars: int = 520,
) -> list[dict[str, Any]]:
    flattened: list[dict[str, Any]] = []
    for raw in list(value or []):
        if not isinstance(raw, dict):
            continue
        nested = raw.get("shots")
        candidates = list(nested) if isinstance(nested, list) else [raw]
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            row: dict[str, Any] = {}
            for key in (
                "shot_id", "segment", "time", "timecode", "start_second", "end_second",
                "visual_state", "terminal_state", "final_state", "visual_action",
                "visual_story", "visual", "action", "camera", "dialogue", "text",
                "audio", "product_visible",
            ):
                if candidate.get(key) in (None, "", [], {}):
                    continue
                row[key] = _short_prompt_value(
                    candidate.get(key),
                    # Concrete visual state is the image compiler's authority;
                    # do not truncate a complete terminal pose or product
                    # placement to the generic metadata limit.
                    max_chars=visual_max_chars if key in {
                        "visual_state", "terminal_state", "final_state",
                        "visual_action", "visual_story", "visual", "action",
                    } else 180,
                    max_items=4,
                )
            if row:
                flattened.append(row)
            if len(flattened) >= max_rows:
                return flattened
    return flattened


def _creative_selected_concept(creative: dict[str, Any]) -> dict[str, Any]:
    raw = creative.get("selected_concept")
    if isinstance(raw, dict):
        return dict(raw)
    selected_id = str(raw or "").strip().lower()
    if selected_id:
        concepts = creative.get("concepts")
        for candidate in concepts if isinstance(concepts, list) else []:
            if not isinstance(candidate, dict):
                continue
            aliases = {
                str(candidate.get(key) or "").strip().lower()
                for key in ("concept_id", "id", "name", "title")
            }
            if selected_id in aliases:
                return dict(candidate)
        return {"concept_id": str(raw).strip()}
    return {}


def _compact_visual_previous_outputs(previous: dict[str, Any]) -> dict[str, Any]:
    creative_raw = previous.get("MEDIA_DESIGN")
    creative = _reference_contract_for_media_execution(
        dict(creative_raw) if isinstance(creative_raw, dict) else {}
    )
    selected = _creative_selected_concept(creative)
    selected_summary = {
        key: _short_prompt_value(selected.get(key), max_chars=260, max_items=5)
        for key in (
            "concept_id", "id", "name", "title", "logline", "hook", "tone",
            "format", "visual_identity",
        )
        if selected.get(key) not in (None, "", [], {})
    }
    ticket_raw = creative.get("visual_job_ticket")
    ticket = dict(ticket_raw) if isinstance(ticket_raw, dict) else {}
    ticket_summary = {
        key: _short_prompt_value(ticket.get(key), max_chars=260, max_items=5)
        for key in (
            "source", "plan_id", "plan_sha256", "job_id", "board_rule",
            "canvas", "orientation", "resolution",
            "video_model", "visual_style", "character_lock", "character_description",
            "scene_lock", "product_lock", "reference_image_count", "final_reference_count",
        )
        if ticket.get(key) not in (None, "", [], {})
    }
    references = _compact_reference_plan_for_prompt(ticket.get("reference_plan"))
    if references:
        ticket_summary["reference_plan"] = references
    return {
        "MEDIA_DESIGN": {
            "selected_concept": selected_summary,
            "visual_job_ticket": ticket_summary,
            "continuity_rules": _short_prompt_value(
                creative.get("continuity_rules") or {}, max_chars=180, max_items=8,
            ),
            # The reference plan above is the image-stage authority. Keep only
            # a bounded supporting shot sample here so the same long action is
            # not serialized twice and allowed to crowd out the references.
            "shot_plan": _compact_shot_plan_for_prompt(
                creative.get("shot_plan") or [],
                max_rows=8,
                visual_max_chars=360,
            ),
        }
    }


_ADULT_PRODUCT_CONTEXT_MINOR_RE = re.compile(
    r"\b(?:child|children|kid|kids|teen|teenager|teenagers|minor|daughter|son|"
    r"school|homework)\b",
    flags=re.IGNORECASE,
)


def _adult_product_creative_context(packet: dict[str, Any]) -> tuple[str, list[Any]]:
    """Remove positive minor-story examples from adult product prompt context.

    The project writing brief historically included "a child puts a drawing
    away" as one possible knife-twist, and prior-variant fingerprints could
    contain complete school/parent stories. The API model treated those rich
    examples as stronger instructions than the short adult-only rule and
    repeatedly regenerated prohibited casts. Preserve the pain framework but
    replace that positive example and omit contaminated do-not-repeat
    fingerprints from provider context. The original project/state remains
    untouched.
    """
    requirements = str(packet.get("project_requirements") or "")
    requirements = re.sub(
        r"\ba child puts a drawing away\b",
        "an adult partner quietly stops asking",
        requirements,
        flags=re.IGNORECASE,
    )
    briefs = []
    for item in list(packet.get("previous_variant_briefs") or []):
        encoded = json.dumps(item, ensure_ascii=False)
        if _ADULT_PRODUCT_CONTEXT_MINOR_RE.search(encoded):
            continue
        briefs.append(item)
    return requirements, briefs


def _creative_conversion_requirement_excerpt(requirements: str) -> str:
    """Preserve both ends of any long user brief without campaign assumptions.

    A blind prefix cut can drop decisive requirements placed near the end.
    Keep a bounded prefix for premise and a bounded tail for later constraints;
    do not depend on one customer's heading names, brand, offer, story shape,
    language, or number of segments.
    """
    raw = str(requirements or "").replace("\r\n", "\n").replace("\r", "\n")
    if not raw.strip():
        return ""
    if len(raw) <= 6200:
        return raw
    # minimal_stage_context already carries the first 2,400 characters in
    # project_requirement. Spend this separate budget on the immediate
    # continuation plus the tail instead of duplicating the same prefix.
    continuation = raw[2200:4300].strip()
    tail_start = max(4300, len(raw) - 4000)
    tail = raw[tail_start:].strip()
    return (
        f"{continuation}\n\n[Middle of long project brief omitted only for "
        f"provider context size; saved project remains authoritative.]\n\n{tail}"
    )[:6200]


def _compact_packet_for_chatgpt(packet: dict[str, Any], stage: str) -> dict[str, Any]:
    compact = dict(packet)
    # This registry is server-only validation evidence. Sending every prior
    # successful attempt to the provider would bloat the request and defeat the
    # deliberately bounded prompt context.
    compact.pop("authoritative_previous_variant_briefs", None)
    previous = dict(compact.get("previous_outputs") or {})
    signed_review_media_design = (
        _compact_visual_previous_outputs(previous).get("MEDIA_DESIGN")
        if stage == "CREATIVE_REVIEW" and previous.get("MEDIA_DESIGN")
        else None
    )
    if stage == "VISUAL_PREVIEW":
        compact_previous = _compact_visual_previous_outputs(previous)
        keep_keys = {
            "project_id", "execution_id", "content_mode", "product_required", "product", "market", "brief", "current_stage",
            # Visual execution is API-first.  Unlike a browser text prompt,
            # its compact packet is the *only* source the image provider sees,
            # so never drop the stage's hard medium instruction here.
            "user_instruction", "visual_style_requirement",
            "browser_slot", "browser_cdp_url", "browser_bridge_id",
            "browser_device_id", "browser_device_name", "browser_inbox_root",
            "browser_asset_paths", "browser_assets", "browser_output_path",
            "force_fresh_response", "allow_visible_visual_recovery", "knowledge_namespace", "video_count",
            "video_variant_index", "video_variant_total", "video_variant_mode",
            "render_reference_images_individually",
            "visual_reference_generation_mode", "visual_image_model_chain",
            "visual_image_model", "visual_image_model_index",
            "video_duration_range_seconds", "recommended_video_duration_seconds",
            "video_segment_durations_seconds", "video_segment_count",
            "video_model", "video_reference_limit", "video_reference_video_limit",
            "video_resolution", "video_language", "video_language_label",
            "video_model_policy", "marketing_authorization", "project_requirements",
            "creative_cast_policy", "product_presentation_policy",
            "self_heal_action", "self_heal_reason", "visual_repair_instruction",
            "visual_repair_failed_indices", "visual_repair_preserved_references",
            "visual_repair_continuity_anchor_indices",
            "visual_repair_source_review_stage_id",
            "required_result_fields", "required_next_stage",
        }
        compact = {key: compact.get(key) for key in keep_keys if key in compact}
        compact["previous_outputs"] = compact_previous
        compact["project_state"] = _compact_project_state_for_prompt(dict(packet.get("project_state") or {}), stage)
        compact["project_assets"] = compact.get("browser_assets") or []
        compact["marketing_authorization"] = _prompt_safe_value(compact.get("marketing_authorization") or {}, max_string=420, max_items=8)
        compact["video_model_policy"] = _prompt_safe_value(compact.get("video_model_policy") or {}, max_string=380, max_items=10)
        raw_requirements = str(packet.get("project_requirements") or "")
        compact["project_requirements"] = _prompt_safe_value(raw_requirements, max_string=700, max_items=6)
        # The project requirements begin with copy constraints.  The visual
        # contract is deliberately farther down and used to be truncated out,
        # causing an image API request for adult animation to silently become
        # a photorealistic request.  Preserve only the visual section as a
        # separate compact field rather than expanding the provider packet.
        if not compact.get("visual_style_requirement"):
            visual_requirement = _extract_visual_style_requirement(
                raw_requirements
            )
            if visual_requirement:
                compact["visual_style_requirement"] = _prompt_safe_value(
                    visual_requirement, max_string=1200, max_items=12,
                )
        return compact
    if stage == "FINAL_ASSETS":
        previous.pop("FACTS", None)
        previous_limit = 320
        previous_items = 8
    elif stage == "VISUAL_PREVIEW":
        previous_limit = 360
        previous_items = 8
    elif stage == "CREATIVE_REVIEW":
        previous_limit = 420
        previous_items = 8
    else:
        previous_limit = 1400
        previous_items = 18
    compact["previous_outputs"] = _prompt_safe_value(
        previous,
        max_string=previous_limit,
        max_items=previous_items,
    )
    compact["project_state"] = _compact_project_state_for_prompt(dict(compact.get("project_state") or {}), stage)
    compact["learned_constraints"] = _prompt_safe_value(compact.get("learned_constraints") or {}, max_string=900, max_items=12)
    visual_stage = stage in {"VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS"}
    compact["project_requirements"] = _prompt_safe_value(
        compact.get("project_requirements") or "",
        max_string=900 if visual_stage else 1400,
        max_items=8,
    )
    if stage == "CREATIVE_REVIEW":
        # Preserve the signed semantic authority independently from the
        # human-readable requirement summary.  Truncating that summary before
        # the benchmark exclusions made the visual reviewer enforce raw
        # benchmark suggestions that the user had explicitly forbidden.
        compact["producer_intent_authority"] = _prompt_safe_value(
            compact.get("producer_intent_authority") or {},
            max_string=1200,
            max_items=64,
        )
    else:
        compact.pop("producer_intent_authority", None)
    compact["marketing_authorization"] = _prompt_safe_value(
        compact.get("marketing_authorization") or {},
        max_string=520 if visual_stage else 900,
        max_items=10 if visual_stage else 16,
    )
    compact["video_model_policy"] = _prompt_safe_value(
        compact.get("video_model_policy") or {},
        max_string=520 if visual_stage else 900,
        max_items=14 if visual_stage else 24,
    )
    if stage in {"VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS"}:
        compact["project_assets"] = compact.get("browser_assets") or []
    elif stage != "FACTS":
        compact["project_assets"] = _prompt_safe_value(compact.get("project_assets") or [], max_string=400, max_items=12)
    if isinstance(signed_review_media_design, dict):
        review_previous = dict(compact.get("previous_outputs") or {})
        # Generic depth/item compaction is suitable for narrative history but
        # not for the signed reference transport. Restore its deliberately
        # compact, ordered rows after generic compaction so generation_mode and
        # source_asset_refs cannot disappear based on dictionary insertion
        # order.
        review_previous["MEDIA_DESIGN"] = signed_review_media_design
        compact["previous_outputs"] = review_previous
    return compact


def _prepare_stage_packet_for_execution(
    packet: dict[str, Any],
    stage: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Separate bounded provider context from authoritative server validation.

    The text provider only needs a compact sample of prior variants, but the
    output gate must compare a new creative against the complete durable
    history. Returning both views prevents prompt-size compaction from silently
    weakening the server-side duplicate detector.
    """
    authoritative_history = [
        dict(item)
        for item in list(
            packet.get("authoritative_previous_variant_briefs")
            or packet.get("previous_variant_briefs")
            or []
        )
        if isinstance(item, dict)
    ]
    return _compact_packet_for_chatgpt(packet, stage), authoritative_history


def _asset_file_available(asset: HermesContentFactoryAsset) -> bool:
    try:
        path = Path(str(asset.file_path or ""))
    except (TypeError, ValueError):
        return False
    return path.is_file() and path.stat().st_size > 0


def _latest_creative_review_auto_approved(project: HermesContentFactoryProject, db) -> bool:
    stage = db.query(HermesContentFactoryStage).filter_by(
        project_id=project.id, stage="CREATIVE_REVIEW", status="success"
    ).order_by(HermesContentFactoryStage.id.desc()).first()
    if stage is None:
        return False
    envelope = dict(stage.output_json or {})
    result = dict(envelope.get("result") or {})
    evidence = dict(envelope.get("evidence") or {})
    review = str(result.get("creative_review") or "")
    if bool(evidence.get("auto_approved_after_review_loop")):
        return False
    return (
        bool(result.get("approved_for_split"))
        and (
            str(evidence.get("source") or "") == "deterministic_server_fallback"
            or "Server fallback approved" in review
            or bool(evidence.get("auto_accepted_soft_creative_review"))
        )
    )


def _benchmark_video_analysis(project: HermesContentFactoryProject) -> dict[str, Any]:
    state = dict(project.state_json or {})
    analysis = dict(state.get("benchmark_video_analysis") or {})
    if not analysis:
        return {"status": "none"}
    return analysis


def _benchmark_is_structure_only(project: HermesContentFactoryProject) -> bool:
    """Return whether creative models may see only abstract source timing.

    ``inspiration_only`` is intentionally a low-bandwidth creative boundary.
    Giving the Director the source transcript, keyframes, or source analysis
    document after promising a fully regenerated concept makes literal
    imitation the easiest model completion even when the surrounding prompt
    says not to copy it.  The source remains stored for the final originality
    audit; it is simply withheld from creative generation.
    """
    contract = _project_transformation_contract(project)
    return (
        str(contract.get("transfer_mode") or "").strip().lower()
        == "inspiration_only"
        and str(contract.get("source_media_reuse") or "").strip().lower()
        == "forbidden"
    )


def _is_semantic_benchmark_asset(asset: HermesContentFactoryAsset) -> bool:
    """Identify high-bandwidth source semantics, not product authority."""
    meta = dict(asset.meta_json or {})
    kind = str(asset.kind or "").strip().lower()
    role = str(meta.get("asset_role") or "").strip().lower()
    source_kind = str(meta.get("source_kind") or "").strip().lower()
    return bool(
        kind in BENCHMARK_ASSET_KINDS
        or kind == "reference_video"
        or role in {
            "reference_video",
            "benchmark_transcript",
            "benchmark_keyframes",
        }
        or source_kind in {"reference_video", "analysis_report"}
    )


def _benchmark_video_prompt_summary(project: HermesContentFactoryProject) -> dict[str, Any]:
    analysis = dict(_benchmark_video_analysis(project))
    if analysis.get("status") != "success":
        return analysis
    if _benchmark_is_structure_only(project):
        raw_segments = [
            dict(item)
            for item in list(analysis.get("segments") or [])[:240]
            if isinstance(item, dict)
        ]
        timing_windows: list[dict[str, float | int]] = []
        total_spoken_units = 0
        for fallback_index, item in enumerate(raw_segments, 1):
            try:
                start = max(
                    0.0,
                    float(
                        item.get("start_seconds")
                        if item.get("start_seconds") is not None
                        else item.get("start") or 0.0
                    ),
                )
                end = max(
                    start,
                    float(
                        item.get("end_seconds")
                        if item.get("end_seconds") is not None
                        else item.get("end") or start
                    ),
                )
            except (TypeError, ValueError):
                continue
            timing_windows.append({
                "index": int(item.get("index") or fallback_index),
                "start_seconds": round(start, 3),
                "end_seconds": round(end, 3),
            })
            total_spoken_units += len(
                re.findall(r"[A-Za-z0-9']+", str(item.get("text") or ""))
            )
        duration = max(
            0.0,
            float(analysis.get("duration_seconds") or 0.0),
        )
        opening_turn_count = sum(
            1
            for item in timing_windows
            if float(item["start_seconds"]) < 3.0
        )
        return {
            "status": "success",
            "imitation_mode": "inspiration_only",
            "source_asset_id": analysis.get("source_asset_id"),
            "duration_seconds": duration,
            "timing_profile": {
                "cue_count": len(timing_windows),
                "opening_three_second_turn_count": opening_turn_count,
                "average_cue_duration_seconds": round(
                    sum(
                        float(item["end_seconds"])
                        - float(item["start_seconds"])
                        for item in timing_windows
                    )
                    / max(1, len(timing_windows)),
                    3,
                ),
                "spoken_units_per_second": round(
                    total_spoken_units / max(duration, 0.001),
                    3,
                ),
                "cue_windows": timing_windows,
            },
            "semantic_source_withheld": True,
            "withheld_fields": [
                "transcript",
                "subtitle_text",
                "keyframes",
                "source_story",
                "source_roles",
                "source_props",
                "source_shots",
            ],
            "instructions": [
                "Use only the numeric attention and pacing profile.",
                "Invent a materially new premise, narrative device, cast, setting, props, actions, dialogue concept, voice, shots, and audio.",
                "Do not reconstruct source subtitle functions, scene progression, keyframes, platform UI, watermarks, or watermark-covering caption bands.",
            ],
        }
    imitation_mode = benchmark_imitation_mode(
        _project_requirement_text(project),
        has_benchmark=True,
        transformation_contract=_project_transformation_contract(project),
    )
    if imitation_mode == "exact":
        instructions = [
            "This project explicitly requests 1:1 reconstruction.",
            "Map every subtitle cue exactly once in original chronological order and preserve each cue time window, speaker-turn pattern, speech density, and scene function.",
            "Use every chronological keyframe sheet to reconstruct the benchmark setting, shot order, performance style, and edit rhythm.",
            "Keep source wording unless it conflicts with current product truth, confirmed offer, required language, or explicit project requirements; replace only those conflicts without changing timing or sentence function.",
        ]
    else:
        instructions = [
            "This project requests adaptive imitation rather than literal reconstruction.",
            "Follow subtitle cue structure, speech density, hook logic, scene progression, and edit rhythm, but rewrite wording and concrete actions for this project.",
            "Use chronological keyframe sheets as scene/style evidence and make each variant materially different.",
        ]
    return {
        "status": "success",
        "imitation_mode": imitation_mode,
        "source_asset_id": analysis.get("source_asset_id"),
        "duration_seconds": analysis.get("duration_seconds"),
        "detected_language": analysis.get("detected_language"),
        "transcript": str(analysis.get("transcript") or "")[:16000],
        "segments": list(analysis.get("segments") or [])[:120],
        "keyframe_asset_id": analysis.get("keyframe_asset_id"),
        "keyframe_asset_ids": list(analysis.get("keyframe_asset_ids") or [])[:12],
        "keyframe_sheets": list(analysis.get("keyframe_sheets") or [])[:12],
        "srt_asset_id": analysis.get("srt_asset_id"),
        # This is the pixel-grounded semantic bridge from the source video to
        # the Director.  File paths and a transcript alone cannot preserve an
        # opening's visual abnormality, ordered escalation, or edit grammar.
        "visual_semantic_analysis": dict(
            analysis.get("visual_semantic_analysis") or {}
        ),
        "instructions": instructions,
    }


def _benchmark_visual_director_evidence(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Return the bounded pixel-derived evidence creative roles may execute."""
    summary = dict(_benchmark_video_prompt_summary(project))
    if summary.get("status") != "success":
        return {}
    if bool(summary.get("semantic_source_withheld")):
        return {
            "status": "success",
            "imitation_mode": summary.get("imitation_mode"),
            "duration_seconds": summary.get("duration_seconds"),
            "timing_profile": dict(summary.get("timing_profile") or {}),
            "semantic_source_withheld": True,
        }
    semantic = dict(summary.get("visual_semantic_analysis") or {})
    if semantic.get("status") != "success":
        return {}
    return {
        "status": "success",
        "imitation_mode": summary.get("imitation_mode"),
        "duration_seconds": summary.get("duration_seconds"),
        "visual_semantic_analysis": semantic,
        "authority": "ordered_source_contact_sheets_multimodal_analysis",
        "instruction": (
            "Transfer only the authorized abstract hook, pacing, progression, "
            "and conversion mechanics. Do not copy any item under must_not_copy."
        ),
    }


def _benchmark_opening_hook_contract(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Return signed hook authority plus multimodal evidence for AI review.

    Source analysis is evidence, not a contract.  Historical code converted
    its suggested state count into a fixed minimum reference count and could
    therefore require a capability-reversal device that the Producer had
    explicitly excluded.  Keep the evidence rich, but let the independent
    model judge only the user's signed observable checks.
    """
    requirement = _project_requirement_text(project)
    if not re.search(
        r"\bhook\b|opening.{0,20}(?:impact|attention|visual)|first\s*[23]\s*seconds?|"
        r"前\s*[23]\s*秒|视觉钩子|开头.{0,12}(?:冲击|抓|吸引|钩子)",
        requirement,
        flags=re.IGNORECASE,
    ):
        return {}
    evidence = _benchmark_visual_director_evidence(project)
    semantic = dict(evidence.get("visual_semantic_analysis") or {})
    opening = dict(semantic.get("opening_hook") or {})
    states = [
        dict(item)
        for item in list(opening.get("ordered_states") or [])
        if isinstance(item, dict)
    ]
    if not states:
        return {}
    intent_authority = _project_intent_authority(project)
    signed_requirements = [
        dict(item)
        for item in list(intent_authority.get("requirements") or [])
        if isinstance(item, dict)
        and str(item.get("kind") or "").strip().lower()
        == "reference_transfer"
    ]
    has_signed_authority = bool(
        str(intent_authority.get("manifest_sha256") or "").strip()
        or list(intent_authority.get("requirements") or [])
        or dict(intent_authority.get("transformation_contract") or {})
    )
    if has_signed_authority and not signed_requirements:
        return {}
    return {
        "multimodal_opening_evidence": {
            **opening,
            "ordered_states": states[:8],
            "must_transfer_suggestions": list(
                semantic.get("must_transfer") or []
            )[:16],
            "must_not_copy": list(
                semantic.get("must_not_copy") or []
            )[:16],
        },
        "signed_reference_transfer_requirements": signed_requirements,
        "signed_transformation_contract": dict(
            intent_authority.get("transformation_contract") or {}
        ),
        "authority_rule": (
            "Judge only observable_checks and transformation success_checks. "
            "Benchmark states and must_transfer suggestions are evidence, not "
            "additional requirements. must_not_reuse and excluded_source_artifacts "
            "always win. The AI Critic chooses the smallest sufficient reference "
            "topology; no server-owned reference count is mandatory."
        ),
        "policy_version": semantic.get("policy_version"),
    }


def _benchmark_video_assets(assets: list[HermesContentFactoryAsset]) -> list[HermesContentFactoryAsset]:
    return [
        asset for asset in assets
        if asset.kind in BENCHMARK_ASSET_KINDS
        and str(asset.stage or "").upper() == BENCHMARK_VIDEO_STAGE
    ]


def _browser_stage_output_path(project, stage_row, variant_index: int) -> Path:
    return (
        BROWSER_OUTBOX_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
        / stage_row.stage
        / f"variant_{int(variant_index):02d}"
        / f"execution_{int(stage_row.id)}_{int(stage_row.attempt or 1)}"
    )


def _creative_review_reference_asset_status(
    creative_output: dict[str, Any],
    preview_assets: list[HermesContentFactoryAsset],
) -> dict[str, Any]:
    """Describe whether every planned reference is locally reviewable.

    Product source images are intentionally not accepted here: they establish
    package authority but cannot replace a missing generated story reference.
    Older composite boards may cover a range; individual API images normally
    cover exactly one reference index.
    """
    ticket = dict(dict(creative_output or {}).get("visual_job_ticket") or {})
    plan = [
        dict(item)
        for item in list(ticket.get("reference_plan") or [])
        if isinstance(item, dict)
    ]
    expected_count = _authoritative_reference_count(
        creative_output,
        default=max(1, len(plan) or 4),
    )
    expected_indices = set(range(1, expected_count + 1))
    covered_indices: set[int] = set()
    available_asset_ids: list[int] = []
    for asset in list(preview_assets or []):
        if not _asset_file_available(asset):
            continue
        meta = dict(asset.meta_json or {})
        try:
            start = int(
                meta.get("global_start_index")
                or meta.get("reference_index")
                or _visual_asset_reference_index(asset)
                or 0
            )
        except (TypeError, ValueError):
            start = 0
        try:
            end = int(meta.get("global_end_index") or start or 0)
        except (TypeError, ValueError):
            end = start
        if start > 0:
            explicit_indices = {
                int(value)
                for value in list(meta.get("global_reference_indices") or [])
                if str(value).strip().isdigit()
                and 1 <= int(value) <= expected_count
            }
            if explicit_indices:
                covered_indices.update(explicit_indices)
            else:
                covered_indices.update(
                    range(max(1, start), min(expected_count, max(start, end)) + 1)
                )
        elif len(preview_assets) == 1:
            try:
                panel_count = int(
                    meta.get("expected_panels")
                    or meta.get("reference_count")
                    or 0
                )
            except (TypeError, ValueError):
                panel_count = 0
            if panel_count >= expected_count:
                covered_indices.update(expected_indices)
        if int(asset.id or 0) > 0:
            available_asset_ids.append(int(asset.id))
    missing_indices = sorted(expected_indices - covered_indices)
    return {
        "complete": not missing_indices,
        "expected_count": expected_count,
        "covered_indices": sorted(covered_indices),
        "missing_indices": missing_indices,
        "asset_ids": available_asset_ids,
    }


def _creative_review_uses_native_reference_files(
    preview_assets: list[HermesContentFactoryAsset],
    reference_status: dict[str, Any],
) -> bool:
    """Describe the files actually sent to the multimodal reviewer.

    Board-mode generation is split locally into one native file per signed
    row before review.  The review contract must follow that transport shape,
    not the image provider's earlier generation mode; otherwise the model
    interprets four independent references as four boards and invents panel
    topology/count failures.
    """

    if not bool(reference_status.get("complete")):
        return False
    try:
        expected_count = int(reference_status.get("expected_count") or 0)
    except (TypeError, ValueError):
        return False
    if expected_count <= 0 or len(preview_assets) != expected_count:
        return False
    observed: set[int] = set()
    for asset in preview_assets:
        if not _asset_file_available(asset):
            return False
        meta = dict(asset.meta_json or {})
        try:
            index = int(
                meta.get("reference_index")
                or meta.get("global_start_index")
                or _visual_asset_reference_index(asset)
                or 0
            )
            start = int(meta.get("global_start_index") or index or 0)
            end = int(meta.get("global_end_index") or start or 0)
            panel_count = int(meta.get("expected_panels") or 1)
        except (TypeError, ValueError):
            return False
        if index <= 0 or start != index or end != index or panel_count != 1:
            return False
        observed.add(index)
    return observed == set(range(1, expected_count + 1))


def _stage_packet(
    db,
    project,
    stage_row,
    *,
    prepare_browser: bool = True,
) -> dict[str, Any]:
    prior = (
        db.query(HermesContentFactoryStage)
        .filter(HermesContentFactoryStage.project_id == project.id, HermesContentFactoryStage.status == "success")
        .order_by(HermesContentFactoryStage.id.asc()).all()
    )
    all_assets = db.query(HermesContentFactoryAsset).filter(HermesContentFactoryAsset.project_id == project.id).order_by(HermesContentFactoryAsset.id.asc()).all()
    for asset in all_assets:
        _set_asset_role(asset)
    all_assets = [asset for asset in all_assets if _asset_file_available(asset)]
    if _benchmark_is_structure_only(project):
        # Keep the source files in project storage for the post-generation
        # originality audit, but never upload or enumerate their semantic
        # content to the creative roles. Stable product facts and the uploaded
        # package remain available because they are not benchmark assets.
        all_assets = [
            asset for asset in all_assets
            if not _is_semantic_benchmark_asset(asset)
        ]
    assets = list(all_assets)
    review_uses_native_reference_files = False
    config = dict(project.config_json or {})
    variant_index = _stage_variant_index(stage_row, project)
    variant_total = _target_video_count(project)
    sequential_variants = _sequential_variants_enabled(project)
    video_policy = _video_model_policy(project)
    effective_learning = _effective_hermes_learning(db, project)
    marketing_authorization = _marketing_authorization(project)
    creative_copy_contract = _creative_copy_contract(
        project,
        marketing_authorization,
    )
    creative_cast_policy = _creative_cast_policy(project)
    product_presentation_policy = _product_presentation_policy(project)
    benchmark_video_analysis = _benchmark_video_prompt_summary(project)
    previous_outputs = _compact_previous_outputs(
        prior,
        stage_row.stage,
        variant_index=variant_index if sequential_variants else None,
    )
    if stage_row.stage == "FACTS":
        assets = [
            asset for asset in assets
            if asset.kind == "source" and not _is_promotion_asset(asset)
        ]
    elif stage_row.stage == "VISUAL_PREVIEW":
        character_reference_assets = [
            asset for asset in assets
            if asset.kind == "character_reference"
            and str(asset.mime_type or "").startswith("image/")
        ]
        product_reference_assets = [
            asset for asset in assets
            if asset.kind == "source"
            and _asset_role(asset) == "product_visual"
            and str(asset.mime_type or "").startswith("image/")
        ]
        # The signed Production Plan is the source of truth for visual
        # reference policy. Rebuild the compiled media design here too so the
        # prompt and uploaded references share the same immutable contract.
        # Updating previous_outputs ensures the API prompt and its uploaded
        # references are driven by the same repaired plan.
        creative_output = dict(previous_outputs.get("MEDIA_DESIGN") or {})
        # Prompt compaction deliberately omits the full script from the
        # VISUAL_PREVIEW packet. The worker, however, needs that authoritative
        # segment action to decide whether the real product image must be sent
        # to the image model. Recover only this small server-side contract;
        # never expand the browser/model-facing context with unrelated output.
        full_creative = _successful_media_design_for_variant(
            db,
            project,
            variant_index=variant_index,
        )
        complete_script = dict(
            full_creative.get("complete_video_script") or {}
        )
        if complete_script:
            creative_output["complete_video_script"] = complete_script
        # VISUAL_PREVIEW must receive the concrete per-segment still state,
        # not only the abstract reference-purpose rows retained by prompt
        # compaction. Restore this small authoritative field from the exact
        # variant's signed Production Plan.
        if isinstance(full_creative.get("shot_plan"), list):
            creative_output["shot_plan"] = list(
                full_creative["shot_plan"]
            )
        creative_output = _reference_contract_for_media_execution(
            creative_output,
            product_allowed=_project_uses_product(project),
        )
        previous_outputs["MEDIA_DESIGN"] = creative_output
        visual_ticket = dict(creative_output.get("visual_job_ticket") or {})
        visual_plan = list(visual_ticket.get("reference_plan") or [])
        needs_product_reference = _project_uses_product(project) and _visual_plan_needs_product_reference(visual_plan)
        # Product references may guide scripted interaction keyframes, but the
        # original upload remains the separate downstream package authority.
        # Ingredient/fact images are deliberately excluded.
        assets = character_reference_assets[:3]
        if needs_product_reference:
            assets += product_reference_assets[:2]
    elif stage_row.stage == "CREATIVE_REVIEW":
        # Review the same server-compiled static reference contract that the
        # image model received.  The persisted creative response may still
        # contain video-camera motion in reference_plan; exposing that raw
        # timeline made a still-image reviewer demand proof that a prop was
        # "rolling into frame".  Motion remains authoritative only in
        # complete_video_script.
        creative_output = dict(previous_outputs.get("MEDIA_DESIGN") or {})
        full_creative = _successful_media_design_for_variant(
            db,
            project,
            variant_index=variant_index,
        )
        if full_creative:
            creative_output.update(full_creative)
        previous_outputs["MEDIA_DESIGN"] = _reference_contract_for_media_execution(
            creative_output,
            product_allowed=_project_uses_product(project),
        )
        preview_assets = [
            asset for asset in assets
            if asset.stage == "VISUAL_PREVIEW" and str(asset.mime_type or "").startswith("image/")
            and str(
                dict(asset.meta_json or {}).get("capture_origin") or ""
            ).strip().lower() != "generated_scene_precomposite"
            and not bool(
                dict(asset.meta_json or {}).get(
                    "superseded_by_authoritative_composite_asset_id"
                )
            )
            and (
                not sequential_variants
                or int(dict(asset.meta_json or {}).get("variant_index") or 1) == variant_index
            )
        ]
        indexed_preview_assets: dict[int, HermesContentFactoryAsset] = {}
        unindexed_preview_assets: list[HermesContentFactoryAsset] = []
        for asset in preview_assets:
            reference_index = _visual_asset_reference_index(asset)
            if reference_index > 0:
                indexed_preview_assets[reference_index] = asset
            else:
                unindexed_preview_assets.append(asset)
        if indexed_preview_assets:
            preview_assets = [
                indexed_preview_assets[index]
                for index in sorted(indexed_preview_assets)
            ]
        else:
            preview_assets = unindexed_preview_assets
        reference_status = _creative_review_reference_asset_status(
            previous_outputs["MEDIA_DESIGN"],
            preview_assets,
        )
        if not bool(reference_status["complete"]):
            recovered_assets = _recover_visual_preview_assets_from_stage(db, project)
            if recovered_assets:
                preview_assets = list(preview_assets) + list(recovered_assets)
                indexed_preview_assets = {}
                unindexed_preview_assets = []
                for asset in preview_assets:
                    reference_index = _visual_asset_reference_index(asset)
                    if reference_index > 0:
                        indexed_preview_assets[reference_index] = asset
                    else:
                        unindexed_preview_assets.append(asset)
                preview_assets = (
                    [
                        indexed_preview_assets[index]
                        for index in sorted(indexed_preview_assets)
                    ]
                    if indexed_preview_assets
                    else unindexed_preview_assets
                )
                reference_status = _creative_review_reference_asset_status(
                    previous_outputs["MEDIA_DESIGN"],
                    preview_assets,
                )
        if not bool(reference_status["complete"]):
            raise _CreativeReviewReferencesIncomplete(
                "CREATIVE_REVIEW_REFERENCE_ASSETS_INCOMPLETE: "
                + json.dumps(reference_status, ensure_ascii=False, sort_keys=True)
            )
        review_uses_native_reference_files = (
            _creative_review_uses_native_reference_files(
                preview_assets,
                reference_status,
            )
        )
        # The generated board is reviewed as an action/composition reference,
        # not as a replacement package photo.  Upload the original product
        # visual alongside it so the reviewer understands that the exact
        # package remains a separate downstream video anchor.  This avoids
        # wasting regeneration attempts on tiny AI-rendered label text.
        product_reference_assets = [
            asset for asset in all_assets
            if asset.kind == "source"
            and _asset_role(asset) == "product_visual"
            and str(asset.mime_type or "").startswith("image/")
        ]
        # Benchmark frames have already been interpreted by Producer and
        # Director before a Production Plan is signed. Re-attaching the raw
        # source frames here gives the visual reviewer two competing creative
        # authorities: the approved reference plan and the old source story.
        # CREATIVE_REVIEW owns rendered-plan conformance only: generated
        # references plus the separate authoritative package image.
        assets = preview_assets + product_reference_assets[:1]
        benchmark_video_analysis = {}
    elif stage_row.stage == "FINAL_ASSETS":
        assets = [
            asset for asset in assets
            if asset.stage == "VISUAL_PREVIEW" and str(asset.mime_type or "").startswith("image/")
            and (
                not sequential_variants
                or int(dict(asset.meta_json or {}).get("variant_index") or 1) == variant_index
            )
        ]
    elif stage_row.stage == "VIDEO_PROMPTS":
        final_images = [
            asset for asset in assets
            if asset.stage == "FINAL_ASSETS" and str(asset.mime_type or "").startswith("image/")
            and (
                not sequential_variants
                or int(dict(asset.meta_json or {}).get("variant_index") or 1) == variant_index
            )
        ]
        reference_videos = [
            asset for asset in assets
            if asset.kind == "reference_video" and str(asset.mime_type or "").startswith("video/")
        ][:int(video_policy["reference_video_limit"])]
        image_limit = max(1, int(video_policy["reference_limit"]))
        # VIDEO_PROMPTS reference_indices are defined against FINAL_ASSETS only.
        # The original package image is appended later by the server as the sole
        # product authority. Uploading it here shifted every ChatGPT index by one
        # and made @image bindings point at the wrong files downstream.
        selected_images = final_images[-image_limit:]
        assets = selected_images[:image_limit] + reference_videos
    elif stage_row.stage == "EDIT_PACKAGE":
        # Publishing copy is derived from the approved plan and completed-video
        # manifest. Uploading every PDF/image/video bloats ChatGPT context and
        # is the main cause of truncated one-character responses.
        assets = []
    video_assets = [
        {
            "name": asset.original_name,
            "local_path": asset.file_path,
            "remote_url": dict(asset.meta_json or {}).get("remote_url"),
            "kie_task_id": dict(asset.meta_json or {}).get("kie_task_id"),
        }
        for asset in db.query(HermesContentFactoryAsset).filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.kind == "video",
        ).order_by(HermesContentFactoryAsset.id.asc()).all()
    ] if stage_row.stage == "EDIT_PACKAGE" else []
    product_knowledge = _product_knowledge_result(project)
    stage_input = dict(stage_row.input_json or {})
    production_plan_external_repair = bool(
        stage_input.get("production_plan_external_repair")
    )
    if production_plan_external_repair:
        latest_director_stage_id = db.query(
            func.max(HermesContentFactoryStage.id)
        ).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "DIRECTOR",
            HermesContentFactoryStage.status == "success",
        ).scalar()
        latest_successful_plan_stage_id = db.query(
            func.max(HermesContentFactoryStage.id)
        ).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "PRODUCTION_PLAN",
            HermesContentFactoryStage.status == "success",
        ).scalar()
        from app.services.hermes_agent.content_factory import (
            _production_plan_repair_matches_current_director_generation,
        )

        production_plan_external_repair = (
            _production_plan_repair_matches_current_director_generation(
                latest_director_stage_id=latest_director_stage_id,
                latest_successful_plan_stage_id=(
                    latest_successful_plan_stage_id
                ),
            )
        )
        if not production_plan_external_repair:
            # Persist the generation correction so periodic self-heal does not
            # keep replaying a stale external-repair marker from before the
            # newer Director artifact was accepted.
            stage_input["production_plan_external_repair"] = False
            stage_input.pop("production_plan_repair_instruction", None)
            stage_input["self_heal_action"] = (
                "generate_fresh_plan_for_new_director_generation"
            )
            stage_row.input_json = stage_input
            db.flush()
    # A project must stay on its assigned browser slot for the whole pipeline.
    # Prefer the locked routing stored on the stage; recomputing after restarts
    # can point a slot2 project at slot0 and make valid ChatGPT replies vanish.
    if prepare_browser:
        browser_slot, browser_cdp_url, queue_name = _locked_browser_routing(db, project, stage_input)
        stage_input["browser_slot"] = browser_slot
        stage_input["browser_cdp_url"] = browser_cdp_url
        stage_input["queue"] = queue_name
        stage_row.input_json = stage_input
        db.flush()
        assets = _sync_stage_assets_to_browser_inbox(db, project, assets)
    else:
        browser_slot = str(stage_input.get("browser_slot") or "")
        browser_cdp_url = ""
        queue_name = str(stage_input.get("queue") or project_hermes_queue(project))
    browser_upload_assets: list[Any] = list(assets)
    browser_upload_mode = "individual_files"
    reference_sheet_spec = _browser_reference_sheet_spec(
        stage_row.stage,
        variant_index=variant_index,
    )
    browser_upload_note = "Each listed browser asset is uploaded individually in manifest order."
    if prepare_browser and reference_sheet_spec is not None:
        image_assets = [asset for asset in assets if str(asset.mime_type or "").startswith("image/")]
        other_assets = [asset for asset in assets if asset not in image_assets]
        if len(image_assets) > 3:
            sheet_name, browser_upload_note = reference_sheet_spec
            sheet_path = (
                BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}"
                / project.project_key / sheet_name
            )
            _render_video_prompt_reference_sheet(image_assets, sheet_path)
            browser_upload_assets = [
                SimpleNamespace(
                    id=0,
                    meta_json={
                        "bridge_path": str(sheet_path),
                        "browser_inbox_relative": (
                            f"workspace_{project.workspace_id}/{project.project_key}/{sheet_name}"
                        ),
                    },
                    original_name=sheet_name,
                    file_path=str(sheet_path),
                    size_bytes=sheet_path.stat().st_size,
                    mime_type="image/jpeg",
                    kind="internal_reference_sheet",
                    stage="VIDEO_PROMPTS",
                )
            ] + other_assets
            browser_upload_mode = "indexed_reference_contact_sheet"
    if prepare_browser:
        _wait_for_browser_inbox_sync(
            db,
            project=project,
            stage_input=stage_input,
            assets=browser_upload_assets,
        )
    if stage_row.stage != "FACTS" and product_knowledge and "FACTS" not in previous_outputs:
        previous_outputs["FACTS"] = product_knowledge
    def browser_asset_path(asset: HermesContentFactoryAsset) -> str | None:
        meta = dict(asset.meta_json or {})
        bridge_path = str(meta.get("bridge_path") or "").strip()
        inbox_root = str(stage_input.get("browser_inbox_root") or dict(project.state_json or {}).get("browser_inbox_root") or "").strip()
        if inbox_root and bridge_path:
            try:
                # The bridge agent manifest is rooted at the current
                # workspace directory and writes files directly below the
                # user's HermesInbox. Including "workspace_N" here points
                # Chrome at a path the agent never created.
                workspace_root = BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}"
                relative = Path(bridge_path).resolve().relative_to(workspace_root.resolve())
                separator = "\\" if "\\" in inbox_root or ":" in inbox_root else "/"
                return inbox_root.rstrip("\\/") + separator + str(relative).replace("/", separator).replace("\\", separator)
            except Exception:
                pass
        return None

    browser_paths = (
        [path for path in (browser_asset_path(asset) for asset in browser_upload_assets) if path]
        if prepare_browser
        else [str(asset.file_path) for asset in browser_upload_assets if _asset_file_available(asset)]
    )
    if prepare_browser and browser_upload_assets and len(browser_paths) != len(browser_upload_assets):
        missing = [
            str(asset.original_name or asset.file_path or asset.id)
            for asset in browser_upload_assets
            if not browser_asset_path(asset)
        ]
        raise ValueError(
            "BROWSER_INBOX_SYNC_INCOMPLETE: current user's browser bridge has not synced upload files; "
            f"missing={missing[:8]}"
        )
    return {
        "project_id": project.project_key,
        "execution_id": (
            f"{project.project_key}:{int(stage_row.id)}:"
            f"{int(stage_row.attempt or 1)}:v{int(variant_index):02d}"
        ),
        "content_mode": str(config.get("content_mode") or "general"),
        "product_required": _project_uses_product(project),
        "product": project.product_name if _project_uses_product(project) else None,
        "market": project.market,
        "brief": project.product_brief,
        "current_stage": stage_row.stage,
        "user_instruction": stage_row.instruction,
        "gpt_url": ROLE_URLS[stage_row.stage],
        "browser_slot": browser_slot,
        "browser_cdp_url": browser_cdp_url,
        "browser_bridge_id": str(stage_input.get("browser_bridge_id") or browser_slot),
        "browser_device_id": str(stage_input.get("browser_device_id") or ""),
        "browser_device_name": str(stage_input.get("browser_device_name") or ""),
        "browser_inbox_root": str(stage_input.get("browser_inbox_root") or ""),
        "browser_asset_paths": browser_paths,
        "browser_assets": _asset_manifest(assets),
        "browser_upload_mode": browser_upload_mode,
        "browser_upload_note": browser_upload_note,
        "project_assets": [] if stage_row.stage == "EDIT_PACKAGE" else _asset_manifest(all_assets),
        # Browser media is scoped to one variant and one immutable stage
        # execution. A repair stage must never reuse half of a board set from
        # the rejected execution that created it.
        "browser_output_path": str(_browser_stage_output_path(project, stage_row, variant_index)),
        "force_fresh_response": bool(stage_input.get("force_fresh_response", False)),
        # A semantic validation failure means the provider returned a complete
        # but unusable answer.  It is a new logical generation, unlike a
        # transport retry of an ambiguous request, and must therefore get a
        # distinct API idempotency identity.
        "api_regeneration_generation": int(stage_input.get("api_regeneration_generation") or 0),
        "semantic_validation_last_error": str(
            stage_input.get("semantic_validation_last_error") or ""
        )[:1200],
        "semantic_api_retry_count": int(
            stage_input.get("semantic_api_retry_count") or 0
        ),
        # A locally rejected complete API response may be retried through the
        # alternate commercial model. Keep this route decision in the stage
        # packet so it survives broker and worker restarts.
        "text_api_prefer_alternate_model": bool(
            stage_input.get("text_api_prefer_alternate_model", False)
        ),
        "allow_visible_visual_recovery": bool(stage_input.get("allow_visible_visual_recovery", False)),
        "self_heal_action": str(stage_input.get("self_heal_action") or ""),
        "self_heal_reason": str(stage_input.get("self_heal_reason") or ""),
        "visual_repair_instruction": str(stage_input.get("visual_repair_instruction") or ""),
        "visual_repair_failed_indices": list(
            stage_input.get("visual_repair_failed_indices") or []
        ),
        "visual_repair_preserved_references": list(
            stage_input.get("visual_repair_preserved_references") or []
        ),
        "visual_repair_continuity_anchor_indices": list(
            stage_input.get("visual_repair_continuity_anchor_indices") or []
        ),
        "visual_repair_source_review_stage_id": int(
            stage_input.get("visual_repair_source_review_stage_id") or 0
        ),
        "knowledge_namespace": f"workspace_{project.workspace_id}/{project.project_key}",
        "video_count": 1 if sequential_variants and stage_row.stage in VARIANT_STAGES else variant_total,
        "video_variant_index": variant_index,
        "video_variant_total": variant_total,
        "video_variant_mode": "serial_one_complete_video_at_a_time" if sequential_variants else "single_batch",
        # Reference packaging is a project-owned production choice. Boards
        # reduce paid image calls and lock cast/location/style on one canvas;
        # individual mode remains available for projects that need isolated
        # per-frame repair. Hermes validates and splits either representation.
        "visual_reference_generation_mode": str(
            config.get("visual_reference_generation_mode") or "board"
        ).strip().lower(),
        "render_reference_images_individually": (
            review_uses_native_reference_files
            if stage_row.stage == "CREATIVE_REVIEW"
            else str(
                config.get("visual_reference_generation_mode") or "board"
            ).strip().lower() != "board"
        ),
        "visual_image_model_chain": list(
            config.get("visual_image_model_chain")
            or ["gpt-image-2", "nano_banana_pro"]
        ),
        "visual_image_model_index": max(
            0,
            int(stage_input.get("visual_image_model_index") or 0),
        ),
        "video_duration_range_seconds": _configured_video_duration_range(project),
        "recommended_video_duration_seconds": _configured_video_duration(project),
        "video_segment_durations_seconds": _segment_durations_for_project(project),
        "video_segment_count": len(_segment_durations_for_project(project)),
        "video_model": video_policy["id"],
        "video_reference_limit": video_policy["reference_limit"],
        "video_reference_video_limit": video_policy["reference_video_limit"],
        "video_resolution": _configured_video_resolution(project),
        "video_aspect_ratio": _configured_video_aspect_ratio(project),
        "video_language": _configured_video_language(project),
        "video_language_label": _video_language_label(project),
        "video_model_policy": video_policy,
        "marketing_authorization": marketing_authorization,
        "creative_copy_contract": creative_copy_contract,
        "creative_cast_policy": creative_cast_policy,
        "product_presentation_policy": product_presentation_policy,
        "benchmark_video_analysis": benchmark_video_analysis,
        "learned_constraints": effective_learning,
        "auto_run": bool(config.get("auto_run", True)),
        "project_state": _compact_project_state_for_prompt(dict(project.state_json or {}), stage_row.stage),
        "product_facts_source": dict(project.state_json or {}).get("product_facts_source") or (
            ("library" if product_knowledge else "stage")
            if _project_uses_product(project)
            else "not_applicable"
        ),
        "project_requirements": _project_requirement_text(project),
        "producer_intent_authority": _project_intent_authority(project),
        "visual_style_requirement": _project_visual_style_requirement(project),
        "product_facts_rules": [
            "Product facts must cover only stable product identity, packaging, label-visible facts, confirmed ingredient/fact panels, approved claims, banned claims, visual invariants, and usage constraints.",
            "Do not include promotions, coupons, discount percentages, prices, limited-time offers, new-customer CTAs, campaign names, or stackability rules in product facts.",
            "If directions, warnings, dosage, daily maximum, contraindications, allergen details, or substantiation are missing, record them as unconfirmed constraints in prohibited_claims/application_rules; do not fail the product facts stage solely because they are missing.",
            "If product naming conflicts exist, choose the uploaded package label as display_name and preserve aliases in product_passport; do not fail solely because of an alias conflict.",
        ] if stage_row.stage == "FACTS" else [],
        "video_evidence": video_assets,
        "previous_outputs": previous_outputs,
        "required_result_fields": REQUIRED_FIELDS[stage_row.stage],
        "required_next_stage": _configured_next_stage(project, stage_row.stage),
    }


def _creative_spoken_copy_budget_contract(packet: dict[str, Any]) -> str:
    """Keep API and browser creative prompts on one timing contract."""
    return creative_spoken_copy_budget_contract(packet)


def _build_prompt(db, project, stage_row) -> str:
    packet = _stage_packet(db, project, stage_row)
    packet = _compact_packet_for_chatgpt(packet, stage_row.stage)
    policy = packet.get("video_model_policy") or {}
    hard_rules = "\n".join(f"- {rule}" for rule in list(policy.get("hard_rules") or []))
    duration_note = (
        "Choose a complete-video duration inside video_duration_range_seconds. "
        "Use recommended_video_duration_seconds unless the creative story clearly needs a nearby duration. "
        "Each complete video must use exactly video_segment_durations_seconds and preserve strict continuity across segments."
    )
    model_note = f"\n\nVIDEO MODEL HARD RULES:\n{hard_rules}\n- {duration_note}" if hard_rules else f"\n\n- {duration_note}"
    stage_rules = ""
    product_required = bool(packet.get("product_required"))
    creative_copy_contract = dict(packet.get("creative_copy_contract") or {})
    creative_cast_policy = dict(packet.get("creative_cast_policy") or {})
    product_presentation_policy = dict(
        packet.get("product_presentation_policy") or {}
    )
    video_aspect_ratio = str(packet.get("video_aspect_ratio") or "9:16")
    adult_cast_rule = (
        "- CREATIVE CAST POLICY: "
        + json.dumps(
            creative_cast_policy,
            ensure_ascii=False,
            separators=(",", ":"),
        )
        + ". Obey it exactly and do not invent additional age, relationship, "
        "speaker-count, or character-count restrictions.\n"
        if creative_cast_policy
        else ""
    )
    product_presentation_rule = (
        "- PRODUCT PRESENTATION POLICY: "
        + json.dumps(
            product_presentation_policy,
            ensure_ascii=False,
            separators=(",", ":"),
        )
        + ". Obey it exactly and do not infer a product form, dosage, "
        "interaction, or package state that the project did not configure.\n"
        if product_required
        else ""
    )
    if stage_row.stage == "VISUAL_PREVIEW":
        visual_product_rule = (
            "- For a scripted product-visible keyframe, use the attached product_visual as authoritative product identity and render it naturally in the described scene with coherent lighting, perspective, contact, occlusion, and hand interaction.\n"
            "- Preserve package type, silhouette, closure shape/mechanism, cap color, dominant colors, brand identity, primary label, and proportions. Minor illegibility is allowed for genuinely tiny secondary label copy. Missing, softened, or unreadable secondary tamper-seal wording on an otherwise matching closure is non-blocking. Never invent prominent words, logos, bands, seals, or printed graphics on the cap/closure or package surface when they are absent from product_visual. Reject a materially different closure shape/mechanism, invented prominent package text or graphics, redesign, substitution, gross deformation, duplication, a pasted source rectangle, visible white source background, standalone packshot, label study, sales card, or placeholder.\n"
            "- Follow PRODUCT PRESENTATION POLICY for package handling and interaction boundaries.\n"
            if product_required
            else "- This project does not require a product. The whole board must remain product-free: no package, bottle, label, logo, offer, sales card, shopping UI, or product placeholder.\n"
        )
        stage_rules = (
            "\n\nBOARD GENERATION CONTRACT:\n"
            "- Follow MEDIA_DESIGN.visual_job_ticket.reference_plan in exact global chronological order. If the plan exceeds seven panels, generate the requested numbered board sequence with no more than seven panels per board; never squeeze the whole plan into one unreadable board.\n"
            "- Every board must state its board_index/board_count in the response manifest, and its panels must continue global ordering without omissions or duplicates.\n"
            "- Use a regular grid with clear straight bright gutters from edge to edge so the server can detect rows and columns.\n"
            "- Do not place borders, nested frames, labels, numbers, captions, or picture-in-picture inside any panel.\n"
            "- Preserve the exact same fictional characters, wardrobe, room layout, lighting, and camera side across all panels.\n"
            + visual_product_rule + product_presentation_rule + adult_cast_rule +
            "\n- If browser_assets contains role/kind character_reference, use those uploaded images only as appearance, age-range, hairstyle, and wardrobe inspiration for the fictional character design.\n"
            "- Do not copy the character_reference file itself into preview_canvas, asset_manifest, FINAL_ASSETS, or VIDEO_PROMPTS. The video pipeline must use only ChatGPT-generated visual preview/final reference images after this stage.\n"
            "- browser_assets may contain product_visual as package identity authority for the product-visible scene and downstream video model."
        )
    elif stage_row.stage == "CREATIVE_REVIEW":
        review_product_rule = (
            "- Review a product-visible reference against the separate original uploaded product_visual identity authority; the source is not a storyboard row and must not be counted as one.\n"
            "- Accept minor illegibility in genuinely tiny secondary label copy when package type, silhouette, closure shape/mechanism, cap color, dominant colors, brand identity, primary label, and proportions remain recognizably correct. Missing, softened, or unreadable secondary tamper-seal wording on an otherwise matching closure is non-blocking. This tolerance never covers prominent invented words, logos, bands, seals, or graphics on the cap/closure or package.\n"
            "- Reject a materially different closure shape/mechanism, invented prominent package text or graphics, missing or wrong product, gross deformation, duplicate, pasted rectangle, visible white source background, standalone packshot, physically implausible placement or interaction, wrong scene/action, or missing product_visual. Ask repairs to regenerate only the failed product scene from the same authority.\n"
            "- Apply PRODUCT PRESENTATION POLICY exactly; do not invent a product form or interaction requirement.\n"
            if product_required
            else "- Reject any advertised product, package, label, logo, offer, shopping UI, or sales card because this project does not require a product.\n"
        )
        if bool(packet.get("render_reference_images_individually")):
            # Short segmented product videos deliberately render one native
            # target-aspect image per reference-plan row. Treating those files as
            # an absent collage caused the reviewer to request a new board,
            # discarding valid API work and reintroducing the very multi-panel
            # failure this mode prevents.
            stage_rules = (
                "\n\nINDIVIDUAL NATIVE REFERENCE REVIEW CONTRACT:\n"
                + review_product_rule + product_presentation_rule + adult_cast_rule +
                f"- browser_assets contains one independently rendered native {video_aspect_ratio} reference image for each MEDIA_DESIGN.visual_job_ticket.reference_plan row, in exact global chronological order. These files are NOT a storyboard board, collage, grid, split screen, or panel set; do not require gutters, separators, or multiple panels within any one image.\n"
                "- Review each image against its corresponding reference-plan row: required configured character, illustrated medium when requested, scene, single still action, continuity, and for a product-visible row a naturally rendered product matching the separately attached product_visual authority.\n"
                "- The first reference is also the pixel-grounded opening-hook gate. Compare it with the approved opening mechanism, visual grammar, first beat, camera composition, and generation brief. Reject it when it merely contains named props but visibly flattens a designed disruption, surprise, contrast, expressive reaction, scale, motion cue, or information-density hook into a generic establishing frame. Record that loss in missing_or_wrong_facts and request only the affected native replacement image. Never demand copied source-video pixels, roles, story premises, dialogue conceits, watermark-cover overlays, captions, search bars, or platform UI.\n"
                "- These files are controllable input anchors for a video model, not final edited-video screenshots. Set terminal_action_verdict=match when the still contains the correct configured character, scene, essential action prop, and a coherent immediately animatable starting or adjacent pose from which the segment prompt can perform the planned motion. Reject only a missing/wrong configured character, scene, essential action prop, contradictory action, or unrelated pose that cannot guide the planned segment.\n"
                "- Do not require the exact final hand position, exact fold degree, optional secondary prop, or two moments of one action to coexist in one still. Treat those as non-blocking degree/state differences when the frame remains an immediately animatable adjacent pose.\n"
                "- continuity_verdict judges configured character identity, primary location/layout, illustrated medium, and authoritative appearance across files. Do not fail continuity merely because a movable secondary prop changes position or is absent from one frame. In a product-visible row, the generated product identity, natural interaction, and separate product_visual authority are reviewed together.\n"
                "- Hard character appearance authority comes only from an attached character_reference or explicit user/project requirement. Creative-model-invented hair texture/shade, exact wardrobe color, and accessory micro-details are continuity guidance, not pixel-exact authority. Reject only violations of creative_cast_policy, wrong configured character count/role, duplicates, missing characters, material cross-file identity drift, or mismatch to an attached/user-authoritative character anchor.\n"
                "- Return reference_checks with exactly one ordered object per reference row. Each object must include index, character_scene_verdict, terminal_action_verdict, continuity_verdict, emotional_beat_verdict, placement_surface_verdict, observed_characters, observed_terminal_state, observed_gaze_expression, observed_placement_surface, observed_facts, and missing_or_wrong_facts. Verdicts are match, mismatch, uncertain, or not_required only. observed_facts and missing_or_wrong_facts must each be JSON arrays for every row; use [] when empty, never prose strings or omitted rows. Return every ordered row even when a reference fails.\n"
                "- Describe only visible pixels. Never infer a later animation, off-screen prop, future movement, relationship, reconnection, eye contact, smile, or hidden placement surface. Uncertain is a rejection only for a required fact that can reasonably be proven by one still image. Each row may contain story context or several actions for the later video, but the still must show only its single_frame_terminal_state. Earlier/intermediate actions are context and their absence is not a mismatch; they also cannot substitute for the named terminal state. A generic surrounding surface or an implied off-screen surface is not evidence of the scripted product placement surface.\n"
                "- Do not reject because small phone text, a sender name, notification/app settings, or other UI microcopy is unreadable, and do not demand that an invisible setting be proven from pixels. Accept a clear visible proxy such as a message-like screen, a face-down or deliberately set-aside phone, or the adult visibly absorbing the moment when that proxy preserves the planned emotional terminal state. Do not require an intermediate telescope POV, prior movement, or earlier gesture to coexist in the terminal still.\n"
                "- COPY-LANE BOUNDARY: MEDIA_DESIGN.copy_delivery rows whose method is local_overlay are rendered later by the deterministic local compositor and are intentionally absent from generated reference pixels. Never reject a reference because exact time, count, quantified consequence, headline, CTA, caption, letters, or numerals assigned to local_overlay are not baked into the image. Judge the visible action, expression, composition, medium, continuity, and reserved placement space instead. If visual_job_ticket forbids generated text, clock numerals, screen copy, or captions, that instruction wins and must not be reversed during benchmark-hook review.\n"
                "- Treat harmless prop attachment or placement micro-details as continuity guidance, not blockers, unless they change the story's core visible action, identity continuity, product placement surface, or final emotional beat. A chart on the telescope stand instead of clipped to the telescope is not by itself a rejection.\n"
                f"- approved_for_split may be true only when there is exactly one usable native {video_aspect_ratio} image per required reference-plan row, the files together match chronological order, every required verdict is match, and every missing_or_wrong_facts list is empty.\n"
                "- On rejection, name only the incorrect global reference image(s), request native individual replacement frame(s), preserve the product identity authority and configured presentation policy, and never ask for a storyboard, board, grid, collage, or split screen."
            )
        else:
            stage_rules = (
                "\n\nVISUAL REVIEW CONTRACT:\n"
                + review_product_rule + product_presentation_rule + adult_cast_rule +
                "- approved_for_split may be true only when panel count/order match the creative plan, separators are clear, and every panel contains the required character, scene and action; a product-visible panel must contain a recognizable, naturally integrated product matching product_visual authority within the declared minor-drift tolerance.\n"
                "- The first panel is also the pixel-grounded opening-hook gate. Compare it with the approved opening mechanism, visual grammar, first beat, camera composition, and generation brief. Reject a board that merely includes named props while flattening a designed disruption, surprise, contrast, expressive reaction, scale, motion cue, or information-density hook into a generic establishing frame. Ask for a fresh board that restores the current Director concept without copying source-video pixels, roles, story premises, dialogue conceits, watermark-cover overlays, captions, search bars, or platform UI.\n"
                "- On rejection, repair_brief must request a fresh board with the same required panel count and preserve product identity authority and configured presentation policy."
            )
        stage_rules += (
            "\n- On every rejection return repair_strategy with mode, reference_indices, continuity_anchor_indices, and reason. "
            "Use mode regenerate_full_board for shared-medium, cast, location/style continuity, opening sequence, chronology, "
            "or topology/count failures. Use regenerate_references only for truly local defects after naming accepted reference "
            "indices whose actual pixels should be attached as continuity anchors. Never claim that a repair preserves an image "
            "unless its index is in continuity_anchor_indices."
        )
    elif stage_row.stage == "VIDEO_PROMPTS":
        story_structure_rule = (
            "- Keep the complete video's conversion logic: retention hook, visual product proof, and final spoken approved offer/CTA.\n"
            if product_required
            else "- Keep the approved complete video's opening, development, and resolution. Do not add a product reveal, selling point, offer, CTA, or shopping action.\n"
        )
        product_reference_rule = (
            "- Product-visible beats must also request product_anchor; product-free beats must not request it.\n"
            if product_required
            else "- This project has no product anchor. Request only the character, scene, and key-action anchors needed by the current segment.\n"
        )
        benchmark_adaptation_rule = (
            "- If benchmark_video_analysis.status is success, use only its style and pacing for this video's segmented script. "
            "Do not paste its transcript; rewrite the current segment around this project's approved product and visual anchors.\n"
            if product_required
            else "- If benchmark_video_analysis.status is success, use only its style and pacing for this video's segmented script. "
            "Do not paste its transcript, people, brands, products, offers, or shopping actions; adapt only the current approved segment.\n"
        )
        marketing_segment_rule = (
            "- If marketing_authorization contains a confirmed price, discount, offer, or CTA, the final half of every complete video must speak it aloud naturally "
            "in the configured video language and include it only in the segment where it belongs."
            if product_required
            else "- Do not add product claims, prices, offers, sales CTAs, shopping actions, or commercial overlays."
        )
        stage_rules = (
            "\n\nSEGMENTED STORY CONTRACT:\n"
            "- If video_variant_mode is serial_one_complete_video_at_a_time, return exactly one complete video for video_variant_index. "
            "Do not return the remaining variants; the scheduler will ask for them one by one.\n"
            "- MEDIA_DESIGN.complete_video_script is authoritative. Copy only the current segment assignment's complete dialogue_lines; never rewrite, split, merge, move, duplicate, or add a spoken sentence.\n"
            "- Use MEDIA_DESIGN.voice_bible speaker IDs. Keep each speaker's gender, timbre, pitch, accent, delivery, and speech rate identical across every segment.\n"
            "- Partition each complete video's story into non-overlapping segment prompts. Every action and spoken line must occur in exactly one segment.\n"
            "- A segment prompt must describe only its own time window; it must never summarize, replay, or complete the entire story arc.\n"
            "- Every segment timeline must restart at 0 seconds and end at that segment's own duration. For example, segment 2 of a 30-second video still uses 0-10, never 10-20.\n"
            "- Segment 1 must stop at a precise visual bridge state. Segment 2+ must continue from that state without replaying the hook.\n"
            + story_structure_rule + product_presentation_rule + adult_cast_rule +
            "- continuity_note must describe only the boundary pose/state shared by adjacent segments, never the complete story_arc.\n"
            "\nOMNI REFERENCE CONTRACT:\n"
            "- Return reference_indices for each segment based on FINAL_ASSETS reference_index and semantic_roles.\n"
            "- Each segment must request a character anchor, scene anchor, and key-action anchor when that role is needed by the current shot.\n"
            + product_reference_rule +
            "- Keep the narrative prompt concise and concrete. Do not write media tags; the server binds uploads using official <FIRST_FRAME> and <IMAGE_REF_N> tags.\n"
            "- Never invent image numbers or use vague phrases such as 'the reference image'.\n"
            + benchmark_adaptation_rule
            + marketing_segment_rule
        )
    elif stage_row.stage == "EDIT_PACKAGE":
        stage_rules = (
            "\n\nEDITOR HANDOFF CONTRACT:\n"
            "- This stage is editing and publishing guidance for a human editor, not an ad delivery or media-buying plan.\n"
            "- The creative director must write concise natural language guidance with timeline ranges, overlay text, font style, position, final publish title, publish caption, and hashtags.\n"
            "- Do not include budget, bidding, audience targeting, CTR, CVR, ROAS, pixel, ad-set, A/B testing, or campaign optimization instructions.\n"
            "- Keep wording culturally natural for the configured market and use only the configured video language.\n"
            "- If marketing_authorization.user_confirmed_marketing is true, confirmed_promotions and promotion_cta are user-approved project requirements. "
            "They must appear naturally in edit_guidance and publish_caption; do not reject, soften, or remove confirmed prices or CTAs."
        )
    return (
        "Use the complete content-factory contract in this request. Execute exactly one workflow stage through the connected user-owned Chrome. "
        "Use the standard signed-in ChatGPT session and upload only the listed browser_asset_paths when relevant. Never log in, solve CAPTCHA, purchase, publish, or change account settings. "
        "Wait for ChatGPT to finish, validate its answer against the stage contract, and return its complete JSON envelope as your final response. "
        "Do not advance beyond this stage."
        + model_note
        + stage_rules
        + "\n\nSTAGE PACKET:\n" + json.dumps(packet, ensure_ascii=False, indent=2)
    )


def _find_local_paths(value: Any) -> list[str]:
    found: list[str] = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key in {"path", "local_path", "file_path"} and isinstance(item, str):
                found.append(item)
            else:
                found.extend(_find_local_paths(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(_find_local_paths(item))
    elif isinstance(value, str) and value.startswith(str(BROWSER_OUTBOX_ROOT)):
        found.append(value)
    return found


def _generated_asset_manifest_paths(
    stage: str,
    envelope: dict[str, Any],
) -> list[str]:
    """Return only files authorized as generated assets for this stage.

    FINAL_ASSETS follows its explicit signed reference manifest instead of
    recursively discovering unrelated support paths in the envelope.
    """
    if str(stage or "").upper() == "FINAL_ASSETS":
        reference_items = list(
            dict(envelope.get("result") or {}).get("reference_images") or []
        )
        return [
            str(item.get("path") or "").strip()
            for item in reference_items
            if isinstance(item, dict) and str(item.get("path") or "").strip()
        ]
    candidates = _find_local_paths(envelope.get("evidence") or {})
    candidates.extend(_find_local_paths(envelope.get("result") or {}))
    return candidates


def _generated_reference_index(path: str | Path) -> int:
    """Recover the signed row index from a native reference filename."""
    match = re.search(
        r"(?:reference|final[_-]?assets?)[_-](\d+)",
        Path(str(path or "")).name,
        flags=re.IGNORECASE,
    )
    if not match:
        return 0
    try:
        return max(0, int(match.group(1)))
    except (TypeError, ValueError):
        return 0


def _server_outbox_path(raw_path: str) -> tuple[Path, str] | None:
    server_path = Path(raw_path).expanduser().resolve()
    root = BROWSER_OUTBOX_ROOT.resolve()
    if server_path != root and root not in server_path.parents:
        return None
    return server_path, str(server_path)


def _image_dhash(path: Path) -> int:
    with Image.open(path) as image:
        grayscale = image.convert("L").resize((17, 16), Image.Resampling.LANCZOS)
        pixels = np.asarray(grayscale, dtype=np.int16)
    bits = (pixels[:, 1:] > pixels[:, :-1]).reshape(-1)
    value = 0
    for bit in bits:
        value = (value << 1) | int(bool(bit))
    return value


def _quarantine_generated_visual_capture(
    project: HermesContentFactoryProject,
    *,
    stage: str,
    source: Path,
    reason: str,
) -> Path | None:
    """Preserve a rejected provider image outside normal project assets.

    Failed boards are essential evidence for splitter and prompt regressions.
    They must not appear in the user asset gallery or be considered by later
    stages, but deleting them makes deterministic failures impossible to
    diagnose and teaches self-heal nothing.
    """
    if not source.exists():
        return None
    diagnostic_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
        / "generated"
        / "diagnostics"
        / "visual_capture"
    )
    try:
        diagnostic_dir.mkdir(parents=True, exist_ok=True)
        timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
        suffix = source.suffix.lower() or ".bin"
        target = diagnostic_dir / (
            f"{stage.lower()}-{timestamp}-{uuid.uuid4().hex[:8]}{suffix}"
        )
        shutil.move(str(source), str(target))
        sidecar = target.with_suffix(target.suffix + ".json")
        sidecar.write_text(
            json.dumps(
                {
                    "stage": stage,
                    "reason": str(reason)[:2000],
                    "source_name": source.name,
                    "captured_at": datetime.now(timezone.utc).isoformat(),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return target
    except Exception:
        return None


def _visual_capture_error(
    project: HermesContentFactoryProject,
    *,
    stage: str,
    source: Path,
    reason: str,
) -> str:
    quarantined = _quarantine_generated_visual_capture(
        project,
        stage=stage,
        source=source,
        reason=reason,
    )
    if quarantined is None:
        return reason
    return f"{reason}; diagnostic_capture={quarantined}"


def _validate_generated_visual_capture(
    db,
    project: HermesContentFactoryProject,
    *,
    stage: str,
    source: Path,
    expected_panel_count: int | None = None,
) -> dict[str, Any]:
    if stage not in {"VISUAL_PREVIEW", "FINAL_ASSETS"}:
        return {}
    try:
        with Image.open(source) as image:
            width, height = image.size
    except Exception as exc:
        reason = f"VISUAL_CAPTURE_INVALID_IMAGE: {source}: {exc}"
        raise ValueError(
            _visual_capture_error(project, stage=stage, source=source, reason=reason)
        ) from exc
    if width < 512 or height < 512:
        reason = f"VISUAL_CAPTURE_TOO_SMALL: expected generated board, got {width}x{height}"
        raise ValueError(
            _visual_capture_error(project, stage=stage, source=source, reason=reason)
        )
    if stage == "VISUAL_PREVIEW":
        reference_count = max(
            1,
            int(expected_panel_count or _expected_final_reference_count(db, project) or 1),
        )
        try:
            cells, detected_layout = _detect_preview_cells(source, count=reference_count)
        except Exception as exc:
            reason = (
                "VISUAL_CAPTURE_GRID_INVALID: "
                f"could not identify {reference_count} usable panels in {width}x{height}: {exc}"
            )
            raise ValueError(
                _visual_capture_error(project, stage=stage, source=source, reason=reason)
            ) from exc
        target_aspect_ratio = _configured_video_aspect_ratio(project)
        _target_size, target_ratio = _reference_frame_geometry(target_aspect_ratio)
        wrong_aspect = [
            index for index, (_x, _y, cell_width, cell_height) in enumerate(cells, 1)
            if not 0.4 <= (cell_width / max(1, cell_height)) / target_ratio <= 2.25
        ]
        if wrong_aspect:
            reason = (
                "VISUAL_CAPTURE_GRID_INVALID: "
                f"panels {wrong_aspect} do not match target aspect {target_aspect_ratio} after automatic grid detection; "
                f"layout={detected_layout.get('columns')}x{detected_layout.get('rows')} "
                f"canvas={width}x{height}"
            )
            raise ValueError(
                _visual_capture_error(project, stage=stage, source=source, reason=reason)
            )
    else:
        detected_layout = None

    captured_hash = _image_dhash(source)
    source_assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == int(project.id),
            HermesContentFactoryAsset.kind == "source",
            HermesContentFactoryAsset.mime_type.like("image/%"),
        )
        .all()
    )
    for asset in source_assets:
        asset_path = Path(str(asset.file_path or ""))
        if not asset_path.is_file():
            continue
        try:
            distance = (captured_hash ^ _image_dhash(asset_path)).bit_count()
        except Exception:
            continue
        if distance <= 8:
            reason = (
                "VISUAL_CAPTURE_SOURCE_COLLISION: browser returned an uploaded source image "
                f"instead of assistant-generated media (source_asset_id={int(asset.id)}, distance={distance})"
            )
            raise ValueError(
                _visual_capture_error(project, stage=stage, source=source, reason=reason)
            )
    result = {
        "validated_generated_media": True,
        "source_collision_checked": True,
        "portrait_board_checked": stage == "VISUAL_PREVIEW",
        "width": int(width),
        "height": int(height),
    }
    if detected_layout:
        result["detected_grid"] = detected_layout
    return result


def _visual_expected_panel_count(stage_input: dict[str, Any] | None) -> int | None:
    values = stage_input if isinstance(stage_input, dict) else {}
    api_state = values.get("visual_api")
    api_values = api_state if isinstance(api_state, dict) else {}
    for raw in (
        api_values.get("expected_panels"),
        values.get("expected_panel_count"),
        values.get("expected_reference_count"),
    ):
        try:
            count = int(raw or 0)
        except (TypeError, ValueError):
            continue
        if 1 <= count <= 12:
            return count
    return None


def _visual_grid_repair_instruction(
    db,
    project: HermesContentFactoryProject,
    *,
    expected_panel_count: int | None = None,
    repair_attempt: int | None = None,
) -> str:
    reference_count = max(
        1,
        int(expected_panel_count or _expected_final_reference_count(db, project) or 1),
    )
    target_aspect_ratio = _configured_video_aspect_ratio(project)
    _target_size, target_ratio = _reference_frame_geometry(target_aspect_ratio)
    panel_orientation = (
        "vertical" if target_ratio < 0.98
        else "horizontal" if target_ratio > 1.02
        else "square"
    )
    panel_label = f"{panel_orientation} {target_aspect_ratio} panels"
    layout_by_count = {
        1: f"Use one full {panel_label[:-1]} with no internal split.",
        2: f"Use one row of exactly two equal {panel_label}.",
        3: f"Use one row of exactly three equal {panel_label}.",
        4: f"Use exactly a 2x2 grid of equal {panel_label}.",
        5: (
            f"Use two rows: exactly three equal {panel_label} on top and two centered {panel_label} below. "
            "The two lower panels must keep exactly the same width and height as the upper panels, with pure-white outer margins; "
            "never stretch either lower panel to half-canvas width and do not draw a sixth cell."
        ),
        6: f"Use exactly a 3x2 grid of equal {panel_label}.",
        7: (
            f"Use two rows: exactly four equal {panel_label} on top and three centered {panel_label} below. "
            "The three lower panels must keep exactly the same width and height as the upper panels, with pure-white outer margins; "
            "never stretch the lower row to fill the canvas and do not draw an eighth cell."
        ),
        8: f"Use exactly a 4x2 grid of equal {panel_label}.",
        9: f"Use exactly a 3x3 grid of equal {panel_label}.",
        10: f"Use exactly a 5x2 grid of equal {panel_label}.",
        11: (
            f"Use three rows: exactly four, four, then three centered {panel_label}. The final three panels must keep exactly the same "
            "width and height as the earlier panels, with pure-white outer margins; never stretch the final row and do not draw a twelfth cell."
        ),
        12: f"Use exactly a 4x3 grid of equal {panel_label}.",
    }
    layout_instruction = layout_by_count.get(
        reference_count,
        f"Use exactly {reference_count} ordered {panel_label} in balanced rows.",
    )
    attempt_note = (
        f" This is bounded geometry repair {int(repair_attempt)} of {max(1, MAX_VISUAL_REGENERATION_CYCLES - 1)}."
        if repair_attempt
        else ""
    )
    board_scope = (
        f"Regenerate as an ordered set of clean board images containing exactly {reference_count} panels in total. "
        "The runtime requests one local board at a time; in each request, obey that request's local board index, local panel count, and local grid specification. "
        "Do not squeeze the full sequence into every board or repeat panels from another board. "
        if reference_count > 7
        else f"Regenerate from scratch as exactly one clean board containing {reference_count} ordered {panel_label}. {layout_instruction} "
    )
    return (
        "The previous visual preview was rejected because the whole contact sheet geometry was wrong. "
        + attempt_note
        + " "
        + board_scope
        + "Each cell must contain one complete native target-aspect composition and straight edge-to-edge gutters. "
        f"All content cells on a board must keep one identical {target_aspect_ratio} width-to-height ratio and size. A shorter final row must be centered "
        "using pure-white outer margins, never by widening or stretching its cells. "
        "Each numbered shot maps to exactly one outer cell and must show one camera exposure at one instant. "
        "If a shot mentions several objects, stages, or examples, combine them naturally inside that one scene; "
        "never render internal gutters, before/after views, strips, inserts, montage, collage, diagram, or sequence inside a cell. "
        "Do not create an elongated strip, infographic, thumbnail collage, "
        "nested frames, picture-in-picture, labels, numbers, captions, or product-only crop sheet. "
        "Use continuous pure-white gutters of uniform visible thickness that run edge-to-edge across the whole board. "
        f"Keep all important people, hands and actions inside each {panel_orientation} panel with safe margins. "
        "Preserve the original ordered panel descriptions and their product-presence or product-free rules exactly. "
        "Show the uploaded product only when that scripted character/action keyframe explicitly needs it, and "
        "copy the attached user product reference exactly; "
        "Never create a standalone product-only panel or white-background packshot, and never add the product "
        "to a product-free panel."
    )


def _visual_grid_repair_budget(stage_input: dict[str, Any]) -> tuple[int, int]:
    """Return the current-variant grid repair count and its bounded limit.

    Stage.attempt is project-global for a stage name, so using it here makes a
    late serial variant ineligible for repair before its first malformed board.
    """
    try:
        current = max(0, int(stage_input.get("visual_grid_repair_count") or 0))
    except (TypeError, ValueError):
        current = 0
    hard_cap = max(0, MAX_VISUAL_REGENERATION_CYCLES - 1)
    try:
        configured = int(
            os.getenv(
                "HERMES_VISUAL_GRID_CURRENT_REPAIR_MAX_ATTEMPTS",
                str(hard_cap),
            )
        )
    except (TypeError, ValueError):
        configured = hard_cap
    maximum = min(hard_cap, max(0, configured))
    return current, maximum


def _is_visual_grid_error(message: str) -> bool:
    value = str(message or "").upper()
    return any(marker in value for marker in (
        "VISUAL_CAPTURE_GRID_INVALID",
        "VISUAL_CAPTURE_GRID_RATIO_INVALID",
    ))


def _visual_board_expected_counts(evidence: dict[str, Any]) -> dict[str, int]:
    """Map each generated board file to its board-local panel count."""
    result: dict[str, int] = {}
    api_meta = dict(evidence.get("api") or {})
    board_groups = [
        list(api_meta.get("boards") or []),
        list(evidence.get("visual_boards") or []),
    ]
    for boards in board_groups:
        for board in boards:
            if not isinstance(board, dict):
                continue
            board_path = str(board.get("output_path") or board.get("path") or "").strip()
            try:
                board_count = int(
                    board.get("expected_panels")
                    or board.get("panel_count")
                    or board.get("count")
                    or 0
                )
            except (TypeError, ValueError):
                board_count = 0
            if board_path and board_count > 0:
                result[board_path] = board_count
                result[Path(board_path).name] = board_count
    return result


def _visual_board_reference_meta(evidence: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """Preserve the reference range represented by each generated board.

    A board is one stored image but may cover several signed story references.
    Dropping ``global_end_index`` made CREATIVE_REVIEW interpret a four-panel
    board as reference 1 only, which then triggered a duplicate paid image
    generation even though the complete board was already on local storage.
    Keep both path and basename lookup keys because browser/API evidence may
    refer to the same file through different outbox paths.
    """
    result: dict[str, dict[str, int]] = {}
    api = dict(evidence.get("api") or {})
    for raw_board in list(api.get("boards") or []):
        if not isinstance(raw_board, dict):
            continue
        raw_path = str(raw_board.get("output_path") or raw_board.get("path") or "").strip()
        try:
            start = int(raw_board.get("global_start_index") or raw_board.get("board_index") or 0)
        except (TypeError, ValueError):
            start = 0
        try:
            expected_panels = int(
                raw_board.get("expected_panels")
                or raw_board.get("panel_count")
                or raw_board.get("count")
                or 0
            )
        except (TypeError, ValueError):
            expected_panels = 0
        try:
            end = int(raw_board.get("global_end_index") or 0)
        except (TypeError, ValueError):
            end = 0
        reference_indices = [
            int(value)
            for value in list(raw_board.get("global_reference_indices") or [])
            if str(value).strip().isdigit() and int(value) > 0
        ]
        if end <= 0 and start > 0 and expected_panels > 0:
            end = start + expected_panels - 1
        if not raw_path or start <= 0:
            continue
        row = {
            "reference_index": start,
            "global_start_index": start,
            "global_end_index": max(start, end or start),
            "expected_panels": max(1, expected_panels or (end - start + 1)),
            "global_reference_indices": reference_indices,
        }
        result[raw_path] = row
        result[Path(raw_path).name] = row
    return result


def _split_visual_board_native_files(
    source: Path,
    *,
    start_index: int,
    panel_count: int,
    output_dir: Path,
    aspect_ratio: str,
    reference_indices: list[int] | None = None,
) -> list[dict[str, Any]]:
    """Split one paid board locally into durable native reference frames."""
    if panel_count <= 1:
        return []
    cells, layout = _detect_preview_cells(source, count=panel_count)
    if len(cells) != panel_count:
        raise ValueError(
            "VISUAL_PREVIEW_NATIVE_SPLIT_UNSAFE: "
            f"detected={len(cells)}, expected={panel_count}, source={source}"
        )
    stat = source.stat()
    source_token = hashlib.sha256(
        f"{source.resolve()}:{stat.st_size}:{stat.st_mtime_ns}".encode("utf-8")
    ).hexdigest()[:12]
    output_dir.mkdir(parents=True, exist_ok=True)
    output_dir.chmod(0o775)
    rows: list[dict[str, Any]] = []
    mapped_indices = [int(value) for value in list(reference_indices or [])]
    if mapped_indices and len(mapped_indices) != panel_count:
        raise ValueError(
            "VISUAL_PREVIEW_NATIVE_SPLIT_INDEX_MAP_INVALID: "
            f"indices={mapped_indices}, expected={panel_count}, source={source}"
        )
    with Image.open(source) as opened:
        board = opened.convert("RGB")
        for offset, (x, y, width, height) in enumerate(cells):
            reference_index = (
                mapped_indices[offset]
                if mapped_indices
                else int(start_index) + offset
            )
            target = output_dir / (
                f"visual-preview-reference-{reference_index:02d}-{source_token}.png"
            )
            panel = board.crop((x, y, x + width, y + height))
            panel.save(target, format="PNG", optimize=True)
            normalized_meta = _normalize_reference_panel_to_aspect(
                target,
                aspect_ratio=aspect_ratio,
            )
            panel_ok, panel_reason = _split_panel_quality_ok(
                normalized_meta,
                index=reference_index,
                aspect_ratio=aspect_ratio,
            )
            if not panel_ok:
                target.unlink(missing_ok=True)
                raise ValueError(
                    "VISUAL_PREVIEW_NATIVE_SPLIT_UNSAFE: "
                    + str(panel_reason or f"reference {reference_index} failed")
                )
            target.chmod(0o644)
            rows.append({
                "index": reference_index,
                "path": str(target),
                "crop": {"x": x, "y": y, "width": width, "height": height},
                "aspect_normalization": normalized_meta,
                "detected_layout": layout,
            })
    return rows


def _materialize_visual_preview_native_assets(
    db,
    project: HermesContentFactoryProject,
    board_assets: list[HermesContentFactoryAsset],
    *,
    variant_index: int,
) -> list[HermesContentFactoryAsset]:
    """Create one local VISUAL_PREVIEW asset per panel without another API call."""
    derived: list[HermesContentFactoryAsset] = []
    target_aspect_ratio = _configured_video_aspect_ratio(project)
    native_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
        / "generated"
        / "visual_preview"
        / f"variant_{int(variant_index):02d}"
        / "native_references"
    )
    bridge_dir = (
        BROWSER_INBOX_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
    )
    bridge_dir.mkdir(parents=True, exist_ok=True)
    for board_asset in list(board_assets or []):
        if not _asset_file_available(board_asset):
            continue
        meta = dict(board_asset.meta_json or {})
        try:
            start = int(
                meta.get("global_start_index")
                or meta.get("reference_index")
                or 0
            )
            end = int(meta.get("global_end_index") or start or 0)
            panel_count = int(
                meta.get("expected_panels")
                or (end - start + 1 if start > 0 and end >= start else 1)
            )
            reference_indices = [
                int(value)
                for value in list(meta.get("global_reference_indices") or [])
                if str(value).strip().isdigit() and int(value) > 0
            ]
        except (TypeError, ValueError):
            continue
        if start <= 0 or panel_count <= 1:
            continue
        rows = _split_visual_board_native_files(
            Path(str(board_asset.file_path)),
            start_index=start,
            panel_count=panel_count,
            output_dir=native_dir,
            aspect_ratio=target_aspect_ratio,
            reference_indices=reference_indices or None,
        )
        board_outbox_path = str(meta.get("outbox_path") or board_asset.file_path)
        board_derived_assets: list[HermesContentFactoryAsset] = []
        for row in rows:
            index = int(row["index"])
            target = Path(str(row["path"]))
            bridge_name = f"v{int(variant_index):02d}-{target.name}"
            bridge_target = bridge_dir / bridge_name
            if (
                not bridge_target.exists()
                or bridge_target.stat().st_size != target.stat().st_size
            ):
                shutil.copy2(target, bridge_target)
            native_meta = {
                "asset_role": "visual_preview",
                "bridge_path": str(bridge_target),
                "browser_inbox_relative": (
                    f"workspace_{project.workspace_id}/{project.project_key}/{bridge_name}"
                ),
                # Keep the paid board's outbox path as the evidence join key.
                "outbox_path": board_outbox_path,
                "capture_origin": "assistant_generated",
                "variant_index": int(variant_index),
                "content_factory_variant_index": int(variant_index),
                "reference_index": index,
                "global_start_index": index,
                "global_end_index": index,
                "expected_panels": 1,
                "derived_from_board_asset_id": int(board_asset.id or 0),
                "derived_from_board_path": str(board_asset.file_path),
                "crop": dict(row.get("crop") or {}),
                "aspect_normalization": dict(
                    row.get("aspect_normalization") or {}
                ),
                "capture_validation": {
                    "validated_generated_media": True,
                    "derived_by_local_board_split": True,
                },
            }
            existing = (
                db.query(HermesContentFactoryAsset)
                .filter(
                    HermesContentFactoryAsset.project_id == project.id,
                    HermesContentFactoryAsset.file_path == str(target),
                )
                .one_or_none()
            )
            if existing is None:
                existing = HermesContentFactoryAsset(
                    project_id=project.id,
                    workspace_id=project.workspace_id,
                    user_id=project.user_id,
                    stage="VISUAL_PREVIEW",
                    kind="generated_image",
                    original_name=target.name,
                    file_path=str(target),
                    mime_type="image/png",
                    size_bytes=target.stat().st_size,
                    meta_json=native_meta,
                )
                db.add(existing)
            else:
                existing.size_bytes = target.stat().st_size
                existing.meta_json = {
                    **dict(existing.meta_json or {}),
                    **native_meta,
                }
            board_derived_assets.append(existing)
            derived.append(existing)
        db.flush()
        board_asset.meta_json = {
            **meta,
            "derived_native_reference_asset_ids": [
                int(asset.id) for asset in board_derived_assets if asset.id
            ],
            "derived_native_reference_count": len(board_derived_assets),
        }
    db.flush()
    return derived


def _visual_grid_repair_budget_exhausted(stage_input: dict[str, Any]) -> bool:
    current, maximum = _visual_grid_repair_budget(stage_input)
    return current >= maximum


def _visual_grid_failure_needs_browser_fallback(
    stage_input: dict[str, Any],
) -> bool:
    """Use the browser once after bounded API boards fail structural validation."""
    return bool(
        _visual_grid_repair_budget_exhausted(stage_input)
        and str(stage_input.get("execution_backend") or "").strip().lower() == "api"
        and not bool(stage_input.get("visual_api_force_browser_fallback"))
        and not bool(stage_input.get("visual_grid_browser_fallback_attempted"))
    )


def _import_generated_assets(
    db,
    project: HermesContentFactoryProject,
    stage: str,
    envelope: dict[str, Any],
    *,
    expected_panel_count: int | None = None,
) -> list[HermesContentFactoryAsset]:
    evidence = dict(envelope.get("evidence") or {})
    capture_origin = str(evidence.get("capture_origin") or "").strip()
    variant_index = int(evidence.get("content_factory_variant_index") or evidence.get("variant_index") or _active_variant_index(project))
    reference_items = list(dict(envelope.get("result") or {}).get("reference_images") or []) if stage == "FINAL_ASSETS" else []
    # FINAL_ASSETS is a signed manifest, not a directory/evidence scan.
    candidates = _generated_asset_manifest_paths(stage, envelope)
    reference_meta: dict[str, dict[str, Any]] = {}
    visual_board_expected = (
        _visual_board_expected_counts(evidence)
        if stage == "VISUAL_PREVIEW"
        else {}
    )
    visual_reference_meta: dict[str, dict[str, Any]] = (
        _visual_board_reference_meta(evidence)
        if stage == "VISUAL_PREVIEW"
        else {}
    )
    for position, item in enumerate(reference_items, 1):
        if not isinstance(item, dict):
            continue
        semantic = {
            "reference_index": int(item.get("index") or position),
            "reference_segment": item.get("segment"),
            "reference_description": item.get("description"),
            "semantic_roles": [
                str(value).strip().lower()
                for value in list(item.get("semantic_roles") or item.get("roles") or [])
                if str(value).strip().lower() in ANCHOR_ROLES
            ],
            "product_render_mode": "provider_reference",
        }
        raw_path = str(item.get("path") or "")
        if raw_path:
            reference_meta[raw_path] = semantic
            reference_meta[Path(raw_path).name] = semantic
    mapped = []
    seen = set()
    for value in candidates:
        item = _server_outbox_path(value)
        if item and str(item[0]) not in seen:
            seen.add(str(item[0]))
            mapped.append(item)
    if not mapped:
        return []

    deadline = time.monotonic() + 60
    while time.monotonic() < deadline and not all(path.is_file() for path, _ in mapped):
        time.sleep(2)

    asset_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
        / "generated"
        / stage.lower()
        / f"variant_{variant_index:02d}"
    )
    asset_dir.mkdir(parents=True, exist_ok=True)
    imported = []
    for source, _outbox_path in mapped:
        if not source.is_file():
            continue
        mime_type = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
        if not (mime_type.startswith("image/") or mime_type.startswith("video/")):
            continue
        capture_validation = (
            _validate_generated_visual_capture(
                db,
                project,
                stage=stage,
                source=source,
                expected_panel_count=(
                    visual_board_expected.get(str(source))
                    or visual_board_expected.get(source.name)
                    or expected_panel_count
                ),
            )
            if mime_type.startswith("image/")
            else {}
        )
        target = asset_dir / source.name
        if target.exists() and target.stat().st_size != source.stat().st_size:
            target = asset_dir / f"{source.stem}_{int(time.time())}{source.suffix}"
        if not target.exists():
            shutil.copy2(source, target)
        bridge_dir = BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key
        bridge_dir.mkdir(parents=True, exist_ok=True)
        bridge_name = f"v{variant_index:02d}-{source.name}" if stage in VARIANT_STAGES else source.name
        bridge_target = bridge_dir / bridge_name
        if not bridge_target.exists() or bridge_target.stat().st_size != target.stat().st_size:
            shutil.copy2(target, bridge_target)
        semantic_meta = dict(
            reference_meta.get(str(source))
            or reference_meta.get(source.name)
            or visual_reference_meta.get(str(source))
            or visual_reference_meta.get(source.name)
            or {}
        )
        if stage == "VISUAL_PREVIEW" and not int(
            semantic_meta.get("reference_index") or 0
        ):
            # Partial visual repairs may persist only the repaired row's API
            # board metadata.  The paid, preserved sibling files still carry
            # their signed row number in the native filename; retain that join
            # key so an approved checkpoint can be reconstructed after a
            # worker restart without regenerating images.
            recovered_reference_index = _generated_reference_index(source)
            if recovered_reference_index > 0:
                semantic_meta.update({
                    "reference_index": recovered_reference_index,
                    "global_start_index": recovered_reference_index,
                })
        # Product pixels are owned by the image/video provider. Do not import
        # retired clean plates or local-composite manifests into new assets.
        for retired_key in (
            "clean_plate_source",
            "clean_plate_path",
            "clean_plate_size_bytes",
            "authoritative_product_composite",
            "authoritative_product_composites",
        ):
            semantic_meta.pop(retired_key, None)
        for source_only_key in ("asset_role", "source", "product_id", "product_asset_id"):
            semantic_meta.pop(source_only_key, None)
        existing = db.query(HermesContentFactoryAsset).filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.file_path == str(target),
        ).one_or_none()
        if existing is not None:
            existing_meta = dict(existing.meta_json or {})
            for source_only_key in ("asset_role", "source", "product_id", "product_asset_id"):
                existing_meta.pop(source_only_key, None)
            existing.meta_json = {
                **existing_meta,
                "bridge_path": str(bridge_target),
                "browser_inbox_relative": f"workspace_{project.workspace_id}/{project.project_key}/{bridge_name}",
                "outbox_path": str(source),
                "capture_origin": capture_origin,
                "variant_index": variant_index,
                "content_factory_variant_index": variant_index,
                "capture_validation": capture_validation,
                **semantic_meta,
            }
            imported.append(existing)
            continue
        asset = HermesContentFactoryAsset(
            project_id=project.id, workspace_id=project.workspace_id, user_id=project.user_id,
            stage=stage, kind="generated_video" if mime_type.startswith("video/") else "generated_image",
            original_name=target.name, file_path=str(target), mime_type=mime_type,
            size_bytes=target.stat().st_size,
            meta_json={
                "bridge_path": str(bridge_target),
                "browser_inbox_relative": f"workspace_{project.workspace_id}/{project.project_key}/{bridge_name}",
                "outbox_path": str(source),
                "capture_origin": capture_origin,
                "variant_index": variant_index,
                "content_factory_variant_index": variant_index,
                "capture_validation": capture_validation,
                **semantic_meta,
            },
        )
        db.add(asset)
        imported.append(asset)
    db.flush()
    if stage == "VISUAL_PREVIEW":
        imported.extend(
            _materialize_visual_preview_native_assets(
                db,
                project,
                imported,
                variant_index=variant_index,
            )
        )
    return imported


def _reference_plan_for_project(
    db,
    project: HermesContentFactoryProject,
    count: int,
    *,
    variant_index: int | None = None,
) -> list[dict[str, Any]]:
    signed_variant = max(
        1,
        int(variant_index or _active_variant_index(project)),
    )
    creative_result = _successful_media_design_for_variant(
        db,
        project,
        variant_index=signed_variant,
    )
    normalized = _reference_contract_for_media_execution(
        creative_result,
        product_allowed=_project_uses_product(project),
    )
    plan = list(dict(normalized.get("visual_job_ticket") or {}).get("reference_plan") or [])
    rows: list[dict[str, Any]] = []
    for index in range(1, count + 1):
        source = dict(plan[index - 1] if index <= len(plan) else {})
        roles = [
            str(value).strip().lower()
            for value in list(source.get("roles") or [])
            if str(value).strip().lower() in ANCHOR_ROLES
        ]
        if not roles:
            roles = _classify_anchor_roles("", index=index, count=count)
        # The visual renderer deliberately generates reference 1 first and
        # supplies its pixels to every later reference whenever the user did
        # not upload a character anchor.  That image therefore owns the
        # recurring cast/subject, illustration medium and scene language even
        # when the Director described it only as an action/scene panel.  Keep
        # the persisted semantic topology aligned with the actual provider
        # topology so every video segment receives the same identity/style
        # seed.  This is a reference-control role, not a claim that every
        # project depicts a human character.
        if count > 1 and index == 1:
            roles.extend(("character_anchor", "scene_anchor"))
        rows.append({
            "index": index,
            "segment": int(source.get("segment") or 1),
            "segments": list(source.get("segments") or [int(source.get("segment") or 1)]),
            "description": str(source.get("description") or f"Reference panel {index}"),
            "roles": list(dict.fromkeys(roles)),
            # FINAL_ASSETS retains the signed source/generate decision. The
            # product package remains a separate provider authority reference;
            # no local product-composite instruction is propagated.
            "reference_id": str(source.get("reference_id") or f"reference_{index}"),
            "generation_mode": str(source.get("generation_mode") or "generate"),
            "source_asset_refs": list(source.get("source_asset_refs") or []),
            "requires_product_reference": bool(source.get("requires_product_reference")),
            "product_render_mode": "provider_reference",
        })
    return rows


def _ordered_native_reference_assets(
    preview_assets: list[HermesContentFactoryAsset],
    reference_plan: list[dict[str, Any]],
    *,
    evidence_files: set[str],
    active_variant: int,
) -> list[HermesContentFactoryAsset]:
    """Return one verified native file for every signed reference row.

    Image APIs emit one portrait file per generated row. The signed reference
    index is the join key. Older assets from a superseded attempt are ignored
    unless they are named by the successful VISUAL_PREVIEW evidence.
    """
    candidates: dict[int, list[HermesContentFactoryAsset]] = {}
    for asset in preview_assets:
        meta = dict(asset.meta_json or {})
        if int(meta.get("variant_index") or active_variant) != int(active_variant):
            continue
        path = Path(str(asset.file_path or ""))
        if not path.is_file():
            continue
        try:
            reference_index = int(meta.get("reference_index") or 0)
        except (TypeError, ValueError):
            continue
        if reference_index <= 0:
            continue
        candidates.setdefault(reference_index, []).append(asset)

    ordered: list[HermesContentFactoryAsset] = []
    for position, raw_plan in enumerate(reference_plan, 1):
        plan = dict(raw_plan or {})
        index = int(plan.get("index") or position)
        matched: list[HermesContentFactoryAsset] = []
        for asset in candidates.get(index, []):
            meta = dict(asset.meta_json or {})
            path = Path(str(asset.file_path or ""))
            capture_origin = str(meta.get("capture_origin") or "").strip().lower()
            evidence_match = (
                not evidence_files
                or path.name in evidence_files
                or Path(str(meta.get("outbox_path") or "")).name in evidence_files
            )
            if capture_origin == "assistant_generated" and evidence_match:
                matched.append(asset)
        if not matched:
            return []
        ordered.append(max(matched, key=lambda item: int(item.id or 0)))
    return ordered


def _detect_preview_cells(source: Path, *, count: int) -> tuple[list[tuple[int, int, int, int]], dict[str, Any]]:
    # Compatibility wrapper for existing task/tests. The reusable detector is
    # also exposed to the Hermes storyboard-grid-split skill.
    #
    # A targeted visual repair is intentionally rendered as one native image,
    # not as a one-cell contact sheet.  Sending that image through separator
    # detection incorrectly rejects a valid provider result because a native
    # frame has no storyboard gutters.  Treat the complete image as the only
    # cell; downstream aspect normalization still owns the final 9:16/16:9/1:1
    # reference geometry.
    if int(count or 0) == 1:
        with Image.open(source) as image:
            width, height = image.size
        if width <= 0 or height <= 0:
            raise ValueError(f"Invalid single reference image size: {source}")
        return [(0, 0, width, height)], {
            "columns": 1,
            "rows": 1,
            "mode": "native_single_reference",
        }
    return detect_preview_cells(source, count=count)


def _reference_frame_geometry(aspect_ratio: str) -> tuple[tuple[int, int], float]:
    normalized = str(aspect_ratio or "9:16").strip().replace("x", ":").replace("/", ":")
    try:
        width_text, height_text = normalized.split(":", 1)
        ratio = float(width_text) / float(height_text)
    except (TypeError, ValueError, ZeroDivisionError):
        ratio = 9 / 16
    if not math.isfinite(ratio) or ratio <= 0:
        ratio = 9 / 16
    if ratio > 1:
        width = 1920
        height = max(2, round(width / ratio / 2) * 2)
    elif ratio < 1:
        height = 1920
        width = max(2, round(height * ratio / 2) * 2)
    else:
        width = height = 1080
    return (width, height), ratio


def _normalize_reference_panel_to_aspect(
    path: Path,
    *,
    aspect_ratio: str = "9:16",
    existing_normalization: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Normalize a split panel without creating watermark-like matte bands.

    Storyboard cells are often a little wider or taller than the requested
    video frame. A contain canvas, even with blurred fill, looks like the
    top/bottom caption bands used to cover source-video watermarks and teaches
    downstream video models to preserve that framing. When the panel is close
    to the requested aspect, remove a genuine white storyboard gutter and use
    a small center cover-crop so the generated scene is actually full-bleed.
    Only large geometry mismatches retain the complete frame over blurred
    generated edge fill; the quality gate will normally reject those panels.

    ``existing_normalization`` lets FINAL_ASSETS recover a native reference
    that an older worker already padded. Stored original cell dimensions give
    us an exact crop of the contained foreground; no source-video pixels are
    introduced.
    """
    target_size, target_ratio = _reference_frame_geometry(aspect_ratio)
    with Image.open(path) as image:
        source = image.convert("RGB")
        prior = dict(existing_normalization or {})
        if bool(prior.get("padded")) and source.size == target_size:
            try:
                prior_width = int(prior.get("source_width") or 0)
                prior_height = int(prior.get("source_height") or 0)
            except (TypeError, ValueError):
                prior_width = prior_height = 0
            if prior_width > 0 and prior_height > 0:
                prior_scale = min(
                    target_size[0] / prior_width,
                    target_size[1] / prior_height,
                )
                contained_width = max(1, round(prior_width * prior_scale))
                contained_height = max(1, round(prior_height * prior_scale))
                left = max(0, (target_size[0] - contained_width) // 2)
                top = max(0, (target_size[1] - contained_height) // 2)
                right = min(target_size[0], left + contained_width)
                bottom = min(target_size[1], top + contained_height)
                if right > left and bottom > top:
                    source = source.crop((left, top, right, bottom))
        source_width, source_height = source.size
        if source_width <= 0 or source_height <= 0:
            raise ValueError(f"Invalid reference panel size: {path}")

        # Contact-sheet separators are commonly pure or near-white. Trim only
        # a bounded outer gutter and only when doing so leaves nearly all of
        # the panel; this never scans or removes internal bright scene areas.
        if source.size != target_size:
            grayscale = source.convert("L")
            content_mask = grayscale.point(lambda value: 255 if value < 244 else 0)
            content_bbox = content_mask.getbbox()
            if content_bbox is not None:
                left, top, right, bottom = content_bbox
                candidate_width = right - left
                candidate_height = bottom - top
                if (
                    candidate_width >= round(source_width * 0.88)
                    and candidate_height >= round(source_height * 0.88)
                    and (left > 0 or top > 0 or right < source_width or bottom < source_height)
                ):
                    source = source.crop(content_bbox)
                    source_width, source_height = source.size

        relative_ratio = (source_width / source_height) / target_ratio
        full_bleed_crop = 0.78 <= relative_ratio <= 1.28
        scale = (
            max(target_size[0] / source_width, target_size[1] / source_height)
            if full_bleed_crop
            else min(target_size[0] / source_width, target_size[1] / source_height)
        )
        resized_size = (
            max(1, round(source_width * scale)),
            max(1, round(source_height * scale)),
        )
        if hasattr(Image, "Resampling"):
            resized = source.resize(resized_size, Image.Resampling.LANCZOS)
        else:
            resized = source.resize(resized_size, Image.LANCZOS)
        if full_bleed_crop:
            crop_left = max(0, (resized_size[0] - target_size[0]) // 2)
            crop_top = max(0, (resized_size[1] - target_size[1]) // 2)
            canvas = resized.crop((
                crop_left,
                crop_top,
                crop_left + target_size[0],
                crop_top + target_size[1],
            ))
        elif resized_size == target_size:
            canvas = resized
        else:
            cover_scale = max(
                target_size[0] / source_width,
                target_size[1] / source_height,
            )
            cover_size = (
                max(target_size[0], round(source_width * cover_scale)),
                max(target_size[1], round(source_height * cover_scale)),
            )
            if hasattr(Image, "Resampling"):
                cover = source.resize(cover_size, Image.Resampling.LANCZOS)
            else:
                cover = source.resize(cover_size, Image.LANCZOS)
            cover_left = max(0, (cover_size[0] - target_size[0]) // 2)
            cover_top = max(0, (cover_size[1] - target_size[1]) // 2)
            canvas = cover.crop(
                (
                    cover_left,
                    cover_top,
                    cover_left + target_size[0],
                    cover_top + target_size[1],
                )
            ).filter(
                ImageFilter.GaussianBlur(
                    radius=max(18, round(max(target_size) / 42)),
                )
            )
        if not full_bleed_crop:
            x = (target_size[0] - resized_size[0]) // 2
            y = (target_size[1] - resized_size[1]) // 2
            canvas.paste(resized, (x, y))
        canvas.save(path, format="PNG", optimize=True)
    return {
        "target_width": target_size[0],
        "target_height": target_size[1],
        "source_width": source_width,
        "source_height": source_height,
        "target_aspect_ratio": str(aspect_ratio),
        "target_ratio": target_ratio,
        "mode": (
            "center_crop_full_bleed"
            if full_bleed_crop
            else "contain_over_blurred_fill"
        ),
        "padded": not full_bleed_crop and resized_size != target_size,
    }


def _split_panel_quality_ok(
    normalized_meta: dict[str, Any],
    *,
    index: int,
    aspect_ratio: str = "9:16",
) -> tuple[bool, str | None]:
    source_width = max(1, int(normalized_meta.get("source_width") or 1))
    source_height = max(1, int(normalized_meta.get("source_height") or 1))
    aspect = source_width / source_height
    _target_size, target_ratio = _reference_frame_geometry(aspect_ratio)
    # A usable video reference should already be reasonably close to the
    # configured frame. Extreme slivers mean the storyboard/grid split failed
    # and must be rebuilt
    # by ChatGPT image generation instead of being passed to video providers.
    # When a real edge-to-edge gutter was detected, keep the complete panel
    # even if the model made it slightly landscape. The normalization step
    # contains the full image in the configured canvas. Cropping it again to force a
    # ratio would remove people or product details and recreate the bug this
    # validation is meant to prevent.
    relative_ratio = aspect / target_ratio
    if relative_ratio < 0.4 or relative_ratio > 2.25:
        return False, (
            f"panel {index} does not match target aspect {aspect_ratio} after split: "
            f"{source_width}x{source_height}"
        )
    if min(source_width, source_height) < 200 or max(source_width, source_height) < 360:
        return False, f"panel {index} is too small after split: {source_width}x{source_height}"
    return True, None


def _prune_stale_final_split_files(
    output_dir: Path,
    *,
    saved_paths: list[str],
    split_manifest: list[dict[str, Any]],
) -> list[str]:
    """Remove numbered leftovers not authorized by the current split."""
    authorized = {
        str(Path(path).resolve())
        for path in saved_paths
        if str(path or "").strip()
    }
    removed: list[str] = []
    for candidate in output_dir.glob("final_assets-*.png"):
        if not re.fullmatch(
            r"final_assets-\d+(?:-clean-plate)?\.png",
            candidate.name,
            flags=re.IGNORECASE,
        ):
            continue
        if str(candidate.resolve()) in authorized:
            continue
        candidate.unlink(missing_ok=True)
        removed.append(str(candidate))
    return removed


def _creative_review_rejection_policy(
    state: dict[str, Any],
    *,
    variant_index: int,
    repair_limit: int | None = None,
    replan_limit: int | None = None,
    replan_stage: str = "PRODUCTION_PLAN",
) -> dict[str, Any]:
    """Bound visual repairs and full creative replans for one variant."""
    repair_key = str(max(1, int(variant_index or 1)))
    effective_repair_limit = max(
        1,
        int(
            repair_limit
            if repair_limit is not None
            else os.getenv("HERMES_CREATIVE_REVIEW_VISUAL_REPAIR_LIMIT", "2")
        ),
    )
    effective_replan_limit = max(
        1,
        int(
            replan_limit
            if replan_limit is not None
            else os.getenv("HERMES_CREATIVE_REPLAN_LIMIT", "1")
        ),
    )
    repair_counts = dict(state.get("creative_review_visual_repair_counts") or {})
    repair_count = max(0, int(repair_counts.get(repair_key) or 0)) + 1
    replan_counts = dict(state.get("production_plan_repair_counts") or {})
    replan_count = max(0, int(replan_counts.get(repair_key) or 0))
    exhausted = False
    if repair_count >= effective_repair_limit:
        repair_counts[repair_key] = 0
        replan_count += 1
        replan_counts[repair_key] = replan_count
        next_stage = str(replan_stage or "PRODUCTION_PLAN").strip().upper()
        if next_stage != "PRODUCTION_PLAN":
            raise ValueError(
                "visual review replans must return to PRODUCTION_PLAN"
            )
        exhausted = replan_count >= effective_replan_limit
    else:
        repair_counts[repair_key] = repair_count
        next_stage = "VISUAL_PREVIEW"
    state["creative_review_visual_repair_counts"] = repair_counts
    state["production_plan_repair_counts"] = replan_counts
    return {
        "next_stage": next_stage,
        "repair_count": repair_count,
        "repair_limit": effective_repair_limit,
        "replan_count": replan_count,
        "replan_limit": effective_replan_limit,
        "exhausted": exhausted,
        "state": state,
    }


def _creative_review_asset_cleanup_allowed(
    *,
    creative_replan_exhausted: bool,
) -> bool:
    """Quality-pause evidence must survive the terminal repair decision."""
    return not bool(creative_replan_exhausted)


def _recover_visual_preview_assets_from_stage(
    db,
    project: HermesContentFactoryProject,
) -> list[HermesContentFactoryAsset]:
    """Rebuild missing VISUAL_PREVIEW asset rows from trusted ChatGPT stage output."""
    active_variant = _active_variant_index(project)
    rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "VISUAL_PREVIEW",
            HermesContentFactoryStage.output_json.isnot(None),
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .limit(12)
        .all()
    )
    for row in rows:
        row_variant = _stage_output_variant(row)
        if row_variant is not None and int(row_variant) != int(active_variant):
            continue
        envelope = dict(row.output_json or {})
        evidence = dict(envelope.get("evidence") or {})
        if str(evidence.get("capture_origin") or "") != "assistant_generated":
            continue
        imported = _import_generated_assets(
            db,
            project,
            "VISUAL_PREVIEW",
            envelope,
            expected_panel_count=_visual_expected_panel_count(dict(row.input_json or {})),
        )
        recovered = [
            asset for asset in imported
            if str(asset.mime_type or "").startswith("image/")
            and str(dict(asset.meta_json or {}).get("capture_origin") or "") == "assistant_generated"
            and int(dict(asset.meta_json or {}).get("variant_index") or active_variant) == int(active_variant)
            and Path(str(asset.file_path or "")).is_file()
        ]
        if recovered:
            state = dict(project.state_json or {})
            state["last_visual_preview_asset_recovered"] = {
                "stage_id": int(row.id),
                "variant_index": int(active_variant),
                "paths": [str(asset.file_path) for asset in recovered],
                "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            }
            project.state_json = state
            db.flush()
            return recovered
    return []


def _visual_preview_evidence_files(
    preview_stage: HermesContentFactoryStage | None,
) -> set[str]:
    """Return the complete file set authorized by one preview attempt.

    A sparse repair checkpoints preserved siblings in ``input_json.visual_api``
    before it submits the failed rows.  That checkpoint is project-owned,
    stage-scoped evidence and remains valid if an older worker produced an
    incomplete output envelope containing only the newly rendered file.
    """
    if preview_stage is None:
        return set()
    output = dict(preview_stage.output_json or {})
    evidence = dict(output.get("evidence") or {})
    files = {
        Path(str(value)).name
        for value in list(evidence.get("files") or [])
        if str(value or "").strip()
    }
    visual_api = dict(dict(preview_stage.input_json or {}).get("visual_api") or {})
    for raw in dict(visual_api.get("boards") or {}).values():
        row = dict(raw or {})
        if str(row.get("status") or "").strip().lower() != "completed":
            continue
        output_path = str(row.get("output_path") or "").strip()
        if output_path:
            files.add(Path(output_path).name)
    return files


def _latest_successful_stage_for_variant(
    db,
    project: HermesContentFactoryProject,
    stage_name: str,
    variant_index: int,
) -> HermesContentFactoryStage | None:
    """Select stage evidence by immutable variant identity, never recency alone."""
    signed_variant = max(1, int(variant_index or 1))
    rows = (
        db.query(HermesContentFactoryStage)
        .filter_by(
            project_id=project.id,
            stage=stage_name,
            status="success",
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .all()
    )
    return next(
        (
            row
            for row in rows
            if int(_stage_output_variant(row) or 1) == signed_variant
        ),
        None,
    )


def _split_approved_preview(
    db,
    project: HermesContentFactoryProject,
    *,
    source_path: str | None = None,
    require_verified_preview: bool = True,
    variant_index: int | None = None,
) -> list[str]:
    active_variant = max(
        1,
        int(variant_index or _active_variant_index(project)),
    )

    preview_stage = _latest_successful_stage_for_variant(
        db,
        project,
        "VISUAL_PREVIEW",
        active_variant,
    )
    if preview_stage is None:
        raise ValueError(
            "FINAL_ASSETS_VISUAL_PREVIEW_MISSING: no successful visual "
            f"preview belongs to variant {active_variant}"
        )
    sources: list[Path] = []
    preview_assets: list[HermesContentFactoryAsset] = []
    selected: list[HermesContentFactoryAsset] = []
    evidence_files: set[str] = set()
    if source_path:
        source = Path(source_path)
        if not source.is_file():
            raise ValueError(f"Generated final-asset board is missing: {source}")
        sources = [source]
    else:
        preview_assets = db.query(HermesContentFactoryAsset).filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage == "VISUAL_PREVIEW",
            HermesContentFactoryAsset.mime_type.like("image/%"),
        ).order_by(HermesContentFactoryAsset.id.asc()).all()
        evidence_files = _visual_preview_evidence_files(preview_stage)
        selected = [
            asset for asset in preview_assets
            if int(dict(asset.meta_json or {}).get("variant_index") or active_variant) == int(active_variant)
            and Path(str(asset.file_path or "")).is_file()
            and (
                not evidence_files
                or Path(str(asset.file_path or "")).name in evidence_files
                or Path(str(dict(asset.meta_json or {}).get("outbox_path") or "")).name in evidence_files
            )
        ]
        if not selected:
            recovered = _recover_visual_preview_assets_from_stage(db, project)
            selected = recovered
        if not selected:
            raise ValueError("No approved visual preview board is available to split")
        def board_order(asset: HermesContentFactoryAsset) -> tuple[int, int]:
            name = Path(str(asset.file_path or "")).name
            match = re.search(r"board[-_](\d+)", name, flags=re.IGNORECASE)
            return (int(match.group(1)) if match else 1, int(asset.id))
        sources = [Path(str(asset.file_path)) for asset in sorted(selected, key=board_order)]
    review_stage = _latest_successful_stage_for_variant(
        db,
        project,
        "CREATIVE_REVIEW",
        active_variant,
    )
    creative_result = _successful_media_design_for_variant(
        db,
        project,
        variant_index=active_variant,
    )
    review_result = dict((review_stage.output_json or {}).get("result") or {}) if review_stage else {}
    count = _authoritative_reference_count(
        creative_result,
        review_result=review_result,
        fallback_texts=[
            str(review_stage.response_text or "") if review_stage else "",
            str(preview_stage.response_text or "") if preview_stage else "",
        ],
    )
    reference_plan = _reference_plan_for_project(
        db,
        project,
        count,
        variant_index=active_variant,
    )
    if not source_path:
        native_assets = _ordered_native_reference_assets(
            preview_assets,
            reference_plan,
            evidence_files=evidence_files,
            active_variant=active_variant,
        )
        if native_assets:
            selected = native_assets
            sources = [Path(str(asset.file_path)) for asset in native_assets]
        elif require_verified_preview and any(
            str(dict(asset.meta_json or {}).get("capture_origin") or "")
            != "assistant_generated"
            for asset in selected
        ):
            raise ValueError(
                "VISUAL_PREVIEW_PROVENANCE_INVALID: preview is neither a verified generated board "
                "nor a complete signed native-reference set"
            )
        if len(sources) != count:
            raise ValueError(
                "FINAL_ASSETS_GENERATED_REFERENCE_SET_INCOMPLETE: the approved "
                "native reference set does not contain every signed generated row"
            )
    output_dir = BROWSER_OUTBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key / "FINAL_ASSETS"
    output_dir.mkdir(parents=True, exist_ok=True)
    output_dir.chmod(0o775)
    board_counts: list[int] = []
    api_boards = list(
        dict(dict((preview_stage.output_json or {}).get("evidence") or {}).get("api") or {}).get("boards") or []
    ) if preview_stage else []
    if len(api_boards) == len(sources):
        board_counts = [max(1, int(dict(item).get("expected_panels") or 1)) for item in api_boards]
    if not board_counts or sum(board_counts) != count:
        base, remainder = divmod(count, len(sources))
        board_counts = [base + (1 if index < remainder else 0) for index in range(len(sources))]
    if any(value <= 0 for value in board_counts) or sum(board_counts) != count:
        raise ValueError(
            f"FINAL_ASSETS_BOARD_COUNT_INVALID: boards={len(sources)}, panel_counts={board_counts}, expected={count}"
        )
    saved: list[str] = []
    split_manifest: list[dict[str, Any]] = []
    board_layouts: list[dict[str, Any]] = []
    unsafe_reasons: list[str] = []
    source_normalization_by_path: dict[str, dict[str, Any]] = {
        str(Path(str(asset.file_path or "")).resolve()): dict(
            dict(asset.meta_json or {}).get("aspect_normalization") or {}
        )
        for asset in selected
        if str(asset.file_path or "").strip()
    }
    global_index = 0
    for board_index, (source, board_panel_count) in enumerate(zip(sources, board_counts), 1):
        try:
            if source.resolve().parent == output_dir.resolve():
                source_copy = output_dir / f"_source_board_{board_index:02d}_for_split.png"
                shutil.copy2(source, source_copy)
                source = source_copy
        except Exception:
            pass
        cells, layout = _detect_preview_cells(source, count=board_panel_count)
        board_layouts.append({
            "board_index": board_index,
            "source": str(source),
            "panel_count": board_panel_count,
            "layout": layout,
        })
        for local_index, (x, y, cell_width, cell_height) in enumerate(cells, 1):
            global_index += 1
            target = output_dir / f"final_assets-{global_index}.png"
            try:
                subprocess.run(
                    [
                        FFMPEG_BIN, "-y", "-i", str(source),
                        "-vf", f"crop={cell_width}:{cell_height}:{x}:{y}",
                        "-frames:v", "1", str(target),
                    ],
                    check=True, capture_output=True, text=True, timeout=120,
                )
            except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as exc:
                stderr = str(exc.stderr or "") if isinstance(exc, subprocess.CalledProcessError) else ""
                stdout = str(exc.stdout or "") if isinstance(exc, subprocess.CalledProcessError) else ""
                target.unlink(missing_ok=True)
                state = dict(project.state_json or {})
                state["last_split_layout"] = {"boards": board_layouts, "panel_count": count}
                state["last_split_manifest"] = split_manifest
                state["last_split_rejected"] = {
                    "reasons": [f"ffmpeg crop failed for panel {global_index}: {(stderr or stdout or str(exc))[:400]}"],
                    "action": "rebuild_with_chatgpt_final_assets",
                    "rejected_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                }
                project.state_json = state
                db.flush()
                raise ValueError(
                    "FINAL_ASSETS_SPLIT_UNSAFE: local storyboard split failed; "
                    f"board={board_index}; panel={global_index}; crop={cell_width}:{cell_height}:{x}:{y}; "
                    f"{(stderr or stdout or str(exc))[:600]}"
                ) from exc
            target.chmod(0o644)
            if not target.is_file() or target.stat().st_size < 1024:
                raise RuntimeError(f"Could not split preview panel {global_index}")
            target_aspect_ratio = _configured_video_aspect_ratio(project)
            normalized_meta = _normalize_reference_panel_to_aspect(
                target,
                aspect_ratio=target_aspect_ratio,
                existing_normalization=source_normalization_by_path.get(
                    str(source.resolve()),
                ),
            )
            panel_ok, panel_reason = _split_panel_quality_ok(
                normalized_meta,
                index=global_index,
                aspect_ratio=target_aspect_ratio,
            )
            if not panel_ok and panel_reason:
                unsafe_reasons.append(panel_reason)
            saved.append(str(target))
            plan_item = reference_plan[global_index - 1]
            split_manifest.append({
                "path": str(target),
                "index": global_index,
                "board_index": board_index,
                "board_panel_index": local_index,
                "segment": plan_item["segment"],
                "description": plan_item["description"],
                "roles": plan_item["roles"],
                "product_render_mode": "provider_reference",
                "crop": {"x": x, "y": y, "width": cell_width, "height": cell_height},
                "aspect_normalization": normalized_meta,
            })
    if unsafe_reasons:
        for path in saved:
            try:
                Path(path).unlink(missing_ok=True)
            except Exception:
                pass
        state = dict(project.state_json or {})
        state["last_split_layout"] = {"boards": board_layouts, "panel_count": count}
        state["last_split_manifest"] = split_manifest
        state["last_split_rejected"] = {
            "reasons": unsafe_reasons,
            "action": "rebuild_with_chatgpt_final_assets",
            "rejected_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        }
        project.state_json = state
        db.flush()
        raise ValueError(
            "FINAL_ASSETS_SPLIT_UNSAFE: local storyboard split produced unusable video references; "
            + "; ".join(unsafe_reasons[:6])
        )
    state = dict(project.state_json or {})
    state["last_split_layout"] = {"boards": board_layouts, "panel_count": count}
    state["last_split_manifest"] = split_manifest
    stale_split_files = _prune_stale_final_split_files(
        output_dir,
        saved_paths=saved,
        split_manifest=split_manifest,
    )
    if stale_split_files:
        state["last_stale_final_split_files_pruned"] = {
            "paths": stale_split_files,
            "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        }
    project.state_json = state
    db.flush()
    return saved


def _expected_final_reference_count(db, project: HermesContentFactoryProject) -> int:
    review_stage = db.query(HermesContentFactoryStage).filter_by(
        project_id=project.id, stage="CREATIVE_REVIEW", status="success"
    ).order_by(HermesContentFactoryStage.id.desc()).first()
    preview_stage = db.query(HermesContentFactoryStage).filter_by(
        project_id=project.id, stage="VISUAL_PREVIEW", status="success"
    ).order_by(HermesContentFactoryStage.id.desc()).first()
    creative_result = _successful_media_design_for_variant(
        db,
        project,
        variant_index=_active_variant_index(project),
    )
    review_result = dict((review_stage.output_json or {}).get("result") or {}) if review_stage else {}
    return _authoritative_reference_count(
        creative_result,
        review_result=review_result,
        fallback_texts=[
            str(review_stage.response_text or "") if review_stage else "",
            str(preview_stage.response_text or "") if preview_stage else "",
        ],
    )


def _final_reference_assets(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int | None = None,
) -> list[HermesContentFactoryAsset]:
    assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage == "FINAL_ASSETS",
            HermesContentFactoryAsset.mime_type.like("image/%"),
        )
        .order_by(HermesContentFactoryAsset.id.asc())
        .all()
    )
    if variant_index is None and _sequential_variants_enabled(project):
        variant_index = _active_variant_index(project)
    if variant_index is not None:
        assets = [
            asset for asset in assets
            if int(dict(asset.meta_json or {}).get("variant_index") or 1) == int(variant_index)
        ]
    return assets


def _final_assets_are_complete(db, project: HermesContentFactoryProject) -> tuple[bool, int, int]:
    # Text-to-video deliberately owns no reference-image artifacts.  Treat its
    # empty set as the complete media contract so generic VIDEO_PROMPTS,
    # EDIT_PACKAGE, and self-heal preflights cannot resurrect the retired
    # VISUAL_PREVIEW/FINAL_ASSETS branch.
    if _configured_video_generation_mode(project) == "text_to_video":
        return True, 0, 0
    expected = _expected_final_reference_count(db, project)
    assets = _final_reference_assets(db, project)
    valid = [
        asset for asset in assets
        if Path(asset.file_path).is_file()
        and Path(asset.file_path).stat().st_size > 1024
        and str(dict(asset.meta_json or {}).get("capture_origin") or "") in VALID_FINAL_ASSET_ORIGINS
    ]
    reference_indices: list[int] = []
    for asset in valid:
        try:
            reference_indices.append(
                int(dict(asset.meta_json or {}).get("reference_index") or 0)
            )
        except (TypeError, ValueError):
            reference_indices.append(0)
    expected_indices = set(range(1, expected + 1))
    complete = (
        len(valid) == expected
        and len(reference_indices) == len(set(reference_indices))
        and set(reference_indices) == expected_indices
    )
    return complete, expected, len(valid)


def _clean_final_assets(db, project: HermesContentFactoryProject) -> int:
    removed = 0
    for asset in _final_reference_assets(db, project):
        for raw_path in (
            asset.file_path,
            dict(asset.meta_json or {}).get("bridge_path"),
            dict(asset.meta_json or {}).get("outbox_path"),
        ):
            if not raw_path:
                continue
            try:
                path = Path(str(raw_path))
                if path.is_file():
                    path.unlink()
                    removed += 1
            except Exception:
                pass
        db.delete(asset)
    for root in (
        BROWSER_OUTBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key / "FINAL_ASSETS",
        CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}" / project.project_key / "generated" / "final_assets",
        BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key,
    ):
        try:
            if root.name in {"FINAL_ASSETS", "final_assets"} and root.exists():
                shutil.rmtree(root, ignore_errors=True)
            elif root.exists():
                for item in root.glob("final_assets-*.png"):
                    item.unlink()
        except Exception:
            pass
    db.flush()
    return removed


def _generated_asset_variant_index(asset: HermesContentFactoryAsset) -> int:
    meta = dict(asset.meta_json or {})
    for key in ("variant_index", "content_factory_variant_index"):
        try:
            value = int(meta.get(key) or 0)
        except (TypeError, ValueError):
            value = 0
        if value > 0:
            return value
    if str(asset.kind or "") == "video" or str(asset.stage or "") in {"VIDEO_PROMPTS"}:
        return _video_asset_index(asset)
    return 1


def _prune_project_asset_state(
    project: HermesContentFactoryProject,
    deleted_asset_ids: set[int],
) -> None:
    if not deleted_asset_ids:
        return
    state = dict(project.state_json or {})
    for key in ("ai_video_final_asset_ids", "editor_guidance_asset_ids"):
        state[key] = [
            int(value)
            for value in list(state.get(key) or [])
            if str(value).strip().isdigit() and int(value) not in deleted_asset_ids
        ]
    project.state_json = state


def _clean_generated_stage_assets(db, project: HermesContentFactoryProject, stages: tuple[str, ...]) -> int:
    removed = 0
    deleted_asset_ids: set[int] = set()
    stage_set = set(stages)
    assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage.in_(tuple(stage_set)),
            HermesContentFactoryAsset.kind.in_(("generated_image", "video")),
        )
        .all()
    )
    for asset in assets:
        for raw_path in (
            asset.file_path,
            dict(asset.meta_json or {}).get("bridge_path"),
            dict(asset.meta_json or {}).get("outbox_path"),
        ):
            if not raw_path:
                continue
            try:
                path = Path(str(raw_path))
                if path.is_file():
                    path.unlink()
                    removed += 1
            except Exception:
                pass
        if asset.id:
            deleted_asset_ids.add(int(asset.id))
        db.delete(asset)
    for stage in stage_set:
        for root in (
            BROWSER_OUTBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key / stage,
            CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}" / project.project_key / "generated" / stage.lower(),
        ):
            try:
                if root.exists():
                    shutil.rmtree(root, ignore_errors=True)
            except Exception:
                pass
    _prune_project_asset_state(project, deleted_asset_ids)
    db.flush()
    return removed


def _clean_generated_variant_assets(
    db,
    project: HermesContentFactoryProject,
    stages: tuple[str, ...],
    *,
    variant_index: int,
    preserve_asset_ids: set[int] | None = None,
) -> int:
    preserved_ids = {
        int(value)
        for value in (preserve_asset_ids or set())
        if int(value) > 0
    }
    removed = 0
    deleted_asset_ids: set[int] = set()
    assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage.in_(tuple(stages)),
            HermesContentFactoryAsset.kind.in_(("generated_image", "video")),
        )
        .all()
    )
    for asset in assets:
        meta = dict(asset.meta_json or {})
        if _generated_asset_variant_index(asset) != int(variant_index):
            continue
        if int(asset.id or 0) in preserved_ids:
            continue
        # Generated working copies and browser bridge uploads may be removed,
        # but the provider outbox is the durable paid-result ledger. Deleting
        # it here made a corrected reviewer unable to rebuild asset rows and
        # forced a second image submission for the same prompt.
        for raw_path in (
            asset.file_path,
            meta.get("bridge_path"),
        ):
            if not raw_path:
                continue
            try:
                path = Path(str(raw_path))
                if path.is_file():
                    path.unlink()
                    removed += 1
            except Exception:
                pass
        if asset.id:
            deleted_asset_ids.add(int(asset.id))
        db.delete(asset)
    # A partial repair keeps approved files in these variant directories.
    # Delete failed files above, but never remove their shared parent tree.
    if not preserved_ids:
        for stage in stages:
            for root in (
                CONTENT_FACTORY_STORAGE_ROOT
                / f"workspace_{project.workspace_id}"
                / project.project_key
                / "generated"
                / stage.lower()
                / f"variant_{int(variant_index):02d}",
            ):
                try:
                    if root.exists():
                        shutil.rmtree(root, ignore_errors=True)
                except Exception:
                    pass
    _prune_project_asset_state(project, deleted_asset_ids)
    db.flush()
    return removed


def _visual_asset_reference_index(asset: HermesContentFactoryAsset) -> int:
    meta = dict(asset.meta_json or {})
    for value in (
        meta.get("reference_index"),
        meta.get("global_start_index"),
    ):
        try:
            index = int(value or 0)
        except (TypeError, ValueError):
            index = 0
        if index > 0:
            return index
    for value in (
        asset.original_name,
        asset.file_path,
        meta.get("outbox_path"),
        meta.get("bridge_path"),
    ):
        match = re.search(
            r"(?:reference|panel|final_assets)[-_]?0*(\d+)",
            str(value or ""),
            flags=re.IGNORECASE,
        )
        if match:
            return int(match.group(1))
    return 0


def _creative_review_failed_reference_indices(result: dict[str, Any]) -> tuple[set[int], set[int]]:
    """Return (failed, observed) indices from pixel-grounded review rows."""
    failed: set[int] = set()
    observed: set[int] = set()
    for fallback_index, raw in enumerate(list(result.get("reference_checks") or []), 1):
        if not isinstance(raw, dict):
            continue
        try:
            index = int(raw.get("index") or fallback_index)
        except (TypeError, ValueError):
            continue
        if index <= 0:
            continue
        observed.add(index)
        verdicts = [
            str(raw.get(key) or "").strip().lower()
            for key in (
                "character_scene_verdict",
                "terminal_action_verdict",
                "continuity_verdict",
                "emotional_beat_verdict",
                "placement_surface_verdict",
            )
        ]
        if (
            any(value not in {"match", "not_required"} for value in verdicts)
            or bool(list(raw.get("missing_or_wrong_facts") or []))
        ):
            failed.add(index)

    # Some multimodal reviewers can identify a local topology defect across
    # the attached board and return an exact repair strategy without emitting
    # one ``reference_checks`` row per frame.  The strategy is still
    # pixel-grounded evidence: its repair indices are the failed files and its
    # continuity anchors are the files the reviewer explicitly accepted.
    # Ignoring that evidence makes the partial-repair descriptor empty, which
    # deletes every accepted native reference and pays to redraw the full
    # board.  Recover the same observed/failed sets from the normalized repair
    # contract when detailed rows are absent.
    if not observed:
        strategy = dict(result.get("repair_strategy") or {})
        mode = str(strategy.get("mode") or "").strip().lower()

        def strategy_indices(name: str) -> set[int]:
            values: set[int] = set()
            for value in list(strategy.get(name) or []):
                try:
                    index = int(value or 0)
                except (TypeError, ValueError):
                    continue
                if index > 0:
                    values.add(index)
            return values

        repair_indices = strategy_indices("reference_indices")
        anchor_indices = strategy_indices("continuity_anchor_indices")
        try:
            reference_count = int(result.get("reference_image_count") or 0)
        except (TypeError, ValueError):
            reference_count = 0
        if reference_count > 0:
            observed.update(range(1, reference_count + 1))
        observed.update(repair_indices)
        observed.update(anchor_indices)
        if mode == "regenerate_full_board":
            failed.update(observed)
        elif mode == "regenerate_references":
            failed.update(repair_indices)
    return failed, observed


def _targeted_visual_repair_brief(
    result: dict[str, Any],
    *,
    include_rejected_state: bool = False,
) -> str:
    """Turn pixel-grounded review facts into a useful image repair command.

    Review models sometimes return a generic top-level repair sentence even
    though ``reference_checks`` precisely describe the missing person, wrong
    prop, or obstructed product surface. Replaying only the generic sentence
    produces the same prompt digest and can regenerate the same defect. Put
    the concrete per-reference corrections first so the image prompt's bounded
    repair field retains them.
    """
    rows: list[str] = []
    for fallback_index, raw in enumerate(list(result.get("reference_checks") or []), 1):
        if not isinstance(raw, dict):
            continue
        try:
            index = int(raw.get("index") or fallback_index)
        except (TypeError, ValueError):
            continue
        verdicts = [
            str(raw.get(key) or "").strip().lower()
            for key in (
                "character_scene_verdict",
                "terminal_action_verdict",
                "continuity_verdict",
                "emotional_beat_verdict",
                "placement_surface_verdict",
            )
        ]
        missing = [
            re.sub(r"\s+", " ", str(value or "")).strip()
            for value in list(raw.get("missing_or_wrong_facts") or [])
            if str(value or "").strip()
        ]
        if (
            not missing
            and all(value in {"match", "not_required"} for value in verdicts)
        ):
            continue
        corrections = "; ".join(missing[:4])
        if not corrections:
            failed_fields = [
                key.replace("_verdict", "").replace("_", " ")
                for key in (
                    "character_scene_verdict",
                    "terminal_action_verdict",
                    "continuity_verdict",
                    "emotional_beat_verdict",
                    "placement_surface_verdict",
                )
                if str(raw.get(key) or "").strip().lower()
                not in {"match", "not_required"}
            ]
            corrections = "correct " + ", ".join(failed_fields)
        observed = re.sub(
            r"\s+",
            " ",
            str(raw.get("observed_terminal_state") or ""),
        ).strip()
        row = f"Reference {index}: {corrections}."
        if observed and include_rejected_state:
            row += f" Do not repeat the rejected state: {observed}."
        rows.append(row)
    if not rows:
        return ""
    repair_mode = str(
        dict(result.get("repair_strategy") or {}).get("mode") or ""
    ).strip().lower()
    opening = (
        "Regenerate the complete reference board as one coherent cast, scene, style, and chronology. Preserve the signed opening conflict, surprise, escalation, and visual energy; do not replace the hook with a calm generic establishing image. "
        if repair_mode == "regenerate_full_board"
        else "Regenerate only the failed native target-aspect references without reducing the approved hook intensity or emotional escalation. "
    )
    closing = (
        " Do not preserve predecessor reference pixels; rebuild one internally coherent board."
        if repair_mode == "regenerate_full_board"
        else " Preserve all passed references and the established adult cast and location."
    )
    return (
        opening
        + " ".join(rows)
        + closing
    )[:4000]


def _production_plan_visual_repair_brief(result: dict[str, Any]) -> str:
    """Carry the exact pixel failure into a new, simpler signed plan.

    A generic instruction to "simplify the rejected visuals" lets the plan
    author restate the same unrenderable terminal fact and starts the paid
    image loop again.  The replan boundary must preserve copy and meaning, but
    it is specifically allowed to replace the failed visual device with a
    simpler, visibly verifiable one.  Include the bounded pixel evidence so
    the author knows what must change rather than merely what must be retried.
    """
    # The production-plan author is a reasoning model, so the exact rejected
    # pixel state remains useful evidence at this boundary.  Image generation
    # calls intentionally omit it: repeating a visually salient bad state in
    # a positive image prompt (for example an open bottle and lifted cap) can
    # cause diffusion/image models to reproduce that state despite a leading
    # negation.
    targeted = _targeted_visual_repair_brief(
        result,
        include_rejected_state=True,
    )
    if targeted:
        targeted = re.sub(
            r"^Regenerate only the failed native target-aspect references"
            r"(?:\s+without reducing the approved hook intensity or emotional escalation)?\.\s*",
            "",
            targeted,
        )
        targeted = re.sub(
            r"\s*Preserve all passed references and the established adult cast and location\.?$",
            "",
            targeted,
        ).strip()
    evidence = (
        f" Pixel-grounded rejected state: {targeted}"
        if targeted
        else ""
    )
    return (
        "Revise only the current signed Production Plan. Preserve the approved "
        "Director script, product truth, line IDs, timing, conversion meaning, "
        "adult cast, and all passed visual facts. Replace each repeatedly failed "
        "visual device or terminal action with a simpler generator-friendly and "
        "pixel-verifiable depiction of the same story purpose and equal observable "
        "attention strength; provider safety must not turn a designed conflict, "
        "surprise, or escalation into a generic lifestyle shot. Do not merely "
        "restate the rejected image requirement."
        + evidence
    )[:4000]


def _expand_failed_visual_reference_dependencies(
    failed: set[int],
    observed: set[int],
    *,
    has_uploaded_character_anchor: bool,
    reference_one_identity_failed: bool = True,
) -> set[int]:
    """Keep pixel-grounded repair sparse, even when reference one failed.

    A generated first frame used to be treated as a one-way identity root, so
    any failure in reference one invalidated every later accepted frame. That
    assumption is no longer true: the repair request can attach one or more
    passed later frames as reverse continuity anchors. Regenerating passed
    product and action frames wastes quota and often introduces more drift.

    The unused keyword arguments remain for call-site/API compatibility while
    older queued deliveries drain; repair authority now comes exclusively
    from the review's per-reference verdicts and durable files.
    """
    del observed, has_uploaded_character_anchor, reference_one_identity_failed
    return set(failed)


def _visual_partial_repair_descriptor(
    db,
    project: HermesContentFactoryProject,
    review_stage: HermesContentFactoryStage,
    result: dict[str, Any],
    *,
    variant_index: int,
) -> dict[str, Any]:
    """Describe approved references that can survive a rejected review."""
    failed, observed = _creative_review_failed_reference_indices(result)
    if not observed or not failed:
        return {}
    repair_strategy = dict(result.get("repair_strategy") or {})
    repair_mode = str(
        repair_strategy.get("mode") or ""
    ).strip().lower()
    requested_repairs = {
        int(value)
        for value in list(repair_strategy.get("reference_indices") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    requested_anchors = {
        int(value)
        for value in list(
            repair_strategy.get("continuity_anchor_indices") or []
        )
        if str(value).strip().isdigit() and int(value) > 0
    }
    if repair_mode == "regenerate_full_board":
        failed = set(observed)
        requested_anchors = set()
    elif repair_mode == "regenerate_references" and requested_repairs:
        failed = set(requested_repairs)
    assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage == "VISUAL_PREVIEW",
            HermesContentFactoryAsset.kind == "generated_image",
        )
        .order_by(HermesContentFactoryAsset.id.desc())
        .all()
    )
    character_assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.kind == "character_reference",
            HermesContentFactoryAsset.mime_type.like("image/%"),
        )
        .all()
    )
    has_uploaded_character_anchor = any(
        _asset_file_available(asset)
        for asset in character_assets
    )
    reference_plan = _reference_plan_for_project(
        db,
        project,
        max(observed),
        variant_index=variant_index,
    )
    first_reference = next(
        (
            item
            for position, item in enumerate(reference_plan, 1)
            if int(item.get("index") or position) == 1
        ),
        {},
    )
    first_roles = {
        str(value or "").strip().lower().replace("-", "_")
        for value in list(dict(first_reference).get("roles") or [])
        if str(value or "").strip()
    }
    reference_one_is_identity_anchor = any(
        role == "character" or role.startswith("character_")
        for role in first_roles
    )
    reference_one_identity_failed = reference_one_is_identity_anchor and any(
        _coerce_segment_number(
            dict(raw).get("index"),
            fallback_index,
        ) == 1
        and (
            str(dict(raw).get("character_scene_verdict") or "").strip().lower()
            != "match"
            or str(dict(raw).get("continuity_verdict") or "").strip().lower()
            not in {"match", "not_required"}
        )
        for fallback_index, raw in enumerate(
            list(result.get("reference_checks") or []),
            1,
        )
        if isinstance(raw, dict)
    )
    failed = _expand_failed_visual_reference_dependencies(
        failed,
        observed,
        has_uploaded_character_anchor=has_uploaded_character_anchor,
        reference_one_identity_failed=reference_one_identity_failed,
    )
    by_index: dict[int, HermesContentFactoryAsset] = {}
    for asset in assets:
        if _generated_asset_variant_index(asset) != int(variant_index):
            continue
        index = _visual_asset_reference_index(asset)
        if index in observed and index not in by_index and _asset_file_available(asset):
            by_index[index] = asset

    # If a nominally passed row no longer has a durable local file, regenerate
    # it too. A partial-repair manifest must always describe a complete output
    # set, never point to an off-screen or deleted predecessor.
    passed = observed - failed
    missing_passed = {index for index in passed if index not in by_index}
    failed.update(missing_passed)
    passed.difference_update(missing_passed)
    preserved: list[dict[str, Any]] = []
    for index in sorted(passed):
        asset = by_index[index]
        meta = dict(asset.meta_json or {})
        preserved.append({
            "index": index,
            "asset_id": int(asset.id or 0),
            "path": str(asset.file_path),
            "bridge_path": str(meta.get("bridge_path") or ""),
            "outbox_path": str(meta.get("outbox_path") or ""),
        })
    return {
        "variant_index": int(variant_index),
        "source_review_stage_id": int(review_stage.id),
        "failed_indices": sorted(failed),
        "passed_indices": sorted(passed),
        "preserved_references": preserved,
        "repair_mode": repair_mode,
        "continuity_anchor_indices": sorted(
            requested_anchors & passed
        ),
    }


def _completed_video_assets_by_index(
    db,
    project: HermesContentFactoryProject,
) -> dict[int, HermesContentFactoryAsset]:
    rows = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage == "VIDEO_PROMPTS",
            HermesContentFactoryAsset.kind == "video",
        )
        .order_by(HermesContentFactoryAsset.id.asc())
        .all()
    )
    completed: dict[int, HermesContentFactoryAsset] = {}
    for asset in rows:
        video_index = _video_asset_index(asset)
        if video_index <= 0:
            continue
        try:
            path = Path(str(asset.file_path or ""))
            if not path.is_file() or path.stat().st_size < 1024:
                continue
        except Exception:
            continue
        completed[video_index] = asset
    return completed


def _completed_series_content_history(
    db,
    project: HermesContentFactoryProject,
    *,
    completed_indices: Iterable[int],
) -> list[dict[str, Any]]:
    """Compile bounded semantic history from durable completed videos.

    A completed local MP4 is the authority that an episode exists. Its
    semantic history comes from the current DIRECTOR/PRODUCTION_PLAN path.
    The resulting registry is generic and small enough for whole-series
    planning and review.
    """
    completed = {
        int(value)
        for value in completed_indices
        if str(value).strip().isdigit() and int(value) > 0
    }
    if not completed:
        return []

    stage_rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage.in_((
                "DIRECTOR",
                "PRODUCTION_PLAN",
            )),
            HermesContentFactoryStage.status.in_(("success", "superseded")),
        )
        .order_by(HermesContentFactoryStage.id.asc())
        .all()
    )
    latest_by_variant_and_stage: dict[
        tuple[int, str], HermesContentFactoryStage
    ] = {}
    for row in stage_rows:
        variant_index = _stage_output_variant(row)
        if variant_index is None:
            variant_index = 1
        if int(variant_index) in completed:
            latest_by_variant_and_stage[(
                int(variant_index), str(row.stage),
            )] = row

    video_plans = _latest_video_plans_by_index(db, project)
    completed_assets = _completed_video_assets_by_index(db, project)

    def bounded_text(value: Any, *, limit: int) -> str:
        if value in (None, "", [], {}):
            return ""
        if isinstance(value, str):
            text_value = value
        else:
            text_value = json.dumps(
                value,
                ensure_ascii=False,
                sort_keys=True,
                default=str,
            )
        return re.sub(r"\s+", " ", text_value).strip()[:limit]

    def script_fingerprint(script_value: Any) -> dict[str, Any]:
        script = dict(script_value or {}) if isinstance(script_value, dict) else {}
        segments = [
            dict(item)
            for item in list(
                script.get("segments")
                or script.get("ordered_segment_assignments")
                or []
            )
            if isinstance(item, dict)
        ]
        dialogue = [
            str(line.get("line") or line.get("text") or "").strip()
            for segment in segments
            for line in list(segment.get("dialogue_lines") or [])
            if isinstance(line, dict)
            and str(line.get("line") or line.get("text") or "").strip()
        ]
        return {
            "opening": bounded_text(
                script.get("opening")
                or (segments[0] if segments else None),
                limit=220,
            ),
            "development": bounded_text(
                script.get("development")
                or script.get("story_outline")
                or [
                    item.get("story_function")
                    for item in segments
                ],
                limit=260,
            ),
            "resolution": bounded_text(
                script.get("resolution")
                or (segments[-1] if segments else None),
                limit=220,
            ),
            "dialogue_excerpt": bounded_text(dialogue, limit=300),
        }

    history: list[dict[str, Any]] = []
    for variant_index in sorted(completed):
        semantic_source: dict[str, Any] = {}
        source_stage = "completed_video"

        director_row = latest_by_variant_and_stage.get(
            (variant_index, "DIRECTOR")
        )
        production_row = latest_by_variant_and_stage.get(
            (variant_index, "PRODUCTION_PLAN")
        )
        if director_row is not None:
            result = dict(
                dict(director_row.output_json or {}).get("result") or {}
            )
            artifact = dict(result.get("director_artifact") or {})
            program = dict(artifact.get("program") or {})
            script = dict(artifact.get("script") or {})
            semantic_source = {
                "objective": bounded_text(
                    program.get("objective"), limit=220
                ),
                "content_type": bounded_text(
                    program.get("content_type"), limit=100
                ),
                "creative_strategy": bounded_text(
                    program.get("creative_strategy"), limit=260
                ),
                "conversion_route": bounded_text(
                    program.get("conversion"), limit=240
                ),
                "script_excerpt": bounded_text(
                    [
                        dict(line).get("text")
                        for line in list(script.get("lines") or [])
                        if isinstance(line, dict)
                    ],
                    limit=500,
                ),
            }
            source_stage = "DIRECTOR"
        elif production_row is not None:
            result = dict(
                dict(production_row.output_json or {}).get("result") or {}
            )
            design = dict(result.get("compiled_media_design") or {})
            selected_raw = design.get("selected_concept")
            selected_concept = (
                dict(selected_raw)
                if isinstance(selected_raw, dict)
                else {"logline": selected_raw}
                if selected_raw not in (None, "", [], {})
                else {}
            )
            semantic_source = {
                "title": bounded_text(
                    selected_concept.get("title")
                    or selected_concept.get("name"),
                    limit=140,
                ),
                "premise": bounded_text(
                    selected_concept.get("logline")
                    or selected_concept.get("story_engine")
                    or selected_concept.get("why_selected"),
                    limit=300,
                ),
                **script_fingerprint(
                    design.get("complete_video_script")
                ),
            }
            source_stage = "PRODUCTION_PLAN"
        if not semantic_source:
            video_plan = dict(video_plans.get(variant_index) or {})
            asset = completed_assets.get(variant_index)
            asset_meta = dict(asset.meta_json or {}) if asset is not None else {}
            semantic_source = {
                "title": bounded_text(
                    video_plan.get("title")
                    or asset_meta.get("version_name"),
                    limit=140,
                ),
                "story_arc": bounded_text(
                    video_plan.get("story_arc")
                    or asset_meta.get("story_arc"),
                    limit=300,
                ),
                **script_fingerprint({
                    "segments": video_plan.get("segments")
                    or asset_meta.get("segment_plan"),
                }),
            }

        compact = _prompt_safe_value(
            semantic_source,
            max_string=420,
            max_items=16,
        )
        canonical = json.dumps(
            compact,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        history.append({
            "variant_index": variant_index,
            "source_stage": source_stage,
            "content_fingerprint": compact,
            "semantic_sha256": hashlib.sha256(
                canonical.encode("utf-8")
            ).hexdigest(),
        })
    return history


def _video_index_from_delivery_name(value: Any) -> int:
    name = Path(str(value or "")).name
    match = re.search(
        r"(?:^|[-_])v(?:ideo)?0*([1-9]\d*)(?=[-_.]|$)",
        name,
        flags=re.IGNORECASE,
    )
    if not match:
        return 0
    try:
        return int(match.group(1))
    except ValueError:
        return 0


def _latest_video_plans_by_index(
    db,
    project: HermesContentFactoryProject,
) -> dict[int, dict[str, Any]]:
    """Recover the durable per-variant plan used to compose a delivered video."""
    rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "VIDEO_PROMPTS",
            HermesContentFactoryStage.status.in_(("success", "superseded")),
        )
        .order_by(HermesContentFactoryStage.id.asc())
        .all()
    )
    selected: dict[int, dict[str, Any]] = {}
    for stage in rows:
        stage_output = dict(stage.output_json or {})
        result = (
            dict(stage_output.get("result") or {})
            if isinstance(stage_output.get("result"), dict)
            else stage_output
        )
        for raw_video in list(result.get("videos") or []):
            if not isinstance(raw_video, dict):
                continue
            video = dict(raw_video)
            try:
                index = int(
                    video.get("video_index")
                    or dict(stage.input_json or {}).get("variant_index")
                    or 0
                )
            except (TypeError, ValueError):
                index = 0
            if index > 0:
                selected[index] = video
    return selected


def _recover_orphaned_bridged_video_assets(
    db,
    project: HermesContentFactoryProject,
) -> list[HermesContentFactoryAsset]:
    """Restore completed local videos whose DB/final copy was lost.

    The bridge inbox is a second server-side delivery copy written only after
    a complete video has been composed locally.  It is therefore safe recovery
    evidence, but only after a scoped filename, size, duration, and target-count
    check.  This path never submits a provider task.
    """
    bridge_dir = (
        BROWSER_INBOX_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
    )
    if not bridge_dir.is_dir():
        return []

    target_count = _target_video_count(project)
    expected_duration = _configured_video_duration(project)
    plans = _latest_video_plans_by_index(db, project)
    rows = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.stage == "VIDEO_PROMPTS",
            HermesContentFactoryAsset.kind == "video",
        )
        .order_by(HermesContentFactoryAsset.id.asc())
        .all()
    )
    existing_by_index = {
        index: asset
        for asset in rows
        if (index := _video_asset_index(asset)) > 0
    }
    generated_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{project.workspace_id}"
        / project.project_key
        / "generated"
        / "final_videos"
    )
    recovered: list[HermesContentFactoryAsset] = []
    for bridge_path in sorted(bridge_dir.glob("*.mp4")):
        index = _video_index_from_delivery_name(bridge_path.name)
        if index <= 0 or index > target_count:
            continue
        try:
            bridge_size = bridge_path.stat().st_size
        except OSError:
            continue
        if bridge_size < 1024:
            continue
        duration = _probe_video_duration_seconds(bridge_path)
        if duration + 0.5 < float(expected_duration):
            continue

        existing = existing_by_index.get(index)
        if existing is not None:
            try:
                existing_path = Path(str(existing.file_path or ""))
                if (
                    existing_path.is_file()
                    and existing_path.stat().st_size >= 1024
                ):
                    continue
            except OSError:
                pass

        generated_dir.mkdir(parents=True, exist_ok=True)
        target = generated_dir / bridge_path.name
        if not target.is_file() or target.stat().st_size != bridge_size:
            temporary = target.with_name(
                f".{target.name}.{uuid.uuid4().hex}.recovering"
            )
            try:
                shutil.copy2(bridge_path, temporary)
                temporary.chmod(0o644)
                os.replace(temporary, target)
            finally:
                try:
                    temporary.unlink(missing_ok=True)
                except OSError:
                    pass

        plan = dict(plans.get(index) or {})
        segments = [
            dict(segment)
            for segment in list(plan.get("segments") or [])
            if isinstance(segment, dict)
        ]
        meta = {
            **(
                dict(existing.meta_json or {})
                if existing is not None
                else {}
            ),
            "content_factory_video_index": index,
            "content_factory_variant_index": index,
            "version_name": str(
                plan.get("version_name")
                or plan.get("title")
                or f"V{index}"
            ),
            "story_arc": str(
                plan.get("story_arc")
                or plan.get("title")
                or f"V{index}"
            ),
            "duration": int(round(duration)),
            "segment_count": len(segments),
            "segment_plan": [
                {
                    "segment_index": int(
                        segment.get("segment_index") or position
                    ),
                    "duration": int(segment.get("duration_seconds") or 0),
                    "segment_goal": str(segment.get("segment_goal") or ""),
                    "timeline": list(segment.get("timeline") or []),
                    "dialogue_lines": list(
                        segment.get("dialogue_lines") or []
                    ),
                    "display_lines": list(
                        segment.get("display_lines") or []
                    ),
                    "product_anchor_required": bool(
                        segment.get("product_anchor_required", False)
                    ),
                    "product_render_mode": "provider_reference",
                    "compile_source": str(
                        segment.get("compile_source") or ""
                    ),
                }
                for position, segment in enumerate(segments, 1)
            ],
            "source_task_ids": list(
                dict(existing.meta_json or {}).get("source_task_ids") or []
            ) if existing is not None else [],
            "is_composed_final": True,
            "bridge_path": str(bridge_path),
            "browser_inbox_relative": (
                f"workspace_{project.workspace_id}/"
                f"{project.project_key}/{bridge_path.name}"
            ),
            "recovered_from_bridge_copy": True,
            "recovered_at": (
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ),
        }
        if existing is None:
            existing = HermesContentFactoryAsset(
                project_id=project.id,
                workspace_id=project.workspace_id,
                user_id=project.user_id,
                stage="VIDEO_PROMPTS",
                kind="video",
                original_name=target.name,
                file_path=str(target),
                mime_type="video/mp4",
                size_bytes=target.stat().st_size,
                meta_json=meta,
            )
            db.add(existing)
            existing_by_index[index] = existing
        else:
            existing.original_name = target.name
            existing.file_path = str(target)
            existing.mime_type = "video/mp4"
            existing.size_bytes = target.stat().st_size
            existing.meta_json = meta
        db.flush()
        recovered.append(existing)
    if recovered:
        completed = _completed_video_assets_by_index(db, project)
        state = dict(project.state_json or {})
        state["ai_video_final_asset_ids"] = [
            int(completed[index].id)
            for index in sorted(completed)
            if int(completed[index].id or 0) > 0
        ]
        state["ai_video_ready_video_count"] = len(completed)
        pipeline = _variant_pipeline(project)
        pipeline["completed_indices"] = _authoritative_completed_variant_indices(
            completed.keys(),
            target=int(
                pipeline.get("target_count")
                or _target_video_count(project)
            ),
        )
        pipeline["completion_blocked_missing_indices"] = [
            index
            for index in range(
                1,
                int(
                    pipeline.get("target_count")
                    or _target_video_count(project)
                ) + 1,
            )
            if index not in set(pipeline["completed_indices"])
        ]
        pipeline["last_recovered_at"] = (
            datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        )
        state["video_variant_pipeline"] = pipeline
        project.state_json = state
        db.flush()
    return recovered


def _authoritative_editor_guidance_assets_by_index(
    db,
    project: HermesContentFactoryProject,
    *,
    completed_video_indices: set[int] | None = None,
) -> dict[int, HermesContentFactoryAsset]:
    """Return one existing local guide for each completed local video only."""
    completed = (
        set(completed_video_indices)
        if completed_video_indices is not None
        else set(_completed_video_assets_by_index(db, project))
    )
    rows = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.kind == "edit_guidance",
        )
        .order_by(HermesContentFactoryAsset.id.asc())
        .all()
    )
    selected: dict[int, HermesContentFactoryAsset] = {}
    for asset in rows:
        index = _video_asset_index(asset)
        if index <= 0 or index not in completed:
            continue
        try:
            path = Path(str(asset.file_path or ""))
            if not path.is_file() or path.stat().st_size <= 0:
                continue
        except OSError:
            continue
        selected[index] = asset
    return selected


def _reconcile_editor_guidance_state(
    db,
    project: HermesContentFactoryProject,
    state: dict[str, Any] | None = None,
    *,
    ensure_for_completed_videos: bool = True,
) -> tuple[dict[str, Any], dict[int, HermesContentFactoryAsset]]:
    """Rebuild guide state from local RAID and replenish any missing guide."""
    _recover_orphaned_bridged_video_assets(db, project)
    completed_videos = _completed_video_assets_by_index(db, project)
    guides = _authoritative_editor_guidance_assets_by_index(
        db,
        project,
        completed_video_indices=set(completed_videos),
    )
    if ensure_for_completed_videos:
        for index, video_asset in sorted(completed_videos.items()):
            if index in guides:
                continue
            guidance = _upsert_per_video_editor_guidance(db, project, video_asset)
            guides[index] = guidance
        db.flush()

    reconciled = dict(state if state is not None else project.state_json or {})
    reconciled["editor_guidance_asset_ids"] = [
        int(guides[index].id)
        for index in sorted(guides)
        if int(guides[index].id or 0) > 0
    ]
    reconciled["editor_guidance_ready_video_indices"] = sorted(guides)
    reconciled["editor_guidance_ready_count"] = len(guides)
    project.state_json = reconciled
    return reconciled, guides


def _queue_missing_serial_video_variant_if_needed(
    db,
    project: HermesContentFactoryProject,
    *,
    reason: str,
) -> HermesContentFactoryStage | None:
    if not _sequential_variants_enabled(project):
        return None
    config = dict(project.config_json or {})
    if not bool(config.get("auto_run", True)) or bool(config.get("manual_paused", False)):
        return None
    pipeline = _variant_pipeline(project)
    target = max(_target_video_count(project), int(pipeline.get("target_count") or 0))
    completed = {
        index for index in _completed_video_assets_by_index(db, project)
        if 1 <= int(index) <= target
    }
    missing = [index for index in range(1, target + 1) if index not in completed]
    if not missing:
        pipeline["completed_indices"] = sorted(completed)
        pipeline["target_count"] = target
        _set_variant_pipeline(project, pipeline)
        return None

    authorized_missing = [
        index
        for index in missing
        if _variant_rollout_authorized(project, index)
    ]
    if not authorized_missing:
        return None
    variant_index = int(authorized_missing[0])

    # ``state_json.ai_video_groups`` is only a mutable scheduling cache.  A
    # video waiter can finish from an older snapshot while VIDEO_PROMPTS has
    # already committed a paid provider task and its append-only execution
    # ledger.  Treat that durable ledger as authoritative before deciding the
    # variant is missing; otherwise the completion gate can submit the exact
    # same variant twice while the first task is downloading/composing.
    recovered_group = _recover_variant_media_group_from_execution_ledger(
        db,
        project=project,
        variant_index=variant_index,
    )
    if recovered_group is not None and not _ledger_group_still_owns_missing_variant(
        db,
        project=project,
        group=recovered_group,
    ):
        recovered_group = None
    if recovered_group is not None:
        state = dict(project.state_json or {})
        groups = [
            dict(item)
            for item in list(state.get("ai_video_groups") or [])
            if isinstance(item, dict)
            and int(item.get("video_index") or 0) != variant_index
        ]
        groups.append(recovered_group)
        task_ids = {
            int(segment.get("task_id") or 0)
            for segment in list(recovered_group.get("segments") or [])
            if isinstance(segment, dict)
            and int(segment.get("task_id") or 0) > 0
        }
        active_task_ids = {
            int(value)
            for value in list(state.get("ai_video_task_ids") or [])
            if str(value).strip().isdigit() and int(value) > 0
        }
        submitted = {
            int(value)
            for value in list(pipeline.get("submitted_indices") or [])
            if str(value).strip().isdigit()
        }
        failed_indices = {
            int(value)
            for value in list(pipeline.get("failed_indices") or [])
            if str(value).strip().isdigit()
        }
        submitted.add(variant_index)
        failed_indices.discard(variant_index)
        pipeline.update({
            "active_index": max(
                int(pipeline.get("active_index") or 0),
                variant_index,
            ),
            "target_count": target,
            "submitted_indices": sorted(submitted),
            "completed_indices": sorted(completed),
            "failed_indices": sorted(failed_indices),
            "completion_blocked_missing_indices": missing,
            "last_execution_ledger_recovery_at": (
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ),
        })
        state.update({
            "video_variant_pipeline": pipeline,
            "ai_video_groups": sorted(
                groups,
                key=lambda item: int(item.get("video_index") or 0),
            ),
            "ai_video_task_ids": sorted(active_task_ids | task_ids),
            "ai_video_wait_task_id": None,
        })
        project.state_json = state
        db.add(project)
        db.flush()
        _schedule_video_wait(
            db,
            project,
            countdown=5,
            reason=(
                f"recovered paid provider ledger for variant {variant_index}; "
                "waiting for download/composition instead of resubmitting"
            ),
        )
        return None

    active_variant = int(pipeline.get("active_index") or 0)
    active_variant_stages = [
        stage
        for stage in db.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage.in_(tuple(VARIANT_STAGES)),
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        ).all()
        if _stage_matches_variant(stage, project, variant_index)
    ]
    project_is_advancing_variant = (
        variant_index == active_variant
        and project.current_stage in VARIANT_STAGES
        and project.status in {"ready", "queued", "running", "retrying", "waiting_bridge"}
    )
    if active_variant_stages or project_is_advancing_variant:
        # The video waiter and the serial creative pipeline run concurrently.
        # A missing final MP4 is expected while this variant is still moving
        # through creative/visual/prompt stages and must not trigger a second
        # repair stage or delete its in-progress assets.
        return None
    submitted = {
        int(value) for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit()
    }
    failed_indices = {
        int(value) for value in list(pipeline.get("failed_indices") or [])
        if str(value).strip().isdigit()
    }
    submitted.discard(variant_index)
    failed_indices.add(variant_index)

    _clean_generated_variant_assets(
        db,
        project,
        ("VISUAL_PREVIEW", "FINAL_ASSETS", "VIDEO_PROMPTS"),
        variant_index=variant_index,
    )
    _delete_editor_guidance_for_video_index(db, project, variant_index)
    for stage in db.query(HermesContentFactoryStage).filter(
        HermesContentFactoryStage.project_id == project.id,
        HermesContentFactoryStage.stage.in_(tuple(VARIANT_STAGES)),
        HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
    ).all():
        if _stage_matches_variant(stage, project, variant_index):
            stage.status = "failed"
            stage.error_message = "Superseded because the required complete-video target was not met."

    state = dict(project.state_json or {})
    pipeline.update({
        "active_index": variant_index,
        "target_count": target,
        "submitted_indices": sorted(submitted),
        "completed_indices": sorted(completed),
        "failed_indices": sorted(failed_indices),
        "completion_blocked_missing_indices": missing,
        "last_completion_gate_requeue_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
    })
    state.update({
        "video_variant_pipeline": pipeline,
        "active_variant_index": variant_index,
        "ai_video_task_ids": [],
        "ai_video_groups": [],
        "ai_video_pending_task_ids": [],
        "ai_video_failed_task_ids": [],
        "ai_video_wait_task_id": None,
        "ai_video_ready_video_count": len(completed),
    })
    state, _guides = _reconcile_editor_guidance_state(db, project, state)
    project.state_json = state

    # Missing final media does not revoke an approved script.  Re-enter at the
    # first media boundary that can actually replace the failed deliverable.
    # Image-to-video needs fresh references because this function deliberately
    # removed the failed variant's generated images above; text-to-video can
    # recompile the already-approved signed plan directly.
    generation_mode = _configured_video_generation_mode(project)
    latest_plan = _latest_variant_stage(
        db,
        project,
        "PRODUCTION_PLAN",
        variant_index,
    )
    latest_director = _latest_variant_stage(
        db,
        project,
        "DIRECTOR",
        variant_index,
    )
    latest_video_prompts = _latest_variant_stage(
        db,
        project,
        "VIDEO_PROMPTS",
        variant_index,
    )
    if (
        generation_mode == "text_to_video"
        and latest_video_prompts is not None
        and latest_video_prompts.status == "success"
    ):
        repair_stage_name = "VIDEO_PROMPTS"
    elif latest_plan is not None and latest_plan.status == "success":
        repair_stage_name = "VISUAL_PREVIEW"
    elif latest_director is not None and latest_director.status == "success":
        repair_stage_name = "PRODUCTION_PLAN"
    else:
        repair_stage_name = "DIRECTOR"

    stage = _create_repair_stage(
        db,
        project,
        repair_stage_name,
        reason=reason,
        continue_workflow=True,
    )
    stage_input = dict(stage.input_json or {})
    stage_input.update({
        "variant_index": variant_index,
        "variant_total": target,
        "video_variant_index": variant_index,
        "video_variant_total": target,
        "video_variant_mode": "serial_one_complete_video_at_a_time",
        "self_heal_action": "regenerate_missing_complete_video_variant",
        "force_fresh_response": True,
        "queue_priority": max(8, int(stage_input.get("queue_priority") or 5)),
        "self_heal_count": 0,
        "automatic_retry_count": 0,
    })
    stage_input["self_heal_scope"] = (
        f"variant:{variant_index}:stage:{repair_stage_name}"
    )
    if repair_stage_name == "VISUAL_PREVIEW":
        stage_input.update({
            "allow_visible_visual_recovery": False,
            "force_fresh_response": True,
            "clear_stale_composer_before_send": False,
        })
    stage_input.pop("retry_after", None)
    stage_input.pop("retry_release_task_id", None)
    stage.input_json = stage_input
    project.current_stage = repair_stage_name
    project.status = "queued"
    project.last_error = (
        f"目标需要 {target} 条完整视频，目前只有 {len(completed)} 条；"
        f"Hermes 已清理第 {variant_index} 条失败产物并从 "
        f"{repair_stage_name} 媒体断点补做，不改写已审批文案。"
    )
    db.add(project)
    db.flush()
    return stage


def _ledger_group_still_owns_missing_variant(
    db,
    *,
    project: HermesContentFactoryProject,
    group: dict[str, Any],
) -> bool:
    """Return whether recovered paid work must block a fresh variant repair.

    The append-only execution ledger proves that a provider request existed; it
    does not prove that the request is still capable of producing the missing
    deliverable.  A superseded prompt-stage lineage or a group whose every
    provider task is terminally failed must yield to the complete-video target
    gate.  Otherwise the gate restores the same dead task on every waiter pass
    and spins forever instead of replenishing the missing ordinal.

    Mixed groups remain authoritative while at least one task is pending or
    successful.  Their failed sibling can still be reconciled by the normal
    bounded segment-retry path without duplicating live paid work.
    """

    if _media_group_source_is_superseded(db, project, group):
        return False
    task_ids = {
        int(segment.get("task_id") or 0)
        for segment in list(dict(group or {}).get("segments") or [])
        if isinstance(segment, dict)
        and int(segment.get("task_id") or 0) > 0
    }
    if not task_ids:
        return False
    tasks = _scoped_content_video_tasks(
        db,
        project,
        sorted(task_ids),
    )
    if len(tasks) != len(task_ids):
        return False
    return not all(_is_failed_video_task(task) for task in tasks)


def _configured_video_duration_range(project: HermesContentFactoryProject) -> dict[str, int]:
    config = dict(project.config_json or {})
    minimum = max(1, min(120, int(config.get("video_duration_min_seconds") or 10)))
    maximum = max(minimum, min(120, int(config.get("video_duration_max_seconds") or minimum)))
    return {"min": minimum, "max": maximum}


def _configured_locked_script_speech_rate_range(
    project: HermesContentFactoryProject,
) -> tuple[float, float]:
    """Read a user-confirmed narration range without product hard-coding."""

    config = dict(project.config_json or {})
    try:
        explicit_min = float(config.get("speech_rate_wpm_min"))
        explicit_max = float(config.get("speech_rate_wpm_max"))
    except (TypeError, ValueError):
        explicit_min = explicit_max = 0.0
    if explicit_min > 0 and explicit_max >= explicit_min:
        return explicit_min, explicit_max
    constraints = list(config.get("director_creative_constraints") or [])
    constraints.extend(list(config.get("creative_constraints") or []))
    for constraint in constraints:
        match = re.search(
            r"(?<!\d)(\d{2,3})\s*(?:-|\u2013|\u2014|to)\s*(\d{2,3})\s*wpm\b",
            str(constraint or ""),
            flags=re.IGNORECASE,
        )
        if not match:
            continue
        minimum = float(match.group(1))
        maximum = float(match.group(2))
        if 40 <= minimum <= maximum <= 400:
            return minimum, maximum
    return 145.0, 220.0


def _normalize_model_duration(project: HermesContentFactoryProject, requested: int | None = None) -> int:
    duration_range = _configured_video_duration_range(project)
    minimum, maximum = duration_range["min"], duration_range["max"]
    try:
        requested_value = int(float(requested)) if requested is not None else round((minimum + maximum) / 2)
    except (TypeError, ValueError):
        requested_value = round((minimum + maximum) / 2)
    desired = max(minimum, min(maximum, requested_value))
    config = dict(project.config_json or {})
    plan = dict(config.get("video_duration_plan") or {})
    if (
        str(plan.get("model_id") or "").strip().lower()
        == normalize_video_model_id(
            str(config.get("video_model") or "")
        )
    ):
        legal = sorted({
            int(value)
            for value in list(
                plan.get("legal_total_durations_seconds") or []
            )
            if str(value).strip().isdigit()
            and minimum <= int(value) <= maximum
        })
        if legal:
            return min(
                legal,
                key=lambda value: (abs(value - desired), value),
            )
    policy = _video_model_policy(project)
    if policy["id"] == "omni_flash":
        valid = [value for value in range(10, 121, 10) if minimum <= value <= maximum]
        if not valid:
            raise ValueError("Omni Flash total duration range must include a multiple of 10 seconds")
        return min(valid, key=lambda value: (abs(value - desired), value))
    return desired


def _configured_video_duration(project: HermesContentFactoryProject) -> int:
    state = dict(project.state_json or {})
    return _normalize_model_duration(project, state.get("planned_video_duration_seconds"))


def _segment_durations_for_project(project: HermesContentFactoryProject, duration: int | None = None) -> list[int]:
    total = _normalize_model_duration(project, duration or _configured_video_duration(project))
    plan = dict(dict(project.config_json or {}).get("video_duration_plan") or {})
    planned_total = int(plan.get("normalized_seconds") or 0)
    planned_segments = [
        int(value)
        for value in list(plan.get("segment_durations_seconds") or [])
        if str(value).strip().isdigit() and int(value) > 0
    ]
    if total == planned_total and sum(planned_segments) == total:
        return planned_segments
    production_contract = dict(plan.get("production_contract") or {})
    if production_contract:
        from app.services.hermes_agent.content_director import (
            VideoProductionContract,
            production_segment_durations,
        )

        contract = VideoProductionContract.model_validate(
            production_contract
        )
        return [
            int(round(value))
            for value in production_segment_durations(contract, total)
        ]
    policy = _video_model_policy(project)
    segment_max = int(policy["segment_duration_max"])
    count = max(1, (total + segment_max - 1) // segment_max)
    base, extra = divmod(total, count)
    durations = [base + (1 if index < extra else 0) for index in range(count)]
    if any(value < int(policy["segment_duration_min"]) or value > segment_max for value in durations):
        raise ValueError(f"{policy['label']} cannot generate the selected duration range")
    return durations



def _safe_file_stem(value: str) -> str:
    stem = "".join(char if char.isalnum() or char in "-_." else "-" for char in str(value or "").strip())
    stem = "-".join(part for part in stem.split("-") if part)
    return stem[:120] or "video"


def _cleanup_persisted_browser_chat(db, stage_row: HermesContentFactoryStage) -> bool:
    """Delete only this stage's persisted normal chat from its owning device."""
    if stage_row.stage not in {"VISUAL_PREVIEW", "FINAL_ASSETS"}:
        return False
    chat_url = str(stage_row.chat_url or "").strip()
    stage_input = dict(stage_row.input_json or {})
    cdp_url = str(stage_input.get("browser_cdp_url") or "").strip()
    if not chat_url or not cdp_url:
        return False
    deleted = direct_browser_runtime.delete_chatgpt_conversation_best_effort(
        cdp_url=cdp_url,
        chat_url=chat_url,
    )
    stage_input["chat_history_cleanup_attempted_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    stage_input["chat_history_cleanup_status"] = "deleted" if deleted else "pending"
    stage_row.input_json = stage_input
    if deleted:
        stage_row.chat_url = None
        output = dict(stage_row.output_json or {})
        evidence = dict(output.get("evidence") or {})
        evidence.pop("chat_url", None)
        evidence["chat_history_deleted"] = True
        evidence["chat_history_deleted_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        output["evidence"] = evidence
        stage_row.output_json = output
    db.add(stage_row)
    db.commit()
    return deleted


def _normalized_dialogue_lines(value: Any) -> list[dict[str, Any]]:
    """Normalize model dialogue without ever turning object keys into speech."""
    rows: list[dict[str, Any]] = []

    def preserve_delivery_fields(
        row: dict[str, Any],
        payload: Any,
    ) -> dict[str, Any]:
        if not isinstance(payload, dict):
            return row
        for field in (
            "delivery_mode",
            "delivery_method",
            "start_seconds",
            "end_seconds",
            "overlay_presentation",
        ):
            if field in payload:
                row[field] = payload.get(field)
        return row
    if isinstance(value, dict):
        iterable = list(value.items())
        for key, payload in iterable:
            if isinstance(payload, dict):
                line = str(
                    payload.get("line") or payload.get("dialogue") or payload.get("spoken_copy") or payload.get("copy")
                    or payload.get("text") or ""
                ).strip()
                line_id = str(payload.get("line_id") or "").strip()
                speaker = str(payload.get("speaker") or "").strip()
                speaker_id = str(payload.get("speaker_id") or payload.get("voice_id") or speaker or key or "").strip()
            else:
                line = str(payload or "").strip()
                line_id = ""
                speaker = ""
                speaker_id = str(key or "").strip()
            if not line:
                continue
            if not speaker:
                token = re.split(r"[_:\-]", str(key or "").strip(), maxsplit=1)[0]
                speaker = token.replace("_", " ").strip().title() if token else ""
            row = {
                "speaker_id": speaker_id or speaker,
                "speaker": speaker,
                "line": line,
            }
            if line_id:
                row["line_id"] = line_id
            rows.append(preserve_delivery_fields(row, payload))
        return rows
    if not isinstance(value, list):
        value = [value] if str(value or "").strip() else []
    for payload in value:
        if isinstance(payload, dict):
            line = str(
                payload.get("line") or payload.get("dialogue") or payload.get("spoken_copy") or payload.get("copy")
                or payload.get("text") or ""
            ).strip()
            line_id = str(payload.get("line_id") or "").strip()
            speaker = str(payload.get("speaker") or "").strip()
            speaker_id = str(payload.get("speaker_id") or payload.get("voice_id") or speaker or "").strip()
        else:
            line = str(payload or "").strip()
            line_id = ""
            speaker = ""
            speaker_id = ""
        if line:
            row = {
                "speaker_id": speaker_id or speaker,
                "speaker": speaker,
                "line": line,
            }
            if line_id:
                row["line_id"] = line_id
            rows.append(preserve_delivery_fields(row, payload))
    return rows


def _spoken_unit_count(text: str, language: str) -> int:
    if str(language or "").lower().startswith("zh"):
        return len(re.findall(r"[\u4e00-\u9fff]|[A-Za-z0-9']+", str(text or "")))
    return len(re.findall(r"[A-Za-z0-9]+(?:['-][A-Za-z0-9]+)*", str(text or "")))


def _dialogue_line_is_fragment(line: str, language: str) -> bool:
    text = str(line or "").strip()
    if not text:
        return True
    if re.search(r"[,;:\-]\s*$", text):
        return True
    if str(language or "").lower().startswith("zh"):
        return bool(re.search(r"(?:但是|因为|所以|然后|而且|以及|并且)\s*$", text))
    return bool(re.search(r"\b(?:and|but|because|so|then|while|although|with)\s*$", text, flags=re.IGNORECASE))


def _default_voice_profile(language: str) -> dict[str, Any]:
    chinese = str(language or "").lower().startswith("zh")
    return {
        "gender": "consistent neutral adult",
        "timbre": "clear, natural, medium-weight",
        "pitch": "medium",
        "accent": language or ("zh-CN" if chinese else "en-US"),
        "delivery": "fast, natural short-form delivery with clear articulation",
        "speech_rate": 300 if chinese else 165,
    }


def _script_speaker_candidates(raw_segments: list[Any]) -> list[dict[str, str]]:
    candidates: list[dict[str, str]] = []
    seen: set[str] = set()
    for raw_segment in raw_segments:
        if not isinstance(raw_segment, dict):
            continue
        dialogue_value = (
            raw_segment.get("dialogue_lines") or raw_segment.get("spoken_lines")
            or raw_segment.get("speaker_dialogue") or raw_segment.get("speaker_assignments")
            or raw_segment.get("spoken_dialogue")
            or raw_segment.get("dialogue")
        )
        raw_speaker_id = str(
            raw_segment.get("speaker_id") or raw_segment.get("speaker") or ""
        ).strip()
        if raw_speaker_id and not isinstance(dialogue_value, (dict, list)):
            dialogue_value = [{
                "speaker_id": raw_speaker_id,
                "speaker": str(raw_segment.get("speaker") or raw_speaker_id).strip(),
                "line": dialogue_value,
            }]
        dialogue = _normalized_dialogue_lines(
            dialogue_value
        )
        for line in dialogue:
            speaker_id = str(line.get("speaker_id") or line.get("speaker") or "").strip()
            if not speaker_id:
                speaker_id = "primary_narrator"
            key = speaker_id.casefold()
            if key in seen:
                continue
            seen.add(key)
            candidates.append({
                "speaker_id": speaker_id,
                "name": str(line.get("speaker") or speaker_id).strip() or speaker_id,
            })
    return candidates or [{"speaker_id": "primary_narrator", "name": "Primary narrator"}]


def _normalize_voice_bible(
    value: Any,
    language: str,
    *,
    fallback_speakers: list[dict[str, str]] | None = None,
) -> dict[str, Any]:
    source = dict(value or {}) if isinstance(value, dict) else {}
    raw_speakers = source.get("speakers") or source.get("voices") or []
    if isinstance(raw_speakers, dict):
        raw_speakers = [
            {"speaker_id": key, **(dict(item) if isinstance(item, dict) else {"description": item})}
            for key, item in raw_speakers.items()
        ]
    if not raw_speakers and any(
        str(source.get(key) or "").strip()
        for key in ("voice_type", "tone", "speed", "performance", "delivery")
    ):
        raw_speakers = [{
            "speaker_id": "primary_narrator",
            "name": "Primary narrator",
            "timbre": source.get("voice_type"),
            "delivery": " ".join(
                str(source.get(key) or "").strip()
                for key in ("tone", "speed", "performance", "delivery")
                if str(source.get(key) or "").strip()
            ),
        }]
    if not raw_speakers:
        raw_speakers = list(fallback_speakers or [])
    defaults = _default_voice_profile(language)
    speakers: list[dict[str, Any]] = []
    for index, raw in enumerate(list(raw_speakers or []), 1):
        if not isinstance(raw, dict):
            continue
        speaker_id = str(
            raw.get("speaker_id") or raw.get("voice_id") or raw.get("id") or raw.get("name") or f"speaker_{index}"
        ).strip()
        name = str(raw.get("name") or raw.get("speaker") or speaker_id).strip()
        gender = str(
            raw.get("gender") or raw.get("gender_presentation")
            or raw.get("voice_gender") or defaults["gender"]
        ).strip()
        timbre = str(
            raw.get("timbre") or raw.get("tone_color")
            or raw.get("voice_timbre") or defaults["timbre"]
        ).strip()
        pitch = str(raw.get("pitch") or raw.get("voice_pitch") or defaults["pitch"]).strip()
        accent = str(raw.get("accent") or raw.get("locale") or defaults["accent"]).strip()
        delivery = str(
            raw.get("delivery") or raw.get("delivery_style")
            or raw.get("tone") or defaults["delivery"]
        ).strip()
        try:
            rate = int(float(
                raw.get("speech_rate_wpm") or raw.get("speech_rate_cpm")
                or raw.get("pace_wpm") or raw.get("rate") or 0
            ))
        except (TypeError, ValueError):
            rate = 0
        if rate <= 0:
            rate = int(defaults["speech_rate"])
        speakers.append({
            "speaker_id": speaker_id,
            "name": name,
            "gender": gender,
            "timbre": timbre,
            "pitch": pitch,
            "accent": accent,
            "delivery": delivery,
            "speech_rate": rate,
            "speech_rate_unit": "characters_per_minute" if str(language).lower().startswith("zh") else "words_per_minute",
        })
    if not speakers:
        # Defensive fallback for malformed non-object speaker entries.
        fallback = dict((fallback_speakers or [{}])[0])
        speaker_id = str(fallback.get("speaker_id") or "primary_narrator").strip()
        speakers.append({
            "speaker_id": speaker_id,
            "name": str(fallback.get("name") or speaker_id).strip(),
            **defaults,
            "speech_rate_unit": "characters_per_minute" if str(language).lower().startswith("zh") else "words_per_minute",
        })
    primary_id = str(
        source.get("primary_speaker_id") or source.get("narrator_speaker_id")
        or source.get("primary_voice_id") or speakers[0]["speaker_id"]
    ).strip()
    if primary_id not in {item["speaker_id"] for item in speakers}:
        primary_id = str(speakers[0]["speaker_id"])
    return {"primary_speaker_id": primary_id, "speakers": speakers}


def _creative_positional_story_function(index: int, count: int) -> str:
    if index <= 1:
        return "opening hook and story setup"
    if index >= count:
        return "resolution and closing payoff"
    return "story development and progression"


def _creative_shot_for_segment(result: dict[str, Any], index: int, count: int) -> dict[str, Any]:
    shots = [item for item in list(result.get("shot_plan") or []) if isinstance(item, dict)]
    if not shots:
        return {}
    for position, shot in enumerate(shots, 1):
        if _coerce_segment_number(shot.get("segment"), position) == int(index):
            return dict(shot)
    shot_index = min(
        len(shots) - 1,
        round((index - 1) * (len(shots) - 1) / max(1, count - 1)),
    )
    return dict(shots[shot_index])


def _benchmark_time_seconds(value: Any) -> float | None:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return max(0.0, float(value))
    text = str(value).strip().replace(",", ".")
    if not text:
        return None
    try:
        return max(0.0, float(text))
    except ValueError:
        pass
    parts = text.split(":")
    if not 1 <= len(parts) <= 3:
        return None
    try:
        seconds = float(parts[-1])
        minutes = float(parts[-2]) if len(parts) >= 2 else 0.0
        hours = float(parts[-3]) if len(parts) >= 3 else 0.0
    except ValueError:
        return None
    return max(0.0, hours * 3600.0 + minutes * 60.0 + seconds)


def _benchmark_cue_rows(analysis: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for cue_index, raw in enumerate(list(analysis.get("segments") or []), 1):
        if not isinstance(raw, dict):
            continue
        text = str(
            raw.get("text") or raw.get("subtitle") or raw.get("transcript")
            or raw.get("dialogue") or raw.get("line") or ""
        ).strip()
        if not text:
            continue
        start = next((
            parsed for parsed in (
                _benchmark_time_seconds(raw.get(key))
                for key in ("start_seconds", "start_second", "start_time", "start")
            )
            if parsed is not None
        ), None)
        end = next((
            parsed for parsed in (
                _benchmark_time_seconds(raw.get(key))
                for key in ("end_seconds", "end_second", "end_time", "end")
            )
            if parsed is not None
        ), None)
        if start is None:
            start = rows[-1]["end_seconds"] if rows else 0.0
        if end is None or end <= start:
            end = start + 1.0
        rows.append({
            "cue_index": len(rows) + 1,
            "start_seconds": float(start),
            "end_seconds": float(end),
            "text": text,
        })
    return rows


def _canonical_exact_benchmark_script(
    project: HermesContentFactoryProject,
    result: dict[str, Any],
    script: dict[str, Any],
    voice_bible: dict[str, Any],
    analysis: dict[str, Any],
) -> tuple[dict[str, Any], int]:
    cues = _benchmark_cue_rows(analysis)
    if not cues:
        raise ValueError("CREATIVE exact benchmark reconstruction requires analyzed subtitle cues")
    source_duration = max(
        float(analysis.get("duration_seconds") or 0.0),
        max(float(item["end_seconds"]) for item in cues),
    )
    duration_range = _configured_video_duration_range(project)
    if source_duration > float(duration_range["max"]) + 0.01:
        raise ValueError(
            "CREATIVE exact benchmark source duration "
            f"{source_duration:g}s exceeds the configured maximum {duration_range['max']}s"
        )
    expected_duration = _normalize_model_duration(project, math.ceil(source_duration))
    if float(expected_duration) + 0.01 < source_duration:
        raise ValueError(
            f"CREATIVE exact benchmark requires at least {math.ceil(source_duration)} seconds"
        )
    durations = _segment_durations_for_project(project, expected_duration)
    primary_id = str(voice_bible["primary_speaker_id"])
    voice_by_id = {item["speaker_id"]: item for item in voice_bible["speakers"]}
    primary_name = str(voice_by_id[primary_id]["name"])
    boundaries: list[tuple[float, float]] = []
    cursor = 0.0
    for duration in durations:
        boundaries.append((cursor, cursor + float(duration)))
        cursor += float(duration)
    grouped: list[list[dict[str, Any]]] = [[] for _ in durations]
    for cue in cues:
        midpoint = (float(cue["start_seconds"]) + float(cue["end_seconds"])) / 2.0
        segment_index = min(
            len(boundaries) - 1,
            max(0, next((
                index
                for index, (_, end) in enumerate(boundaries)
                if midpoint < end or index == len(boundaries) - 1
            ), len(boundaries) - 1)),
        )
        grouped[segment_index].append(cue)
    # Source subtitles are authoritative. If rounding leaves an empty interior
    # segment, move one adjacent cue while preserving the global cue order.
    if len(cues) >= len(grouped):
        for index, group in enumerate(grouped):
            if group:
                continue
            donor = next((
                candidate for candidate in range(index - 1, -1, -1)
                if len(grouped[candidate]) > 1
            ), None)
            if donor is not None:
                group.append(grouped[donor].pop())
                continue
            donor = next((
                candidate for candidate in range(index + 1, len(grouped))
                if len(grouped[candidate]) > 1
            ), None)
            if donor is not None:
                group.append(grouped[donor].pop(0))
    normalized_segments: list[dict[str, Any]] = []
    for index, (duration, group) in enumerate(zip(durations, grouped), 1):
        shot = _creative_shot_for_segment(result, index, len(durations))
        story_function = str(
            shot.get("purpose") or shot.get("dialogue_function")
            or shot.get("story_function")
            or _creative_positional_story_function(index, len(durations))
        ).strip()
        visual_action = str(
            shot.get("visual") or shot.get("action") or shot.get("shot")
            or story_function
        ).strip()
        normalized_segments.append({
            "segment_index": index,
            "duration_seconds": int(duration),
            "story_function": story_function,
            "visual_action": visual_action,
            "dialogue_lines": [
                {
                    "speaker_id": primary_id,
                    "speaker": primary_name,
                    "line": str(cue["text"]),
                }
                for cue in group
            ],
            "benchmark_cue_indices": [int(cue["cue_index"]) for cue in group],
            "end_bridge": (
                "Continue from this exact pose, scene, prop state and vocal identity."
                if index < len(durations)
                else "Resolve the complete benchmark story cleanly."
            ),
        })
    flat_indices = [
        cue_index
        for segment in normalized_segments
        for cue_index in segment["benchmark_cue_indices"]
    ]
    expected_indices = list(range(1, len(cues) + 1))
    if flat_indices != expected_indices:
        raise ValueError(
            "CREATIVE exact benchmark subtitle grouping lost chronological cue order: "
            f"expected={expected_indices}, actual={flat_indices}"
        )
    story_outline = {
        "opening": str(normalized_segments[0]["story_function"]),
        "development": " ".join(
            str(item["story_function"]) for item in normalized_segments[1:-1]
        ) or str(normalized_segments[0]["story_function"]),
        "resolution": str(normalized_segments[-1]["story_function"]),
    }
    script.update({
        "duration_seconds": int(expected_duration),
        "target_edit_duration_seconds": max(1, min(int(expected_duration), round(source_duration))),
        "story_outline": story_outline,
        "segments": normalized_segments,
        "benchmark_source_duration_seconds": source_duration,
        "benchmark_cue_count": len(cues),
    })
    return script, int(expected_duration)


def _sanitize_product_visual_action(
    value: str,
    policy: dict[str, Any] | None = None,
) -> str:
    """Apply only interaction categories explicitly configured by the project."""
    text = str(value or "").strip()
    if not text:
        return text
    configured = dict(policy or {})
    categories = set(
        str(value or "").strip()
        for value in list(
            configured.get("forbidden_interaction_categories") or []
        )
        if str(value or "").strip()
    )
    if "open_package" in categories:
        # Keep the rest of a compound shot usable. Deleting the entire
        # sentence also erased a safe instruction to show a prepared serving
        # beside a sealed package.
        text = re.sub(
            r"\b(?:opens?|unseals?|unwraps?|unscrews?|twists?\s+off)\b"
            r"(?:\s+(?:the|an?|approved|authoritative|product))*"
            r"\s*(?:bottle|package|container|pouch|jar|box|bag|cap|lid)?\b",
            "keeps the package sealed and closed",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"\bcloses?\s+(?:the\s+)?(?:bottle|package|container)\b",
            "keeps the package closed",
            text,
            flags=re.IGNORECASE,
        )
        # Opening may be forbidden while a pre-staged serving is still
        # permitted. Rewriting only the opening verb used to leave impossible
        # directions that keep a package sealed while dispensing its contents.
        # Preserve the desired loose-product shot without claiming it came out
        # of the closed package during this take.
        text = re.sub(
            r"\b(?:pours?|dispenses?)\b[^.。!?]{0,300}"
            r"|\b(?:takes?\s+out|removes?)\b[^.。!?]{0,180}"
            r"\bfrom\b[^.。!?]{0,80}\b"
            r"(?:package|container|bottle|pouch|jar|box|bag)\b"
            r"[^.。!?]{0,80}",
            "shows a previously prepared loose serving beside the closed package",
            text,
            flags=re.IGNORECASE,
        )
    category_patterns = {
        "expose_loose_contents": (
            r"\b(?:takes?\s+out|removes?|pours?\s+out|loose\s+contents?)\b"
            r"[^.。!?]*[.。!?]?"
        ),
        "consume_product": (
            r"\b(?:eats?|chews?|swallows?|ingests?|consumes?|drinks?)\b"
            r"[^.。!?]*[.。!?]?"
        ),
        "minor_product_interaction": (
            r"\b(?:child|children|kid|kids|teen|minor)\b"
            r"[^.。!?]*(?:product|package|container|contents?)\b"
            r"[^.。!?]*[.。!?]?"
        ),
    }
    for category in categories:
        if category == "open_package":
            continue
        pattern = category_patterns.get(category)
        if pattern:
            text = re.sub(pattern, "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s{2,}", " ", text).strip(" .")
    if not text:
        instructions = [
            str(item or "").strip()
            for item in list(
                configured.get("presentation_instructions") or []
            )
            if str(item or "").strip()
        ]
        return (
            instructions[0][:900]
            if instructions
            else "Stage the authoritative uploaded product according to the saved project presentation policy"
        )
    return text[:900]


_CREATIVE_TIEBACK_STOPWORDS = {
    "about", "after", "again", "also", "another", "before", "began",
    "chose", "close",
    "could", "deliberate", "each", "ending", "evening", "every",
    "final", "from", "into", "just", "keep",
    "kept", "might",
    "night", "nighttime", "only", "package", "price", "product", "routine",
    "step", "still", "stopped", "that", "their", "them",
    "then", "there", "these", "they", "this", "those", "through", "until",
    "where", "which", "while", "wind-down", "with", "without", "would",
    "your",
}


def _creative_contract_token(value: Any) -> str:
    """Normalize one configured copy-contract token for stable comparison.

    Legacy projects can still carry a data-driven ``creative_copy_contract``
    while their completed history is migrated to Director artifacts.  Keep
    this compatibility normalizer local and generic: it folds possessives and
    common English inflections, but contains no campaign, brand, offer, or
    story-specific vocabulary.
    """
    token = re.sub(r"[^a-z0-9'-]+", "", str(value or "").strip().lower())
    token = re.sub(r"(?:'s|s')$", "", token)
    if len(token) > 5 and token.endswith("ing"):
        token = token[:-3]
    elif len(token) > 4 and token.endswith("ed"):
        token = token[:-2]
    elif len(token) > 4 and token.endswith("s"):
        token = token[:-1]
    return token


def _creative_conversion_segment_text(segment: dict[str, Any]) -> str:
    dialogue = " ".join(
        str(item.get("line") or "")
        for item in list(segment.get("dialogue_lines") or [])
        if isinstance(item, dict)
    )
    return re.sub(
        r"\s+",
        " ",
        f"{dialogue} {str(segment.get('visual_action') or '')}",
    ).strip()


def _creative_tieback_tokens(
    value: str,
    extra_stopwords: set[str] | None = None,
) -> set[str]:
    normalized_extra = {
        normalized
        for token in set(extra_stopwords or set())
        if (normalized := _creative_contract_token(token))
    }
    tokens: set[str] = set()
    for raw in re.findall(r"[a-z][a-z'-]{3,}", str(value or "").lower()):
        normalized = _creative_contract_token(raw)
        if (
            normalized
            and normalized not in _CREATIVE_TIEBACK_STOPWORDS
            and normalized not in normalized_extra
        ):
            tokens.add(normalized)
    return tokens


def _creative_bridge_tokens(value: str) -> set[str]:
    # A causal bridge is allowed to repeat the concrete solution-principle
    # language (for example "wind-down step" or "day-ending transition").
    # Those words are intentionally excluded from the opening-loss tieback
    # check but are meaningful continuity here.
    bridge_stopwords = _CREATIVE_TIEBACK_STOPWORDS - {
        "ending", "nighttime", "routine", "step", "wind-down",
    }
    tokens: set[str] = set()
    for raw in re.findall(r"[a-z][a-z'-]{3,}", str(value or "").lower()):
        normalized = _creative_contract_token(raw)
        if normalized and normalized not in bridge_stopwords:
            tokens.add(normalized)
    return tokens


def _assert_project_creative_copy_contract(
    project: HermesContentFactoryProject,
    segments: list[dict[str, Any]],
) -> None:
    """Validate the project-compiled copy contract without campaign constants."""
    if _content_director_enforced(project):
        # Enforced projects already passed the project-owned Director and
        # independent Critic contracts. Their exact line identities, text,
        # allocation, timing, and hashes are checked by
        # _assert_director_script_lock. Applying the legacy campaign compiler
        # here would reintroduce server-authored reveal, bridge, and ending
        # formulas after approval.
        return
    contract = _creative_copy_contract(project)
    if not bool(contract.get("product_required")):
        return
    expected_count = int(contract.get("segment_count") or len(segments))
    if len(segments) != expected_count:
        raise ValueError(
            "CREATIVE_CONVERSION_BRIDGE_SEGMENT_COUNT: the project copy "
            f"contract requires exactly {expected_count} ordered segments"
        )
    product_free_through = max(
        0,
        min(
            expected_count,
            int(contract.get("product_free_through_segment") or 0),
        ),
    )
    forbidden_terms = [
        str(term).strip().lower()
        for term in list(contract.get("pre_reveal_forbidden_terms") or [])
        if str(term).strip()
    ]
    for position, segment in enumerate(segments[:product_free_through], 1):
        early_text = _creative_conversion_segment_text(segment).lower()
        matched_term = next(
            (
                term for term in forbidden_terms
                if re.search(
                    rf"(?<![a-z0-9]){re.escape(term)}(?![a-z0-9])",
                    early_text,
                )
            ),
            "",
        )
        if matched_term:
            raise ValueError(
                "CREATIVE_CONVERSION_BRIDGE_PRODUCT_TOO_EARLY: "
                f"segment #{position} must complete story recognition without "
                f"the project-configured pre-reveal term {matched_term!r}"
            )

    reveal_segment = max(
        1,
        min(
            expected_count,
            int(contract.get("product_reveal_segment") or expected_count),
        ),
    )
    conversion_segment = max(
        reveal_segment,
        min(
            expected_count,
            int(contract.get("conversion_segment") or expected_count),
        ),
    )
    product_identity_segment = max(
        1,
        min(
            expected_count,
            int(contract.get("product_identity_segment") or conversion_segment),
        ),
    )
    reveal_dialogue = " ".join(
        str(item.get("line") or "")
        for item in list(segments[product_identity_segment - 1].get("dialogue_lines") or [])
        if isinstance(item, dict)
    ).strip()
    required_identity_terms = [
        str(term).strip().lower()
        for term in list(contract.get("required_product_identity_terms") or [])
        if str(term).strip()
    ]
    if required_identity_terms and not any(
        re.search(
            rf"(?<![a-z0-9]){re.escape(term)}(?![a-z0-9])",
            reveal_dialogue.lower(),
        )
        for term in required_identity_terms
    ):
        raise ValueError(
            "CREATIVE_FINAL_PRODUCT_OFFER_MISSING: the configured product "
            f"identity must be spoken in segment #{product_identity_segment}"
        )

    final_dialogue = " ".join(
        str(item.get("line") or "")
        for item in list(segments[conversion_segment - 1].get("dialogue_lines") or [])
        if isinstance(item, dict)
    ).strip()
    compact_final = re.sub(r"\s+", "", final_dialogue).lower()
    missing_prices = [
        token
        for token in list(contract.get("required_price_tokens") or [])
        if str(token).strip().lower() not in compact_final
    ]
    if missing_prices:
        raise ValueError(
            "CREATIVE_FINAL_PRODUCT_OFFER_MISSING: the conversion segment must "
            f"speak the project-authorized price token(s) {missing_prices}"
        )
    final_tokens = {
        token.lower()
        for token in re.findall(r"[a-z][a-z'-]{3,}", final_dialogue.lower())
    }
    cta_terms = {
        str(token).strip().lower()
        for token in list(contract.get("required_cta_terms") or [])
        if str(token).strip()
    }
    required_cta_count = int(contract.get("required_cta_term_count") or 0)
    if len(final_tokens & cta_terms) < required_cta_count:
        raise ValueError(
            "CREATIVE_FINAL_PRODUCT_OFFER_MISSING: the conversion segment must "
            "preserve the configured CTA destination/action"
        )
    if bool(contract.get("require_post_cta_agency_ending")):
        cta_matches = [
            match
            for token in cta_terms
            for match in re.finditer(
                rf"(?<![a-z0-9]){re.escape(token)}(?![a-z0-9])",
                final_dialogue.lower(),
            )
        ]
        post_cta_text = (
            final_dialogue[max(match.end() for match in cta_matches):].strip()
            if cta_matches
            else ""
        )
        post_cta_words = re.findall(
            r"[a-z0-9][a-z0-9'-]*",
            post_cta_text.lower(),
        )
        agency_terms = {
            str(token).strip().lower()
            for token in list(contract.get("post_cta_agency_terms") or [])
            if str(token).strip()
        }
        agency_matches = {
            token
            for token in agency_terms
            if re.search(
                rf"(?<![a-z0-9]){re.escape(token)}(?:s|d|ed|ing)?(?![a-z0-9])",
                post_cta_text.lower(),
            )
        }
        required_agency_count = int(
            contract.get("required_post_cta_agency_term_count") or 0
        )
        minimum_post_cta_words = int(
            contract.get("minimum_post_cta_word_count") or 0
        )
        if (
            len(agency_matches) < required_agency_count
            or len(post_cta_words) < minimum_post_cta_words
        ):
            raise ValueError(
                "CREATIVE_FINAL_AGENCY_TIEBACK_MISSING: after the configured "
                "CTA, the conversion segment must end with a separate human-"
                "agency clause using the project-configured agency vocabulary; "
                "the product cannot be written as the cause that prevents or "
                "repairs the opening loss"
            )
    if bool(contract.get("require_causal_product_bridge")):
        bridge_source_segment = max(
            1,
            min(
                expected_count,
                int(
                    contract.get("bridge_source_segment")
                    or max(1, conversion_segment - 1)
                ),
            ),
        )
        bridge_dialogue = " ".join(
            str(item.get("line") or "")
            for item in list(
                segments[bridge_source_segment - 1].get("dialogue_lines") or []
            )
            if isinstance(item, dict)
        ).strip()
        bridge_overlap = (
            _creative_bridge_tokens(bridge_dialogue)
            & _creative_bridge_tokens(final_dialogue)
        )
        product_role_terms = {
            str(token).strip().lower()
            for token in list(contract.get("product_role_terms") or [])
            if str(token).strip()
        }
        required_role_count = int(
            contract.get("required_product_role_term_count") or 0
        )
        role_matches = {
            token
            for token in product_role_terms
            if re.search(
                rf"(?<![a-z0-9]){re.escape(token)}(?:s|d|ed|ing)?(?![a-z0-9])",
                final_dialogue.lower(),
            )
        }
        if not bridge_overlap or len(role_matches) < required_role_count:
            raise ValueError(
                "CREATIVE_CONVERSION_BRIDGE_CAUSAL_LINK_MISSING: the conversion "
                "segment must carry forward a concrete phrase from the preceding "
                "recognition/solution principle and position the product as one "
                "configured step or part of that choice, not jump from story to "
                "price and CTA"
            )
    if not bool(contract.get("require_opening_tieback")):
        return
    tieback_source_indices = [
        int(index)
        for index in list(contract.get("tieback_source_segments") or [])
        if str(index).isdigit() and 1 <= int(index) <= expected_count
    ]
    opening_text = " ".join(
        _creative_conversion_segment_text(segments[index - 1])
        for index in tieback_source_indices
    )
    project_stopwords = _project_creative_duplicate_stopwords(project)
    project_stopwords.update(
        str(token).strip().lower()
        for token in list(contract.get("post_cta_agency_terms") or [])
        if str(token).strip()
    )
    tieback_tokens = (
        _creative_tieback_tokens(opening_text, project_stopwords)
        & _creative_tieback_tokens(final_dialogue, project_stopwords)
    )
    if not tieback_tokens:
        raise ValueError(
            "CREATIVE_FINAL_REGRET_TIEBACK_MISSING: the conversion segment must repeat a "
            "concrete person, relationship, object, trust, or life moment from "
            "the project-configured tieback source instead of ending with a "
            "detached product catalog"
        )


def _normalize_creative_video_blueprint(
    project: HermesContentFactoryProject,
    result: dict[str, Any],
    *,
    stage_input: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Validate the complete story once, before any segment prompt is produced."""
    normalized = dict(result or {})
    language = _configured_video_language(project)
    raw_script = normalized.get("complete_video_script")
    director_locked = bool(
        isinstance(normalized.get("director_lock"), dict)
        and normalized.get("director_lock")
    )
    if isinstance(raw_script, list):
        script = {"segments": list(raw_script)}
    elif isinstance(raw_script, dict):
        script = dict(raw_script)
    else:
        raise ValueError("CREATIVE complete_video_script must be an object")
    benchmark_analysis = _benchmark_video_analysis(project)
    imitation_mode = benchmark_imitation_mode(
        _project_requirement_text(project),
        has_benchmark=benchmark_analysis.get("status") == "success",
        transformation_contract=_project_transformation_contract(project),
    )
    expected_duration = _normalize_model_duration(
        project,
        script.get("duration_seconds")
        or script.get("total_duration_seconds")
        or normalized.get("recommended_duration_seconds"),
    )
    expected_durations = _segment_durations_for_project(project, expected_duration)
    raw_segments = list(
        script.get("segments") or script.get("segment_assignments")
        or script.get("ordered_segment_assignments") or []
    )
    audio_mode = str(script.get("audio_mode") or "spoken").strip().lower()
    if audio_mode not in {"spoken", "silent", "music_only", "sound_design"}:
        raise ValueError(
            f"CREATIVE audio_mode is unsupported: {audio_mode}"
        )
    voice_bible = (
        _normalize_voice_bible(
            normalized.get("voice_bible"),
            language,
            fallback_speakers=_script_speaker_candidates(raw_segments),
        )
        if audio_mode == "spoken"
        else {
            "audio_mode": audio_mode,
            "primary_speaker_id": None,
            "speakers": [],
        }
    )
    voice_by_id = {item["speaker_id"]: item for item in voice_bible["speakers"]}
    single_narrator_required = bool(re.search(
        r"\bexactly\s+one\s+adult\s+(?:us-english\s+)?narrator\b|"
        r"\bonly\s+spoken\s+voice\b",
        _project_requirement_text(project),
        flags=re.IGNORECASE,
    ))
    if single_narrator_required:
        if audio_mode != "spoken":
            raise ValueError(
                "CREATIVE project requires one narrator but Director selected "
                f"audio_mode={audio_mode}"
            )
        primary_id = str(voice_bible["primary_speaker_id"])
        primary_voice = dict(voice_by_id[primary_id])
        voice_bible["speakers"] = [primary_voice]
        voice_by_id = {primary_id: primary_voice}
    if imitation_mode == "exact":
        if audio_mode != "spoken":
            raise ValueError(
                "CREATIVE exact subtitle reconstruction requires spoken "
                "audio_mode"
            )
        script, expected_duration = _canonical_exact_benchmark_script(
            project,
            normalized,
            script,
            voice_bible,
            benchmark_analysis,
        )
        ticket = dict(normalized.get("visual_job_ticket") or {})
        ticket.update({
            "duration_seconds": expected_duration,
            "segment_count": len(script["segments"]),
            "segment_duration_seconds": max(
                int(item["duration_seconds"]) for item in script["segments"]
            ),
        })
        normalized["visual_job_ticket"] = ticket
        normalized["complete_video_script"] = script
        normalized["voice_bible"] = voice_bible
        normalized["recommended_duration_seconds"] = expected_duration
        normalized["benchmark_imitation_mode"] = imitation_mode
        return _ensure_reference_plan_segment_coverage(
            normalized,
            product_allowed=_project_uses_product(project),
        )
    raw_story_source = (
        script.get("story_outline") or script.get("story_arc")
        or script.get("structure") or {}
    )
    # Some text providers use ``structure`` for a short prose description and
    # keep the actual opening/development/resolution blocks beside it. That is
    # a complete script, not a semantic failure.
    story_source = (
        dict(raw_story_source)
        if isinstance(raw_story_source, dict)
        else {}
    )

    def story_outline_text(raw: Any) -> str:
        if raw in (None, "", [], {}):
            return ""
        if isinstance(raw, str):
            return raw.strip()
        if isinstance(raw, list):
            return " ".join(
                value for value in (story_outline_text(item) for item in raw) if value
            ).strip()
        if isinstance(raw, dict):
            values: list[str] = []
            for key in (
                "story_function", "narrative_function", "summary", "description",
                "dialogue", "spoken_copy", "visual_direction", "visual_action",
                "action", "purpose",
            ):
                value = story_outline_text(raw.get(key))
                if value and value not in values:
                    values.append(value)
            return " ".join(values).strip()
        return str(raw).strip()

    def segment_summary(raw: Any) -> str:
        if not isinstance(raw, dict):
            return ""
        return str(
            raw.get("story_function") or raw.get("narrative_function")
            or raw.get("segment_goal") or raw.get("structure_role") or raw.get("visual_action")
            or raw.get("action") or raw.get("purpose")
            or raw.get("dialogue_function") or raw.get("assignment")
            or raw.get("script") or raw.get("dialogue")
            or raw.get("spoken_dialogue") or ""
        ).strip()

    raw_reference_plan = [
        dict(item)
        for item in list(
            dict(normalized.get("visual_job_ticket") or {}).get("reference_plan")
            or []
        )
        if isinstance(item, dict)
    ]

    def reference_visual_for_segment(segment_index: int) -> str:
        for position, item in enumerate(raw_reference_plan, 1):
            item_segment = _coerce_segment_number(
                item.get("segment") or item.get("segment_index"),
                position,
            )
            if item_segment != int(segment_index):
                continue
            return story_outline_text(
                item.get("single_frame_terminal_state")
                or item.get("description")
                or item.get("visual_state")
                or item.get("action")
            )
        return ""

    story_outline = {
        "opening": story_outline_text(
            story_source.get("opening") or story_source.get("setup") or script.get("opening")
        ),
        "development": story_outline_text(
            story_source.get("development") or story_source.get("middle")
            or story_source.get("escalation") or script.get("development")
        ),
        "resolution": story_outline_text(
            story_source.get("resolution") or story_source.get("ending")
            or story_source.get("payoff") or script.get("resolution")
        ),
    }
    if raw_segments:
        story_outline["opening"] = story_outline["opening"] or segment_summary(raw_segments[0])
        middle = raw_segments[1:-1] or raw_segments[:1]
        story_outline["development"] = story_outline["development"] or " ".join(
            value for value in (segment_summary(item) for item in middle) if value
        )
        story_outline["resolution"] = story_outline["resolution"] or segment_summary(raw_segments[-1])
    if any(not value for value in story_outline.values()):
        raise ValueError("CREATIVE complete_video_script must contain a complete opening, development, and resolution")
    if len(raw_segments) != len(expected_durations):
        raise ValueError(
            f"CREATIVE complete_video_script must contain exactly {len(expected_durations)} segment assignments"
        )
    total_target_edit = int(script.get("target_edit_duration_seconds") or max(1, round(expected_duration * 0.84)))
    if total_target_edit > expected_duration or total_target_edit < max(1, round(expected_duration * 0.6)):
        raise ValueError("CREATIVE target_edit_duration_seconds must reserve sensible edit headroom inside the generated duration")
    hard_spoken_budget = creative_spoken_copy_budget_limits({
        "video_language": language,
        "video_segment_durations_seconds": expected_durations,
    })
    hard_spoken_limits = {
        int(item["segment_index"]): int(item["max_units"])
        for item in list(hard_spoken_budget.get("limits") or [])
    }
    hard_spoken_unit_label = str(
        hard_spoken_budget.get("unit_label") or "spoken units"
    )
    normalized_segments: list[dict[str, Any]] = []
    seen_lines: set[str] = set()
    used_benchmark_cues: list[int] = []
    primary_id = str(voice_bible.get("primary_speaker_id") or "")
    for index, (raw_segment, duration) in enumerate(zip(raw_segments, expected_durations), 1):
        if not isinstance(raw_segment, dict):
            raise ValueError(f"CREATIVE segment assignment #{index} must be an object")
        segment_index = _coerce_segment_number(
            raw_segment.get("segment_index") or raw_segment.get("index")
            or raw_segment.get("segment"),
            index,
        )
        if segment_index != index:
            raise ValueError("CREATIVE segment assignments must be sequential and ordered")
        derived_duration = None
        try:
            start_seconds = float(raw_segment.get("start_seconds"))
            end_seconds = float(raw_segment.get("end_seconds"))
            if end_seconds > start_seconds:
                derived_duration = end_seconds - start_seconds
        except (TypeError, ValueError):
            derived_duration = None
        try:
            supplied_duration = int(float(
                raw_segment.get("duration_seconds") or derived_duration or duration
            ))
        except (TypeError, ValueError):
            supplied_duration = duration
        if supplied_duration != int(duration):
            raise ValueError(f"CREATIVE segment #{index} duration must be {duration} seconds")
        shot = _creative_shot_for_segment(normalized, index, len(expected_durations))
        story_function = str(
            raw_segment.get("story_function") or raw_segment.get("narrative_function")
            or raw_segment.get("segment_goal") or raw_segment.get("structure_role")
            or raw_segment.get("purpose")
            or raw_segment.get("dialogue_function") or raw_segment.get("assignment")
            or shot.get("purpose") or shot.get("dialogue_function")
            or shot.get("story_function")
            or _creative_positional_story_function(index, len(expected_durations))
        ).strip()
        # Providers legitimately vary between one ``visual_state`` string,
        # an ordered ``visual_beats`` array, or a per-reference description.
        # Preserve the first concrete candidate instead of falling back to the
        # story taxonomy ("Loss hook", "Knife-twist moment", ...), which is
        # not an image instruction and silently produces meaningless boards.
        story_function_key = re.sub(
            r"[^a-z0-9]+", " ", story_function.lower(),
        ).strip()
        visual_action = ""
        for candidate in (
            shot.get("visual_state"),
            shot.get("terminal_state"),
            shot.get("final_state"),
            raw_segment.get("visual_action"),
            raw_segment.get("action"),
            raw_segment.get("visual_story"),
            raw_segment.get("visual"),
            shot.get("visual_beats"),
            shot.get("beats"),
            shot.get("visual_action"),
            shot.get("visual_story"),
            shot.get("visual"),
            shot.get("visuals"),
            shot.get("action"),
            shot.get("shot"),
            shot.get("description"),
            shot.get("composition"),
            reference_visual_for_segment(index),
        ):
            candidate_text = story_outline_text(candidate)
            candidate_key = re.sub(
                r"[^a-z0-9]+", " ", candidate_text.lower(),
            ).strip()
            if candidate_text and candidate_key != story_function_key:
                visual_action = candidate_text
                break
        if _project_uses_product(project):
            visual_action = _sanitize_product_visual_action(
                visual_action,
                _product_presentation_policy(project),
            )
        if not story_function or not visual_action:
            raise ValueError(
                f"CREATIVE segment #{index} needs both a story function and "
                "concrete visual action; a story taxonomy label is not visual evidence"
            )
        dialogue_value = (
            raw_segment.get("dialogue_lines") or raw_segment.get("spoken_lines")
            or raw_segment.get("speaker_dialogue") or raw_segment.get("speaker_assignments")
            or raw_segment.get("speaker_assignment")
            or raw_segment.get("spoken_dialogue")
            or raw_segment.get("spoken_copy")
            or raw_segment.get("script") or raw_segment.get("voiceover")
            or raw_segment.get("narration") or raw_segment.get("dialogue")
        )
        raw_speaker_id = str(
            raw_segment.get("speaker_id") or raw_segment.get("speaker") or ""
        ).strip()
        if raw_speaker_id and not isinstance(dialogue_value, (dict, list)):
            dialogue_value = [{
                "speaker_id": raw_speaker_id,
                "speaker": str(raw_segment.get("speaker") or raw_speaker_id).strip(),
                "line": dialogue_value,
            }]
        dialogue = _normalized_dialogue_lines(dialogue_value)
        if (
            single_narrator_required
            and dialogue
            and not director_locked
        ):
            # The project may quote a child, partner, or colleague inside the
            # adult narration, but no secondary voice may be generated. Keep
            # the words in order and assign the whole line to the locked adult
            # narrator.
            joined_line = re.sub(
                r"\s+",
                " ",
                " ".join(str(item.get("line") or "").strip() for item in dialogue),
            ).strip()
            dialogue = [{
                "speaker_id": primary_id,
                "speaker": str(voice_by_id[primary_id]["name"]),
                "line": joined_line,
            }]
        if (
            raw_segment.get("speaker_dialogue")
            and len(dialogue) > 1
            and not director_locked
            and any(_dialogue_line_is_fragment(item.get("line") or "", language) for item in dialogue)
        ):
            # Some text APIs split one narrated sentence around a short quote.
            # Preserve the complete copy without sending syntactic fragments to
            # separate voice generations or inventing additional speaker turns.
            joined_line = re.sub(
                r"\s+",
                " ",
                " ".join(str(item.get("line") or "").strip() for item in dialogue),
            ).strip()
            dialogue = [{
                "speaker_id": primary_id,
                "speaker": str(voice_by_id[primary_id]["name"]),
                "line": joined_line,
            }]
        if audio_mode != "spoken" and dialogue:
            raise ValueError(
                f"CREATIVE segment #{index} contains spoken copy while "
                f"audio_mode={audio_mode}"
            )
        if audio_mode == "spoken" and not dialogue:
            raise ValueError(f"CREATIVE segment #{index} must receive complete spoken copy; empty dialogue segments are not allowed")
        segment_units = 0
        normalized_dialogue: list[dict[str, str]] = []
        for line_index, item in enumerate(dialogue, 1):
            line = str(item.get("line") or "").strip()
            speaker_id = str(item.get("speaker_id") or item.get("speaker") or primary_id).strip()
            if speaker_id not in voice_by_id:
                raise ValueError(f"CREATIVE segment #{index} dialogue references undefined speaker {speaker_id}")
            if _dialogue_line_is_fragment(line, language):
                raise ValueError(f"CREATIVE segment #{index} dialogue line #{line_index} is an incomplete sentence")
            fingerprint = re.sub(r"\s+", " ", line).strip().lower()
            if fingerprint in seen_lines:
                raise ValueError("CREATIVE dialogue lines must not be duplicated across segments")
            seen_lines.add(fingerprint)
            segment_units += _spoken_unit_count(line, language)
            normalized_line = {
                "speaker_id": speaker_id,
                "speaker": str(voice_by_id[speaker_id]["name"]),
                "line": line,
            }
            line_id = str(item.get("line_id") or "").strip()
            if line_id:
                normalized_line["line_id"] = line_id
            normalized_dialogue.append(normalized_line)
        hard_max_units = int(hard_spoken_limits.get(index) or 0)
        if hard_max_units > 0 and segment_units > hard_max_units:
            raise ValueError(
                f"CREATIVE segment #{index} spoken copy has {segment_units} units "
                f"but the hard maximum is {hard_max_units} "
                f"{hard_spoken_unit_label}"
            )
        segment_edit_budget = max(1.0, total_target_edit * (float(duration) / float(expected_duration)))
        if normalized_dialogue:
            slowest_rate = min(
                int(voice_by_id[item["speaker_id"]]["speech_rate"])
                for item in normalized_dialogue
            )
            capacity = max(
                1,
                int(segment_edit_budget * slowest_rate / 60.0),
            )
            # Short-form delivery can naturally run about 25% faster for a
            # dense CTA beat. Keep a bounded allowance so usable short-form
            # copy is not rejected for a few words.
            capacity_tolerance = max(2, math.ceil(capacity * 0.25))
            if segment_units > capacity + capacity_tolerance:
                raise ValueError(
                    f"CREATIVE segment #{index} spoken copy has "
                    f"{segment_units} units but only {capacity} fit its "
                    "edit-time budget (bounded tolerance "
                    f"{capacity_tolerance})"
                )
        normalized_segments.append({
            "segment_index": index,
            "duration_seconds": int(duration),
            "story_function": story_function,
            "visual_action": visual_action,
            "dialogue_lines": normalized_dialogue,
            "end_bridge": str(raw_segment.get("end_bridge") or raw_segment.get("continuity_bridge") or "").strip(),
        })
    _assert_project_creative_copy_contract(project, normalized_segments)
    script.update({
        "audio_mode": audio_mode,
        "duration_seconds": expected_duration,
        "target_edit_duration_seconds": total_target_edit,
        "story_outline": story_outline,
        "segments": normalized_segments,
    })
    normalized["complete_video_script"] = script
    normalized["voice_bible"] = voice_bible
    normalized["recommended_duration_seconds"] = expected_duration
    normalized["benchmark_imitation_mode"] = imitation_mode
    # Always rebuild the reference plan from the canonical complete script
    # before only filling coverage gaps.  Without this pass, a generic
    # provider-supplied panel (notably the conversion segment) can retain a
    # stale product-free placeholder and the authoritative uploaded package is
    # never supplied to the visual generator.
    normalized = _ensure_reference_plan(
        normalized,
        product_allowed=_project_uses_product(project),
    )
    normalized = _ensure_reference_plan_segment_coverage(
        normalized,
        product_allowed=_project_uses_product(project),
    )
    return normalized


def _creative_blueprint_for_variant(
    project: HermesContentFactoryProject,
    variant_index: int,
) -> tuple[dict[str, Any], dict[str, Any]]:
    db = object_session(project)
    if db is None:
        return {}, {}
    result = _successful_media_design_for_variant(
        db,
        project,
        variant_index=variant_index,
    )
    return (
        dict(result.get("complete_video_script") or {}),
        dict(result.get("voice_bible") or {}),
    )


def _voice_lock_for_dialogue(voice_bible: dict[str, Any], dialogue: list[dict[str, str]]) -> list[dict[str, Any]]:
    speakers = {
        str(item.get("speaker_id") or ""): dict(item)
        for item in list(dict(voice_bible or {}).get("speakers") or [])
        if isinstance(item, dict)
    }
    used = list(dict.fromkeys(str(item.get("speaker_id") or item.get("speaker") or "") for item in dialogue))
    return [speakers[speaker_id] for speaker_id in used if speaker_id in speakers]


def _spoken_dialogue_lines(value: Any) -> list[dict[str, Any]]:
    """Keep only copy that the signed plan authorizes the provider to speak.

    Director blueprints intentionally retain both spoken and display copy in
    their ordered line ledger.  Transport segments, however, expose display
    copy through ``display_lines`` for local post-production.  Treating the
    complete ledger as provider dialogue makes the video model read overlays
    aloud and can overflow an otherwise valid speech window.

    Rows without ``delivery_mode`` are retained for legacy non-Director
    projects whose dialogue schema predates the split delivery contract.
    """
    if isinstance(value, dict):
        filtered: Any = {
            key: payload
            for key, payload in value.items()
            if not isinstance(payload, dict)
            or str(
                payload.get("delivery_mode") or "spoken"
            ).strip().lower() == "spoken"
        }
    else:
        source = list(value) if isinstance(value, (list, tuple)) else [value]
        filtered = [
            payload
            for payload in source
            if not isinstance(payload, dict)
            or str(
                payload.get("delivery_mode") or "spoken"
            ).strip().lower() == "spoken"
        ]
    return _normalized_dialogue_lines(filtered)


def _dialogue_without_display_lines(
    dialogue: Any,
    display: Any,
) -> list[dict[str, Any]]:
    """Remove legacy display rows after old normalizers dropped their mode."""
    dialogue_rows = _normalized_dialogue_lines(dialogue)
    display_rows = _normalized_dialogue_lines(display)
    display_ids = {
        str(row.get("line_id") or "").strip()
        for row in display_rows
        if str(row.get("line_id") or "").strip()
    }
    display_text = {
        str(row.get("line") or "").strip()
        for row in display_rows
        if str(row.get("line") or "").strip()
    }
    return [
        row
        for row in dialogue_rows
        if not (
            (
                str(row.get("line_id") or "").strip()
                and str(row.get("line_id") or "").strip() in display_ids
            )
            or str(row.get("line") or "").strip() in display_text
        )
    ]


def _normalize_segment_timeline(
    value: Any,
    *,
    segment_duration: float,
    segment_offset: float,
    video_index: int,
    segment_index: int,
) -> list[dict[str, Any]]:
    """Normalize either segment-local or complete-video timeline coordinates."""
    def parse_second(value: Any) -> float:
        """Accept provider seconds as numbers, ``3s``, or ``M:SS`` timestamps."""
        if isinstance(value, (int, float)):
            return float(value)
        token = str(value or "").strip().lower()
        for suffix in ("seconds", "second", "s"):
            if token.endswith(suffix):
                token = token[:-len(suffix)].strip()
                break
        minute_match = re.fullmatch(r"(\d+):(\d{1,2}(?:\.\d+)?)", token)
        if minute_match:
            minutes, seconds = minute_match.groups()
            seconds_value = float(seconds)
            if seconds_value >= 60:
                raise ValueError(f"Invalid timestamp seconds: {value}")
            return float(int(minutes) * 60) + seconds_value
        return float(token)

    tolerance = 0.01
    parsed: list[tuple[float, float, dict[str, Any], str]] = []
    source_beats = list(value or [])
    for beat in source_beats:
        if not isinstance(beat, dict):
            continue
        start_value = beat.get("start_second")
        if start_value is None:
            start_value = beat.get("start_seconds")
        if start_value is None:
            start_value = beat.get("start")
        end_value = beat.get("end_second")
        if end_value is None:
            end_value = beat.get("end_seconds")
        if end_value is None:
            end_value = beat.get("end")
        if start_value is None or end_value is None:
            timecode = str(beat.get("timecode") or beat.get("time") or "").strip()
            # Text providers commonly emit decimal local ranges such as
            # ``0.0-3.0``.  The prior matcher accepted ``M:SS`` decimals but
            # accidentally rejected ordinary decimal seconds, then reported
            # the misleading "no valid positive-duration beats" error even
            # for an otherwise valid four-segment 40-second plan.
            time_token = r"(?:\d+:\d{1,2}(?:\.\d+)?|\d+(?:\.\d+)?)"
            match = re.fullmatch(
                rf"\s*({time_token})\s*(?:-|–|—|to|至)\s*({time_token})\s*(?:s|秒)?\s*",
                timecode,
                flags=re.IGNORECASE,
            )
            if match:
                start_value, end_value = match.groups()
        try:
            start_second = max(0.0, parse_second(start_value))
            end_second = max(start_second, parse_second(end_value))
        except (TypeError, ValueError):
            continue
        action = str(beat.get("action") or beat.get("visual") or "").strip()
        if action and end_second - start_second > tolerance:
            parsed.append((start_second, end_second, beat, action))
    if source_beats and not parsed:
        raise ValueError(
            f"Video #{video_index} segment #{segment_index} timeline contains no valid positive-duration beats"
        )
    if not parsed:
        return []

    local_coordinates = all(
        start_second <= segment_duration + tolerance and end_second <= segment_duration + tolerance
        for start_second, end_second, _, _ in parsed
    )
    absolute_coordinates = segment_offset > 0 and all(
        start_second >= segment_offset - tolerance
        and end_second <= segment_offset + segment_duration + tolerance
        for start_second, end_second, _, _ in parsed
    )
    if local_coordinates:
        coordinate_offset = 0.0
    elif absolute_coordinates:
        coordinate_offset = segment_offset
    else:
        raise ValueError(
            f"Video #{video_index} segment #{segment_index} timeline must use either local 0-"
            f"{segment_duration:g}s or complete-video {segment_offset:g}-"
            f"{segment_offset + segment_duration:g}s coordinates without mixing them"
        )

    normalized: list[dict[str, Any]] = []
    for start_second, end_second, beat, action in parsed:
        local_start = start_second - coordinate_offset
        local_end = end_second - coordinate_offset
        if -tolerance <= local_start < 0:
            local_start = 0.0
        if segment_duration < local_end <= segment_duration + tolerance:
            local_end = segment_duration
        if local_start < 0 or local_end > segment_duration + tolerance:
            raise ValueError(
                f"Video #{video_index} segment #{segment_index} timeline exceeds its "
                f"{segment_duration:g}-second boundary"
            )
        normalized.append({
            "start_second": local_start,
            "end_second": local_end,
            "action": action,
            # Preserve the AI-authored semantic lanes.  The provider-budget
            # compiler needs the concise subject action and explicit effect
            # transition; collapsing them into the long combined prose made
            # a head truncation retain only room descriptions.
            "subject_action": str(beat.get("subject_action") or "").strip(),
            "motion_and_transition": str(
                beat.get("motion_and_transition") or ""
            ).strip(),
            "environment": str(beat.get("environment") or "").strip(),
            "camera": str(beat.get("camera") or "").strip(),
            "dialogue_key": str(beat.get("dialogue_key") or "").strip(),
        })
    return normalized


def _video_segment_prompt_text(segment: dict[str, Any]) -> str:
    """Accept provider wording while storing one canonical segment field."""
    return str(segment.get("prompt") or segment.get("short_prompt") or "").strip()


def _canonicalize_video_prompt_result(result: dict[str, Any]) -> dict[str, Any]:
    """Normalize provider aliases before the stage envelope is persisted."""
    normalized = dict(result or {})
    videos: list[Any] = []
    for raw_video in list(normalized.get("videos") or []):
        if not isinstance(raw_video, dict):
            videos.append(raw_video)
            continue
        video = dict(raw_video)
        segments: list[Any] = []
        for raw_segment in list(video.get("segments") or []):
            if not isinstance(raw_segment, dict):
                segments.append(raw_segment)
                continue
            segment = dict(raw_segment)
            prompt = _video_segment_prompt_text(segment)
            if prompt:
                segment["prompt"] = prompt
            segment.pop("short_prompt", None)
            segments.append(segment)
        video["segments"] = segments
        videos.append(video)
    if "videos" in normalized:
        normalized["videos"] = videos
    return normalized


def _normalize_video_plan(
    project: HermesContentFactoryProject,
    envelope: dict[str, Any],
    *,
    variant_index: int | None = None,
) -> list[dict[str, Any]]:
    result = envelope.get("result") or {}
    text_to_video = (
        _configured_video_generation_mode(project) == "text_to_video"
    )
    active_variant = max(1, int(variant_index or _active_variant_index(project)))
    creative_script, voice_bible = _creative_blueprint_for_variant(project, active_variant)
    audio_mode = str(
        creative_script.get("audio_mode") or "spoken"
    ).strip().lower()
    forbid_local_display_overlays = (
        _project_forbids_local_display_overlays(project)
    )
    creative_segments = {
        int(item.get("segment_index") or index): dict(item)
        for index, item in enumerate(list(creative_script.get("segments") or []), 1)
        if isinstance(item, dict)
    }
    expected_videos = 1 if _sequential_variants_enabled(project) else _target_video_count(project)
    reference_limit = int(_video_model_policy(project)["reference_limit"])
    videos = list(result.get("videos") or [])
    if not videos:
        prompts = list(result.get("prompts") or [])
        if len(prompts) == expected_videos:
            videos = [
                {
                    "version_name": f"v{index:02d}",
                    "story_arc": str(item.get("story_arc") or item.get("prompt") or "")[:500],
                    "segments": [item],
                }
                for index, item in enumerate(prompts, 1)
                if isinstance(item, dict)
            ]
    if len(videos) > expected_videos:
        videos = videos[:expected_videos]
    if len(videos) < expected_videos:
        raise ValueError(f"VIDEO_PROMPTS must return exactly {expected_videos} complete videos")

    normalized: list[dict[str, Any]] = []
    for local_video_index, video in enumerate(videos, 1):
        video_index = active_variant if _sequential_variants_enabled(project) else local_video_index
        if not isinstance(video, dict):
            raise ValueError("Each VIDEO_PROMPTS video item must be an object")
        requested_duration = video.get("duration_seconds") or _configured_video_duration(project)
        total_duration = _normalize_model_duration(project, requested_duration)
        expected_durations = _segment_durations_for_project(project, total_duration)
        expected_segments = len(expected_durations)
        segments = list(video.get("segments") or [])
        if len(segments) != expected_segments:
            raise ValueError(
                f"Video #{video_index} must contain exactly {expected_segments} segment prompts "
                f"for {total_duration} seconds on {_video_model_policy(project)['label']}"
            )
        normalized_segments: list[dict[str, Any]] = []
        for segment_index, segment in enumerate(segments, 1):
            if not isinstance(segment, dict) or not _video_segment_prompt_text(segment):
                raise ValueError(f"Video #{video_index} segment #{segment_index} must contain prompt")
            prompt_text = _video_segment_prompt_text(segment)
            segment_goal = str(segment.get("segment_goal") or "").strip()
            visual_anchor_plan = segment.get("visual_anchor_plan")
            dialogue_lines = _spoken_dialogue_lines(
                segment.get("dialogue_lines")
            )
            creative_assignment = creative_segments.get(segment_index) or {}
            assigned_dialogue = _spoken_dialogue_lines(
                creative_assignment.get("dialogue_lines")
            )
            if audio_mode == "spoken" and assigned_dialogue:
                # Creative owns the complete spoken script. VIDEO_PROMPTS may
                # not rewrite, split, or move a sentence. Production Plan,
                # however, owns provider_dialogue vs local_voiceover and its
                # exact timing. Merge Creative's immutable wording into those
                # signed delivery rows instead of dropping the execution lane.
                delivery_by_line_id = {
                    str(item.get("line_id") or "").strip(): dict(item)
                    for item in dialogue_lines
                    if str(item.get("line_id") or "").strip()
                }
                dialogue_lines = [
                    {
                        **delivery_by_line_id.get(
                            str(item.get("line_id") or "").strip(),
                            {},
                        ),
                        **dict(item),
                    }
                    for item in assigned_dialogue
                ]
            elif audio_mode != "spoken":
                # A visual planner cannot silently turn a Director-approved
                # silent/music/sound-design video into a spoken video.
                dialogue_lines = []
            if creative_assignment.get("story_function"):
                segment_goal = str(creative_assignment["story_function"]).strip()
            negative_prompt = str(segment.get("negative_prompt") or "").strip()
            # Keep the Director/compiler's complete authoring record here.
            # This is not the provider transport payload: the latter is built
            # from the structured timeline, action, camera, dialogue and
            # continuity lanes by ``_compact_provider_segment_prompt`` and is
            # then losslessly fitted to the selected model's configured
            # prompt budget.  Rejecting this durable field at 1,800 characters
            # discarded otherwise valid segment plans before semantic
            # compaction could run, which made a complete Hermes output fail
            # merely because its explanation was detailed.
            segment_duration = float(expected_durations[segment_index - 1])
            segment_offset = float(sum(expected_durations[:segment_index - 1]))
            timeline = _normalize_segment_timeline(
                segment.get("timeline") or segment.get("time_beats") or [],
                segment_duration=segment_duration,
                segment_offset=segment_offset,
                video_index=video_index,
                segment_index=segment_index,
            )
            reference_indices = (
                []
                if text_to_video
                else list(dict.fromkeys(
                    int(value)
                    for value in list(segment.get("reference_indices") or [])
                    if str(value).strip().isdigit() and int(value) > 0
                ))[:reference_limit]
            )
            normalized_segments.append(
                {
                    "prompt": prompt_text,
                    "aspect_ratio": str(
                        segment.get("aspect_ratio")
                        or video.get("aspect_ratio")
                        or _configured_video_aspect_ratio(project)
                    ),
                    "duration": expected_durations[segment_index - 1],
                    "segment_index": segment_index,
                    "segment_count": expected_segments,
                    "reference_indices": reference_indices,
                    "continuity_note": str(segment.get("continuity_note") or "").strip(),
                    "segment_goal": segment_goal,
                    "visual_style": str(
                        segment.get("visual_style")
                        or video.get("visual_style")
                        or ""
                    ).strip(),
                    "visual_grammar": str(
                        segment.get("visual_grammar")
                        or video.get("visual_grammar")
                        or ""
                    ).strip(),
                    "visual_anchor_plan": visual_anchor_plan,
                    "timeline": timeline,
                    "pacing": str(segment.get("pacing") or "").strip(),
                    "camera_direction": str(segment.get("camera_direction") or "").strip(),
                    "dialogue_lines": dialogue_lines,
                    "display_lines": (
                        []
                        if forbid_local_display_overlays
                        else [
                            dict(item)
                            for item in list(
                                segment.get("display_lines") or []
                            )
                            if isinstance(item, dict)
                        ]
                    ),
                    "voice_lock": (
                        [
                            dict(value)
                            for value in list(segment.get("voice_lock") or [])
                            if isinstance(value, dict)
                        ]
                        or _voice_lock_for_dialogue(voice_bible, dialogue_lines)
                    ),
                    "audio_mode": audio_mode,
                    "spoken_boundary_mode": str(
                        segment.get("spoken_boundary_mode")
                        or video.get("spoken_boundary_mode")
                        or "complete_sentence"
                    ).strip().lower(),
                    "negative_prompt": negative_prompt,
                    "reference_ids": (
                        []
                        if text_to_video
                        else [
                            str(value)
                            for value in list(segment.get("reference_ids") or [])
                            if str(value).strip()
                        ]
                    ),
                    "product_anchor_required": (
                        False
                        if text_to_video
                        else bool(
                            segment.get("product_anchor_required", False)
                        )
                    ),
                    "product_render_mode": (
                        "none" if text_to_video else "provider_reference"
                    ),
                    # These fields are part of the signed local compiler
                    # output, not optional provider prose.  Dropping them
                    # here made the media ledger and the final intent
                    # guardian believe that no user requirements were
                    # attached to the generated segment even though the
                    # authoritative VIDEO_PROMPTS stage contained them.
                    "intent_manifest_sha256": str(
                        segment.get("intent_manifest_sha256")
                        or video.get("intent_manifest_sha256")
                        or ""
                    ).strip(),
                    "requirement_ids": [
                        str(value).strip()
                        for value in list(segment.get("requirement_ids") or [])
                        if str(value).strip()
                    ],
                    "requirement_contract": [
                        dict(value)
                        for value in list(segment.get("requirement_contract") or [])
                        if isinstance(value, dict)
                    ],
                    "authoritative_product_composites": [
                        dict(value)
                        for value in list(
                            segment.get("authoritative_product_composites") or []
                        )
                        if isinstance(value, dict)
                    ],
                    "continuity_dependency": str(
                        segment.get("continuity_dependency")
                        or "previous_segment"
                    ).strip().lower(),
                    "compile_source": str(
                        segment.get("compile_source") or ""
                    ).strip(),
                }
            )
        normalized.append(
            {
                "video_index": video_index,
                "version_name": str(video.get("version_name") or f"v{video_index:02d}").strip(),
                "story_arc": str(video.get("story_arc") or "").strip(),
                "cta": str(video.get("cta") or "").strip(),
                "mandatory_end_copy": video.get("mandatory_end_copy") or video.get("end_copy") or [],
                "duration_seconds": total_duration,
                "audio_mode": audio_mode,
                "spoken_boundary_mode": str(
                    video.get("spoken_boundary_mode")
                    or "complete_sentence"
                ).strip().lower(),
                "compiler_authority": dict(
                    video.get("compiler_authority") or {}
                ),
                "intent_manifest_sha256": str(
                    video.get("intent_manifest_sha256") or ""
                ).strip(),
                "intent_requirements": [
                    dict(value)
                    for value in list(video.get("intent_requirements") or [])
                    if isinstance(value, dict)
                ],
                "requirement_execution": [
                    dict(value)
                    for value in list(video.get("requirement_execution") or [])
                    if isinstance(value, dict)
                ],
                "production_requirement_execution": [
                    dict(value)
                    for value in list(
                        video.get("production_requirement_execution") or []
                    )
                    if isinstance(value, dict)
                ],
                "segments": normalized_segments,
            }
        )
    return normalized


def _video_prompt_quality_summary(
    project: HermesContentFactoryProject,
    envelope: dict[str, Any],
) -> dict[str, Any]:
    plans = _normalize_video_plan(project, envelope)
    forbidden_tokens = tuple(
        str(value).lower()
        for value in _baseline_hermes_learning()["quality_contract"]["forbidden_spoken_payload_tokens"]
    )
    segment_count = 0
    reference_counts: list[int] = []
    contaminated_segments: list[str] = []
    prompt_hashes: list[str] = []
    for video in plans:
        for segment in list(video.get("segments") or []):
            segment_count += 1
            prompt = str(segment.get("prompt") or "").strip()
            prompt_hashes.append(hashlib.sha256(prompt.encode("utf-8")).hexdigest()[:16])
            reference_counts.append(len(list(segment.get("reference_indices") or [])))
            value_texts = [
                prompt,
                str(segment.get("segment_goal") or ""),
                str(segment.get("continuity_note") or ""),
                str(segment.get("pacing") or ""),
                str(segment.get("camera_direction") or ""),
                str(segment.get("negative_prompt") or ""),
            ]
            value_texts.extend(
                str(item.get("line") or "") if isinstance(item, dict) else str(item or "")
                for item in list(segment.get("dialogue_lines") or [])
            )
            value_texts.extend(
                str(beat.get("action") or "") + " " + str(beat.get("camera") or "")
                for beat in list(segment.get("timeline") or [])
                if isinstance(beat, dict)
            )
            all_values = "\n".join(value_texts).lower()
            hits = [token for token in forbidden_tokens if token and token in all_values]
            if hits:
                contaminated_segments.append(
                    f"v{int(video.get('video_index') or 0)}s{int(segment.get('segment_index') or 0)}:{','.join(hits)}"
                )
    return {
        "video_count": len(plans),
        "segment_count": segment_count,
        "reference_counts": reference_counts,
        "max_reference_count": max(reference_counts or [0]),
        "prompt_hashes": prompt_hashes[:20],
        "contaminated_segments": contaminated_segments,
    }


def _record_stage_quality_learning(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    envelope: dict[str, Any],
    imported_assets: list[HermesContentFactoryAsset],
) -> None:
    stage = str(stage_row.stage or "")
    result = dict(envelope.get("result") or {})
    details: dict[str, Any] = {
        "attempt": int(stage_row.attempt or 1),
        "variant_index": int(_stage_variant_index(stage_row, project)),
    }
    if stage == "PRODUCTION_PLAN":
        ticket = dict(result.get("visual_job_ticket") or {})
        details["requested_reference_count"] = int(_reference_count_from_ticket(ticket) or 0)
        details["concept_count"] = len(list(result.get("concepts") or []))
    elif stage == "VISUAL_PREVIEW":
        details["captured_visual_count"] = len([
            asset for asset in imported_assets if str(asset.mime_type or "").startswith("image/")
        ])
    elif stage == "CREATIVE_REVIEW":
        details.update({
            "approved_for_split": bool(result.get("approved_for_split")),
            "approved_reference_count": int(result.get("reference_image_count") or 0),
        })
    elif stage == "FINAL_ASSETS":
        image_assets = [
            asset for asset in imported_assets if str(asset.mime_type or "").startswith("image/")
        ]
        details.update({
            "final_reference_count": len(image_assets),
            "generated_package_authority_count": sum(
                1 for asset in image_assets if "product_anchor" in _semantic_roles(asset)
            ),
        })
    elif stage == "VIDEO_PROMPTS":
        summary = _video_prompt_quality_summary(project, envelope)
        details.update(summary)
        if summary["contaminated_segments"]:
            raise ValueError(
                "VIDEO_PROMPTS_STRUCTURED_PAYLOAD_CONTAMINATION: "
                + "; ".join(summary["contaminated_segments"])
            )
    elif stage == "EDIT_PACKAGE":
        details.update({
            "has_publish_title": bool(str(result.get("publish_title") or "").strip()),
            "has_edit_guidance": bool(str(result.get("edit_guidance") or "").strip()),
            "hashtag_count": len(list(result.get("hashtags") or [])),
        })
    learning = _record_hermes_observation(
        db,
        project,
        category="stage_quality",
        outcome="success",
        stage=stage,
        details=details,
    )
    if stage == "VIDEO_PROMPTS":
        model_key = str(_video_model_policy(project).get("id") or "unknown")
        model_learning = dict(learning.get(model_key) or {})
        # This used to encode one fixed direct-response template (one CTA in
        # the final segment).  A universal content system must preserve the
        # accepted Showrunner plan instead of teaching every future project
        # the same conversion shape.
        model_learning.pop("cta_exactly_once_in_final_segment", None)
        model_learning.update({
            "last_successful_prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
            "last_prompt_quality_summary": details,
            "segment_prompt_only": True,
            "copy_delivery_lossless": True,
            "conversion_structure_owned_by_showrunner": True,
            "original_product_visual_is_only_package_authority": True,
            "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        })
        learning[model_key] = model_learning
        _persist_hermes_learning(db, project, learning)


def _reference_images_for_project(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int | None = None,
) -> list[HermesContentFactoryAsset]:
    def product_sources() -> list[HermesContentFactoryAsset]:
        if not _project_uses_product(project):
            return []
        source_assets = (
            db.query(HermesContentFactoryAsset)
            .filter(
                HermesContentFactoryAsset.project_id == project.id,
                HermesContentFactoryAsset.kind == "source",
                HermesContentFactoryAsset.mime_type.like("image/%"),
            )
            .order_by(HermesContentFactoryAsset.id.asc()).all()
        )
        anchors = [
            asset for asset in source_assets
            if _asset_role(asset) == "product_visual"
            and not any(
                token in str(asset.original_name or Path(str(asset.file_path or "")).name or "").lower()
                for token in ("supplement", "facts", "fact", "ingredient", "nutrition", "panel", "pri", "promo", "control", "sheet")
            )
        ]
        if not anchors:
            anchors = [
                asset for asset in source_assets
                if _asset_role(asset) == "product_visual"
            ]
        return anchors

    image_assets = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.mime_type.like("image/%"),
            HermesContentFactoryAsset.stage == "FINAL_ASSETS",
        )
        .order_by(HermesContentFactoryAsset.id.asc()).all()
        )
    if image_assets and _sequential_variants_enabled(project):
        selected_variant = max(1, int(variant_index or _active_variant_index(project)))
        image_assets = [
            asset for asset in image_assets
            if int(dict(asset.meta_json or {}).get("variant_index") or 1) == selected_variant
        ]
    if not image_assets:
        image_assets = product_sources()
    else:
        product_anchors = product_sources()
        existing_ids = {int(asset.id) for asset in image_assets if asset.id}
        image_assets = image_assets + [asset for asset in product_anchors if int(asset.id) not in existing_ids]
    if not image_assets:
        raise ValueError("No reference images are available for AI video generation")
    # Keep the package authority in the candidate pool even when it is appended
    # after generated anchors. _select_segment_refs applies the model limit and
    # reserves a slot for it only in product-visible segments.
    return image_assets


def _reference_videos_for_project(db, project: HermesContentFactoryProject) -> list[HermesContentFactoryAsset]:
    policy = _video_model_policy(project)
    limit = int(policy.get("reference_video_limit") or 0)
    if limit <= 0:
        return []
    return (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == project.id,
            HermesContentFactoryAsset.kind == "reference_video",
            HermesContentFactoryAsset.mime_type.like("video/%"),
        )
        .order_by(HermesContentFactoryAsset.id.desc()).limit(limit).all()
    )[::-1]


def _copy_video_refs(project: HermesContentFactoryProject, image_assets: list[HermesContentFactoryAsset]) -> list[dict[str, Any]]:
    target_dir = Path(settings.BANDIANWA_UPLOAD_STORAGE_DIR).expanduser() / f"workspace_{project.workspace_id}" / datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y%m%d") / "hermes"
    target_dir.mkdir(parents=True, exist_ok=True)
    refs = []
    for index, asset in enumerate(image_assets, 1):
        source = Path(asset.file_path)
        if not source.exists():
            continue
        target = target_dir / f"cf{project.id}_{asset.id}{source.suffix.lower()}"
        if not target.exists():
            shutil.copy2(source, target)
        target.chmod(0o644)
        is_product_anchor = asset.kind == "source" and _asset_role(asset) == "product_visual"
        semantic_roles = _semantic_roles(asset)
        if not is_product_anchor:
            # AI-generated panels may show the product to anchor a hand/action
            # or composition, but their rendered label is never packaging
            # truth. Keep the original uploaded product visual as the sole
            # product authority sent to the video provider.
            semantic_roles = [role for role in semantic_roles if role != "product_anchor"]
            if not semantic_roles:
                semantic_roles = ["action_anchor"]
        reference_segment = int(
            dict(asset.meta_json or {}).get("reference_segment") or 0
        )
        # A recurring character is a cross-segment identity anchor even when
        # the board panel was first authored for one segment. Scene and action
        # panels remain segment-local; prompt text owns their chronology.
        if "character_anchor" in semantic_roles:
            reference_segment = 0
        refs.append({
            "index": index, "path": str(target), "filename": asset.original_name,
            "content_type": asset.mime_type or mimetypes.guess_type(target.name)[0] or "image/*",
            "size_bytes": target.stat().st_size,
            "asset_id": int(asset.id or 0),
            "role": _asset_role(asset),
            "semantic_roles": semantic_roles,
            "description": str(dict(asset.meta_json or {}).get("reference_description") or ""),
            "is_product_anchor": is_product_anchor,
            "reference_segment": reference_segment,
            "product_render_mode": "provider_reference",
        })
    if not refs:
        raise ValueError("Reference image files are missing")
    return refs


def _copy_reference_videos(project: HermesContentFactoryProject, video_assets: list[HermesContentFactoryAsset]) -> list[dict[str, Any]]:
    target_dir = Path(settings.BANDIANWA_UPLOAD_STORAGE_DIR).expanduser() / f"workspace_{project.workspace_id}" / datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y%m%d") / "hermes"
    target_dir.mkdir(parents=True, exist_ok=True)
    refs = []
    for index, asset in enumerate(video_assets, 1):
        source = Path(asset.file_path)
        if not source.exists():
            continue
        target = target_dir / f"cf{project.id}_video_{asset.id}{source.suffix.lower()}"
        if not target.exists():
            shutil.copy2(source, target)
        target.chmod(0o644)
        refs.append({
            "index": index, "path": str(target), "filename": asset.original_name,
            "content_type": asset.mime_type or mimetypes.guess_type(target.name)[0] or "video/mp4",
            "size_bytes": target.stat().st_size,
        })
    return refs




def _segment_needs_product_anchor(prompt: str, selected_refs: list[dict[str, Any]]) -> bool:
    if any(bool(ref.get("is_product_anchor")) for ref in selected_refs):
        return True
    # Clause-scoped detection is essential.  A valid segment may say "no
    # product in 0-3s; reveal the bottle at 6s".  A global negative-regex early
    # return silently removed the authoritative package from exactly that
    # conversion beat.
    if unbound_product_visual_depiction_evidence(prompt):
        return True
    text = str(prompt or "")
    positive = re.compile(
        r"\b(?:show|reveal|display|feature|present|hold|holding|open|opens|"
        r"place|places|pick(?:s)?\s+up)\b[^.;|\n]{0,100}\b"
        r"(?:product|package|packaging|label|bottle|jar|tube|box|"
        r"gumm(?:y|ies)|balm|cream)\b",
        flags=re.IGNORECASE,
    )
    negative = re.compile(
        r"\b(?:do\s+not|don't|never|no|without)\b[^.;|\n]{0,80}\b"
        r"(?:show|reveal|display|product|package|bottle)\b",
        flags=re.IGNORECASE,
    )
    return any(
        positive.search(clause) and not negative.search(clause)
        for clause in re.split(r"[.;|\n]+", text)
    )


def _segment_product_visual_evidence(segment: dict[str, Any]) -> str | None:
    values: list[Any] = [
        segment.get("prompt"),
        segment.get("segment_goal"),
        segment.get("camera_direction"),
    ]
    for row in list(segment.get("timeline") or []):
        if not isinstance(row, dict):
            continue
        values.extend(
            row.get(key)
            for key in (
                "action",
                "subject_action",
                "motion_and_transition",
                "continuity_state",
                "visual_description",
            )
        )
    return next(
        (
            evidence
            for value in values
            if (
                evidence := unbound_product_visual_depiction_evidence(value)
            )
        ),
        None,
    )


def _retry_product_visual_evidence(
    input_params: dict[str, Any],
) -> str | None:
    """Re-evaluate product visibility from immutable retry evidence.

    Historical tasks can carry ``content_factory_product_required=False`` even
    though a later beat in the same segment reveals the package.  Recovery
    must not trust that stale boolean: the full Director/feasibility timeline
    is the semantic authority.  This helper intentionally examines only
    segment-local visual fields and provider prompts, never project-wide sales
    prose or product facts.
    """

    for key in (
        "content_factory_execution_feasibility_replan",
        "content_factory_segment_execution_contract",
    ):
        candidate = input_params.get(key)
        if isinstance(candidate, dict):
            evidence = _segment_product_visual_evidence(candidate)
            if evidence:
                return evidence
    # Provider packets combine visual direction with spoken copy, reviewer
    # notes and reference bindings. Product words in Dialogue/Repair/Refs are
    # not evidence that the product is visually present. Historical retries
    # used the whole packet here, so a line such as "bedtime gummy labels" or
    # a global "exact package label" repair silently changed a product-free
    # segment into a product-required segment.
    nonvisual_prefixes = (
        "dialogue:",
        "voice:",
        "audio:",
        "repair:",
        "refs:",
        "reference bindings:",
        "product:",
        "product presentation policy:",
        "script:",
        "cta:",
    )
    for key in ("content_factory_base_prompt", "prompt"):
        raw_prompt = str(input_params.get(key) or "")
        visual_prompt = "\n".join(
            line
            for line in raw_prompt.splitlines()
            if line.strip()
            and not line.strip().lower().startswith(nonvisual_prefixes)
        )
        evidence = unbound_product_visual_depiction_evidence(
            visual_prompt
        )
        if evidence:
            return evidence
    return None


def _dedupe_refs(refs: list[dict[str, Any]], limit: int) -> list[dict[str, Any]]:
    merged: list[dict[str, Any]] = []
    seen: set[str] = set()
    for ref in refs:
        key = str(ref.get("path") or ref.get("filename") or ref.get("index") or "")
        if not key or key in seen:
            continue
        seen.add(key)
        merged.append(ref)
        if len(merged) >= limit:
            break
    return merged


def _ref_has_product_role(ref: dict[str, Any]) -> bool:
    return bool(ref.get("is_product_anchor")) or "product_anchor" in list(ref.get("semantic_roles") or [])


def _ensure_product_authority_ref(
    selected_refs: list[dict[str, Any]],
    all_refs: list[dict[str, Any]],
    limit: int,
) -> list[dict[str, Any]]:
    if any(bool(ref.get("is_product_anchor")) for ref in selected_refs):
        return selected_refs
    product_anchor = next((ref for ref in all_refs if bool(ref.get("is_product_anchor"))), None)
    if product_anchor is None:
        return selected_refs
    merged = _dedupe_refs([*selected_refs, product_anchor], max(1, limit + 1))
    if len(merged) <= limit:
        return merged
    product_key = str(product_anchor.get("path") or product_anchor.get("filename") or product_anchor.get("index") or "")
    for index in range(len(merged) - 1, -1, -1):
        ref = merged[index]
        key = str(ref.get("path") or ref.get("filename") or ref.get("index") or "")
        if key != product_key and "character_anchor" not in list(ref.get("semantic_roles") or []):
            del merged[index]
            break
    while len(merged) > limit:
        for index in range(len(merged) - 1, -1, -1):
            ref = merged[index]
            key = str(ref.get("path") or ref.get("filename") or ref.get("index") or "")
            if key != product_key:
                del merged[index]
                break
        else:
            break
    return merged






def _select_segment_refs(
    refs: list[dict[str, Any]],
    reference_indices: list[int],
    limit: int = 5,
    *,
    prompt: str = "",
    product_required: bool | None = None,
    segment_index: int = 0,
    authoritative_selection: bool = False,
) -> list[dict[str, Any]]:
    needs_product = bool(product_required) if product_required is not None else _segment_needs_product_anchor(prompt, [])
    wanted = {
        int(value) for value in reference_indices
        if str(value).strip().isdigit() and int(value) > 0
    }

    def eligible(ref: dict[str, Any]) -> bool:
        return needs_product or not _ref_has_product_role(ref)

    current_segment = int(segment_index or 0)
    has_segment_assignments = any(
        int(ref.get("reference_segment") or 0) > 0 for ref in refs
    )
    exact_segment = [
        ref for ref in refs
        if eligible(ref) and current_segment > 0
        and int(ref.get("reference_segment") or 0) == current_segment
    ]
    shared = [
        ref for ref in refs
        if eligible(ref) and int(ref.get("reference_segment") or 0) == 0
    ]
    # Once the creative reference plan assigns panels to segments, an upstream
    # model cannot pull another segment's action panels back in by returning
    # every reference index. Shared (segment=0) identity/scene anchors remain
    # eligible because they intentionally span the complete video.
    allowed = (
        exact_segment + shared
        if has_segment_assignments
        else [ref for ref in refs if eligible(ref)]
    )
    selected = [
        dict(ref) for ref in allowed
        if int(ref.get("index") or 0) in wanted
    ]
    pool = list(allowed) if has_segment_assignments else [
        ref for ref in refs if eligible(ref)
    ]

    # reference_indices express preference, not permission to bypass segment
    # isolation. Repair only missing control duties and keep the upload set
    # small enough that each image has one clear job.
    if not authoritative_selection:
        for role in ("character_anchor", "scene_anchor"):
            if any(role in list(ref.get("semantic_roles") or []) for ref in selected):
                continue
            candidate = next((ref for ref in pool if role in list(ref.get("semantic_roles") or [])), None)
            if candidate is not None:
                selected.append(dict(candidate))
    # Action panels are optional candidates, not required coverage. Motion,
    # pacing, camera, dialogue and chronology are authored in the segment
    # prompt. Automatically restoring an action still can reintroduce a
    # malformed hand/body pose that the multimodal author explicitly omitted.

    selected = [dict(ref) for ref in _dedupe_refs(selected, max(1, limit))]

    # A short segment may use one identity/scene anchor and, only when the
    # signed selector explicitly keeps it, a key-pose anchor. Sending every
    # board panel makes providers blend unrelated beats. Chronology, motion,
    # pace, camera, performance and speech always remain prompt-owned. The
    # exact package source is added separately when the segment shows product.
    generated_budget = min(max(1, limit - (1 if needs_product else 0)), 4)
    if len(selected) > generated_budget:
        ranked = sorted(
            enumerate(selected),
            key=lambda item: (
                0 if int(item[1].get("reference_segment") or 0) == current_segment and current_segment else 1,
                0 if "character_anchor" in list(item[1].get("semantic_roles") or []) else 1,
                0 if "scene_anchor" in list(item[1].get("semantic_roles") or []) else 1,
                item[0],
            ),
        )
        retained: list[dict[str, Any]] = []
        covered: set[str] = set()
        required_roles = {"character_anchor", "scene_anchor"}
        remaining = [dict(ref) for _position, ref in ranked]
        while remaining and len(retained) < generated_budget and not required_roles.issubset(covered):
            best = max(
                remaining,
                key=lambda ref: len(
                    required_roles.intersection(set(ref.get("semantic_roles") or [])) - covered
                ),
            )
            retained.append(best)
            covered.update(set(best.get("semantic_roles") or []))
            remaining.remove(best)
        for ref in remaining:
            if len(retained) >= generated_budget:
                break
            retained.append(ref)
        selected = retained
    if needs_product:
        selected = _ensure_product_authority_ref(selected, refs, limit)
    for ref in selected:
        if not needs_product:
            ref["is_product_anchor"] = False
            ref["semantic_roles"] = [role for role in list(ref.get("semantic_roles") or []) if role != "product_anchor"]
    # A signed plan may intentionally use text-to-video for its opening beat
    # and introduce references only in a later segment. Returning no anchors
    # is safer than borrowing a later segment's image: route resolution can
    # select a provider that supports zero references, while cross-segment
    # fallback can leak a late product reveal into the opening.
    return selected


def _compact_prompt_text(value: Any, limit: int) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if len(text) <= limit:
        return text
    if limit <= 0:
        return ""
    candidate = text[:limit].rstrip()
    # Never manufacture an ellipsis or leave a provider token half-written.
    # Dialogue, speaker IDs and action clauses are parsed again downstream;
    # ``narr...`` stopped speaker stripping and leaked malformed metadata into
    # the actual Seedance prompt. Prefer the last complete word/phrase.
    if re.search(r"[A-Za-z0-9]$", candidate) and len(text) > limit:
        boundary = re.search(r"\s+\S*$", candidate)
        if boundary and boundary.start() >= max(1, int(limit * 0.55)):
            candidate = candidate[: boundary.start()].rstrip()
    return candidate.rstrip(" ,;:，；：")


def _compact_reference_description(value: Any) -> str:
    text = str(value or "").strip()
    fields: list[str] = []
    for key in ("shot", "action"):
        match = re.search(rf"['\"]{key}['\"]\s*:\s*['\"]([^'\"]+)", text, flags=re.IGNORECASE)
        if match:
            fields.append(match.group(1).strip())
    return _compact_prompt_text("; ".join(fields) or text, 150)


def _seedance_reference_prompt(
    prompt: str,
    refs: list[dict[str, Any]],
) -> str:
    """Bind ordered Seedance images to their narrow multimodal roles.

    Images anchor visible identity, scene, action state, and package identity;
    the AI-authored timeline and motion lines remain authoritative for motion,
    camera, effects, and pacing. Grouping identical roles keeps every alias in
    Doubao's verified 500-character budget without losing upload order.
    """

    if not refs:
        return str(prompt or "").strip()
    grouped: dict[str, list[str]] = {}
    order: list[str] = []
    role_names = {
        "character_anchor": "character",
        "scene_anchor": "scene",
        "action_anchor": "action",
        "product_anchor": "package",
    }
    for index, ref in enumerate(refs, 1):
        roles = [
            role_names[role]
            for role in list(ref.get("semantic_roles") or [])
            if role in role_names
        ]
        if ref.get("is_product_anchor") and "package" not in roles:
            roles.append("package")
        label = "+".join(dict.fromkeys(roles)) or "visual"
        grouped.setdefault(label, []).append(f"@image{index}")
        if label not in order:
            order.append(label)
    bindings = "; ".join(
        f"{','.join(grouped[label])}={label}"
        for label in order
    )
    line = (
        "Reference bindings: "
        + bindings
    )
    return str(prompt or "").strip() + "\n" + line


def _authored_reference_selection(
    authored_aliases: list[Any],
    segment_refs: list[dict[str, Any]],
    *,
    product_required: bool,
) -> tuple[list[int], list[str]]:
    """Translate the multimodal author's pixel-level choice back to plan refs.

    Product authority is fail-closed even if a model omits its alias.  Generated
    reference indices may otherwise be reduced when the inspected pixels conflict
    with the authored first state.
    """

    requested = [
        str(value or "").strip()
        for value in list(authored_aliases or [])
        if str(value or "").strip()
    ]
    if not requested:
        return [], []
    alias_to_ref = {
        f"@image{position}": ref
        for position, ref in enumerate(segment_refs, 1)
    }
    kept_refs = [
        alias_to_ref[alias]
        for alias in requested
        if alias in alias_to_ref
    ]
    if product_required:
        for ref in segment_refs:
            if bool(ref.get("is_product_anchor")) and ref not in kept_refs:
                kept_refs.append(ref)
    kept_indices = list(dict.fromkeys(
        int(ref.get("index") or 0)
        for ref in kept_refs
        if not bool(ref.get("is_product_anchor"))
        and int(ref.get("index") or 0) > 0
    ))
    kept_aliases = [
        alias
        for alias, ref in alias_to_ref.items()
        if ref in kept_refs
    ]
    return kept_indices, kept_aliases


def _provider_segment_action_text(raw: str) -> str:
    text = str(raw or "").strip()
    if not text:
        return ""
    text = re.split(
        r"\n\s*(?:Dialogue(?: lines)?|Reference use|Negative|VISUAL ANCHOR PLAN|CONTINUITY|SEGMENT SCOPE RULE|FULL VIDEO|WHOLE VIDEO)\s*:",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    text = re.sub(r"^\s*Action\s*:\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"^\s*Segment\s+\d+\s*[:.-]\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(
        r"\b(?:complete|full|whole)\s+(?:video|clip|story)\b",
        "this segment",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\b(?:from beginning to end|entire arc|all segments|every segment)\b",
        "this segment only",
        text,
        flags=re.IGNORECASE,
    )
    return re.sub(r"\s+", " ", text).strip()


def _provider_safe_base_prompt(raw: str, *, confirmed_promotion: str = "") -> str:
    text = str(raw or "").strip()
    if not text:
        return ""
    preserved_promotion = str(confirmed_promotion or "").strip()
    preserved_language = "zh-CN" if re.search(r"[\u4e00-\u9fff]", preserved_promotion) else "en-US"
    # Always remove a previously generated CTA block before rebuilding the
    # retry prompt. Only the explicit project authorization may add it back.
    text = re.sub(
        r"Required spoken(?: short-video)? CTA:\s*in the final 2 seconds, (?:an adult|the on-camera person)(?: on camera)? (?:must naturally say|naturally says) exactly:\s*\"[^\"]*\".*?(?:spoken line\.|sales pitch\.|another offer\.)\s*",
        "",
        text,
        flags=re.IGNORECASE | re.DOTALL,
    ).strip()
    text = re.sub(
        r"强制信息流口播 CTA：最后 2 秒必须由镜头内人物自然说出「[^」]*」。.*?(?:电视购物式叫卖。|同句小字幕。)\s*",
        "",
        text,
        flags=re.DOTALL,
    ).strip()
    text = re.split(
        r"\b(?:References?|Negative|SEGMENT GOAL|VISUAL ANCHOR PLAN|SEGMENT SCOPE RULE|OMNI REFERENCE BINDINGS)\s*:",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    dialogue_lines = [
        line.strip()
        for line in text.splitlines()
        if re.match(r"^\s*Dialogue\s*:", line, flags=re.IGNORECASE)
    ]
    dialogue = _compact_prompt_text(" ".join(dialogue_lines), 650)
    text_without_dialogue = "\n".join(
        line for line in text.splitlines()
        if not re.match(r"^\s*Dialogue\s*:", line, flags=re.IGNORECASE)
    )
    text = _provider_segment_action_text(text_without_dialogue) or text_without_dialogue
    text = _strip_generated_text_directions(text)
    cleaned = _compact_prompt_text(text, 1700)
    if dialogue:
        cleaned = cleaned + "\n" + dialogue
    if preserved_promotion:
        cleaned = _ensure_prompt_required_promotion(cleaned, preserved_promotion, preserved_language)
    return cleaned


def _strip_generated_text_directions(value: Any) -> str:
    """Keep selling points as speech/visual proof, never model-rendered text."""
    text = str(value or "").strip()
    if not text:
        return ""
    replacements = (
        (r"\b(?:ingredient|benefit|value)(?:/|\s+)(?:callouts?|cards?|bubbles?|labels?)\b", "spoken selling-point line"),
        (r"\b(?:floating|on-screen)\s+(?:ingredient|benefit|value)\s+(?:text|labels?|callouts?)\b", "spoken selling-point line"),
        (r"\b(?:show|add|display|render|create)\s+(?:an?\s+)?(?:caption|subtitle|text overlay|sales card|ingredient card|benefit card)s?\b", "communicate it through synchronized on-camera speech"),
        (r"(?:成分|卖点|功效)(?:气泡|短字卡|字卡|浮层|浮动标签|字幕卡)", "人物同步口播卖点"),
        (r"(?:显示|添加|生成|展示)(?:成分|卖点|功效)?(?:字幕|文字浮层|文字叠加|促销卡片|销售卡片)", "由人物同步口播表达"),
    )
    for pattern, replacement in replacements:
        text = re.sub(pattern, replacement, text, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", text).strip()


def _compact_provider_segment_prompt(
    segment: dict[str, Any],
    *,
    resolution: str,
    aspect_ratio: str = "9:16",
    language_label: str,
    requirement_contract: list[dict[str, Any]] | None = None,
    promotion: str = "",
    soft_cta: str = "",
    product_required: bool = False,
    product_name: str = "the approved product",
    product_presentation_policy: dict[str, Any] | None = None,
    audio_mode: str = "spoken",
) -> str:
    """Build a concise provider prompt from the structured Hermes segment."""
    exact_script_locked = (
        str(segment.get("compile_source") or "")
        == "signed_production_plan"
    )

    def authored_text(value: Any, legacy_limit: int) -> str:
        """Keep signed execution prose intact until the provider boundary.

        A signed production plan has already passed the Director and Critic.
        Applying field-local character slices here can turn complete actions
        into fragments (for example ``lies with``) before the real provider
        limit is even known.  The provider-aware structured compactor below is
        the single place allowed to reduce that plan.  Historical, unsigned
        payloads retain their bounded compatibility behaviour.
        """

        text = re.sub(r"\s+", " ", str(value or "")).strip()
        return text if exact_script_locked else _compact_prompt_text(
            text,
            legacy_limit,
        )

    raw = str(segment.get("prompt") or "").strip()
    first_line, _, remainder = raw.partition("\n")
    title = _compact_prompt_text(first_line or segment.get("segment_goal") or "Video segment", 90)
    action_source = _provider_segment_action_text(remainder or raw)
    action = (
        action_source
        if exact_script_locked
        else _strip_generated_text_directions(action_source)
    )
    if product_required and product_presentation_policy:
        action = _sanitize_product_visual_action(
            action,
            product_presentation_policy,
        )
    if not promotion and not exact_script_locked:
        action = _strip_unconfirmed_action_cta(action)
    goal = authored_text(segment.get("segment_goal"), 220)
    visual_style = authored_text(
        segment.get("visual_style"),
        700,
    )
    visual_grammar = authored_text(
        segment.get("visual_grammar"),
        700,
    )
    project_visual_style = authored_text(
        segment.get("project_visual_style_requirement"),
        1200,
    )
    continuity = authored_text(
        _provider_segment_action_text(
            str(segment.get("continuity_note") or "")
        ),
        240,
    )
    negative = authored_text(segment.get("negative_prompt"), 300)
    pacing = authored_text(segment.get("pacing"), 180)
    requirement_rows = [
        (
            f"{str(item.get('requirement_id') or '').strip()}: "
            f"{_compact_prompt_text(item.get('interpretation') or item.get('intent'), 360)}; "
            "observable proof: "
            + " / ".join(
                _compact_prompt_text(value, 240)
                for value in list(item.get("observable_checks") or [])[:6]
            )
        )
        for item in list(requirement_contract or [])[:32]
        if isinstance(item, dict)
        and str(item.get("requirement_id") or "").strip()
    ]
    raw_camera_direction = str(
        segment.get("camera_direction") or segment.get("camera") or ""
    ).strip()
    camera_direction = authored_text(
        raw_camera_direction
        if exact_script_locked
        else _strip_generated_text_directions(raw_camera_direction),
        220,
    )
    provider_direction = authored_text(
        segment.get("provider_direction")
        or segment.get("provider_direction_en")
        or segment.get("provider_direction_zh"),
        320,
    )
    spoken_delivery_rows = [
        dict(item)
        for item in list(segment.get("dialogue_lines") or [])[:8]
        if isinstance(item, dict)
        and str(item.get("delivery_mode") or "spoken").strip().lower()
        == "spoken"
        and str(item.get("line") or "").strip()
    ]
    local_voiceover_only = bool(spoken_delivery_rows) and all(
        str(item.get("delivery_method") or "provider_dialogue")
        .strip()
        .lower()
        == "local_voiceover"
        for item in spoken_delivery_rows
    )
    timeline_rows: list[str] = []
    motion_rows: list[str] = []
    for beat in list(segment.get("timeline") or [])[:8]:
        if not isinstance(beat, dict):
            continue
        start = float(beat.get("start_second") or 0)
        end = float(beat.get("end_second") or start)
        raw_action_text = str(
            beat.get("subject_action")
            if local_voiceover_only and beat.get("subject_action")
            else beat.get("action")
            or ""
        ).strip()
        if product_required and product_presentation_policy:
            raw_action_text = _sanitize_product_visual_action(
                raw_action_text,
                product_presentation_policy,
            )
        action_text = authored_text(
            raw_action_text
            if exact_script_locked
            else _strip_generated_text_directions(raw_action_text),
            420 if local_voiceover_only else 220,
        )
        if not promotion and not exact_script_locked:
            action_text = _strip_unconfirmed_action_cta(action_text)
        raw_camera_text = str(beat.get("camera") or "").strip()
        camera_text = authored_text(
            raw_camera_text
            if exact_script_locked
            else _strip_generated_text_directions(raw_camera_text),
            220 if local_voiceover_only else 120,
        )
        if not action_text:
            continue
        motion_text = authored_text(
            beat.get("motion_and_transition") or "",
            300 if local_voiceover_only else 180,
        )
        label = f"{start:g}-{end:g}s"
        if local_voiceover_only:
            # For the 495-character Doubao composer, one AI-authored timed
            # row must carry the action, animation/effect and camera together.
            # Keeping them in separate long paragraphs caused head truncation
            # to retain only generic scene prose and discard the actual hook.
            row = f"{label}: {action_text}"
            if motion_text:
                row += f"; FX: {motion_text}"
            if camera_text:
                row += f"; Cam: {camera_text}"
            timeline_rows.append(row)
        else:
            timeline_rows.append(
                f"{label}: {action_text}"
                + (f"; camera: {camera_text}" if camera_text else "")
            )
        if motion_text and not local_voiceover_only:
            motion_rows.append(f"{label}: {motion_text}")
    if not motion_rows:
        raw_motion_match = re.search(
            r"(?:^|\n)Motion and transition:\s*(.+?)(?:\n[A-Z][^\n:]{0,48}:|\Z)",
            raw,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if raw_motion_match:
            motion_text = _compact_prompt_text(
                raw_motion_match.group(1),
                360,
            )
            if motion_text:
                motion_rows.append(motion_text)
    dialogue_rows: list[str] = []
    provider_speaker_ids = {
        str(item.get("speaker_id") or item.get("speaker") or "").strip()
        for item in list(segment.get("dialogue_lines") or [])[:8]
        if isinstance(item, dict)
        and str(item.get("delivery_mode") or "spoken").strip().lower()
        == "spoken"
        and str(item.get("delivery_method") or "provider_dialogue")
        .strip()
        .lower()
        != "local_voiceover"
        and str(item.get("line") or "").strip()
    }
    provider_speaker_ids.discard("")
    include_speaker_labels = len(provider_speaker_ids) > 1
    structured_payload_markers = (
        "duration':", 'duration":', "characters':", 'characters":',
        "segment_index", "reference_indices", "schema_version", "content_factory_",
    )

    def valid_dialogue(value: str) -> bool:
        lowered = str(value or "").lower()
        return bool(lowered) and not any(marker in lowered for marker in structured_payload_markers)

    for item in list(segment.get("dialogue_lines") or [])[:8]:
        if isinstance(item, dict):
            if str(
                item.get("delivery_mode") or "spoken"
            ).strip().lower() != "spoken":
                continue
            if (
                str(item.get("delivery_method") or "provider_dialogue")
                .strip()
                .lower()
                == "local_voiceover"
            ):
                # The exact narration remains in the signed local delivery
                # lane.  Giving it to a video model wastes the small visual
                # prompt budget and makes release depend on unreliable native
                # speech.  Timeline/dialogue keys still synchronize action.
                continue
            # A single speaker is already governed by Voice lock. Repeating a
            # long internal speaker_id before every quote wastes the 495-char
            # Seedance lane and, after compaction, used to leak malformed
            # tokens such as ``narr...`` into the actual prompt. Only retain
            # labels when the segment truly contains a dialogue exchange.
            speaker = (
                _compact_prompt_text(
                    item.get("speaker_id") or item.get("speaker"),
                    30,
                )
                if include_speaker_labels
                else ""
            )
            # Ten seconds of concise spoken copy can legitimately exceed 140
            # characters. Truncating it with an ellipsis violates Creative's
            # authoritative complete-script contract and commonly cuts the
            # price/CTA off the final line.
            line = authored_text(item.get("line"), 320)
            if line and valid_dialogue(line):
                if (
                    not exact_script_locked
                    and not promotion
                    and _text_has_action_cta(line)
                ):
                    line = soft_cta or ""
                    if not line:
                        continue
                if (
                    not exact_script_locked
                    and promotion
                    and language_label.lower().startswith("english")
                    and re.search(r"[\u4e00-\u9fff]", line)
                ):
                    if any(marker in line for marker in ("限量", "售完", "成本价", "美元", "优惠", "立减")):
                        line = promotion
                    else:
                        continue
                dialogue_rows.append(f"{speaker}: '{line}'" if speaker else f"'{line}'")
        elif str(item or "").strip():
            line = authored_text(item, 320)
            if not valid_dialogue(line):
                continue
            if (
                not exact_script_locked
                and not promotion
                and _text_has_action_cta(line)
            ):
                line = soft_cta or ""
                if not line:
                    continue
            if (
                not exact_script_locked
                and promotion
                and language_label.lower().startswith("english")
                and re.search(r"[\u4e00-\u9fff]", line)
            ):
                if any(marker in line for marker in ("限量", "售完", "成本价", "美元", "优惠", "立减")):
                    line = promotion
                else:
                    continue
            dialogue_rows.append(line)
    dialogue_rows = list(dict.fromkeys(dialogue_rows))
    if soft_cta and not promotion and not exact_script_locked:
        normalized_soft_cta = _strip_unconfirmed_action_cta(soft_cta).lower().strip(" .。")
        if normalized_soft_cta and not any(
            normalized_soft_cta in _strip_unconfirmed_action_cta(row).lower().strip(" .。")
            for row in dialogue_rows
        ):
            dialogue_rows.append(f"CTA: '{soft_cta}'")
    voice_rows: list[str] = []
    for voice in list(segment.get("voice_lock") or [])[:4]:
        if local_voiceover_only:
            break
        if not isinstance(voice, dict):
            continue
        identity = _compact_prompt_text(
            voice.get("identity") or voice.get("name") or voice.get("speaker_id"),
            140,
        )
        gender = _compact_prompt_text(voice.get("gender"), 24).lower()
        screen_relation = _compact_prompt_text(
            voice.get("screen_relation"), 36
        ).lower()
        traits = ", ".join(
            value for value in (
                gender,
                _compact_prompt_text(voice.get("timbre"), 36),
                _compact_prompt_text(voice.get("pitch"), 24),
                _compact_prompt_text(voice.get("accent"), 32),
                _compact_prompt_text(voice.get("delivery"), 48),
            ) if value
        )
        rate = int(voice.get("speech_rate") or 0)
        rate_label = str(voice.get("speech_rate_unit") or "words_per_minute").replace("_", " ")
        authority = f"{identity}: {traits}"
        if rate > 0:
            authority += f", {rate} {rate_label}"
        if gender in {"female", "male", "androgynous"}:
            authority += (
                f". This speaker is explicitly {gender}; do not change the "
                "speaker's gender in this or any adjacent segment"
            )
        if screen_relation == "off_screen_narrator":
            authority += (
                ". This is an off-screen narrator; visible characters remain "
                "silent unless a separate voice authority explicitly assigns "
                "them dialogue"
            )
        elif screen_relation == "on_screen_character":
            authority += (
                ". This voice belongs to the visible speaking character; "
                "lip-sync only that same character"
            )
        elif screen_relation == "character_voiceover":
            authority += (
                ". This is the visible protagonist's own voiceover, not an "
                "independent narrator, even when the protagonist's lips are "
                "not visible"
            )
        voice_rows.append(authority)
    parts = [title]
    if visual_style:
        parts.append(
            "Visual style (signed whole-video contract): " + visual_style
        )
    if project_visual_style:
        parts.append(
            "Project visual-medium constraint (authoritative): "
            + project_visual_style
        )
    if timeline_rows:
        parts.append("Timeline (this segment only): " + " | ".join(timeline_rows))
    elif action:
        parts.append("Action: " + _compact_prompt_text(action, 620))
    elif goal:
        parts.append("Goal: " + goal)
    if motion_rows:
        parts.append("Motion and effects: " + " | ".join(motion_rows))
    # Timeline owns what happens. Direction owns how it feels in motion.
    # This lane must remain present even when timed rows exist; the previous
    # conditional silently removed the Director's pace and camera grammar from
    # every normal segment that had a structured timeline.
    direction_parts = []
    if provider_direction:
        direction_parts.append(provider_direction)
    else:
        if pacing:
            direction_parts.append("Pace=" + pacing)
        if camera_direction:
            direction_parts.append("Camera=" + camera_direction)
        if visual_grammar and visual_grammar != pacing:
            direction_parts.append("Edit grammar=" + visual_grammar)
        if visual_style or project_visual_style:
            direction_parts.append(
                "Style=" + (visual_style or project_visual_style)
            )
    if direction_parts:
        parts.append("Direction: " + " | ".join(direction_parts))
    if dialogue_rows:
        parts.append("Dialogue: " + " | ".join(dialogue_rows))
    if voice_rows:
        parts.append(
            "Voice lock for this segment: " + " | ".join(voice_rows)
            + ". Keep the same speaker identity, gender, timbre, pitch, accent, and delivery in every adjacent clip."
        )
    if requirement_rows:
        parts.append(
            "Signed intent requirements for this segment: "
            + " | ".join(requirement_rows)
        )
    if continuity:
        parts.append("Continuity: " + continuity)
    # The exact CTA is injected once by _ensure_prompt_required_promotion.
    # Keeping a second CTA block here previously produced duplicated or even
    # JSON-contaminated spoken lines at the provider.
    if product_required and product_presentation_policy:
        presentation_policy = dict(product_presentation_policy)
        authority_mode = str(
            presentation_policy.get("authority_mode") or ""
        ).strip()
        instructions = [
            str(value or "").strip()
            for value in list(
                presentation_policy.get("presentation_instructions") or []
            )
            if str(value or "").strip()
        ]
        categories = [
            str(value or "").strip()
            for value in list(
                presentation_policy.get("forbidden_interaction_categories")
                or []
            )
            if str(value or "").strip()
        ]
        policy_parts: list[str] = []
        if authority_mode == "uploaded_source_only":
            policy_parts.append(
                f"use the uploaded {product_name} source as the sole package authority"
            )
        policy_parts.extend(instructions)
        if categories:
            policy_parts.append(
                "forbidden interaction categories: " + ", ".join(categories)
            )
        if policy_parts:
            parts.append(
                "Product presentation policy: " + "; ".join(policy_parts) + "."
            )
    normalized_audio_mode = str(audio_mode or "spoken").strip().lower()
    if normalized_audio_mode == "spoken" and local_voiceover_only:
        parts.append(
            "Audio: visible characters remain silent with no lip-sync; use "
            "only restrained non-verbal ambience and foley. The exact signed "
            "voiceover is added during local post-production."
        )
        parts.append(
            "Do not model-render captions, overlays, sales UI, QR codes, "
            "collage, picture-in-picture, or watermark."
        )
        parts.append(f"Output: {aspect_ratio} {resolution}.")
    elif normalized_audio_mode == "spoken":
        if str(
            segment.get("spoken_boundary_mode") or ""
        ).strip().lower() == "runtime_compiled_continuation":
            parts.append(
                "Narration continuity: this exact dialogue is one lossless "
                "excerpt of a continuous voiceover across adjacent clips. "
                "If it begins or ends mid-thought, continue the same "
                "speaker, prosody, and sentence without adding a greeting, "
                "summary, concluding cadence, or any new words."
            )
        parts.append(
            "Do not model-render captions, overlays, ingredient cards, sales "
            "UI, QR codes, collage, picture-in-picture, or watermark. Preserve "
            "the exact approved dialogue; any declared local overlays are "
            "added during local post-production."
        )
        parts.append(
            f"Output: {aspect_ratio} {resolution}; spoken language "
            f"{language_label} only."
        )
    elif normalized_audio_mode == "silent":
        parts.append(
            "Output is completely silent: no dialogue, narration, vocals, "
            "music, or sound effects. No generated captions, overlays, sales "
            "UI, QR codes, collage, picture-in-picture, or watermark."
        )
        parts.append(f"Output: {aspect_ratio} {resolution}.")
    elif normalized_audio_mode == "music_only":
        parts.append(
            "Use instrumental music only. No dialogue, narration, lyrics, "
            "vocals, captions, overlays, sales UI, QR codes, collage, "
            "picture-in-picture, or watermark."
        )
        parts.append(f"Output: {aspect_ratio} {resolution}.")
    else:
        parts.append(
            "Use non-verbal sound design only. No dialogue, narration, lyrics, "
            "vocals, captions, overlays, sales UI, QR codes, collage, "
            "picture-in-picture, or watermark."
        )
        parts.append(f"Output: {aspect_ratio} {resolution}.")
    if negative:
        parts.append("Avoid: " + negative)
    return "\n".join(parts)


def _prompt_without_local_voiceover_delivery(value: Any) -> str:
    """Remove local voiceover from a frozen provider retry prompt.

    References, timeline, motion, effects, camera and continuity remain
    untouched.  Only the lane owned by deterministic local post-production is
    removed, so a provider retry cannot regress into paid speech roulette.
    """
    lines: list[str] = []
    for raw_line in str(value or "").splitlines():
        line = raw_line.strip()
        if re.match(
            r"^(?:Dialogue|Voice lock for this segment|Narration continuity|"
            r"COPY DELIVERY REPAIR)\s*(?::|\()",
            line,
            re.IGNORECASE,
        ):
            continue
        if re.match(
            r"^Output:.*spoken language\b",
            line,
            re.IGNORECASE,
        ):
            continue
        if "Preserve the exact approved dialogue" in line:
            line = line.replace(
                "Preserve the exact approved dialogue; ",
                "",
            )
        if line:
            lines.append(line)
    audio_clause = (
        "Audio: visible characters remain silent with no lip-sync; use only "
        "restrained non-verbal ambience and foley. Exact signed voiceover is "
        "added locally."
    )
    if not any("Exact signed voiceover is added locally" in row for row in lines):
        lines.append(audio_clause)
    return "\n".join(lines).strip()


def _scope_retry_prompt_to_segment_timeline(
    value: Any,
) -> str:
    """Remove inherited whole-video motion prose from a timeline retry.

    Retries preserve the signed segment prompt, but historical prompts may
    contain project-wide ``Pacing`` and ``Camera`` lines whose concrete hook
    actions belong to another segment. The timeline remains authoritative;
    only an abstract rhythm instruction is retained.
    """
    text = str(value or "").strip()
    if "Timeline (this segment only):" not in text:
        return text
    lines = [
        line
        for line in text.splitlines()
        if not re.match(r"^\s*(?:Pacing|Camera)\s*:", line, re.IGNORECASE)
    ]
    return "\n".join(lines).strip()


def _omni_reference_prompt(
    prompt: str,
    refs: list[dict[str, Any]],
    *,
    product_required: bool,
    first_frame: bool = False,
    provider_safe_retry: bool = False,
    retry_attempt: int = 0,
) -> str:
    clean = str(prompt or "")
    # Reference bindings are a transport artifact, never part of Creative's
    # durable segment prompt.  Historical retry paths sometimes promoted an
    # already-compiled provider prompt into ``content_factory_base_prompt``;
    # compiling it again then accumulated duplicate REFERENCE ANCHORS blocks
    # (and, after alias stripping, misleading empty authority sentences).
    # Always discard every prior compiled suffix and rebuild exactly one block
    # from the current ordered files below.
    clean = re.split(
        r"\n+(?:"
        r"OMNI (?:REFERENCE|OFFICIAL MEDIA) BINDINGS"
        r"|REFERENCE ANCHORS \(uploaded order is authoritative\):"
        r")",
        clean,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    # A prior compiled packet may start with a transport-only ``Refs:`` row.
    # Dependency release replaces the entire ordered reference set with a
    # continuity frame plus the still-authoritative anchors below.  Remove the
    # obsolete binding row as one unit; stripping only ``@imageN`` tokens left
    # malformed prose such as ``Refs: =character; =package`` in the paid
    # provider prompt.
    clean = re.sub(r"(?im)^\s*Refs:\s*.*(?:\n|$)", "", clean)
    clean = re.sub(r"\[#\s*(?:Sources|References)[^\]]*\]", "", clean, flags=re.IGNORECASE)
    clean = re.sub(r"@image\s*\d+|<IMAGE_REF_\d+>|<FIRST_FRAME>", "", clean, flags=re.IGNORECASE)
    clean = re.sub(r"reference\s+image\s*#?\s*\d+", "", clean, flags=re.IGNORECASE)
    # The prompt also contains Creative's signed spoken copy. Never rewrite a
    # platform name across this whole string: doing so changed the exact user
    # CTA ``TikTok Shop`` into ``short-form Shop``. Visual-style abstraction
    # belongs in upstream visual fields, while dialogue remains authoritative.
    clean = re.sub(r"\s{2,}", " ", clean).strip()
    if provider_safe_retry:
        clean = re.sub(
            r"\b(slap|slaps|slapped|swat|swats|swatted|hit|hits|hitting|fight|fighting|violent|violence|abuse|abusive)\b",
            "sharp reaction",
            clean,
            flags=re.IGNORECASE,
        )
        clean = re.sub(r"\b(non-graphic|non-injurious|physical confrontation)\b", "", clean, flags=re.IGNORECASE)
    if retry_attempt >= 2:
        clean = re.sub(
            r"\b(close-?up|punch-?in|face close-?up|explosive conflict|furious|rage|violent reaction)\b",
            "medium reaction shot",
            clean,
            flags=re.IGNORECASE,
        )
    if retry_attempt >= 3:
        clean = re.sub(
            r"\b(shout|shouts|shouting|scream|screams|screaming|strike|strikes|striking)\b",
            "react",
            clean,
            flags=re.IGNORECASE,
        )
    if not refs:
        return (
            clean
            + "\n\nOMNI MEDIA RULE: no reference image is attached for this segment. "
            "Create one stable fictional adult cast and one stable scene, and preserve them throughout this segment. "
            "Do not create collage panels, picture-in-picture, or a generic product."
        )
    bindings: list[str] = []
    role_aliases: dict[str, list[str]] = {role: [] for role in ANCHOR_ROLES}
    exact_product_aliases: list[str] = []
    for local_index, ref in enumerate(refs, 1):
        is_first_frame = first_frame and local_index == 1
        alias = f"@image{local_index}"
        roles = list(ref.get("semantic_roles") or [])
        if ref.get("is_product_anchor") and "product_anchor" not in roles:
            roles.append("product_anchor")
        if first_frame and local_index > 1:
            roles = [role for role in roles if role not in {"character_anchor", "scene_anchor"}]
        if ref.get("is_product_anchor"):
            exact_product_aliases.append(alias)
        for role in roles:
            if role in role_aliases:
                role_aliases[role].append(alias)
        role_text = ", ".join(roles) or str(ref.get("role") or "visual reference")
        description = _compact_reference_description(ref.get("description") or ref.get("filename") or "")
        first_frame_label = " FIRST_FRAME" if is_first_frame else ""
        bindings.append(f"{alias}{first_frame_label}: {role_text}" + (f"; {description}" if description else ""))

    def aliases(role: str) -> str:
        return " and ".join(role_aliases.get(role) or [])

    rules = ["REFERENCE ANCHORS (uploaded order is authoritative):", *bindings]
    if first_frame:
        rules.append(
            "Continue directly from @image1 pose, wardrobe, props, room, camera side, and lighting; do not replay the prior segment."
        )
        if len(refs) > 1:
            rules.append(
                "Other images control only named action/product roles; @image1 controls identity and scene."
            )
    else:
        rules.append("Use anchors for control only; never display them as panels or inserts.")
    if aliases("character_anchor"):
        rules.append(f"Character identity/face/hair/body/wardrobe authority: {aliases('character_anchor')}.")
    if aliases("scene_anchor"):
        rules.append(f"Room/furniture/camera-side/lighting authority: {aliases('scene_anchor')}.")
    if aliases("action_anchor"):
        rules.append(f"Key pose/action authority only: {aliases('action_anchor')}.")
    if product_required and (exact_product_aliases or role_aliases["product_anchor"]):
        product_authority = " and ".join(exact_product_aliases or role_aliases["product_anchor"])
        rules.append(
            f"Authoritative product identity reference: {product_authority}. "
            "Render the same advertised product naturally inside the current "
            "scene with coherent perspective, lighting, contact shadows, hand "
            "interaction, and occlusion. Closely preserve the package type, "
            "silhouette, cap, dominant colors, brand identity, primary label, "
            "and proportions. Minor micro-label or decorative-detail variation "
            "is acceptable, but do not redesign, substitute, duplicate, melt, "
            "or grossly deform the package. Never paste the reference image or "
            "its white background, and never turn it into a packshot card or "
            "full-frame product still."
        )
    elif aliases("product_anchor"):
        rules.append(f"{aliases('product_anchor')} is packaging authority only; do not introduce the product before the scripted product beat.")
    if provider_safe_retry:
        rules.append(
            f"PROVIDER-SAFE RETRY VARIANT {max(1, retry_attempt)}: use verbal comedy, startled reactions, and sharp gestures only. "
            "No hitting, physical contact, injury, intimidation, or abuse."
        )
    rules.append("One continuous full-frame scene; no identity/scene change, extra people/limbs, morphing, teleporting, collage, fake UI, watermark, or generic product.")
    return clean + "\n\n" + "\n".join(rules)


def _schedule_video_wait(
    db,
    project: HermesContentFactoryProject,
    *,
    countdown: int = 20,
    reason: str,
) -> str:
    # A long-running creative/API stage can commit an older project JSON
    # snapshot after this waiter has scheduled its successor.  Carry the
    # currently registered waiter id in the Celery message itself so that the
    # successor can prove it is the intended handoff even if that stale write
    # restores the predecessor id in state_json.
    prior_state = dict(project.state_json or {})
    predecessor_wait_id = str(prior_state.get("ai_video_wait_task_id") or "").strip() or None
    task = wait_for_content_factory_videos.apply_async(
        kwargs={
            "project_id": int(project.id),
            "predecessor_wait_id": predecessor_wait_id,
        },
        countdown=max(0, int(countdown)),
        queue=project_hermes_queue(project),
    )
    state = prior_state
    state["ai_video_wait_task_id"] = task.id
    state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
    state["ai_video_wait_reason"] = reason
    if reason != "waiting for the next bounded provider-priority recovery round":
        previous_lane_message = str(
            state.pop("ai_video_lane_status_message", "") or ""
        ).strip()
        state.pop("ai_video_lane_status_updated_at", None)
        state.pop("ai_video_provider_cooldown_until", None)
        if previous_lane_message and str(
            getattr(project, "last_error", None) or ""
        ).strip() == (
            previous_lane_message
        ):
            project.last_error = None
    project.state_json = state
    db.commit()
    return str(task.id)


def _set_serial_variant_progress_message(
    project: HermesContentFactoryProject,
    *,
    completed_count: int,
    target_count: int,
    guide_count: int,
) -> None:
    """Expose serial progress without hiding an actionable browser blocker.

    Video draining is project-global and can finish while a later creative
    variant is waiting for its browser fallback.  That waiter must not replace
    the login/offline instruction with a generic progress sentence: doing so
    makes a correctly paused project look inexplicably stuck in the UI.
    """
    if str(project.status or "").strip().lower() == "waiting_bridge":
        return
    project.last_error = (
        f"已完成 {completed_count}/{target_count} 条完整视频；Hermes 正在串行生成或补做缺失变体，"
        f"已完成视频已生成 {guide_count} 个对应剪辑发布指导。"
    )


def _video_wait_pause_mode(project: HermesContentFactoryProject) -> str:
    """Separate an operator pause from an automatic quality-gate pause."""
    config = dict(project.config_json or {})
    state = dict(project.state_json or {})
    status = str(project.status or "").lower()
    task_ids = list(state.get("ai_video_task_ids") or [])
    reason = str(state.get("pause_reason_code") or "").strip().lower()
    if reason == "manual":
        return "manual"
    if reason == "creative_visual_replan_exhausted":
        return "drain_submitted_video" if task_ids else "paused"

    if bool(config.get("manual_paused", False)):
        # Older deployments marked automatic quality exhaustion as a manual
        # pause. Prefer the newer quality event over an older paused_at value,
        # while keeping a newer explicit operator pause authoritative.
        quality_event = dict(state.get("creative_visual_replan_exhausted") or {})

        def _pause_time(value: Any) -> datetime | None:
            raw = str(value or "").strip()
            if not raw:
                return None
            try:
                return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
            except (TypeError, ValueError):
                return None

        quality_at = _pause_time(quality_event.get("at"))
        manual_at = _pause_time(state.get("manual_paused_at") or state.get("paused_at"))
        if quality_at is not None and (manual_at is None or quality_at >= manual_at):
            return "drain_submitted_video" if task_ids else "paused"
        return "manual"

    if status != "paused":
        return "active"
    if task_ids:
        return "drain_submitted_video"
    return "paused"


def _content_factory_retryable_video_failure(task: KieTask) -> bool:
    failure_code = _content_task_effective_failure_code(task)
    text = (
        f"{failure_code} {_content_task_effective_failure_message(task)}"
    ).lower()
    # Multimodal quality diagnostics are prose.  They legitimately use words
    # such as "insufficient" to describe weak hook transfer or incomplete
    # product identity.  Never let those words fall through to the provider
    # quota classifier: the explicit semantic failure code is authoritative
    # and these failures are precisely the evidence-backed repair lane.
    if failure_code in {
        SEGMENT_EXECUTION_QA_FAIL_CODE,
        PRODUCT_VISUAL_QA_FAIL_CODE,
        VOICE_CONTINUITY_FAIL_CODE,
        SPOKEN_COPY_FAIL_CODE,
    }:
        return True
    # Doubao rejects a visible face *reference*, not the scripted person or
    # the video request itself.  This is recoverable by preserving the
    # approved character description in text and retaining only non-human
    # anchors (especially the authoritative product package).
    if str(task.fail_code or "").strip().lower() == "doubao_face_ref_unsupported":
        return True
    prompt_or_permission_failure = (
        "modelnotopen", "model_not_open", "unauthorized", "forbidden",
        "permission", "real_person", "真人", "人脸", "prompt violation",
        "prompt_violation", "content policy violation",
        "safety policy violation", "提示词违规", "提示词违反", "内容违规",
    )
    if any(marker in text for marker in prompt_or_permission_failure):
        return False
    quota_failure = any(
        marker in text
        for marker in (
            "quota", "balance", "insufficient", "额度", "余额",
        )
    )
    if not quota_failure:
        return True
    # A lone balance failure cannot improve by resubmitting.  But when the
    # active provider reports quota only after an earlier enabled provider was
    # attempted, the logical round also contains a transient provider failure.
    # Cool down and restart the bounded priority cycle so that healthy first
    # provider gets another chance instead of letting the final quota message
    # permanently mask the earlier retryable failure.
    attempted_provider_ids = {
        int(value)
        for value in list(
            dict(get_task_local_meta(task) or {}).get(
                "attempted_provider_key_ids"
            )
            or []
        )
        if str(value).strip().isdigit()
    }
    return bool(attempted_provider_ids)


def _content_factory_local_transport_rebuild_failure(
    task: KieTask,
) -> bool:
    """Return whether Hermes can repair the task before provider I/O.

    A provider-prompt contract rejection is raised by our own final I/O fence;
    no upstream generation was attempted.  Treating it as a provider outage
    needlessly cools every compatible account and presents a false 5xx status
    to the user.  The normal fresh-task retry budget still bounds repeated
    compiler defects, but the first rebuild must run immediately.
    """

    local_meta = dict(get_task_local_meta(task) or {})
    if str(local_meta.get("content_factory_retry_prompt_compile_error") or "").strip():
        # The provider error on the task is historical.  The latest recovery
        # attempt stopped inside our prompt compiler before any provider I/O,
        # so it must never re-enter an upstream cooldown loop.
        return True
    return str(task.fail_code or "").strip().lower() in {
        PROVIDER_PROMPT_CONTRACT_FAIL_CODE,
        # Flow has already spent its bounded fresh-reCAPTCHA attempts before
        # this code reaches Hermes. A surviving request-level 400 is not an
        # account outage and must immediately enter the model-authored segment
        # repair lane instead of replaying the same request after cooldown.
        "flow_request_rejected",
    }


def _content_factory_account_rotation_failure(task: KieTask) -> bool:
    """Return whether a fresh pool account can safely replace this attempt.

    These errors are raised only after the Doubao adapter proves that the
    accepted conversation never created a video-model job and releases the
    account lease.  They are account/conversation failures, not evidence that
    every compatible provider route is unavailable.  The content factory may
    therefore create its normal fresh-id retry immediately; the per-segment
    retry budget still bounds paid submissions.
    """

    code = str(task.fail_code or "").strip().lower()
    if code == "doubao_membership_required":
        params = dict(task.input_json or {})
        try:
            duration = int(params.get("seconds") or params.get("duration") or 0)
        except (TypeError, ValueError):
            duration = 0
        # Older workers persisted the web upgrade card literally.  Inside the
        # verified free duration lane it represents an account-level capacity
        # mismatch and must rotate immediately; above ten seconds it remains a
        # genuine request-tier rejection.
        return 4 <= duration <= 10
    return code in {
        "doubao_silent_timeout",
        "doubao_text_only_response",
    }


def _normalize_segment_release_failure_code(task: KieTask) -> str:
    """Restore a precise semantic code for old/in-flight release failures.

    Workers deployed before the semantic release-code fix persisted the
    generic ``segment_release_quality_gate`` value even when their diagnostic
    already proved a product-identity rejection. Normalize from that durable
    diagnostic so an in-flight project benefits from the source fix without a
    one-row operational patch.
    """

    quality_incident = dict(
        dict(get_task_local_meta(task) or {}).get("content_quality_incident")
        or {}
    )
    quality_code = str(quality_incident.get("code") or "").strip().lower()
    if quality_code:
        return quality_code
    code = str(task.fail_code or "").strip().lower()
    diagnostic = str(task.fail_msg or "")
    if (
        code == "segment_release_quality_gate"
        and "CONTENT_PRODUCT_VIDEO_VISUAL_QA_FAILED_TASK_" in diagnostic
    ):
        return PRODUCT_VISUAL_QA_FAIL_CODE
    if (
        code == "segment_release_quality_gate"
        and "CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_" in diagnostic
    ):
        return SEGMENT_EXECUTION_QA_FAIL_CODE
    return code


def _content_task_effective_failure_code(task: KieTask) -> str:
    quality_incident = dict(
        dict(get_task_local_meta(task) or {}).get("content_quality_incident")
        or {}
    )
    return str(
        quality_incident.get("code") or task.fail_code or ""
    ).strip().lower()


def _content_task_effective_failure_message(task: KieTask) -> str:
    quality_incident = dict(
        dict(get_task_local_meta(task) or {}).get("content_quality_incident")
        or {}
    )
    return str(
        quality_incident.get("message") or task.fail_msg or ""
    ).strip()


def _content_task_has_blocking_quality_incident(task: KieTask) -> bool:
    """Identify a provider-success clip that has scoped blocking QA evidence.

    Provider transport success and content release success are independent. A
    downloaded clip keeps its successful provider state, while a blocking
    multimodal evaluation may authorize one bounded localized repair.
    """

    if str(task.state or "").strip().lower() != "success":
        return False
    incident = dict(
        dict(get_task_local_meta(task) or {}).get("content_quality_incident")
        or {}
    )
    code = str(incident.get("code") or "").strip().lower()
    message = str(incident.get("message") or "").strip()
    return bool(
        message
        and code in {
            SEGMENT_EXECUTION_QA_FAIL_CODE,
            PRODUCT_VISUAL_QA_FAIL_CODE,
            VOICE_CONTINUITY_FAIL_CODE,
            SPOKEN_COPY_FAIL_CODE,
        }
    )


def _content_task_is_final_quality_repair_candidate(task: KieTask) -> bool:
    return bool(
        str(task.state or "").strip().lower() in {"failed", "timeout"}
        or _content_task_has_blocking_quality_incident(task)
    )


def _set_content_quality_incident(
    task: KieTask,
    *,
    code: str,
    message: str,
    evidence: dict[str, Any],
) -> None:
    """Attach semantic evidence without corrupting provider transport state."""

    set_task_local_meta(
        task,
        content_quality_incident={
            "code": str(code)[:64],
            "message": str(message)[:4000],
            "evidence": dict(evidence or {}),
            "recorded_at": _stage_now().isoformat(),
        },
    )


def _quality_evaluation_sha256(
    task: KieTask,
    evidence: dict[str, Any],
) -> str:
    source_sha = str(evidence.get("source_sha256") or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", source_sha):
        return source_sha
    payload = {
        "task_id": int(task.id or 0),
        "provider_task_id": str(task.task_id or ""),
        "evidence": evidence,
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()


def _product_visual_replan_review(
    failed_meta: dict[str, Any],
    *,
    diagnostic: str,
) -> dict[str, Any]:
    """Translate the multimodal product review into recovery evidence.

    Product QA already owns the pixel-level observation.  The retry path must
    pass that evidence back to the multimodal execution Director instead of
    reducing it to a boolean flag that the provider prompt compactor can
    discard.  This helper carries only observed evidence and the requested
    repair boundary; the Director still authors the replacement choreography.
    """

    review = dict(failed_meta.get("provider_product_video_review") or {})
    observed = [
        str(value).strip()
        for value in list(review.get("observed_facts") or [])[:10]
        if str(value or "").strip()
    ]
    reasons = [
        str(value).strip()
        for value in list(review.get("blocking_reasons") or [])[:8]
        if str(value or "").strip()
    ]
    if not reasons and str(diagnostic or "").strip():
        reasons = [str(diagnostic).strip()[:1200]]
    evidence = " ".join(reasons or observed).strip()
    return {
        "policy_version": str(review.get("policy_version") or "current"),
        "blocking": True,
        "observed_execution": observed,
        "missing_planned_execution": reasons,
        "blocking_reasons": reasons,
        "repair_instruction": (
            "Re-author this segment so the authoritative uploaded product is "
            "visibly present as a physical in-scene object throughout every "
            "signed product beat, with readable identity and coherent contact, "
            "perspective, lighting, occlusion, and temporal continuity. Preserve "
            "the signed story, exact dialogue, duration, pace, and style; change "
            "only the provider-executable product choreography needed to correct "
            f"this observed defect: {evidence}"
        )[:2400],
    }


def _provider_safe_omni_retry_needed(task: KieTask) -> bool:
    text = f"{task.fail_code or ''} {task.fail_msg or ''}".lower()
    markers = (
        "public_error", "public error", "common_error", "common error", "公共错误",
        "internal", "internal error", "internal_error",
        "upstream_generation_failed", "generation failed", "生成过程中出现异常", "重新发起请求",
        "prominent_people_filter", "content policy", "policy",
        "safety", "safe", "blocked", "flagged", "review", "审核", "违规",
        "sensitive", "敏感", "sy_err:8881",
    )
    return any(marker in text for marker in markers)


def _should_retry_exhausted_content_video_after_cooldown(
    task: KieTask,
    *,
    retry_key: str,
    effective_count: int,
    retry_limit: int,
    recovery_generations: dict[str, Any],
    now: datetime,
    cooldown_seconds: int,
    recovery_limit: int = 5,
) -> bool:
    """Allow bounded provider-priority rounds after separate cooldowns.

    A transient upstream outage must stay in the provider recovery plane.  The
    old one-shot generation marker made the next 502/503 fall through to the
    complete-video target gate, which then rebuilt approved creative work.
    Count recovery rounds explicitly so every round is auditable and bounded,
    while preserving the approved Director and media contract.
    """
    failed_at = task.updated_at or task.external_complete_time or task.created_at
    if failed_at is None:
        return False
    if getattr(failed_at, "tzinfo", None) is not None:
        failed_at = failed_at.astimezone(timezone.utc).replace(tzinfo=None)
    due_at = failed_at + timedelta(seconds=max(30, int(cooldown_seconds)))
    prior = recovery_generations.get(str(retry_key))
    if isinstance(prior, dict):
        is_segment_execution_recovery = bool(
            str(task.fail_code or "").strip().lower()
            == SEGMENT_EXECUTION_QA_FAIL_CODE
            or "CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_"
            in str(task.fail_msg or "")
        )
        reference_policy_matches = bool(
            not is_segment_execution_recovery
            or str(
                prior.get("segment_execution_reference_policy_version") or ""
            ).strip()
            == SEGMENT_EXECUTION_REFERENCE_REPLAN_POLICY_VERSION
        )
        prior_policy = int(prior.get("policy_version") or 0)
        prior_rounds = (
            int(prior.get("round") or prior.get("attempt") or 1)
            if reference_policy_matches
            and prior_policy in {0, SELF_HEAL_POLICY_VERSION}
            else 0
        )
    else:
        prior_rounds = 1 if prior else 0
    return bool(
        int(retry_limit) > 0
        and int(effective_count) >= int(retry_limit)
        and prior_rounds < max(1, int(recovery_limit))
        and _content_factory_retryable_video_failure(task)
        and now >= due_at
    )


def _content_factory_provider_cycle_cooldown_elapsed(
    task: KieTask,
    *,
    now: datetime,
    cooldown_seconds: int,
) -> bool:
    """Do not start another all-provider round immediately after failure."""
    failed_at = task.updated_at or task.external_complete_time or task.created_at
    if failed_at is None:
        return False
    if getattr(failed_at, "tzinfo", None) is not None:
        failed_at = failed_at.astimezone(timezone.utc).replace(tzinfo=None)
    return now >= failed_at + timedelta(
        seconds=max(30, int(cooldown_seconds))
    )


def _content_factory_transient_retry_wait_seconds(
    project: HermesContentFactoryProject,
    failed_tasks: list[KieTask],
    *,
    now: datetime,
) -> int | None:
    """Return the next bounded retry delay for transient provider failures.

    The 20-second video waiter used to interpret "retry cooldown not elapsed"
    as "media contract exhausted" and immediately entered creative
    replenishment.  Keep retryable 5xx/network failures in WAITING_VIDEO_INPUT
    until the next provider-priority round is due.
    """
    config = dict(project.config_json or {})
    cooldown_seconds = max(
        30,
        min(
            1800,
            int(
                config.get("content_factory_video_provider_cycle_cooldown_seconds")
                or config.get("content_factory_video_exhausted_cooldown_seconds")
                or 180
            ),
        ),
    )
    recovery_limit = max(
        1,
        min(
            10,
            int(
                config.get("content_factory_video_exhausted_recovery_limit")
                or 5
            ),
        ),
    )
    state = dict(project.state_json or {})
    generations = dict(
        state.get("ai_video_exhausted_cooldown_retry_generations") or {}
    )
    delays: list[int] = []
    for task in failed_tasks:
        if _is_unreleasable_dependency_failure(task):
            continue
        if _content_factory_local_transport_rebuild_failure(task):
            # This is a local compiler/transport repair, not evidence that any
            # provider route is unhealthy.  The immediate bounded rebuild is
            # owned by ``_retry_failed_video_segments``.
            continue
        if not _content_factory_retryable_video_failure(task):
            continue
        values = dict(task.input_json or {})
        video_index = int(values.get("content_factory_video_index") or 0)
        segment_index = int(values.get("content_factory_segment_index") or 0)
        if video_index <= 0 or segment_index <= 0:
            continue
        record = generations.get(f"{video_index}:{segment_index}")
        if isinstance(record, dict):
            record_policy = int(record.get("policy_version") or 0)
            completed_rounds = (
                int(record.get("round") or record.get("attempt") or 1)
                if record_policy in {0, SELF_HEAL_POLICY_VERSION}
                else 0
            )
        else:
            completed_rounds = 1 if record else 0
        if completed_rounds >= recovery_limit:
            continue
        failed_at = task.updated_at or task.external_complete_time or task.created_at
        if failed_at is None:
            delays.append(30)
            continue
        if getattr(failed_at, "tzinfo", None) is not None:
            failed_at = failed_at.astimezone(timezone.utc).replace(tzinfo=None)
        due_at = failed_at + timedelta(seconds=cooldown_seconds)
        remaining = int(math.ceil((due_at - now).total_seconds()))
        if remaining > 0:
            delays.append(max(1, remaining))
    return min(delays) if delays else None


def _restore_failed_segment_dependencies_for_retry(
    db,
    *,
    group: dict[str, Any],
    root_segment: dict[str, Any],
    task_by_id: dict[int, KieTask],
) -> list[int]:
    """Restore only the downstream chain invalidated by the retried root."""
    root_index = int(root_segment.get("segment_index") or 0)
    restored: list[int] = []
    for segment in sorted(
        list(group.get("segments") or []),
        key=lambda item: int(item.get("segment_index") or 0),
    ):
        if int(segment.get("segment_index") or 0) <= root_index:
            continue
        task = task_by_id.get(int(segment.get("task_id") or 0))
        if task is None:
            continue
        local_meta = dict(get_task_local_meta(task) or {})
        if not (
            str(task.fail_code or "").strip().lower() == "dependency_failed"
            or local_meta.get("dependency_failed_task_id")
        ):
            continue
        task.state = "waiting_dependency"
        task.fail_code = None
        task.fail_msg = None
        set_task_local_meta(
            task,
            dependency_failed_task_id=None,
            dependency_failed_at=None,
            provider_failover_dependency_restored_at=(
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ),
        )
        segment["dependency_status"] = "waiting_previous_segment"
        segment.pop("continuity_frame", None)
        db.add(task)
        restored.append(int(task.id))
    return restored


def _is_unreleasable_dependency_failure(task: KieTask) -> bool:
    """Distinguish a current dependency failure from stale release history."""
    meta = dict(get_task_local_meta(task) or {})
    return bool(
        str(task.fail_code or "").strip().lower() == "dependency_failed"
        or (
            str(task.state or "").strip().lower() == "waiting_dependency"
            and meta.get("dependency_failed_task_id")
        )
    )


def _blocked_reference_asset_ids(state: dict[str, Any]) -> set[int]:
    blocked = {
        int(value) for value in list(state.get("ai_video_blocked_reference_asset_ids") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    for item in list(state.get("ai_video_retry_history") or []):
        repair = dict(item.get("reference_repair") or {}) if isinstance(item, dict) else {}
        asset_id = repair.get("blocked_asset_id")
        if str(asset_id or "").strip().isdigit() and int(asset_id) > 0:
            blocked.add(int(asset_id))
    return blocked


def _exclude_blocked_reference_indices_from_video_plan(
    video_plan: list[dict[str, Any]],
    all_refs: list[dict[str, Any]],
    blocked_asset_ids: set[int],
) -> set[int]:
    """Remove only operator/model-rejected anchors from a compiled plan.

    Reference indices are a narrow visual-anchor lane.  Once a source asset is
    rejected for malformed anatomy or another visible defect, leaving its old
    index in the signed plan must not stall prompt authoring or cause another
    model to reconstruct the action from that still.  Unknown indices remain
    invalid and are still rejected by the caller.
    """

    blocked_indices = {
        int(ref.get("index") or 0)
        for ref in all_refs
        if int(ref.get("asset_id") or 0) in blocked_asset_ids
        and int(ref.get("index") or 0) > 0
    }
    if not blocked_indices:
        return set()
    for planned_video in video_plan:
        for planned_segment in list(planned_video.get("segments") or []):
            planned_segment["reference_indices"] = [
                int(value)
                for value in list(planned_segment.get("reference_indices") or [])
                if str(value).strip().isdigit()
                and int(value) > 0
                and int(value) not in blocked_indices
            ]
            planned_segment["reference_selection_authoritative"] = True
    return blocked_indices


def _repair_blocked_omni_reference(
    task: KieTask,
    input_params: dict[str, Any],
    source_files: list[KieFile],
    project: HermesContentFactoryProject | None = None,
) -> tuple[dict[str, Any], list[KieFile], dict[str, Any] | None]:
    error_text = f"{task.fail_code or ''} {task.fail_msg or ''}"
    match = (
        re.search(r"(?:image\s+reference|reference\s+image)\s*#?\s*(\d+)", error_text, re.IGNORECASE)
        or re.search(r"(?:图片|图像|第)\s*#?\s*(\d+)\s*(?:张|个)?", error_text, re.IGNORECASE)
    )
    if not match or not any(
        marker in error_text.lower()
        for marker in (
            "sy_err:8881", "blocked", "flagged", "content policy", "policy",
            "sensitive", "reference upload failed", "图片被屏蔽", "图片违规", "图片审核",
        )
    ):
        return input_params, source_files, None

    blocked_index = int(match.group(1))
    image_files = [item for item in source_files if item.kind == "reference_upload"]
    video_files = [item for item in source_files if item.kind != "reference_upload"]
    refs = [dict(item) for item in list(input_params.get("reference_file_paths") or [])]
    if blocked_index < 1 or blocked_index > len(image_files) or blocked_index > len(refs):
        return input_params, source_files, None
    blocked_ref = refs[blocked_index - 1]
    if bool(blocked_ref.get("is_product_anchor")) or bool(blocked_ref.get("is_continuity_frame")):
        return input_params, source_files, None

    removed_file = image_files.pop(blocked_index - 1)
    removed_ref = refs.pop(blocked_index - 1)
    # A rejected still's semantic duty transfers to the authored text lane.
    # Never relabel a surviving image as its replacement: doing so can make a
    # scene or product anchor silently become action authority and asks the
    # provider to infer chronology from the wrong pixels.

    repaired = dict(input_params)
    repaired["reference_file_paths"] = refs
    repaired["content_factory_provider_safe_retry"] = True
    required_promotion = str(input_params.get("content_factory_required_promotion") or "").strip()
    exact_script_locked = bool(
        input_params.get("content_factory_exact_script_locked")
    )
    raw_base_prompt = str(
        input_params.get("content_factory_base_prompt")
        or input_params.get("prompt")
        or ""
    )
    safe_base_prompt = (
        raw_base_prompt
        if exact_script_locked
        else _provider_safe_base_prompt(
            raw_base_prompt,
            confirmed_promotion=required_promotion,
        )
    )
    if required_promotion and not exact_script_locked:
        safe_base_prompt = _ensure_prompt_required_promotion(
            safe_base_prompt,
            required_promotion,
            str(input_params.get("content_factory_video_language") or "en-US"),
        )
    if (
        not exact_script_locked
        and project is not None
        and bool(input_params.get("content_factory_product_required"))
    ):
        safe_base_prompt = _ensure_prompt_conversion_block(
            safe_base_prompt,
            project,
            language=str(input_params.get("content_factory_video_language") or _configured_video_language(project)),
            promotion=required_promotion,
            final_segment=True,
        )
    repaired["content_factory_base_prompt"] = safe_base_prompt
    repaired["content_factory_prompt_policy_version"] = VIDEO_PROMPT_POLICY_VERSION
    repaired["prompt"] = _omni_reference_prompt(
        safe_base_prompt,
        refs,
        product_required=any(bool(ref.get("is_product_anchor")) for ref in refs),
        first_frame=bool(repaired.get("content_factory_first_frame")),
        provider_safe_retry=True,
    )
    repaired["reference_repair"] = {
        "kind": "blocked_reference_removed",
        "blocked_index": blocked_index,
        "blocked_asset_id": removed_ref.get("asset_id"),
        "blocked_file_id": int(removed_file.id),
    }
    return repaired, [*image_files, *video_files], dict(repaired["reference_repair"])


def _normalize_omni_retry_references(
    input_params: dict[str, Any],
    source_files: list[KieFile],
    blocked_asset_ids: set[int],
    *,
    retry_attempt: int = 1,
    project: HermesContentFactoryProject | None = None,
) -> tuple[dict[str, Any], list[KieFile]]:
    """Rebuild retry media instead of copying a stale multipart payload.

    Product-authority recovery is model-neutral and therefore runs before the
    Omni-specific reference reduction.  This matters for Seedance tasks whose
    old metadata says product-free while the accepted AI timeline clearly
    reveals the product in a later beat.
    """
    normalized_input = dict(input_params)
    generation_mode = (
        _configured_video_generation_mode(project)
        if project is not None
        else str(
            normalized_input.get("content_factory_video_generation_mode")
            or "image_to_video"
        ).strip().lower()
    )
    if generation_mode == "text_to_video":
        # Text-to-video is a hard media boundary. A retry may rewrite a
        # provider-safe sentence, but it may never inherit stale reference
        # rows, continuity frames, product anchors, or uploaded video from an
        # earlier attempt.
        base_prompt = str(
            # Preserve the already validated provider packet.  The base field
            # is an earlier compilation boundary and may not yet contain the
            # final segment-scope or continuity controls.
            normalized_input.get("prompt")
            or normalized_input.get("content_factory_base_prompt")
            or ""
        ).strip()
        normalized_input.update({
            "prompt": base_prompt,
            "content_factory_base_prompt": base_prompt,
            "content_factory_video_generation_mode": "text_to_video",
            "reference_file_paths": [],
            "reference_video_file_paths": [],
            "content_factory_reference_manifest": [],
            "content_factory_reference_video_count": 0,
            "content_factory_first_frame": False,
            "content_factory_product_anchor_required": False,
            "content_factory_product_render_mode": "text_only",
            "content_factory_authoritative_product_composites": [],
            "content_factory_prompt_rewrite_attempt": int(retry_attempt),
            "content_factory_prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
            "content_factory_prompt_hash": hashlib.sha256(
                base_prompt.encode("utf-8")
            ).hexdigest(),
        })
        return normalized_input, [
            item
            for item in source_files
            if item.kind not in {
                "reference_upload", "reference_video_upload"
            }
        ]
    if (
        project is None
        or _configured_video_generation_mode(project) != "video_to_video"
    ):
        normalized_input["reference_video_file_paths"] = []
        normalized_input["content_factory_reference_video_count"] = 0
        source_files = [
            item for item in source_files
            if item.kind != "reference_video_upload"
        ]
    product_presence_decided = bool(
        normalized_input.get(
            "content_factory_product_presence_decided_by_model"
        )
    )
    product_visual_evidence = (
        None
        if product_presence_decided
        else _retry_product_visual_evidence(normalized_input)
    )
    if product_presence_decided:
        product_required = bool(
            normalized_input.get("content_factory_product_required")
            or normalized_input.get(
                "content_factory_product_anchor_required"
            )
        )
    else:
        product_required = bool(
            normalized_input.get("content_factory_product_required")
            or normalized_input.get(
                "content_factory_product_anchor_required"
            )
            or (
                project is not None
                and _project_uses_product(project)
                and bool(product_visual_evidence)
            )
        )
    if product_required:
        normalized_input["content_factory_product_required"] = True
        normalized_input["content_factory_product_anchor_required"] = True
        normalized_input["content_factory_product_render_mode"] = (
            "provider_reference"
        )
        if product_visual_evidence:
            normalized_input[
                "content_factory_product_requirement_source"
            ] = {
                "kind": "retry_segment_visual_evidence",
                "evidence": str(product_visual_evidence)[:500],
            }
    elif product_presence_decided:
        normalized_input["content_factory_product_required"] = False
        normalized_input["content_factory_product_anchor_required"] = False
        normalized_input["content_factory_product_render_mode"] = (
            "scene_reference"
            if normalized_input.get("reference_file_paths")
            else "text_only"
        )
        normalized_input.pop(
            "content_factory_product_requirement_source", None
        )
    refs = [
        dict(item)
        for item in list(normalized_input.get("reference_file_paths") or [])
        if isinstance(item, dict)
    ]

    # A retry created by an older worker may carry only the authoritative
    # product package even though the current variant already owns a clean,
    # generated character anchor.  Re-authoring the timed prompt under a new
    # policy is not sufficient in that case: text such as "the same couple"
    # cannot preserve identity without the generated anchor pixels.  Restore
    # one variant-owned character anchor before the multimodal replan so
    # references keep owning identity/scene while prompt text owns action and
    # chronology.  Never restore an uploaded source character, a blocked
    # image, or a face reference which Doubao already rejected.
    should_restore_character_anchor = bool(
        project is not None
        and generation_mode == "image_to_video"
        and not normalized_input.get(
            "content_factory_doubao_face_reference_fallback"
        )
        and not any(
            "character_anchor" in set(ref.get("semantic_roles") or [])
            for ref in refs
            if not bool(ref.get("is_product_anchor"))
        )
    )
    if should_restore_character_anchor:
        # ``object_session`` is the only authority we need here.  Requiring an
        # exact ORM class couples retry normalization to one construction path
        # and silently drops a valid generated continuity anchor for compatible
        # project objects used by repair/replay code.
        try:
            db = object_session(project)
        except (TypeError, UnmappedInstanceError):
            db = None
        if db is not None:
            all_project_refs = _copy_video_refs(
                project,
                _reference_images_for_project(
                    db,
                    project,
                    variant_index=int(
                        normalized_input.get("content_factory_video_index")
                        or _active_variant_index(project)
                    ),
                ),
            )
            character_ref = next(
                (
                    dict(ref)
                    for ref in all_project_refs
                    if not bool(ref.get("is_product_anchor"))
                    and "character_anchor"
                    in set(ref.get("semantic_roles") or [])
                    and int(ref.get("asset_id") or 0)
                    not in blocked_asset_ids
                    and Path(str(ref.get("path") or "")).is_file()
                ),
                None,
            )
            # Assets rendered under an older worker can predate the semantic
            # role fix above.  The earliest generated non-product reference is
            # still the real cross-call continuity seed used by the image
            # provider, so recover that durable pixel authority instead of
            # allowing a retry to invent a new cast or switch visual medium.
            if character_ref is None:
                continuity_candidates = [
                    dict(ref)
                    for ref in all_project_refs
                    if not bool(ref.get("is_product_anchor"))
                    and int(ref.get("asset_id") or 0) not in blocked_asset_ids
                    and Path(str(ref.get("path") or "")).is_file()
                ]
                if continuity_candidates:
                    character_ref = min(
                        continuity_candidates,
                        key=lambda ref: (
                            int(ref.get("index") or 2**31 - 1),
                            int(ref.get("asset_id") or 2**31 - 1),
                        ),
                    )
                    character_ref["semantic_roles"] = list(dict.fromkeys([
                        *list(character_ref.get("semantic_roles") or []),
                        "character_anchor",
                        "scene_anchor",
                    ]))
                    character_ref["reference_segment"] = 0
                    character_ref[
                        "recovered_generated_continuity_seed"
                    ] = True
            if character_ref is not None:
                character_asset_id = int(character_ref.get("asset_id") or 0)
                character_path = str(character_ref.get("path") or "").strip()
                existing_character_index = next(
                    (
                        index
                        for index, ref in enumerate(refs)
                        if (
                            character_asset_id > 0
                            and int(ref.get("asset_id") or 0)
                            == character_asset_id
                        )
                        or (
                            character_path
                            and str(ref.get("path") or "").strip()
                            == character_path
                        )
                    ),
                    None,
                )
                restored_file_required = existing_character_index is None
                if existing_character_index is None:
                    refs.insert(0, character_ref)
                else:
                    existing_ref = dict(refs.pop(existing_character_index))
                    existing_ref.update({
                        key: value
                        for key, value in character_ref.items()
                        if value not in (None, "", [], {})
                    })
                    existing_ref["semantic_roles"] = list(dict.fromkeys([
                        *list(existing_ref.get("semantic_roles") or []),
                        "character_anchor",
                        "scene_anchor",
                    ]))
                    refs.insert(0, existing_ref)
                existing_image_files = [
                    item for item in source_files
                    if item.kind == "reference_upload"
                ]
                other_files = [
                    item for item in source_files
                    if item.kind != "reference_upload"
                ]
                restored_file = SimpleNamespace(
                    workspace_id=int(project.workspace_id),
                    file_url=str(character_ref["path"]),
                    kind="reference_upload",
                    mime_type=str(
                        character_ref.get("content_type") or "image/*"
                    ),
                    size_bytes=int(character_ref.get("size_bytes") or 0),
                    meta_json={
                        "asset_id": int(character_ref.get("asset_id") or 0),
                        "semantic_roles": list(
                            character_ref.get("semantic_roles") or []
                        ),
                        "is_product_anchor": False,
                        "restored_for_cross_segment_character_identity": True,
                    },
                )
                source_files = (
                    [restored_file, *existing_image_files, *other_files]
                    if restored_file_required
                    else [*existing_image_files, *other_files]
                )
                normalized_input[
                    "content_factory_retry_restored_character_anchor_asset_id"
                ] = int(character_ref.get("asset_id") or 0)

    # Historical product segments may have been submitted with a generated
    # clean plate only because the old worker pasted package pixels locally.
    # A bounded retry must migrate that same logical task to the current
    # provider-reference contract instead of resubmitting a product-free
    # scene.  Recover the authoritative uploaded package from this project and
    # attach it as a normal provider upload.  This is generic project data,
    # never a product- or campaign-specific constant.
    if product_required and not any(bool(ref.get("is_product_anchor")) for ref in refs):
        db = object_session(project) if project is not None else None
        if db is None or project is None:
            raise ValueError(
                "PRODUCT_REFERENCE_MIGRATION_FAILED: product segment retry "
                "has no authoritative product anchor"
            )
        all_project_refs = _copy_video_refs(
            project,
            _reference_images_for_project(
                db,
                project,
                variant_index=int(
                    normalized_input.get("content_factory_video_index")
                    or _active_variant_index(project)
                ),
            ),
        )
        product_ref = next(
            (dict(ref) for ref in all_project_refs if bool(ref.get("is_product_anchor"))),
            None,
        )
        if product_ref is None or not Path(str(product_ref.get("path") or "")).is_file():
            raise ValueError(
                "PRODUCT_REFERENCE_MIGRATION_FAILED: authoritative uploaded "
                "product image is unavailable"
            )
        refs.append(product_ref)
        source_files = [
            *source_files,
            SimpleNamespace(
                workspace_id=int(project.workspace_id),
                file_url=str(product_ref["path"]),
                kind="reference_upload",
                mime_type=str(product_ref.get("content_type") or "image/*"),
                size_bytes=int(product_ref.get("size_bytes") or 0),
                meta_json={
                    "asset_id": int(product_ref.get("asset_id") or 0),
                    "semantic_roles": list(product_ref.get("semantic_roles") or []),
                    "is_product_anchor": True,
                    "restored_for_provider_product_reference": True,
                },
            ),
        ]
        normalized_input["content_factory_product_render_mode"] = "provider_reference"
        normalized_input["content_factory_authoritative_product_composites"] = []

    # Keep the logical reference manifest and the multipart file list in the
    # same one-to-one order.  Historical retries can contain the same local
    # image row twice even after ``reference_file_paths`` has already been
    # repaired.  Passing that stale duplicate to the provider shifts every
    # later @imageN alias and is therefore worse than a normal transport
    # failure.  Merge duplicate logical refs and then rebuild the upload rows
    # from those refs, preserving one source row per path/asset only.
    deduplicated_refs: list[dict[str, Any]] = []
    ref_positions: dict[tuple[str, Any], int] = {}
    for raw_ref in refs:
        ref = dict(raw_ref)
        ref_path = str(ref.get("path") or "").strip()
        ref_asset_id = int(ref.get("asset_id") or 0)
        identity = (
            ("path", ref_path)
            if ref_path
            else ("asset", ref_asset_id)
        )
        existing_position = ref_positions.get(identity)
        if existing_position is None:
            ref_positions[identity] = len(deduplicated_refs)
            deduplicated_refs.append(ref)
            continue
        existing = deduplicated_refs[existing_position]
        existing["semantic_roles"] = list(dict.fromkeys([
            *list(existing.get("semantic_roles") or []),
            *list(ref.get("semantic_roles") or []),
        ]))
        existing["is_product_anchor"] = bool(
            existing.get("is_product_anchor")
            or ref.get("is_product_anchor")
        )
    refs = deduplicated_refs

    image_sources = [
        item for item in source_files if item.kind == "reference_upload"
    ]
    other_sources = [
        item for item in source_files if item.kind != "reference_upload"
    ]
    ordered_image_sources: list[KieFile] = []
    used_source_positions: set[int] = set()
    for ref in refs:
        ref_path = str(ref.get("path") or "").strip()
        ref_asset_id = int(ref.get("asset_id") or 0)
        matched_position = next(
            (
                position
                for position, source in enumerate(image_sources)
                if position not in used_source_positions
                and (
                    (
                        ref_path
                        and str(source.file_url or "").strip() == ref_path
                    )
                    or (
                        ref_asset_id > 0
                        and int(
                            dict(source.meta_json or {}).get("asset_id") or 0
                        )
                        == ref_asset_id
                    )
                )
            ),
            None,
        )
        if matched_position is None:
            raise ValueError(
                "CONTENT_FACTORY_REFERENCE_SOURCE_MISSING: ordered logical "
                "reference has no matching upload row"
            )
        used_source_positions.add(matched_position)
        ordered_image_sources.append(image_sources[matched_position])
    source_files = [*ordered_image_sources, *other_sources]

    # Every provider receives the same ordered semantic manifest.  Only Omni
    # needs the extra provider-specific reduction below; Seedance and other
    # capable routes can return immediately after the missing package authority
    # has been restored.
    normalized_input["reference_file_paths"] = refs
    normalized_input["content_factory_reference_manifest"] = [
        {
            "alias": f"@image{position}",
            "asset_id": int(ref.get("asset_id") or 0),
            "filename": ref.get("filename"),
            "description": ref.get("description"),
            "semantic_roles": list(ref.get("semantic_roles") or []),
            "is_product_anchor": bool(ref.get("is_product_anchor")),
        }
        for position, ref in enumerate(refs, 1)
    ]
    if str(normalized_input.get("model") or "").strip().lower() != "omni_flash":
        return normalized_input, source_files

    has_first_frame = bool(input_params.get("content_factory_first_frame"))
    filtered_refs = [
        ref for ref in refs
        if bool(ref.get("is_continuity_frame"))
        or int(ref.get("asset_id") or 0) not in blocked_asset_ids
    ]
    continuity = next((ref for ref in filtered_refs if bool(ref.get("is_continuity_frame"))), None)
    candidates = [ref for ref in filtered_refs if not bool(ref.get("is_continuity_frame"))]

    # KYY is the automatic fallback for Omni and accepts at most five images.
    # A chained segment spends one slot on the exact preceding final frame.
    max_total = 5 if str(input_params.get("service_provider") or "auto").lower() in {"auto", "kyy"} else 7
    available_slots = max(0, max_total - (1 if continuity is not None else 0))
    declared_base_prompt = str(normalized_input.get("content_factory_base_prompt") or normalized_input.get("prompt") or "")
    if not product_required:
        candidates = [ref for ref in candidates if not bool(ref.get("is_product_anchor"))]
        for ref in candidates:
            ref["semantic_roles"] = [
                role for role in list(ref.get("semantic_roles") or [])
                if role != "product_anchor"
            ]
    exact_product = next((ref for ref in candidates if bool(ref.get("is_product_anchor"))), None)

    selected: list[dict[str, Any]] = []
    uncovered = {"character_anchor", "scene_anchor", "action_anchor"}
    pool = list(candidates)
    while pool and uncovered and len(selected) < available_slots:
        best = max(
            pool,
            key=lambda ref: len(uncovered.intersection(set(ref.get("semantic_roles") or []))),
        )
        covered = uncovered.intersection(set(best.get("semantic_roles") or []))
        if not covered:
            break
        selected.append(best)
        pool.remove(best)
        uncovered.difference_update(covered)

    if product_required and exact_product is not None and exact_product not in selected:
        if len(selected) >= available_slots and selected:
            selected[-1] = exact_product
        elif len(selected) < available_slots:
            selected.append(exact_product)
    for ref in candidates:
        if len(selected) >= available_slots:
            break
        if ref not in selected:
            selected.append(ref)

    # Public/safety errors need materially different media, not the same five
    # portraits resubmitted under a cosmetically changed sentence.
    progressive_limit = 4 if retry_attempt <= 1 else (3 if retry_attempt == 2 else 2)
    selected = selected[: min(available_slots, progressive_limit)]
    if (
        product_required
        and exact_product is not None
        and exact_product not in selected
        and available_slots > 0
    ):
        if selected:
            selected[-1] = exact_product
        else:
            selected.append(exact_product)

    normalized_refs = ([continuity] if continuity is not None else []) + selected
    normalized = normalized_input
    normalized["content_factory_product_required"] = product_required
    normalized["reference_file_paths"] = normalized_refs
    normalized["content_factory_first_frame"] = bool(continuity is not None and has_first_frame)
    required_promotion = str(normalized.get("content_factory_required_promotion") or "").strip()
    base_prompt = str(normalized.get("content_factory_base_prompt") or normalized.get("prompt") or "").strip()
    # Remove only the retired rendering implementation. The Director-owned
    # story, dialogue, offer, and CTA remain untouched.
    base_prompt = base_prompt.split("CLEAN-PLATE PRODUCT OVERRIDE:", 1)[0].strip()
    base_prompt = re.sub(
        r"\b(?:authoritative|exact)\s+(?:package|product)\s+composite\b",
        "authoritative product reference",
        base_prompt,
        flags=re.IGNORECASE,
    )
    base_prompt = re.sub(
        r"\blocal\s+(?:pixel\s+)?(?:composite|compositing|post-?production\s+insert)\b",
        "provider-rendered product",
        base_prompt,
        flags=re.IGNORECASE,
    )
    exact_script_locked = bool(
        normalized.get("content_factory_exact_script_locked")
    )
    if not exact_script_locked:
        base_prompt = _provider_safe_base_prompt(
            base_prompt,
            confirmed_promotion=required_promotion,
        )
    if bool(normalized.get("content_factory_product_visual_retry")):
        base_prompt += (
            " PRODUCT VISUAL REPAIR: keep the authoritative product anchor "
            "clearly visible during the scripted product beat and render it "
            "as a real object inside the scene. Preserve package type, "
            "silhouette, cap, dominant colors, brand identity, primary label, "
            "and proportions. Use coherent perspective, contact, lighting, "
            "occlusion, and hand interaction. Do not paste the source image or "
            "white background, create a product card, duplicate the package, "
            "or let it melt, morph, or change identity across frames."
        )
    if required_promotion and not exact_script_locked:
        base_prompt = _ensure_prompt_required_promotion(
            base_prompt,
            required_promotion,
            str(normalized.get("content_factory_video_language") or "en-US"),
        )
    if not exact_script_locked and project is not None and product_required:
        base_prompt = _ensure_prompt_conversion_block(
            base_prompt,
            project,
            language=str(normalized.get("content_factory_video_language") or _configured_video_language(project)),
            promotion=required_promotion,
            final_segment=True,
        )
    normalized["content_factory_base_prompt"] = base_prompt
    normalized["content_factory_product_render_mode"] = "provider_reference"
    normalized["content_factory_authoritative_product_composites"] = []
    provider_safe_retry = bool(normalized.get("content_factory_provider_safe_retry")) or bool(blocked_asset_ids)
    normalized["content_factory_provider_safe_retry"] = provider_safe_retry
    normalized["prompt"] = _omni_reference_prompt(
        base_prompt,
        normalized_refs,
        product_required=product_required,
        first_frame=bool(normalized["content_factory_first_frame"]),
        provider_safe_retry=provider_safe_retry,
        retry_attempt=min(3, retry_attempt),
    )
    normalized["content_factory_prompt_rewrite_attempt"] = int(retry_attempt)
    normalized["content_factory_prompt_policy_version"] = VIDEO_PROMPT_POLICY_VERSION
    normalized["content_factory_prompt_hash"] = hashlib.sha256(
        str(normalized["prompt"]).encode("utf-8")
    ).hexdigest()
    normalized["content_factory_reference_manifest"] = [
        {
            "alias": f"@image{position}",
            "asset_id": int(ref.get("asset_id") or 0),
            "filename": ref.get("filename"),
            "semantic_roles": list(ref.get("semantic_roles") or []),
            "is_product_anchor": bool(ref.get("is_product_anchor")),
        }
        for position, ref in enumerate(normalized_refs, 1)
    ]

    image_files = [item for item in source_files if item.kind == "reference_upload"]
    other_files = [item for item in source_files if item.kind != "reference_upload"]
    unused_files = list(image_files)
    selected_files: list[KieFile] = []
    for ref in normalized_refs:
        ref_path = str(ref.get("path") or "")
        ref_asset_id = int(ref.get("asset_id") or 0)
        matched = next((item for item in unused_files if str(item.file_url or "") == ref_path), None)
        if matched is None and ref_asset_id > 0:
            matched = next(
                (
                    item for item in unused_files
                    if int(dict(item.meta_json or {}).get("asset_id") or 0) == ref_asset_id
                ),
                None,
            )
        if matched is not None:
            selected_files.append(matched)
            unused_files.remove(matched)
    return normalized, [*selected_files, *other_files]


def _repair_doubao_face_reference_failure(
    failed: KieTask,
    input_params: dict[str, Any],
    source_files: list[KieFile],
) -> tuple[dict[str, Any], list[KieFile], dict[str, Any] | None]:
    """Turn a rejected face image into text-only character continuity.

    The creative contract remains authoritative.  Only the provider input
    representation changes: human/face reference pixels are removed, their
    approved visual description is carried into the segment timeline, and
    product/non-human anchors remain in the exact original order.
    """
    if str(failed.fail_code or "").strip().lower() != "doubao_face_ref_unsupported":
        return input_params, source_files, None

    normalized = dict(input_params or {})
    refs = [
        dict(item)
        for item in list(normalized.get("reference_file_paths") or [])
        if isinstance(item, dict)
    ]
    kept_refs = [ref for ref in refs if bool(ref.get("is_product_anchor"))]
    removed_refs = [ref for ref in refs if not bool(ref.get("is_product_anchor"))]
    if not removed_refs:
        return normalized, source_files, None

    character_description = re.sub(
        r"\s+",
        " ",
        " ".join(
            str(ref.get("description") or "").strip()
            for ref in removed_refs
            if str(ref.get("description") or "").strip()
        ),
    ).strip()[:700]
    continuity_clause = (
        "Character continuity: text-only, not a face identity reference; "
        + (
            character_description
            or "preserve the approved adult character, wardrobe, action, and expression from the signed segment plan"
        )
    )

    def _inject_character_continuity(value: Any) -> str:
        source = str(value or "").strip()
        lines = [
            line
            for line in source.splitlines()
            if not line.startswith("Character continuity:")
        ]
        # Character appearance and temporal action are separate semantic
        # lanes.  Putting this text into Timeline used to make the prompt
        # compactor prefer it over the authored Beats row and silently discard
        # every real action after a rejected Doubao face reference.
        insert_at = next(
            (
                index
                for index, line in enumerate(lines)
                if line.startswith(("Timeline (this segment only):", "Beats:"))
            ),
            -1,
        )
        lines.insert(insert_at + 1, continuity_clause)
        return "\n".join(lines).strip()

    normalized["prompt"] = _inject_character_continuity(normalized.get("prompt"))
    normalized["content_factory_base_prompt"] = _inject_character_continuity(
        normalized.get("content_factory_base_prompt") or normalized.get("prompt")
    )
    normalized["reference_file_paths"] = kept_refs
    normalized["content_factory_first_frame"] = False
    normalized["content_factory_doubao_face_reference_fallback"] = True

    kept_paths = {str(ref.get("path") or "") for ref in kept_refs}
    kept_asset_ids = {
        int(ref.get("asset_id") or 0)
        for ref in kept_refs
        if int(ref.get("asset_id") or 0) > 0
    }
    filtered_files: list[KieFile] = []
    for source_file in source_files:
        if source_file.kind != "reference_upload":
            filtered_files.append(source_file)
            continue
        source_asset_id = int(dict(source_file.meta_json or {}).get("asset_id") or 0)
        if (
            str(source_file.file_url or "") in kept_paths
            or source_asset_id in kept_asset_ids
        ):
            filtered_files.append(source_file)

    return normalized, filtered_files, {
        "kind": "doubao_face_reference_to_text",
        "removed_asset_ids": [
            int(ref.get("asset_id") or 0) for ref in removed_refs
        ],
        "retained_asset_ids": [
            int(ref.get("asset_id") or 0) for ref in kept_refs
        ],
        "character_description_preserved": bool(character_description),
    }


def _replace_video_task_reference_files(
    db,
    *,
    task: KieTask,
    retry_input: dict[str, Any],
    retry_files: list[KieFile],
    source_task_id: int,
) -> None:
    if int(task.id) == int(source_task_id):
        raise ValueError(
            "CONTENT_FACTORY_RETRY_TASK_ID_REUSED: a rewritten media request "
            "must own a new local task identity"
        )
    db.query(KieFile).filter(
        KieFile.task_id == int(task.id),
        KieFile.workspace_id == int(task.workspace_id),
        KieFile.kind.in_(("reference_upload", "reference_video_upload", "result", "result_watermark")),
    ).delete(synchronize_session=False)
    image_position = 0
    repaired_refs = list(retry_input.get("reference_file_paths") or [])
    for source_file in retry_files:
        source_meta = dict(source_file.meta_json or {})
        if source_file.kind == "reference_upload":
            image_position += 1
            ref_meta = repaired_refs[image_position - 1] if image_position <= len(repaired_refs) else {}
            has_first_frame = bool(retry_input.get("content_factory_first_frame"))
            is_first_frame = has_first_frame and image_position == 1
            source_meta.update({
                "omni_alias": "@image1" if is_first_frame else f"@image{image_position}",
                "provider_alias": "<FIRST_FRAME>" if is_first_frame else f"<IMAGE_REF_{image_position - (2 if has_first_frame else 1)}>",
                "semantic_roles": list(ref_meta.get("semantic_roles") or []),
                "is_product_anchor": bool(ref_meta.get("is_product_anchor")),
            })
        db.add(KieFile(
            workspace_id=source_file.workspace_id,
            key_id=task.key_id,
            task_id=task.id,
            file_url=source_file.file_url,
            kind=source_file.kind,
            mime_type=source_file.mime_type,
            size_bytes=source_file.size_bytes,
            meta_json={
                **source_meta,
                "content_factory_retry_source_task_id": int(source_task_id),
            },
        ))
    db.flush()


def _append_content_segment_retry_attempt(
    db,
    *,
    project: HermesContentFactoryProject,
    failed_task: KieTask,
    retry_task: KieTask,
    segment: dict[str, Any],
    provider_key: str,
) -> None:
    """Append an immutable segment attempt for one replacement task.

    The group pointer selects the active attempt used for composition, while
    this ledger preserves the rejected/failed provider result and the exact
    replacement which superseded it.  A rewritten request must never overwrite
    the old row or inherit its provider idempotency identity.
    """
    prior = (
        db.query(HermesContentSegmentRun)
        .filter(
            HermesContentSegmentRun.project_id == int(project.id),
            HermesContentSegmentRun.workspace_id == int(project.workspace_id),
            HermesContentSegmentRun.provider_task_row_id == int(failed_task.id),
        )
        .order_by(HermesContentSegmentRun.attempt.desc())
        .first()
    )
    if prior is None:
        return
    now = _stage_now()
    prior.state = "failed"
    prior.error_class = str(
        failed_task.fail_code or "content_factory_retry_replaced"
    )[:96]
    prior.error_message = str(
        failed_task.fail_msg or "Superseded by a new content-factory retry task."
    )[:4000]
    prior.completed_at = prior.completed_at or now
    prior.meta_json = {
        **dict(prior.meta_json or {}),
        "superseded_by_provider_task_row_id": int(retry_task.id),
        "superseded_at": now.isoformat(),
    }
    db.add(prior)

    next_attempt = int(
        db.query(func.max(HermesContentSegmentRun.attempt))
        .filter(
            HermesContentSegmentRun.variant_run_id == int(prior.variant_run_id),
            HermesContentSegmentRun.segment_index == int(prior.segment_index),
        )
        .scalar()
        or 0
    ) + 1
    retry_row = HermesContentSegmentRun(
        variant_run_id=int(prior.variant_run_id),
        project_id=int(project.id),
        workspace_id=int(project.workspace_id),
        user_id=project.user_id,
        segment_index=int(
            segment.get("segment_index") or prior.segment_index
        ),
        attempt=next_attempt,
        state=str(retry_task.state or "queued_local"),
        provider_key=str(provider_key),
        provider_model=str(retry_task.model),
        provider_task_row_id=int(retry_task.id),
        input_sha256=_canonical_content_digest(
            dict(retry_task.input_json or {})
        ),
        meta_json={
            "schema_version": "content-segment-run-v1",
            "retry_source_task_id": int(failed_task.id),
            "dependency_task_id": segment.get("dependency_task_id"),
        },
    )
    db.add(retry_row)
    variant = db.get(HermesContentVariantRun, int(prior.variant_run_id))
    if variant is not None and str(variant.state or "") != "composed":
        variant.state = "segments_running"
        variant.error_class = None
        variant.error_message = None
        variant.completed_at = None
        db.add(variant)
    db.flush()


def _apply_voice_continuity_retry_prompt(
    retry_input: dict[str, Any],
    voice_repair: dict[str, Any],
) -> dict[str, Any]:
    repair_gender = str(voice_repair.get("gender") or "").strip().lower()
    if repair_gender not in {"female", "male", "androgynous"}:
        return retry_input
    repair_speaker = str(
        voice_repair.get("speaker_id") or "the assigned speaker"
    ).strip()
    voice_repair_clause = (
        "ACOUSTIC VOICE REPAIR (authoritative): "
        f"{repair_speaker} must use one adult {repair_gender} US English "
        "voice matching the same speaker in the adjacent segments. Do not "
        "switch speaker gender, vocal register, timbre, pitch family, "
        "accent, or delivery identity."
    )
    original_base_prompt = str(
        retry_input.get("content_factory_base_prompt")
        or retry_input.get("prompt")
        or ""
    ).strip()
    repaired_base_prompt = original_base_prompt
    if voice_repair_clause not in original_base_prompt:
        repaired_base_prompt = (
            voice_repair_clause + "\n" + original_base_prompt
        ).strip()
    # Provider payload compilation deliberately treats base_prompt as the
    # authority and may rebuild prompt after reference normalization.  Write
    # both fields so this repair survives every downstream compiler boundary.
    retry_input["content_factory_base_prompt"] = repaired_base_prompt
    retry_input["prompt"] = repaired_base_prompt
    retry_input["content_factory_voice_continuity_repair"] = dict(
        voice_repair
    )
    return retry_input


def _apply_segment_execution_retry_prompt(
    retry_input: dict[str, Any],
    execution_review: dict[str, Any],
) -> dict[str, Any]:
    if not execution_review or not bool(execution_review.get("blocking")):
        return retry_input
    reasons = "; ".join(
        str(value)
        for value in list(execution_review.get("blocking_reasons") or [])
        if str(value).strip()
    )[:700]
    model_instruction = re.sub(
        r"\s+",
        " ",
        str(execution_review.get("repair_instruction") or "").strip(),
    )[:700]
    repair_parts: list[str] = []
    failed_requirement_ids = [
        str(value)
        for value in list(execution_review.get("failed_requirement_ids") or [])
        if str(value).strip()
    ]
    if failed_requirement_ids:
        repair_parts.append("requirements " + ", ".join(failed_requirement_ids))
    if bool(retry_input.get("content_factory_forbid_overlay_bands")):
        repair_parts.append("no caption bands/search bars/platform UI")
    if model_instruction:
        repair_parts.insert(0, model_instruction)
    elif reasons:
        repair_parts.insert(0, reasons)
    repair_line = "Repair: " + "; ".join(repair_parts)
    original = str(
        # The provider-facing prompt owns the ordered @image bindings.  The
        # older base prompt deliberately predates those bindings and must not
        # replace them during a multimodal retry.
        retry_input.get("prompt")
        or retry_input.get("content_factory_base_prompt")
        or ""
    ).strip()
    original_lines = [
        line
        for line in original.splitlines()
        if not line.strip().startswith((
            "SIGNED VISUAL EXECUTION REPAIR (authoritative):",
            "Repair:",
        ))
    ]
    repaired = (repair_line + "\n" + "\n".join(original_lines)).strip()
    retry_input["content_factory_base_prompt"] = repaired
    retry_input["prompt"] = repaired
    retry_input["content_factory_segment_execution_repair"] = {
        "policy_version": execution_review.get("policy_version"),
        "reasons": list(execution_review.get("blocking_reasons") or [])[:8],
        "repair_instruction": model_instruction,
    }
    return retry_input


def _recover_media_group_from_execution_ledger(
    db,
    *,
    project: HermesContentFactoryProject,
    task: KieTask,
) -> dict[str, Any] | None:
    """Rebuild one lost project-level media pointer from immutable ledgers.

    ``state_json.ai_video_groups`` is a scheduling cache, not the paid-media
    source of truth.  A concurrent JSON merge must never make a downloaded or
    failed segment unrecoverable.  Rebuild only when the tenant, user, project,
    variant, manifest and source-stage identities agree across the provider
    task and the append-only execution ledger.
    """

    values = dict(task.input_json or {})
    try:
        video_index = int(
            values.get("content_factory_video_index")
            or values.get("content_factory_variant_index")
            or 0
        )
        source_stage_id = int(
            values.get("content_factory_source_stage_id") or 0
        )
    except (TypeError, ValueError):
        return None
    manifest_sha256 = str(
        values.get("content_factory_media_manifest_sha256") or ""
    ).strip()
    if (
        video_index <= 0
        or source_stage_id <= 0
        or len(manifest_sha256) != 64
        or int(task.workspace_id) != int(project.workspace_id)
        or int(values.get("content_factory_project_id") or 0)
        != int(project.id)
        or (
            project.user_id is not None
            and int(task.created_by_user_id or 0) != int(project.user_id)
        )
    ):
        return None
    source_stage = db.get(HermesContentFactoryStage, source_stage_id)
    if (
        source_stage is None
        or int(source_stage.project_id) != int(project.id)
        or str(source_stage.stage or "").upper() != "VIDEO_PROMPTS"
        or str(source_stage.status or "").lower() != "success"
    ):
        return None
    variant = (
        db.query(HermesContentVariantRun)
        .filter(
            HermesContentVariantRun.project_id == int(project.id),
            HermesContentVariantRun.workspace_id == int(project.workspace_id),
            HermesContentVariantRun.variant_index == video_index,
            HermesContentVariantRun.media_manifest_sha256 == manifest_sha256,
        )
        .order_by(HermesContentVariantRun.attempt.desc())
        .first()
    )
    if variant is None:
        return None
    newest_variant = (
        db.query(HermesContentVariantRun)
        .filter(
            HermesContentVariantRun.project_id == int(project.id),
            HermesContentVariantRun.workspace_id == int(project.workspace_id),
            HermesContentVariantRun.variant_index == video_index,
        )
        .order_by(
            HermesContentVariantRun.attempt.desc(),
            HermesContentVariantRun.id.desc(),
        )
        .first()
    )
    if (
        newest_variant is None
        or int(newest_variant.id) != int(variant.id)
        or str(variant.state or "").lower() == "superseded"
    ):
        return None
    variant_meta = dict(variant.meta_json or {})
    if int(variant_meta.get("source_stage_id") or 0) != source_stage_id:
        return None

    ledger_rows = (
        db.query(HermesContentSegmentRun)
        .filter(HermesContentSegmentRun.variant_run_id == int(variant.id))
        .order_by(
            HermesContentSegmentRun.segment_index.asc(),
            HermesContentSegmentRun.attempt.desc(),
        )
        .all()
    )
    latest_by_segment: dict[int, HermesContentSegmentRun] = {}
    for row in ledger_rows:
        latest_by_segment.setdefault(int(row.segment_index), row)
    if not latest_by_segment:
        return None
    scoped_tasks = {
        int(item.id): item
        for item in _scoped_content_video_tasks(
            db,
            project,
            [
                int(row.provider_task_row_id or 0)
                for row in latest_by_segment.values()
                if int(row.provider_task_row_id or 0) > 0
            ],
        )
    }
    segments: list[dict[str, Any]] = []
    for segment_index, row in sorted(latest_by_segment.items()):
        segment_task = scoped_tasks.get(int(row.provider_task_row_id or 0))
        if segment_task is None:
            return None
        segment_values = dict(segment_task.input_json or {})
        if (
            int(segment_values.get("content_factory_project_id") or 0)
            != int(project.id)
            or int(
                segment_values.get("content_factory_video_index")
                or segment_values.get("content_factory_variant_index")
                or 0
            )
            != video_index
            or str(
                segment_values.get("content_factory_media_manifest_sha256")
                or ""
            ).strip()
            != manifest_sha256
            or int(
                segment_values.get("content_factory_source_stage_id") or 0
            )
            != source_stage_id
        ):
            return None
        execution_contract = dict(
            segment_values.get("content_factory_segment_execution_contract")
            or {}
        )
        reference_manifest = [
            dict(item)
            for item in list(
                segment_values.get("content_factory_reference_manifest") or []
            )
            if isinstance(item, dict)
        ]
        reference_paths = [
            dict(item)
            for item in list(segment_values.get("reference_file_paths") or [])
            if isinstance(item, dict)
        ]
        reference_names = [
            str(item.get("filename") or "").strip()
            for item in reference_paths
            if str(item.get("filename") or "").strip()
        ]
        segments.append({
            "task_id": int(segment_task.id),
            "segment_index": int(segment_index),
            "dependency_task_id": segment_values.get(
                "content_factory_dependency_task_id"
            ),
            "dependency_status": (
                "waiting_previous_segment"
                if str(segment_task.state or "").lower()
                == "waiting_dependency"
                else "ready"
            ),
            "continuity_dependency": str(
                segment_values.get("content_factory_continuity_dependency")
                or "independent"
            ),
            "reference_indices": [
                int(item.get("index") or item.get("reference_index") or 0)
                for item in reference_paths
                if int(item.get("index") or item.get("reference_index") or 0)
                > 0
            ],
            "reference_names": reference_names,
            "reference_bindings": reference_manifest,
            "product_anchor_names": [
                str(item.get("filename") or "").strip()
                for item in reference_manifest
                if bool(item.get("is_product_anchor"))
                and str(item.get("filename") or "").strip()
            ],
            "reference_video_names": [
                str(item.get("filename") or "").strip()
                for item in list(
                    segment_values.get("reference_video_file_paths") or []
                )
                if isinstance(item, dict)
                and str(item.get("filename") or "").strip()
            ],
            "duration": int(
                execution_contract.get("duration_seconds")
                or segment_values.get("seconds")
                or 0
            ),
            "initial_provider_key_id": int(segment_task.key_id),
            "resolution": str(
                segment_values.get("resolution")
                or segment_values.get("size")
                or ""
            ),
            "language": str(
                segment_values.get("content_factory_video_language") or ""
            ),
            "segment_goal": str(execution_contract.get("segment_goal") or ""),
            "timeline": list(execution_contract.get("timeline") or []),
            "dialogue_lines": list(
                segment_values.get("content_factory_dialogue_lines") or []
            ),
            "display_lines": list(
                segment_values.get("content_factory_display_lines") or []
            ),
            "voice_lock": list(
                segment_values.get("content_factory_voice_lock") or []
            ),
            "product_anchor_required": bool(
                segment_values.get("content_factory_product_anchor_required")
                or segment_values.get("content_factory_product_required")
            ),
            "product_render_mode": str(
                segment_values.get("content_factory_product_render_mode")
                or "text_only"
            ),
            "compile_source": str(
                segment_values.get("content_factory_compile_source") or ""
            ),
            "requirement_ids": list(
                execution_contract.get("requirement_ids") or []
            ),
            "requirement_contract": list(
                segment_values.get("content_factory_requirement_contract")
                or []
            ),
            "audio_mode": str(
                segment_values.get("content_factory_audio_mode") or "spoken"
            ),
            "prompt": str(segment_values.get("prompt") or "")[:1000],
            "recovered_from_execution_ledger": True,
        })
    duration = int(variant_meta.get("duration") or 0) or sum(
        int(item.get("duration") or 0) for item in segments
    )
    recovered = {
        "video_index": video_index,
        "version_name": _safe_file_stem(
            str(
                values.get("content_factory_final_name_base")
                or f"v{video_index:02d}"
            )
        ),
        "duration": duration,
        "aspect_ratio": str(
            variant_meta.get("aspect_ratio")
            or values.get("aspect_ratio")
            or _configured_video_aspect_ratio(project)
        ),
        "final_name_base": str(
            values.get("content_factory_final_name_base")
            or f"{project.project_key}-v{video_index:02d}"
        ),
        "segments": segments,
        "media_manifest_sha256": manifest_sha256,
        "media_manifest_schema_version": "content-media-manifest-v1",
        "provider_retry_budget_per_segment": int(
            dict(project.config_json or {}).get(
                "content_factory_video_retry_limit"
            )
            or 2
        ),
        "source_stage_id": source_stage_id,
        "intent_manifest_sha256": str(
            values.get("content_factory_intent_manifest_sha256") or ""
        )
        or None,
        "audio_mode": str(
            values.get("content_factory_audio_mode") or "spoken"
        ),
        "recovered_from_execution_ledger": True,
        "recovered_provider_task_id": int(task.id),
    }
    return _restore_media_group_signed_contract(db, project, recovered)


def _recover_variant_media_group_from_execution_ledger(
    db,
    *,
    project: HermesContentFactoryProject,
    variant_index: int,
) -> dict[str, Any] | None:
    """Recover the newest paid media attempt for one user-facing ordinal.

    This lookup deliberately starts from the append-only variant/segment
    ledger rather than mutable project JSON.  It is used immediately before a
    missing-variant repair would authorize another paid submission.
    """

    try:
        normalized_variant = int(variant_index)
    except (TypeError, ValueError):
        return None
    if normalized_variant <= 0:
        return None
    variant_runs = (
        db.query(HermesContentVariantRun)
        .filter(
            HermesContentVariantRun.project_id == int(project.id),
            HermesContentVariantRun.workspace_id == int(project.workspace_id),
            HermesContentVariantRun.variant_index == normalized_variant,
        )
        .order_by(
            HermesContentVariantRun.attempt.desc(),
            HermesContentVariantRun.id.desc(),
        )
        .all()
    )
    for variant_run in variant_runs:
        if (
            project.user_id is not None
            and int(variant_run.user_id or 0) != int(project.user_id)
        ):
            continue
        segment_rows = (
            db.query(HermesContentSegmentRun)
            .filter(
                HermesContentSegmentRun.variant_run_id
                == int(variant_run.id),
                HermesContentSegmentRun.provider_task_row_id.isnot(None),
            )
            .order_by(
                HermesContentSegmentRun.segment_index.asc(),
                HermesContentSegmentRun.attempt.desc(),
                HermesContentSegmentRun.id.desc(),
            )
            .all()
        )
        newest_by_segment: dict[int, HermesContentSegmentRun] = {}
        for row in segment_rows:
            newest_by_segment.setdefault(int(row.segment_index), row)
        provider_task_ids = [
            int(row.provider_task_row_id or 0)
            for row in newest_by_segment.values()
            if int(row.provider_task_row_id or 0) > 0
        ]
        provider_tasks = _scoped_content_video_tasks(
            db,
            project,
            provider_task_ids,
        )
        for task in sorted(provider_tasks, key=lambda item: int(item.id), reverse=True):
            recovered = _recover_media_group_from_execution_ledger(
                db,
                project=project,
                task=task,
            )
            if recovered is not None:
                return recovered
        # The newest immutable variant attempt is authoritative.  Do not fall
        # back to an older attempt when its current segment ledger is corrupt
        # or missing; that could resurrect media intentionally superseded by a
        # quality repair.
        return None
    return None


def _recover_premature_authority_rejections(
    db,
    *,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    """Requeue tasks quarantined during a transient group-cache race.

    Provider workers intentionally fail closed when a task is absent from the
    project's mutable group cache.  If the immutable execution ledger proves
    that the exact task is still the newest authoritative owner, restore the
    cache and put the task back on the local queue without consuming provider
    retry budget.  All other authority failures remain terminal.
    """

    state = dict(project.state_json or {})
    groups = [
        dict(item)
        for item in list(state.get("ai_video_groups") or [])
        if isinstance(item, dict)
    ]
    groups_by_variant = {
        int(item.get("video_index") or 0): item
        for item in groups
        if int(item.get("video_index") or 0) > 0
    }
    recovered_task_ids: list[int] = []
    now = _stage_now()
    for task in tasks:
        if str(task.fail_code or "").strip().lower() != (
            CONTENT_FACTORY_NOT_AUTHORITATIVE_CODE
        ):
            continue
        local_meta = dict(get_task_local_meta(task) or {})
        if str(local_meta.get("authority_rejected_reason") or "") != (
            "variant_group_missing"
        ):
            continue
        recovered_group = _recover_media_group_from_execution_ledger(
            db,
            project=project,
            task=task,
        )
        if recovered_group is None:
            continue
        variant_index = int(recovered_group.get("video_index") or 0)
        segment_index = int(
            dict(task.input_json or {}).get(
                "content_factory_segment_index"
            )
            or 0
        )
        matching_segment = next(
            (
                dict(item)
                for item in list(recovered_group.get("segments") or [])
                if int(dict(item).get("segment_index") or 0) == segment_index
            ),
            None,
        )
        if (
            variant_index <= 0
            or matching_segment is None
            or int(matching_segment.get("task_id") or 0) != int(task.id)
        ):
            continue
        current_group = groups_by_variant.get(variant_index)
        if current_group is not None:
            current_owner = next(
                (
                    int(dict(item).get("task_id") or 0)
                    for item in list(current_group.get("segments") or [])
                    if int(dict(item).get("segment_index") or 0)
                    == segment_index
                ),
                0,
            )
            if current_owner not in {0, int(task.id)}:
                continue
        groups_by_variant[variant_index] = recovered_group
        for stale_key in (
            "authority_rejected_at",
            "authority_rejected_reason",
            "poll_owner_task_id",
            "poll_heartbeat_at",
            "poll_heartbeat_provider",
            "submit_enqueued_at",
        ):
            local_meta.pop(stale_key, None)
        local_meta.update({
            "authority_cache_race_recovered_at": now.isoformat(),
            "authority_cache_race_recovery": "immutable_execution_ledger",
        })
        task.task_id = f"local-ai-video-{uuid.uuid4().hex}"
        task.state = "queued_local"
        task.fail_code = None
        task.fail_msg = None
        task.result_json = {"__local": local_meta}
        task.updated_at = now
        db.add(task)
        segment_row = (
            db.query(HermesContentSegmentRun)
            .filter(
                HermesContentSegmentRun.project_id == int(project.id),
                HermesContentSegmentRun.provider_task_row_id == int(task.id),
            )
            .order_by(
                HermesContentSegmentRun.attempt.desc(),
                HermesContentSegmentRun.id.desc(),
            )
            .first()
        )
        if segment_row is not None:
            segment_row.state = "queued_local"
            segment_row.error_class = None
            segment_row.error_message = None
            segment_row.completed_at = None
            db.add(segment_row)
        recovered_task_ids.append(int(task.id))
    if not recovered_task_ids:
        return []
    state["ai_video_groups"] = [
        groups_by_variant[index] for index in sorted(groups_by_variant)
    ]
    state["ai_video_task_ids"] = sorted({
        *{
            int(value)
            for value in list(state.get("ai_video_task_ids") or [])
            if str(value).strip().isdigit()
        },
        *recovered_task_ids,
    })
    state["ai_video_authority_cache_race_recovered_task_ids"] = list(
        dict.fromkeys(
            list(
                state.get(
                    "ai_video_authority_cache_race_recovered_task_ids"
                )
                or []
            )
            + recovered_task_ids
        )
    )[-50:]
    state["ai_video_authority_cache_race_recovered_at"] = now.isoformat()
    project.state_json = state
    project.status = "generating_video"
    project.current_stage = "WAITING_VIDEO_INPUT"
    project.last_error = (
        "Hermes 已从不可变执行账本恢复过早隔离的视频片段，未重复创建付费任务，"
        "正在继续执行。"
    )
    db.add(project)
    db.flush()
    return recovered_task_ids


def _merge_video_retry_state(
    latest_state: dict[str, Any],
    retry_state: dict[str, Any],
    *,
    retry_groups: list[dict[str, Any]],
    affected_video_indices: set[int],
    replaced_task_ids: set[int],
    restored_dependency_ids: set[int],
) -> dict[str, Any]:
    """Merge retry-owned state without deleting concurrent sibling variants."""

    merged = dict(latest_state or {})
    latest_groups = [
        dict(item)
        for item in list(merged.get("ai_video_groups") or [])
        if isinstance(item, dict)
    ]
    retry_by_video = {
        int(item.get("video_index") or 0): dict(item)
        for item in retry_groups
        if int(item.get("video_index") or 0) in affected_video_indices
    }
    latest_by_video = {
        int(item.get("video_index") or 0): dict(item)
        for item in latest_groups
        if int(item.get("video_index") or 0) > 0
    }
    for video_index, retry_group in retry_by_video.items():
        latest_group = latest_by_video.get(video_index)
        if latest_group is None:
            latest_by_video[video_index] = retry_group
            continue
        latest_segments = {
            int(item.get("segment_index") or 0): dict(item)
            for item in list(latest_group.get("segments") or [])
            if isinstance(item, dict)
        }
        for retry_segment in list(retry_group.get("segments") or []):
            if not isinstance(retry_segment, dict):
                continue
            segment_index = int(retry_segment.get("segment_index") or 0)
            latest_segment = latest_segments.get(segment_index)
            latest_task_id = int(
                dict(latest_segment or {}).get("task_id") or 0
            )
            retry_task_id = int(retry_segment.get("task_id") or 0)
            retry_source_task_id = int(
                retry_segment.get("retry_source_task_id") or 0
            )
            # A same-variant concurrent repair already moved this pointer to a
            # different child. Preserve that newer decision. Otherwise apply
            # the candidate replacement while retaining sibling segments.
            if (
                latest_segment is not None
                and latest_task_id not in {
                    0,
                    retry_task_id,
                    retry_source_task_id,
                    *replaced_task_ids,
                }
            ):
                continue
            latest_segments[segment_index] = dict(retry_segment)
        merged_group = {**latest_group, **retry_group}
        merged_group["segments"] = [
            latest_segments[index] for index in sorted(latest_segments)
        ]
        latest_by_video[video_index] = merged_group
    merged["ai_video_groups"] = [
        latest_by_video[index] for index in sorted(latest_by_video)
    ]

    latest_task_ids = {
        int(value)
        for value in list(merged.get("ai_video_task_ids") or [])
        if str(value).strip().isdigit()
    }
    retry_task_ids = {
        int(value)
        for value in list(retry_state.get("ai_video_task_ids") or [])
        if str(value).strip().isdigit()
    }
    merged["ai_video_task_ids"] = sorted(
        (latest_task_ids | retry_task_ids) - replaced_task_ids
    )
    for key in (
        "ai_video_segment_retry_counts",
        "ai_video_segment_quality_retry_counts",
        "ai_video_exhausted_cooldown_retry_generations",
        "ai_video_account_rotation_retry_counts",
    ):
        merged[key] = {
            **dict(merged.get(key) or {}),
            **dict(retry_state.get(key) or {}),
        }
    history: list[dict[str, Any]] = []
    seen_history: set[tuple[int, int, str]] = set()
    for item in [
        *list(merged.get("ai_video_retry_history") or []),
        *list(retry_state.get("ai_video_retry_history") or []),
    ]:
        if not isinstance(item, dict):
            continue
        identity = (
            int(item.get("failed_task_id") or 0),
            int(item.get("retry_task_id") or 0),
            str(item.get("at") or ""),
        )
        if identity in seen_history:
            continue
        seen_history.add(identity)
        history.append(dict(item))
    merged["ai_video_retry_history"] = history[-100:]
    latest_failed_ids = {
        int(value)
        for value in list(merged.get("ai_video_failed_task_ids") or [])
        if str(value).strip().isdigit()
    }
    retry_failed_ids = {
        int(value)
        for value in list(retry_state.get("ai_video_failed_task_ids") or [])
        if str(value).strip().isdigit()
    }
    merged["ai_video_failed_task_ids"] = sorted(
        (latest_failed_ids | retry_failed_ids)
        - replaced_task_ids
        - restored_dependency_ids
    )
    for key in (
        "ai_video_cooldown_retry_restored_dependency_task_ids",
        "ai_video_blocked_reference_asset_ids",
        "ai_video_last_retry_at",
        "ai_video_highest_retry_attempt",
        "ai_video_retry_limit",
    ):
        if key in retry_state:
            merged[key] = retry_state[key]
    merged.pop("ai_video_terminal_failure", None)
    return merged


def _provider_reference_aliases(
    input_params: dict[str, Any],
) -> tuple[str, ...]:
    aliases: list[str] = []
    for position, row in enumerate(
        list(input_params.get("content_factory_reference_manifest") or []),
        1,
    ):
        if not isinstance(row, dict):
            continue
        alias = str(row.get("alias") or f"@image{position}").strip()
        if alias:
            aliases.append(alias)
    return tuple(dict.fromkeys(aliases))


def _validate_and_stamp_provider_prompt(
    input_params: dict[str, Any],
    *,
    source_prompt: str,
    actual_prompt: str,
) -> dict[str, Any]:
    """Prove that the exact provider payload still carries signed semantics.

    This executes after every compaction and immediately before task creation.
    Metadata stores the proof rather than another mutable copy of the creative
    packet, so retries can be audited without trusting UI summaries.
    """

    aliases = _provider_reference_aliases(input_params)
    product_required = bool(
        input_params.get("content_factory_product_anchor_required")
        or input_params.get("content_factory_product_required")
    )
    if product_required:
        product_anchors = [
            row
            for row in list(
                input_params.get("content_factory_reference_manifest") or []
            )
            if isinstance(row, dict) and bool(row.get("is_product_anchor"))
        ]
        if not product_anchors and str(
            input_params.get("content_factory_product_render_mode") or ""
        ).strip() != "text_only":
            raise ValueError(
                "CONTENT_PRODUCT_AUTHORITY_MISSING: product-visible segment "
                "has no authoritative uploaded product reference"
            )
    contract = validate_structured_video_prompt_fidelity(
        source_prompt,
        actual_prompt,
        required_reference_aliases=aliases,
        product_required=(
            product_required
            and str(
                input_params.get("content_factory_product_render_mode") or ""
            ).strip() != "text_only"
        ),
    )
    contract.update({
        "policy_version": VIDEO_PROMPT_POLICY_VERSION,
        "source_sha256": hashlib.sha256(
            str(source_prompt or "").encode("utf-8")
        ).hexdigest(),
        "actual_sha256": hashlib.sha256(
            str(actual_prompt or "").encode("utf-8")
        ).hexdigest(),
    })
    input_params["content_factory_provider_prompt_contract"] = contract
    return input_params


def _compact_content_factory_retry_prompt(
    project: HermesContentFactoryProject,
    retry_input: dict[str, Any],
) -> dict[str, Any]:
    """Re-fit a repaired prompt to the selected model's declared text lane.

    The signed story, references and QA packet remain in task metadata.  This
    is only the provider-facing multimodal execution view.  Running this after
    every repair prevents retry prose from silently dropping @image bindings
    or exceeding a web composer's limit.
    """

    prompt = str(retry_input.get("prompt") or "").strip()
    if not prompt:
        return retry_input
    lines = [line.strip() for line in prompt.splitlines() if line.strip()]
    model_decided_no_product = bool(
        retry_input.get("content_factory_product_presence_decided_by_model")
    ) and not bool(
        retry_input.get("content_factory_product_anchor_required")
    )
    if model_decided_no_product:
        lines = [
            line
            for line in lines
            if not line.startswith(
                ("Product:", "Product presentation policy:")
            )
        ]
    elif bool(retry_input.get("content_factory_product_anchor_required")):
        # The uploaded package image is an appearance authority, never a
        # finished white-background composition.  Normalize this execution
        # rule even when the repaired packet happens to fit under the text
        # limit; the generic compactor intentionally returns already-small
        # packets unchanged.
        strict_product_line = (
            "Product: uploaded package is sole authority. In-scene; no "
            "white background/packshot."
        )
        product_indices = [
            index
            for index, line in enumerate(lines)
            if line.startswith(("Product:", "Product presentation policy:"))
        ]
        if product_indices:
            first = product_indices[0]
            lines[first] = strict_product_line
            lines = [
                line
                for index, line in enumerate(lines)
                if index == first
                or not line.startswith(
                    ("Product:", "Product presentation policy:")
                )
            ]
        else:
            # Historical retries can gain a restored package reference only
            # after their old provider prompt was written.  The prompt must
            # gain the matching semantic lane as well; otherwise media and
            # text disagree and the provider can treat the upload as an
            # unrelated still.
            refs_index = next(
                (
                    index
                    for index, line in enumerate(lines)
                    if line.startswith(("Refs:", "Reference bindings:"))
                ),
                -1,
            )
            lines.insert(refs_index + 1, strict_product_line)
    # Migrate retries created by the pre-fix worker.  Their verbose first line
    # contains the right reviewer decision but is not a structured compiler
    # field, so the small-budget compactor used to discard it.
    lines = [
        line
        for line in lines
        if not line.startswith(
            "SIGNED VISUAL EXECUTION REPAIR (authoritative):"
        )
    ]
    repair = dict(
        retry_input.get("content_factory_segment_execution_repair") or {}
    )
    repair_instruction = re.sub(
        r"\s+",
        " ",
        str(repair.get("repair_instruction") or "").strip(),
    )
    upstream_repair_instruction = re.sub(
        r"\s+",
        " ",
        str(repair.get("upstream_repair_instruction") or "").strip(),
    )
    ai_replan_has_beats = bool(
        str(repair.get("source") or "") == "ai_feasibility_replan"
        and any(line.startswith("Beats:") for line in lines)
    )
    repair_policy = str(repair.get("policy_version") or "").strip()
    upstream_repair_policy = str(
        repair.get("upstream_repair_policy_version") or ""
    ).strip()
    if (
        ai_replan_has_beats
        and upstream_repair_instruction
        and not model_decided_no_product
    ):
        repair_instruction = upstream_repair_instruction
        repair_policy = upstream_repair_policy
        ai_replan_has_beats = False
    repair_policy_is_current = (
        not repair_policy
        or repair_policy
        in {
            str(SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION),
            str(FINAL_INTENT_REVIEW_POLICY_VERSION),
        }
    )
    if repair_instruction and repair_policy_is_current and not ai_replan_has_beats and not any(
        line.startswith("Repair:") for line in lines
    ):
        lines.insert(0, "Repair: " + repair_instruction)

    # The image files are copied in manifest order.  Recreate the textual
    # aliases as well when migrating a historical retry whose base prompt had
    # lost them; images anchor appearance/state while Beats/Repair own motion.
    # Reference strategy and product-authority recovery can add, remove, or
    # reorder files.  Never retain a pre-repair Refs line: regenerate it from
    # the exact manifest that will be persisted to the replacement task.
    manifest_rows = [
        row
        for row in list(
            retry_input.get("content_factory_reference_manifest") or []
        )
        if isinstance(row, dict)
    ]
    if manifest_rows:
        lines = [
            line
            for line in lines
            if not line.startswith(("Refs:", "Reference bindings:"))
        ]
    grouped: dict[str, list[str]] = {}
    role_names = {
        "character_anchor": "character",
        "scene_anchor": "scene",
        "action_anchor": "action",
        "product_anchor": "package",
    }
    for position, row in enumerate(manifest_rows, 1):
        alias = str(row.get("alias") or f"@image{position}").strip()
        roles = [
            role_names[role]
            for role in list(row.get("semantic_roles") or [])
            if role in role_names
        ]
        if bool(row.get("is_product_anchor")) and "package" not in roles:
            roles.append("package")
        label = "+".join(dict.fromkeys(roles)) or "visual"
        grouped.setdefault(label, []).append(alias)
    if manifest_rows and grouped:
        bindings = "; ".join(
            f"{','.join(aliases)}={label}"
            for label, aliases in grouped.items()
        )
        lines.insert(0, "Refs: " + bindings)
    prompt = "\n".join(lines)
    project_model = str(
        dict(getattr(project, "config_json", None) or {}).get("video_model")
        or ""
    ).strip()
    if project_model:
        prompt_policy = _video_model_policy(project)
    else:
        # A replacement task already carries the selected model. Historical
        # projects may predate the project-level model field, so prompt
        # recompilation must use the task's actual provider contract rather
        # than crash or guess another model.
        retry_model = str(retry_input.get("model") or "").strip()
        prompt_policy = resolve_video_model_policy(
            model_id=retry_model,
            reference_image_limit=int(
                retry_input.get("video_reference_limit") or 7
            ),
            allow_reference_video=False,
            product_required=_project_uses_product(project),
        )
    limit = int(prompt_policy["provider_prompt_max_characters"])
    compacted = compact_structured_video_prompt(
        prompt,
        max_characters=limit,
    )
    retry_input["prompt"] = compacted
    # A retry is submitted directly, so both prompt fields must carry the same
    # ordered provider view.  The complete immutable contract remains in the
    # dedicated content_factory_* metadata fields.
    retry_input["content_factory_base_prompt"] = compacted
    retry_input["content_factory_retry_prompt_budget"] = {
        "model": str(retry_input.get("model") or ""),
        "max_characters": limit,
        "actual_characters": len(compacted),
    }
    # The compacted retry is the exact provider payload.  Stamp the compiler
    # policy that produced it so a future recovery can distinguish a real
    # legacy prompt from a retry already migrated to the current multimodal
    # contract.  Without this, each self-heal pass can repeatedly consume a
    # migration retry generation even though the payload is current.
    retry_input["content_factory_prompt_policy_version"] = (
        VIDEO_PROMPT_POLICY_VERSION
    )
    return _validate_and_stamp_provider_prompt(
        retry_input,
        source_prompt=prompt,
        actual_prompt=compacted,
    )


def _rebuild_retry_prompt_from_segment_execution_contract(
    retry_input: dict[str, Any],
) -> dict[str, Any]:
    """Restore a legacy transport prompt from its complete authoring record.

    Older prompt-budget policies could leave timed rows such as ``0-1.7s: ;``
    in the provider payload.  Recompacting that already-lossy payload cannot
    recover the action even though the complete, immutable per-segment
    timeline is still stored beside it.  Policy migration must therefore
    rebuild the semantic source from that timeline before applying the current
    provider budget.

    This changes only the provider transport view.  Script, references,
    product authority, voice and the stored execution contract remain intact.
    """

    contract = dict(
        retry_input.get("content_factory_segment_execution_contract") or {}
    )
    timeline = [
        dict(row)
        for row in list(contract.get("timeline") or [])
        if isinstance(row, dict)
        and str(
            row.get("subject_action") or row.get("action") or ""
        ).strip()
    ]
    if not timeline:
        return retry_input

    existing = str(
        retry_input.get("prompt")
        or retry_input.get("content_factory_base_prompt")
        or ""
    ).strip()
    retained_lines = [
        line.strip()
        for line in existing.splitlines()
        if line.strip()
        and not line.strip().startswith(
            (
                "Beats:",
                "Must:",
                "Timeline (this segment only):",
                "Motion and effects:",
                "Repair:",
                "Voice:",
                "Voice lock for this segment:",
            )
        )
    ]
    # Retry payloads may already have passed through the 495-character
    # provider compactor. Rebuilding from that lossy view used to preserve a
    # generic ``Voice: ... US`` line and permanently discard the signed speech
    # rate. Recover the provider voice lane from task metadata whenever it is
    # available, just as we recover the complete timed actions below.
    voice_locks = [
        dict(row)
        for row in list(retry_input.get("content_factory_voice_lock") or [])
        if isinstance(row, dict)
    ]
    if voice_locks:
        voice = voice_locks[0]
        gender = str(voice.get("gender") or "same").strip().lower() or "same"
        relation = str(voice.get("screen_relation") or "speaker").strip().lower()
        owner = {
            "off_screen_narrator": "off-screen narrator",
            "on_screen_character": "visible protagonist",
            "character_voiceover": "visible protagonist",
        }.get(relation, "speaker")
        rate = int(float(voice.get("speech_rate") or 0))
        voice_line = f"Voice: same {gender} {owner}, US accent"
        if rate > 0:
            voice_line += f"; {rate} words per minute"
        retained_lines.append(voice_line + ".")
    beat_rows: list[str] = []
    for row in timeline:
        try:
            start = float(row.get("start_second") or 0)
            end = float(row.get("end_second") or start)
            time_label = f"{start:g}-{end:g}s"
        except (TypeError, ValueError):
            time_label = "beat"
        provider_action_key = (
            "provider_action_zh"
            if str(retry_input.get("service_provider") or "").strip().lower()
            == "doubao"
            else "provider_action_en"
        )
        subject_action = re.sub(
            r"\s+",
            " ",
            str(
                row.get(provider_action_key)
                or row.get("provider_action_en")
                or row.get("subject_action")
                or row.get("action")
                or ""
            ).strip(),
        )
        motion = re.sub(
            r"\s+",
            " ",
            str(row.get("motion_and_transition") or "").strip(),
        )
        action = subject_action
        if motion:
            action = f"{action} Transition: {motion}"
        beat_rows.append(f"{time_label}: {action}")

    beats_line = "Beats: " + " | ".join(beat_rows)
    rebuilt_lines = [beats_line]
    invariants = structured_video_prompt_semantic_invariants(beats_line)
    if invariants:
        rebuilt_lines.append("Must: " + "; ".join(invariants))
    visual_style = re.sub(
        r"\s+",
        " ",
        str(
            contract.get("visual_style")
            or contract.get("project_visual_style_requirement")
            or ""
        ).strip(),
    )
    visual_grammar = re.sub(
        r"\s+",
        " ",
        str(contract.get("visual_grammar") or "").strip(),
    )
    pacing = re.sub(
        r"\s+", " ", str(contract.get("pacing") or "").strip()
    )
    camera_direction = re.sub(
        r"\s+",
        " ",
        str(contract.get("camera_direction") or "").strip(),
    )
    direction_parts = [
        value
        for value in (
            ("Pace=" + pacing) if pacing else "",
            ("Camera=" + camera_direction) if camera_direction else "",
            (
                "Edit grammar=" + visual_grammar
                if visual_grammar and visual_grammar != pacing
                else ""
            ),
            ("Style=" + visual_style) if visual_style else "",
        )
        if value
    ]
    if direction_parts:
        rebuilt_lines.append("Direction: " + " | ".join(direction_parts))
    repair_contract = dict(
        retry_input.get("content_factory_segment_execution_repair") or {}
    )
    if str(repair_contract.get("policy_version") or "") == str(
        SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
    ):
        current_repair = re.sub(
            r"\s+",
            " ",
            str(repair_contract.get("repair_instruction") or "").strip(),
        )
        if current_repair:
            rebuilt_lines.append("Repair: " + current_repair)
    rebuilt_lines.extend(retained_lines)
    rebuilt = "\n".join(rebuilt_lines).strip()

    retry_input["prompt"] = rebuilt
    retry_input["content_factory_base_prompt"] = rebuilt
    retry_input["content_factory_prompt_migration"] = {
        "from_policy_version": str(
            retry_input.get("content_factory_prompt_policy_version") or ""
        ),
        "to_policy_version": VIDEO_PROMPT_POLICY_VERSION,
        "source": "content_factory_segment_execution_contract",
        "timeline_rows": len(beat_rows),
    }
    retry_input.pop("content_factory_provider_prompt_contract", None)
    return retry_input


def _apply_ai_segment_execution_replan(
    retry_input: dict[str, Any],
    replanned_contract: dict[str, Any],
) -> dict[str, Any]:
    """Install a model-authored feasibility repair without changing copy.

    Provider retries used to accumulate increasingly long repair prefixes while
    preserving the same over-dense choreography. This authoritative override
    changes only the current segment's action/camera contract and the QA target;
    the signed script, voice, product facts, references and whole-video story
    remain untouched.
    """

    prior_repair = dict(
        retry_input.get("content_factory_segment_execution_repair") or {}
    )
    explicit_upstream_repair = re.sub(
        r"\s+",
        " ",
        str(prior_repair.get("upstream_repair_instruction") or "").strip(),
    )
    prior_repair_instruction = re.sub(
        r"\s+",
        " ",
        str(
            explicit_upstream_repair
            or prior_repair.get("repair_instruction")
            or ""
        ).strip(),
    )
    prior_repair_policy = str(
        (
            prior_repair.get("upstream_repair_policy_version")
            if explicit_upstream_repair
            else prior_repair.get("policy_version")
        )
        or ""
    ).strip()
    # Once a multimodal reviewer has supplied independent defect evidence,
    # every later feasibility replan must keep it.  Historical replans store
    # that evidence in upstream_repair_instruction while source remains
    # ai_feasibility_replan.  The former source check therefore erased a real
    # shoulder-to-leg continuity repair on the next account/provider retry.
    # Treat the explicit upstream lane as immutable reviewer authority; the
    # new model-authored choreography remains a separate Direction/Beats lane.
    preserve_upstream_repair = bool(
        prior_repair_instruction
        and (
            bool(explicit_upstream_repair)
            or str(prior_repair.get("source") or "")
            != "ai_feasibility_replan"
        )
        and (
            not prior_repair_policy
            or prior_repair_policy
            in {
                str(SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION),
                str(FINAL_INTENT_REVIEW_POLICY_VERSION),
            }
        )
    )
    original = str(
        retry_input.get("prompt")
        or retry_input.get("content_factory_base_prompt")
        or ""
    ).strip()
    reference_strategy_changed = bool(
        retry_input.get("content_factory_execution_reference_replan")
    )
    retained_lines: list[str] = []
    skip_prior_replan_json = False
    for line in original.splitlines():
        stripped = line.strip()
        if stripped.startswith(
            "SIGNED VISUAL EXECUTION REPAIR (authoritative):"
        ):
            continue
        if stripped.startswith("Repair:"):
            continue
        if stripped.startswith("Must:"):
            # Must is derived from the active timed choreography. Keeping the
            # previous replan's invariants would create a contradictory
            # provider packet after AI feasibility repair.
            continue
        if (
            reference_strategy_changed
            and stripped.startswith(("Refs:", "Reference bindings:"))
        ):
            # A multimodal recovery may remove a high-weight still that
            # conflicts with the chronological opening. Rebuild aliases from
            # the current manifest after that decision.
            continue
        if stripped.startswith(
            (
                "Beats:",
                "Direction:",
                "Timeline (this segment only):",
                "Motion and effects:",
                "Dialogue:",
                "Signed intent requirements for this segment:",
            )
        ):
            # The feasibility model owns the replacement choreography, while
            # the immutable structured copy ledger owns speech. Keeping either
            # the old provider timeline/direction or its already-compacted
            # Dialogue/requirement prose produced contradictory instructions,
            # including two different shot counts in the same Flow request.
            # Signed requirements remain in typed task metadata and were input
            # to the replan model; they must not be pasted back as a competing
            # provider screenplay. This also prevents truncated internal
            # speaker ids such as ``narr...`` from leaking into later retries.
            continue
        if stripped.startswith("AI FEASIBILITY REPLAN (authoritative"):
            skip_prior_replan_json = True
            continue
        if skip_prior_replan_json and stripped.startswith("{"):
            # The compact JSON immediately following the marker belongs to the
            # superseded replan.  Keeping it would make later recovery rounds
            # carry multiple mutually exclusive authoritative choreographies.
            skip_prior_replan_json = False
            continue
        skip_prior_replan_json = False
        retained_lines.append(line)
    original = "\n".join(retained_lines).strip()
    provider_instruction = re.sub(
        r"\s+",
        " ",
        str(replanned_contract.get("provider_instruction") or "").strip(),
    )
    if not provider_instruction:
        provider_instruction = "; ".join(
            str(row.get("action") or "").strip()
            for row in list(replanned_contract.get("timeline") or [])
            if isinstance(row, dict) and str(row.get("action") or "").strip()
        )
    replanned_beats: list[str] = []
    provider_action_key = (
        "provider_action_zh"
        if str(retry_input.get("service_provider") or "").strip().lower()
        == "doubao"
        else "provider_action_en"
    )
    provider_context_key = (
        "provider_visual_context_zh"
        if provider_action_key == "provider_action_zh"
        else "provider_visual_context_en"
    )
    provider_visual_context = re.sub(
        r"\s+",
        " ",
        str(replanned_contract.get(provider_context_key) or "").strip(),
    ).rstrip(" .。;；")
    provider_direction_key = (
        "provider_direction_zh"
        if provider_action_key == "provider_action_zh"
        else "provider_direction_en"
    )
    provider_direction = re.sub(
        r"\s+",
        " ",
        str(replanned_contract.get(provider_direction_key) or "").strip(),
    ).rstrip(" .。;；")
    if not provider_direction:
        provider_direction = " | ".join(
            value
            for value in (
                re.sub(
                    r"\s+", " ",
                    str(replanned_contract.get("pacing") or "").strip(),
                ),
                re.sub(
                    r"\s+", " ",
                    str(
                        replanned_contract.get("camera_direction") or ""
                    ).strip(),
                ),
                provider_visual_context,
            )
            if value
        )
    for row_index, row in enumerate(
        list(replanned_contract.get("timeline") or [])
    ):
        if not isinstance(row, dict):
            continue
        action = re.sub(
            r"\s+",
            " ",
            str(
                row.get(provider_action_key)
                or row.get("provider_action_en")
                or row.get("action")
                or ""
            ).strip(),
        )
        # The structured compiler owns the timestamp. Some model responses
        # repeat it inside provider_action_zh/en; carrying both wastes enough
        # of Doubao's 495-character lane to crowd out the final observable
        # action. Remove only that duplicated structural label, never creative
        # wording.
        action = re.sub(
            r"^\s*\d+(?:\.\d+)?\s*[-–—]\s*\d+(?:\.\d+)?\s*"
            r"(?:s|秒)\s*[;；,:：-]?\s*",
            "",
            action,
            flags=re.IGNORECASE,
        )
        if row_index == 0 and provider_visual_context:
            # The feasibility author returns medium/subject/environment in a
            # separate typed field and may also prepend the same prose to the
            # first provider action.  Small provider budgets retain complete
            # clauses from the start of each beat.  Leaving the duplicated
            # static context first can therefore preserve "home office" while
            # dropping the actual hook (for example the desk rising and the
            # keyboard catch).  References never own chronology: move only an
            # exact duplicated context prefix behind the authored action so
            # motion/conflict survives compaction and the scene remains a
            # secondary text cue.
            context_prefix = provider_visual_context.rstrip(" .。;；")
            if action.startswith(context_prefix):
                action_remainder = action[len(context_prefix):].lstrip(
                    " .。;；,，:："
                )
                if action_remainder:
                    action = (
                        f"{action_remainder}；场景：{context_prefix}"
                        if provider_action_key == "provider_action_zh"
                        else f"{action_remainder}; Context: {context_prefix}"
                    )
        if not action:
            continue
        try:
            start = float(row.get("start_second") or 0)
            end = float(row.get("end_second") or start)
            time_label = f"{start:g}-{end:g}s"
        except (TypeError, ValueError):
            time_label = "beat"
        replanned_beats.append(f"{time_label}: {action}")
    provider_dialogue_rows = [
        dict(item)
        for item in list(
            retry_input.get("content_factory_dialogue_lines") or []
        )
        if isinstance(item, dict)
        and str(item.get("delivery_mode") or "spoken").strip().lower()
        == "spoken"
        and str(
            item.get("delivery_method") or "provider_dialogue"
        ).strip().lower()
        != "local_voiceover"
        and str(item.get("line") or "").strip()
    ]
    provider_speakers = {
        str(item.get("speaker_id") or item.get("speaker") or "").strip()
        for item in provider_dialogue_rows
    }
    provider_speakers.discard("")
    include_speaker_labels = len(provider_speakers) > 1
    rebuilt_dialogue: list[str] = []
    for item in provider_dialogue_rows:
        line = re.sub(
            r"\s+",
            " ",
            str(item.get("line") or "").strip(),
        )
        if not line:
            continue
        speaker = str(
            item.get("speaker_id") or item.get("speaker") or ""
        ).strip()
        rebuilt_dialogue.append(
            f"{speaker}: '{line}'"
            if include_speaker_labels and speaker
            else f"'{line}'"
        )
    rebuilt_dialogue = list(dict.fromkeys(rebuilt_dialogue))

    provider_lines = []
    # The model-authored choreography explains the new execution, while the
    # evidence-backed repair explains the one defect this paid retry must not
    # repeat.  A populated Beats lane previously suppressed Repair entirely,
    # so a continuity retry could keep the new pace yet reproduce the same
    # shoulder-to-leg jump.  Preserve both independent authorities.
    repair_for_provider = (
        prior_repair_instruction
        if preserve_upstream_repair
        else ""
    )
    if repair_for_provider:
        provider_lines.append(
            "Repair: "
            + compact_repair_instruction(
                repair_for_provider,
                max_characters=145,
            )
        )
    if replanned_beats:
        beats_line = "Beats: " + " | ".join(replanned_beats)
        provider_lines.append(beats_line)
        invariants = structured_video_prompt_semantic_invariants(beats_line)
        if invariants:
            provider_lines.append("Must: " + "; ".join(invariants))
    if provider_direction:
        provider_lines.append("Direction: " + provider_direction)
    if rebuilt_dialogue:
        provider_lines.append(
            "Dialogue: " + " | ".join(rebuilt_dialogue)
        )
    if original:
        provider_lines.append(original)
    repaired = "\n".join(provider_lines).strip()
    retry_input["content_factory_base_prompt"] = repaired
    retry_input["prompt"] = repaired
    prior_execution_contract = dict(
        retry_input.get("content_factory_segment_execution_contract") or {}
    )
    merged_execution_contract = {
        **prior_execution_contract,
        **{
            key: value
            for key, value in replanned_contract.items()
            if key not in {"provider_instruction", "rationale"}
        },
    }
    # The execution replan owns the current segment's motion, shot sequence
    # and reference selection.  It does not own the signed whole-video visual
    # medium.  Earlier retries replaced the complete contract with the
    # narrower replan response, silently deleting animation style and edit
    # grammar; the next provider then drifted into photorealism and a generic
    # slow push-in.  Preserve these immutable lanes from the source contract.
    for immutable_key in (
        "visual_style",
        "visual_grammar",
        "project_visual_style_requirement",
        "continuity_note",
        "negative_prompt",
    ):
        if str(prior_execution_contract.get(immutable_key) or "").strip():
            merged_execution_contract[immutable_key] = (
                prior_execution_contract[immutable_key]
            )
    retry_input["content_factory_segment_execution_contract"] = (
        merged_execution_contract
    )
    retry_input["content_factory_execution_feasibility_replan"] = dict(
        replanned_contract
    )
    active_repair = {
        "policy_version": replanned_contract.get("policy_version"),
        "repair_instruction": provider_instruction,
        "source": "ai_feasibility_replan",
    }
    if preserve_upstream_repair:
        active_repair.update({
            "upstream_repair_policy_version": prior_repair_policy,
            "upstream_repair_instruction": prior_repair_instruction,
        })
    retry_input["content_factory_segment_execution_repair"] = active_repair
    retry_input["content_factory_execution_replan_attempt"] = int(
        retry_input.get("content_factory_execution_replan_attempt") or 0
    ) + 1
    return retry_input


def _apply_ai_segment_reference_strategy(
    retry_input: dict[str, Any],
    retry_files: list[KieFile],
    replanned_contract: dict[str, Any],
) -> tuple[dict[str, Any], list[KieFile]]:
    """Apply a pixel-grounded minimum-reference decision to one retry.

    Seedance treats uploaded stills as strong visual priors. A static product
    close-up can therefore defeat an otherwise correct product-free opening.
    After repeated execution failure the recovery model sees the actual
    reference pixels and may remove only conflicting generated anchors. The
    authoritative product package is retained only when the multimodal
    segment plan says that this segment visibly contains the product.
    """

    selection_present = "keep_reference_aliases" in replanned_contract
    requested = {
        str(value or "").strip()
        for value in list(
            replanned_contract.get("keep_reference_aliases") or []
        )
        if str(value or "").strip()
    }
    refs = [
        dict(item)
        for item in list(retry_input.get("reference_file_paths") or [])
        if isinstance(item, dict)
    ]
    image_files = [
        item for item in retry_files if item.kind == "reference_upload"
    ]
    other_files = [
        item for item in retry_files if item.kind != "reference_upload"
    ]
    if not selection_present or not refs or len(refs) != len(image_files):
        return retry_input, retry_files

    kept_pairs: list[tuple[int, dict[str, Any], KieFile]] = []
    for position, (ref, source_file) in enumerate(
        zip(refs, image_files), 1
    ):
        alias = f"@image{position}"
        if alias in requested:
            kept_pairs.append((position, ref, source_file))
    if not kept_pairs:
        return retry_input, retry_files

    normalized_refs: list[dict[str, Any]] = []
    normalized_manifest: list[dict[str, Any]] = []
    for position, (_old_position, ref, _source_file) in enumerate(
        kept_pairs, 1
    ):
        normalized = dict(ref)
        normalized_refs.append(normalized)
        normalized_manifest.append({
            "alias": f"@image{position}",
            "asset_id": normalized.get("asset_id"),
            "filename": normalized.get("filename"),
            "description": normalized.get("description"),
            "semantic_roles": list(
                normalized.get("semantic_roles") or []
            ),
            "is_product_anchor": bool(
                normalized.get("is_product_anchor")
            ),
        })

    repaired = dict(retry_input)
    repaired["reference_file_paths"] = normalized_refs
    repaired["content_factory_reference_manifest"] = normalized_manifest
    product_required = any(
        bool(ref.get("is_product_anchor")) for ref in normalized_refs
    )
    repaired["content_factory_product_presence_decided_by_model"] = True
    repaired["content_factory_product_required"] = product_required
    repaired["content_factory_product_anchor_required"] = product_required
    repaired["content_factory_product_render_mode"] = (
        "provider_reference" if product_required else "scene_reference"
    )
    if not product_required:
        repaired.pop("content_factory_product_requirement_source", None)
    repaired["content_factory_execution_reference_replan"] = {
        "policy_version": replanned_contract.get("policy_version"),
        "kept_original_aliases": [
            f"@image{old_position}"
            for old_position, _ref, _source_file in kept_pairs
        ],
        "reference_rationale": replanned_contract.get(
            "reference_rationale"
        ),
    }
    return repaired, [
        *[source_file for _position, _ref, source_file in kept_pairs],
        *other_files,
    ]


def _prepare_segment_execution_retry_prompt(
    retry_input: dict[str, Any],
    execution_review: dict[str, Any],
) -> dict[str, Any]:
    """Rebuild a QA retry from the last full AI plan, not its tiny transport.

    The provider-facing Seedance prompt is intentionally compressed to a
    495-character execution view.  Copying that view on the next QA retry and
    merely prefixing another reviewer sentence permanently loses the original
    per-beat actions.  The full model-authored feasibility replan remains in
    task metadata, so recompile from it on every bounded retry.  Only fall back
    to the reviewer sentence when no auditable AI timeline exists yet.
    """

    existing_replan = dict(
        retry_input.get("content_factory_execution_feasibility_replan") or {}
    )
    if any(
        isinstance(row, dict) and str(row.get("action") or "").strip()
        for row in list(existing_replan.get("timeline") or [])
    ):
        rebuilt = _apply_ai_segment_execution_replan(
            retry_input,
            existing_replan,
        )
        rebuilt["content_factory_latest_segment_execution_review"] = dict(
            execution_review
        )
        return rebuilt
    return _apply_segment_execution_retry_prompt(
        retry_input,
        execution_review,
    )


def _has_ai_authored_provider_beats(
    retry_input: dict[str, Any],
) -> bool:
    """Return whether every full audit beat owns a complete transport beat."""

    contract = dict(
        retry_input.get("content_factory_execution_feasibility_replan") or {}
    )
    timeline = [
        row
        for row in list(contract.get("timeline") or [])
        if isinstance(row, dict)
    ]
    if not timeline:
        return False
    key = (
        "provider_action_zh"
        if str(retry_input.get("service_provider") or "").strip().lower()
        == "doubao"
        else "provider_action_en"
    )
    return all(str(row.get(key) or "").strip() for row in timeline)


def _apply_exact_spoken_copy_retry_prompt(
    retry_input: dict[str, Any],
    exact_copy: str,
    *,
    missing_tokens: list[Any] | None = None,
) -> dict[str, Any]:
    """Give immutable copy enough delivery time without rewriting it."""

    text = re.sub(r"\s+", " ", str(exact_copy or "")).strip()
    if not text:
        return retry_input
    contract = dict(
        retry_input.get("content_factory_segment_execution_contract") or {}
    )
    try:
        duration = float(
            retry_input.get("seconds")
            or retry_input.get("duration")
            or contract.get("duration_seconds")
            or 10
        )
    except (TypeError, ValueError):
        duration = 10.0
    duration = max(1.0, duration)
    # Hyphenated names and claims still consume separate spoken units.
    words = re.findall(r"[A-Za-z0-9]+", text)
    # Reserve a small lead-out for the final phoneme. Round upward to a simple
    # five-WPM target so the provider receives one executable delivery rate
    # rather than a conflicting fixed rate inherited from an earlier draft.
    available_seconds = max(0.75, duration - 0.4)
    required_wpm = math.ceil((max(1, len(words)) * 60.0) / available_seconds)
    # Add delivery headroom for punctuation and ingredient pronunciation. The
    # provider otherwise spends the entire clip at the mathematical minimum
    # and drops either the opening brand phrase or the final CTA.
    target_wpm = max(
        120,
        min(200, int(math.ceil((required_wpm + 15) / 5.0) * 5)),
    )
    # A retry may need to speed up enough to preserve exact copy, but it must
    # never silently slow down the Director-signed voice. Short hook videos
    # commonly reserve a final silent reaction beat; computing only from the
    # raw provider duration previously changed a signed 220 WPM delivery to
    # 165 WPM and contradicted that beat. Structured voice continuity is the
    # authority, while the calculated rate remains the minimum needed for the
    # immutable words to fit.
    signed_voice_rates: list[float] = []
    for raw_voice in list(retry_input.get("content_factory_voice_lock") or []):
        if not isinstance(raw_voice, dict):
            continue
        unit = str(
            raw_voice.get("speech_rate_unit") or "words_per_minute"
        ).strip().lower()
        if unit not in {"words_per_minute", "wpm"}:
            continue
        try:
            rate = float(raw_voice.get("speech_rate") or 0)
        except (TypeError, ValueError):
            continue
        if rate > 0:
            signed_voice_rates.append(rate)
    if signed_voice_rates:
        signed_wpm = int(
            math.ceil(max(signed_voice_rates) / 5.0) * 5
        )
        target_wpm = min(400, max(target_wpm, signed_wpm))
    missed = [
        re.sub(r"[^A-Za-z0-9'-]+", "", str(value)).strip()
        for value in list(missing_tokens or [])[:8]
    ]
    missed = [value for value in missed if value]
    missed_instruction = (
        " Pronounce these previously missed words distinctly in their exact "
        "original positions: " + ", ".join(missed) + "."
        if missed
        else ""
    )
    # Providers sometimes interpret a leading ``Brand/Product: claim`` phrase
    # as prompt metadata and begin the generated speech after the colon.  Keep
    # the signed copy immutable, but make its first delivery boundary explicit
    # so the product name is spoken rather than silently treated as a title.
    leading_colon = re.match(r"^([^:\n]{1,96}):\s*(.+)$", text)
    opening_instruction = ""
    if leading_colon:
        opening = leading_colon.group(1).strip()
        remainder = leading_colon.group(2).strip()
        opening_words = re.findall(r"[A-Za-z0-9]+", opening)
        opening_end = max(
            0.6,
            min(
                duration - 0.5,
                (len(opening_words) * 60.0 / float(target_wpm)) + 0.2,
            ),
        )
        opening_instruction = (
            " The words before the first colon are spoken dialogue, not a "
            "title, label, speaker name, caption, or metadata. From 0.0 to "
            f"approximately {opening_end:.1f} seconds, first say exactly: "
            f'\"{opening}.\" Only after that phrase is complete, continue '
            f'exactly with: \"{remainder}\" Do not display or silently skip '
            "the opening phrase."
        )
    clause = (
        "COPY DELIVERY REPAIR (highest audio priority): Begin speaking at "
        f"0.0 seconds, use approximately {target_wpm} words per minute with "
        "no introductory pause, and speak every word of this exact dialogue "
        f"once without omission, paraphrase, or added words: {text}"
        + opening_instruction
        + missed_instruction
        + " Stop speaking immediately after the exact final word."
    )

    for key in ("prompt", "content_factory_base_prompt"):
        original = str(retry_input.get(key) or "").strip()
        clean = "\n".join(
            line
            for line in original.splitlines()
            if not line.strip().startswith("COPY DELIVERY REPAIR (")
        ).strip()
        clean = re.sub(
            r"\b\d{2,3}\s+words\s+per\s+minute\b",
            f"{target_wpm} words per minute",
            clean,
            flags=re.IGNORECASE,
        )
        clean = re.sub(
            r"\b\d{2,3}\s*WPM\b",
            f"{target_wpm} WPM",
            clean,
            flags=re.IGNORECASE,
        )
        retry_input[key] = (clause + "\n\n" + clean).strip()
    retry_input["content_factory_copy_delivery_target_wpm"] = target_wpm
    return retry_input


def _uses_only_local_voiceover(params: dict[str, Any]) -> bool:
    rows = [
        dict(item)
        for item in list(params.get("content_factory_dialogue_lines") or [])
        if isinstance(item, dict)
        and str(item.get("delivery_mode") or "spoken").strip().lower()
        == "spoken"
        and str(item.get("line") or "").strip()
    ]
    return bool(rows) and all(
        str(item.get("delivery_method") or "provider_dialogue")
        .strip()
        .lower()
        == "local_voiceover"
        for item in rows
    )


def _reconcile_segment_execution_qa_after_policy_change(
    db,
    *,
    project: HermesContentFactoryProject,
    task: KieTask,
) -> bool:
    """Re-review a downloaded clip when only the semantic gate changed.

    Provider pixels are immutable and already paid for.  A newer inspector
    policy must first evaluate that local artifact instead of submitting a
    duplicate generation.  Reconciliation is allowed only for the explicit
    segment-execution semantic failure, only when the cached policy is stale,
    and only after the new multimodal gate returns a non-blocking verdict.
    """

    local_meta = dict(get_task_local_meta(task) or {})
    # A final-composition intent failure is not a stale per-segment gate.
    # Re-running only the segment execution reviewer can legitimately pass the
    # same pixels while the composition-level reviewer still rejects spoken
    # copy or cross-segment continuity.  Treating that pass as a policy
    # reconciliation reactivates the same paid result and creates an endless
    # wait/review loop instead of a new bounded repair attempt.
    if (
        isinstance(local_meta.get("final_intent_qa_failure"), dict)
        or "CONTENT_FINAL_INTENT_QA_FAILED" in str(task.fail_msg or "")
    ):
        return False
    prior_review = dict(local_meta.get("segment_execution_review") or {})
    if (
        str(prior_review.get("policy_version") or "").strip()
        == SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
    ):
        return False
    try:
        source, _result_file = _result_video_for_task(db, task)
        review = _review_provider_segment_execution(
            db,
            project=project,
            source=source,
            task=task,
        )
    except (ContentFactoryApiError, RuntimeError, ValueError):
        return False
    if not isinstance(review, dict) or bool(review.get("blocking")):
        return False
    task.state = "success"
    task.fail_code = None
    task.fail_msg = None
    set_task_local_meta(
        task,
        content_quality_incident=None,
        segment_execution_qa_failed_at=None,
        segment_execution_qa_policy_reconciled_at=_stage_now().isoformat(),
        segment_execution_qa_policy_reconciled_from=(
            str(prior_review.get("policy_version") or "legacy")
        ),
    )
    db.add(task)
    db.flush()
    return True


def _reconcile_product_visual_qa_after_policy_change(
    db,
    *,
    project: HermesContentFactoryProject,
    task: KieTask,
) -> bool:
    """Re-review an already downloaded product clip under a newer policy.

    Product generation is paid and immutable.  When only the multimodal review
    policy changes, reuse the local result and authoritative product reference
    instead of submitting another provider task.
    """

    local_meta = dict(get_task_local_meta(task) or {})
    prior_review = dict(local_meta.get("provider_product_video_review") or {})
    if (
        str(prior_review.get("policy_version") or "").strip()
        == PRODUCT_REFERENCE_VIDEO_REVIEW_POLICY_VERSION
    ):
        return False
    try:
        source, _result_file = _result_video_for_task(db, task)
        review = _review_provider_product_segment(
            db,
            project=project,
            source=source,
            task=task,
        )
    except (ContentFactoryApiError, RuntimeError, ValueError):
        return False
    if not isinstance(review, dict) or bool(review.get("blocking")):
        return False
    task.state = "success"
    task.fail_code = None
    task.fail_msg = None
    set_task_local_meta(
        task,
        content_quality_incident=None,
        product_visual_qa_failed_at=None,
        product_visual_qa_policy_reconciled_at=_stage_now().isoformat(),
        product_visual_qa_policy_reconciled_from=(
            str(prior_review.get("policy_version") or "legacy")
        ),
    )
    db.add(task)
    db.flush()
    return True


def _restore_inherited_final_intent_repair(
    db,
    *,
    project: HermesContentFactoryProject,
    failed_task: KieTask,
    failed_meta: dict[str, Any],
    retry_input: dict[str, Any],
) -> dict[str, Any]:
    """Recover final-QA repair evidence lost by an older AI replan.

    A feasibility replan owns executable choreography, but it must not erase
    the pixel/speech defects that caused the parent task to be rejected.  Some
    tasks created before the upstream-repair fields existed only retain that
    evidence on their immediate parent.  Restore it through the audited retry
    lineage, while enforcing workspace/project/video/segment isolation.
    """

    repair = dict(
        retry_input.get("content_factory_segment_execution_repair") or {}
    )
    if (
        str(repair.get("source") or "").strip() != "ai_feasibility_replan"
        or str(repair.get("upstream_repair_instruction") or "").strip()
    ):
        return retry_input
    try:
        parent_task_id = int(
            failed_meta.get("content_factory_retry_parent_task_id") or 0
        )
    except (TypeError, ValueError):
        return retry_input
    if parent_task_id <= 0 or parent_task_id == int(failed_task.id):
        return retry_input
    project_key = str(project.project_key or "").strip()
    failed_input = dict(failed_task.input_json or {})
    parent_review: dict[str, Any] = {}
    repair_ancestor_id = 0
    visited = {int(failed_task.id)}
    # Recovery can itself fail at the provider before a new clip exists. Walk
    # through those transport-only descendants to the nearest evidence-bearing
    # ancestor instead of losing the original multimodal defect on generation
    # two. The traversal is deliberately shallow and identity-checked at every
    # hop so malformed lineage cannot cross a task boundary.
    for _ in range(8):
        if parent_task_id <= 0 or parent_task_id in visited:
            break
        visited.add(parent_task_id)
        parent = db.get(KieTask, parent_task_id)
        if parent is None or int(parent.workspace_id) != int(project.workspace_id):
            return retry_input
        parent_meta = dict(get_task_local_meta(parent) or {})
        parent_input = dict(parent.input_json or {})
        parent_project_key = str(
            parent_meta.get("content_factory_project_key")
            or parent_input.get("content_factory_project_key")
            or ""
        ).strip()
        if (
            project_key
            and parent_project_key
            and parent_project_key != project_key
        ):
            return retry_input
        for identity_key in (
            "content_factory_video_index",
            "content_factory_segment_index",
        ):
            failed_value = failed_input.get(identity_key)
            parent_value = parent_input.get(identity_key)
            if parent_value is None:
                parent_value = parent_meta.get(identity_key)
            if failed_value is None or parent_value is None:
                continue
            try:
                identity_matches = int(failed_value) == int(parent_value)
            except (TypeError, ValueError):
                identity_matches = (
                    str(failed_value).strip() == str(parent_value).strip()
                )
            if not identity_matches:
                return retry_input
        candidate_review = dict(
            parent_meta.get("final_intent_qa_failure") or {}
        )
        if str(candidate_review.get("repair_instruction") or "").strip():
            parent_review = candidate_review
            repair_ancestor_id = parent_task_id
            break
        try:
            parent_task_id = int(
                parent_meta.get("content_factory_retry_parent_task_id") or 0
            )
        except (TypeError, ValueError):
            break

    instruction = re.sub(
        r"\s+",
        " ",
        str(parent_review.get("repair_instruction") or "").strip(),
    )
    policy_version = str(parent_review.get("policy_version") or "").strip()
    if not instruction or (
        policy_version
        and policy_version
        not in {
            str(FINAL_INTENT_REVIEW_POLICY_VERSION),
            str(SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION),
        }
    ):
        return retry_input

    repair.update({
        "upstream_repair_policy_version": policy_version,
        "upstream_repair_instruction": instruction,
        "upstream_repair_parent_task_id": repair_ancestor_id,
    })
    retry_input["content_factory_segment_execution_repair"] = repair
    return retry_input


def _restore_authoritative_segment_direction_from_source_stage(
    db,
    *,
    project: HermesContentFactoryProject,
    retry_input: dict[str, Any],
) -> dict[str, Any]:
    """Restore signed style/edit lanes before recompiling a legacy retry.

    Provider tasks intentionally keep a compact execution packet, while the
    successful VIDEO_PROMPTS stage keeps the complete signed visual contract.
    Tasks created by the former compiler omitted the style and edit-grammar
    lanes. Copying such a task for recovery made every later multimodal pass
    blind to the project's animation medium and encouraged generic slow
    push-ins. Recover only from the exact tenant/project-owned source stage
    stamped on the task; never infer these values from another project.
    """

    restored = dict(retry_input or {})
    try:
        source_stage_id = int(
            restored.get("content_factory_source_stage_id") or 0
        )
        video_index = int(
            restored.get("content_factory_video_index") or 0
        )
        segment_index = int(
            restored.get("content_factory_segment_index") or 0
        )
    except (TypeError, ValueError):
        return restored
    if source_stage_id <= 0 or segment_index <= 0:
        return restored
    source_stage = db.get(HermesContentFactoryStage, source_stage_id)
    if (
        source_stage is None
        or int(source_stage.project_id) != int(project.id)
        or str(source_stage.stage or "") != "VIDEO_PROMPTS"
        or str(source_stage.status or "").lower() != "success"
    ):
        return restored
    result = dict(dict(source_stage.output_json or {}).get("result") or {})
    videos = [
        dict(item)
        for item in list(result.get("videos") or [])
        if isinstance(item, dict)
    ]
    if not videos:
        return restored
    # Sequential production stores one video in each source stage even when
    # its global variant index is greater than one. Multi-video stages retain
    # positional selection.
    if len(videos) == 1:
        source_video = videos[0]
    elif 0 < video_index <= len(videos):
        source_video = videos[video_index - 1]
    else:
        return restored
    source_segments = [
        dict(item)
        for item in list(source_video.get("segments") or [])
        if isinstance(item, dict)
    ]
    source_segment = next(
        (
            item
            for offset, item in enumerate(source_segments, 1)
            if int(item.get("segment_index") or offset) == segment_index
        ),
        None,
    )
    if source_segment is None:
        return restored

    visual_style = str(
        source_segment.get("visual_style")
        or source_video.get("visual_style")
        or ""
    ).strip()
    visual_grammar = str(
        source_segment.get("visual_grammar")
        or source_video.get("visual_grammar")
        or ""
    ).strip()
    source_pacing = str(
        source_segment.get("pacing") or visual_grammar or ""
    ).strip()
    source_camera = str(
        source_segment.get("camera_direction") or ""
    ).strip()
    contract = dict(
        restored.get("content_factory_segment_execution_contract") or {}
    )
    if visual_style:
        contract["visual_style"] = visual_style
        restored["content_factory_visual_style_requirement"] = visual_style
    if visual_grammar:
        contract["visual_grammar"] = visual_grammar
        restored["content_factory_visual_grammar"] = visual_grammar
    if source_pacing and not str(contract.get("pacing") or "").strip():
        contract["pacing"] = source_pacing
    if source_camera and not str(
        contract.get("camera_direction") or ""
    ).strip():
        contract["camera_direction"] = source_camera
    restored["content_factory_segment_execution_contract"] = contract
    restored["content_factory_source_direction_restored"] = bool(
        visual_style or visual_grammar
    )
    return restored


def _attach_final_intent_repair_evidence(
    task: KieTask,
    report: dict[str, Any],
) -> None:
    """Bind one composed-video verdict to the exact failed segment task.

    Final intent QA runs after composition, so its repair packet originally
    lived only on the project.  Segment retry compilation reads task-local
    evidence.  Persist the scoped verdict on each named task before planning
    the replacement; otherwise a feasibility replan can see only an older
    segment review and silently omit the defect that caused final QA to fail.
    """

    params = dict(task.input_json or {})
    try:
        segment_index = int(params.get("content_factory_segment_index") or 0)
    except (TypeError, ValueError):
        segment_index = 0
    packet = {
        "policy_version": str(
            report.get("policy_version") or FINAL_INTENT_REVIEW_POLICY_VERSION
        ),
        "repair_instruction": str(report.get("repair_instruction") or "").strip(),
        "blocking_reasons": [
            str(value).strip()
            for value in list(report.get("blocking_reasons") or [])
            if str(value).strip()
        ][:12],
        "failed_requirement_ids": [
            str(value).strip()
            for value in list(report.get("blocking_requirement_ids") or [])
            if str(value).strip()
        ][:64],
        "affected_segment_indices": [
            int(value)
            for value in list(report.get("affected_segment_indices") or [])
            if str(value).strip().isdigit()
        ][:32],
        "segment_index": segment_index,
        "repair_scope": str(report.get("repair_scope") or "segment_regeneration"),
    }
    set_task_local_meta(task, final_intent_qa_failure=packet)


def _final_intent_segment_repair_budget(
    *,
    retry_key: str,
    normalized_failure_code: str,
    failed_meta: dict[str, Any],
    quality_retry_counts: dict[str, Any],
    config: dict[str, Any],
) -> tuple[bool, str, int, int]:
    """Return the isolated, incident-bounded final-composite repair budget.

    A segment can pass its own review and only later fail when the composed
    video exposes a boundary defect (for example the recurring creator changes
    between two otherwise valid clips).  That is a new multimodal observation,
    not another attempt at the earlier product/segment defect.  Reusing the
    generic segment-execution counter made this repair appear exhausted before
    it had ever run.  Bind one bounded attempt to the immutable final-review
    packet so the new defect can heal once without opening an infinite loop.
    """

    review = dict(failed_meta.get("final_intent_qa_failure") or {})
    instruction = re.sub(
        r"\s+",
        " ",
        str(review.get("repair_instruction") or "").strip(),
    )
    if not instruction:
        return False, "", 0, 0
    incident_payload = {
        "policy_version": str(
            review.get("policy_version") or FINAL_INTENT_REVIEW_POLICY_VERSION
        ),
        "repair_scope": str(review.get("repair_scope") or "segment_regeneration"),
        "segment_index": int(review.get("segment_index") or 0),
        "affected_segment_indices": sorted(
            int(value)
            for value in list(review.get("affected_segment_indices") or [])
            if str(value).strip().isdigit()
        ),
    }
    incident_hash = hashlib.sha256(
        json.dumps(
            incident_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()[:20]
    budget_key = (
        f"{retry_key}:final_intent:{normalized_failure_code}:{incident_hash}"
    )
    retry_limit = max(
        0,
        min(
            2,
            int(
                config.get("content_factory_final_intent_segment_retry_limit")
                if config.get("content_factory_final_intent_segment_retry_limit")
                is not None
                else 1
            ),
        ),
    )
    current_count = int(quality_retry_counts.get(budget_key) or 0)
    return True, budget_key, retry_limit, current_count


def _bind_final_intent_identity_anchor(
    db,
    *,
    project: HermesContentFactoryProject,
    failed_task: KieTask,
    group: dict[str, Any],
    retry_input: dict[str, Any],
    retry_files: list[KieFile],
    final_intent_review: dict[str, Any],
) -> tuple[dict[str, Any], list[KieFile]]:
    """Attach the preceding accepted pixels as identity-only continuity.

    References anchor cast, scene and product; the timed prompt remains the
    sole authority for action, camera and editing.  The final reviewer is the
    first stage that can prove a cross-clip identity mismatch, so a targeted
    repair needs the accepted preceding clip rather than merely repeating the
    original storyboard still.  This does not turn Seedance into first-frame
    continuation and therefore cannot freeze the new segment's pose or motion.
    """

    instruction_text = " ".join((
        str(final_intent_review.get("repair_instruction") or ""),
        " ".join(
            str(value)
            for value in list(final_intent_review.get("blocking_reasons") or [])
        ),
    )).lower()
    if not any(
        marker in instruction_text
        for marker in (
            "identity",
            "same recurring creator",
            "same adult",
            "same face",
            "same character",
            "hair",
            "wardrobe",
            "cast continuity",
            "人物连续",
            "同一人物",
            "同一角色",
        )
    ):
        return retry_input, retry_files
    try:
        video_index = int(retry_input.get("content_factory_video_index") or 0)
        segment_index = int(retry_input.get("content_factory_segment_index") or 0)
    except (TypeError, ValueError):
        return retry_input, retry_files
    if video_index <= 0 or segment_index <= 1:
        return retry_input, retry_files
    previous_segment = max(
        (
            dict(item)
            for item in list(group.get("segments") or [])
            if isinstance(item, dict)
            and 0 < int(item.get("segment_index") or 0) < segment_index
        ),
        key=lambda item: int(item.get("segment_index") or 0),
        default=None,
    )
    if previous_segment is None:
        return retry_input, retry_files
    try:
        previous_task_id = int(previous_segment.get("task_id") or 0)
    except (TypeError, ValueError):
        return retry_input, retry_files
    previous_task = db.get(KieTask, previous_task_id)
    if (
        previous_task is None
        or int(previous_task.workspace_id) != int(project.workspace_id)
        or (
            project.user_id is not None
            and int(previous_task.created_by_user_id or 0) != int(project.user_id)
        )
        or str(previous_task.state or "").strip().lower() != "success"
    ):
        return retry_input, retry_files
    previous_input = dict(previous_task.input_json or {})
    if (
        int(previous_input.get("content_factory_project_id") or 0)
        != int(project.id)
        or int(previous_input.get("content_factory_video_index") or 0)
        != video_index
    ):
        return retry_input, retry_files
    try:
        previous_video, _ = _result_video_for_task(db, previous_task)
    except (OSError, RuntimeError, ValueError):
        return retry_input, retry_files
    continuity_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
        / "generated"
        / "continuity_frames"
    )
    continuity_path = continuity_dir / (
        f"video-{video_index:02d}-segment-{segment_index - 1:02d}-"
        f"final-intent-task-{int(previous_task.id)}.png"
    )
    try:
        if not continuity_path.is_file() or continuity_path.stat().st_size < 1024:
            _extract_segment_last_frame(previous_video, continuity_path)
    except (OSError, RuntimeError):
        return retry_input, retry_files
    reference = {
        "path": str(continuity_path),
        "role": "final_intent_identity_anchor",
        "index": 0,
        "asset_id": 0,
        "filename": continuity_path.name,
        "size_bytes": int(continuity_path.stat().st_size),
        "description": (
            "Exact accepted preceding-segment frame. Preserve only recurring "
            "adult identity, face, hair, wardrobe, illustration medium and "
            "shared room design; do not copy its pose, framing or action."
        ),
        "content_type": "image/png",
        "semantic_roles": ["character_anchor", "scene_anchor"],
        "is_product_anchor": False,
        "is_continuity_frame": True,
        "final_intent_identity_only": True,
    }
    refs = [
        dict(item)
        for item in list(retry_input.get("reference_file_paths") or [])
        if isinstance(item, dict)
        and str(item.get("path") or "").strip() != str(continuity_path)
        and not bool(item.get("final_intent_identity_only"))
    ]
    retry_input["reference_file_paths"] = [reference, *refs]
    retry_input["content_factory_final_intent_identity_anchor_task_id"] = int(
        previous_task.id
    )
    # This is an identity reference, not an exact first-frame continuation.
    retry_input["content_factory_first_frame"] = False
    retry_input["content_factory_requires_previous_segment_frame"] = False

    source_file = (
        db.query(KieFile)
        .filter(
            KieFile.task_id == int(failed_task.id),
            KieFile.workspace_id == int(project.workspace_id),
            KieFile.kind == "reference_upload",
            KieFile.file_url == str(continuity_path),
        )
        .one_or_none()
    )
    if source_file is None:
        source_file = KieFile(
            workspace_id=int(project.workspace_id),
            key_id=int(failed_task.key_id),
            task_id=int(failed_task.id),
            file_url=str(continuity_path),
            kind="reference_upload",
            mime_type="image/png",
            size_bytes=int(continuity_path.stat().st_size),
            meta_json={
                "filename": continuity_path.name,
                "source": "hermes_final_intent_identity_anchor",
                "semantic_roles": ["character_anchor", "scene_anchor"],
                "is_product_anchor": False,
                "is_continuity_frame": True,
                "final_intent_identity_only": True,
                "continuity_source_task_id": int(previous_task.id),
                "video_index": video_index,
                "segment_index": segment_index,
            },
        )
        db.add(source_file)
        db.flush()
    retry_files = [
        source_file,
        *[
            item
            for item in retry_files
            if str(item.file_url or "").strip() != str(continuity_path)
        ],
    ]
    return retry_input, retry_files


def _retry_failed_video_segments(
    db,
    project: HermesContentFactoryProject,
    failed_tasks: list[KieTask],
    *,
    allow_exhausted_cooldown_retry: bool = False,
) -> list[int]:
    config = dict(project.config_json or {})
    # Paid provider work gets a deliberately small per-segment budget. A
    # project may lower or raise it explicitly, but the generic production
    # default is two retries rather than five blind resubmissions.
    retry_limit = max(0, min(3, int(config.get("content_factory_video_retry_limit") or 2)))
    if retry_limit <= 0:
        return []
    provider_cycle_cooldown_seconds = max(
        30,
        min(
            1800,
            int(
                config.get("content_factory_video_provider_cycle_cooldown_seconds")
                or config.get("content_factory_video_exhausted_cooldown_seconds")
                or 180
            ),
        ),
    )
    exhausted_recovery_limit = max(
        1,
        min(
            10,
            int(
                config.get("content_factory_video_exhausted_recovery_limit")
                or 5
            ),
        ),
    )
    account_rotation_retry_limit = max(
        1,
        min(
            20,
            int(
                config.get("content_factory_video_account_rotation_retry_limit")
                or 8
            ),
        ),
    )
    state = dict(project.state_json or {})
    blocked_asset_ids = _blocked_reference_asset_ids(state)
    retry_counts = dict(state.get("ai_video_segment_retry_counts") or {})
    # Transport/account/provider recovery and evidence-backed quality repair
    # are different budgets.  A segment can spend several provider attempts
    # before one result is downloaded; those failures must not consume the
    # bounded opportunity to repair pixels or spoken copy that the multimodal
    # reviewer has actually inspected.
    quality_retry_counts = dict(
        state.get("ai_video_segment_quality_retry_counts") or {}
    )
    retry_history = list(state.get("ai_video_retry_history") or [])[-99:]
    recovery_generations = dict(
        state.get("ai_video_exhausted_cooldown_retry_generations") or {}
    )
    account_rotation_retry_counts = dict(
        state.get("ai_video_account_rotation_retry_counts") or {}
    )
    groups = json.loads(json.dumps(list(state.get("ai_video_groups") or []), ensure_ascii=False))
    active_task_ids = [int(value) for value in list(state.get("ai_video_task_ids") or [])]
    retried_tasks: list[tuple[KieTask, str]] = []
    adopted_retry_task_ids: list[int] = []
    policy_reconciled_task_ids: list[int] = []
    replaced_task_ids: set[int] = set()
    restored_dependency_ids: set[int] = set()
    task_by_id = {int(task.id): task for task in failed_tasks}

    grouped_task_ids = {
        int(segment.get("task_id") or 0)
        for group in groups
        if isinstance(group, dict)
        for segment in list(group.get("segments") or [])
        if isinstance(segment, dict)
    }
    for failed in failed_tasks:
        # A dependency failure is deliberately terminal until its predecessor
        # is restored.  It has no independent provider submission to recover,
        # and asking the immutable ledger to reconstruct one can both waste a
        # query and accidentally resurrect a mid-story segment without its
        # authoritative continuity frame.
        if _is_unreleasable_dependency_failure(failed):
            continue
        if int(failed.id) in grouped_task_ids:
            continue
        recovered_group = _recover_media_group_from_execution_ledger(
            db,
            project=project,
            task=failed,
        )
        if recovered_group is None:
            continue
        recovered_video_index = int(
            recovered_group.get("video_index") or 0
        )
        groups = [
            group
            for group in groups
            if int(dict(group).get("video_index") or 0)
            != recovered_video_index
        ]
        groups.append(recovered_group)
        grouped_task_ids.update(
            int(segment.get("task_id") or 0)
            for segment in list(recovered_group.get("segments") or [])
            if isinstance(segment, dict)
        )
        for recovered_task_id in grouped_task_ids:
            if recovered_task_id > 0 and recovered_task_id not in active_task_ids:
                active_task_ids.append(recovered_task_id)

    segment_locations: dict[int, tuple[dict[str, Any], dict[str, Any], str]] = {}
    for group in groups:
        video_index = int(group.get("video_index") or 0)
        for segment in list(group.get("segments") or []):
            segment_index = int(segment.get("segment_index") or 0)
            segment_locations[int(segment.get("task_id") or 0)] = (
                group,
                segment,
                f"{video_index}:{segment_index}",
            )

    affected_video_indices: set[int] = set()
    for failed in failed_tasks:
        # Retrying an earlier segment restores its downstream chain in-place.
        # ``failed_tasks`` still contains those same ORM objects from the
        # pre-repair snapshot, so never continue around the loop and reset a
        # just-restored successor as an independent paid retry.  It must stay
        # dormant until the predecessor supplies an authoritative final frame.
        if int(failed.id) in restored_dependency_ids:
            continue
        # A chained segment whose predecessor exhausted its retries cannot be
        # regenerated independently: it has no authoritative continuity
        # frame.  Keep it terminal so the whole variant can be replenished
        # instead of accidentally submitting a broken mid-story clip.
        normalized_failure_code = _normalize_segment_release_failure_code(
            failed
        )
        if (
            normalized_failure_code == SEGMENT_EXECUTION_QA_FAIL_CODE
            and _reconcile_segment_execution_qa_after_policy_change(
                db,
                project=project,
                task=failed,
            )
        ):
            policy_reconciled_task_ids.append(int(failed.id))
            continue
        if (
            normalized_failure_code == PRODUCT_VISUAL_QA_FAIL_CODE
            and _reconcile_product_visual_qa_after_policy_change(
                db,
                project=project,
                task=failed,
            )
        ):
            policy_reconciled_task_ids.append(int(failed.id))
            continue
        failed_meta = dict(get_task_local_meta(failed) or {})
        # ``doubao_failed_account_bridge_ids`` is a submission-round fence,
        # not durable account truth.  The pool already persists real CAPTCHA,
        # auth, quota and health observations on the account itself.  Carrying
        # this task-local list into a replacement row permanently excluded
        # Profiles that had only hit a now-fixed client/UI defect, eventually
        # leaving a healthy pool with no selectable account.  Every paid-safe
        # replacement therefore starts a fresh round and lets the pool's live
        # state choose accounts; failures within that row are still fenced by
        # ``submit_doubao_task`` so one delivery never loops on one Profile.
        if _is_unreleasable_dependency_failure(failed):
            continue
        location = segment_locations.get(int(failed.id))
        if location is None:
            continue
        group, segment, retry_key = location
        affected_video_indices.add(int(group.get("video_index") or 0))
        # A guardian and an operator resume used to be able to compile the
        # same final-QA repair across the internal commit boundary below.  If
        # one paid child is already live or successful, adopt it into the
        # project ledger instead of creating another provider request.  Scope
        # by tenant, project, variant, segment, parent incident and compiler
        # policy so an unrelated task can never be attached.
        replacement_candidates = (
            db.query(KieTask)
            .filter(
                KieTask.workspace_id == int(project.workspace_id),
                KieTask.created_by_user_id == project.user_id,
                KieTask.id > int(failed.id),
            )
            .order_by(KieTask.id.desc())
            .limit(100)
            .all()
        )
        existing_retry_child = next(
            (
                candidate
                for candidate in replacement_candidates
                if str(candidate.state or "").strip().lower()
                not in {"failed", "fail", "error", "timeout", "cancelled"}
                and int(
                    dict(candidate.input_json or {}).get(
                        "content_factory_project_id"
                    )
                    or 0
                )
                == int(project.id)
                and int(
                    dict(candidate.input_json or {}).get(
                        "content_factory_video_index"
                    )
                    or 0
                )
                == int(group.get("video_index") or 0)
                and int(
                    dict(candidate.input_json or {}).get(
                        "content_factory_segment_index"
                    )
                    or 0
                )
                == int(segment.get("segment_index") or 0)
                and str(
                    dict(candidate.input_json or {}).get(
                        "content_factory_prompt_policy_version"
                    )
                    or ""
                )
                == VIDEO_PROMPT_POLICY_VERSION
                and int(
                    dict(get_task_local_meta(candidate) or {}).get(
                        "content_factory_retry_parent_task_id"
                    )
                    or 0
                )
                == int(failed.id)
            ),
            None,
        )
        if existing_retry_child is not None:
            old_task_id = int(failed.id)
            new_task_id = int(existing_retry_child.id)
            segment["task_id"] = new_task_id
            segment["retry_source_task_id"] = old_task_id
            segment["retry_adopted_existing_child"] = True
            active_task_ids = [
                task_id
                for task_id in active_task_ids
                if int(task_id) != old_task_id
            ]
            if new_task_id not in active_task_ids:
                active_task_ids.append(new_task_id)
            replaced_task_ids.add(old_task_id)
            adopted_retry_task_ids.append(new_task_id)
            set_task_local_meta(
                failed,
                content_factory_retry_child_task_id=new_task_id,
                content_factory_retry_child_adopted_at=(
                    datetime.now(timezone.utc)
                    .replace(tzinfo=None)
                    .isoformat()
                ),
            )
            db.add(failed)
            continue
        if not _content_factory_retryable_video_failure(failed):
            continue
        segment["dialogue_lines"] = _dialogue_without_display_lines(
            segment.get("dialogue_lines"),
            segment.get("display_lines"),
        )
        quality_repair = normalized_failure_code in {
            "segment_release_quality_gate",
            "copy_delivery_invalid",
            "content_factory_continuity_frame_missing",
            SEGMENT_EXECUTION_QA_FAIL_CODE,
            PRODUCT_VISUAL_QA_FAIL_CODE,
            VOICE_CONTINUITY_FAIL_CODE,
            SPOKEN_COPY_FAIL_CODE,
            # A request-level Flow 400 is a new semantic incident discovered
            # only after the provider parsed the compiled request. Keep its
            # multimodal re-authoring budget separate from already-spent
            # transport/account retries.
            "flow_request_rejected",
        }
        final_intent_review = dict(
            failed_meta.get("final_intent_qa_failure") or {}
        )
        (
            final_intent_repair,
            final_intent_retry_key,
            final_intent_retry_limit,
            final_intent_retry_count,
        ) = _final_intent_segment_repair_budget(
            retry_key=retry_key,
            normalized_failure_code=normalized_failure_code,
            failed_meta=failed_meta,
            quality_retry_counts=quality_retry_counts,
            config=config,
        )
        quality_repair = bool(quality_repair or final_intent_repair)
        quality_policy_version = str(
            dict(failed_meta.get("final_intent_qa_failure") or {}).get(
                "policy_version"
            )
            or dict(failed_meta.get("segment_execution_review") or {}).get(
                "policy_version"
            )
            or dict(failed_meta.get("provider_product_video_review") or {}).get(
                "policy_version"
            )
            or dict(failed_meta.get("spoken_copy_review") or {}).get(
                "policy_version"
            )
            or "current"
        ).strip()
        quality_retry_key = (
            final_intent_retry_key
            if final_intent_repair
            else f"{retry_key}:{normalized_failure_code}:{quality_policy_version}"
        )
        if final_intent_repair:
            segment_retry_limit = final_intent_retry_limit
            current_count = final_intent_retry_count
        else:
            segment_retry_limit = max(
                0,
                min(
                    3,
                    int(
                        config.get("content_factory_video_quality_retry_limit")
                        or 2
                        if quality_repair
                        else (
                            group.get("provider_retry_budget_per_segment")
                            if group.get("provider_retry_budget_per_segment") is not None
                            else retry_limit
                        )
                    ),
                ),
            )
            current_count = int(
                (
                    quality_retry_counts.get(quality_retry_key)
                    if quality_repair
                    else retry_counts.get(retry_key)
                )
                or 0
            )
        quota_failed_key_ids = {
            int(value)
            for value in list(
                failed_meta.get("provider_quota_failed_key_ids") or []
            )
            if str(value).strip().isdigit()
        }
        failed_input = dict(failed.input_json or {})
        copy_failure_code = _content_task_effective_failure_code(failed)
        effective_failure_message = _content_task_effective_failure_message(
            failed
        )
        spoken_copy_failure = bool(
            copy_failure_code == SPOKEN_COPY_FAIL_CODE
        )
        copy_delivery_repair = bool(
            not bool(failed_input.get("content_factory_copy_delivery_repaired"))
            and (
                (
                    copy_failure_code == "copy_delivery_invalid"
                    and _content_task_nonspoken_dialogue_rows(failed)
                )
                or spoken_copy_failure
            )
        )
        legacy_identity_migration = bool(
            str(failed_meta.get("content_factory_retry_mode") or "")
            == "same_task_id"
            and "idempotency key was reused with a different request"
            in effective_failure_message.lower()
        )
        needs_policy_migration = (
            str(failed_input.get("content_factory_prompt_policy_version") or "")
            != VIDEO_PROMPT_POLICY_VERSION
        )
        # A deployment is never a free retry. Count every paid attempt under
        # the frozen media manifest even if repair logic uses the newer local
        # compiler for the next bounded attempt.
        # Historical workers rewrote prompts/references on the same task id.
        # Flow correctly rejected those calls with 409, but the project then
        # counted every conflict as a paid generation attempt. Migrate that
        # poisoned identity once to a fresh task and restart the real bounded
        # repair budget; after the pointer replacement this condition cannot
        # match again.
        # A new transport/compiler policy materially changes the provider
        # request. Give that new policy its own bounded retry budget exactly
        # once; the replacement task is stamped with the current version, so
        # subsequent failures cannot reset the counter again.
        effective_count = (
            0
            if legacy_identity_migration or needs_policy_migration
            else current_count
        )
        account_rotation_retry = _content_factory_account_rotation_failure(
            failed
        )
        local_transport_rebuild = (
            _content_factory_local_transport_rebuild_failure(failed)
        )
        account_rotation_count = int(
            account_rotation_retry_counts.get(retry_key) or 0
        )
        account_rotation_retry_allowed = bool(
            account_rotation_retry
            and account_rotation_count < account_rotation_retry_limit
        )
        provider_cycle_retry = (
            not local_transport_rebuild
            and normalized_failure_code not in {
                "segment_release_quality_gate",
                "copy_delivery_invalid",
                "content_factory_continuity_frame_missing",
                VOICE_CONTINUITY_FAIL_CODE,
                PRODUCT_VISUAL_QA_FAIL_CODE,
                SEGMENT_EXECUTION_QA_FAIL_CODE,
            }
            and not legacy_identity_migration
        )
        if (
            not account_rotation_retry_allowed
            and not copy_delivery_repair
            and
            provider_cycle_retry
            and not _content_factory_account_rotation_failure(failed)
            and not _content_factory_provider_cycle_cooldown_elapsed(
                failed,
                now=_stage_now(),
                cooldown_seconds=provider_cycle_cooldown_seconds,
            )
        ):
            continue
        exhausted_cooldown_retry = bool(
            not copy_delivery_repair
            and
            allow_exhausted_cooldown_retry
            and _should_retry_exhausted_content_video_after_cooldown(
                failed,
                retry_key=retry_key,
                effective_count=effective_count,
                retry_limit=segment_retry_limit,
                recovery_generations=recovery_generations,
                recovery_limit=exhausted_recovery_limit,
                now=_stage_now(),
                cooldown_seconds=provider_cycle_cooldown_seconds,
            )
        )
        if (
            effective_count >= segment_retry_limit
            and not account_rotation_retry_allowed
            and not exhausted_cooldown_retry
            and not copy_delivery_repair
            and not legacy_identity_migration
        ):
            continue
        key = db.get(KieApiKey, int(failed.key_id))
        if key is None:
            continue
        source_files = db.query(KieFile).filter(
            KieFile.task_id == failed.id,
            KieFile.workspace_id == int(project.workspace_id),
            KieFile.kind.in_(("reference_upload", "reference_video_upload")),
        ).order_by(KieFile.id.asc()).all()
        retry_input, retry_files, reference_repair = _repair_blocked_omni_reference(
            failed,
            dict(failed.input_json or {}),
            source_files,
            project,
        )
        retry_input, retry_files, doubao_face_repair = (
            _repair_doubao_face_reference_failure(
                failed,
                retry_input,
                retry_files,
            )
        )
        if doubao_face_repair:
            reference_repair = {
                **dict(reference_repair or {}),
                **doubao_face_repair,
            }
        if final_intent_repair:
            retry_input, retry_files = _bind_final_intent_identity_anchor(
                db,
                project=project,
                failed_task=failed,
                group=group,
                retry_input=retry_input,
                retry_files=retry_files,
                final_intent_review=final_intent_review,
            )
        retry_input = _sanitize_content_task_copy_delivery(retry_input)
        if normalized_failure_code == PRODUCT_VISUAL_QA_FAIL_CODE:
            # Make the semantic repair visible before reference normalization
            # and prompt compilation.  More importantly, the structured review
            # below is sent back through the multimodal execution Director so a
            # missing/malformed product causes a newly authored choreography,
            # not a repeat of the same compact provider request.
            retry_input["content_factory_product_visual_retry"] = True
        retry_input = (
            _restore_authoritative_segment_direction_from_source_stage(
                db,
                project=project,
                retry_input=retry_input,
            )
        )
        if needs_policy_migration:
            retry_input = (
                _rebuild_retry_prompt_from_segment_execution_contract(
                    retry_input
                )
            )
        retry_input = _restore_inherited_final_intent_repair(
            db,
            project=project,
            failed_task=failed,
            failed_meta=failed_meta,
            retry_input=retry_input,
        )
        final_intent_instruction = re.sub(
            r"\s+",
            " ",
            str(final_intent_review.get("repair_instruction") or "").strip(),
        )
        if final_intent_instruction:
            retry_input["content_factory_segment_execution_repair"] = {
                "policy_version": str(
                    final_intent_review.get("policy_version")
                    or FINAL_INTENT_REVIEW_POLICY_VERSION
                ),
                "repair_instruction": final_intent_instruction,
                "reasons": list(
                    final_intent_review.get("blocking_reasons") or []
                )[:12],
                "source": "final_intent_qa",
            }
        if _uses_only_local_voiceover(retry_input):
            for prompt_key in ("prompt", "content_factory_base_prompt"):
                retry_input[prompt_key] = (
                    _prompt_without_local_voiceover_delivery(
                        retry_input.get(prompt_key)
                    )
                )
            # A historical provider-speech failure is not a reason to spend
            # another generation once the signed plan assigns exact speech to
            # deterministic local voiceover.
            spoken_copy_failure = False
        if spoken_copy_failure:
            exact_copy = " ".join(
                str(item.get("line") or "").strip()
                for item in list(
                    retry_input.get("content_factory_dialogue_lines") or []
                )
                if isinstance(item, dict)
                and str(item.get("line") or "").strip()
                and str(
                    item.get("delivery_method") or "provider_dialogue"
                ).strip().lower() != "local_voiceover"
            )
            retry_input = _apply_exact_spoken_copy_retry_prompt(
                retry_input,
                exact_copy,
                missing_tokens=list(
                    dict(failed_meta.get("spoken_copy_review") or {}).get(
                        "missing_tokens"
                    )
                    or []
                ),
            )
        if copy_delivery_repair:
            retry_input["content_factory_copy_delivery_repair_retry"] = True
            retry_input["content_factory_copy_delivery_repaired"] = True
        voice_repair = dict(
            failed_meta.get("voice_continuity_repair") or {}
        )
        retry_input = _apply_voice_continuity_retry_prompt(
            retry_input,
            voice_repair,
        )
        execution_review = dict(
            failed_meta.get("segment_execution_review") or {}
        )
        if copy_failure_code == "flow_request_rejected":
            execution_review = {
                **execution_review,
                "policy_version": "provider_request_rejection_v1",
                "blocking": True,
                "blocking_reasons": [effective_failure_message[:1200]],
                "repair_instruction": (
                    "The video provider rejected the compiled segment request "
                    "as an invalid request. Re-author this segment from the "
                    "signed requirement contract, reference pixels, exact copy, "
                    "and product facts. Preserve the intended emotional and "
                    "conversion effect, but change only the provider-executable "
                    "visual claim, action, or wording that caused rejection. "
                    "Do not invent claims and do not weaken unrelated hook, "
                    "pacing, camera, continuity, or product requirements."
                ),
            }
        if normalized_failure_code == PRODUCT_VISUAL_QA_FAIL_CODE:
            execution_review = {
                **execution_review,
                **_product_visual_replan_review(
                    failed_meta,
                    diagnostic=effective_failure_message,
                ),
            }
        if final_intent_instruction:
            execution_review = {
                **execution_review,
                "policy_version": str(
                    final_intent_review.get("policy_version")
                    or FINAL_INTENT_REVIEW_POLICY_VERSION
                ),
                "blocking": True,
                "blocking_reasons": list(
                    final_intent_review.get("blocking_reasons") or []
                )[:12],
                "failed_requirement_ids": list(
                    final_intent_review.get("failed_requirement_ids") or []
                )[:64],
                "repair_instruction": final_intent_instruction,
            }
        execution_feasibility_replan: dict[str, Any] | None = None
        # A provider-prompt policy upgrade changes what the multimodal author
        # must preserve, not merely how an old lossy string is compacted.  The
        # previous migration path rebuilt the new transport from the old
        # execution contract, so a segment authored before visual context was
        # required could keep omitting its medium, subject, environment and
        # performance even after deployment. Re-author once under the new
        # policy for any retryable failure. This is still bounded by the
        # policy stamp on the replacement task, and it does not alter signed
        # copy, product facts, duration, or segment allocation.
        needs_ai_provider_beat_migration = bool(
            needs_policy_migration or final_intent_instruction
        )
        if (
            normalized_failure_code
            in {
                SEGMENT_EXECUTION_QA_FAIL_CODE,
                PRODUCT_VISUAL_QA_FAIL_CODE,
                "flow_request_rejected",
            }
            or needs_ai_provider_beat_migration
        ):
            if (
                normalized_failure_code == PRODUCT_VISUAL_QA_FAIL_CODE
                or normalized_failure_code
                == SEGMENT_EXECUTION_QA_FAIL_CODE
                or normalized_failure_code == "flow_request_rejected"
                or exhausted_cooldown_retry
                or needs_ai_provider_beat_migration
            ):
                try:
                    retry_provider = str(
                        retry_input.get("service_provider") or ""
                    ).strip().lower()
                    retry_segment_contract = dict(
                        retry_input.get(
                            "content_factory_segment_execution_contract"
                        )
                        or {}
                    )
                    if not str(
                        retry_segment_contract.get(
                            "project_visual_style_requirement"
                        )
                        or ""
                    ).strip():
                        retry_segment_contract[
                            "project_visual_style_requirement"
                        ] = str(
                            retry_input.get(
                                "content_factory_visual_style_requirement"
                            )
                            or ""
                        )
                    execution_feasibility_replan = (
                        replan_failed_segment_execution_api(
                            db,
                            segment_contract=retry_segment_contract,
                            execution_review=execution_review,
                            dialogue_lines=list(
                                retry_input.get(
                                    "content_factory_dialogue_lines"
                                )
                                or []
                            ),
                            execution_id=(
                                f"project-{int(project.id)}-task-{int(failed.id)}-"
                                f"recovery-{effective_count + 1}"
                            ),
                            requirement_contract=list(
                                retry_input.get(
                                    "content_factory_requirement_contract"
                                )
                                or []
                            ),
                            forbid_overlay_bands=bool(
                                retry_input.get(
                                    "content_factory_forbid_overlay_bands"
                                )
                            ),
                            reference_manifest=list(
                                retry_input.get(
                                    "content_factory_reference_manifest"
                                )
                                or []
                            ),
                            reference_image_paths=[
                                str(item.get("path") or "")
                                for item in list(
                                    retry_input.get(
                                        "reference_file_paths"
                                    )
                                    or []
                                )
                                if isinstance(item, dict)
                                and str(item.get("path") or "").strip()
                            ],
                            provider_key=retry_provider,
                            provider_prompt_language=(
                                "zh-CN"
                                if retry_provider == "doubao"
                                else "en"
                            ),
                            provider_prompt_max_characters=int(
                                _video_model_policy(project).get(
                                    "provider_prompt_max_characters"
                                )
                                or 495
                            ),
                            initial_multimodal_authoring=bool(
                                needs_ai_provider_beat_migration
                                and normalized_failure_code
                                != SEGMENT_EXECUTION_QA_FAIL_CODE
                            ),
                        )
                    )
                    retry_input, retry_files = (
                        _apply_ai_segment_reference_strategy(
                            retry_input,
                            retry_files,
                            execution_feasibility_replan,
                        )
                    )
                    retry_input = _apply_ai_segment_execution_replan(
                        retry_input,
                        execution_feasibility_replan,
                    )
                except (ContentFactoryApiError, ValueError) as exc:
                    set_task_local_meta(
                        failed,
                        content_factory_execution_replan_error=(
                            str(exc)[:500]
                        ),
                        content_factory_execution_replan_failed_at=(
                            datetime.now(timezone.utc)
                            .replace(tzinfo=None)
                            .isoformat()
                        ),
                    )
                    db.add(failed)
                    continue
        # The multimodal author may remove ordinary references when it judges
        # that text can carry their semantic duty.  A final-composite identity
        # anchor is different: it is the accepted pixel evidence that exposed
        # the cross-clip mismatch and must survive reference optimization.
        # Rebind it after the model-authored strategy while leaving action,
        # camera and edit timing exclusively in the prompt contract.
        if final_intent_repair:
            retry_input, retry_files = _bind_final_intent_identity_anchor(
                db,
                project=project,
                failed_task=failed,
                group=group,
                retry_input=retry_input,
                retry_files=retry_files,
                final_intent_review=final_intent_review,
            )
        if reference_repair and int(reference_repair.get("blocked_asset_id") or 0) > 0:
            blocked_asset_ids.add(int(reference_repair["blocked_asset_id"]))
        if _provider_safe_omni_retry_needed(failed):
            retry_input["content_factory_provider_safe_retry"] = True
        if _content_task_effective_failure_code(failed) == (
            PRODUCT_VISUAL_QA_FAIL_CODE
        ):
            retry_input["content_factory_product_visual_retry"] = True
        retry_input, retry_files = _normalize_omni_retry_references(
            retry_input,
            retry_files,
            blocked_asset_ids,
            retry_attempt=effective_count + 1,
            project=project,
        )
        retry_input["prompt"] = _scope_retry_prompt_to_segment_timeline(
            retry_input.get("prompt"),
        )
        if str(retry_input.get("content_factory_base_prompt") or "").strip():
            retry_input["content_factory_base_prompt"] = (
                _scope_retry_prompt_to_segment_timeline(
                    retry_input.get("content_factory_base_prompt"),
                )
            )
        try:
            retry_input = _compact_content_factory_retry_prompt(
                project,
                retry_input,
            )
        except ValueError as exc:
            # Prompt fidelity is a pre-submission safety boundary.  A
            # compaction defect must not create paid provider work, but it
            # also must not escape the waiter transaction and erase the
            # multimodal failure evidence.  Persist the exact local compiler
            # error; the caller will enter the normal bounded quality pause
            # and self-heal can re-author from the complete signed contract.
            set_task_local_meta(
                failed,
                content_factory_retry_prompt_compile_error=(
                    str(exc)[:1000]
                ),
                content_factory_retry_prompt_compile_failed_at=(
                    datetime.now(timezone.utc)
                    .replace(tzinfo=None)
                    .isoformat()
                ),
            )
            db.add(failed)
            continue
        if (
            needs_policy_migration
            and str(retry_input.get("service_provider") or "").lower() == "kyy"
            and str(retry_input.get("content_factory_provider_fallback") or "").startswith("kyy_after_")
        ):
            retry_input["service_provider"] = "auto"
            retry_input.pop("content_factory_provider_fallback", None)
        # The prior worker round already walked every enabled compatible key.
        # Start the next round from API-management priority 1 after cooldown.
        retry_input["service_provider"] = "auto"
        retry_input.pop("content_factory_provider_fallback", None)
        retry_input.pop("content_factory_provider_failover_recovery", None)
        try:
            cycle_key = resolve_video_model_key(
                db,
                model_id=str(retry_input.get("model") or failed.model or ""),
                reference_count=sum(
                    1 for item in retry_files if item.kind == "reference_upload"
                ),
                reference_video_count=sum(
                    1
                    for item in retry_files
                    if item.kind == "reference_video_upload"
                ),
                aspect_ratio=str(retry_input.get("aspect_ratio") or ""),
                reference_mode=str(
                    retry_input.get("video_frame_mode")
                    or retry_input.get("reference_mode")
                    or "reference"
                ),
                duration=int(
                    retry_input.get("seconds")
                    or retry_input.get("duration")
                    or 0
                )
                or None,
                resolution=str(retry_input.get("resolution") or "") or None,
                exclude_key_ids=quota_failed_key_ids,
            )
        except (TypeError, ValueError):
            continue
        retry_task = create_local_video_task(
            db,
            workspace_id=int(project.workspace_id),
            key_id=int(cycle_key.id),
            input_params=retry_input,
            actor_user_id=project.user_id,
            actor_workspace_id=int(project.workspace_id),
        )
        _replace_video_task_reference_files(
            db,
            task=retry_task,
            retry_input=retry_input,
            retry_files=retry_files,
            source_task_id=int(failed.id),
        )
        input_params = dict(retry_task.input_json or {})
        set_task_local_meta(
            retry_task,
            download_name_base=(
                f"{input_params.get('content_factory_final_name_base')}-segment-"
                f"{input_params.get('content_factory_segment_index')}"
            ),
            content_factory_retry=effective_count + 1,
            content_factory_quality_retry=(
                effective_count + 1 if quality_repair else None
            ),
            content_factory_retry_parent_task_id=int(failed.id),
            content_factory_retry_root_task_id=int(
                failed_meta.get("content_factory_retry_root_task_id")
                or failed.id
            ),
            content_factory_retry_mode="new_task_attempt",
            content_factory_project_key=project.project_key,
            content_factory_video_index=input_params.get("content_factory_video_index"),
            content_factory_segment_index=input_params.get("content_factory_segment_index"),
            content_factory_final_name_base=input_params.get("content_factory_final_name_base"),
            content_factory_exhausted_cooldown_retry=exhausted_cooldown_retry,
            content_factory_exhausted_cooldown_retry_generation=(
                SELF_HEAL_POLICY_VERSION if exhausted_cooldown_retry else None
            ),
            attempted_provider_key_ids=[],
            attempted_provider_keys=[],
            provider_quota_failed_key_ids=sorted(quota_failed_key_ids),
            doubao_failed_account_bridge_ids=None,
            provider_retry_counts={},
            active_provider=str(cycle_key.provider_key),
            active_provider_key_id=int(cycle_key.id),
            provider_priority_cycle_attempt=effective_count + 1,
            content_factory_account_rotation_retry=(
                account_rotation_count + 1
                if account_rotation_retry_allowed
                else None
            ),
            content_factory_local_transport_rebuild=(
                local_transport_rebuild or None
            ),
            # This transaction commits before the Celery publish below.  A
            # short durable handoff lease prevents the 20-second waiter from
            # republishing the same reset while the original delivery is
            # being submitted or uploaded.
            submit_enqueued_at=(
                datetime.now(timezone.utc).isoformat()
            ),
        )
        set_task_local_meta(
            failed,
            content_factory_retry_child_task_id=int(retry_task.id),
            content_factory_retry_replaced_at=(
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ),
        )
        db.add(failed)
        old_task_id = int(failed.id)
        new_task_id = int(retry_task.id)
        segment["task_id"] = new_task_id
        segment["retry_source_task_id"] = old_task_id
        segment["retry_attempt"] = effective_count + 1
        # Only the immediately following segment points at this task. Retarget
        # that dormant dependency before the state snapshot is committed so a
        # later release always extracts continuity from the replacement.
        for downstream in list(group.get("segments") or []):
            if int(downstream.get("dependency_task_id") or 0) != old_task_id:
                continue
            downstream["dependency_task_id"] = new_task_id
            downstream_task = task_by_id.get(
                int(downstream.get("task_id") or 0)
            )
            if downstream_task is None:
                scoped_downstream = _scoped_content_video_tasks(
                    db,
                    project,
                    [int(downstream.get("task_id") or 0)],
                )
                downstream_task = (
                    scoped_downstream[0] if scoped_downstream else None
                )
            if downstream_task is None:
                continue
            downstream_input = dict(downstream_task.input_json or {})
            downstream_input["content_factory_dependency_task_id"] = (
                new_task_id
            )
            downstream_task.input_json = downstream_input
            set_task_local_meta(
                downstream_task,
                dependency_task_id=new_task_id,
                dependency_retargeted_from_task_id=old_task_id,
            )
            db.add(downstream_task)
        active_task_ids = [
            task_id for task_id in active_task_ids
            if int(task_id) != old_task_id
        ]
        if new_task_id not in active_task_ids:
            active_task_ids.append(new_task_id)
        replaced_task_ids.add(old_task_id)
        _append_content_segment_retry_attempt(
            db,
            project=project,
            failed_task=failed,
            retry_task=retry_task,
            segment=segment,
            provider_key=str(cycle_key.provider_key),
        )
        segment["retry_count"] = effective_count + 1
        if quality_repair:
            quality_retry_counts[quality_retry_key] = effective_count + 1
        else:
            retry_counts[retry_key] = effective_count + 1
        if account_rotation_retry_allowed:
            account_rotation_retry_counts[retry_key] = (
                account_rotation_count + 1
            )
        retry_history.append({
            "video_segment": retry_key,
            "failed_task_id": int(failed.id),
            "retry_task_id": int(retry_task.id),
            "retry_mode": "new_task_attempt",
            "attempt": effective_count + 1,
            "budget_kind": (
                "quality"
                if quality_repair
                else (
                    "local_transport"
                    if local_transport_rebuild
                    else "transport"
                )
            ),
            "final_intent_incident_repair": bool(final_intent_repair),
            "quality_retry_key": quality_retry_key if quality_repair else None,
            "policy_changed_since_submission": bool(needs_policy_migration),
            "legacy_same_task_identity_migration": legacy_identity_migration,
            "reason": str(
                effective_failure_message
                or _content_task_effective_failure_code(failed)
                or failed.state
            )[:500],
            "reference_repair": reference_repair,
            "voice_continuity_repair": voice_repair or None,
            "segment_execution_repair": (
                execution_review or None
            ),
            "segment_execution_feasibility_replan": (
                execution_feasibility_replan or None
            ),
            "prompt_rewrite_attempt": int(retry_input.get("content_factory_prompt_rewrite_attempt") or 0),
            "prompt_hash": str(retry_input.get("content_factory_prompt_hash") or "")[:16],
            "reference_asset_ids": [
                int(ref.get("asset_id") or 0)
                for ref in list(retry_input.get("reference_file_paths") or [])
            ],
            "exhausted_cooldown_retry": exhausted_cooldown_retry,
            "selected_service_provider": str(
                cycle_key.provider_key
            ),
            "account_rotation_retry": account_rotation_retry_allowed,
            "account_rotation_attempt": (
                account_rotation_count + 1
                if account_rotation_retry_allowed
                else None
            ),
            "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        })
        if exhausted_cooldown_retry:
            prior_generation = recovery_generations.get(retry_key)
            if isinstance(prior_generation, dict):
                is_segment_execution_recovery = bool(
                    normalized_failure_code
                    == SEGMENT_EXECUTION_QA_FAIL_CODE
                )
                reference_policy_matches = bool(
                    not is_segment_execution_recovery
                    or str(
                        prior_generation.get(
                            "segment_execution_reference_policy_version"
                        )
                        or ""
                    ).strip()
                    == SEGMENT_EXECUTION_REFERENCE_REPLAN_POLICY_VERSION
                )
                prior_policy = int(
                    prior_generation.get("policy_version") or 0
                )
                prior_round = (
                    int(
                        prior_generation.get("round")
                        or prior_generation.get("attempt")
                        or 1
                    )
                    if reference_policy_matches
                    and prior_policy in {0, SELF_HEAL_POLICY_VERSION}
                    else 0
                )
            else:
                prior_round = 1 if prior_generation else 0
            recovery_generations[retry_key] = {
                "policy_version": SELF_HEAL_POLICY_VERSION,
                "task_id": int(retry_task.id),
                "provider": "priority_cycle",
                "round": prior_round + 1,
                "round_limit": exhausted_recovery_limit,
                "cooldown_seconds": provider_cycle_cooldown_seconds,
                "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            }
            if normalized_failure_code == SEGMENT_EXECUTION_QA_FAIL_CODE:
                recovery_generations[retry_key][
                    "segment_execution_reference_policy_version"
                ] = SEGMENT_EXECUTION_REFERENCE_REPLAN_POLICY_VERSION
        # Any successful reset of a failed root segment makes its downstream
        # dependency failures provisional again.  This is not limited to the
        # extra post-cooldown generation: otherwise an ordinary first retry
        # leaves later segments terminal and the variant can never drain.
        restored_dependency_ids.update(
            _restore_failed_segment_dependencies_for_retry(
                db,
                group=group,
                root_segment=segment,
                task_by_id=task_by_id,
            )
        )
        retried_tasks.append((retry_task, retry_key))

    if not retried_tasks and not adopted_retry_task_ids and policy_reconciled_task_ids:
        state["ai_video_failed_task_ids"] = [
            int(value)
            for value in list(state.get("ai_video_failed_task_ids") or [])
            if int(value) not in set(policy_reconciled_task_ids)
        ]
        state.pop("ai_video_terminal_failure", None)
        state["ai_video_segment_qa_policy_reconciled_task_ids"] = list(
            dict.fromkeys(
                list(
                    state.get(
                        "ai_video_segment_qa_policy_reconciled_task_ids"
                    )
                    or []
                )
                + policy_reconciled_task_ids
            )
        )[-50:]
        project.state_json = state
        project.status = "generating_video"
        project.current_stage = "WAITING_VIDEO_INPUT"
        project.last_error = (
            "Hermes 已按最新用户意图优先的多模态验收策略重新审核本地视频，"
            "无需重复调用生成 API，正在继续合并。"
        )
        db.add(project)
        db.flush()
        return policy_reconciled_task_ids
    if not retried_tasks and not adopted_retry_task_ids:
        return []
    state["ai_video_task_ids"] = list(dict.fromkeys(active_task_ids))
    state["ai_video_groups"] = groups
    state["ai_video_segment_retry_counts"] = retry_counts
    state["ai_video_segment_quality_retry_counts"] = quality_retry_counts
    state["ai_video_retry_history"] = retry_history
    state["ai_video_exhausted_cooldown_retry_generations"] = recovery_generations
    state["ai_video_account_rotation_retry_counts"] = (
        account_rotation_retry_counts
    )
    state["ai_video_cooldown_retry_restored_dependency_task_ids"] = sorted(
        restored_dependency_ids
    )
    state["ai_video_blocked_reference_asset_ids"] = sorted(blocked_asset_ids)
    state["ai_video_last_retry_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    highest_retry_attempt = max(
        (
            int(
                dict(get_task_local_meta(task) or {}).get(
                    "content_factory_quality_retry"
                )
                or dict(get_task_local_meta(task) or {}).get(
                    "content_factory_retry"
                )
                or 0
            )
            for task, _retry_key in retried_tasks
        ),
        default=int(state.get("ai_video_highest_retry_attempt") or 0),
    )
    state["ai_video_highest_retry_attempt"] = highest_retry_attempt
    state["ai_video_retry_limit"] = retry_limit
    state["ai_video_failed_task_ids"] = [
        int(task.id)
        for task in failed_tasks
        if int(task.id) not in replaced_task_ids
        and int(task.id) not in restored_dependency_ids
    ]
    state.pop("ai_video_terminal_failure", None)
    # The multimodal repair compiler above can legitimately take longer than
    # another variant's provider submission. Refresh and lock the project only
    # at this last, short commit boundary, then merge this retry's affected
    # variants into the newest state instead of replacing the full JSON cache.
    if isinstance(project, HermesContentFactoryProject):
        project = _lock_project_for_video_state_merge(db, project)
    state = _merge_video_retry_state(
        dict(project.state_json or {}),
        state,
        retry_groups=groups,
        affected_video_indices=affected_video_indices,
        replaced_task_ids=replaced_task_ids,
        restored_dependency_ids=restored_dependency_ids,
    )
    project.state_json = state
    project.status = "generating_video"
    if retried_tasks and any(
        bool(
            dict(get_task_local_meta(task) or {}).get(
                "content_factory_local_transport_rebuild"
            )
        )
        for task, _retry_key in retried_tasks
    ):
        project.last_error = (
            f"Hermes 在供应商调用前发现并重建了 {len(retried_tasks)} 个"
            "本地视频提示词契约；未将内部错误计入供应商故障，正在继续执行。"
        )
    elif retried_tasks and recovery_generations and any(
        bool(item.get("exhausted_cooldown_retry"))
        for item in retry_history[-len(retried_tasks):]
        if isinstance(item, dict)
    ):
        project.last_error = (
            f"Hermes 已在全部已启用视频供应商均失败后等待 "
            f"{provider_cycle_cooldown_seconds} 秒，正按 API 管理优先级开始"
            f"新一轮有界恢复，并已恢复 "
            f"{len(restored_dependency_ids)} 个后续依赖片段。"
        )
    else:
        project.last_error = (
            f"Hermes 已在冷却后按供应商优先级重启或接管 "
            f"{len(retried_tasks) + len(adopted_retry_task_ids)} 个失败片段；"
            f"当前最高累计第 {highest_retry_attempt}/{retry_limit} 次，继续监控中。"
        )
    db.commit()
    for retry_task, _retry_key in retried_tasks:
        submit_and_poll_ai_video_task.apply_async(
            kwargs={
                "workspace_id": int(project.workspace_id),
                "local_task_id": int(retry_task.id),
                "interval_seconds": int(settings.BANDIANWA_POLL_INTERVAL_SECONDS),
                "timeout_seconds": int(settings.BANDIANWA_POLL_TIMEOUT_SECONDS),
            },
            queue=production_video_queue(retry_task),
        )
    return list(dict.fromkeys([
        *adopted_retry_task_ids,
        *[int(task.id) for task, _retry_key in retried_tasks],
    ]))


def _queue_next_variant_after_video_submit(
    db,
    project: HermesContentFactoryProject,
    *,
    submitted_variant_index: int,
) -> HermesContentFactoryStage | None:
    if not _sequential_variants_enabled(project):
        return None
    config = dict(project.config_json or {})
    if not bool(config.get("auto_run", True)) or bool(config.get("manual_paused", False)):
        return None
    pipeline = _variant_pipeline(project)
    target = int(pipeline.get("target_count") or _target_video_count(project))
    submitted = {
        int(value) for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit()
    }
    if submitted_variant_index not in submitted:
        submitted.add(int(submitted_variant_index))
    parallelism = _configured_api_video_variant_parallelism(project)
    # Browser work remains one project-owned lane.  Once this variant's video
    # API tasks are durably submitted, the project may start at most one next
    # browser turn, provided the number of provider variants in flight remains
    # below the configured cap.  This preserves reference/task isolation while
    # allowing provider polling, download and composition to overlap with the
    # next independent creative turn.
    pipeline["submitted_indices"] = sorted(submitted)
    pipeline["active_index"] = int(submitted_variant_index)
    pipeline["mode"] = (
        "bounded_api_parallel_v1" if parallelism > 1
        else "serial_one_complete_video_at_a_time"
    )
    pipeline["max_api_video_variants_in_flight"] = parallelism
    pipeline["last_submitted_variant_index"] = int(submitted_variant_index)
    pipeline["awaiting_completed_variant_index"] = int(submitted_variant_index)
    pipeline["awaiting_completion_since"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    _set_variant_pipeline(project, pipeline)
    project.current_stage = "WAITING_VIDEO_INPUT"
    project.status = "generating_video"
    project.last_error = (
        f"第 {submitted_variant_index}/{target} 条视频已提交；"
        f"API 视频流水线最多并行 {parallelism} 条，浏览器创意阶段仍保持单线隔离。"
    )
    hibernate_project_browser_slot_for_api_video(db, project=project)
    db.add(project)
    resumed_variant_stage = None
    # This call is made immediately after the provider task group is committed,
    # but callers and older rows may not yet expose that group through the
    # state snapshot used by the generic stale-ledger detector. The variant
    # handed to this function is authoritative fresh work for this scheduling
    # decision; count it even during that narrow state-publication window.
    current_inflight = _inflight_api_video_variant_indices(project) | {
        int(submitted_variant_index)
    }
    if len(current_inflight) < parallelism:
        resumed_variant_stage = _queue_next_unsubmitted_serial_variant_if_needed(
            db,
            project,
            reason=(
                "bounded API parallel pipeline started the next isolated browser variant "
                f"after variant {submitted_variant_index} submitted provider tasks"
            ),
        )
    db.commit()
    return resumed_variant_stage


def _canonical_content_digest(value: Any) -> str:
    return hashlib.sha256(
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()


_CONTENT_EXECUTION_RUNTIME_CONFIG_KEYS = {
    "auto_run",
    "auto_start_on_upload",
    "content_execution_key",
    "manual_paused",
    "manual_paused_at",
    "max_api_video_variants_in_flight",
    "user_confirmed_marketing",
    "variant_rollout_gate",
}


def _content_execution_contract_digest(
    project: HermesContentFactoryProject,
) -> str:
    """Hash immutable creative/media truth, excluding runtime controls."""
    config = {
        str(key): value
        for key, value in dict(project.config_json or {}).items()
        if str(key) not in _CONTENT_EXECUTION_RUNTIME_CONFIG_KEYS
    }
    return _canonical_content_digest({
        "project": {
            "product_name": str(getattr(project, "product_name", "") or ""),
            "market": str(getattr(project, "market", "") or ""),
            "product_brief": str(
                getattr(project, "product_brief", "") or ""
            ),
        },
        "config": config,
    })


def _file_sha256(path: Path, *, chunk_bytes: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(max(64 * 1024, int(chunk_bytes))):
            digest.update(chunk)
    return digest.hexdigest()


def _ensure_content_execution_ledger(
    db: Session,
    project: HermesContentFactoryProject,
) -> HermesContentExecution:
    config = dict(project.config_json or {})
    execution_key = str(
        config.get("content_execution_key")
        or f"{project.project_key}:production-v1"
    ).strip()
    if not execution_key:
        raise ValueError("CONTENT_EXECUTION_KEY_EMPTY")
    row = db.query(HermesContentExecution).filter(
        HermesContentExecution.project_id == int(project.id),
        HermesContentExecution.execution_key == execution_key,
    ).one_or_none()
    config_sha256 = _content_execution_contract_digest(project)
    if row is None:
        row = HermesContentExecution(
            project_id=int(project.id),
            workspace_id=int(project.workspace_id),
            user_id=project.user_id,
            execution_key=execution_key,
            status="running",
            target_count=_target_video_count(project),
            config_sha256=config_sha256,
            meta_json={"schema_version": "content-execution-v1"},
        )
        db.add(row)
        db.flush()
        superseded_at = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        prior_running = db.query(HermesContentExecution).filter(
            HermesContentExecution.project_id == int(project.id),
            HermesContentExecution.id != int(row.id),
            HermesContentExecution.status == "running",
        ).all()
        for prior in prior_running:
            prior.status = "superseded"
            prior.meta_json = {
                **dict(prior.meta_json or {}),
                "superseded_at": superseded_at,
                "superseded_by_execution_id": int(row.id),
                "superseded_by_execution_key": execution_key,
            }
            db.add(prior)
        _backfill_local_content_deliverables(db, project=project, execution=row)
    else:
        if str(row.config_sha256 or "") != config_sha256:
            has_attempts = db.query(HermesContentVariantRun.id).filter(
                HermesContentVariantRun.execution_id == int(row.id),
            ).first()
            if has_attempts is not None:
                raise ValueError(
                    "CONTENT_EXECUTION_CONTRACT_DRIFT: immutable production "
                    "settings changed after media execution started"
                )
            row.config_sha256 = config_sha256
        if str(row.status or "") != "complete":
            row.status = "running"
        row.target_count = _target_video_count(project)
        db.add(row)
    return row


def _backfill_local_content_deliverables(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    execution: HermesContentExecution,
) -> None:
    """Import verified pre-ledger local outputs without resubmitting media."""
    completed_videos = _completed_video_assets_by_index(db, project)
    guides = _authoritative_editor_guidance_assets_by_index(
        db,
        project,
        completed_video_indices=set(completed_videos),
    )
    imported: list[int] = []
    target = int(execution.target_count)
    for ordinal in sorted(set(completed_videos).intersection(guides)):
        if ordinal < 1 or ordinal > target:
            continue
        assets = {
            "video": completed_videos[ordinal],
            "edit_guide": guides[ordinal],
        }
        source_identity = {
            kind: {
                "asset_id": int(asset.id or 0),
                "file_path": str(asset.file_path or ""),
                "size_bytes": int(asset.size_bytes or 0),
            }
            for kind, asset in assets.items()
        }
        input_sha256 = _canonical_content_digest(source_identity)
        variant = db.query(HermesContentVariantRun).filter(
            HermesContentVariantRun.execution_id == int(execution.id),
            HermesContentVariantRun.variant_index == int(ordinal),
        ).order_by(HermesContentVariantRun.attempt.desc()).first()
        if variant is None:
            variant = HermesContentVariantRun(
                execution_id=int(execution.id),
                project_id=int(project.id),
                workspace_id=int(project.workspace_id),
                user_id=project.user_id,
                variant_index=int(ordinal),
                deliverable_ordinal=int(ordinal),
                attempt=1,
                state="composed",
                media_manifest_sha256=input_sha256,
                input_sha256=input_sha256,
                meta_json={
                    "schema_version": "content-variant-run-v1",
                    "imported_from_preledger_local_assets": True,
                },
                completed_at=_stage_now(),
            )
            db.add(variant)
            db.flush()
        output_hashes: dict[str, str] = {}
        for kind, asset in assets.items():
            path = Path(str(asset.file_path or ""))
            try:
                path_stat = path.stat()
            except OSError:
                continue
            if not path.is_file() or path_stat.st_size <= 0:
                continue
            deliverable = db.query(HermesContentDeliverable).filter(
                HermesContentDeliverable.execution_id == int(execution.id),
                HermesContentDeliverable.deliverable_ordinal == int(ordinal),
                HermesContentDeliverable.kind == kind,
            ).one_or_none()
            if deliverable is None:
                file_sha256 = _file_sha256(path)
                deliverable = HermesContentDeliverable(
                    execution_id=int(execution.id),
                    variant_run_id=int(variant.id),
                    project_id=int(project.id),
                    workspace_id=int(project.workspace_id),
                    user_id=project.user_id,
                    deliverable_ordinal=int(ordinal),
                    kind=kind,
                    status="ready",
                    asset_id=int(asset.id),
                    file_path=str(path),
                    file_sha256=file_sha256,
                    meta_json={
                        "schema_version": "content-deliverable-v1",
                        "imported_from_preledger_local_asset": True,
                        "file_size_bytes": int(path_stat.st_size),
                        "file_mtime_ns": int(path_stat.st_mtime_ns),
                    },
                )
                db.add(deliverable)
                db.flush()
            output_hashes[kind] = str(deliverable.file_sha256)
        if set(output_hashes) == {"video", "edit_guide"}:
            variant.state = "composed"
            variant.output_sha256 = _canonical_content_digest(output_hashes)
            variant.completed_at = variant.completed_at or _stage_now()
            db.add(variant)
            imported.append(int(ordinal))
    execution_meta = dict(execution.meta_json or {})
    execution_meta.update({
        "legacy_local_backfill_version": "v1",
        "legacy_local_backfilled_ordinals": imported,
    })
    execution.meta_json = execution_meta
    if len(set(imported)) >= int(execution.target_count):
        execution.status = "complete"
        execution.completed_at = execution.completed_at or _stage_now()
    db.add(execution)
    db.flush()


def _dual_write_media_execution_ledger(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    groups: list[dict[str, Any]],
    tasks: list[KieTask],
    media_manifest_sha256: str,
    provider_key: str,
    provider_model: str,
) -> list[HermesContentVariantRun]:
    execution = _ensure_content_execution_ledger(db, project)
    task_by_id = {int(task.id): task for task in tasks if int(task.id or 0) > 0}
    variant_rows: list[HermesContentVariantRun] = []
    for group in groups:
        variant_index = int(group.get("video_index") or 0)
        if variant_index <= 0:
            raise ValueError("CONTENT_EXECUTION_LEDGER_VARIANT_INDEX_INVALID")
        existing = db.query(HermesContentVariantRun).filter(
            HermesContentVariantRun.execution_id == int(execution.id),
            HermesContentVariantRun.variant_index == variant_index,
            HermesContentVariantRun.media_manifest_sha256 == media_manifest_sha256,
        ).order_by(HermesContentVariantRun.attempt.desc()).first()
        if existing is None:
            latest_attempt = db.query(func.max(HermesContentVariantRun.attempt)).filter(
                HermesContentVariantRun.execution_id == int(execution.id),
                HermesContentVariantRun.variant_index == variant_index,
            ).scalar()
            existing = HermesContentVariantRun(
                execution_id=int(execution.id),
                project_id=int(project.id),
                workspace_id=int(project.workspace_id),
                user_id=project.user_id,
                variant_index=variant_index,
                deliverable_ordinal=variant_index,
                attempt=int(latest_attempt or 0) + 1,
                state="segments_submitted",
                media_manifest_sha256=media_manifest_sha256,
                input_sha256=media_manifest_sha256,
                meta_json={
                    "schema_version": "content-variant-run-v1",
                    "aspect_ratio": group.get("aspect_ratio"),
                    "duration": group.get("duration"),
                    "source_stage_id": int(group.get("source_stage_id") or 0),
                },
            )
            db.add(existing)
            db.flush()
        else:
            existing.state = "segments_submitted"
            existing.error_class = None
            existing.error_message = None
            db.add(existing)
        for segment in list(group.get("segments") or []):
            task_id = int(dict(segment).get("task_id") or 0)
            task = task_by_id.get(task_id)
            if task is None:
                raise ValueError(
                    "CONTENT_EXECUTION_LEDGER_TASK_MISSING: "
                    f"variant={variant_index} task_id={task_id}"
                )
            segment_index = int(dict(segment).get("segment_index") or 0)
            input_sha256 = _canonical_content_digest(dict(task.input_json or {}))
            segment_row = db.query(HermesContentSegmentRun).filter(
                HermesContentSegmentRun.variant_run_id == int(existing.id),
                HermesContentSegmentRun.segment_index == segment_index,
                HermesContentSegmentRun.attempt == 1,
            ).one_or_none()
            if segment_row is None:
                task_key = db.get(KieApiKey, int(task.key_id))
                segment_row = HermesContentSegmentRun(
                    variant_run_id=int(existing.id),
                    project_id=int(project.id),
                    workspace_id=int(project.workspace_id),
                    user_id=project.user_id,
                    segment_index=segment_index,
                    attempt=1,
                    state=str(task.state or "queued_local"),
                    provider_key=str(
                        task_key.provider_key
                        if task_key is not None
                        else provider_key
                    ),
                    provider_model=str(provider_model),
                    provider_task_row_id=int(task.id),
                    input_sha256=input_sha256,
                    meta_json={
                        "schema_version": "content-segment-run-v1",
                        "dependency_task_id": dict(segment).get("dependency_task_id"),
                    },
                )
                db.add(segment_row)
            else:
                segment_row.state = str(task.state or "queued_local")
                segment_row.provider_task_row_id = int(task.id)
                segment_row.input_sha256 = input_sha256
                db.add(segment_row)
        variant_rows.append(existing)
    db.flush()
    return variant_rows


def _sync_content_segment_execution_ledger(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> None:
    task_ids = [int(task.id) for task in tasks if int(task.id or 0) > 0]
    if not task_ids:
        return
    task_by_id = {int(task.id): task for task in tasks}
    rows = db.query(HermesContentSegmentRun).filter(
        HermesContentSegmentRun.project_id == int(project.id),
        HermesContentSegmentRun.provider_task_row_id.in_(tuple(task_ids)),
    ).all()
    files_by_task: dict[int, list[KieFile]] = {}
    for file in db.query(KieFile).filter(
        KieFile.task_id.in_(tuple(task_ids)),
        KieFile.workspace_id == int(project.workspace_id),
        KieFile.kind.in_(("result", "result_watermark")),
    ).all():
        files_by_task.setdefault(int(file.task_id or 0), []).append(file)
    now = _stage_now()
    variant_ids: set[int] = set()
    for row in rows:
        task_id = int(row.provider_task_row_id or 0)
        task = task_by_id.get(task_id)
        if task is None:
            continue
        variant_ids.add(int(row.variant_run_id))
        state = str(task.state or "").strip().lower()
        local_path = None
        for file in files_by_task.get(task_id, []):
            candidate = get_local_path(file)
            if candidate is not None:
                local_path = candidate
                break
        if local_path is not None:
            file_stat = local_path.stat()
            row_meta = dict(row.meta_json or {})
            unchanged_verified_file = (
                str(row.state or "") == "downloaded"
                and str(row.local_file_path or "") == str(local_path)
                and bool(str(row.output_sha256 or "").strip())
                and int(row_meta.get("output_size_bytes") or -1)
                == int(file_stat.st_size)
                and int(row_meta.get("output_mtime_ns") or -1)
                == int(file_stat.st_mtime_ns)
            )
            output_sha256 = (
                str(row.output_sha256)
                if unchanged_verified_file
                else _file_sha256(local_path)
            )
            row.state = "downloaded"
            row.local_file_path = str(local_path)
            row.output_sha256 = output_sha256
            row.meta_json = {
                **row_meta,
                "output_size_bytes": int(file_stat.st_size),
                "output_mtime_ns": int(file_stat.st_mtime_ns),
            }
            row.completed_at = row.completed_at or now
            row.error_class = None
            row.error_message = None
        elif _is_failed_video_task(task):
            row.state = "failed"
            row.error_class = str(task.fail_code or "provider_failure")[:96]
            row.error_message = str(task.fail_msg or task.state or "")[:4000]
            row.completed_at = row.completed_at or now
        else:
            row.state = state or "pending"
            row.error_class = None
            row.error_message = None
            db.add(row)
            continue
        db.add(row)
    for variant_id in variant_ids:
        variant = db.get(HermesContentVariantRun, variant_id)
        if variant is None or str(variant.state or "") == "composed":
            continue
        segment_rows = db.query(HermesContentSegmentRun).filter(
            HermesContentSegmentRun.variant_run_id == variant_id,
        ).all()
        # A quality repair appends a new immutable attempt. Historical failed
        # attempts remain auditable but must not keep the variant failed once
        # the active (highest) attempt for that segment is running/downloaded.
        latest_by_segment: dict[int, HermesContentSegmentRun] = {}
        for item in segment_rows:
            segment_index = int(item.segment_index)
            current = latest_by_segment.get(segment_index)
            if current is None or int(item.attempt) > int(current.attempt):
                latest_by_segment[segment_index] = item
        active_rows = list(latest_by_segment.values())
        states = {str(item.state or "") for item in active_rows}
        if active_rows and states == {"downloaded"}:
            variant.state = "segments_downloaded"
        elif "failed" in states:
            variant.state = "segment_failed"
        else:
            variant.state = "segments_running"
        db.add(variant)
    db.flush()


def _upsert_content_deliverable_ledger(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    group: dict[str, Any],
    video_asset: HermesContentFactoryAsset,
    guidance_asset: HermesContentFactoryAsset,
) -> None:
    execution = _ensure_content_execution_ledger(db, project)
    variant_index = int(group.get("video_index") or 0)
    manifest_sha256 = str(group.get("media_manifest_sha256") or "")
    variant = db.query(HermesContentVariantRun).filter(
        HermesContentVariantRun.execution_id == int(execution.id),
        HermesContentVariantRun.variant_index == variant_index,
        HermesContentVariantRun.media_manifest_sha256 == manifest_sha256,
    ).order_by(HermesContentVariantRun.attempt.desc()).first()
    if variant is None:
        raise ValueError(
            "CONTENT_EXECUTION_LEDGER_VARIANT_MISSING: "
            f"variant={variant_index} manifest={manifest_sha256}"
        )
    deliverable_hashes: dict[str, str] = {}
    for kind, asset in (("video", video_asset), ("edit_guide", guidance_asset)):
        path = Path(str(asset.file_path or ""))
        if not path.is_file() or path.stat().st_size <= 0:
            raise ValueError(
                "CONTENT_EXECUTION_LEDGER_DELIVERABLE_FILE_MISSING: "
                f"kind={kind} path={path}"
            )
        row = db.query(HermesContentDeliverable).filter(
            HermesContentDeliverable.execution_id == int(execution.id),
            HermesContentDeliverable.deliverable_ordinal == variant_index,
            HermesContentDeliverable.kind == kind,
        ).one_or_none()
        path_stat = path.stat()
        row_meta = dict(row.meta_json or {}) if row is not None else {}
        unchanged_verified_file = bool(
            row is not None
            and str(row.status or "") == "ready"
            and str(row.file_path or "") == str(path)
            and str(row.file_sha256 or "").strip()
            and int(row_meta.get("file_size_bytes") or -1)
            == int(path_stat.st_size)
            and int(row_meta.get("file_mtime_ns") or -1)
            == int(path_stat.st_mtime_ns)
        )
        file_sha256 = (
            str(row.file_sha256)
            if unchanged_verified_file
            else _file_sha256(path)
        )
        deliverable_hashes[kind] = file_sha256
        file_meta = {
            **row_meta,
            "schema_version": "content-deliverable-v1",
            "file_size_bytes": int(path_stat.st_size),
            "file_mtime_ns": int(path_stat.st_mtime_ns),
        }
        if row is None:
            row = HermesContentDeliverable(
                execution_id=int(execution.id),
                variant_run_id=int(variant.id),
                project_id=int(project.id),
                workspace_id=int(project.workspace_id),
                user_id=project.user_id,
                deliverable_ordinal=variant_index,
                kind=kind,
                status="ready",
                asset_id=int(asset.id),
                file_path=str(path),
                file_sha256=file_sha256,
                meta_json=file_meta,
            )
            db.add(row)
            db.flush()
        else:
            row.variant_run_id = int(variant.id)
            row.status = "ready"
            row.asset_id = int(asset.id)
            row.file_path = str(path)
            row.file_sha256 = file_sha256
            row.meta_json = file_meta
            db.add(row)
    variant.state = "composed"
    variant.output_sha256 = _canonical_content_digest(deliverable_hashes)
    variant.completed_at = variant.completed_at or _stage_now()
    variant.error_class = None
    variant.error_message = None
    db.add(variant)
    ready_video_count = db.query(func.count(HermesContentDeliverable.id)).filter(
        HermesContentDeliverable.execution_id == int(execution.id),
        HermesContentDeliverable.kind == "video",
        HermesContentDeliverable.status == "ready",
    ).scalar()
    ready_guide_count = db.query(func.count(HermesContentDeliverable.id)).filter(
        HermesContentDeliverable.execution_id == int(execution.id),
        HermesContentDeliverable.kind == "edit_guide",
        HermesContentDeliverable.status == "ready",
    ).scalar()
    if (
        int(ready_video_count or 0) >= int(execution.target_count)
        and int(ready_guide_count or 0) >= int(execution.target_count)
    ):
        execution.status = "complete"
        execution.completed_at = execution.completed_at or _stage_now()
    db.add(execution)
    db.flush()


def _guard_existing_media_manifest(
    existing_group: dict[str, Any] | None,
    existing_tasks: list[Any],
    *,
    media_manifest_sha256: str,
    variant_index: int,
) -> list[int] | None:
    """Keep a variant's paid media boundary immutable and idempotent."""
    if existing_group is None:
        return None
    existing_ids = [
        int(segment.get("task_id") or 0)
        for segment in list(existing_group.get("segments") or [])
        if int(segment.get("task_id") or 0) > 0
    ]
    task_ids = {
        int(getattr(task, "id", 0) or 0)
        for task in existing_tasks
        if int(getattr(task, "id", 0) or 0) > 0
    }
    if (
        str(existing_group.get("media_manifest_sha256") or "")
        == media_manifest_sha256
        and existing_ids
    ):
        missing_ids = sorted(set(existing_ids) - task_ids)
        if missing_ids:
            raise ValueError(
                "CONTENT_MEDIA_MANIFEST_TASK_LEDGER_INCOMPLETE: variant "
                f"{variant_index} references missing tasks {missing_ids}"
            )
        return existing_ids
    paid_or_terminal = [
        task
        for task in existing_tasks
        if str(getattr(task, "state", "") or "").lower()
        not in {"queued_local", "waiting_dependency"}
    ]
    if paid_or_terminal:
        states = sorted({
            str(getattr(task, "state", "") or "").lower()
            for task in paid_or_terminal
        })
        raise ValueError(
            "CONTENT_MEDIA_MANIFEST_FROZEN: variant "
            f"{variant_index} already has provider-visible tasks "
            f"{existing_ids} in states {states}; an automatic policy "
            "change cannot replace paid media work"
        )
    return None


def _media_group_source_is_superseded(
    db,
    project: HermesContentFactoryProject,
    group: dict[str, Any],
) -> bool:
    """Return true only when a stage-bound media group lost its authority.

    Legacy groups without ``source_stage_id`` remain frozen by the old paid
    media guard. This avoids silently replacing historical provider work.
    """
    source_stage_id = dict(group or {}).get("source_stage_id")
    if not str(source_stage_id or "").strip().isdigit():
        return False
    source_stage_id_int = int(source_stage_id)
    stage = db.get(HermesContentFactoryStage, source_stage_id_int)
    directly_superseded = bool(
        stage is None
        or int(stage.project_id) != int(project.id)
        or str(stage.stage or "") != "VIDEO_PROMPTS"
        or str(stage.status or "").lower() != "success"
    )
    if directly_superseded:
        return True
    # Historical Director replans were recorded on the replacement Director
    # input but did not retire their source VIDEO_PROMPTS row.  Treat that
    # immutable, project-owned lineage as authority too.  Otherwise a late
    # waiter can submit another paid retry from the old prompt stage and the
    # replacement VIDEO_PROMPTS stage then deadlocks on its own frozen media
    # manifest.
    newer_directors = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == int(project.id),
            HermesContentFactoryStage.stage == "DIRECTOR",
            HermesContentFactoryStage.id > source_stage_id_int,
            HermesContentFactoryStage.status.in_((
                "queued",
                "running",
                "success",
            )),
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .limit(20)
        .all()
    )
    for row in newer_directors:
        row_input = dict(row.input_json or {})
        retired_source_ids = {
            int(value)
            for value in list(
                row_input.get(
                    "director_replan_superseded_source_stage_ids"
                )
                or []
            )
            if str(value or "").strip().isdigit()
        }
        direct_source_id = row_input.get(
            "director_replan_source_stage_id"
        )
        if str(direct_source_id or "").strip().isdigit():
            retired_source_ids.add(int(direct_source_id))

        # Compatibility for a Director replan created before the complete
        # source list was persisted.  The multimodal failure report names the
        # exact provider tasks it rejected; their immutable task inputs name
        # the VIDEO_PROMPTS stage that actually authorized the paid media.
        # A later empty/frozen prompt generation is not a substitute for that
        # real ancestry.
        replan_report = dict(
            row_input.get("final_intent_replan_report") or {}
        )
        for raw_task_id in list(
            replan_report.get("affected_task_ids") or []
        )[:64]:
            if not str(raw_task_id or "").strip().isdigit():
                continue
            affected_task = db.get(KieTask, int(raw_task_id))
            if affected_task is None or int(
                affected_task.workspace_id
            ) != int(project.workspace_id):
                continue
            task_input = dict(affected_task.input_json or {})
            if int(task_input.get("content_factory_project_id") or 0) != int(
                project.id
            ):
                continue
            task_source_id = task_input.get(
                "content_factory_source_stage_id"
            )
            if str(task_source_id or "").strip().isdigit():
                retired_source_ids.add(int(task_source_id))
        if source_stage_id_int in retired_source_ids:
            return True
    return False


def _superseded_media_group_task_ids(
    db,
    project: HermesContentFactoryProject,
    state: dict[str, Any],
) -> set[int]:
    """Return task ids whose immutable prompt-stage authority was retired."""
    task_ids: set[int] = set()
    for raw_group in list(state.get("ai_video_groups") or []):
        if not isinstance(raw_group, dict):
            continue
        group = dict(raw_group)
        if not _media_group_source_is_superseded(db, project, group):
            continue
        task_ids.update(
            int(dict(segment).get("task_id") or 0)
            for segment in list(group.get("segments") or [])
            if int(dict(segment).get("task_id") or 0) > 0
        )
    return task_ids


def _recover_legacy_media_group_source_stage(
    project: HermesContentFactoryProject,
    group: dict[str, Any],
    existing_tasks: list[Any],
) -> dict[str, Any]:
    """Recover one omitted group source stage from its immutable task ledger.

    Early frozen-manifest groups stamped ``content_factory_source_stage_id``
    on every paid task but omitted it from the project-level group. After an
    operator restart superseded that VIDEO_PROMPTS stage, the group therefore
    looked permanently authoritative and the manifest guard retried forever.
    Recover only when every referenced task is present, tenant/project scoped,
    carries the same manifest, and agrees on one positive source stage id.
    """
    recovered = dict(group or {})
    if str(recovered.get("source_stage_id") or "").strip().isdigit():
        return recovered
    expected_ids = {
        int(dict(segment).get("task_id") or 0)
        for segment in list(recovered.get("segments") or [])
        if int(dict(segment).get("task_id") or 0) > 0
    }
    tasks_by_id = {
        int(getattr(task, "id", 0) or 0): task
        for task in existing_tasks
        if int(getattr(task, "id", 0) or 0) > 0
    }
    if not expected_ids or set(tasks_by_id) != expected_ids:
        return recovered
    expected_manifest = str(
        recovered.get("media_manifest_sha256") or ""
    ).strip()
    source_stage_ids: set[int] = set()
    for task in tasks_by_id.values():
        values = dict(getattr(task, "input_json", None) or {})
        if (
            int(getattr(task, "workspace_id", 0) or 0)
            != int(project.workspace_id)
            or int(values.get("content_factory_project_id") or 0)
            != int(project.id)
            or (
                project.user_id is not None
                and int(getattr(task, "created_by_user_id", 0) or 0)
                != int(project.user_id)
            )
            or (
                expected_manifest
                and str(
                    values.get("content_factory_media_manifest_sha256")
                    or ""
                ).strip()
                != expected_manifest
            )
        ):
            return recovered
        try:
            source_stage_id = int(
                values.get("content_factory_source_stage_id") or 0
            )
        except (TypeError, ValueError):
            return recovered
        if source_stage_id <= 0:
            return recovered
        source_stage_ids.add(source_stage_id)
    if len(source_stage_ids) != 1:
        return recovered
    recovered["source_stage_id"] = source_stage_ids.pop()
    recovered["source_stage_recovered_from_task_ledger"] = True
    return recovered


def _queue_ai_video_tasks(
    db,
    project: HermesContentFactoryProject,
    envelope: dict[str, Any],
    *,
    variant_index: int | None = None,
    advance_pipeline: bool = True,
    source_stage_id: int | None = None,
) -> list[int]:
    """Create an isolated provider task group for one content variant.

    ``variant_index`` is normally the active browser/creative variant. It is
    explicit for repair tooling because the bounded parallel pipeline may
    already be preparing variant N+1 while variant N's still-unsubmitted local
    tasks need a prompt-policy rebuild. In that repair mode callers also set
    ``advance_pipeline=False`` so replacing N cannot move the live creative
    lane backwards.
    """
    transformation_contract = _project_transformation_contract(project)
    if str(
        transformation_contract.get("execution_strategy") or ""
    ).strip().lower() == "local_edit":
        raise ValueError(
            "CONTENT_LOCAL_EDIT_ROUTE_REQUIRED: the Producer-authorized "
            "source contract requires a bounded local edit; full provider "
            "generation is not authorized"
        )
    active_variant = max(1, int(variant_index or _active_variant_index(project)))
    if not source_stage_id or int(source_stage_id) <= 0:
        raise ValueError("CONTENT_MEDIA_SOURCE_STAGE_REQUIRED")
    source_stage = db.get(HermesContentFactoryStage, int(source_stage_id))
    source_status = str(getattr(source_stage, "status", "") or "").lower()
    latest_source_stage = _latest_stage(db, project, "VIDEO_PROMPTS")
    source_is_current_compiler = bool(
        source_stage is not None
        and source_status == "running"
        and str(project.current_stage or "").upper() == "VIDEO_PROMPTS"
        and latest_source_stage is not None
        and int(latest_source_stage.id) == int(source_stage.id)
    )
    if (
        source_stage is None
        or int(source_stage.project_id) != int(project.id)
        or str(source_stage.stage or "") != "VIDEO_PROMPTS"
        or (
            source_status != "success"
            and not source_is_current_compiler
        )
    ):
        raise ValueError("CONTENT_MEDIA_SOURCE_STAGE_NOT_AUTHORITATIVE")
    if not _variant_rollout_authorized(project, active_variant):
        raise ValueError(
            "CONTENT_ROLLOUT_GATE_VARIANT_NOT_AUTHORIZED: "
            f"variant {active_variant} is outside the current project release manifest"
        )
    director_media_authorization = _assert_director_media_authorization(
        db,
        project,
        variant_index=active_variant,
    )
    video_plan = _normalize_video_plan(
        project,
        envelope,
        variant_index=active_variant,
    )
    generation_mode = _configured_video_generation_mode(project)
    text_to_video = generation_mode == "text_to_video"
    refs = (
        []
        if text_to_video
        else _copy_video_refs(
            project,
            _reference_images_for_project(
                db,
                project,
                variant_index=active_variant,
            ),
        )
    )
    blocked_asset_ids = _blocked_reference_asset_ids(dict(project.state_json or {}))
    blocked_reference_indices = _exclude_blocked_reference_indices_from_video_plan(
        video_plan,
        refs,
        blocked_asset_ids,
    )
    refs = [ref for ref in refs if int(ref.get("asset_id") or 0) not in blocked_asset_ids]
    generated_reference_indices = {
        int(ref.get("index") or 0) for ref in refs if not bool(ref.get("is_product_anchor"))
    }
    for planned_video in video_plan:
        for planned_segment in list(planned_video.get("segments") or []):
            requested = {
                int(value) for value in list(planned_segment.get("reference_indices") or [])
                if str(value).strip().isdigit() and int(value) > 0
            }
            invalid = sorted(requested - generated_reference_indices)
            if invalid:
                raise ValueError(
                    "VIDEO_PROMPTS_REFERENCE_INDEX_INVALID: "
                    f"segment {planned_segment.get('segment_index')} requested {invalid}; "
                    f"available final reference indices are {sorted(generated_reference_indices)}"
                )
            if blocked_reference_indices:
                planned_segment["excluded_defective_reference_indices"] = sorted(
                    blocked_reference_indices
                )
    video_refs = (
        []
        if text_to_video
        else _copy_reference_videos(
            project,
            _reference_videos_for_project(db, project),
        )
    )
    video_policy = _video_model_policy(project)
    reference_limit = int(video_policy["reference_limit"])
    video_resolution = _configured_video_resolution(project)
    video_language = _configured_video_language(project)
    video_language_label = _video_language_label(project)
    project_requirement = _project_requirement_text(project)
    project_visual_style_requirement = _project_visual_style_requirement(
        project
    )
    marketing = _marketing_authorization(project)
    project_uses_product = _project_uses_product(project)
    # Provider-facing choreography is authored from the actual final reference
    # pixels, not assembled from a code template.  The signed production plan
    # remains the story/copy authority; this multimodal pass translates that
    # authority into executable segment-local motion, camera and performance
    # instructions before the immutable media manifest is hashed.
    author_cache_key = "multimodal_provider_segment_authoring_v1"
    project_state = dict(project.state_json or {})
    author_cache = dict(project_state.get(author_cache_key) or {})
    author_cache_changed = False
    if not text_to_video:
        for authored_video in video_plan:
            signed_plan_compiled = bool(
                dict(authored_video.get("compiler_authority") or {}).get(
                    "production_plan_sha256"
                )
            ) or all(
                str(dict(item).get("compile_source") or "")
                == "signed_production_plan"
                for item in list(authored_video.get("segments") or [])
                if isinstance(item, dict)
            )
            authored_segments = list(authored_video.get("segments") or [])
            for segment_offset, original_segment in enumerate(authored_segments):
                segment = dict(original_segment)
                segment_index = int(segment.get("segment_index") or segment_offset + 1)
                segment_count = int(
                    segment.get("segment_count") or len(authored_segments) or 1
                )
                requested_indices = {
                    int(value)
                    for value in list(segment.get("reference_indices") or [])
                    if str(value).strip().isdigit() and int(value) > 0
                }
                requested_refs = [
                    ref for ref in refs
                    if int(ref.get("index") or 0) in requested_indices
                ]
                product_required = project_uses_product and (
                    bool(segment.get("product_anchor_required"))
                    if signed_plan_compiled
                    else (
                        _segment_needs_product_anchor(
                            str(segment.get("prompt") or ""), requested_refs
                        )
                        or segment_index >= segment_count
                    )
                )
                segment_refs = _select_segment_refs(
                    refs,
                    list(segment.get("reference_indices") or []),
                    reference_limit,
                    prompt=str(segment.get("prompt") or ""),
                    product_required=product_required,
                    segment_index=segment_index,
                )
                if product_required:
                    segment_refs = _ensure_product_authority_ref(
                        segment_refs, refs, reference_limit
                    )
                reference_manifest = [
                    {
                        "alias": f"@image{position}",
                        "asset_id": int(ref.get("asset_id") or 0),
                        "filename": str(ref.get("filename") or ""),
                        "description": str(ref.get("description") or ""),
                        "semantic_roles": list(ref.get("semantic_roles") or []),
                        "is_product_anchor": bool(ref.get("is_product_anchor")),
                    }
                    for position, ref in enumerate(segment_refs, 1)
                ]
                contract = {
                    "segment_index": segment_index,
                    "duration_seconds": int(segment.get("duration") or 0),
                    "segment_goal": str(segment.get("segment_goal") or ""),
                    "visual_style": str(segment.get("visual_style") or ""),
                    "visual_grammar": str(
                        segment.get("visual_grammar") or ""
                    ),
                    "project_visual_style_requirement": str(
                        segment.get("project_visual_style_requirement")
                        or project_visual_style_requirement
                        or ""
                    ),
                    "continuity_note": str(
                        segment.get("continuity_note") or ""
                    ),
                    "negative_prompt": str(
                        segment.get("negative_prompt") or ""
                    ),
                    "timeline": list(segment.get("timeline") or []),
                    "pacing": str(segment.get("pacing") or ""),
                    "camera_direction": str(
                        segment.get("camera_direction") or ""
                    ),
                }
                digest_payload = {
                    "policy": VIDEO_PROMPT_POLICY_VERSION,
                    "source_stage_id": int(source_stage_id),
                    "video_index": int(authored_video.get("video_index") or 0),
                    "segment": contract,
                    "dialogue": list(segment.get("dialogue_lines") or []),
                    "voice": list(segment.get("voice_lock") or []),
                    "references": reference_manifest,
                    "provider": str(video_policy.get("id") or ""),
                }
                digest = hashlib.sha256(
                    json.dumps(
                        digest_payload,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                        default=str,
                    ).encode("utf-8")
                ).hexdigest()
                authored = dict(author_cache.get(digest) or {})
                if not authored:
                    authored = replan_failed_segment_execution_api(
                        db,
                        segment_contract=contract,
                        execution_review={
                            "observed_execution": [
                                "No provider attempt exists; author the initial "
                                "execution from the signed plan and attached pixels."
                            ],
                            "missing_planned_execution": [],
                            "blocking_reasons": [],
                        },
                        dialogue_lines=list(segment.get("dialogue_lines") or []),
                        execution_id=(
                            f"{project.project_key}:source:{int(source_stage_id)}:"
                            f"v{int(authored_video.get('video_index') or 0)}:"
                            f"s{segment_index}"
                        ),
                        requirement_contract=list(
                            segment.get("requirement_contract") or []
                        ),
                        forbid_overlay_bands=bool(
                            _project_forbids_local_display_overlays(project)
                        ),
                        reference_manifest=reference_manifest,
                        reference_image_paths=[
                            str(ref.get("path") or "") for ref in segment_refs
                        ],
                        provider_key=str(video_policy.get("provider_key") or ""),
                        provider_prompt_language=(
                            "zh"
                            if str(video_policy.get("id") or "")
                            == "seedance_2_0_mini"
                            else "en"
                        ),
                        provider_prompt_max_characters=int(
                            video_policy["provider_prompt_max_characters"]
                        ),
                        initial_multimodal_authoring=True,
                    )
                    author_cache[digest] = authored
                    author_cache_changed = True
                selected_action_key = (
                    "provider_action_zh"
                    if str(video_policy.get("id") or "")
                    == "seedance_2_0_mini"
                    else "provider_action_en"
                )
                authored_timeline: list[dict[str, Any]] = []
                for beat in list(authored.get("timeline") or []):
                    if not isinstance(beat, dict):
                        continue
                    authored_timeline.append({
                        **dict(beat),
                        "audit_action": str(beat.get("action") or ""),
                        "action": str(
                            beat.get(selected_action_key)
                            or beat.get("action")
                            or ""
                        ),
                    })
                if authored_timeline:
                    segment["timeline"] = authored_timeline
                # The multimodal author inspected the actual pixels, not just
                # their planned descriptions.  Respect its bounded reference
                # decision when a still conflicts with the signed opening
                # state; otherwise the later queue builder silently restores
                # every pre-authoring image and can overwhelm both Seedance's
                # visual conditioning and its 495-character alias lane.
                authored_aliases = [
                    str(value or "").strip()
                    for value in list(
                        authored.get("keep_reference_aliases") or []
                    )
                    if str(value or "").strip()
                ]
                if authored_aliases:
                    kept_indices, kept_aliases = (
                        _authored_reference_selection(
                            authored_aliases,
                            segment_refs,
                            product_required=product_required,
                        )
                    )
                    segment["reference_indices"] = kept_indices
                    authored_aliases = kept_aliases
                else:
                    # Empty is a valid, explicit multimodal decision. The
                    # uploaded product authority is appended independently
                    # whenever the segment shows the product.
                    segment["reference_indices"] = []
                segment["reference_selection_authoritative"] = True
                segment["segment_goal"] = str(
                    authored.get("segment_goal")
                    or segment.get("segment_goal")
                    or ""
                )
                segment["pacing"] = str(
                    authored.get("pacing") or segment.get("pacing") or ""
                )
                segment["camera_direction"] = str(
                    authored.get("camera_direction")
                    or segment.get("camera_direction")
                    or ""
                )
                segment["provider_direction"] = str(
                    authored.get(
                        "provider_direction_zh"
                        if str(video_policy.get("id") or "")
                        == "seedance_2_0_mini"
                        else "provider_direction_en"
                    )
                    or ""
                )
                segment["multimodal_provider_authoring"] = {
                    "policy_version": VIDEO_PROMPT_POLICY_VERSION,
                    "digest": digest,
                    "reference_aliases": [
                        row["alias"] for row in reference_manifest
                    ],
                    "kept_reference_aliases": authored_aliases,
                    "reference_assessments": list(
                        authored.get("reference_assessments") or []
                    ),
                    "motion_authority": "prompt_text",
                    "reference_authority": "sparse_visual_anchors_only",
                    "model_routed": True,
                }
                authored_segments[segment_offset] = segment
            authored_video["segments"] = authored_segments
    if author_cache_changed:
        project_state[author_cache_key] = dict(
            list(author_cache.items())[-200:]
        )
        project.state_json = project_state
        db.add(project)
        db.flush()
    provider_retry_budget = max(
        0,
        min(
            3,
            int(
                dict(project.config_json or {}).get(
                    "content_factory_video_retry_limit"
                )
                or 2
            ),
        ),
    )
    manifest_payload = {
        "schema_version": "content-media-manifest-v1",
        "variant_index": int(active_variant),
        "source_stage_id": int(source_stage_id),
        "director_media_authorization": director_media_authorization,
        "video_plan": video_plan,
        "video_generation_mode": generation_mode,
        "references": [
            {
                "asset_id": int(ref.get("asset_id") or 0),
                "index": int(ref.get("index") or 0),
                "filename": str(ref.get("filename") or ""),
                "size_bytes": int(ref.get("size_bytes") or 0),
                "semantic_roles": list(ref.get("semantic_roles") or []),
                "is_product_anchor": bool(ref.get("is_product_anchor")),
            }
            for ref in refs
        ],
        "product_render_mode": (
            "text_only" if text_to_video else "provider_reference"
        ),
        "reference_videos": [
            {
                "index": int(ref.get("index") or 0),
                "filename": str(ref.get("filename") or ""),
                "size_bytes": int(ref.get("size_bytes") or 0),
            }
            for ref in video_refs
        ],
        "video_policy": video_policy,
        "resolution": video_resolution,
        "language": video_language,
        "project_requirement": project_requirement,
        "visual_style_requirement": project_visual_style_requirement,
        "marketing_authorization": marketing,
        "prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
        "postproduction_policy_version": LOCAL_POSTPRODUCTION_POLICY_VERSION,
        "provider_retry_budget_per_segment": provider_retry_budget,
    }
    media_manifest_sha256 = hashlib.sha256(
        json.dumps(
            manifest_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    current_state = dict(project.state_json or {})
    existing_group = next(
        (
            dict(group)
            for group in list(current_state.get("ai_video_groups") or [])
            if int(dict(group).get("video_index") or 0) == int(active_variant)
        ),
        None,
    )
    existing_tasks: list[KieTask] = []
    if existing_group is not None:
        existing_ids = [
            int(segment.get("task_id") or 0)
            for segment in list(existing_group.get("segments") or [])
            if int(segment.get("task_id") or 0) > 0
        ]
        if existing_ids:
            query = db.query(KieTask).filter(
                KieTask.id.in_(tuple(existing_ids)),
                KieTask.workspace_id == int(project.workspace_id),
            )
            if project.user_id is not None:
                query = query.filter(
                    KieTask.created_by_user_id == int(project.user_id)
                )
            existing_tasks = query.all()
        existing_group = _recover_legacy_media_group_source_stage(
            project,
            existing_group,
            existing_tasks,
        )
    existing_group_superseded = bool(
        existing_group is not None
        and _media_group_source_is_superseded(db, project, existing_group)
    )
    if existing_group_superseded:
        stale_manifest = str(
            dict(existing_group or {}).get("media_manifest_sha256") or ""
        ).strip()
        if stale_manifest:
            stale_runs = db.query(HermesContentVariantRun).filter(
                HermesContentVariantRun.project_id == int(project.id),
                HermesContentVariantRun.variant_index == int(active_variant),
                HermesContentVariantRun.media_manifest_sha256 == stale_manifest,
            ).all()
            for stale_run in stale_runs:
                if str(stale_run.state or "").lower() == "composed":
                    continue
                stale_run.state = "superseded"
                stale_run.error_class = "source_stage_superseded"
                stale_run.error_message = (
                    "Media attempt retired because its source VIDEO_PROMPTS "
                    "stage lost execution authority."
                )
                stale_meta = dict(stale_run.meta_json or {})
                stale_meta.update({
                    "superseded_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                    "superseded_source_stage_id": int(
                        dict(existing_group or {}).get("source_stage_id") or 0
                    ),
                    "replacement_source_stage_id": int(source_stage_id),
                })
                stale_run.meta_json = stale_meta
                db.add(stale_run)
    if existing_group is not None and not existing_group_superseded:
        existing_ids = [
            int(segment.get("task_id") or 0)
            for segment in list(existing_group.get("segments") or [])
            if int(segment.get("task_id") or 0) > 0
        ]
        existing_manifest_ids = _guard_existing_media_manifest(
            existing_group,
            existing_tasks,
            media_manifest_sha256=media_manifest_sha256,
            variant_index=active_variant,
        )
        if existing_manifest_ids is not None:
            return existing_manifest_ids
    tasks = []
    groups: list[dict[str, Any]] = []
    project_name = _safe_file_stem(project.title or project.product_name or project.project_key)
    for video in video_plan:
        signed_plan_compiled = bool(
            dict(video.get("compiler_authority") or {}).get(
                "production_plan_sha256"
            )
        ) or all(
            str(dict(segment).get("compile_source") or "")
            == "signed_production_plan"
            for segment in list(video.get("segments") or [])
            if isinstance(segment, dict)
        )
        audio_mode = str(
            video.get("audio_mode") or "spoken"
        ).strip().lower()
        promo = _required_video_promotion(project, video)
        config = dict(project.config_json or {})
        promo_allowed_for_video = bool(marketing.get("allow_promotional_cta")) or (
            bool(promo)
            and bool(config.get("allow_promotional_cta", True))
            and bool(config.get("user_confirmed_marketing", True))
        )
        version_name = _safe_file_stem(video["version_name"] or f"v{video['video_index']:02d}")
        final_name_base = f"{project_name}-{version_name}-{video['video_index']}"
        group = {
            "video_index": int(video["video_index"]),
            "version_name": version_name,
            "story_arc": video.get("story_arc"),
            "duration": int(video["duration_seconds"]),
            "aspect_ratio": str(
                video.get("aspect_ratio")
                or next(
                    (
                        dict(item).get("aspect_ratio")
                        for item in list(video.get("segments") or [])
                        if dict(item).get("aspect_ratio")
                    ),
                    _configured_video_aspect_ratio(project),
                )
            ),
            "final_name_base": final_name_base,
            "segments": [],
            "director_media_authorization": director_media_authorization,
            "media_manifest_sha256": media_manifest_sha256,
            "media_manifest_schema_version": "content-media-manifest-v1",
            "provider_retry_budget_per_segment": provider_retry_budget,
            "source_stage_id": int(source_stage_id),
            "intent_manifest_sha256": video.get("intent_manifest_sha256"),
            "intent_requirements": list(video.get("intent_requirements") or []),
            "requirement_execution": list(video.get("requirement_execution") or []),
            "production_requirement_execution": list(
                video.get("production_requirement_execution") or []
            ),
            "audio_mode": audio_mode,
        }
        previous_task_id: int | None = None
        video_elapsed_seconds = 0.0
        for segment in video["segments"]:
            segment = dict(segment)
            if project_visual_style_requirement:
                segment["project_visual_style_requirement"] = (
                    project_visual_style_requirement
                )
            segment_index = int(segment["segment_index"])
            segment_count = int(segment.get("segment_count") or len(video["segments"]) or 1)
            is_final_segment = segment_index >= segment_count
            # Whether the product appears is a signed production-plan
            # decision.  Historical plans retain the old bounded inference
            # fallback; a Showrunner plan never receives a forced final
            # product shot merely because the project has a product bound.
            requested_reference_indices = {
                int(value) for value in list(segment.get("reference_indices") or [])
                if str(value).strip().isdigit() and int(value) > 0
            }
            requested_refs = [
                ref for ref in refs
                if int(ref.get("index") or 0) in requested_reference_indices
            ]
            product_visual_evidence = _segment_product_visual_evidence(segment)
            product_required = project_uses_product and (
                bool(segment.get("product_anchor_required"))
                if signed_plan_compiled
                else (
                    _segment_needs_product_anchor(
                        str(segment["prompt"]), requested_refs
                    )
                    or is_final_segment
                )
            )
            segment_refs = (
                []
                if text_to_video
                else _select_segment_refs(
                    refs,
                    list(segment.get("reference_indices") or []),
                    reference_limit,
                    prompt=str(segment.get("prompt") or ""),
                    product_required=product_required,
                    segment_index=segment_index,
                    authoritative_selection=bool(
                        segment.get("reference_selection_authoritative")
                    ),
                )
            )
            if product_required and not text_to_video:
                segment_refs = _ensure_product_authority_ref(segment_refs, refs, reference_limit)
                if not any(
                    bool(ref.get("is_product_anchor")) for ref in segment_refs
                ):
                    raise ValueError(
                        "CONTENT_PRODUCT_AUTHORITY_MISSING: product-visible "
                        f"variant {int(video['video_index'])} segment "
                        f"{segment_index} has no authoritative uploaded "
                        "product reference"
                    )
            offer_for_segment = "" if signed_plan_compiled else (
                promo
                if (
                    audio_mode == "spoken"
                    and is_final_segment
                    and promo
                    and promo_allowed_for_video
                )
                else ""
            )
            soft_cta_for_segment = "" if signed_plan_compiled else (
                _non_promotional_video_cta(project, video_language)
                if (
                    audio_mode == "spoken"
                    and is_final_segment
                    and project_uses_product
                    and not offer_for_segment
                )
                else ""
            )
            semantic_source_prompt = _compact_provider_segment_prompt(
                segment,
                resolution=video_resolution,
                aspect_ratio=str(
                    segment.get("aspect_ratio")
                    or group.get("aspect_ratio")
                    or _configured_video_aspect_ratio(project)
                ),
                language_label=video_language_label,
                requirement_contract=list(
                    segment.get("requirement_contract") or []
                ),
                promotion=offer_for_segment,
                soft_cta=soft_cta_for_segment,
                product_required=product_required,
                product_name=str(project.product_name or "the approved product").strip(),
                product_presentation_policy=_product_presentation_policy(project),
                audio_mode=audio_mode,
            )
            provider_prompt_limit = int(
                video_policy["provider_prompt_max_characters"]
            )
            base_prompt = compact_structured_video_prompt(
                semantic_source_prompt,
                max_characters=provider_prompt_limit,
            )
            base_prompt += (
                f"\nSegment scope: {segment_index}/{segment_count}; show only this segment's actions and dialogue."
            )
            continuity_dependency = str(
                segment.get("continuity_dependency")
                or "previous_segment"
            ).strip().lower()
            if text_to_video:
                continuity_dependency = "independent"
            if continuity_dependency not in {
                "previous_segment",
                "independent",
            }:
                continuity_dependency = "previous_segment"
            waits_for_previous_segment = bool(
                not text_to_video
                and
                video_policy["id"] == "omni_flash"
                and segment_index > 1
                and continuity_dependency == "previous_segment"
            )
            # ``continuity_dependency`` is authored by the Director and may
            # describe story continuity even when the selected provider does
            # not consume the previous segment's final frame.  Persist the
            # execution dependency, not the narrative label, so downstream
            # recovery never invents a first-frame requirement for Seedance
            # reference-anchored independent shots.
            if segment_index > 1 and not waits_for_previous_segment:
                continuity_dependency = "independent"
            if segment_count > 1 and segment_index == 1:
                base_prompt += (
                    " End on this segment's signed continuity state; do not "
                    "preplay a later segment."
                )
            elif segment_count > 1 and waits_for_previous_segment:
                base_prompt += (
                    " Begin from the previous segment's final frame; do not "
                    "replay an earlier segment."
                )
            elif segment_count > 1:
                base_prompt += (
                    " This is a Director-approved independent shot. Follow "
                    "only this segment's signed prompt and do not imply an "
                    "unprovided first-frame continuation."
                )
            if offer_for_segment and not signed_plan_compiled:
                base_prompt = _ensure_prompt_required_promotion(base_prompt, offer_for_segment, video_language)
            if product_required and not signed_plan_compiled:
                base_prompt = _ensure_prompt_conversion_block(
                    base_prompt,
                    project,
                    language=video_language,
                    promotion=offer_for_segment,
                    final_segment=is_final_segment,
                )
            prompt = base_prompt
            if video_policy["id"] == "omni_flash" and not text_to_video:
                prompt = _omni_reference_prompt(
                    base_prompt,
                    segment_refs,
                    product_required=product_required,
                    first_frame=False,
                )
            elif video_policy["id"] == "seedance_2_0_mini" and not text_to_video:
                prompt = _seedance_reference_prompt(
                    base_prompt,
                    segment_refs,
                )
            else:
                prompt += "\nOne continuous full-frame scene. No collage, inset, playback UI, watermark, or language mixing."
            prompt = compact_structured_video_prompt(
                prompt,
                max_characters=provider_prompt_limit,
            )
            dependency_task_id = previous_task_id if waits_for_previous_segment else None
            input_params = {
                "model": str(video_policy["task_model"]), "prompt": prompt,
                "aspect_ratio": str(
                    segment.get("aspect_ratio")
                    or group.get("aspect_ratio")
                    or _configured_video_aspect_ratio(project)
                ),
                "seconds": str(int(segment["duration"])),
                "generate_audio": audio_mode != "silent",
                # Resolve enabled providers by the priority stored in API
                # management; each attempted key is recorded by the worker.
                "service_provider": "auto",
                "size": video_resolution,
                "resolution": video_resolution,
                "video_frame_mode": str(dict(project.config_json or {}).get("video_frame_mode") or "reference"),
                "content_factory_video_generation_mode": generation_mode,
                "reference_file_paths": segment_refs,
                "content_factory_reference_manifest": [
                    {
                        "alias": f"@image{position}",
                        "asset_id": int(ref.get("asset_id") or 0),
                        "filename": ref.get("filename"),
                        "semantic_roles": list(ref.get("semantic_roles") or []),
                        "is_product_anchor": bool(ref.get("is_product_anchor")),
                    }
                    for position, ref in enumerate(segment_refs, 1)
                ],
                "reference_video_file_paths": video_refs,
                "content_factory_project_id": int(project.id),
                "content_factory_project_key": project.project_key,
                "content_factory_variant_index": int(video["video_index"]),
                "content_factory_video_index": int(video["video_index"]),
                "content_factory_segment_index": int(segment["segment_index"]),
                "content_factory_final_name_base": final_name_base,
                "content_factory_video_language": video_language,
                "content_factory_base_prompt": base_prompt,
                "content_factory_required_promotion": offer_for_segment,
                "content_factory_conversion_points": (
                    []
                    if signed_plan_compiled
                    else _product_conversion_points(project, video_language)
                ),
                "content_factory_prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
                "content_factory_media_manifest_sha256": media_manifest_sha256,
                "content_factory_source_stage_id": int(source_stage_id),
                "content_factory_visual_style_requirement": str(
                    segment.get("visual_style")
                    or project_visual_style_requirement
                    or ""
                ),
                "content_factory_visual_grammar": str(
                    segment.get("visual_grammar") or ""
                ),
                "content_factory_prompt_hash": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
                "content_factory_product_required": bool(product_required),
                "content_factory_first_frame": False,
                "content_factory_dependency_task_id": dependency_task_id,
                "content_factory_requires_previous_segment_frame": bool(
                    waits_for_previous_segment
                ),
                "content_factory_continuity_dependency": continuity_dependency,
                "content_factory_audio_mode": audio_mode,
                "content_factory_dialogue_lines": list(
                    segment.get("dialogue_lines") or []
                ),
                "content_factory_voice_lock": list(
                    segment.get("voice_lock") or []
                ),
                "content_factory_display_lines": list(
                    segment.get("display_lines") or []
                ),
                "content_factory_segment_execution_contract": {
                    "segment_index": int(segment["segment_index"]),
                    "duration_seconds": int(segment["duration"]),
                    "global_start_seconds": float(video_elapsed_seconds),
                    "global_end_seconds": float(
                        video_elapsed_seconds + int(segment["duration"])
                    ),
                    "segment_goal": str(
                        segment.get("segment_goal") or ""
                    ),
                    "visual_style": str(
                        segment.get("visual_style") or ""
                    ),
                    "visual_grammar": str(
                        segment.get("visual_grammar") or ""
                    ),
                    "project_visual_style_requirement": str(
                        segment.get("project_visual_style_requirement")
                        or project_visual_style_requirement
                        or ""
                    ),
                    "continuity_note": str(
                        segment.get("continuity_note") or ""
                    ),
                    "negative_prompt": str(
                        segment.get("negative_prompt") or ""
                    ),
                    "timeline": list(segment.get("timeline") or []),
                    "pacing": str(segment.get("pacing") or ""),
                    "camera_direction": str(
                        segment.get("camera_direction") or ""
                    ),
                    "requirement_ids": list(
                        segment.get("requirement_ids") or []
                    ),
                },
                "content_factory_intent_manifest_sha256": (
                    str(segment.get("intent_manifest_sha256") or "") or None
                ),
                "content_factory_requirement_contract": list(
                    segment.get("requirement_contract") or []
                ),
                "content_factory_forbid_overlay_bands": bool(
                    _project_forbids_local_display_overlays(project)
                ),
                "content_factory_product_anchor_required": bool(
                    product_required
                ),
                "content_factory_product_requirement_source": {
                    "declared": bool(
                        segment.get("product_anchor_required")
                    ),
                    "visual_evidence": product_visual_evidence,
                    "derived_required": bool(product_required),
                },
                "content_factory_product_render_mode": (
                    "text_only" if text_to_video else "provider_reference"
                ),
                "content_factory_compile_source": str(
                    segment.get("compile_source") or ""
                ),
                "content_factory_exact_script_locked": bool(
                    signed_plan_compiled
                ),
                "content_factory_director_artifact_sha256": (
                    str(
                        dict(director_media_authorization or {}).get(
                            "director_artifact_sha256"
                        )
                        or ""
                    )
                    or None
                ),
                "content_factory_director_script_sha256": (
                    str(
                        dict(director_media_authorization or {}).get(
                            "director_script_sha256"
                        )
                        or ""
                    )
                    or None
                ),
            }
            _validate_and_stamp_provider_prompt(
                input_params,
                source_prompt=semantic_source_prompt,
                actual_prompt=prompt,
            )
            try:
                route_key = resolve_video_model_key(
                    db,
                    model_id=str(video_policy["id"]),
                    reference_count=len(segment_refs),
                    reference_video_count=len(video_refs),
                    aspect_ratio=str(input_params["aspect_ratio"]),
                    reference_mode=str(
                        input_params.get("video_frame_mode") or "reference"
                    ),
                    duration=int(segment["duration"]),
                    resolution=video_resolution,
                )
            except ValueError as exc:
                raise ValueError(
                    "VIDEO_PROVIDER_ROUTE_UNAVAILABLE: no enabled provider "
                    f"supports variant {int(video['video_index'])} segment "
                    f"{segment_index} at {int(segment['duration'])} seconds"
                ) from exc
            task = create_local_video_task(
                db, workspace_id=project.workspace_id, key_id=route_key.id,
                input_params=input_params, actor_user_id=project.user_id,
                actor_workspace_id=project.workspace_id,
            )
            if waits_for_previous_segment:
                task.state = "waiting_dependency"
                task.fail_code = None
                task.fail_msg = None
                db.add(task)
            tasks.append(task)
            for ref_position, ref in enumerate(segment_refs, 1):
                db.add(KieFile(
                    workspace_id=project.workspace_id, key_id=route_key.id, task_id=task.id,
                    file_url=ref["path"], kind="reference_upload", mime_type=ref["content_type"],
                    size_bytes=ref["size_bytes"],
                    meta_json={
                        "filename": ref["filename"], "source": "hermes_content_factory",
                        "reference_index": int(ref["index"]),
                        "asset_id": int(ref.get("asset_id") or 0),
                        "asset_role": ref.get("role"),
                        "semantic_roles": list(ref.get("semantic_roles") or []),
                        "omni_alias": f"@image{ref_position}",
                        "provider_alias": f"<IMAGE_REF_{ref_position - 1}>",
                        "is_product_anchor": bool(ref.get("is_product_anchor")),
                        "video_index": int(video["video_index"]),
                        "segment_index": int(segment["segment_index"]),
                        "resolution": video_resolution,
                        "language": video_language,
                    },
                ))
            for ref in video_refs:
                db.add(KieFile(
                    workspace_id=project.workspace_id, key_id=route_key.id, task_id=task.id,
                    file_url=ref["path"], kind="reference_video_upload", mime_type=ref["content_type"],
                    size_bytes=ref["size_bytes"],
                    meta_json={
                        "filename": ref["filename"], "source": "hermes_content_factory",
                        "reference_video_index": int(ref["index"]),
                        "video_index": int(video["video_index"]),
                        "segment_index": int(segment["segment_index"]),
                    },
                ))
            group["segments"].append({
                "task_id": int(task.id),
                "segment_index": segment_index,
                "dependency_task_id": dependency_task_id,
                "dependency_status": "waiting_previous_segment" if waits_for_previous_segment else "ready",
                "continuity_dependency": continuity_dependency,
                "reference_indices": [int(ref["index"]) for ref in segment_refs],
                "reference_names": [ref["filename"] for ref in segment_refs],
                "reference_bindings": [
                    {
                        "alias": f"<IMAGE_REF_{index - 1}>",
                        "asset_id": int(ref.get("asset_id") or 0),
                        "filename": ref["filename"],
                        "semantic_roles": list(ref.get("semantic_roles") or []),
                        "is_product_anchor": bool(ref.get("is_product_anchor")),
                    }
                    for index, ref in enumerate(segment_refs, 1)
                ],
                "product_anchor_names": [ref["filename"] for ref in segment_refs if ref.get("is_product_anchor")],
                "reference_video_names": [ref["filename"] for ref in video_refs],
                "duration": int(segment["duration"]),
                "initial_provider_key": str(route_key.provider_key),
                "initial_provider_key_id": int(route_key.id),
                "resolution": video_resolution,
                "language": video_language,
                "segment_goal": str(segment.get("segment_goal") or ""),
                "timeline": list(segment.get("timeline") or []),
                "dialogue_lines": list(segment.get("dialogue_lines") or []),
                "display_lines": list(segment.get("display_lines") or []),
                "voice_lock": list(segment.get("voice_lock") or []),
                "product_anchor_required": bool(product_required),
                "product_render_mode": (
                    "text_only" if text_to_video else "provider_reference"
                ),
                "compile_source": str(segment.get("compile_source") or ""),
                "requirement_ids": list(segment.get("requirement_ids") or []),
                "requirement_contract": list(
                    segment.get("requirement_contract") or []
                ),
                "audio_mode": audio_mode,
                "prompt": prompt[:1000],
            })
            previous_task_id = int(task.id)
            video_elapsed_seconds += int(segment["duration"])
        groups.append(group)
    batch_root = max(int(task.id) for task in tasks)
    total_segments = len(tasks)
    for segment_number, task in enumerate(tasks, 1):
        params = dict(task.input_json or {})
        video_index = int(params.get("content_factory_video_index") or 0)
        segment_index = int(params.get("content_factory_segment_index") or 0)
        final_name_base = _safe_file_stem(str(params.get("content_factory_final_name_base") or f"{batch_root}-{segment_number}"))
        set_task_local_meta(
            task,
            download_name_base=f"{final_name_base}-segment-{segment_index}",
            batch_root_task_id=batch_root,
            batch_index=segment_number,
            batch_size=total_segments,
            content_factory_project_id=int(project.id),
            content_factory_project_key=project.project_key,
            content_factory_variant_index=video_index,
            content_factory_video_index=video_index,
            content_factory_segment_index=segment_index,
            content_factory_final_name_base=final_name_base,
            active_provider=str(
                db.get(KieApiKey, int(task.key_id)).provider_key
            ),
            active_provider_key_id=int(task.key_id),
            # The waiter uses this durable publish lease to distinguish a
            # broker handoff in progress from a lost delivery.  Without it a
            # 20-second waiter republishes every still-reserved queued_local
            # segment, filling the queue with no-op duplicates and delaying
            # result downloads.
            submit_enqueued_at=(
                datetime.now(timezone.utc).isoformat()
                if str(task.state or "").lower() == "queued_local"
                else None
            ),
        )
    db.flush()
    _dual_write_media_execution_ledger(
        db,
        project=project,
        groups=groups,
        tasks=tasks,
        media_manifest_sha256=media_manifest_sha256,
        provider_key=str(video_policy["provider_key"]),
        provider_model=str(video_policy["task_model"]),
    )
    task_ids = [int(task.id) for task in tasks]
    state = dict(project.state_json or {})
    existing_task_ids = [
        int(value) for value in list(state.get("ai_video_task_ids") or [])
        if str(value).strip().isdigit()
    ]
    previous_groups = [
        group for group in list(state.get("ai_video_groups") or [])
        if int(group.get("video_index") or 0) != int(active_variant)
    ]
    replaced_task_ids = {
        int(segment.get("task_id") or 0)
        for group in list(state.get("ai_video_groups") or [])
        if int(group.get("video_index") or 0) == int(active_variant)
        for segment in list(group.get("segments") or [])
        if int(segment.get("task_id") or 0) > 0
    }
    if replaced_task_ids:
        for stale_task in _scoped_content_video_tasks(
            db,
            project,
            replaced_task_ids,
        ):
            stale_state = str(stale_task.state or "").lower()
            provider_visible = not str(stale_task.task_id or "").startswith(
                "local-bandianwa-"
            )
            if stale_state in {"queued_local", "waiting_dependency"} or not provider_visible:
                stale_task.state = "failed"
                # KieTask.fail_code is VARCHAR(32). Keep stable machine codes
                # inside that storage contract so the whole replacement
                # remains one atomic transaction instead of rolling back.
                stale_task.fail_code = CONTENT_FACTORY_VARIANT_SUPERSEDED_CODE
                stale_task.fail_msg = (
                    "Superseded before provider submission by replacement "
                    f"content-factory variant {int(active_variant)}."
                )
            set_task_local_meta(
                stale_task,
                superseded_at=datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                superseded_by_task_ids=task_ids,
                drain_non_authoritative=bool(provider_visible and not _is_terminal_video_task(stale_task)),
                content_factory_variant_index=int(active_variant),
            )
            db.add(stale_task)
    state["ai_video_blocked_reference_asset_ids"] = sorted(blocked_asset_ids)
    for stale_key in (
        # Retry history is intentionally retained across serial variants; only
        # transient wait result sets are refreshed for the newly submitted one.
        "ai_video_failed_task_ids",
        "ai_video_pending_task_ids",
        "ai_video_group_statuses",
        "ai_video_ready_video_count",
        "ai_video_dependency_released_at",
        "ai_video_queued_local_resubmitted_at",
    ):
        state.pop(stale_key, None)
    state["ai_video_task_ids"] = sorted({
        task_id for task_id in existing_task_ids
        if int(task_id) not in replaced_task_ids
    }.union(task_ids))
    state["ai_video_groups"] = previous_groups + groups
    state["ai_video_mode"] = "segmented"
    state["ai_video_submission_enqueued_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    pipeline = _variant_pipeline(project)
    pipeline["completed_indices"] = _authoritative_completed_variant_indices(
        _completed_video_assets_by_index(db, project).keys(),
        target=int(pipeline.get("target_count") or _target_video_count(project)),
    )
    pipeline["completion_blocked_missing_indices"] = [
        index
        for index in range(
            1,
            int(pipeline.get("target_count") or _target_video_count(project)) + 1,
        )
        if index not in set(pipeline["completed_indices"])
    ]
    submitted = {
        int(value) for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit()
    }
    submitted.add(int(active_variant))
    pipeline["submitted_indices"] = sorted(submitted)
    pipeline["last_submitted_variant_index"] = int(active_variant)
    pipeline["last_submitted_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    state["video_variant_pipeline"] = pipeline
    state["active_variant_index"] = int(pipeline.get("active_index") or active_variant)
    project.state_json = state
    project.status = "generating_video"
    # Publish the source checkpoint and its provider-task ledger atomically.
    # Multimodal provider-prompt authoring can commit routing telemetry through
    # this SQLAlchemy session.  Marking VIDEO_PROMPTS successful before the
    # task ledger existed exposed WAITING_VIDEO_INPUT with no task ids, so the
    # periodic self-healer repeatedly superseded the still-running compiler.
    # A running current compiler is accepted above, but becomes successful in
    # the same commit that makes its locally queued tasks authoritative.
    if source_status == "running":
        source_stage.status = "success"
        source_stage.error_message = None
        source_stage.completed_at = _stage_now()
        db.add(source_stage)
    db.commit()
    for task in tasks:
        if str(task.state or "").lower() != "queued_local":
            continue
        submit_and_poll_ai_video_task.apply_async(
            kwargs={"workspace_id": project.workspace_id, "local_task_id": int(task.id), "interval_seconds": int(settings.BANDIANWA_POLL_INTERVAL_SECONDS), "timeout_seconds": int(settings.BANDIANWA_POLL_TIMEOUT_SECONDS)},
            queue=production_video_queue(task),
        )
    _schedule_video_wait(db, project, countdown=20, reason=f"initial video generation wait for variant {active_variant}")
    resumed_variant_stage = (
        _queue_next_variant_after_video_submit(
            db,
            project,
            submitted_variant_index=int(active_variant),
        )
        if advance_pipeline
        else None
    )
    if resumed_variant_stage is not None:
        _publish_stage(resumed_variant_stage, project)
        db.commit()
    return task_ids


def _contact_sheet(video_path: Path, target: Path) -> None:
    probe = subprocess.run(
        [FFPROBE_BIN, "-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", str(video_path)],
        check=True, capture_output=True, text=True, timeout=30,
    )
    duration = max(1.0, float(probe.stdout.strip() or 10.0))
    target.parent.mkdir(parents=True, exist_ok=True)
    fps = 6.0 / duration
    subprocess.run(
        [
            FFMPEG_BIN, "-y", "-i", str(video_path), "-an",
            "-vf", f"fps={fps:.8f},scale=480:-2,tile=3x2:padding=4:margin=8",
            "-frames:v", "1", "-q:v", "2", str(target),
        ],
        check=True, capture_output=True, text=True, timeout=180,
    )
    if not target.is_file() or target.stat().st_size < 1024:
        raise RuntimeError(f"FFmpeg did not create a usable contact sheet for {video_path}")


def _segment_execution_contact_sheet(
    video_path: Path,
    target: Path,
) -> None:
    """Sample the opening densely so a static hook cannot hide in averages."""

    duration = _probe_video_duration_seconds(video_path)
    opening_end = min(3.0, max(0.3, duration - 0.1))
    times = [
        min(opening_end, value)
        for value in (0.10, 0.70, 1.35, 2.05, 2.80)
    ]
    times.extend([
        max(0.0, duration * 0.55),
        max(0.0, duration * 0.78),
        max(0.0, duration - 0.12),
    ])
    # Preserve stable chronological order while collapsing duplicate samples
    # for clips shorter than the ordinary three-second opening window.
    samples: list[float] = []
    for value in sorted(times):
        timestamp = min(max(0.0, float(value)), max(0.0, duration - 0.05))
        if not samples or abs(timestamp - samples[-1]) >= 0.04:
            samples.append(timestamp)
    target.parent.mkdir(parents=True, exist_ok=True)
    frames: list[Image.Image] = []
    with tempfile.TemporaryDirectory(prefix="cf-execution-sheet-") as temp_dir:
        for index, timestamp in enumerate(samples, 1):
            frame_path = Path(temp_dir) / f"frame-{index:02d}.jpg"
            result = subprocess.run(
                [
                    FFMPEG_BIN, "-hide_banner", "-loglevel", "error", "-y",
                    "-ss", f"{timestamp:.3f}", "-i", str(video_path),
                    "-frames:v", "1", "-vf", "scale=360:-2",
                    "-q:v", "2", str(frame_path),
                ],
                check=False,
                capture_output=True,
                text=True,
                timeout=90,
            )
            if (
                result.returncode != 0
                or not frame_path.is_file()
                or frame_path.stat().st_size < 1024
            ):
                raise RuntimeError(
                    "Could not sample segment execution frame: "
                    + str(result.stderr or result.stdout or "")[:400]
                )
            # Execution review must inspect provider pixels only. Inspector
            # decorations previously burned into the frame were misclassified
            # as real caption/watermark-cover bands.
            frames.append(Image.open(frame_path).convert("RGB").copy())
    if not frames:
        raise RuntimeError("No segment execution frames were sampled")
    columns = 4
    rows = math.ceil(len(frames) / columns)
    width = max(frame.width for frame in frames)
    height = max(frame.height for frame in frames)
    sheet = Image.new(
        "RGB",
        (columns * width, rows * height),
        (22, 22, 22),
    )
    for index, frame in enumerate(frames):
        sheet.paste(
            frame,
            ((index % columns) * width, (index // columns) * height),
        )
    sheet.save(target, format="JPEG", quality=90, optimize=True)
    if not target.is_file() or target.stat().st_size < 1024:
        raise RuntimeError(
            f"Could not create segment execution contact sheet for {video_path}"
        )


def _segment_requirement_contract_for_review(
    project: HermesContentFactoryProject,
    task: KieTask,
    segment_contract: dict[str, Any],
    requirement_contract: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], float, float]:
    """Scope whole-video intent to the provider pixels under review.

    Project requirements remain available as negative/constraint checks, but
    their later positive actions are deferred to composed-video intent QA.
    Time-window requirements only become positive evidence gates for the
    segment whose global window overlaps them.
    """

    try:
        start_seconds = float(segment_contract.get("global_start_seconds"))
        end_seconds = float(segment_contract.get("global_end_seconds"))
    except (TypeError, ValueError):
        start_seconds = 0.0
        end_seconds = 0.0

    if end_seconds <= start_seconds:
        # Recover the global window for immutable tasks created before the
        # explicit fields existed. Match only by task id in this project.
        for group in list(dict(project.state_json or {}).get("ai_video_groups") or []):
            if not isinstance(group, dict):
                continue
            elapsed = 0.0
            for raw_segment in list(group.get("segments") or []):
                if not isinstance(raw_segment, dict):
                    continue
                duration = float(raw_segment.get("duration") or 0)
                if int(raw_segment.get("task_id") or 0) == int(task.id):
                    start_seconds = elapsed
                    end_seconds = elapsed + max(0.0, duration)
                    break
                elapsed += max(0.0, duration)
            if end_seconds > start_seconds:
                break

    if end_seconds <= start_seconds:
        duration = float(segment_contract.get("duration_seconds") or 0)
        end_seconds = start_seconds + max(0.0, duration)

    scoped: list[dict[str, Any]] = []
    for raw in list(requirement_contract or []):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        scope = str(item.get("scope") or "project").strip().lower()
        gate_mode = "constraint_only"
        if scope in {"segment", "current_segment"}:
            gate_mode = "positive_evidence"
        elif scope == "time_window":
            try:
                req_start = float(item.get("start_seconds") or 0)
            except (TypeError, ValueError):
                req_start = 0.0
            try:
                req_end = (
                    float(item.get("end_seconds"))
                    if item.get("end_seconds") is not None
                    else float("inf")
                )
            except (TypeError, ValueError):
                req_end = float("inf")
            if req_end <= start_seconds or req_start >= end_seconds:
                continue
            gate_mode = (
                "positive_evidence"
                if req_start >= start_seconds and req_end <= end_seconds
                else "partial_positive_evidence"
            )
            item["segment_observable_start_seconds"] = max(
                start_seconds,
                req_start,
            )
            item["segment_observable_end_seconds"] = min(
                end_seconds,
                req_end,
            )
            item["positive_evidence_deferred_before_segment"] = bool(
                req_start < start_seconds
            )
            item["positive_evidence_deferred_after_segment"] = bool(
                req_end > end_seconds
            )
        item["segment_gate_mode"] = gate_mode
        scoped.append(item)
    return scoped, start_seconds, end_seconds


def _review_provider_segment_execution(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    source: Path,
    task: KieTask,
) -> dict[str, Any] | None:
    params = dict(task.input_json or {})
    contract = dict(
        params.get("content_factory_segment_execution_contract") or {}
    )
    if (
        str(params.get("content_factory_compile_source") or "")
        != "signed_production_plan"
        or not contract
    ):
        return None
    source_sha256 = _file_sha256(source)
    local_meta = dict(get_task_local_meta(task) or {})
    cached = dict(local_meta.get("segment_execution_review") or {})
    if (
        str(cached.get("policy_version") or "")
        == SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
        and str(cached.get("source_sha256") or "") == source_sha256
        and str(cached.get("status") or "").lower() == "pass"
    ):
        return cached
    review_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
        / "generated"
        / "segment_execution_reviews"
    )
    sheet_path = (
        review_dir / f"task-{int(task.id)}-{source_sha256[:16]}.jpg"
    )
    _segment_execution_contact_sheet(source, sheet_path)
    scoped_requirements, global_start, global_end = (
        _segment_requirement_contract_for_review(
            project,
            task,
            contract,
            list(params.get("content_factory_requirement_contract") or []),
        )
    )
    review_contract = {
        **contract,
        "global_start_seconds": global_start,
        "global_end_seconds": global_end,
        "provider_pixels_only": True,
        "local_voiceover_pending": any(
            str(dict(item).get("delivery_method") or "").strip().lower()
            == "local_voiceover"
            for item in list(params.get("content_factory_dialogue_lines") or [])
            if isinstance(item, dict)
        ),
        "local_overlay_pending": any(
            str(dict(item).get("delivery_method") or "").strip().lower()
            == "local_overlay"
            for item in list(params.get("content_factory_display_lines") or [])
            if isinstance(item, dict)
        ),
        "provider_dialogue_pending_audio_review": any(
            str(dict(item).get("delivery_method") or "").strip().lower()
            == "provider_dialogue"
            for item in list(params.get("content_factory_dialogue_lines") or [])
            if isinstance(item, dict)
            and str(dict(item).get("delivery_mode") or "spoken").strip().lower()
            == "spoken"
            and str(dict(item).get("line") or "").strip()
        ),
        "pending_local_overlays": [
            {
                "line_id": str(dict(item).get("line_id") or "")[:80],
                "line": str(dict(item).get("line") or "")[:300],
                "start_seconds": dict(item).get("start_seconds"),
                "end_seconds": dict(item).get("end_seconds"),
            }
            for item in list(params.get("content_factory_display_lines") or [])
            if isinstance(item, dict)
            and str(dict(item).get("delivery_method") or "").strip().lower()
            == "local_overlay"
        ][:16],
        "pending_provider_dialogue": [
            {
                "line_id": str(dict(item).get("line_id") or "")[:80],
                "line": str(dict(item).get("line") or "")[:500],
                "start_seconds": dict(item).get("start_seconds"),
                "end_seconds": dict(item).get("end_seconds"),
            }
            for item in list(params.get("content_factory_dialogue_lines") or [])
            if isinstance(item, dict)
            and str(dict(item).get("delivery_method") or "").strip().lower()
            == "provider_dialogue"
            and str(dict(item).get("delivery_mode") or "spoken").strip().lower()
            == "spoken"
            and str(dict(item).get("line") or "").strip()
        ][:16],
        "authoritative_product_reference_supplied": any(
            isinstance(item, dict) and bool(item.get("is_product_anchor"))
            for item in list(params.get("reference_file_paths") or [])
        ),
    }
    verdict = review_provider_rendered_segment_execution_api(
        db,
        contact_sheet_path=str(sheet_path),
        segment_contract=review_contract,
        execution_id=(
            f"{params.get('content_factory_media_manifest_sha256') or ''}:"
            f"task-{int(task.id)}:{source_sha256}"
        ),
        requirement_contract=scoped_requirements,
        forbid_overlay_bands=bool(
            params.get("content_factory_forbid_overlay_bands")
        ),
    )
    review = {
        **dict(verdict),
        "source_sha256": source_sha256,
        "contact_sheet_path": str(sheet_path),
        "reviewed_at": _stage_now().isoformat(),
    }
    set_task_local_meta(task, segment_execution_review=review)
    db.add(task)
    db.flush()
    if bool(review.get("blocking")):
        reasons = "; ".join(
            str(value)
            for value in list(review.get("blocking_reasons") or [])
            if str(value).strip()
        )[:700]
        repair_packet = {
            "blocking": True,
            "status": "fail",
            "policy_version": review.get("policy_version"),
            "failed_requirement_ids": list(
                review.get("failed_requirement_ids") or []
            )[:16],
            "blocking_reasons": list(
                review.get("blocking_reasons") or []
            )[:8],
            "repair_instruction": str(
                review.get("repair_instruction") or ""
            )[:1200],
            "requirement_evidence": dict(
                review.get("requirement_evidence") or {}
            ),
        }
        raise ValueError(
            "CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_"
            f"{int(task.id)}: {reasons or 'render did not execute signed segment'}"
            " || REVIEW_JSON "
            + json.dumps(
                repair_packet,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
        )
    return review


def _review_provider_product_segment(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    source: Path,
    task: KieTask,
) -> dict[str, Any]:
    """Review a generated product segment once and cache its bounded verdict."""
    params = dict(task.input_json or {})
    product_ref = next(
        (
            dict(item)
            for item in list(params.get("reference_file_paths") or [])
            if isinstance(item, dict) and bool(item.get("is_product_anchor"))
        ),
        None,
    )
    product_path = Path(str(dict(product_ref or {}).get("path") or ""))
    if not product_path.is_file() or product_path.stat().st_size <= 1024:
        raise ValueError(
            "CONTENT_PRODUCT_VIDEO_REVIEW_AUTHORITY_MISSING_TASK_"
            f"{int(task.id)}"
        )
    source_sha256 = _file_sha256(source)
    product_sha256 = _file_sha256(product_path)
    local_meta = dict(get_task_local_meta(task) or {})
    cached = dict(local_meta.get("provider_product_video_review") or {})
    if (
        str(cached.get("policy_version") or "")
        == PRODUCT_REFERENCE_VIDEO_REVIEW_POLICY_VERSION
        and str(cached.get("source_sha256") or "") == source_sha256
        and str(cached.get("product_sha256") or "") == product_sha256
        and str(cached.get("status") or "").lower() == "pass"
    ):
        return cached
    review_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
        / "generated"
        / "product_video_reviews"
    )
    contact_sheet = review_dir / f"task-{int(task.id)}-{source_sha256[:16]}.jpg"
    _contact_sheet(source, contact_sheet)
    execution_contract = dict(
        params.get("content_factory_segment_execution_contract") or {}
    )
    segment_context = {
        key: execution_contract.get(key)
        for key in (
            "segment_index",
            "duration_seconds",
            "segment_goal",
            "visual_grammar",
            "continuity_note",
            "pacing",
            "camera_direction",
            "timeline",
        )
        if execution_contract.get(key) not in (None, "", [], {})
    }
    verdict = review_provider_rendered_product_video_api(
        db,
        contact_sheet_path=str(contact_sheet),
        product_reference_path=str(product_path),
        execution_id=(
            f"{params.get('content_factory_media_manifest_sha256') or ''}:"
            f"task-{int(task.id)}:{source_sha256}"
        ),
        segment_context=segment_context,
    )
    review = {
        **dict(verdict),
        "source_sha256": source_sha256,
        "product_sha256": product_sha256,
        "contact_sheet_path": str(contact_sheet),
        "reviewed_at": _stage_now().isoformat(),
    }
    set_task_local_meta(task, provider_product_video_review=review)
    db.add(task)
    db.flush()
    if bool(review.get("blocking")):
        reasons = "; ".join(
            str(value) for value in list(review.get("blocking_reasons") or [])
            if str(value).strip()
        )[:700]
        raise ValueError(
            "CONTENT_FINAL_QUALITY_GATE_FAILED: "
            "CONTENT_PRODUCT_VIDEO_VISUAL_QA_FAILED_TASK_"
            f"{int(task.id)}: {reasons or 'blocking product mismatch'}"
        )
    return review


def _result_video_for_task(db, task: KieTask) -> tuple[Path, KieFile]:
    result_files = db.query(KieFile).filter(
        KieFile.task_id == task.id,
        KieFile.workspace_id == int(task.workspace_id),
        KieFile.kind.in_(("result", "result_watermark")),
    ).order_by(KieFile.id.asc()).all()
    selected = next((file for file in result_files if (get_local_path(file) or Path("/")).is_file()), None)
    if selected is None:
        raise ValueError(f"Video task #{task.id} has no downloaded result file")
    video_path = get_local_path(selected)
    if video_path is None:
        raise ValueError(f"Video task #{task.id} local path is missing")
    return video_path, selected


def _segment_release_quality_gate(
    db: Session,
    *,
    project: HermesContentFactoryProject,
    task: KieTask,
    source: Path,
) -> dict[str, Any]:
    """Evaluate a segment without rewriting its provider transport result.

    This is a creative/media evaluation boundary, not a provider boundary. A
    downloaded result stays successful in ``kie_api_tasks``; any bounded
    localized repair is driven by the independent evaluation evidence below.
    """

    params = dict(task.input_json or {})
    source_sha256 = _file_sha256(source)
    cached = dict(
        dict(get_task_local_meta(task) or {}).get(
            "segment_release_quality_gate"
        )
        or {}
    )
    if (
        str(cached.get("policy_version") or "")
        == SEGMENT_RELEASE_QUALITY_POLICY_VERSION
        and str(cached.get("source_sha256") or "") == source_sha256
        and str(cached.get("status") or "") == "PASS"
    ):
        return cached

    failures: list[str] = []
    expected_duration = float(params.get("seconds") or 0)
    actual_duration = _probe_video_duration_seconds(source)
    duration_tolerance = max(0.75, expected_duration * 0.12)
    if expected_duration <= 0:
        failures.append("missing expected segment duration")
    elif abs(actual_duration - expected_duration) > duration_tolerance:
        failures.append(
            "duration mismatch "
            f"expected={expected_duration:.2f}s actual={actual_duration:.2f}s"
        )

    width, height = _video_dimensions(source)
    expected_aspect = str(params.get("aspect_ratio") or "9:16")
    try:
        expected_ratio, normalized_aspect = _parse_aspect_ratio(expected_aspect)
    except ValueError as exc:
        expected_ratio = 0.0
        normalized_aspect = expected_aspect
        failures.append(str(exc))
    actual_ratio = width / max(1, height)
    if width <= 0 or height <= 0:
        failures.append(f"invalid dimensions {width}x{height}")
    elif expected_ratio and abs(actual_ratio - expected_ratio) > max(
        0.02,
        expected_ratio * 0.05,
    ):
        failures.append(
            f"aspect mismatch expected={normalized_aspect} actual={width}x{height}"
        )

    audio_required = str(
        params.get("content_factory_audio_mode") or "spoken"
    ).strip().lower() != "silent"
    has_audio = _video_has_audio_stream(source)
    if audio_required and not has_audio:
        failures.append("signed audio mode requires an audio stream")

    execution_review: dict[str, Any] | None = None
    review_diagnostics: list[str] = []
    try:
        execution_review = _review_provider_segment_execution(
            db,
            project=project,
            source=source,
            task=task,
        )
    except (RuntimeError, ValueError) as exc:
        diagnostic = str(exc)[:700]
        if "CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_" in diagnostic:
            failures.append(diagnostic)
        else:
            # A reviewer transport/model outage is not visual evidence.  It
            # must never spend another provider generation.  Persist it as an
            # advisory diagnostic so reconciliation can review the same local
            # file later without changing the downloaded transport truth.
            review_diagnostics.append(
                "segment execution reviewer unavailable: " + diagnostic
            )

    product_review: dict[str, Any] | None = None
    if bool(params.get("content_factory_product_anchor_required")):
        try:
            product_review = _review_provider_product_segment(
                db,
                project=project,
                source=source,
                task=task,
            )
        except (RuntimeError, ValueError) as exc:
            diagnostic = str(exc)[:700]
            if (
                "CONTENT_PRODUCT_VIDEO_VISUAL_QA_FAILED_TASK_" in diagnostic
                or "CONTENT_PRODUCT_VIDEO_REVIEW_AUTHORITY_MISSING_TASK_"
                in diagnostic
            ):
                failures.append(diagnostic)
            else:
                review_diagnostics.append(
                    "product identity reviewer unavailable: " + diagnostic
                )

    failure_code = "segment_release_quality_gate"
    if any(
        "CONTENT_PRODUCT_VIDEO_VISUAL_QA_FAILED_TASK_" in str(failure)
        for failure in failures
    ):
        failure_code = PRODUCT_VISUAL_QA_FAIL_CODE
    elif any(
        "CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_" in str(failure)
        for failure in failures
    ):
        failure_code = SEGMENT_EXECUTION_QA_FAIL_CODE
    failure_message = (
        "Segment failed the pre-dependency quality evaluation: "
        + "; ".join(failures)
        if failures
        else ""
    )
    report = {
        "policy_version": SEGMENT_RELEASE_QUALITY_POLICY_VERSION,
        "status": "FAIL" if failures else "PASS",
        "blocking": bool(failures),
        "failure_code": failure_code if failures else None,
        "source_sha256": source_sha256,
        "expected_duration_seconds": expected_duration,
        "actual_duration_seconds": actual_duration,
        "width": width,
        "height": height,
        "expected_aspect_ratio": normalized_aspect,
        "actual_aspect_ratio": actual_ratio,
        "audio_required": audio_required,
        "has_audio": has_audio,
        "product_review_status": (
            str(dict(product_review or {}).get("status") or "") or None
        ),
        "execution_review_status": (
            str(dict(execution_review or {}).get("status") or "") or None
        ),
        "review_diagnostics": review_diagnostics,
        "failures": failures,
        "checked_at": _stage_now().isoformat(),
    }
    set_task_local_meta(task, segment_release_quality_gate=report)
    if failures:
        _set_content_quality_incident(
            task,
            code=failure_code,
            message=failure_message,
            evidence=report,
        )
    else:
        set_task_local_meta(task, content_quality_incident=None)
    if isinstance(db, Session) and int(getattr(project, "id", 0) or 0) > 0:
        record_content_evaluation(
            db,
            project=project,
            task=task,
            evaluation_kind="segment_release",
            policy_version=SEGMENT_RELEASE_QUALITY_POLICY_VERSION,
            status=("repair_required" if failures else "passed"),
            blocking=bool(failures),
            input_sha256=source_sha256,
            evidence=report,
        )
    db.add(task)
    db.flush()
    return report


def _extract_segment_last_frame(source: Path, target: Path) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    result = subprocess.run(
        [
            FFMPEG_BIN, "-hide_banner", "-loglevel", "error", "-y",
            "-sseof", "-0.08", "-i", str(source), "-frames:v", "1", str(target),
        ],
        check=False,
        capture_output=True,
        text=True,
        timeout=120,
    )
    if result.returncode != 0 or not target.is_file() or target.stat().st_size < 1024:
        raise RuntimeError(f"Could not extract continuity frame: {(result.stderr or result.stdout or '')[:500]}")
    target.chmod(0o664)


def _compatible_chained_reference_route(
    db,
    task: KieTask,
    references: list[dict[str, Any]],
    *,
    product_required: bool,
) -> tuple[list[dict[str, Any]], KieApiKey | None]:
    """Choose the richest subset on an enabled route in priority order."""
    params = dict(task.input_json or {})
    meta = dict(get_task_local_meta(task) or {})
    excluded_key_ids = {
        int(value)
        for value in list(meta.get("attempted_provider_key_ids") or [])
        if str(value).strip().isdigit()
    }
    mandatory = [
        ref
        for ref in references
        if bool(ref.get("is_continuity_frame"))
        or (product_required and bool(ref.get("is_product_anchor")))
    ]
    optional = [ref for ref in references if ref not in mandatory]
    candidates: list[list[dict[str, Any]]] = []
    for optional_count in range(len(optional), -1, -1):
        for selected in combinations(optional, optional_count):
            selected_ids = {id(ref) for ref in selected}
            candidate = [
                ref for ref in references
                if ref in mandatory or id(ref) in selected_ids
            ]
            if candidate not in candidates:
                candidates.append(candidate)

    for candidate in candidates:
        try:
            key = resolve_video_model_key(
                db,
                model_id=str(params.get("model") or task.model or ""),
                reference_count=len(candidate),
                reference_video_count=len(list(params.get("reference_video_file_paths") or [])),
                aspect_ratio=str(params.get("aspect_ratio") or ""),
                reference_mode=str(
                    params.get("video_frame_mode")
                    or params.get("reference_mode")
                    or "reference"
                ),
                duration=int(params.get("seconds") or params.get("duration") or 0) or None,
                resolution=str(params.get("resolution") or "") or None,
                exclude_key_ids=excluded_key_ids,
            )
        except (TypeError, ValueError):
            continue
        return candidate, key
    return references, None


def _release_ready_segment_dependencies(
    db,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    state = dict(project.state_json or {})
    blocked_asset_ids = _blocked_reference_asset_ids(state)
    groups = json.loads(json.dumps(list(state.get("ai_video_groups") or []), ensure_ascii=False))
    task_by_id = {int(task.id): task for task in tasks}
    released: list[KieTask] = []
    superseded: list[KieTask] = []
    policy = _video_model_policy(project)
    reference_limit = max(2, min(7, int(policy.get("reference_limit") or 7)))
    continuity_dir = (
        CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}"
        / project.project_key / "generated" / "continuity_frames"
    )

    if _configured_video_generation_mode(project) == "text_to_video":
        # Recover tasks created by an older worker which inferred an Omni
        # first-frame dependency from segment_index alone.  T2V owns a strict
        # zero-reference contract, so release all such rows independently and
        # delete any stale reference ledger before provider submission.
        for group in groups:
            for segment in list(group.get("segments") or []):
                current_task = task_by_id.get(
                    int(dict(segment).get("task_id") or 0)
                )
                if (
                    current_task is None
                    or str(current_task.state or "").lower()
                    != "waiting_dependency"
                ):
                    continue
                params = dict(current_task.input_json or {})
                params.update({
                    "content_factory_video_generation_mode": "text_to_video",
                    "content_factory_dependency_task_id": None,
                    "content_factory_continuity_dependency": "independent",
                    "content_factory_first_frame": False,
                    "content_factory_product_render_mode": "text_only",
                    "content_factory_reference_manifest": [],
                    "reference_file_paths": [],
                    "reference_video_file_paths": [],
                    "reference_images": [],
                    "reference_videos": [],
                    "images": [],
                })
                current_task.input_json = params
                current_task.state = "queued_local"
                current_task.fail_code = None
                current_task.fail_msg = None
                set_task_local_meta(
                    current_task,
                    submit_enqueued_at=datetime.now(timezone.utc).isoformat(),
                )
                db.query(KieFile).filter(
                    KieFile.task_id == int(current_task.id),
                    KieFile.workspace_id == int(project.workspace_id),
                    KieFile.kind.in_((
                        "reference_upload",
                        "reference_video_upload",
                    )),
                ).delete(synchronize_session=False)
                segment["dependency_task_id"] = None
                segment["dependency_status"] = "ready"
                segment["continuity_dependency"] = "independent"
                segment["reference_indices"] = []
                segment["reference_names"] = []
                segment["reference_bindings"] = []
                segment["reference_video_names"] = []
                segment["product_anchor_names"] = []
                segment["product_render_mode"] = "text_only"
                db.add(current_task)
                released.append(current_task)
        if released:
            state["ai_video_groups"] = groups
            state["ai_video_dependency_released_at"] = (
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            )
            project.state_json = state
            db.add(project)
            db.commit()
            for task in released:
                submit_and_poll_ai_video_task.apply_async(
                    kwargs={
                        "workspace_id": int(project.workspace_id),
                        "local_task_id": int(task.id),
                        "interval_seconds": int(
                            settings.BANDIANWA_POLL_INTERVAL_SECONDS
                        ),
                        "timeout_seconds": int(
                            settings.BANDIANWA_POLL_TIMEOUT_SECONDS
                        ),
                    },
                    queue=production_video_queue(task),
                )
        return [int(task.id) for task in released]

    for group in groups:
        segments = sorted(list(group.get("segments") or []), key=lambda item: int(item.get("segment_index") or 0))
        if _media_group_source_is_superseded(db, project, dict(group)):
            for segment in segments:
                stale_task = task_by_id.get(int(segment.get("task_id") or 0))
                if stale_task is None or str(stale_task.state or "").lower() not in {
                    "queued_local",
                    "waiting_dependency",
                }:
                    continue
                stale_task.state = "failed"
                stale_task.fail_code = CONTENT_FACTORY_VARIANT_SUPERSEDED_CODE
                stale_task.fail_msg = (
                    "Source VIDEO_PROMPTS stage was superseded before provider submission."
                )
                set_task_local_meta(
                    stale_task,
                    superseded_at=datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                    authority_rejected_reason="source_stage_not_authoritative",
                )
                db.add(stale_task)
                superseded.append(stale_task)
            continue
        for position in range(1, len(segments)):
            previous_segment = segments[position - 1]
            current_segment = segments[position]
            previous_task = task_by_id.get(int(previous_segment.get("task_id") or 0))
            current_task = task_by_id.get(int(current_segment.get("task_id") or 0))
            if previous_task is None or current_task is None:
                continue
            if str(current_task.state or "").lower() != "waiting_dependency":
                continue
            if str(previous_task.state or "").lower() != "success":
                continue

            previous_video, _result_file = _result_video_for_task(db, previous_task)
            release_quality = _segment_release_quality_gate(
                db,
                project=project,
                task=previous_task,
                source=previous_video,
            )
            if str(release_quality.get("status") or "") != "PASS":
                previous_segment["dependency_status"] = (
                    "blocked_by_segment_quality_gate"
                )
                retry_task_ids = _retry_failed_video_segments(
                    db,
                    project,
                    [previous_task],
                )
                if retry_task_ids:
                    # The retry transaction replaced the predecessor pointer.
                    # Returning prevents this stale ``groups`` snapshot from
                    # overwriting that replacement during dependency release.
                    return retry_task_ids
                quality_state = dict(project.state_json or {})
                quality_state.update({
                    "pause_reason_code": FINAL_VIDEO_QUALITY_RECOVERY_REASON,
                    "automatic_quality_paused_at": _stage_now().isoformat(),
                    "final_video_quality_failure": {
                        "at": _stage_now().isoformat(),
                        "message": "segment dependency quality retry budget exhausted",
                        "task_ids": [int(previous_task.id)],
                        "release_quality": release_quality,
                    },
                    "ai_video_wait_task_id": None,
                })
                project.state_json = quality_state
                project.status = "paused"
                project.last_error = (
                    "该片段已完成供应商生成和本地下载，但独立质量评估未通过，"
                    "且本轮局部重做预算已用尽；系统将冷却后自动换策略继续。"
                )
                db.add(project)
                db.commit()
                return []
            video_index = int(group.get("video_index") or 0)
            previous_index = int(previous_segment.get("segment_index") or position)
            continuity_path = continuity_dir / f"video-{video_index:02d}-segment-{previous_index:02d}-last.png"
            _extract_segment_last_frame(previous_video, continuity_path)

            params = dict(current_task.input_json or {})
            if _configured_video_generation_mode(project) != "video_to_video":
                params["reference_video_file_paths"] = []
                params["content_factory_reference_video_count"] = 0
                db.query(KieFile).filter(
                    KieFile.task_id == int(current_task.id),
                    KieFile.workspace_id == int(project.workspace_id),
                    KieFile.kind == "reference_video_upload",
                ).delete(synchronize_session=False)
            original_refs = [
                dict(ref) for ref in list(params.get("reference_file_paths") or [])
                if not bool(ref.get("is_continuity_frame"))
                and int(ref.get("asset_id") or 0) not in blocked_asset_ids
            ]
            product_required = bool(params.get("content_factory_product_required"))
            reference_slots = max(1, reference_limit - 1)
            retained_refs = original_refs[:reference_slots]
            exact_product_ref = next((ref for ref in original_refs if bool(ref.get("is_product_anchor"))), None)
            if product_required and exact_product_ref is not None and exact_product_ref not in retained_refs:
                retained_refs[-1] = exact_product_ref
            original_refs = retained_refs
            continuity_ref = {
                "path": str(continuity_path),
                "role": "continuity_frame",
                "index": 0,
                "asset_id": 0,
                "filename": continuity_path.name,
                "size_bytes": continuity_path.stat().st_size,
                "description": "Exact final frame of the immediately preceding segment",
                "content_type": "image/png",
                "semantic_roles": ["character_anchor", "scene_anchor", "action_anchor"],
                "is_product_anchor": False,
                "is_continuity_frame": True,
            }
            chained_refs = [continuity_ref, *original_refs]
            previous_meta = dict(get_task_local_meta(previous_task) or {})
            current_meta = dict(get_task_local_meta(current_task) or {})
            inherited_quota_key_ids = {
                int(value)
                for value in list(previous_meta.get("provider_quota_failed_key_ids") or [])
                if str(value).strip().isdigit()
            }
            attempted_key_ids = {
                int(value)
                for value in list(current_meta.get("attempted_provider_key_ids") or [])
                if str(value).strip().isdigit()
            }
            if inherited_quota_key_ids:
                attempted_key_ids.update(inherited_quota_key_ids)
                set_task_local_meta(
                    current_task,
                    attempted_provider_key_ids=sorted(attempted_key_ids),
                    provider_quota_failed_key_ids=sorted(
                        inherited_quota_key_ids.union({
                            int(value)
                            for value in list(current_meta.get("provider_quota_failed_key_ids") or [])
                            if str(value).strip().isdigit()
                        })
                    ),
                    inherited_provider_quota_from_task_id=int(previous_task.id),
                )
            chained_refs, compatible_key = _compatible_chained_reference_route(
                db,
                current_task,
                chained_refs,
                product_required=product_required,
            )
            if compatible_key is not None and int(compatible_key.id) != int(current_task.key_id):
                prior_key_id = int(current_task.key_id)
                prior_provider = str(params.get("service_provider") or "auto")
                current_task.key_id = int(compatible_key.id)
                params["service_provider"] = str(compatible_key.provider_key)
                params["routing_failover_from"] = prior_provider
                set_task_local_meta(
                    current_task,
                    active_provider=str(compatible_key.provider_key),
                    active_provider_key_id=int(compatible_key.id),
                    routing_failover_from_key_id=prior_key_id,
                    continuity_route_selected_at=datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                )
            required_promotion = str(params.get("content_factory_required_promotion") or "").strip()
            exact_script_locked = bool(
                params.get("content_factory_exact_script_locked")
            )
            base_prompt = str(
                params.get("content_factory_base_prompt")
                or params.get("prompt")
                or ""
            ).strip()
            if not exact_script_locked:
                base_prompt = _provider_safe_base_prompt(
                    base_prompt,
                    confirmed_promotion=required_promotion,
                )
            if required_promotion and not exact_script_locked:
                base_prompt = _ensure_prompt_required_promotion(
                    base_prompt,
                    required_promotion,
                    str(params.get("content_factory_video_language") or _configured_video_language(project)),
                )
            if product_required and not exact_script_locked:
                base_prompt = _ensure_prompt_conversion_block(
                    base_prompt,
                    project,
                    language=str(params.get("content_factory_video_language") or _configured_video_language(project)),
                    promotion=required_promotion,
                    final_segment=True,
                )
            base_prompt += (
                " CONTINUATION RULE: this segment starts at the exact instant after the preceding segment. "
                "Preserve the same people, face, body, wardrobe, room, camera side, lighting, product state, and emotional momentum."
            )
            provider_safe_retry = bool(params.get("content_factory_provider_safe_retry")) or bool(blocked_asset_ids)
            prompt = _omni_reference_prompt(
                base_prompt,
                chained_refs,
                product_required=product_required,
                first_frame=True,
                provider_safe_retry=provider_safe_retry,
            )
            params.update({
                "prompt": prompt,
                "reference_file_paths": chained_refs,
                "content_factory_base_prompt": base_prompt,
                "content_factory_first_frame": True,
                "content_factory_provider_safe_retry": provider_safe_retry,
                "content_factory_prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
                "content_factory_prompt_hash": hashlib.sha256(str(prompt).encode("utf-8")).hexdigest(),
                "content_factory_project_id": int(project.id),
                "content_factory_project_key": project.project_key,
                "content_factory_variant_index": int(video_index),
                "content_factory_video_index": int(video_index),
                "content_factory_segment_index": int(current_segment.get("segment_index") or position + 1),
                "content_factory_dependency_task_id": int(previous_task.id),
                "content_factory_dependency_released_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            })
            # Dependency release changes the exact paid-provider packet after
            # the original VIDEO_PROMPTS compilation.  Re-run the same
            # semantic validation and stamp the hash of this final prompt at
            # the last mutation boundary.  Otherwise the AI-video worker
            # correctly rejects our own continuity rewrite as an unvalidated
            # late mutation before I/O.
            _validate_and_stamp_provider_prompt(
                params,
                source_prompt=base_prompt,
                actual_prompt=prompt,
            )
            current_task.input_json = params
            current_task.state = "queued_local"
            current_task.fail_code = None
            current_task.fail_msg = None
            set_task_local_meta(
                current_task,
                dependency_failed_task_id=None,
                dependency_failed_at=None,
                continuity_source_task_id=int(previous_task.id),
                continuity_frame_path=str(continuity_path),
                dependency_released_at=datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                content_factory_project_id=int(project.id),
                content_factory_project_key=project.project_key,
                content_factory_variant_index=int(video_index),
                content_factory_video_index=int(video_index),
                content_factory_segment_index=int(current_segment.get("segment_index") or position + 1),
                submit_enqueued_at=datetime.now(timezone.utc).isoformat(),
            )
            db.query(KieFile).filter(
                KieFile.task_id == int(current_task.id),
                KieFile.workspace_id == int(project.workspace_id),
                KieFile.kind == "reference_upload",
            ).delete(synchronize_session=False)
            for ref_position, ref in enumerate(chained_refs, 1):
                alias = "<FIRST_FRAME>" if ref_position == 1 else f"<IMAGE_REF_{ref_position - 2}>"
                db.add(KieFile(
                    workspace_id=project.workspace_id,
                    key_id=current_task.key_id,
                    task_id=current_task.id,
                    file_url=ref["path"],
                    kind="reference_upload",
                    mime_type=ref["content_type"],
                    size_bytes=ref["size_bytes"],
                    meta_json={
                        "filename": ref["filename"],
                        "source": "hermes_content_factory",
                        "reference_index": int(ref.get("index") or 0),
                        "asset_id": int(ref.get("asset_id") or 0),
                        "asset_role": ref.get("role"),
                        "semantic_roles": list(ref.get("semantic_roles") or []),
                        "omni_alias": alias,
                        "is_product_anchor": bool(ref.get("is_product_anchor")),
                        "is_continuity_frame": bool(ref.get("is_continuity_frame")),
                        "video_index": video_index,
                        "segment_index": int(current_segment.get("segment_index") or position + 1),
                        "resolution": params.get("resolution"),
                        "language": params.get("content_factory_video_language"),
                    },
                ))
            current_segment["dependency_task_id"] = int(previous_task.id)
            current_segment["dependency_status"] = "released"
            current_segment["continuity_frame"] = str(continuity_path)
            current_segment["reference_bindings"] = [
                {
                    "alias": "<FIRST_FRAME>" if index == 1 else f"<IMAGE_REF_{index - 2}>",
                    "asset_id": int(ref.get("asset_id") or 0),
                    "filename": ref["filename"],
                    "semantic_roles": list(ref.get("semantic_roles") or []),
                    "is_product_anchor": bool(ref.get("is_product_anchor")),
                    "is_continuity_frame": bool(ref.get("is_continuity_frame")),
                }
                for index, ref in enumerate(chained_refs, 1)
            ]
            released.append(current_task)

    if not released:
        if superseded:
            db.commit()
        return []
    state["ai_video_groups"] = groups
    state["ai_video_dependency_released_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    project.state_json = state
    db.add(project)
    db.commit()
    for task in released:
        submit_and_poll_ai_video_task.apply_async(
            kwargs={
                "workspace_id": int(project.workspace_id),
                "local_task_id": int(task.id),
                "interval_seconds": int(settings.BANDIANWA_POLL_INTERVAL_SECONDS),
                "timeout_seconds": int(settings.BANDIANWA_POLL_TIMEOUT_SECONDS),
            },
            queue=production_video_queue(task),
        )
    return [int(task.id) for task in released]


def _failed_video_dependency_still_has_recovery(
    project: HermesContentFactoryProject,
    dependency: KieTask,
) -> bool:
    """Return whether a failed root segment still owns a bounded recovery.

    Provider-cycle retries intentionally wait for a cooldown.  During that
    window the predecessor row is terminal at the provider boundary, but the
    content-factory chain is not terminal: a replacement task attempt will be
    created and its successors restored.  Retry accounting is scoped by
    ``video_index:segment_index`` so one variant can never consume another
    variant's budget.
    """
    # dependency_failed is produced only after the predecessor's own bounded
    # recovery is exhausted.  Treating that synthetic terminal code as a new
    # retryable provider failure creates an endless A -> B -> C wait chain.
    if str(dependency.fail_code or "").strip().lower() == "dependency_failed":
        return False
    if not _content_factory_retryable_video_failure(dependency):
        return False
    config = dict(project.config_json or {})
    default_limit = max(
        0,
        min(3, int(config.get("content_factory_video_retry_limit") or 2)),
    )
    if default_limit <= 0:
        return False
    params = dict(dependency.input_json or {})
    video_index = int(
        params.get("content_factory_video_index")
        or params.get("content_factory_variant_index")
        or 0
    )
    segment_index = int(params.get("content_factory_segment_index") or 0)
    if video_index <= 0 or segment_index <= 0:
        return False
    retry_key = f"{video_index}:{segment_index}"
    state = dict(project.state_json or {})
    retry_limit = default_limit
    for group in list(state.get("ai_video_groups") or []):
        if int(dict(group or {}).get("video_index") or 0) != video_index:
            continue
        configured_limit = dict(group or {}).get(
            "provider_retry_budget_per_segment"
        )
        if configured_limit is not None:
            retry_limit = max(0, min(3, int(configured_limit)))
        break
    if retry_limit <= 0:
        return False
    retry_counts = dict(state.get("ai_video_segment_retry_counts") or {})
    current_count = int(retry_counts.get(retry_key) or 0)
    if current_count < retry_limit:
        return True
    recovery_generations = dict(
        state.get("ai_video_exhausted_cooldown_retry_generations") or {}
    )
    # One final provider-priority cycle is available after the exhausted
    # cooldown.  Once that generation has been recorded and fails, the chain
    # is genuinely unreleasable.
    return retry_key not in recovery_generations


def _fail_unreleasable_segment_dependencies(
    db,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    task_by_id = {int(task.id): task for task in tasks}
    failed_ids: list[int] = []
    # Repeat to a fixed point so a chain is terminalized correctly regardless
    # of query order (A failed -> B dependency_failed -> C waiting on B).
    for _pass in range(max(1, len(tasks))):
        changed = False
        for task in tasks:
            if str(task.state or "").lower() != "waiting_dependency":
                continue
            params = dict(task.input_json or {})
            dependency_id = params.get("content_factory_dependency_task_id")
            if not str(dependency_id or "").strip().isdigit():
                dependency_id = dict(get_task_local_meta(task) or {}).get(
                    "dependency_task_id"
                )
            if not str(dependency_id or "").strip().isdigit():
                continue
            dependency_id = int(dependency_id)
            dependency = task_by_id.get(dependency_id)
            if dependency is None:
                scoped_dependency = _scoped_content_video_tasks(
                    db,
                    project,
                    [dependency_id],
                )
                dependency = scoped_dependency[0] if scoped_dependency else None
                if dependency is not None:
                    task_by_id[int(dependency.id)] = dependency
            dependency_params = (
                dict(dependency.input_json or {}) if dependency else {}
            )
            if (
                dependency is None
                or int(
                    dependency_params.get("content_factory_project_id") or 0
                )
                != int(project.id)
                or not _is_failed_video_task(dependency)
            ):
                continue
            if _failed_video_dependency_still_has_recovery(
                project,
                dependency,
            ):
                # A provider-cycle cooldown is not retry exhaustion.  Keep the
                # chained segment dormant until its predecessor is retried;
                # the retry path will release it with the predecessor's
                # authoritative final frame.
                continue
            task.state = "failed"
            task.fail_code = "dependency_failed"
            task.fail_msg = (
                f"Previous segment task #{dependency_id} failed after retry threshold; "
                "this chained segment cannot be generated safely."
            )
            set_task_local_meta(
                task,
                dependency_failed_task_id=dependency_id,
                dependency_failed_at=(
                    datetime.now(timezone.utc)
                    .replace(tzinfo=None)
                    .isoformat()
                ),
            )
            db.add(task)
            failed_ids.append(int(task.id))
            changed = True
        if not changed:
            break
    if failed_ids:
        state = dict(project.state_json or {})
        failed_set = set(failed_ids)
        state["ai_video_pending_task_ids"] = [
            int(value)
            for value in list(state.get("ai_video_pending_task_ids") or [])
            if str(value).strip().isdigit() and int(value) not in failed_set
        ]
        state["ai_video_failed_task_ids"] = sorted({
            *{
                int(value)
                for value in list(state.get("ai_video_failed_task_ids") or [])
                if str(value).strip().isdigit()
            },
            *failed_set,
        })
        state["ai_video_dependency_terminalized_at"] = _stage_now().isoformat()
        project.state_json = state
        db.add(project)
        db.flush()
    return failed_ids


def _bridge_video_assets(db, project: HermesContentFactoryProject, video_assets: list[HermesContentFactoryAsset]) -> list[HermesContentFactoryAsset]:
    bridge_dir = BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key
    bridge_dir.mkdir(parents=True, exist_ok=True)
    ready: list[HermesContentFactoryAsset] = []
    for index, video_asset in enumerate(sorted(video_assets, key=lambda item: int(item.id or 0)), 1):
        video_path = Path(video_asset.file_path)
        if not video_path.is_file():
            continue
        video_name = video_asset.original_name or f"video-{index}{video_path.suffix.lower() or '.mp4'}"
        bridge_video = bridge_dir / video_name
        if not bridge_video.exists() or bridge_video.stat().st_size != video_path.stat().st_size:
            shutil.copy2(video_path, bridge_video)
        bridge_video.chmod(0o644)
        video_asset.original_name = video_name
        video_asset.size_bytes = video_path.stat().st_size
        video_asset.meta_json = {
            **dict(video_asset.meta_json or {}),
            "bridge_path": str(bridge_video),
            "browser_inbox_relative": f"workspace_{project.workspace_id}/{project.project_key}/{video_name}",
        }
        ready.append(video_asset)
    db.flush()
    return ready


def _prepare_video_assets_from_tasks(db, project: HermesContentFactoryProject, tasks: list[KieTask]) -> list[HermesContentFactoryAsset]:
    generated_dir = (
        CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}"
        / project.project_key / "generated" / "final_videos"
    )
    generated_dir.mkdir(parents=True, exist_ok=True)
    assets: list[HermesContentFactoryAsset] = []
    for index, task in enumerate(tasks, 1):
        if str(task.state or "").lower() != "success":
            continue
        source, selected = _result_video_for_task(db, task)
        params = dict(task.input_json or {})
        stem = _safe_file_stem(str(params.get("content_factory_final_name_base") or f"{project.project_key}-{task.id}-{index}"))
        target = generated_dir / f"{stem}{source.suffix.lower() or '.mp4'}"
        if not target.exists() or target.stat().st_size != source.stat().st_size:
            shutil.copy2(source, target)
        target.chmod(0o664)
        asset = db.query(HermesContentFactoryAsset).filter_by(
            project_id=project.id, kind="video", file_path=str(target)
        ).order_by(HermesContentFactoryAsset.id.asc()).first()
        meta = {
            "kie_task_id": int(task.id),
            "kie_file_id": int(selected.id),
            "source_video": str(source),
            "remote_url": selected.download_url or selected.file_url,
            "video_index": int(params.get("content_factory_video_index") or index),
            "resolution": params.get("resolution") or params.get("size"),
            "language": params.get("content_factory_video_language"),
        }
        if asset is None:
            asset = HermesContentFactoryAsset(
                project_id=project.id, workspace_id=project.workspace_id, user_id=project.user_id,
                stage="VIDEO_PROMPTS", kind="video", original_name=target.name,
                file_path=str(target), mime_type=mimetypes.guess_type(target.name)[0] or "video/mp4",
                size_bytes=target.stat().st_size, meta_json=meta,
            )
            db.add(asset)
        else:
            asset.original_name = target.name
            asset.size_bytes = target.stat().st_size
            asset.meta_json = {**dict(asset.meta_json or {}), **meta}
        assets.append(asset)
    db.flush()
    return _bridge_video_assets(db, project, assets)


def _concat_videos(segment_paths: list[Path], target: Path) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    expected_duration = sum(
        _probe_video_duration_seconds(path) for path in segment_paths
    )
    list_path = target.with_suffix(".concat.txt")
    list_text = "\n".join(f"file '{str(path).replace(chr(39), chr(39) + chr(92) + chr(39) + chr(39))}'" for path in segment_paths)
    list_path.write_text(list_text + "\n", encoding="utf-8")
    commands = [
        [FFMPEG_BIN, "-y", "-f", "concat", "-safe", "0", "-i", str(list_path), "-c", "copy", "-movflags", "+faststart", str(target)],
        [
            FFMPEG_BIN, "-y", "-f", "concat", "-safe", "0", "-i", str(list_path),
            "-c:v", "libx264", "-pix_fmt", "yuv420p", "-preset", "veryfast", "-crf", "20",
            "-c:a", "aac", "-b:a", "128k", "-movflags", "+faststart", str(target),
        ],
    ]
    last_error = None
    for command in commands:
        result = subprocess.run(command, check=False, capture_output=True, text=True, timeout=1200)
        actual_duration = (
            _probe_video_duration_seconds(target)
            if result.returncode == 0
            and target.is_file()
            and target.stat().st_size > 1024
            else 0.0
        )
        duration_tolerance = max(0.5, expected_duration * 0.015)
        if (
            result.returncode == 0
            and target.is_file()
            and target.stat().st_size > 1024
            and abs(actual_duration - expected_duration) <= duration_tolerance
        ):
            target.chmod(0o664)
            try:
                list_path.unlink(missing_ok=True)
            except OSError:
                pass
            return
        last_error = (
            (result.stderr or result.stdout or "").strip()
            or (
                "composed duration mismatch: "
                f"expected={expected_duration:.3f}s actual={actual_duration:.3f}s"
            )
        )
        try:
            target.unlink(missing_ok=True)
        except OSError:
            pass
    raise RuntimeError(f"Could not compose final video: {str(last_error or '')[:1000]}")


def _ass_timestamp(value: Any) -> str:
    seconds = max(0.0, float(value or 0.0))
    centiseconds = int(round(seconds * 100.0))
    hours, remainder = divmod(centiseconds, 360000)
    minutes, remainder = divmod(remainder, 6000)
    whole_seconds, fraction = divmod(remainder, 100)
    return f"{hours}:{minutes:02d}:{whole_seconds:02d}.{fraction:02d}"


def _ass_overlay_text(value: Any, *, line_width: int = 28) -> str:
    """Escape and wrap one Director-owned display line for ASS rendering."""
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    words = text.split(" ")
    rows: list[str] = []
    current = ""
    for word in words:
        candidate = word if not current else f"{current} {word}"
        if current and len(candidate) > max(12, int(line_width)):
            rows.append(current)
            current = word
        else:
            current = candidate
    if current:
        rows.append(current)
    escaped_rows = [
        row.replace("\\", r"\\")
        .replace("{", r"\{")
        .replace("}", r"\}")
        for row in rows
    ]
    return r"\N".join(escaped_rows)


def _write_local_overlay_ass(
    display_lines: list[dict[str, Any]],
    target: Path,
    *,
    width: int,
    height: int,
    duration: float,
) -> bool:
    placements = {
        "top_safe": "TopSafe",
        "center": "Center",
        "lower_third": "LowerThird",
        "bottom_safe": "BottomSafe",
        "bottom_right": "BottomRight",
    }
    font_size = max(32, int(round(int(height) * 0.036)))
    margin_h = max(36, int(round(int(width) * 0.07)))
    margin_v = max(52, int(round(int(height) * 0.055)))
    events: list[str] = []
    for item in display_lines:
        if not isinstance(item, dict):
            continue
        presentation = dict(item.get("overlay_presentation") or {})
        max_lines = max(1, min(4, int(presentation.get("max_lines") or 2)))
        line_width = max(18, min(42, int(round(56 / max_lines))))
        text = _ass_overlay_text(item.get("line"), line_width=line_width)
        if not text:
            continue
        start = min(max(0.0, float(item.get("start_seconds") or 0.0)), duration)
        end = min(max(start + 0.05, float(item.get("end_seconds") or duration)), duration)
        if end <= start:
            continue
        base_style = placements.get(
            str(presentation.get("placement") or "").strip().lower(),
            "LowerThird",
        )
        background = str(presentation.get("background") or "box").lower()
        if background not in {"none", "shadow", "box", "band"}:
            background = "box"
        if background == "band":
            band_height = max(font_size * 2, int(round(height * 0.075)))
            if base_style == "TopSafe":
                band_top = max(0, margin_v - int(font_size * 0.45))
                band_bottom = min(height, band_top + band_height)
            elif base_style in {"BottomSafe", "BottomRight"}:
                band_bottom = min(height, height - margin_v + int(font_size * 0.45))
                band_top = max(0, band_bottom - band_height)
            elif base_style == "LowerThird":
                band_bottom = min(
                    height,
                    height - max(margin_v, int(height * 0.20))
                    + int(font_size * 0.45),
                )
                band_top = max(0, band_bottom - band_height)
            else:
                band_top = max(0, int((height - band_height) / 2))
                band_bottom = min(height, band_top + band_height)
            drawing = (
                r"{\an7\pos(0,0)\p1\1c&H000000&\alpha&H50&}"
                f"m 0 {band_top} l {width} {band_top} "
                f"l {width} {band_bottom} l 0 {band_bottom}"
            )
            events.append(
                "Dialogue: 0,"
                f"{_ass_timestamp(start)},{_ass_timestamp(end)},CenterNone,,0,0,0,,"
                + drawing
            )
            background = "shadow"
        style = f"{base_style}{background.title()}"
        emphasis = str(presentation.get("emphasis") or "standard").lower()
        scale = {"quiet": 0.90, "standard": 1.0, "strong": 1.12}.get(
            emphasis, 1.0,
        )
        override = f"{{\\fs{max(24, int(round(int(height) * 0.036 * scale)))}}}"
        events.append(
            "Dialogue: 1,"
            f"{_ass_timestamp(start)},{_ass_timestamp(end)},{style},,0,0,0,,{override}{text}"
        )
    if not events:
        return False
    placement_styles = {
        "TopSafe": (8, margin_v),
        "Center": (5, margin_v),
        "LowerThird": (2, max(margin_v, int(height * 0.20))),
        "BottomSafe": (2, margin_v),
        "BottomRight": (3, margin_v),
    }
    background_styles = {
        "None": (1, 0, 0, "&HFF000000"),
        "Shadow": (1, 2, 2, "&HFF000000"),
        "Box": (3, 2, 0, "&H78000000"),
    }
    style_rows = []
    for placement_name, (alignment, vertical_margin) in placement_styles.items():
        for background_name, (
            border_style,
            outline,
            shadow,
            back_colour,
        ) in background_styles.items():
            style_rows.append(
                f"Style: {placement_name}{background_name},Arial,{font_size},"
                "&H00FFFFFF,&H00FFFFFF,&H00101010,"
                f"{back_colour},1,0,0,0,100,100,0,0,{border_style},"
                f"{outline},{shadow},{alignment},{margin_h},{margin_h},"
                f"{vertical_margin},1"
            )
    body = "\n".join([
        "[Script Info]",
        "ScriptType: v4.00+",
        f"PlayResX: {int(width)}",
        f"PlayResY: {int(height)}",
        "WrapStyle: 2",
        "ScaledBorderAndShadow: yes",
        "",
        "[V4+ Styles]",
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
        *style_rows,
        "",
        "[Events]",
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text",
        *events,
        "",
    ])
    target.write_text(body, encoding="utf-8")
    return True


def _video_dimensions(source: Path) -> tuple[int, int]:
    result = subprocess.run(
        [
            FFPROBE_BIN, "-v", "error", "-select_streams", "v:0",
            "-show_entries", "stream=width,height", "-of", "csv=s=x:p=0",
            str(source),
        ],
        check=True,
        capture_output=True,
        text=True,
        timeout=30,
    )
    raw = result.stdout.strip().lower()
    match = re.fullmatch(r"(\d+)x(\d+)", raw)
    if not match:
        raise RuntimeError(f"Could not probe video dimensions for {source}: {raw}")
    return int(match.group(1)), int(match.group(2))














def _local_postprocess_segment(
    source: Path,
    target: Path,
    *,
    segment: dict[str, Any],
    task: KieTask,
    db: Session | None = None,
) -> dict[str, Any]:
    """Normalize one provider clip and apply only Director-owned display copy.

    Product pixels are never pasted in local post-production.  A
    product-visible segment must prove that the authoritative uploaded package
    was submitted to the provider as a product anchor; the media model owns
    natural lighting, perspective, contact, motion, and occlusion.
    """
    display_lines = [
        dict(item)
        for item in list(segment.get("display_lines") or [])
        if isinstance(item, dict)
    ]
    product_required = bool(segment.get("product_anchor_required"))
    params = dict(task.input_json or {})
    product_refs = [
        dict(item)
        for item in list(params.get("reference_file_paths") or [])
        if isinstance(item, dict) and bool(item.get("is_product_anchor"))
    ]
    readable_product_ref = next(
        (
            item
            for item in product_refs
            if Path(str(item.get("path") or "")).is_file()
            and Path(str(item.get("path") or "")).stat().st_size > 1024
        ),
        None,
    )
    product_render_mode = str(
        params.get("content_factory_product_render_mode")
        or segment.get("product_render_mode")
        or "provider_reference"
    ).strip()
    if product_required and readable_product_ref is None:
        raise RuntimeError(
            "Authoritative product reference required, but segment task "
            f"#{int(task.id)} did not submit a readable product anchor"
        )
    if product_required and product_render_mode != "provider_reference":
        raise RuntimeError(
            "Unsupported product render mode for new media: "
            f"{product_render_mode or 'missing'}"
        )

    width, height = _video_dimensions(source)
    duration = _probe_video_duration_seconds(source)
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="hermes-cf-post-") as temporary:
        local_voiceover_rows = [
            dict(item)
            for item in list(segment.get("dialogue_lines") or [])
            if isinstance(item, dict)
            and str(item.get("delivery_mode") or "spoken").strip().lower()
            == "spoken"
            and str(item.get("delivery_method") or "provider_dialogue")
            .strip()
            .lower()
            == "local_voiceover"
            and str(item.get("line") or "").strip()
        ]
        voiceover_evidence: dict[str, Any] | None = None
        voiceover_path: Path | None = None
        if local_voiceover_rows:
            voice_lock = next(
                (
                    dict(item)
                    for item in list(segment.get("voice_lock") or [])
                    if isinstance(item, dict)
                ),
                {},
            )
            voiceover_path = Path(temporary) / "local-voiceover.mp3"
            voiceover_evidence = _synthesize_local_voiceover(
                " ".join(
                    str(item.get("line") or "").strip()
                    for item in local_voiceover_rows
                ),
                voiceover_path,
                voice_lock=voice_lock,
                target_duration_seconds=duration,
            )
        ass_path = Path(temporary) / "director-copy.ass"
        has_overlay = _write_local_overlay_ass(
            display_lines,
            ass_path,
            width=width,
            height=height,
            duration=duration,
        )
        filters = [f"ass={ass_path}"] if has_overlay else []
        # Providers may return 24, 25, or 30 fps. Normalize every segment
        # before concat so a planned 40-second video stays 40 seconds.
        filters.append("fps=30")
        command = [
            FFMPEG_BIN, "-hide_banner", "-loglevel", "error", "-y",
            "-i", str(source),
        ]
        if voiceover_path is not None:
            command.extend(["-i", str(voiceover_path)])
        command.extend([
            "-vf", ",".join(filters),
            "-map", "0:v:0",
        ])
        if voiceover_path is not None:
            source_voice_duration = float(
                dict(voiceover_evidence or {}).get("source_duration_seconds")
                or 0
            )
            tempo = max(
                1.0,
                source_voice_duration / max(0.25, duration - 0.1),
            )
            command.extend([
                "-filter_complex",
                (
                    f"[1:a]atempo={tempo:.6f},apad,"
                    f"atrim=0:{duration:.6f},"
                    "loudnorm=I=-16:TP=-1.5:LRA=11[local_voice]"
                ),
                "-map", "[local_voice]",
            ])
        else:
            command.extend(["-map", "0:a?"])
        command.extend([
            "-c:v", "libx264", "-pix_fmt", "yuv420p", "-preset", "veryfast",
            "-crf", "18", "-c:a", "aac", "-b:a", "128k",
            "-movflags", "+faststart", str(target),
        ])
        result = subprocess.run(
            command,
            check=False,
            capture_output=True,
            text=True,
            timeout=1200,
        )
        if (
            result.returncode != 0
            or not target.is_file()
            or target.stat().st_size < 1024
        ):
            raise RuntimeError(
                "Could not apply local Content Factory post-production: "
                + str(result.stderr or result.stdout or "")[:1000]
            )
    target.chmod(0o664)
    product_path = (
        Path(str(readable_product_ref.get("path") or ""))
        if readable_product_ref is not None
        else None
    )
    result = {
        "path": str(target),
        "processed": True,
        "policy_version": LOCAL_POSTPRODUCTION_POLICY_VERSION,
        "normalized_frame_rate": 30,
        "display_line_ids": [
            str(item.get("line_id") or "")
            for item in display_lines
            if str(item.get("line_id") or "").strip()
        ],
        "product_render_mode": product_render_mode,
        "product_reference_submitted": bool(readable_product_ref),
        "product_reference_asset_id": (
            int(readable_product_ref.get("asset_id") or 0)
            if readable_product_ref is not None
            else None
        ),
        "product_reference_source": str(product_path or "") or None,
        "product_reference_sha256": (
            _file_sha256(product_path)
            if product_path is not None
            else None
        ),
        # Historical keys remain explicit and false so old audit readers do
        # not mistake provider-rendered product for a local pixel insert.
        "authoritative_product_insert": False,
        "authoritative_product_composites": [],
        "authoritative_product_source": None,
        "authoritative_product_sha256": None,
    }
    if voiceover_evidence is not None:
        if db is None:
            raise RuntimeError(
                "Local voiceover semantic review requires a database session"
            )
        expected_voiceover = " ".join(
            str(item.get("line") or "").strip()
            for item in local_voiceover_rows
        )
        spoken_review = _review_spoken_copy_with_asr(
            db,
            expected_voiceover,
            target,
            execution_id=f"task-{int(task.id)}-local-voiceover",
        )
        if str(spoken_review.get("status") or "").lower() != "pass":
            raise RuntimeError(
                "LOCAL_VOICEOVER_QA_FAILED: "
                + json.dumps(spoken_review, ensure_ascii=False)[:1000]
            )
        result["local_voiceover"] = {
            **voiceover_evidence,
            "line_ids": [
                str(item.get("line_id") or "")
                for item in local_voiceover_rows
            ],
            "spoken_copy_review": spoken_review,
        }
    return result


def _local_voice_name(voice_lock: dict[str, Any]) -> str:
    gender = str(voice_lock.get("gender") or "female").strip().lower()
    accent = " ".join(
        str(voice_lock.get(key) or "")
        for key in ("accent", "locale", "language")
    ).lower()
    if any(token in accent for token in ("zh", "chinese", "mandarin", "中文")):
        return "zh-CN-YunxiNeural" if gender == "male" else "zh-CN-XiaoxiaoNeural"
    return "en-US-GuyNeural" if gender == "male" else "en-US-JennyNeural"


def _synthesize_local_voiceover(
    text: str,
    target: Path,
    *,
    voice_lock: dict[str, Any],
    target_duration_seconds: float,
) -> dict[str, Any]:
    """Render exact signed narration with one deterministic neural voice."""
    normalized = re.sub(r"\s+", " ", str(text or "")).strip()
    if not normalized:
        raise ValueError("local voiceover text is empty")
    voice = _local_voice_name(voice_lock)
    try:
        speech_rate = float(voice_lock.get("speech_rate") or 150)
    except (TypeError, ValueError):
        speech_rate = 150.0
    rate_percent = int(round((speech_rate / 150.0 - 1.0) * 100.0))
    rate_percent = max(-25, min(35, rate_percent))
    rate = f"{rate_percent:+d}%"
    target.parent.mkdir(parents=True, exist_ok=True)
    code = (
        "import asyncio,edge_tts,sys;"
        "asyncio.run(edge_tts.Communicate(sys.argv[1],sys.argv[2],"
        "rate=sys.argv[3]).save(sys.argv[4]))"
    )
    last_error = ""
    for attempt in range(1, 4):
        completed = subprocess.run(
            [
                "/opt/gmv/python3.13/bin/python",
                "-c",
                code,
                normalized,
                voice,
                rate,
                str(target),
            ],
            check=False,
            capture_output=True,
            text=True,
            timeout=120,
        )
        if (
            completed.returncode == 0
            and target.is_file()
            and target.stat().st_size >= 1024
        ):
            break
        last_error = str(completed.stderr or completed.stdout or "")[:1000]
        target.unlink(missing_ok=True)
        if attempt < 3:
            time.sleep(float(attempt))
    else:
        raise RuntimeError(
            "Neural local voiceover generation failed after 3 attempts: "
            + last_error
        )
    source_duration = _probe_video_duration_seconds(target)
    if source_duration <= 0:
        raise RuntimeError("Neural local voiceover has no measurable duration")
    return {
        "backend": "edge_neural_tts",
        "policy_version": LOCAL_POSTPRODUCTION_POLICY_VERSION,
        "voice": voice,
        "rate": rate,
        "source_duration_seconds": round(source_duration, 3),
        "target_duration_seconds": round(float(target_duration_seconds), 3),
        "text_sha256": hashlib.sha256(normalized.encode("utf-8")).hexdigest(),
    }
def _task_remote_result_urls(db, task: KieTask) -> list[str]:
    files = db.query(KieFile).filter(
        KieFile.task_id == int(task.id),
        KieFile.workspace_id == int(task.workspace_id),
        KieFile.kind.in_(("result", "result_watermark")),
    ).order_by(KieFile.id.asc()).all()
    urls: list[str] = []
    for file in files:
        url = str(file.download_url or file.file_url or "").strip()
        if url and url not in urls:
            urls.append(url)
    return urls


def _is_terminal_video_task(task: KieTask) -> bool:
    return str(task.state or "").lower() in _TERMINAL_VIDEO_TASK_STATES


def _is_failed_video_task(task: KieTask) -> bool:
    return str(task.state or "").lower() in {"failed", "error", "timeout"}


def _normalize_spoken_copy_tokens(value: str) -> list[str]:
    """Normalize universal notation while preserving project-specific words.

    Brand, product and ingredient spellings intentionally remain untouched.
    Transcript mismatches are evidence for the multimodal semantic reviewer,
    not a reason to embed campaign-specific pronunciation aliases here.
    """
    text = (
        str(value or "")
        .lower()
        .replace("&", " and ")
        # Whisper may serialize the spoken word "percent" as the symbol in
        # a numeric phrase ("1%"), while the signed copy stores "1 percent".
        # Expand only the symbol; the quantity and the percent token remain
        # mandatory in the exact-copy comparison.
        .replace("%", " percent ")
    )
    aliases = {
        # This is a platform-name orthography, not project or product copy.
        r"\btick\s+tock\b": "tiktok",
        r"\b0\b": "zero",
        r"\b1\b": "one",
        r"\b2\b": "two",
        r"\b3\b": "three",
        r"\b4\b": "four",
        r"\b5\b": "five",
        r"\b6\b": "six",
        r"\b7\b": "seven",
        r"\b8\b": "eight",
        r"\b9\b": "nine",
        r"\b10\b": "ten",
    }
    for pattern, replacement in aliases.items():
        text = re.sub(pattern, replacement, text)
    return re.findall(r"[a-z0-9]+", text)


def _spoken_copy_comparison(expected: str, observed: str) -> dict[str, Any]:
    expected_tokens = _normalize_spoken_copy_tokens(expected)
    observed_tokens = _normalize_spoken_copy_tokens(observed)
    remaining: dict[str, int] = {}
    for token in observed_tokens:
        remaining[token] = remaining.get(token, 0) + 1
    missing: list[str] = []
    for token in expected_tokens:
        available = remaining.get(token, 0)
        if available > 0:
            remaining[token] = available - 1
        else:
            missing.append(token)
    return {
        "status": "pass" if expected_tokens and not missing else "fail",
        "expected_token_count": len(expected_tokens),
        "observed_token_count": len(observed_tokens),
        "missing_tokens": missing,
    }


def _transcribe_spoken_copy_external(
    video_path: Path,
    *,
    model_name: str = "small",
) -> str:
    """Run Whisper out of process so model memory cannot accumulate in Hermes.

    Content production and transcription use separate resource envelopes.  A
    short-lived subprocess preserves that boundary while still making the
    downloaded provider audio part of the release contract.
    """
    code = (
        "import json,os,sys,whisper;"
        "m=whisper.load_model(sys.argv[2],device='cpu');"
        "r=m.transcribe(sys.argv[1],language='en',fp16=False,temperature=0);"
        "print(json.dumps({'text':str(r.get('text') or '').strip()}))"
    )
    env = dict(os.environ)
    env.setdefault("HOME", "/opt/gmv")
    env.setdefault("OMP_NUM_THREADS", "2")
    completed = subprocess.run(
        [
            "/opt/gmv/python3.13/bin/python",
            "-c",
            code,
            str(video_path),
            str(model_name or "small"),
        ],
        check=True,
        capture_output=True,
        text=True,
        timeout=180,
        env=env,
    )
    payload = json.loads(str(completed.stdout or "").strip().splitlines()[-1])
    return str(payload.get("text") or "").strip()


def _review_spoken_copy_with_asr(
    db: Session,
    expected: str,
    video_path: Path,
    *,
    execution_id: str,
) -> dict[str, Any]:
    """Collect ASR candidates and let the multimodal role judge semantics."""
    primary_observed = _transcribe_spoken_copy_external(
        video_path,
        model_name="small",
    )
    primary_review = _spoken_copy_comparison(expected, primary_observed)
    adjudicated_observed = ""
    adjudicated_review: dict[str, Any] = {}
    if str(primary_review.get("status") or "").lower() != "pass":
        adjudicated_observed = _transcribe_spoken_copy_external(
            video_path,
            model_name="medium",
        )
        adjudicated_review = _spoken_copy_comparison(
            expected,
            adjudicated_observed,
        )
    with tempfile.TemporaryDirectory(prefix="hermes-cf-copy-review-") as temp:
        contact_sheet = Path(temp) / "spoken-copy-contact-sheet.jpg"
        _segment_execution_contact_sheet(video_path, contact_sheet)
        semantic_review = review_spoken_copy_semantics_api(
            db,
            contact_sheet_path=str(contact_sheet),
            expected_text=expected,
            primary_transcript=primary_observed,
            adjudicated_transcript=adjudicated_observed or None,
            transcript_diagnostics={
                "primary": primary_review,
                "adjudicated": adjudicated_review or None,
            },
            execution_id=execution_id,
        )
    return {
        **semantic_review,
        "observed_text": adjudicated_observed or primary_observed,
        "asr_model": "medium" if adjudicated_observed else "small",
        "primary_observed_text": primary_observed,
        "primary_missing_tokens": list(
            primary_review.get("missing_tokens") or []
        ),
        "asr_diagnostics": {
            "primary": primary_review,
            "adjudicated": adjudicated_review or None,
        },
    }


def _invalidate_successful_segments_with_missing_spoken_copy(
    db,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    """Record missing spoken copy without corrupting transport state."""
    invalid_ids: list[int] = []
    for task in tasks:
        if str(task.state or "").lower() != "success":
            continue
        params = dict(task.input_json or {})
        dialogue_rows = [
            dict(item)
            for item in list(params.get("content_factory_dialogue_lines") or [])
            if isinstance(item, dict)
            and str(item.get("delivery_mode") or "spoken").strip().lower()
            == "spoken"
            and str(item.get("line") or "").strip()
            and str(item.get("delivery_method") or "provider_dialogue")
            .strip()
            .lower()
            != "local_voiceover"
        ]
        if not dialogue_rows:
            if _uses_only_local_voiceover(params):
                set_task_local_meta(
                    task,
                    spoken_copy_review={
                        "status": "deferred_to_local_postproduction",
                        "policy_version": SPOKEN_COPY_QA_POLICY_VERSION,
                        "reviewed_at": _stage_now().isoformat(),
                    },
                )
                db.add(task)
            continue
        expected = " ".join(
            str(item.get("line") or "").strip() for item in dialogue_rows
        )
        try:
            video_path, _selected = _result_video_for_task(db, task)
            source_sha256 = _file_sha256(video_path)
            local_meta = dict(get_task_local_meta(task) or {})
            cached = dict(local_meta.get("spoken_copy_review") or {})
            if (
                str(cached.get("policy_version") or "")
                == SPOKEN_COPY_QA_POLICY_VERSION
                and str(cached.get("source_sha256") or "") == source_sha256
            ):
                review = cached
            else:
                comparison = _review_spoken_copy_with_asr(
                    db,
                    expected,
                    video_path,
                    execution_id=f"task-{int(task.id)}-provider-dialogue",
                )
                review = {
                    **comparison,
                    "policy_version": SPOKEN_COPY_QA_POLICY_VERSION,
                    "source_sha256": source_sha256,
                    "expected_text": expected,
                    "reviewed_at": _stage_now().isoformat(),
                }
                set_task_local_meta(task, spoken_copy_review=review)
            if str(review.get("status") or "").lower() == "pass":
                db.add(task)
                continue
        except Exception as exc:
            review = {
                "status": "error",
                "policy_version": SPOKEN_COPY_QA_POLICY_VERSION,
                "reviewed_at": _stage_now().isoformat(),
                "error": str(exc)[:500],
            }
            set_task_local_meta(task, spoken_copy_review=review)
        if str(review.get("status") or "").lower() == "error":
            # Reviewer availability is never evidence that paid media is bad.
            record_content_evaluation(
                db,
                project=project,
                task=task,
                evaluation_kind="spoken_copy",
                policy_version=SPOKEN_COPY_QA_POLICY_VERSION,
                status="review_error",
                blocking=False,
                input_sha256=_quality_evaluation_sha256(task, review),
                evidence=review,
            )
            db.add(task)
            continue
        missing = ", ".join(
            str(value) for value in list(review.get("missing_tokens") or [])[:8]
        )
        message = (
            "Hermes rejected this downloaded segment because its spoken audio "
            "did not preserve the signed dialogue"
            + (f"; missing: {missing}" if missing else "; ASR verification failed")
        )
        _set_content_quality_incident(
            task,
            code=SPOKEN_COPY_FAIL_CODE,
            message=message,
            evidence=review,
        )
        record_content_evaluation(
            db,
            project=project,
            task=task,
            evaluation_kind="spoken_copy",
            policy_version=SPOKEN_COPY_QA_POLICY_VERSION,
            status="repair_required",
            blocking=True,
            input_sha256=_quality_evaluation_sha256(task, review),
            evidence=review,
        )
        db.add(task)
        invalid_ids.append(int(task.id))
    if invalid_ids:
        db.flush()
    return invalid_ids


def _content_task_nonspoken_dialogue_rows(task: KieTask) -> list[dict[str, Any]]:
    params = dict(task.input_json or {})
    display_rows = [
        dict(item)
        for item in list(params.get("content_factory_display_lines") or [])
        if isinstance(item, dict)
    ]
    display_ids = {
        str(item.get("line_id") or "").strip()
        for item in display_rows
        if str(item.get("line_id") or "").strip()
    }
    display_text = {
        str(item.get("line") or "").strip()
        for item in display_rows
        if str(item.get("line") or "").strip()
    }
    return [
        dict(item)
        for item in list(params.get("content_factory_dialogue_lines") or [])
        if isinstance(item, dict)
        and (
            str(item.get("delivery_mode") or "spoken").strip().lower()
            != "spoken"
            or (
                str(item.get("line_id") or "").strip()
                and str(item.get("line_id") or "").strip() in display_ids
            )
            or str(item.get("line") or "").strip() in display_text
        )
    ]


def _sanitize_content_task_copy_delivery(
    value: dict[str, Any],
) -> dict[str, Any]:
    """Repair a frozen local retry payload without changing approved copy.

    Only the transport classification is repaired: display lines stay in the
    local-overlay ledger and are removed from provider dialogue and its prompt.
    This lets a completed contaminated task be rejected and retried under the
    same bounded media manifest rather than counting a knowingly wrong video.
    """
    params = dict(value or {})
    dialogue = [
        dict(item)
        for item in list(params.get("content_factory_dialogue_lines") or [])
        if isinstance(item, dict)
    ]
    display_rows = [
        dict(item)
        for item in list(params.get("content_factory_display_lines") or [])
        if isinstance(item, dict)
    ]
    display_ids = {
        str(item.get("line_id") or "").strip()
        for item in display_rows
        if str(item.get("line_id") or "").strip()
    }
    display_text = {
        str(item.get("line") or "").strip()
        for item in display_rows
        if str(item.get("line") or "").strip()
    }
    nonspoken = [
        item
        for item in dialogue
        if (
            str(item.get("delivery_mode") or "spoken").strip().lower()
            != "spoken"
            or (
                str(item.get("line_id") or "").strip()
                and str(item.get("line_id") or "").strip() in display_ids
            )
            or str(item.get("line") or "").strip() in display_text
        )
    ]
    if not nonspoken:
        return params
    params["content_factory_dialogue_lines"] = [
        item
        for item in dialogue
        if item not in nonspoken
    ]
    for key in ("content_factory_base_prompt", "prompt"):
        prompt = str(params.get(key) or "")
        for item in nonspoken:
            line = str(item.get("line") or "").strip()
            if not line:
                continue
            speaker = str(
                item.get("speaker") or item.get("speaker_id") or ""
            ).strip()
            rendered = f"{speaker}: '{line}'" if speaker else f"'{line}'"
            prompt = prompt.replace(f" | {rendered}", "")
            prompt = prompt.replace(f"{rendered} | ", "")
            prompt = prompt.replace(f"Dialogue: {rendered}\n", "")
            prompt = prompt.replace(f"Dialogue: {rendered}", "")
        params[key] = prompt
    params["content_factory_prompt_hash"] = hashlib.sha256(
        str(params.get("prompt") or "").encode("utf-8")
    ).hexdigest()
    params["content_factory_copy_delivery_repaired"] = True
    return params


def _invalidate_successful_segments_with_nonspoken_dialogue(
    db,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    """Record a signed copy-lane defect independently of provider state."""
    invalid_ids: list[int] = []
    for task in tasks:
        if str(task.state or "").lower() != "success":
            continue
        rows = _content_task_nonspoken_dialogue_rows(task)
        if not rows:
            continue
        message = (
            "Hermes rejected this completed segment before composition because "
            "display-only copy was submitted as provider dialogue. A new "
            "task attempt will be created within the bounded budget."
        )
        evidence = {
            "line_ids": [
                str(item.get("line_id") or "")
                for item in rows
                if str(item.get("line_id") or "").strip()
            ],
        }
        _set_content_quality_incident(
            task,
            code="copy_delivery_invalid",
            message=message,
            evidence=evidence,
        )
        set_task_local_meta(
            task,
            copy_delivery_contract_rejected_at=_stage_now().isoformat(),
            copy_delivery_contract_rejected_line_ids=evidence["line_ids"],
        )
        record_content_evaluation(
            db,
            project=project,
            task=task,
            evaluation_kind="copy_delivery_contract",
            policy_version=LOCAL_POSTPRODUCTION_POLICY_VERSION,
            status="repair_required",
            blocking=True,
            input_sha256=_quality_evaluation_sha256(task, evidence),
            evidence=evidence,
        )
        db.add(task)
        invalid_ids.append(int(task.id))
    if invalid_ids:
        db.flush()
    return invalid_ids


def _successful_content_factory_task_missing_continuity(task: KieTask) -> bool:
    if str(task.state or "").lower() != "success":
        return False
    params = dict(task.input_json or {})
    if not str(params.get("content_factory_project_key") or "").strip():
        return False
    try:
        segment_index = int(params.get("content_factory_segment_index") or 0)
    except (TypeError, ValueError):
        segment_index = 0
    if segment_index <= 1:
        return False

    # Only execution packets that explicitly require a previous-frame input
    # belong to this guard.  Older Omni packets predate the boolean contract,
    # so a concrete dependency task id remains a safe legacy signal.  The
    # Director's narrative ``previous_segment`` label alone is not sufficient:
    # Seedance uses references plus the multimodal prompt to anchor independent
    # shots and must not be invalidated for a frame it was never meant to get.
    requires_previous_frame = bool(
        params.get("content_factory_requires_previous_segment_frame")
    )
    try:
        legacy_dependency_task_id = int(
            params.get("content_factory_dependency_task_id") or 0
        )
    except (TypeError, ValueError):
        legacy_dependency_task_id = 0
    if not requires_previous_frame and legacy_dependency_task_id <= 0:
        return False
    references = [
        ref for ref in list(params.get("reference_file_paths") or [])
        if isinstance(ref, dict)
    ]
    has_continuity_reference = any(bool(ref.get("is_continuity_frame")) for ref in references)
    return not bool(params.get("content_factory_first_frame")) or not has_continuity_reference


def _invalidate_successful_segments_missing_continuity(
    db,
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
) -> list[int]:
    invalid_ids: list[int] = []
    for task in tasks:
        if not _successful_content_factory_task_missing_continuity(task):
            continue
        message = (
            "Hermes rejected this completed segment before composition because its required "
            "previous-segment continuity frame was not submitted. A new task attempt will "
            "be released from its dependency and retried."
        )
        evidence = {
            "reason": "missing_previous_segment_first_frame",
            "task_id": int(task.id),
        }
        _set_content_quality_incident(
            task,
            code="content_factory_continuity_frame_missing",
            message=message,
            evidence=evidence,
        )
        set_task_local_meta(
            task,
            continuity_contract_rejected_at=datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            continuity_contract_rejected_reason="missing_previous_segment_first_frame",
        )
        record_content_evaluation(
            db,
            project=project,
            task=task,
            evaluation_kind="continuity_contract",
            policy_version=VIDEO_PROMPT_POLICY_VERSION,
            status="repair_required",
            blocking=True,
            input_sha256=_quality_evaluation_sha256(task, evidence),
            evidence=evidence,
        )
        db.add(task)
        invalid_ids.append(int(task.id))
    if invalid_ids:
        db.flush()
    return invalid_ids


def _video_has_audio_stream(source: Path) -> bool:
    result = subprocess.run(
        [
            FFPROBE_BIN, "-v", "error", "-select_streams", "a:0",
            "-show_entries", "stream=index", "-of", "csv=p=0",
            str(source),
        ],
        check=False,
        capture_output=True,
        text=True,
        timeout=30,
    )
    return result.returncode == 0 and bool(result.stdout.strip())


def _parse_aspect_ratio(value: Any) -> tuple[float, str]:
    text = str(value or "").strip().lower().replace("x", ":")
    parts = text.split(":", 1)
    if len(parts) != 2:
        raise ValueError(f"invalid aspect ratio {value!r}")
    width = float(parts[0])
    height = float(parts[1])
    if width <= 0 or height <= 0:
        raise ValueError(f"invalid aspect ratio {value!r}")
    return width / height, f"{parts[0]}:{parts[1]}"


def _voice_acoustic_fingerprint(source: Path) -> dict[str, Any]:
    """Measure voiced pitch without trusting provider metadata.

    This is deliberately a continuity signal, not a demographic classifier.
    It catches the large acoustic jump produced when independent provider
    segments switch speakers while tolerating ordinary intonation changes.
    """
    process = subprocess.run(
        [
            FFMPEG_BIN,
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            str(source),
            "-vn",
            "-ac",
            "1",
            "-ar",
            "16000",
            "-f",
            "f32le",
            "-",
        ],
        check=False,
        capture_output=True,
        timeout=45,
    )
    if process.returncode != 0 or len(process.stdout) < 640 * 4:
        return {
            "status": "unavailable",
            "reason": process.stderr.decode("utf-8", errors="ignore")[:500],
        }
    samples = np.frombuffer(process.stdout, dtype="<f4").astype(np.float64)
    sample_rate = 16000
    frame_size = 640
    frame_step = 320
    candidates: list[float] = []
    strengths: list[float] = []
    for start in range(0, max(0, len(samples) - frame_size), frame_step):
        frame = samples[start:start + frame_size]
        frame = frame - float(np.mean(frame))
        rms = float(np.sqrt(np.mean(frame * frame)))
        if rms < 0.015:
            continue
        windowed = frame * np.hanning(frame_size)
        correlation = np.correlate(windowed, windowed, mode="full")[
            frame_size - 1:
        ]
        if not len(correlation) or correlation[0] <= 0:
            continue
        minimum_lag = int(sample_rate / 350)
        maximum_lag = int(sample_rate / 70)
        search = correlation[minimum_lag:maximum_lag + 1]
        if not len(search):
            continue
        lag = minimum_lag + int(np.argmax(search))
        strength = float(correlation[lag] / correlation[0])
        if strength < 0.25:
            continue
        candidates.append(float(sample_rate / lag))
        strengths.append(strength)
    if len(candidates) < 12:
        return {
            "status": "insufficient_voice",
            "voiced_frame_count": len(candidates),
        }
    pitch = np.asarray(candidates, dtype=np.float64)
    return {
        "status": "measured",
        "voiced_frame_count": int(len(pitch)),
        "median_pitch_hz": round(float(np.median(pitch)), 2),
        "pitch_q25_hz": round(float(np.quantile(pitch, 0.25)), 2),
        "pitch_q75_hz": round(float(np.quantile(pitch, 0.75)), 2),
        "high_pitch_fraction": round(float(np.mean(pitch >= 165.0)), 4),
        "median_periodicity": round(float(np.median(strengths)), 4),
    }


def _voice_continuity_outliers(
    records: list[dict[str, Any]],
) -> dict[str, Any]:
    """Return task-level acoustic outliers for each signed speaker ID."""
    by_speaker: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        pitch = float(record.get("median_pitch_hz") or 0)
        speaker_id = str(record.get("speaker_id") or "").strip()
        if pitch <= 0 or not speaker_id:
            continue
        by_speaker.setdefault(speaker_id, []).append(dict(record))

    speaker_reports: list[dict[str, Any]] = []
    blocking_task_ids: set[int] = set()
    repair_by_task_id: dict[str, dict[str, Any]] = {}
    for speaker_id, rows in sorted(by_speaker.items()):
        if len(rows) < 2:
            continue
        pitches = np.asarray(
            [float(row["median_pitch_hz"]) for row in rows],
            dtype=np.float64,
        )
        target_pitch = float(np.median(pitches))
        pitch_ratio = np.maximum(
            pitches / max(target_pitch, 1.0),
            target_pitch / np.maximum(pitches, 1.0),
        )
        outlier_positions = [
            index
            for index, (pitch, ratio) in enumerate(zip(pitches, pitch_ratio))
            if ratio >= 1.45 and abs(float(pitch) - target_pitch) >= 45.0
        ]
        # With only two clips there is no majority reference.  A large split
        # still proves the same signed speaker changed, so both clips are
        # rejected instead of guessing which provider result was authoritative.
        if len(rows) == 2 and float(max(pitch_ratio)) >= 1.45:
            outlier_positions = [0, 1]
        expected_genders = {
            str(row.get("expected_gender") or "").strip().lower()
            for row in rows
            if str(row.get("expected_gender") or "").strip().lower()
            in {"female", "male", "androgynous"}
        }
        selected_gender = (
            next(iter(expected_genders))
            if len(expected_genders) == 1
            else (
                "female" if target_pitch >= 155.0
                else "male" if target_pitch <= 140.0
                else "androgynous"
            )
        )
        outlier_task_ids = [
            int(rows[index]["task_id"])
            for index in outlier_positions
        ]
        for task_id in outlier_task_ids:
            blocking_task_ids.add(task_id)
            repair_by_task_id[str(task_id)] = {
                "speaker_id": speaker_id,
                "gender": selected_gender,
                "target_pitch_hz": round(target_pitch, 2),
                "reason": "cross_segment_speaker_acoustic_outlier",
            }
        speaker_reports.append({
            "speaker_id": speaker_id,
            "segment_count": len(rows),
            "target_pitch_hz": round(target_pitch, 2),
            "selected_gender": selected_gender,
            "task_pitch_hz": {
                str(int(row["task_id"])): float(row["median_pitch_hz"])
                for row in rows
            },
            "blocking_task_ids": outlier_task_ids,
        })
    return {
        "policy_version": VOICE_CONTINUITY_QA_POLICY_VERSION,
        "status": "FAIL" if blocking_task_ids else "PASS",
        "blocking_task_ids": sorted(blocking_task_ids),
        "repair_by_task_id": repair_by_task_id,
        "speakers": speaker_reports,
    }


def _local_voiceover_identity_report(
    *,
    segments: list[dict[str, Any]],
    local_postproduction: list[dict[str, Any]],
) -> dict[str, Any] | None:
    """Verify the actual deterministic voice identity used after muxing.

    Provider clips are deliberately silent when the signed delivery method is
    ``local_voiceover``.  Inspecting their incidental/generated audio before
    post-production misclassified music or provider noise as a speaker change
    and triggered another paid video generation.  For deterministic local TTS,
    the backend voice identifier is the authoritative continuity signal.
    Return ``None`` when any spoken line is provider-owned so the acoustic
    fallback can still validate that workflow.
    """

    evidence_by_segment = {
        int(item.get("segment_index") or 0): dict(item)
        for item in local_postproduction
        if isinstance(item, dict)
    }
    identities_by_speaker: dict[str, set[str]] = {}
    records: list[dict[str, Any]] = []
    has_local_voiceover = False
    for segment in segments:
        spoken = [
            dict(item)
            for item in list(segment.get("dialogue_lines") or [])
            if isinstance(item, dict)
            and str(item.get("delivery_mode") or "spoken").strip().lower()
            == "spoken"
            and str(item.get("line") or "").strip()
        ]
        if not spoken:
            continue
        if any(
            str(item.get("delivery_method") or "provider_dialogue")
            .strip()
            .lower()
            != "local_voiceover"
            for item in spoken
        ):
            return None
        has_local_voiceover = True
        segment_index = int(segment.get("segment_index") or 0)
        local_voice = dict(
            evidence_by_segment.get(segment_index, {}).get("local_voiceover")
            or {}
        )
        voice_name = str(local_voice.get("voice") or "").strip()
        backend = str(local_voice.get("backend") or "").strip()
        speaker_ids = list(dict.fromkeys(
            str(item.get("speaker_id") or item.get("speaker") or "").strip()
            for item in spoken
            if str(item.get("speaker_id") or item.get("speaker") or "").strip()
        ))
        if len(speaker_ids) != 1 or not voice_name or not backend:
            return {
                "policy_version": VOICE_CONTINUITY_QA_POLICY_VERSION,
                "status": "FAIL",
                "blocking_task_ids": [
                    int(evidence_by_segment.get(segment_index, {}).get("task_id") or 0)
                ],
                "reason": "local_voiceover_identity_evidence_missing",
                "records": records,
            }
        speaker_id = speaker_ids[0]
        identity = f"{backend}:{voice_name}"
        identities_by_speaker.setdefault(speaker_id, set()).add(identity)
        records.append({
            "segment_index": segment_index,
            "task_id": int(
                evidence_by_segment.get(segment_index, {}).get("task_id") or 0
            ),
            "speaker_id": speaker_id,
            "backend": backend,
            "voice": voice_name,
            "identity": identity,
        })
    if not has_local_voiceover:
        return None
    mismatched_speakers = sorted(
        speaker_id
        for speaker_id, identities in identities_by_speaker.items()
        if len(identities) != 1
    )
    blocking_task_ids = sorted({
        int(item.get("task_id") or 0)
        for item in records
        if item.get("speaker_id") in mismatched_speakers
        and int(item.get("task_id") or 0) > 0
    })
    return {
        "policy_version": VOICE_CONTINUITY_QA_POLICY_VERSION,
        "status": "FAIL" if mismatched_speakers else "PASS",
        "verification_mode": "deterministic_local_voice_identity",
        "blocking_task_ids": blocking_task_ids,
        "mismatched_speakers": mismatched_speakers,
        "speaker_identities": {
            key: sorted(value)
            for key, value in sorted(identities_by_speaker.items())
        },
        "records": records,
    }


def _audit_segment_voice_continuity(
    db: Session,
    *,
    segments: list[dict[str, Any]],
    segment_paths: list[Path],
    source_task_ids: list[int],
    task_by_id: dict[int, KieTask],
) -> dict[str, Any]:
    records: list[dict[str, Any]] = []
    for segment, source, task_id in zip(
        segments,
        segment_paths,
        source_task_ids,
    ):
        dialogue = [
            dict(item)
            for item in list(segment.get("dialogue_lines") or [])
            if isinstance(item, dict) and str(item.get("line") or "").strip()
        ]
        speaker_ids = list(dict.fromkeys(
            str(item.get("speaker_id") or item.get("speaker") or "").strip()
            for item in dialogue
            if str(item.get("speaker_id") or item.get("speaker") or "").strip()
        ))
        if len(speaker_ids) != 1:
            continue
        voice_lock = next(
            (
                dict(item)
                for item in list(segment.get("voice_lock") or [])
                if isinstance(item, dict)
                and str(item.get("speaker_id") or "").strip()
                == speaker_ids[0]
            ),
            {},
        )
        task = task_by_id[int(task_id)]
        source_sha256 = _file_sha256(source)
        local_meta = dict(get_task_local_meta(task) or {})
        cached = dict(local_meta.get("voice_acoustic_fingerprint") or {})
        if (
            str(cached.get("policy_version") or "")
            == VOICE_CONTINUITY_QA_POLICY_VERSION
            and str(cached.get("source_sha256") or "") == source_sha256
        ):
            fingerprint = cached
        else:
            fingerprint = {
                **_voice_acoustic_fingerprint(source),
                "policy_version": VOICE_CONTINUITY_QA_POLICY_VERSION,
                "source_sha256": source_sha256,
                "measured_at": _stage_now().isoformat(),
            }
            set_task_local_meta(task, voice_acoustic_fingerprint=fingerprint)
            db.add(task)
            db.flush()
        if str(fingerprint.get("status") or "") != "measured":
            continue
        records.append({
            "task_id": int(task_id),
            "segment_index": int(segment.get("segment_index") or 0),
            "speaker_id": speaker_ids[0],
            "expected_gender": str(voice_lock.get("gender") or ""),
            **fingerprint,
        })
    report = _voice_continuity_outliers(records)
    report["records"] = records
    if report["blocking_task_ids"]:
        task_token = "_".join(
            str(value) for value in report["blocking_task_ids"]
        )
        raise ValueError(
            "CONTENT_FINAL_QUALITY_GATE_FAILED: "
            f"CONTENT_VOICE_CONTINUITY_QA_FAILED_TASKS_{task_token}: "
            + json.dumps(report, ensure_ascii=False, sort_keys=True)
        )
    return report


def _audit_composed_content_video(
    target: Path,
    *,
    group: dict[str, Any],
    segments: list[dict[str, Any]],
    local_postproduction: list[dict[str, Any]],
    source_diff: dict[str, Any] | None = None,
    intent_fidelity: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Fail closed before a local MP4 is counted as a completed video."""
    failures: list[str] = []
    normalized_source_diff = dict(source_diff or {})
    normalized_intent_fidelity = dict(intent_fidelity or {})
    if str(normalized_source_diff.get("status") or "").upper() == "FAIL":
        failures.extend(
            f"source contract: {item}"
            for item in list(normalized_source_diff.get("failures") or [])
        )
    if bool(normalized_intent_fidelity.get("blocking")) or str(
        normalized_intent_fidelity.get("status") or ""
    ).lower() == "fail":
        intent_reasons = [
            str(value)
            for value in list(
                normalized_intent_fidelity.get("blocking_reasons") or []
            )
            if str(value).strip()
        ]
        blocking_ids = list(
            normalized_intent_fidelity.get("blocking_requirement_ids") or []
        )
        failures.append(
            "CONTENT_FINAL_INTENT_QA_FAILED "
            + json.dumps(
                {
                    "policy_version": normalized_intent_fidelity.get(
                        "policy_version"
                    ),
                    "video_index": normalized_intent_fidelity.get(
                        "video_index"
                    ),
                    "blocking_requirement_ids": blocking_ids,
                    "blocking_reasons": intent_reasons[:8],
                    "repair_scope": normalized_intent_fidelity.get(
                        "repair_scope"
                    ),
                    "affected_segment_indices": list(
                        normalized_intent_fidelity.get(
                            "affected_segment_indices"
                        )
                        or []
                    ),
                    "affected_task_ids": list(
                        normalized_intent_fidelity.get("affected_task_ids")
                        or []
                    ),
                    "repair_instruction": str(
                        normalized_intent_fidelity.get(
                            "repair_instruction"
                        )
                        or ""
                    )[:1200],
                    "requirement_evidence": dict(
                        normalized_intent_fidelity.get(
                            "requirement_evidence"
                        )
                        or {}
                    ),
                    # These fields are internal evidence pointers, not a
                    # creative verdict.  The recovery supervisor must be able
                    # to inspect the exact pixels that produced the failure;
                    # dropping them here left a valid multimodal pause unable
                    # to choose a different repair layer after local retries
                    # were exhausted.
                    "result_sha256": str(
                        normalized_intent_fidelity.get("result_sha256") or ""
                    ),
                    "contact_sheet_path": str(
                        normalized_intent_fidelity.get("contact_sheet_path")
                        or ""
                    ),
                    "benchmark_contact_sheet_path": str(
                        normalized_intent_fidelity.get(
                            "benchmark_contact_sheet_path"
                        )
                        or ""
                    ),
                    "reviewed_at": str(
                        normalized_intent_fidelity.get("reviewed_at") or ""
                    ),
                },
                ensure_ascii=False,
                sort_keys=True,
            )
        )
    expected_duration = float(
        group.get("duration")
        or sum(float(item.get("duration") or 0) for item in segments)
    )
    actual_duration = _probe_video_duration_seconds(target)
    duration_tolerance = max(0.5, expected_duration * 0.015)
    if abs(actual_duration - expected_duration) > duration_tolerance:
        failures.append(
            "duration mismatch: "
            f"expected={expected_duration:.3f}s actual={actual_duration:.3f}s"
        )
    width, height = _video_dimensions(target)
    expected_aspect_ratio = str(group.get("aspect_ratio") or "9:16")
    try:
        expected_ratio, normalized_aspect_ratio = _parse_aspect_ratio(
            expected_aspect_ratio
        )
    except ValueError as exc:
        expected_ratio = 0.0
        normalized_aspect_ratio = expected_aspect_ratio
        failures.append(str(exc))
    actual_ratio = width / max(1, height)
    ratio_tolerance = max(0.015, expected_ratio * 0.03)
    if width <= 0 or height <= 0:
        failures.append(f"output dimensions are invalid: width={width} height={height}")
    elif expected_ratio > 0 and abs(actual_ratio - expected_ratio) > ratio_tolerance:
        failures.append(
            "output aspect ratio mismatch: "
            f"expected={normalized_aspect_ratio} actual={width}x{height}"
        )

    required_audio = any(
        str(item.get("audio_mode") or "spoken").lower() != "silent"
        for item in segments
    )
    has_audio = _video_has_audio_stream(target)
    if required_audio and not has_audio:
        failures.append("approved audio mode requires an audio stream")

    evidence_by_segment = {
        int(item.get("segment_index") or 0): dict(item)
        for item in local_postproduction
    }
    expected_display_ids: list[str] = []
    delivered_display_ids: list[str] = []
    media_manifest_frozen = bool(group.get("media_manifest_sha256"))
    product_segment_count = 0
    product_reference_count = 0
    for segment in segments:
        segment_index = int(segment.get("segment_index") or 0)
        evidence = evidence_by_segment.get(segment_index, {})
        display_lines = [
            dict(item)
            for item in list(segment.get("display_lines") or [])
            if isinstance(item, dict)
        ]
        expected_display_ids.extend(
            str(item.get("line_id") or "")
            for item in display_lines
            if str(item.get("line_id") or "").strip()
        )
        delivered_display_ids.extend(
            str(value)
            for value in list(evidence.get("display_line_ids") or [])
            if str(value).strip()
        )
        if media_manifest_frozen:
            missing_presentations = [
                str(item.get("line_id") or "")
                for item in display_lines
                if not isinstance(item.get("overlay_presentation"), dict)
            ]
            if missing_presentations:
                failures.append(
                    "display lines lack Director-owned placement: "
                    f"segment={segment_index} lines={missing_presentations}"
                )
        if str(segment.get("compile_source") or "") == (
            "signed_production_plan"
        ):
            execution_review = dict(
                evidence.get("segment_execution_review") or {}
            )
            if (
                str(execution_review.get("policy_version") or "")
                != SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
                or str(execution_review.get("status") or "").lower()
                != "pass"
                or bool(execution_review.get("blocking"))
            ):
                failures.append(
                    f"segment {segment_index} lacks passing signed visual execution review"
                )
        if not bool(segment.get("product_anchor_required")):
            continue
        product_segment_count += 1
        if str(evidence.get("product_render_mode") or "") != "provider_reference":
            failures.append(
                f"segment {segment_index} has invalid product render mode"
            )
        if not bool(evidence.get("product_reference_submitted")):
            failures.append(
                f"segment {segment_index} did not submit product authority"
            )
        else:
            product_reference_count += 1
        if not str(evidence.get("product_reference_sha256") or ""):
            failures.append(
                f"segment {segment_index} lacks product reference checksum"
            )
        if bool(evidence.get("authoritative_product_insert")):
            failures.append(
                f"segment {segment_index} used forbidden local product insert"
            )
        product_review = dict(
            evidence.get("provider_product_video_review") or {}
        )
        if (
            str(product_review.get("policy_version") or "")
            != PRODUCT_REFERENCE_VIDEO_REVIEW_POLICY_VERSION
            or str(product_review.get("status") or "").lower() != "pass"
            or bool(product_review.get("blocking"))
        ):
            failures.append(
                f"segment {segment_index} lacks passing provider product visual review"
            )
    if expected_display_ids != delivered_display_ids:
        failures.append(
            "display-copy delivery mismatch: "
            f"expected={expected_display_ids} delivered={delivered_display_ids}"
        )

    report = {
        "schema_version": "content-final-quality-v1",
        "status": "PASS" if not failures else "FAIL",
        "expected_duration_seconds": expected_duration,
        "actual_duration_seconds": actual_duration,
        "duration_tolerance_seconds": duration_tolerance,
        "width": width,
        "height": height,
        "expected_aspect_ratio": normalized_aspect_ratio,
        "actual_aspect_ratio": actual_ratio,
        "has_audio": has_audio,
        "audio_required": required_audio,
        "expected_display_line_ids": expected_display_ids,
        "delivered_display_line_ids": delivered_display_ids,
        "product_segment_count": product_segment_count,
        "product_reference_count": product_reference_count,
        "product_render_mode": "provider_reference",
        "media_manifest_sha256": group.get("media_manifest_sha256"),
        "intent_manifest_sha256": group.get("intent_manifest_sha256"),
        "source_transformation_diff": normalized_source_diff,
        "intent_fidelity": normalized_intent_fidelity,
        "failures": failures,
    }
    if failures:
        raise ValueError(
            "CONTENT_FINAL_QUALITY_GATE_FAILED: " + "; ".join(failures)
        )
    return report


def _source_transformation_quality_report(
    db,
    project: HermesContentFactoryProject,
    target: Path,
) -> dict[str, Any]:
    contract = _project_transformation_contract(project)
    fidelity = str(contract.get("fidelity") or "").strip().lower()
    source_media_reuse = str(
        contract.get("source_media_reuse") or ""
    ).strip().lower()
    exact_comparison = fidelity in {
        "exact",
        "exact_outside_authorized_changes",
    }
    originality_comparison = source_media_reuse == "forbidden"
    if not exact_comparison and not originality_comparison:
        return {}
    candidates = _benchmark_video_assets(
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == int(project.id),
            HermesContentFactoryAsset.workspace_id == int(project.workspace_id),
        )
        .order_by(HermesContentFactoryAsset.id.desc())
        .all()
    )
    source_asset = next(
        (
            item
            for item in candidates
            if Path(str(item.file_path or "")).is_file()
        ),
        None,
    )
    if source_asset is None:
        if originality_comparison and not exact_comparison:
            # A full-regeneration contract that forbids source-media reuse is
            # already protected by the project asset boundary when no local
            # benchmark video exists: no source pixels or audio were available
            # to any image/video provider.  Treat that media-level comparison
            # as satisfied by isolation, then let the separate final-intent
            # review enforce excluded story, character, prop, shot, UI, and
            # wording requirements.  Exact/local-edit contracts still fail
            # closed below because they cannot be verified without a source.
            return {
                "schema_version": "source-diff-v1",
                "status": "PASS",
                "comparison_mode": "asset_isolation_no_local_source",
                "source_media_available": False,
                "source_media_reuse": "forbidden",
                "media_reuse_possible": False,
                "failures": [],
            }
        return {
            "schema_version": "source-diff-v1",
            "status": "FAIL",
            "failures": [
                "authoritative source video is unavailable for comparison"
            ],
        }
    from app.services.hermes_agent.content_source_diff import (
        audit_bounded_source_edit,
        audit_regenerated_source_originality,
    )

    source_path = Path(str(source_asset.file_path))
    source_duration = _probe_video_duration_seconds(source_path)
    result_duration = _probe_video_duration_seconds(target)
    if exact_comparison:
        return audit_bounded_source_edit(
            source=source_path,
            result=target,
            contract=contract,
            source_duration_seconds=source_duration,
            result_duration_seconds=result_duration,
        )
    return audit_regenerated_source_originality(
        source=source_path,
        result=target,
        contract=contract,
        source_duration_seconds=source_duration,
        result_duration_seconds=result_duration,
    )


def _is_cross_deliverable_intent_requirement(
    requirement: dict[str, Any],
) -> bool:
    """Return whether evidence inherently depends on comparing outputs.

    This is driven by Producer's signed semantic type, not by requirement IDs,
    copy text, language, or a fixed requested video count.
    """

    ordinals = {
        int(value)
        for value in list(requirement.get("deliverable_ordinals") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    return (
        str(requirement.get("kind") or "").strip().lower()
        in {"differentiation", "objective"}
        and len(ordinals) > 1
    )


def _final_intent_fidelity_report(
    db: Session,
    project: HermesContentFactoryProject,
    target: Path,
    *,
    group: dict[str, Any],
    source_diff: dict[str, Any],
) -> dict[str, Any]:
    requirements = [
        dict(item)
        for item in list(group.get("intent_requirements") or [])
        if isinstance(item, dict)
    ]
    if not requirements:
        producer_manifest = dict(
            dict(
                dict(project.config_json or {}).get("producer_intent_spec")
                or {}
            ).get("intent_manifest")
            or {}
        )
        signed_requirements = [
            dict(item)
            for item in list(producer_manifest.get("requirements") or [])
            if isinstance(item, dict)
        ]
        if signed_requirements:
            return {
                "status": "fail",
                "blocking": True,
                "policy_version": "2026-07-28-final-intent-guardian-v1",
                "blocking_reasons": [
                    "The media group lost the signed Producer intent contract."
                ],
                "blocking_requirement_ids": [
                    str(item.get("requirement_id") or "").strip()
                    for item in signed_requirements
                    if str(item.get("requirement_id") or "").strip()
                ],
                "repair_scope": "contract_recovery",
                "repair_instruction": (
                    "Restore the signed VIDEO_PROMPTS intent contract before "
                    "accepting or regenerating any media."
                ),
            }
        return {
            "status": "pass",
            "blocking": False,
            "policy_version": "2026-07-28-final-intent-guardian-v1",
            "requirement_evidence": {},
            "note": "no signed intent requirements",
        }
    # A per-deliverable contact sheet can prove requirements that apply to
    # each output, but it cannot prove a relationship between several outputs.
    # Producer marks that relationship explicitly as ``kind=differentiation``
    # with more than one deliverable ordinal.  Sending such a series-level
    # contract to the one-video guardian caused a structurally impossible
    # verdict ("the other videos are missing") and paused production before
    # those videos were allowed to exist.  Keep the signed requirement in the
    # project contract, but defer its evidence review until the full requested
    # set is available.
    deferred_requirements = [
        item
        for item in requirements
        if _is_cross_deliverable_intent_requirement(item)
    ]
    deliverable_requirements = [
        item
        for item in requirements
        if not _is_cross_deliverable_intent_requirement(item)
    ]
    if not deliverable_requirements:
        return {
            "status": "pass",
            "blocking": False,
            "policy_version": FINAL_INTENT_REVIEW_POLICY_VERSION,
            "requirement_evidence": {},
            "deferred_cross_deliverable_requirement_ids": [
                str(item.get("requirement_id") or "").strip()
                for item in deferred_requirements
                if str(item.get("requirement_id") or "").strip()
            ],
            "note": "cross-deliverable requirements deferred until target completion",
        }
    review_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
        / "generated"
        / "final_intent_reviews"
    )
    result_sha256 = _file_sha256(target)
    result_sheet = review_dir / f"result-{result_sha256[:16]}.jpg"
    _segment_execution_contact_sheet(target, result_sheet)
    benchmark_sheet: Path | None = None
    transformation_contract = _project_transformation_contract(project)
    if transformation_contract:
        candidates = _benchmark_video_assets(
            db.query(HermesContentFactoryAsset)
            .filter(
                HermesContentFactoryAsset.project_id == int(project.id),
                HermesContentFactoryAsset.workspace_id == int(project.workspace_id),
            )
            .order_by(HermesContentFactoryAsset.id.desc())
            .all()
        )
        source_asset = next(
            (
                item
                for item in candidates
                if Path(str(item.file_path or "")).is_file()
            ),
            None,
        )
        if source_asset is not None:
            source_path = Path(str(source_asset.file_path))
            benchmark_sheet = review_dir / (
                f"benchmark-{_file_sha256(source_path)[:16]}.jpg"
            )
            _segment_execution_contact_sheet(source_path, benchmark_sheet)
    segment_contact_sheets: list[dict[str, Any]] = []
    segment_execution_evidence: list[dict[str, Any]] = []
    for position, segment in enumerate(
        list(group.get("segments") or [])[:128],
        1,
    ):
        if not isinstance(segment, dict):
            continue
        segment_index = int(segment.get("segment_index") or position)
        task_id = int(segment.get("task_id") or 0)
        spoken_copy_review: dict[str, Any] = {}
        task = db.get(KieTask, task_id) if task_id > 0 else None
        if task is not None:
            spoken_copy_review = dict(
                dict(get_task_local_meta(task) or {}).get(
                    "spoken_copy_review"
                )
                or {}
            )
            try:
                segment_path, _segment_file = _result_video_for_task(db, task)
                segment_sha256 = _file_sha256(segment_path)
                segment_sheet = review_dir / (
                    f"segment-{segment_index}-task-{task_id}-"
                    f"{segment_sha256[:16]}.jpg"
                )
                _segment_execution_contact_sheet(
                    segment_path,
                    segment_sheet,
                )
                segment_contact_sheets.append({
                    "segment_index": segment_index,
                    "task_id": task_id,
                    "path": str(segment_sheet),
                })
            except (OSError, ValueError):
                # The composed contact sheet remains mandatory evidence. A
                # missing historical segment file is surfaced in the audit
                # packet rather than turning semantic QA into a filesystem
                # exception after a valid final video already exists.
                segment_contact_sheets.append({
                    "segment_index": segment_index,
                    "task_id": task_id,
                    "path": "",
                    "evidence_unavailable": True,
                })
        segment_execution_evidence.append({
            "segment_index": segment_index,
            "duration_seconds": float(
                segment.get("duration")
                or segment.get("duration_seconds")
                or 0
            ),
            "requirement_ids": list(
                segment.get("requirement_ids") or []
            ),
            "dialogue_lines": list(
                segment.get("dialogue_lines") or []
            )[:64],
            "display_lines": list(
                segment.get("display_lines") or []
            )[:64],
            "voice_lock": list(segment.get("voice_lock") or [])[:8],
            "timeline": list(segment.get("timeline") or [])[:32],
            "spoken_copy_review": {
                key: spoken_copy_review.get(key)
                for key in (
                    "status",
                    "blocking",
                    "confidence",
                    "expected_text",
                    "observed_text",
                    "semantic_fidelity",
                    "likely_asr_error",
                    "material_differences",
                    "blocking_reasons",
                    "observed_evidence",
                )
                if spoken_copy_review.get(key) is not None
            },
        })
    verdict = review_composed_intent_fidelity_api(
        db,
        contact_sheet_path=str(result_sheet),
        benchmark_contact_sheet_path=(
            str(benchmark_sheet) if benchmark_sheet is not None else None
        ),
        intent_requirements=deliverable_requirements,
        director_requirement_execution=list(
            group.get("requirement_execution") or []
        ),
        production_requirement_execution=list(
            group.get("production_requirement_execution") or []
        ),
        source_transformation_diff=source_diff,
        composed_execution_evidence={
            "video_index": int(group.get("video_index") or 0),
            "duration_seconds": float(group.get("duration") or 0),
            "aspect_ratio": str(group.get("aspect_ratio") or ""),
            "audio_mode": str(group.get("audio_mode") or ""),
            "has_audio_stream": _video_has_audio_stream(target),
            "voice_continuity": dict(
                group.get("voice_continuity") or {}
            ),
            "segments": segment_execution_evidence,
        },
        segment_contact_sheets=segment_contact_sheets,
        execution_id=(
            f"project-{int(project.id)}-variant-"
            f"{int(group.get('video_index') or 0)}-{result_sha256}"
        ),
    )
    affected_indices = {
        int(value)
        for value in list(verdict.get("affected_segment_indices") or [])
        if str(value).isdigit() and int(value) > 0
    }
    affected_task_ids = [
        int(segment.get("task_id") or 0)
        for segment in list(group.get("segments") or [])
        if int(segment.get("segment_index") or 0) in affected_indices
        and int(segment.get("task_id") or 0) > 0
    ]
    return {
        **dict(verdict),
        "video_index": int(group.get("video_index") or 0),
        "affected_task_ids": affected_task_ids,
        "result_sha256": result_sha256,
        "contact_sheet_path": str(result_sheet),
        "benchmark_contact_sheet_path": (
            str(benchmark_sheet) if benchmark_sheet is not None else None
        ),
        "reviewed_at": _stage_now().isoformat(),
        "deferred_cross_deliverable_requirement_ids": [
            str(item.get("requirement_id") or "").strip()
            for item in deferred_requirements
            if str(item.get("requirement_id") or "").strip()
        ],
    }


def _completed_asset_matches_segment_results(
    asset_meta: dict[str, Any],
    *,
    source_task_ids: list[int],
    source_file_ids: list[int],
) -> bool:
    """Bind a composed asset to result generations, not logical tasks alone."""
    previous_task_ids = [
        int(value) for value in list(asset_meta.get("source_task_ids") or [])
    ]
    previous_file_ids = [
        int(value) for value in list(asset_meta.get("source_file_ids") or [])
    ]
    return (
        previous_task_ids == [int(value) for value in source_task_ids]
        and previous_file_ids == [int(value) for value in source_file_ids]
    )


def _restore_media_group_signed_contract(
    db: Session,
    project: HermesContentFactoryProject,
    group: dict[str, Any],
) -> dict[str, Any]:
    """Recover intent fields lost by an older normalization boundary.

    The authoritative source is the exact successful VIDEO_PROMPTS stage
    recorded on the group.  This is deliberately not a best-effort lookup by
    project or by latest stage: a media task may only inherit the contract
    from the stage that created its immutable media manifest.
    """

    restored = dict(group)
    if (
        str(restored.get("intent_manifest_sha256") or "").strip()
        and list(restored.get("intent_requirements") or [])
        and all(
            list(dict(segment).get("requirement_contract") or [])
            for segment in list(restored.get("segments") or [])
            if isinstance(segment, dict)
        )
    ):
        return restored
    try:
        source_stage_id = int(restored.get("source_stage_id") or 0)
    except (TypeError, ValueError):
        return restored
    if source_stage_id <= 0:
        return restored
    source_stage = db.get(HermesContentFactoryStage, source_stage_id)
    if (
        source_stage is None
        or int(source_stage.project_id) != int(project.id)
        or str(source_stage.stage or "").upper() != "VIDEO_PROMPTS"
        or str(source_stage.status or "").lower() != "success"
    ):
        return restored
    try:
        plans = _normalize_video_plan(
            project,
            dict(source_stage.output_json or {}),
            variant_index=int(restored.get("video_index") or 1),
        )
    except (TypeError, ValueError):
        return restored
    plan = next(
        (
            dict(item)
            for item in plans
            if int(dict(item).get("video_index") or 0)
            == int(restored.get("video_index") or 0)
        ),
        None,
    )
    if plan is None:
        return restored
    for key in (
        "audio_mode",
        "intent_manifest_sha256",
        "intent_requirements",
        "requirement_execution",
        "production_requirement_execution",
    ):
        if not restored.get(key) and plan.get(key):
            restored[key] = json.loads(
                json.dumps(plan.get(key), ensure_ascii=False)
            )
    plan_segments = {
        int(item.get("segment_index") or 0): dict(item)
        for item in list(plan.get("segments") or [])
        if isinstance(item, dict)
    }
    restored_segments: list[dict[str, Any]] = []
    for raw_segment in list(restored.get("segments") or []):
        segment = dict(raw_segment)
        signed_segment = plan_segments.get(
            int(segment.get("segment_index") or 0)
        ) or {}
        for key in (
            "intent_manifest_sha256",
            "requirement_ids",
            "requirement_contract",
            "authoritative_product_composites",
            "continuity_dependency",
            "voice_lock",
        ):
            if not segment.get(key) and signed_segment.get(key):
                segment[key] = json.loads(
                    json.dumps(signed_segment.get(key), ensure_ascii=False)
                )
        restored_segments.append(segment)
    restored["segments"] = restored_segments
    restored["signed_contract_recovered_from_stage_id"] = source_stage_id
    return restored


def _compose_segmented_videos(db, project: HermesContentFactoryProject, tasks: list[KieTask]) -> list[HermesContentFactoryAsset]:
    state = dict(project.state_json or {})
    groups = [
        _restore_media_group_signed_contract(db, project, dict(group))
        for group in list(state.get("ai_video_groups") or [])
        if isinstance(group, dict)
    ]
    if not groups:
        return []
    task_by_id = {int(task.id): task for task in tasks}
    generated_dir = (
        CONTENT_FACTORY_STORAGE_ROOT / f"workspace_{project.workspace_id}"
        / project.project_key / "generated" / "final_videos"
    )
    generated_dir.mkdir(parents=True, exist_ok=True)
    assets: list[HermesContentFactoryAsset] = []
    editor_guidance_assets: list[HermesContentFactoryAsset] = []
    newly_composed_indices: list[int] = []
    group_statuses: list[dict[str, Any]] = []
    for group in sorted(groups, key=lambda item: int(item.get("video_index") or 0)):
        segments = sorted(list(group.get("segments") or []), key=lambda item: int(item.get("segment_index") or 0))
        group_video_index = int(group.get("video_index") or 0)
        if not segments:
            group_statuses.append({
                "video_index": group_video_index,
                "status": "failed",
                "error": "Segmented video group is empty",
            })
            _delete_editor_guidance_for_video_index(db, project, group_video_index)
            continue
        segment_paths: list[Path] = []
        source_task_ids: list[int] = []
        source_file_ids: list[int] = []
        pending_task_ids: list[int] = []
        failed_task_ids: list[int] = []
        missing_task_ids: list[int] = []
        remote_result_urls: list[str] = []
        for segment in segments:
            task_id = int(segment.get("task_id") or 0)
            task = task_by_id.get(task_id)
            if task is None:
                missing_task_ids.append(task_id)
                continue
            remote_result_urls.extend(url for url in _task_remote_result_urls(db, task) if url not in remote_result_urls)
            if _is_failed_video_task(task):
                failed_task_ids.append(task_id)
                continue
            if str(task.state or "").lower() != "success":
                pending_task_ids.append(task_id)
                continue
            try:
                path, selected = _result_video_for_task(db, task)
            except ValueError:
                pending_task_ids.append(task_id)
                continue
            segment_paths.append(path)
            source_task_ids.append(task_id)
            source_file_ids.append(int(selected.id))
        if missing_task_ids or failed_task_ids or pending_task_ids or len(segment_paths) != len(segments):
            status = "pending"
            if (missing_task_ids or failed_task_ids) and not pending_task_ids:
                failed_rows = [
                    task_by_id[task_id]
                    for task_id in failed_task_ids
                    if task_id in task_by_id
                ]
                recoverable_failures = bool(
                    not missing_task_ids
                    and failed_rows
                    and all(
                        _content_factory_retryable_video_failure(task)
                        and not _is_unreleasable_dependency_failure(task)
                        for task in failed_rows
                    )
                )
                # A downloaded sibling group must be composable while another
                # provider attempt is cooling down or being rebuilt.  Marking
                # every current failure as terminal here made the bounded API
                # pipeline consume its parallel window and regress to serial
                # execution even though Hermes still owned a valid retry.
                status = "pending" if recoverable_failures else "failed"
                if status == "failed":
                    _delete_editor_guidance_for_video_index(
                        db,
                        project,
                        group_video_index,
                    )
            group_statuses.append({
                "video_index": group_video_index,
                "version_name": group.get("version_name"),
                "status": status,
                "task_ids": [int(segment.get("task_id") or 0) for segment in segments],
                "pending_task_ids": pending_task_ids,
                "failed_task_ids": failed_task_ids,
                "recoverable_failed_task_ids": (
                    failed_task_ids if status == "pending" else []
                ),
                "missing_task_ids": missing_task_ids,
                "remote_result_urls": remote_result_urls,
            })
            continue
        final_name_base = _safe_file_stem(
            str(
                group.get("final_name_base")
                or f"{project.project_key}-{group_video_index or len(assets) + 1}"
            )
        )
        target = generated_dir / f"{final_name_base}.mp4"
        asset = db.query(HermesContentFactoryAsset).filter_by(
            project_id=project.id,
            kind="video",
            file_path=str(target),
        ).order_by(HermesContentFactoryAsset.id.asc()).first()
        asset_meta = dict(asset.meta_json or {}) if asset is not None else {}
        voice_continuity = dict(asset_meta.get("voice_continuity") or {})
        requested_rebuild_policy = str(
            asset_meta.get("local_rebuild_requested_policy") or ""
        ).strip()
        stable_completed_asset = bool(
            asset is not None
            and target.is_file()
            and target.stat().st_size >= 1024
            and _completed_asset_matches_segment_results(
                asset_meta,
                source_task_ids=source_task_ids,
                source_file_ids=source_file_ids,
            )
            and bool(asset_meta.get("is_composed_final"))
            and str(
                dict(asset_meta.get("final_quality") or {}).get("status")
                or ""
            ).upper()
            == "PASS"
            and (
                not str(group.get("intent_manifest_sha256") or "").strip()
                or str(
                    dict(asset_meta.get("final_quality") or {}).get(
                        "intent_manifest_sha256"
                    )
                    or ""
                ).strip()
                == str(group.get("intent_manifest_sha256") or "").strip()
            )
            and requested_rebuild_policy
            != LOCAL_POSTPRODUCTION_POLICY_VERSION
        )
        if stable_completed_asset:
            # A deployment must not silently rewrite already completed media.
            # Rebuilds are opt-in and policy-addressed so one canary repair
            # never reprocesses every historical group or spends new vision
            # quota behind the operator's back.
            # Acoustic QA itself is read-only and was already evaluated above.
            # Persist the evidence when an asset predates this gate so audits
            # do not mistake a verified retained file for an unchecked one.
            if dict(asset_meta.get("voice_continuity") or {}) != voice_continuity:
                asset_meta["voice_continuity"] = voice_continuity
                asset.meta_json = asset_meta
                db.add(asset)
                db.flush()
            guidance_asset = _upsert_per_video_editor_guidance(
                db,
                project,
                asset,
            )
            editor_guidance_assets.append(guidance_asset)
            if str(group.get("media_manifest_sha256") or ""):
                _upsert_content_deliverable_ledger(
                    db,
                    project=project,
                    group=dict(group),
                    video_asset=asset,
                    guidance_asset=guidance_asset,
                )
            group_statuses.append({
                "video_index": group_video_index,
                "version_name": group.get("version_name"),
                "status": "composed",
                "asset_id": int(asset.id or 0),
                "editor_guidance_asset_id": int(
                    guidance_asset.id or 0
                ),
                "task_ids": source_task_ids,
                "remote_result_urls": remote_result_urls,
                "retained_completed_policy_version": str(
                    asset_meta.get(
                        "local_postproduction_policy_version"
                    )
                    or ""
                ),
            })
            assets.append(asset)
            continue
        postprocessed_paths: list[Path] = []
        local_postproduction: list[dict[str, Any]] = []
        for segment, source_path, task_id in zip(
            segments,
            segment_paths,
            source_task_ids,
        ):
            task = task_by_id[int(task_id)]
            segment_index = int(segment.get("segment_index") or 0)
            target_name = (
                f"v{group_video_index:03d}-s{segment_index:02d}-"
                f"task{int(task_id)}-{LOCAL_POSTPRODUCTION_POLICY_VERSION}.mp4"
            )
            post_target = generated_dir / "postprocessed_segments" / target_name
            product_visual_review = (
                _review_provider_product_segment(
                    db,
                    project=project,
                    source=source_path,
                    task=task,
                )
                if bool(segment.get("product_anchor_required"))
                else None
            )
            segment_execution_review = (
                _review_provider_segment_execution(
                    db,
                    project=project,
                    source=source_path,
                    task=task,
                )
                if str(
                    dict(task.input_json or {}).get(
                        "content_factory_compile_source"
                    )
                    or ""
                ) == "signed_production_plan"
                else None
            )
            evidence = _local_postprocess_segment(
                source_path,
                post_target,
                segment=segment,
                task=task,
                db=db,
            )
            if product_visual_review is not None:
                evidence["provider_product_video_review"] = (
                    product_visual_review
                )
            if segment_execution_review is not None:
                evidence["segment_execution_review"] = (
                    segment_execution_review
                )
            postprocessed_paths.append(Path(str(evidence["path"])))
            local_postproduction.append({
                "segment_index": segment_index,
                "task_id": int(task_id),
                **evidence,
            })
        segment_paths = postprocessed_paths
        local_voice_identity = _local_voiceover_identity_report(
            segments=[dict(item) for item in segments],
            local_postproduction=local_postproduction,
        )
        if local_voice_identity is not None:
            voice_continuity = local_voice_identity
            if str(voice_continuity.get("status") or "").upper() != "PASS":
                raise ValueError(
                    "CONTENT_FINAL_QUALITY_GATE_FAILED: "
                    "LOCAL_VOICEOVER_IDENTITY_MISMATCH: "
                    + json.dumps(
                        voice_continuity,
                        ensure_ascii=False,
                        sort_keys=True,
                    )
                )
        else:
            # Provider-owned dialogue is checked only after its real audio has
            # survived normalization.  Never inspect pre-mux incidental audio
            # for locally voiced segments.
            voice_continuity = _audit_segment_voice_continuity(
                db,
                segments=[dict(item) for item in segments],
                segment_paths=postprocessed_paths,
                source_task_ids=source_task_ids,
                task_by_id=task_by_id,
            )
        _concat_videos(segment_paths, target)
        newly_composed_indices.append(
            int(group.get("video_index") or len(assets) + 1)
        )
        source_diff = _source_transformation_quality_report(
            db,
            project,
            target,
        )
        intent_review_group = {
            **dict(group),
            "voice_continuity": voice_continuity,
        }
        intent_fidelity = _final_intent_fidelity_report(
            db,
            project,
            target,
            group=intent_review_group,
            source_diff=source_diff,
        )
        final_quality = _audit_composed_content_video(
            target,
            group=dict(group),
            segments=[dict(item) for item in segments],
            local_postproduction=local_postproduction,
            source_diff=source_diff,
            intent_fidelity=intent_fidelity,
        )
        meta = {
            "content_factory_video_index": int(group.get("video_index") or len(assets) + 1),
            "content_factory_variant_index": int(group.get("video_index") or len(assets) + 1),
            "version_name": group.get("version_name"),
            "story_arc": group.get("story_arc"),
            "duration": int(group.get("duration") or _configured_video_duration(project)),
            "segment_count": len(segments),
            "segment_plan": [
                {
                    "segment_index": int(segment.get("segment_index") or 0),
                    "duration": int(segment.get("duration") or 0),
                    "segment_goal": str(segment.get("segment_goal") or ""),
                    "timeline": list(segment.get("timeline") or []),
                    "dialogue_lines": list(segment.get("dialogue_lines") or []),
                    "display_lines": list(segment.get("display_lines") or []),
                    "product_anchor_required": bool(
                        segment.get("product_anchor_required", False)
                    ),
                    "product_render_mode": "provider_reference",
                    "compile_source": str(
                        segment.get("compile_source") or ""
                    ),
                }
                for segment in segments
            ],
            "source_task_ids": source_task_ids,
            "source_file_ids": source_file_ids,
            "local_postproduction": local_postproduction,
            "local_postproduction_policy_version": (
                LOCAL_POSTPRODUCTION_POLICY_VERSION
            ),
            "local_rebuild_requested_policy": None,
            "local_rebuild_completed_at": (
                datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            ),
            "media_manifest_sha256": group.get("media_manifest_sha256"),
            "final_quality": final_quality,
            "voice_continuity": voice_continuity,
            "intent_fidelity": intent_fidelity,
            "is_composed_final": True,
            "remote_url": None,
        }
        if asset is None:
            asset = HermesContentFactoryAsset(
                project_id=project.id, workspace_id=project.workspace_id, user_id=project.user_id,
                stage="VIDEO_PROMPTS", kind="video", original_name=target.name,
                file_path=str(target), mime_type="video/mp4", size_bytes=target.stat().st_size,
                meta_json=meta,
            )
            db.add(asset)
        else:
            asset.original_name = target.name
            asset.size_bytes = target.stat().st_size
            asset.meta_json = {**dict(asset.meta_json or {}), **meta}
        db.flush()
        guidance_asset = _upsert_per_video_editor_guidance(db, project, asset)
        editor_guidance_assets.append(guidance_asset)
        if str(group.get("media_manifest_sha256") or ""):
            _upsert_content_deliverable_ledger(
                db,
                project=project,
                group=dict(group),
                video_asset=asset,
                guidance_asset=guidance_asset,
            )
        group_statuses.append({
            "video_index": int(group.get("video_index") or len(assets) + 1),
            "version_name": group.get("version_name"),
            "status": "composed",
            "asset_id": int(asset.id or 0),
            "editor_guidance_asset_id": int(guidance_asset.id or 0),
            "task_ids": source_task_ids,
            "remote_result_urls": remote_result_urls,
        })
        assets.append(asset)
    db.flush()
    # The video waiter deliberately commits its heartbeat before inspecting
    # provider work.  A long-running Director/Production Plan stage may publish
    # a newly accepted control-plane pointer while this function is composing
    # or auditing media.  Never write the waiter's old JSON snapshot back over
    # that newer authority.  Re-lock and refresh only at the final merge
    # boundary so the expensive media work itself does not hold the project
    # row lock.
    project = _lock_project_for_video_state_merge(db, project)
    state = dict(project.state_json or {})
    current_groups = [
        dict(item)
        for item in list(state.get("ai_video_groups") or [])
        if isinstance(item, dict)
    ]
    for restored_group in groups:
        current_group = next(
            (
                item
                for item in current_groups
                if int(item.get("video_index") or 0)
                == int(restored_group.get("video_index") or 0)
                and int(item.get("source_stage_id") or 0)
                == int(restored_group.get("source_stage_id") or 0)
                and str(item.get("media_manifest_sha256") or "")
                == str(restored_group.get("media_manifest_sha256") or "")
            ),
            None,
        )
        if current_group is None:
            continue
        for key in (
            "audio_mode",
            "intent_manifest_sha256",
            "intent_requirements",
            "requirement_execution",
            "production_requirement_execution",
            "signed_contract_recovered_from_stage_id",
        ):
            if restored_group.get(key):
                current_group[key] = restored_group.get(key)
        restored_segments = {
            int(item.get("task_id") or 0): dict(item)
            for item in list(restored_group.get("segments") or [])
            if isinstance(item, dict) and int(item.get("task_id") or 0) > 0
        }
        merged_segments: list[dict[str, Any]] = []
        for raw_segment in list(current_group.get("segments") or []):
            segment = dict(raw_segment)
            repaired = restored_segments.get(int(segment.get("task_id") or 0))
            if repaired is not None:
                for key in (
                    "intent_manifest_sha256",
                    "requirement_ids",
                    "requirement_contract",
                    "authoritative_product_composites",
                    "continuity_dependency",
                    "voice_lock",
                ):
                    if repaired.get(key):
                        segment[key] = repaired.get(key)
            merged_segments.append(segment)
        current_group["segments"] = merged_segments
    state["ai_video_groups"] = current_groups
    previous_ids = [
        int(value) for value in state.get("ai_video_final_asset_ids") or []
        if str(value).strip().isdigit()
    ]
    current_ids = [int(asset.id) for asset in assets if asset.id]
    state["ai_video_final_asset_ids"] = sorted(set(previous_ids + current_ids))
    state, authoritative_guides = _reconcile_editor_guidance_state(
        db,
        project,
        state,
    )
    current_guide_ids = [int(asset.id) for asset in editor_guidance_assets if asset.id]
    if current_guide_ids:
        state["editor_guidance_last_generated_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
    state["ai_video_group_statuses"] = group_statuses
    state["ai_video_active_group_composed_count"] = len([
        item for item in group_statuses if item.get("status") == "composed"
    ])
    # ``ai_video_groups`` is a bounded active-work ledger and may contain only
    # the most recent variants.  Project-level completion must come from the
    # durable local MP4 assets or monitoring regresses as that ledger rotates.
    state["ai_video_composed_video_count"] = len(
        _completed_video_assets_by_index(db, project)
    )
    state["ai_video_pending_task_ids"] = sorted({
        int(task_id)
        for item in group_statuses
        for task_id in item.get("pending_task_ids", [])
        if int(task_id or 0) > 0
    })
    state["ai_video_failed_task_ids"] = sorted({
        int(task_id)
        for item in group_statuses
        for task_id in item.get("failed_task_ids", [])
        if int(task_id or 0) > 0
    })
    state["ai_video_failed_groups"] = [item for item in group_statuses if item.get("status") == "failed"]
    project.state_json = state
    if newly_composed_indices:
        _record_hermes_observation(
            db,
            project,
            category="video_delivery",
            outcome="success",
            provider=str(_video_model_policy(project).get("provider_key") or ""),
            details={
                "video_indices": sorted(set(newly_composed_indices)),
                "prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
                "composed_from_segments": True,
            },
        )
    return assets


def _lock_project_for_video_state_merge(
    db,
    project: HermesContentFactoryProject,
) -> HermesContentFactoryProject:
    """Refresh one project before a video-owned JSON merge.

    ``populate_existing`` is required because SQLAlchemy's identity map may
    otherwise return the stale instance loaded by the waiter before a
    concurrent control-plane commit.  The project-first row lock matches the
    repository's global lock order and is held only until the caller's
    immediate commit.
    """

    refreshed = (
        db.query(HermesContentFactoryProject)
        .filter(HermesContentFactoryProject.id == int(project.id))
        .populate_existing()
        .with_for_update()
        .one()
    )
    return refreshed


_CONCURRENT_VIDEO_RUNTIME_STATE_KEYS = {
    "active_variant_index",
    "video_variant_pipeline",
    "final_video_quality_recovery",
}


def _merge_latest_video_runtime_before_control_commit(
    db,
    project: HermesContentFactoryProject,
) -> None:
    """Keep concurrent media progress when a control stage commits.

    Content authoring for variant N+1 intentionally overlaps polling, final
    review and targeted segment repair for variant N.  A control-stage worker
    can therefore hold an older ``state_json`` snapshot while the video waiter
    atomically replaces one segment pointer with a quality-repair child.  If
    the later control-stage commit writes its whole snapshot, that paid repair
    disappears from ``ai_video_groups`` and the video worker correctly
    quarantines the child as non-authoritative.

    Lock and read the current row immediately before the control-plane commit,
    then preserve only video-runtime-owned fields.  Creative state remains
    owned by the current stage; media task/group/review state remains owned by
    the asynchronous video waiter.  Missing runtime keys are removed as well
    so a stale stage cannot resurrect state deliberately cleared by the
    waiter.
    """

    local_state = dict(project.state_json or {})
    latest_row = (
        db.query(
            HermesContentFactoryProject.id,
            HermesContentFactoryProject.state_json,
        )
        .filter(HermesContentFactoryProject.id == int(project.id))
        .with_for_update()
        .one()
    )
    latest_state = dict(latest_row.state_json or {})

    def video_runtime_owned(key: str) -> bool:
        return (
            str(key).startswith("ai_video_")
            or key in _CONCURRENT_VIDEO_RUNTIME_STATE_KEYS
        )

    for key in list(local_state):
        if video_runtime_owned(key) and key not in latest_state:
            local_state.pop(key, None)
    for key, value in latest_state.items():
        if video_runtime_owned(key):
            local_state[key] = value
    project.state_json = local_state


def _enqueue_queued_local_video_tasks(
    project: HermesContentFactoryProject,
    tasks: list[KieTask],
    *,
    exclude_task_ids: set[int] | None = None,
) -> list[int]:
    """Reliably hand local Content Factory segments back to the video queue.

    A segment can be reset in place after a provider error.  The database
    transition succeeds before Celery publishing, so a broker/worker blip in
    that tiny gap must not leave the segment dormant for the old ten-minute
    stale-task recovery window.  Re-enqueueing is safe: the poll-owner lease
    in ``submit_and_poll_ai_video_task`` makes duplicate deliveries a
    no-op before a second provider submission can occur.
    """
    queued_task_ids: list[int] = []
    excluded = {int(value) for value in (exclude_task_ids or set())}
    # The lease must outlive the longest synchronous submit timeout.  A short
    # 60-second lease republished the same Sub2API Flow task while its
    # legitimate 180-second HTTP request was still in flight, consuming
    # several AI-video workers and making recovery look stalled.
    lease_max_age_seconds = max(
        60,
        int(settings.BANDIANWA_POLL_INTERVAL_SECONDS) * 4,
        int(math.ceil(float(settings.SUB2API_HTTP_TIMEOUT_SECONDS))) + 30,
    )
    now = datetime.now(timezone.utc)
    for task in tasks:
        if int(task.id) in excluded:
            # _release_ready_segment_dependencies already committed and
            # published this task earlier in the same waiter turn. The video
            # worker has not necessarily claimed its poll lease yet, so
            # immediately running the generic queued_local compensator would
            # publish a guaranteed duplicate message. A later waiter still
            # recovers it normally if the original broker delivery is lost.
            continue
        if str(task.state or "").lower() != "queued_local":
            continue
        # The submit worker claims its lease before it makes a provider call.
        # Keep that tiny submit window quiet: otherwise the 20-second Hermes
        # waiter keeps publishing duplicate Celery messages while the original
        # worker is still submitting.  A missing or expired lease is still
        # deliberately re-enqueued, so a broker/worker loss remains recoverable
        # without waiting for the broad stale-task sweep.
        local_meta = dict(getattr(task, "result_json", None) or {}).get("__local") or {}
        owner_task_id = str(local_meta.get("poll_owner_task_id") or "").strip()
        heartbeat_raw = str(local_meta.get("poll_heartbeat_at") or "").strip()
        submit_enqueued_raw = str(local_meta.get("submit_enqueued_at") or "").strip()
        try:
            heartbeat = datetime.fromisoformat(heartbeat_raw.replace("Z", "+00:00"))
            if heartbeat.tzinfo is None:
                heartbeat = heartbeat.replace(tzinfo=timezone.utc)
            else:
                heartbeat = heartbeat.astimezone(timezone.utc)
        except (TypeError, ValueError):
            heartbeat = None
        try:
            submit_enqueued_at = datetime.fromisoformat(
                submit_enqueued_raw.replace("Z", "+00:00")
            )
            if submit_enqueued_at.tzinfo is None:
                submit_enqueued_at = submit_enqueued_at.replace(tzinfo=timezone.utc)
            else:
                submit_enqueued_at = submit_enqueued_at.astimezone(timezone.utc)
        except (TypeError, ValueError):
            submit_enqueued_at = None
        if owner_task_id and heartbeat is not None and heartbeat >= now - timedelta(seconds=lease_max_age_seconds):
            continue
        if (
            submit_enqueued_at is not None
            and submit_enqueued_at >= now - timedelta(seconds=lease_max_age_seconds)
        ):
            continue
        set_task_local_meta(
            task,
            submit_enqueued_at=now.isoformat(),
        )
        submit_and_poll_ai_video_task.apply_async(
            kwargs={
                "workspace_id": int(project.workspace_id),
                "local_task_id": int(task.id),
                "interval_seconds": int(settings.BANDIANWA_POLL_INTERVAL_SECONDS),
                "timeout_seconds": int(settings.BANDIANWA_POLL_TIMEOUT_SECONDS),
            },
            queue=production_video_queue(task),
        )
        queued_task_ids.append(int(task.id))
    return queued_task_ids




def _is_browser_interaction_error(message: str) -> bool:
    value = str(message or "").lower()
    return any(marker in value for marker in (
        "chatgpt did not accept the prompt",
        "browser element did not appear",
        "attachments did not finish uploading",
        "composer has stable attachments but the send button stayed disabled",
        "chatgpt accepted the file tile but did not finish processing it",
        "browser bridge file sync is incomplete",
        "did not confirm local file sync",
        "chatgpt stage returned an incomplete or truncated text response",
        "chatgpt stage returned text but not a valid project json envelope",
        "cannot read properties of undefined",
        "visual_capture_source_collision",
        "visual_capture_not_portrait_board",
        "visual_capture_too_small",
        "cdp command timed out",
        "browser command timed out",
        "page.enable",
        "resource temporarily unavailable",
        "daemon may be busy",
        "runtime.evaluate",
    ))


def _is_recoverable_chatgpt_response_error(message: str) -> bool:
    value = str(message or "").lower()
    return any(marker in value for marker in (
        "chatgpt stage returned an incomplete or truncated text response",
        "chatgpt stage returned text but not a valid project json envelope",
        "chatgpt stage stopped without returning a response",
        "timed out waiting for the chatgpt stage response",
        "chatgpt_response_still_running",
    ))


