def _is_chatgpt_rate_limit_error(message: str) -> bool:
    value = str(message or "").lower()
    return any(marker in value for marker in (
        "chatgpt_temporary_rate_limit", "chatgpt_rate_limit_cooldown_active",
        "request too frequent", "too many requests", "rate limit", "rate limited",
        "try again in a few minutes", "please wait a few minutes",
        "plan limit for image generation", "plan limit for image generations",
        "image generation limit", "image generations requests",
        "create more images when the limit resets",
        "you've hit the plus plan limit", "you have hit the plus plan limit",
        "usage limit", "reached your limit",
        "chatgpt_upload_limit",
        "一次最多可上传 0 个文件",
        "最多可上传 0 个文件",
        "maximum of 0 files",
        "upload up to 0 files",
        "请求过于频繁", "请稍等几分钟", "暂时限制你访问",
        "额度", "限额",
    ))


def _is_chatgpt_quota_limit_error(message: str) -> bool:
    """Compatibility name for every ChatGPT capacity/rate interruption."""
    return _is_chatgpt_rate_limit_error(message) or _rate_limit_kind(message) == "quota"


def _rate_limit_kind(message: str) -> str:
    value = str(message or "").lower()
    if any(marker in value for marker in (
        "plan limit for image generation", "plan limit for image generations",
        "image generation limit", "image generations requests",
        "create more images when the limit resets",
        "you've hit the plus plan limit", "you have hit the plus plan limit",
        "usage limit", "reached your limit", "you've reached", "quota",
        "chatgpt_upload_limit", "一次最多可上传 0 个文件",
        "最多可上传 0 个文件", "maximum of 0 files", "upload up to 0 files",
        "额度", "限额",
    )):
        return "quota"
    if any(marker in value for marker in (
        "chatgpt_temporary_rate_limit", "chatgpt_rate_limit_cooldown_active",
        "request too frequent", "too many requests", "rate limited",
        "try again in a few minutes", "please wait a few minutes",
        "请求过于频繁", "请稍等几分钟", "暂时限制你访问",
    )):
        return "temporary"
    return "temporary" if _is_chatgpt_rate_limit_error(value) else "unknown"


def _stable_seconds_jitter(entropy_key: str, *, minimum: int, maximum: int) -> int:
    low = max(0, int(minimum))
    high = max(low, int(maximum))
    if high == low:
        return low
    digest = hashlib.sha256(str(entropy_key or "hermes").encode("utf-8")).digest()
    return low + int.from_bytes(digest[:4], "big") % (high - low + 1)


def _adaptive_rate_limit_wait_seconds(
    learning: dict[str, Any], *, kind: str,
    episode_started_at: datetime, now: datetime,
    failed_probe_count: int, entropy_key: str,
) -> int:
    """Choose one project's next probe time from its own recovery history."""
    values = dict(learning or {})
    samples = [
        max(60, min(14400, int(value)))
        for value in list(values.get("recovery_samples_seconds") or [])[-12:]
        if str(value).strip().isdigit()
    ]
    ewma = max(0, int(values.get("ewma_recovery_seconds") or 0))
    lower_bound = max(0, int(values.get("observed_lower_bound_seconds") or 0))
    elapsed = max(0, int((now - episode_started_at).total_seconds()))
    if samples or ewma or lower_bound:
        learned_target = max(
            lower_bound,
            ewma,
            sorted(samples)[max(0, math.ceil(len(samples) * 0.75) - 1)] if samples else 0,
        )
        # A failed probe proves the real recovery time is longer than elapsed.
        if int(failed_probe_count) > 1:
            learned_target = max(learned_target, elapsed + 90)
        remaining = max(90 + max(0, int(failed_probe_count)) * 30, learned_target - elapsed)
        jitter = _stable_seconds_jitter(
            f"{entropy_key}:{kind}:{failed_probe_count}",
            minimum=max(10, remaining // 25), maximum=max(20, remaining // 10),
        )
        return min(14400, remaining + jitter)
    cold_min, cold_max = ((1800, 3600) if kind == "quota" else (300, 600))
    return _stable_seconds_jitter(
        f"{entropy_key}:{kind}:cold", minimum=cold_min, maximum=cold_max,
    )


def _historical_rate_limit_recovery_samples(
    rows: list[Any], *, bridge_id: str,
) -> list[int]:
    """Derive prior recovery durations for one browser route only."""
    samples: list[int] = []
    episode_started_at: datetime | None = None
    ordered = sorted(
        rows,
        key=lambda row: (
            getattr(row, "completed_at", None)
            or getattr(row, "updated_at", None)
            or getattr(row, "created_at", None)
            or datetime.min
        ),
    )
    for row in ordered:
        if str(dict(getattr(row, "input_json", None) or {}).get("browser_bridge_id") or "") != str(bridge_id):
            continue
        occurred_at = (
            getattr(row, "completed_at", None)
            or getattr(row, "updated_at", None)
            or getattr(row, "created_at", None)
        )
        if occurred_at is None:
            continue
        if _is_chatgpt_rate_limit_error(str(getattr(row, "error_message", "") or "")):
            episode_started_at = episode_started_at or occurred_at
            continue
        if episode_started_at is not None and str(getattr(row, "status", "")) == "success":
            samples.append(max(60, int((occurred_at - episode_started_at).total_seconds())))
            episode_started_at = None
    return samples[-12:]


def _adaptive_chatgpt_request_gap_seconds(
    project_state: dict[str, Any], *, stage: str, attachment_count: int,
    now: datetime, entropy_key: str,
) -> int:
    """Human review interval scoped to a project, never to a reused slot."""
    values = dict(project_state or {})
    pacing = dict(values.get("chatgpt_request_pacing") or {})
    pressure = max(0, int(pacing.get("pressure_score") or 0))
    base = 30 + min(30, max(0, int(attachment_count)) * 3)
    if str(stage or "").upper() in {"VISUAL_PREVIEW", "FINAL_ASSETS"}:
        base += 15
    target = base + pressure * 40
    learning = dict(values.get("chatgpt_rate_limit_learning") or {})
    for entry in learning.values():
        entry = dict(entry or {})
        recovered_at_raw = str(entry.get("last_recovered_at") or "").strip()
        try:
            recovered_at = datetime.fromisoformat(recovered_at_raw) if recovered_at_raw else None
        except ValueError:
            recovered_at = None
        if recovered_at and recovered_at >= now - timedelta(hours=6):
            target = max(target, max(60, int(entry.get("ewma_recovery_seconds") or 0) // 12))
    jitter = _stable_seconds_jitter(
        f"{entropy_key}:{stage}:{pressure}", minimum=0, maximum=max(3, target // 12),
    )
    return min(900, target + jitter)


def _record_project_rate_limit(
    project: HermesContentFactoryProject, stage_input: dict[str, Any],
    *, message: str, now: datetime,
) -> int:
    """Update only this project's rate-limit episode and return its next wait."""
    kind = _rate_limit_kind(message)
    state = dict(project.state_json or {})
    all_learning = dict(state.get("chatgpt_rate_limit_learning") or {})
    learning = dict(all_learning.get(kind) or {})
    started_raw = str(learning.get("episode_started_at") or "").strip()
    try:
        started_at = datetime.fromisoformat(started_raw) if started_raw else now
    except ValueError:
        started_at = now
    failed_probe_count = max(0, int(learning.get("failed_probe_count") or 0)) + 1
    observed = max(0, int((now - started_at).total_seconds()))
    learning.update({
        "episode_started_at": started_at.isoformat(),
        "failed_probe_count": failed_probe_count,
        "observed_lower_bound_seconds": max(
            observed, int(learning.get("observed_lower_bound_seconds") or 0),
        ),
        "last_error": str(message or "")[:1000],
        "last_limited_at": now.isoformat(),
    })
    wait_seconds = _adaptive_rate_limit_wait_seconds(
        learning,
        kind=kind,
        episode_started_at=started_at,
        now=now,
        failed_probe_count=failed_probe_count,
        entropy_key=f"{project.project_key}:{kind}",
    )
    learning["next_probe_wait_seconds"] = wait_seconds
    all_learning[kind] = learning
    pacing = dict(state.get("chatgpt_request_pacing") or {})
    pacing["pressure_score"] = min(10, int(pacing.get("pressure_score") or 0) + 1)
    pacing["updated_at"] = now.isoformat()
    state["chatgpt_rate_limit_learning"] = all_learning
    state["chatgpt_request_pacing"] = pacing
    project.state_json = state
    stage_input.update({
        "rate_limit_kind": kind,
        "rate_limit_episode_started_at": started_at.isoformat(),
        "rate_limit_failed_probe_count": failed_probe_count,
        "rate_limit_wait_seconds": wait_seconds,
    })
    return wait_seconds


def _record_project_chatgpt_recovery(
    project: HermesContentFactoryProject, *, now: datetime,
) -> None:
    state = dict(project.state_json or {})
    all_learning = dict(state.get("chatgpt_rate_limit_learning") or {})
    recovered = False
    for kind, raw in list(all_learning.items()):
        learning = dict(raw or {})
        started_raw = str(learning.get("episode_started_at") or "").strip()
        if not started_raw:
            continue
        try:
            started_at = datetime.fromisoformat(started_raw)
        except ValueError:
            continue
        duration = max(60, min(14400, int((now - started_at).total_seconds())))
        samples = [
            max(60, min(14400, int(value)))
            for value in list(learning.get("recovery_samples_seconds") or [])[-11:]
            if str(value).strip().isdigit()
        ]
        samples.append(duration)
        previous = max(0, int(learning.get("ewma_recovery_seconds") or 0))
        learning.update({
            "recovery_samples_seconds": samples,
            "ewma_recovery_seconds": duration if not previous else int(previous * 0.65 + duration * 0.35),
            "last_recovered_at": now.isoformat(),
            "last_recovery_seconds": duration,
            "episode_started_at": None,
            "failed_probe_count": 0,
            "observed_lower_bound_seconds": 0,
            "next_probe_wait_seconds": 0,
        })
        all_learning[kind] = learning
        recovered = True
    if not recovered:
        return
    pacing = dict(state.get("chatgpt_request_pacing") or {})
    pacing["pressure_score"] = max(0, int(pacing.get("pressure_score") or 0) - 1)
    pacing["updated_at"] = now.isoformat()
    state["chatgpt_rate_limit_learning"] = all_learning
    state["chatgpt_request_pacing"] = pacing
    project.state_json = state


def _stage_retry_delay(exc: Exception, retry_number: int) -> int | None:
    message = str(exc).lower()
    error_code = str(getattr(exc, "code", "") or "").strip().upper()
    learned_delay = re.search(r"retry_after_seconds\s*=\s*(\d+)", message)
    if learned_delay:
        return max(30, min(14400, int(learned_delay.group(1))))
    if "visual_capture_grid_ratio_invalid" in message:
        # Geometry failures need a rewritten visual instruction, not a blind
        # broker retry of the same ChatGPT image response.
        return None
    if "permission denied" in message and "bandianwa_uploads" in message:
        delays = (30, 120, 300)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if error_code == "HERMES_UPSTREAM_QUOTA":
        # The routing gateway has already opened the exhausted route's quota
        # circuit.  Preserve the stage for a later automatic release rather
        # than hot-looping or converting account capacity into a content
        # failure.  Authentication failures remain terminal.
        delays = (21600, 86400)
        return (
            delays[retry_number - 1]
            if 1 <= retry_number <= len(delays)
            else None
        )
    transient_hermes_codes = {
        "HERMES_TIMEOUT",
        "HERMES_NETWORK_ERROR",
        "HERMES_UPSTREAM_ERROR",
        "HERMES_UPSTREAM_EXECUTION_FAILED",
    }
    # The shared routing gateway deliberately redacts provider-specific
    # transport details and returns a bounded fault class after trying the
    # enabled routes.  Preserve that contract here: otherwise an error such as
    # ``..._ROUTING_FAILED: NETWORK`` is mistaken for a terminal content
    # failure merely because its original 502/503 wording is no longer present.
    routed_transport_fault = bool(
        re.search(
            r"(?:^|\s)[a-z0-9_]+_routing_failed:\s*"
            r"(?:network|timeout|rate_limit)(?:\s|$)",
            message,
        )
    )
    transport_markers = (
        "server disconnected without sending a response",
        "remoteprotocolerror",
        "connection reset by peer",
        "connection aborted",
        "connection closed unexpectedly",
        "readerror",
        "writeerror",
        "connecterror",
        "temporary failure in name resolution",
        "name or service not known",
        "httpstatuserror",
        "gateway timeout",
        "bad gateway",
        "service unavailable",
        "a timeout occurred",
        " 502 ",
        " 503 ",
        " 504 ",
        " 520 ",
        " 522 ",
        " 524 ",
    )
    if (
        error_code in transient_hermes_codes
        or routed_transport_fault
        or any(marker in message for marker in transport_markers)
    ):
        # API submissions carry a stable idempotency key. Retrying the same
        # stage after a transient transport failure therefore recovers a lost
        # response without creating another billable upstream generation.
        delays = (15, 45, 120, 300)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    infrastructure_markers = (
        "failed to connect to cdp",
        "websocket connect failed",
        "connection refused",
        "browser bridge is not connected",
        "browser bridge unavailable",
        "all cdp discovery methods failed",
    )
    if any(marker in message for marker in infrastructure_markers):
        delays = (60, 180, 600, 1800, 3600, 7200)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if _is_recoverable_chatgpt_response_error(message):
        # A partially rendered assistant turn is not a terminal project error.
        # First allow the original tab to settle, then retry with widening
        # backoff so a transient ChatGPT renderer issue cannot retire the slot.
        delays = (45, 120, 300, 600, 900, 1800)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if _is_browser_interaction_error(message):
        delays = (20, 60, 180, 300)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    quota_markers = (
        "usage limit",
        "rate limit",
        "rate limited",
        "request too frequent",
        "chatgpt_temporary_rate_limit",
        "chatgpt_rate_limit_cooldown_active",
        "try again after",
        "you've reached",
        "额度",
        "限额",
        "请求过于频繁",
    )
    if any(marker in message for marker in quota_markers):
        delays = (300, 900, 1800, 3600, 7200, 14400)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if "chatgpt stage stopped without returning a response" in message:
        delays = (600, 1800, 7200)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if (
        "remained busy without observable progress" in message
        or "timed out waiting for the chatgpt stage response" in message
        or "soft time limit" in message
        or "persistable visuals" in message
    ):
        delays = (30, 120, 300)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if (
        "video_prompts must return exactly" in message
        or "not a valid project json envelope" in message
        or "video_prompts_reference_index_invalid" in message
    ):
        delays = (60, 180)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    if "video_prompts_confirmed_promotion_missing" in message:
        delays = (20, 90, 240)
        return delays[retry_number - 1] if 1 <= retry_number <= len(delays) else None
    return None


def _semantic_api_retry_plan(
    stage_input: dict[str, Any] | None,
    *,
    error_message: str,
) -> dict[str, Any] | None:
    """Return one bounded fresh-generation plan for a complete invalid payload.

    Transport retries and semantic corrections have different identities. A
    complete response that violates a local business contract must not be sent
    forever every 20 seconds. The first correction moves CREATIVE to the
    alternate commercial model; later corrections remain fresh generations
    with unique idempotency keys. Exhaustion is handled by a bounded API-only
    creative replan or quality pause; browser automation cannot repair a
    deterministic content-contract violation.
    """
    values = dict(stage_input or {})
    retry_count = int(values.get("semantic_api_retry_count") or 0) + 1
    if retry_count > MAX_SEMANTIC_API_REGENERATION_CYCLES:
        return None
    del error_message
    return {
        "semantic_api_retry_count": retry_count,
        "semantic_api_retry_limit": MAX_SEMANTIC_API_REGENERATION_CYCLES,
        # Every rejected semantic response receives a fresh attempt on the
        # alternate multimodal-capable model. The server does not inspect the
        # prose to choose a special business-rule repair lane.
        "text_api_prefer_alternate_model": True,
    }


def _is_content_text_api_route(api_route: str | None) -> bool:
    """Recognize both physical and logical unified text-API routes.

    Queue creation stores the logical ``ai-routing:<role>`` identity for audit
    and runtime dispatch currently resolves it to the physical text gateway.
    Exception handling re-reads the durable logical identity. Treating only
    the old ``toapis:text`` spelling as API work made a malformed-but-complete
    reviewer response terminal instead of scheduling its bounded semantic
    regeneration.
    """

    route = str(api_route or "").strip().lower()
    return route == "toapis:text" or route.startswith("ai-routing:")


def _is_text_api_output_validation_failure(
    *,
    api_route: str,
    stage: str,
    replayed_response: bool,
    error: Exception,
) -> bool:
    """Classify a complete model response rejected by its typed stage contract.

    Transport faults are handled before this function.  Once a routed semantic
    stage has returned a complete response, any ``ValueError`` or
    ``ContentFactoryApiError`` here is a schema/contract rejection of that
    response.  Do not inspect error prose: doing so turns newly-added model
    contracts into an accidental fixed keyword gate.
    """
    return bool(
        _is_content_text_api_route(api_route)
        and not replayed_response
        and str(stage or "").upper() in TEXT_API_STAGES
        and isinstance(error, (ValueError, ContentFactoryApiError))
    )


def _text_api_fault_needs_recovery_supervisor(
    *,
    api_route: str,
    stage: str,
    error: Exception,
) -> bool:
    """Route first-class transport outages directly into durable recovery.

    A routing-layer NETWORK/TIMEOUT/RATE_LIMIT result means the enabled API
    pool has already made its bounded provider attempts.  Treating that text
    as a malformed model payload briefly marked the project failed and burned
    several identical self-heal passes before the Recovery Supervisor was
    consulted.  The supervisor can immediately choose a cooled API retry (or
    another allowed backend) while preserving the same stage and assets.
    """
    if (
        not str(api_route or "").strip()
        or str(stage or "").upper() not in TEXT_API_STAGES
    ):
        return False
    fault_class = classify_recovery_fault(
        str(error),
        code=str(getattr(error, "code", "") or ""),
    )
    return fault_class in {"NETWORK", "TIMEOUT", "RATE_LIMIT"}


def _is_semantic_text_payload_failure(
    *,
    api_route: str,
    stage: str,
    error: Exception,
) -> bool:
    """Return true when only a fresh model response can satisfy the contract.

    This deliberately includes a replayed complete response.  Replaying a
    script that is now known to duplicate the assigned diversity lane cannot
    improve it and must bypass the durable-capture cooldown.
    """
    return bool(
        _is_content_text_api_route(api_route)
        and str(stage or "").upper() in TEXT_API_STAGES
        and isinstance(error, (ValueError, ContentFactoryApiError))
    )


def _semantic_api_exhaustion_decision(
    state: dict[str, Any] | None,
    *,
    stage: str,
    variant_index: int,
    error_message: str,
) -> dict[str, Any]:
    """Open a cooled API-only recovery epoch without browser fallback."""
    next_state = dict(state or {})
    stage_name = str(stage or "").upper()
    variant = max(1, int(variant_index or 1))
    previous = dict(next_state.get("last_semantic_api_exhaustion") or {})
    try:
        attempt_count = int(previous.get("attempt_count") or 0) + 1
    except (TypeError, ValueError):
        attempt_count = 1
    no_progress_cycles = (
        int(previous.get("no_progress_cycles") or 0) + 1
        if str(previous.get("stage") or "").upper() == stage_name
        else 0
    )
    action = "cooldown_and_retry_api"
    next_state["last_semantic_api_exhaustion"] = {
        "stage": stage_name,
        "variant_index": variant,
        "action": action,
        "attempt_count": attempt_count,
        "no_progress_cycles": no_progress_cycles,
        "error": str(error_message or "")[:1200],
        "at": _stage_now().isoformat(),
    }
    return {
        "action": action,
        "attempt_count": attempt_count,
        "no_progress_cycles": no_progress_cycles,
        "state": next_state,
    }


def _text_api_transport_retry_plan(
    stage_input: dict[str, Any] | None,
) -> dict[str, Any]:
    """Rotate the preferred text model after an ambiguous transport failure.

    ``execute_text_stage_api`` deliberately does not submit a second model in
    the same call after a timeout/disconnect because the first provider may
    already have accepted that billable request. A later, explicitly bounded
    stage retry is a new generation and should not hammer the same unhealthy
    model three times before browser fallback. Persist the route flip on the
    stage so retries and worker restarts alternate Luna/Terra deterministically.
    """
    values = dict(stage_input or {})
    rotation_count = int(values.get("text_api_transport_model_rotation_count") or 0) + 1
    return {
        "text_api_prefer_alternate_model": not bool(
            values.get("text_api_prefer_alternate_model", False)
        ),
        "text_api_transport_model_rotation_count": rotation_count,
    }


def _text_api_transport_budget_exhausted(
    stage_input: dict[str, Any] | None,
    *,
    maximum: int | None = None,
) -> bool:
    """Keep transient transport budget local to one immutable stage delivery.

    Project-level failure history is useful telemetry, but a discarded visual
    plan or operator restart must not make a new review open the browser after
    its first disconnect. The persisted rotation count follows only this stage
    across Celery redeliveries and therefore is the correct atomic budget.
    """
    limit = max(
        1,
        int(
            maximum
            if maximum is not None
            else os.getenv("HERMES_TEXT_API_MAX_FAILURES_BEFORE_BROWSER", "3")
        ),
    )
    return int(
        dict(stage_input or {}).get("text_api_transport_model_rotation_count")
        or 0
    ) >= limit


def _visual_api_provider_retry_delay(
    stage: str,
    stage_input: dict[str, Any],
    message: str,
) -> int | None:
    """Return a project-local retry delay for an explicitly failed image job.

    A content-factory stage can have a large historical attempt number after
    browser recovery, operator resumes, or an earlier provider incident. That
    history must not consume the retry budget of a newly submitted image API
    job. ``provider_retry_generation`` is persisted when the failed upstream
    task id is cleared, so each retry submits a new idempotency key and this
    small budget survives Celery redelivery without creating duplicate jobs.
    """
    if str(stage or "").upper() != "VISUAL_PREVIEW":
        return None
    lowered = str(message or "").lower()
    if not (
        "bandianwa image failed" in lowered
        or "bandianwa image reference" in lowered
        or "toapis image reference" in lowered
        or "toapis image transport error" in lowered
        or "toapis image download transport error" in lowered
        or ("gpt-image-2" in lowered and "task_failed" in lowered)
        or "bandianwa image transport error" in lowered
        or "bandianwa image content transport error" in lowered
        or "bandianwa image download transport error" in lowered
        or "sub2api image transport error" in lowered
        or "sub2api image download transport error" in lowered
    ):
        return None
    visual_api = dict(stage_input.get("visual_api") or {})
    boards = {
        str(key): dict(value)
        for key, value in dict(visual_api.get("boards") or {}).items()
        if isinstance(value, dict)
    }
    transport_failure = "transport error" in lowered
    if transport_failure:
        transport_count = max(
            int(visual_api.get("provider_transport_retry_count") or 0),
            max(
                (
                    int(board.get("provider_transport_retry_count") or 0)
                    for board in boards.values()
                ),
                default=0,
            ),
        )
        if transport_count <= 0:
            # Checkpoints created before transport failures received their own
            # counter stored the bounded attempt in provider_retry_generation.
            # Preserve that already-paid retry position after an in-place
            # deployment instead of treating the same transient timeout as
            # non-retryable merely because the newer field is absent.
            transport_count = max(
                0,
                int(visual_api.get("provider_retry_generation") or 0),
            )
        maximum = max(
            1,
            int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")),
        )
        if 0 < transport_count <= maximum:
            return min(180, 20 * (2 ** (transport_count - 1)))
        if transport_count > maximum:
            # Every enabled provider/model decision is made by the failover
            # layer. If the final route is still transport-unreachable, cool
            # down instead of falling through to browser or marking a render
            # model bad. This keeps unattended recovery alive without a hot
            # retry loop.
            return min(900, 300 * (2 ** min(2, transport_count - maximum - 1)))
        return None
    generation = max(0, int(visual_api.get("provider_retry_generation") or 0))
    maximum = max(1, int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")))
    if generation <= 0 or generation > maximum:
        return None
    return min(180, 20 * (2 ** (generation - 1)))


def _visual_provider_task_reusable_after_error(
    task_id: str | None,
    message: str,
) -> bool:
    """Keep a paid image task across transient poll/download failures."""
    if not str(task_id or "").strip():
        return False
    lowered = str(message or "").lower()
    terminal_markers = (
        "image failed:",
        "returned invalid image",
        "image output is empty",
        "content contains no image",
    )
    return not any(marker in lowered for marker in terminal_markers)


def _visual_prompt_semantic_rejection(message: str) -> bool:
    """Return true when a fresh, safety-preserving prompt can repair a request.

    Provider safety refusal is evidence that the *same* payload must not be
    replayed.  The isolated multimodal repair role may remove accidental
    ambiguity or unsafe framing while preserving user intent; it is expressly
    forbidden from weakening or evading the provider policy.
    """
    lowered = str(message or "").lower()
    repair_markers = (
        "content policy",
        "safety policy",
        "policy violation",
        "moderation_blocked",
        "moderation blocked",
        "prohibited content",
        "unsafe_generation",
        "public_error_unsafe_generation",
        "unsafe generation",
        "违规提示词",
        "内容违规",
        "安全策略",
        "重新调整提示词",
        "adjust prompt",
        "revise the prompt",
        "unexpected image",
        "did not generate as expected",
    )
    return any(marker in lowered for marker in repair_markers)


def _visual_api_account_quota_exhausted(stage: str, message: str) -> bool:
    """Detect image-account balance failures that waiting cannot repair.

    Provider rate limits and transient task failures deserve bounded retries.
    A pre-charge rejection with an explicit insufficient balance does not:
    resubmitting the same key only burns queue time while the balance remains
    unchanged. VISUAL_PREVIEW should activate its retained browser fallback
    immediately, preserving any already-approved reference images.
    """
    if str(stage or "").upper() != "VISUAL_PREVIEW":
        return False
    lowered = str(message or "").lower()
    markers = (
        "insufficient_user_quota",
        "quota_not_enough",
        "insufficient quota",
        "insufficient balance",
        # Sub2API accepts the asynchronous image request before its account
        # pool selects a compatible upstream session. This terminal poll
        # result is an account-pool availability failure, not a render miss
        # that can improve by paying the same provider for the same prompt
        # three more times. Rotate to the next prioritized image provider.
        "no available compatible accounts",
        "no compatible accounts available",
        "remaining balance",
        "pre-charge failed",
        "预扣费额度失败",
        "用户剩余额度",
        "需要预扣费额度",
        "余额不足",
    )
    return any(marker in lowered for marker in markers)


def _prepare_visual_api_provider_failover(
    stage_input: dict[str, Any],
    *,
    from_provider: str,
    to_provider: str,
    error: str,
    account_quota_exhausted: bool = True,
    from_route: str | None = None,
    to_route: str | None = None,
) -> dict[str, Any]:
    """Keep completed boards and reset only failed/unsubmitted provider work."""
    values = json.loads(json.dumps(dict(stage_input or {})))
    visual_api = dict(values.get("visual_api") or {})
    boards = dict(visual_api.get("boards") or {})
    for key, raw in list(boards.items()):
        board = dict(raw or {})
        if str(board.get("status") or "").lower() != "completed":
            board.update({
                "status": "pending_provider_failover",
                "task_id": None,
                "provider_retry_generation": 0,
                "provider_transport_retry_count": 0,
            })
        boards[str(key)] = board
    failures = dict(visual_api.get("provider_failures") or {})
    failures[str(from_provider)] = {
        "account_quota_exhausted": bool(account_quota_exhausted),
        "retry_budget_exhausted": not bool(account_quota_exhausted),
        "error": str(error or "")[:800],
        "failed_at": _stage_now().isoformat(),
    }
    exact_from_route = str(
        from_route or _visual_api_route_for_provider(from_provider)
    ).strip().lower()
    exact_to_route = str(
        to_route or _visual_api_route_for_provider(to_provider)
    ).strip().lower()
    route_failures = dict(visual_api.get("route_failures") or {})
    route_failures[exact_from_route] = {
        "account_quota_exhausted": bool(account_quota_exhausted),
        "retry_budget_exhausted": not bool(account_quota_exhausted),
        "error": str(error or "")[:800],
        "failed_at": _stage_now().isoformat(),
    }
    visual_api.update({
        "provider": str(to_provider),
        "model": _visual_api_model_from_route(exact_to_route),
        "status": "provider_failover_pending",
        "task_id": None,
        "provider_retry_generation": 0,
        "provider_transport_retry_count": 0,
        "account_quota_exhausted": False,
        "bandianwa_account_quota_exhausted": (
            (
                bool(account_quota_exhausted)
                and str(from_provider) == BANDIANWA_PROVIDER_KEY
            )
            or bool(visual_api.get("bandianwa_account_quota_exhausted"))
        ),
        "provider_failures": failures,
        "route_failures": route_failures,
        "boards": boards,
        "last_error": str(error or "")[:800],
        "provider_failover_at": _stage_now().isoformat(),
    })
    values.update({
        "visual_api": visual_api,
        "execution_backend": "api",
        "api_route": exact_to_route,
        "visual_api_skip_bandianwa": (
            str(from_provider) == BANDIANWA_PROVIDER_KEY
            or bool(values.get("visual_api_skip_bandianwa"))
        ),
        "self_heal_action": f"failover_{from_provider}_to_{to_provider}",
    })
    for key in (
        "api_fallback_to_browser",
        "api_force_browser_fallback",
        "api_browser_fallback_attempted",
        "visual_api_force_browser_fallback",
        "visual_grid_browser_fallback_attempted",
    ):
        values.pop(key, None)
    return values


def _prepare_visual_api_provider_inheritance(
    stage_input: dict[str, Any],
    *,
    to_provider: str,
    to_route: str | None = None,
) -> dict[str, Any]:
    """Adopt a variant-owned route without declaring the old route failed.

    Provider inheritance is a routing migration performed before submission,
    not evidence of an upstream failure.  Recording the migration in
    ``provider_failures`` poisoned the circuit ledger and could make the next
    retry rotate back to an already exhausted provider.
    """
    values = json.loads(json.dumps(dict(stage_input or {})))
    visual_api = dict(values.get("visual_api") or {})
    boards: dict[str, Any] = {}
    for key, raw in dict(visual_api.get("boards") or {}).items():
        board = dict(raw or {})
        if str(board.get("status") or "").lower() != "completed":
            board.update({
                "status": "pending_provider_inheritance",
                "task_id": None,
                "provider_retry_generation": 0,
                "provider_transport_retry_count": 0,
            })
        boards[str(key)] = board
    exact_to_route = str(
        to_route or _visual_api_route_for_provider(to_provider)
    ).strip().lower()
    visual_api.update({
        "provider": str(to_provider),
        "model": _visual_api_model_from_route(exact_to_route),
        "status": "provider_inheritance_pending",
        "task_id": None,
        "provider_retry_generation": 0,
        "provider_transport_retry_count": 0,
        "boards": boards,
        "provider_inherited_at": _stage_now().isoformat(),
    })
    values.update({
        "visual_api": visual_api,
        "execution_backend": "api",
        "api_route": exact_to_route,
        "self_heal_action": f"inherit_variant_visual_provider_{to_provider}",
    })
    return values


def _prepare_visual_image_model_failover(
    stage_input: dict[str, Any],
    *,
    from_model: str,
    to_model: str,
    next_index: int,
    error: str,
) -> dict[str, Any]:
    """Rotate a project-owned image-model chain without reusing paid tasks.

    A model change is a new rendering identity. Reset every board checkpoint
    so one mother canvas cannot mix character/style authorities from two
    models. Historical files remain as audit evidence but are not selected by
    the new run; model is also part of every provider idempotency key.
    """

    values = json.loads(json.dumps(dict(stage_input or {})))
    prior = dict(values.get("visual_api") or {})
    failures = list(prior.get("model_failures") or [])
    failures.append({
        "model": str(from_model),
        "error": str(error or "")[:800],
        "failed_at": _stage_now().isoformat(),
    })
    values["visual_api"] = {
        "provider": str(prior.get("provider") or BANDIANWA_PROVIDER_KEY),
        "model": str(to_model),
        "status": "model_failover_pending",
        "provider_retry_generation": 0,
        "boards": {},
        "model_failures": failures[-8:],
        "model_failover_at": _stage_now().isoformat(),
    }
    values["visual_image_model_index"] = max(0, int(next_index))
    values["self_heal_action"] = (
        f"failover_image_model_{from_model}_to_{to_model}"
    )[:255]
    return values


def _visual_api_provider_budget_exhausted(
    stage: str,
    stage_input: dict[str, Any],
) -> bool:
    """Return true only after every bounded API image generation failed."""
    if str(stage or "").upper() != "VISUAL_PREVIEW":
        return False
    visual_api = dict(stage_input.get("visual_api") or {})
    maximum = max(1, int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")))
    return bool(
        str(visual_api.get("status") or "").lower() in {"failed", "partial_failed"}
        and not str(visual_api.get("task_id") or "").strip()
        and int(visual_api.get("provider_retry_generation") or 0) > maximum
    )


def _visual_api_submission_transport_budget_exhausted(
    stage: str,
    stage_input: dict[str, Any],
) -> bool:
    """Return true after repeated pre-task POST transport failures.

    No image model has accepted a task in this failure mode. It must rotate
    API providers while preserving completed references, never rotate the
    image model and regenerate successful paid images.
    """
    if str(stage or "").upper() != "VISUAL_PREVIEW":
        return False
    visual_api = dict(stage_input.get("visual_api") or {})
    maximum = max(
        1,
        int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")),
    )
    for raw in dict(visual_api.get("boards") or {}).values():
        board = dict(raw or {})
        if str(board.get("status") or "").lower() != "failed":
            continue
        if str(board.get("task_id") or "").strip():
            continue
        if "transport error during post" not in str(
            board.get("last_error") or ""
        ).lower():
            continue
        if int(board.get("provider_transport_retry_count") or 0) > maximum:
            return True
    return False


def _visual_api_final_provider_budget_exhausted(
    stage: str,
    stage_input: dict[str, Any],
    *,
    api_route: str,
    db=None,
) -> bool:
    """Allow browser only after the last configured image API exhausts itself.

    Project-level API failure counters intentionally span deliveries and are
    useful for diagnostics, but they include providers already abandoned. They
    must never make a fresh ToAPIs generation inherit Bandianwa's budget.
    """
    if not _visual_api_provider_budget_exhausted(stage, stage_input):
        return False
    if db is None:
        # Compatibility for isolated callers created before route-table
        # authority. Production always supplies the database session.
        return str(api_route or "").strip() == "toapis:gpt-image-2"
    return _next_visual_api_route(
        db,
        current_route=api_route,
        stage_input=stage_input,
    ) is None


def _retry_release_routing(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    stage_input: dict[str, Any],
) -> tuple[str | None, str | None, str]:
    """Route API retries without acquiring an unrelated Chrome slot.

    Browser capacity is required only for browser stages or after the bounded
    image API budget has been exhausted and the stage is explicitly failing
    over to the retained ChatGPT browser path.
    """
    api_route = _content_factory_api_route(db, stage_row.stage, stage_input)
    execution_backend = stage_execution_backend(
        stage_row.stage,
        api_route=api_route,
        stage_input=stage_input,
    )
    if (
        _visual_api_provider_budget_exhausted(stage_row.stage, stage_input)
        and _next_visual_api_route(
            db,
            current_route=str(stage_input.get("api_route") or api_route or ""),
            stage_input=stage_input,
        )
    ):
        # The next delivery will atomically convert this stage to the next
        # platform-prioritized image API.
        # Keep it on the API worker; acquiring a Chrome slot here caused the
        # browser open/close loop while no browser work was actually required.
        return None, None, project_hermes_queue(project)
    if execution_backend != "browser" and not _visual_api_provider_budget_exhausted(
        stage_row.stage,
        stage_input,
    ):
        return None, None, project_hermes_queue(project)
    return _locked_browser_routing(db, project, stage_input)


def _bounded_rate_limit_retry_delay(
    message: str,
    learned_wait_seconds: int,
    *,
    entropy_key: str,
) -> int:
    """Prefer a current page-provided cooldown over stale historical samples.

    The adaptive model remains authoritative when ChatGPT provides no duration.
    When the current interruption includes ``retry_after_seconds``, that fresh
    observation is a stronger signal; learning may add human-like jitter but
    must not turn a five-minute cooldown into a multi-hour stall.
    """
    match = re.search(r"retry_after_seconds\s*=\s*(\d+)", str(message or "").lower())
    learned = max(30, min(86400, int(learned_wait_seconds)))
    if not match:
        return learned
    explicit = max(30, min(86400, int(match.group(1))))
    jitter = _stable_seconds_jitter(
        f"{entropy_key}:explicit-rate-limit:{explicit}",
        minimum=max(5, explicit // 40),
        maximum=max(15, explicit // 8),
    )
    return min(max(explicit, learned), min(86400, explicit + jitter))


def _recoverable_response_retry_plan(stage_input: dict[str, Any]) -> dict[str, Any] | None:
    """Alternate late-response recovery with a bounded fresh regeneration.

    Re-reading one truncated assistant turn on every retry never changes the
    result. Conversely, immediately opening a new conversation can duplicate
    a reply that is still rendering. One project delivery therefore probes the
    existing turn first; only a failed probe permits one fresh submission.
    Three bounded cycles are enough to survive renderer delays without keeping
    a project or browser slot in an endless loop.
    """
    mode = str(stage_input.get("browser_recovery_mode") or "").strip()
    recovering_existing = mode.startswith("recover_existing_response")
    if recovering_existing:
        fresh_count = int(stage_input.get("response_fresh_regeneration_count") or 0) + 1
        if fresh_count > MAX_RESPONSE_REGENERATION_CYCLES:
            return None
        return {
            "delay": 20,
            "force_fresh_response": True,
            "browser_recovery_mode": "fresh_composer_after_invalid_recovered_response",
            "clear_stale_composer_before_send": True,
            "response_fresh_regeneration_count": fresh_count,
            "response_recovery_probe_count": int(stage_input.get("response_recovery_probe_count") or 0),
        }

    probe_count = int(stage_input.get("response_recovery_probe_count") or 0) + 1
    if probe_count > MAX_RESPONSE_REGENERATION_CYCLES:
        return None
    return {
        "delay": 45,
        "force_fresh_response": False,
        "browser_recovery_mode": "recover_existing_response_then_fresh_composer",
        "clear_stale_composer_before_send": False,
        "late_response_probe_seconds": 120,
        "response_recovery_probe_count": probe_count,
        "response_fresh_regeneration_count": int(stage_input.get("response_fresh_regeneration_count") or 0),
    }


def _recoverable_visual_retry_plan(stage_input: dict[str, Any]) -> dict[str, Any] | None:
    """Bound visual recovery to alternating capture probes and fresh renders.

    A generated ChatGPT image can become visible just after the browser task
    times out, so the first recovery must scan the existing project tab. If
    that scan still yields no persisted image, repeating the same scan cannot
    change the result: permit one fresh image request, then probe again. The
    counters survive broker retries and cap both branches, preventing a visual
    stage from holding one project-owned browser slot forever.
    """
    mode = str(stage_input.get("browser_recovery_mode") or "").strip()
    recovering_visible = mode.startswith("recover_visible_visual")
    if recovering_visible:
        fresh_count = int(stage_input.get("visual_fresh_regeneration_count") or 0) + 1
        if fresh_count > MAX_VISUAL_REGENERATION_CYCLES:
            return None
        return {
            "delay": 20,
            "allow_visible_visual_recovery": False,
            "force_fresh_response": True,
            "browser_recovery_mode": "fresh_visual_after_missing_visible_media",
            "clear_stale_composer_before_send": True,
            "visual_fresh_regeneration_count": fresh_count,
            "visual_recovery_probe_count": int(stage_input.get("visual_recovery_probe_count") or 0),
            "visual_recovery_exhausted": False,
        }

    probe_count = int(stage_input.get("visual_recovery_probe_count") or 0) + 1
    if probe_count > MAX_VISUAL_REGENERATION_CYCLES:
        return None
    return {
        "delay": 15,
        "allow_visible_visual_recovery": True,
        "force_fresh_response": False,
        "browser_recovery_mode": "recover_visible_visual_from_project_tabs",
        "clear_stale_composer_before_send": False,
        "visual_recovery_probe_count": probe_count,
        "visual_fresh_regeneration_count": int(stage_input.get("visual_fresh_regeneration_count") or 0),
        "visual_recovery_exhausted": False,
    }


def _latest_stage(db, project: HermesContentFactoryProject, stage: str) -> HermesContentFactoryStage | None:
    """Return the newest stage that was actually admitted for execution.

    ``_publish_stage`` persists rejected concurrent deliveries as failed audit
    rows.  Those rows have a larger id, but they never owned execution
    authority and therefore must not fence the admitted owner at task start,
    provider submission, completion, or self-heal.
    """
    return (
        db.query(HermesContentFactoryStage)
        .filter(HermesContentFactoryStage.project_id == project.id, HermesContentFactoryStage.stage == stage)
        .filter(
            or_(
                HermesContentFactoryStage.status != "failed",
                HermesContentFactoryStage.error_message.is_(None),
                ~HermesContentFactoryStage.error_message.like(
                    "Duplicate publish suppressed:%"
                ),
            )
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .first()
    )


_DUPLICATE_PUBLISH_OWNER_RE = re.compile(
    r"Duplicate publish suppressed:\s*active stage\s+(\d+)\b",
    flags=re.IGNORECASE,
)


def _authoritative_self_heal_stage(
    db,
    project: HermesContentFactoryProject,
    stage_name: str,
    *,
    now: datetime,
) -> HermesContentFactoryStage | None:
    """Resolve the stage that still owns recovery authority.

    A concurrent recovery can create a newer repair row while an older row
    still owns the project execution lease. ``_publish_stage`` correctly
    suppresses that newer delivery and records the older owner id.  Selecting
    stages by descending id alone then inverts that decision: periodic
    self-heal treats the rejected duplicate as authoritative and fails the
    real owner.  In the worst ordering both rows become failed and the project
    remains queued forever.

    Follow only the explicit, project-scoped owner reference written by
    ``_publish_stage``.  A previously damaged owner can be restored only when
    the exact reciprocal self-heal tombstone is present and it never reached a
    terminal completion.  This keeps ordinary historical failures terminal
    and makes the repair idempotent.
    """

    latest = _latest_stage(db, project, stage_name)
    if latest is None:
        return None
    latest_error = str(latest.error_message or "").strip()
    match = _DUPLICATE_PUBLISH_OWNER_RE.search(latest_error)
    if match:
        owner_id = int(match.group(1))
        owner = db.get(HermesContentFactoryStage, owner_id)
        if (
            owner is None
            or int(owner.project_id) != int(project.id)
            or str(owner.stage or "") != str(stage_name or "")
            or int(owner.id) >= int(latest.id)
        ):
            return latest
        if str(owner.status or "").lower() in {"queued", "running", "retrying"}:
            return owner
        duplicate = latest
    else:
        owner = latest
        duplicate = (
            db.query(HermesContentFactoryStage)
            .filter(
                HermesContentFactoryStage.project_id == int(project.id),
                HermesContentFactoryStage.stage == str(stage_name),
                HermesContentFactoryStage.id > int(owner.id),
                HermesContentFactoryStage.status == "failed",
                HermesContentFactoryStage.error_message.like(
                    f"Duplicate publish suppressed: active stage {int(owner.id)} %"
                ),
            )
            .order_by(HermesContentFactoryStage.id.desc())
            .first()
        )
        if duplicate is None:
            return latest

    owner_error = str(owner.error_message or "")
    reciprocal_tombstone = (
        str(owner.status or "").lower() == "failed"
        and owner.completed_at is None
        and (
            (
                owner_error.startswith(
                    f"Superseded by latest {stage_name} stage {int(duplicate.id)}; "
                )
                and "self-heal cleaned duplicate broker delivery" in owner_error
            )
            or owner_error.startswith(
                f"Superseded by newer {stage_name} stage {int(duplicate.id)}; "
                "old broker delivery ignored before touching the browser."
            )
        )
    )
    if not reciprocal_tombstone:
        return latest

    owner_input = dict(owner.input_json or {})
    owner.status = (
        "retrying" if str(owner_input.get("retry_after") or "").strip() else "queued"
    )
    owner.error_message = str(
        dict(owner_input.get("last_recovery_supervisor_decision") or {}).get(
            "diagnosis"
        )
        or "Recovered the authoritative stage after a duplicate-publish race."
    )[:4000]
    owner.celery_task_id = None
    owner_input["duplicate_publish_race_recovered_at"] = now.isoformat()
    owner_input["duplicate_publish_race_duplicate_stage_id"] = int(duplicate.id)
    owner.input_json = owner_input
    db.add(owner)
    return owner


def _locked_browser_routing(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any] | None,
) -> tuple[str, str, str]:
    """Return the project's locked user-owned bridge route without drifting.

    The stage may carry a stale browser_cdp_url from a previous retry, but the
    database bridge row is the authority. Never fall back to numeric slot or
    process HERMES_CDP_URL here; that can send another user's project to the
    wrong local Chrome session.
    """
    from app.services.hermes_agent.content_factory import (
        _acquire_project_bridge,
        _bridge_connected,
        _bridge_matches_preferred_device,
        _recover_degraded_bridge_if_reachable,
        project_hermes_queue,
    )

    values = dict(stage_input or {})
    state = dict(project.state_json or {})
    force_reacquire = bool(values.get("force_reacquire_browser_bridge"))
    if force_reacquire:
        probe_bridge_id = str(
            values.get("browser_bridge_id")
            or state.get("browser_bridge_id")
            or values.get("browser_slot")
            or ""
        ).strip()
        probe_cdp_url = str(
            values.get("browser_cdp_url")
            or state.get("browser_cdp_url")
            or ""
        ).strip()
        probe_query = db.query(HermesBrowserBridge).filter(
            HermesBrowserBridge.workspace_id == int(project.workspace_id),
            HermesBrowserBridge.user_id == int(project.user_id or 0),
        )
        recovered_bridge = None
        if probe_bridge_id.startswith("br_"):
            recovered_bridge = probe_query.filter(
                HermesBrowserBridge.bridge_id == probe_bridge_id,
            ).one_or_none()
        if recovered_bridge is None and probe_cdp_url:
            recovered_bridge = probe_query.filter(
                HermesBrowserBridge.cdp_url == probe_cdp_url,
            ).order_by(HermesBrowserBridge.updated_at.desc()).first()
        if recovered_bridge is not None and recovered_bridge.active_project_id in (None, int(project.id)):
            recovered = _bridge_connected(recovered_bridge)
            if not recovered:
                recovered = _recover_degraded_bridge_if_reachable(
                    recovered_bridge,
                    now=_stage_now(),
                )
            if recovered:
                force_reacquire = False
                values.pop("force_reacquire_browser_bridge", None)
                values["force_reacquire_consumed_at"] = _stage_now().isoformat()
                values["browser_bridge_id"] = str(recovered_bridge.bridge_id)
                values["browser_slot"] = str(recovered_bridge.bridge_id)
                values["browser_cdp_url"] = str(recovered_bridge.cdp_url or "")
                values["browser_inbox_root"] = str(recovered_bridge.inbox_root or "")
                db.add(recovered_bridge)
                if stage_input is not None:
                    stage_input.clear()
                    stage_input.update(values)
    if force_reacquire:
        values = _mark_locked_project_bridge_degraded(
            db,
            project,
            values,
            reason=str(values.get("self_heal_reason") or values.get("browser_recovery_mode") or "forced bridge reacquire"),
        )
        state = dict(project.state_json or {})
        values.pop("force_reacquire_browser_bridge", None)
        values.pop("force_reacquire_consumed_at", None)
    browser_slot_value = str(values.get("browser_slot") or "").strip()
    bridge_id = str(values.get("browser_bridge_id") or state.get("browser_bridge_id") or "").strip()
    if not bridge_id and browser_slot_value.startswith("br_"):
        bridge_id = browser_slot_value
    browser_cdp_url = str(values.get("browser_cdp_url") or state.get("browser_cdp_url") or "").strip()
    query = db.query(HermesBrowserBridge).filter(
        HermesBrowserBridge.workspace_id == int(project.workspace_id),
        HermesBrowserBridge.user_id == int(project.user_id or 0),
    )
    bridge = None
    if bridge_id and not force_reacquire:
        bridge = query.filter(HermesBrowserBridge.bridge_id == bridge_id).one_or_none()
    if bridge is None and browser_cdp_url and not force_reacquire:
        bridge = query.filter(HermesBrowserBridge.cdp_url == browser_cdp_url).order_by(HermesBrowserBridge.updated_at.desc()).first()
    if bridge is None and not force_reacquire:
        bridge = query.filter(HermesBrowserBridge.active_project_id == int(project.id)).order_by(HermesBrowserBridge.updated_at.desc()).first()
    preferred_device_id = str(state.get("preferred_browser_device_id") or "").strip()
    if bridge is not None and preferred_device_id and not _bridge_matches_preferred_device(bridge, preferred_device_id):
        bridge = None
    if bridge is None or bridge.active_project_id is None or not _bridge_connected(bridge):
        bridge = _acquire_project_bridge(
            db,
            project=project,
            user_id=int(project.user_id or 0),
        )
    if bridge is None:
        raise ValueError(
            "BROWSER_BRIDGE_LOCK_MISSING: project has no browser bridge locked for this workspace/user. "
            "Reconnect this user's local bridge and resume the project."
        )
    if bridge.active_project_id not in (None, int(project.id)):
        raise ValueError(
            "BROWSER_BRIDGE_LOCK_CONFLICT: locked bridge is occupied by another project for this user."
        )
    browser_slot = str(bridge.bridge_id)
    browser_cdp_url = str(bridge.cdp_url or "").strip()
    if not browser_cdp_url:
        raise ValueError("BROWSER_BRIDGE_CDP_MISSING: locked bridge has no CDP URL.")
    queue_name = str(values.get("queue") or "").strip() or project_hermes_queue(project)
    if force_reacquire:
        values["force_reacquire_consumed_at"] = _stage_now().isoformat()
        values["browser_bridge_id"] = str(bridge.bridge_id)
        values["browser_device_id"] = str(bridge.device_id or "")
        values["browser_device_name"] = str(bridge.device_name or "")
        values["browser_cdp_url"] = browser_cdp_url
        values["browser_inbox_root"] = str(bridge.inbox_root or "")
        values["browser_slot"] = str(bridge.bridge_id)
        stage_input.clear()
        stage_input.update(values)
    return browser_slot, browser_cdp_url, queue_name


def _mark_locked_project_bridge_degraded(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
    *,
    reason: str,
) -> dict[str, Any]:
    """Keep the project pinned and ask the same slot to restart/recover.

    A content-factory project owns one browser slot for its whole browser
    workflow. CDP failures must not clear the route and acquire a different
    slot, because that can create duplicate ChatGPT sessions and cross-project
    state drift. Pause/delete/complete are the only normal release paths.
    """
    state = dict(project.state_json or {})
    bridge_id = str(stage_input.get("browser_bridge_id") or state.get("browser_bridge_id") or "").strip()
    cdp_url = str(stage_input.get("browser_cdp_url") or state.get("browser_cdp_url") or "").strip()
    query = db.query(HermesBrowserBridge).filter(
        HermesBrowserBridge.workspace_id == int(project.workspace_id),
        HermesBrowserBridge.user_id == int(project.user_id or 0),
    )
    bridge = None
    if bridge_id:
        bridge = query.filter(HermesBrowserBridge.bridge_id == bridge_id).one_or_none()
    if bridge is None and cdp_url:
        bridge = query.filter(HermesBrowserBridge.cdp_url == cdp_url).order_by(HermesBrowserBridge.updated_at.desc()).first()
    if bridge is not None and bridge.active_project_id in (None, int(project.id)):
        bridge.active_project_id = int(project.id)
        bridge.active_stage_id = None
        bridge.lease_expires_at = _stage_now() + timedelta(hours=2)
        bridge.status = "pending"
        bridge_load = dict(bridge.load_json or {})
        bridge_load["agent_error"] = f"server requested same-slot restart: {str(reason)[:420]}"
        bridge_load["last_degraded_reason"] = str(reason)[:800]
        bridge_load["last_degraded_project_id"] = int(project.id)
        bridge_load["last_degraded_at"] = _stage_now().isoformat()
        bridge.load_json = bridge_load
        bridge_meta = dict(bridge.meta_json or {})
        bridge_meta["last_degraded_reason"] = str(reason)[:800]
        bridge_meta["last_degraded_project_id"] = int(project.id)
        bridge_meta["last_degraded_at"] = _stage_now().isoformat()
        bridge.meta_json = bridge_meta
        db.add(bridge)
        state["browser_bridge_id"] = str(bridge.bridge_id)
        state["browser_device_id"] = str(bridge.device_id or "")
        state["browser_device_name"] = str(bridge.device_name or "")
        state["browser_cdp_url"] = str(bridge.cdp_url or "")
        state["browser_inbox_root"] = str(bridge.inbox_root or "")
        state["browser_lease_expires_at"] = bridge.lease_expires_at.isoformat()
        stage_input["browser_bridge_id"] = str(bridge.bridge_id)
        stage_input["browser_slot"] = str(bridge.bridge_id)
        stage_input["browser_cdp_url"] = str(bridge.cdp_url or "")
        stage_input["browser_inbox_root"] = str(bridge.inbox_root or "")
    runtime_learning = dict(state.get("hermes_runtime_learning") or {})
    bridge_learning = dict(runtime_learning.get("browser_bridge") or {})
    bridge_learning.update({
        "last_degraded_reason": str(reason)[:800],
        "last_degraded_bridge_id": bridge_id or None,
        "last_degraded_cdp_url": cdp_url or None,
        "next_retry_should_reacquire_bridge": False,
        "sticky_slot_restart_requested": True,
        "updated_at": _stage_now().isoformat(),
    })
    runtime_learning["browser_bridge"] = bridge_learning
    state["hermes_runtime_learning"] = runtime_learning
    state["browser_bridge_lock_policy"] = "project_sticky_slot"
    project.state_json = state
    db.add(project)
    return stage_input


def _release_degraded_project_bridge(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
    *,
    reason: str,
) -> dict[str, Any]:
    return _mark_locked_project_bridge_degraded(db, project, stage_input, reason=reason)


def _queue_existing_stage(db, project: HermesContentFactoryProject, stage: HermesContentFactoryStage, *, reason: str) -> None:
    stage_input = dict(stage.input_json or {})
    scheduled_retry_release = str(reason or "").strip() == (
        "periodic self-heal released due retry"
    )
    # Manual/self-heal requeue supersedes any delayed release belonging to the
    # previous delivery.  Leaving that timer in the broker can dispatch a
    # second API call beside the newly published stage.
    prior_retry_release_token = str(stage_input.get("retry_release_task_id") or "").strip()
    if prior_retry_release_token:
        _safe_revoke_task(prior_retry_release_token)
    api_route = _content_factory_api_route(db, stage.stage, stage_input)
    execution_backend = stage_execution_backend(
        stage.stage,
        api_route=api_route,
        stage_input=stage_input,
    )
    if execution_backend != "browser":
        browser_slot = ""
        browser_cdp_url = ""
        queue_name = project_hermes_queue(project)
    else:
        browser_slot, browser_cdp_url, queue_name = _locked_browser_routing(db, project, stage_input)
    recovery_message = " ".join((
        str(reason or ""),
        str(stage.error_message or ""),
        str(project.last_error or ""),
    ))
    original_reason = str(stage_input.get("self_heal_reason") or "").strip()
    if not original_reason:
        stage_input["self_heal_reason"] = reason
    elif str(reason or "").strip() and str(reason).strip() != original_reason:
        # Republish cause and root repair contract are different facts. Do not
        # erase operator constraints (for example exactly-one-adult) merely
        # because the periodic watchdog renewed a queued delivery.
        stage_input["last_requeue_reason"] = str(reason).strip()
        stage_input["root_self_heal_reason"] = str(
            stage_input.get("root_self_heal_reason") or original_reason
        )
    stage_input["self_heal_count"] = int(stage_input.get("self_heal_count") or 0) + 1
    stage_input["self_heal_policy_version"] = SELF_HEAL_POLICY_VERSION
    # ``automatic_retry_count`` belongs to the broker delivery that just
    # finished. A formal self-heal requeue creates a new delivery and must get
    # a fresh bounded retry budget. Carrying an exhausted value forward makes
    # the replacement task fail with "Automatic recovery limit reached"
    # before it performs any browser work.
    stage_input["automatic_retry_count"] = 0
    if (
        _is_recoverable_chatgpt_response_error(recovery_message)
        and not scheduled_retry_release
    ):
        stage_input["force_fresh_response"] = False
        stage_input["browser_recovery_mode"] = "recover_existing_response_then_fresh_composer"
        stage_input["clear_stale_composer_before_send"] = False
        stage_input["late_response_probe_seconds"] = 120
        # A formal operator/watchdog recovery starts a new bounded sequence.
        # The normal due-at retry release is different: it is the next step of
        # the same probe/fresh alternation and therefore retains these counters
        # and the exact recovery mode. Resetting them on every due-at release
        # silently turns a three-cycle guard into an infinite browser loop.
        stage_input.pop("response_recovery_probe_count", None)
        stage_input.pop("response_fresh_regeneration_count", None)
    elif "browser" in reason.lower() or "composer" in reason.lower() or "prompt" in reason.lower():
        stage_input["force_fresh_response"] = True
        stage_input["browser_recovery_mode"] = "fresh_composer_after_prompt_stuck"
        stage_input["clear_stale_composer_before_send"] = True
    if execution_backend != "browser":
        stage_input["execution_backend"] = execution_backend
        if api_route:
            stage_input["api_route"] = api_route
        else:
            stage_input.pop("api_route", None)
        stage_input.pop("browser_slot", None)
        stage_input.pop("browser_bridge_id", None)
        stage_input.pop("browser_cdp_url", None)
        stage_input.pop("browser_device_id", None)
        stage_input.pop("browser_device_name", None)
        stage_input.pop("browser_inbox_root", None)
    else:
        stage_input["browser_slot"] = browser_slot
        stage_input["browser_bridge_id"] = browser_slot
        stage_input["browser_cdp_url"] = browser_cdp_url
    stage_input["queue"] = queue_name
    stage_input.pop("run_token", None)
    stage_input.pop("retry_release_task_id", None)
    stage_input.pop("retry_after", None)
    stage.input_json = stage_input
    stage.status = "queued"
    stage.error_message = None
    stage.celery_task_id = None
    stage.started_at = None
    stage.completed_at = None
    project.current_stage = stage.stage
    project.status = "queued"
    project.last_error = None


def _inherit_self_heal_circuit_history(source: dict[str, Any], target: dict[str, Any]) -> dict[str, Any]:
    for key in SELF_HEAL_CIRCUIT_HISTORY_FIELDS:
        if key in source:
            target[key] = source[key]
    return target


def _next_stage_attempt(
    db: Session,
    *,
    project_id: int,
    stage_name: str,
) -> int:
    """Allocate an immutable attempt number from every durable stage row.

    Execution-authority selectors deliberately ignore rejected duplicate-
    publish audit rows.  Attempt allocation must not use those selectors:
    the audit row still owns its unique ``project+stage+attempt`` identity.
    Reusing the apparent authority row's attempt therefore raises a duplicate
    key error and can turn a successful predecessor into a failed project.
    """
    latest_attempt = (
        db.query(func.max(HermesContentFactoryStage.attempt))
        .filter(
            HermesContentFactoryStage.project_id == int(project_id),
            HermesContentFactoryStage.stage == str(stage_name),
        )
        .scalar()
    )
    return int(latest_attempt or 0) + 1


def _create_repair_stage(
    db,
    project: HermesContentFactoryProject,
    stage_name: str,
    *,
    reason: str,
    continue_workflow: bool = True,
) -> HermesContentFactoryStage:
    project_state = dict(project.state_json or {})
    pipeline = dict(project_state.get("video_variant_pipeline") or {})
    project_config = dict(project.config_json or {})
    global_latest = _latest_stage(db, project, stage_name)
    global_latest_input = dict(global_latest.input_json or {}) if global_latest is not None else {}
    variant_total = max(
        1,
        int(
            project_config.get("video_count")
            or pipeline.get("target_count")
            or global_latest_input.get("variant_total")
            or 1
        ),
    )
    authoritative_variant = (
        pipeline.get("active_index")
        or project_state.get("active_variant_index")
        or global_latest_input.get("variant_index")
        or 1
    )
    variant_index = max(1, min(variant_total, int(authoritative_variant)))
    # A repair for a variant-owned stage must inherit only that variant's
    # packet.  Project-global "latest" may already belong to the next variant;
    # reading it first silently crosses creative, reference, and execution
    # identities (for example a v24 repair dispatched as v25).
    latest = (
        _latest_variant_stage(db, project, stage_name, variant_index)
        if stage_name in VARIANT_STAGES
        else global_latest
    )
    source_input = dict(latest.input_json or {}) if latest is not None else {}
    api_route = _content_factory_api_route(db, stage_name, source_input)
    execution_backend = stage_execution_backend(
        stage_name,
        api_route=api_route,
        stage_input=source_input,
    )
    if execution_backend == "browser":
        browser_slot, browser_cdp_url, queue_name = _locked_browser_routing(
            db,
            project,
            source_input,
        )
    else:
        browser_slot, browser_cdp_url, queue_name = "", "", project_hermes_queue(project)
    # Attempts are unique per project+stage, not per variant.  Allocate from
    # every durable row, including duplicate-publish audit rows which are
    # intentionally excluded from ``_latest_stage`` execution authority.
    next_attempt = _next_stage_attempt(
        db,
        project_id=int(project.id),
        stage_name=stage_name,
    )
    if latest is not None and latest.status == "success":
        latest.error_message = f"Superseded by self-heal: {reason}"[:4000]
    repair_input = {
        "continue_workflow": continue_workflow,
        "execution_backend": execution_backend,
        "self_heal_reason": reason,
        "self_heal_count": int(source_input.get("self_heal_count") or 0) + 1,
        "self_heal_policy_version": SELF_HEAL_POLICY_VERSION,
        "queue": queue_name,
        "variant_index": variant_index,
        "variant_total": variant_total,
        "variant_mode": source_input.get("variant_mode") or (
            "serial_one_complete_video_at_a_time" if variant_total > 1 else "single_batch"
        ),
    }
    _inherit_self_heal_circuit_history(source_input, repair_input)
    if api_route:
        repair_input["api_route"] = api_route
    if execution_backend == "browser":
        repair_input.update({
            "browser_slot": browser_slot,
            "browser_bridge_id": browser_slot,
            "browser_cdp_url": browser_cdp_url,
        })
    if stage_name == "VISUAL_PREVIEW" and "review" in str(reason or "").lower():
        repair_input.update({
            "force_fresh_response": True,
            "clear_stale_composer_before_send": True,
            "allow_visible_visual_recovery": False,
            "self_heal_action": "regenerate_visual_after_blocking_creative_review",
            "visual_repair_instruction": str(reason or "")[:4000],
        })
    stage = HermesContentFactoryStage(
        project_id=project.id,
        workspace_id=project.workspace_id,
        user_id=project.user_id,
        stage=stage_name,
        attempt=next_attempt,
        status="queued",
        instruction=None,
        input_json=repair_input,
    )
    db.add(stage)
    project.current_stage = stage_name
    project.status = "queued"
    project.last_error = None
    db.flush()
    return stage


def _production_plan_director_replan_feedback(
    stage: HermesContentFactoryStage | None,
) -> list[dict[str, Any]]:
    """Return structured upstream repair evidence from a plan quality pause.

    A Production Plan critic can explicitly declare that the approved
    Director artifact is the layer that must change.  Retrying the same plan
    cannot satisfy that contract and only consumes the bounded automatic
    recovery allowance.  Keep the critic's concrete evidence so the new
    Director run can repair the right boundary.
    """
    if stage is None or str(stage.stage or "").upper() != "PRODUCTION_PLAN":
        return []
    output = dict(stage.output_json or {})
    evidence = dict(output.get("evidence") or {})
    reviews = list(evidence.get("reviews") or [])
    for review in reversed(reviews):
        verdict = dict(
            dict(review or {}).get("verdict") or {}
        )
        if str(verdict.get("repair_scope") or "").strip().lower() != "director_replan":
            continue
        feedback: list[dict[str, Any]] = []
        for issue in list(verdict.get("blocking_issues") or []):
            row = dict(issue or {})
            feedback.append({
                "code": str(row.get("code") or "DIRECTOR_REPLAN_REQUIRED")[:128],
                "line_ids": [
                    str(value)[:128]
                    for value in list(row.get("line_ids") or [])[:64]
                ],
                "evidence": str(row.get("evidence") or "")[:2000],
                "repair_instruction": str(
                    row.get("repair_instruction") or ""
                )[:2000],
            })
        return feedback or [{
            "code": "DIRECTOR_REPLAN_REQUIRED",
            "line_ids": [],
            "evidence": str(stage.error_message or "")[:2000],
            "repair_instruction": (
                "Replan the approved Director artifact before compiling a "
                "new production plan."
            ),
        }]
    # Backward-compatible recovery for a stage produced before structured
    # critic evidence was persisted.
    if "requires a director replan" in str(stage.error_message or "").lower():
        return [{
            "code": "DIRECTOR_REPLAN_REQUIRED",
            "line_ids": [],
            "evidence": str(stage.error_message or "")[:2000],
            "repair_instruction": (
                "Replan the approved Director artifact before compiling a "
                "new production plan."
            ),
        }]
    return []


def _creative_visual_director_replan_feedback(
    db,
    project: HermesContentFactoryProject,
) -> list[dict[str, Any]]:
    """Promote repeated pixel failures to a fresh Director concept revision."""
    stage = _latest_stage(db, project, "CREATIVE_REVIEW")
    if stage is None:
        return [{
            "code": "CREATIVE_VISUAL_REPLAN_EXHAUSTED",
            "line_ids": [],
            "evidence": "The visual repair and production-plan budgets were exhausted.",
            "repair_instruction": (
                "Create a fresh Director visual concept from the pixel-grounded "
                "benchmark analysis before any further image generation."
            ),
        }]
    output = dict(stage.output_json or {})
    result = dict(output.get("result") or {})
    reference_checks = [
        dict(item)
        for item in list(result.get("reference_checks") or [])
        if isinstance(item, dict)
    ]
    return [{
        "code": "CREATIVE_VISUAL_REPLAN_EXHAUSTED",
        "line_ids": [],
        "evidence": json.dumps(
            {
                "creative_review_stage_id": int(stage.id),
                "repair_brief": str(result.get("repair_brief") or "")[:2000],
                "reference_checks": reference_checks[:12],
                "benchmark_hook_transfer": dict(
                    result.get("benchmark_hook_transfer") or {}
                ),
            },
            ensure_ascii=False,
            sort_keys=True,
        )[:4000],
        "repair_instruction": (
            "Do not repeat or cosmetically patch the rejected storyboard. Use "
            "the multimodal benchmark_visual_evidence to design a fresh, "
            "source-safe opening concept with the required ordered hook states, "
            "then hand a materially new executable visual program to Production."
        ),
    }]


def _production_plan_contract_recovery_errors(
    stage: HermesContentFactoryStage | None,
) -> list[str]:
    """Return bounded deterministic failures for a fresh plan generation."""
    if stage is None or str(stage.stage or "").upper() != "PRODUCTION_PLAN":
        return []
    output = dict(stage.output_json or {})
    result = dict(output.get("result") or {})
    return list(dict.fromkeys(
        str(value).strip()[:4000]
        for value in list(result.get("contract_errors") or [])[:16]
        if str(value).strip()
    ))


def _persisted_director_replan_context(
    project: HermesContentFactoryProject,
) -> tuple[list[dict[str, Any]], int | None, str | None]:
    """Recover the upstream evidence that authorized a Director revision.

    A Director quality pause can happen *inside* a Production-Plan initiated
    upstream replan (for example when the replacement author omitted an
    execution mapping).  The next bounded recovery must retain the original
    evidence and source-stage identity.  Dropping either field makes the
    immutable-copy guard correctly reject the new Director revision as an
    unaudited rewrite.
    """
    state = dict(project.state_json or {})
    saved = dict(state.get("automatic_quality_upstream_replan") or {})
    raw_feedback = list(saved.get("feedback") or [])
    feedback: list[dict[str, Any]] = []
    for value in raw_feedback[:16]:
        row = dict(value or {})
        code = str(row.get("code") or "").strip()
        evidence = str(row.get("evidence") or "").strip()
        instruction = str(row.get("repair_instruction") or "").strip()
        if not (code and evidence and instruction):
            continue
        feedback.append({
            "code": code[:128],
            "line_ids": [
                str(item)[:128]
                for item in list(row.get("line_ids") or [])[:64]
                if str(item).strip()
            ],
            "evidence": evidence[:2000],
            "repair_instruction": instruction[:2000],
        })
    try:
        source_stage_id = int(saved.get("source_stage_id") or 0) or None
    except (TypeError, ValueError):
        source_stage_id = None
    from_stage = str(saved.get("from_stage") or "").strip().upper() or None
    if not feedback or source_stage_id is None:
        return [], None, None
    return feedback, source_stage_id, from_stage


def _resume_automatic_quality_pause(
    db,
    project: HermesContentFactoryProject,
    *,
    now: datetime,
) -> tuple[HermesContentFactoryStage | None, dict[str, Any]]:
    """Resume one eligible control-plane quality pause without operator input."""
    from app.services.hermes_agent.content_director_profile import (
        load_universal_director_profile,
    )
    from app.services.hermes_agent.content_factory import resume_project

    generation = (
        f"self-heal-{SELF_HEAL_POLICY_VERSION}:"
        f"{load_universal_director_profile().profile_id}"
    )
    decision = _automatic_quality_recovery_decision(
        project,
        now=now,
        generation=generation,
    )
    if not bool(decision.get("due")):
        return None, decision

    pause_reason = str(decision["pause_reason_code"])
    attempt = int(decision["attempt_count"]) + 1
    attempt_limit = int(decision["attempt_limit"])
    strategy = str(decision.get("strategy") or "targeted_repair")
    paused_stage = _latest_stage(
        db,
        project,
        str(project.current_stage or ""),
    )
    director_replan_feedback = (
        _production_plan_director_replan_feedback(paused_stage)
        if pause_reason == "production_plan_quality_pause"
        else []
    )
    director_replan_source_stage_id = (
        int(paused_stage.id)
        if director_replan_feedback
        and paused_stage is not None
        and paused_stage.id is not None
        else None
    )
    director_replan_from_stage = (
        "PRODUCTION_PLAN" if director_replan_feedback else None
    )
    if pause_reason == "creative_visual_replan_exhausted":
        director_replan_feedback = _creative_visual_director_replan_feedback(
            db,
            project,
        )
        creative_stage = _latest_stage(db, project, "CREATIVE_REVIEW")
        director_replan_source_stage_id = (
            int(creative_stage.id)
            if creative_stage is not None and creative_stage.id is not None
            else int(paused_stage.id)
            if paused_stage is not None and paused_stage.id is not None
            else None
        )
        director_replan_from_stage = "CREATIVE_REVIEW"
    if (
        pause_reason == "content_director_quality_pause"
        and not director_replan_feedback
    ):
        (
            director_replan_feedback,
            director_replan_source_stage_id,
            director_replan_from_stage,
        ) = _persisted_director_replan_context(project)
    production_plan_contract_errors = (
        _production_plan_contract_recovery_errors(paused_stage)
        if pause_reason == "production_plan_quality_pause"
        else []
    )
    project = resume_project(
        db,
        project,
        resume_reason="automatic_quality_recovery",
    )
    state = dict(project.state_json or {})
    state.pop(pause_reason, None)
    state["automatic_quality_recovery"] = {
        "generation": generation,
        "pause_reason_code": pause_reason,
        "incident_key": str(decision["incident_key"]),
        "source_stage_id": decision.get("source_stage_id"),
        "variant_index": decision.get("variant_index"),
        "attempt_count": attempt,
        "attempt_limit": attempt_limit,
        "budget_epoch": int(decision.get("budget_epoch") or 0),
        "strategy": strategy,
        "no_progress_cycles": int(
            decision.get("no_progress_cycles") or 0
        ),
        "last_quality_snapshot": dict(
            decision.get("quality_snapshot") or {}
        ),
        "last_convergence": dict(decision.get("convergence") or {}),
        "autonomy_policy_version": AUTONOMY_POLICY_VERSION,
        "last_attempt_at": now.isoformat(),
        "next_retry_at": (
            now
            + timedelta(
                seconds=AUTOMATIC_QUALITY_RECOVERY_COOLDOWN_SECONDS
            )
        ).isoformat(),
        "status": "replanning",
    }
    if attempt >= attempt_limit:
        state["automatic_quality_recovery"]["next_epoch_at"] = (
            now
            + timedelta(
                seconds=min(
                    21600,
                    900
                    * (
                        2
                        ** min(
                            4,
                            int(decision.get("budget_epoch") or 0),
                        )
                    ),
                )
            )
        ).isoformat()
    project.state_json = state
    target_stage = (
        "DIRECTOR"
        if director_replan_feedback
        else str(project.current_stage or "").strip().upper()
    )
    if target_stage not in {
        "SERIES_DIRECTOR",
        "DIRECTOR",
        "PRODUCTION_PLAN",
    }:
        raise ValueError(
            "AUTOMATIC_QUALITY_RECOVERY_STAGE_INVALID: resumed quality pause "
            f"selected unsupported stage {target_stage or '<empty>'}"
        )
    repair_stage = _create_repair_stage(
        db,
        project,
        target_stage,
        reason=(
            f"automatic quality recovery {attempt}/"
            f"{attempt_limit} after {pause_reason}; strategy={strategy}"
        ),
    )
    # A quality pause may occur while executing a user/operator-authored
    # refinement instruction (for example a binding benchmark-hook upgrade).
    # The replacement stage is a continuation of that same authorized job,
    # not a fresh generic request. Dropping the instruction here allowed the
    # recovery Director to approve calm default openings that directly
    # contradicted the user's latest high-energy hook requirement.
    paused_instruction = str(
        getattr(paused_stage, "instruction", None) or ""
    ).strip()
    last_restart = dict(state.get("last_restart") or {})
    operator_instruction = str(
        last_restart.get("instruction") or ""
    ).strip()
    # The operator's restart instruction is the newest binding project intent.
    # Downstream stages normally carry short stage-local instructions, so a
    # Production Plan pause cannot safely use that prose as a substitute for
    # the full-series hook, pacing, media, and conversion requirements.
    inherited_instruction = operator_instruction or paused_instruction
    inherited_instruction_source = (
        "project_last_restart"
        if operator_instruction
        else "paused_stage"
        if paused_instruction
        else None
    )
    if inherited_instruction:
        repair_stage.instruction = inherited_instruction
    repair_input = dict(repair_stage.input_json or {})
    repair_input.update({
        "force_fresh_response": True,
        "clear_stale_composer_before_send": True,
        "automatic_quality_recovery_attempt": attempt,
        "automatic_quality_recovery_generation": generation,
        "automatic_quality_recovery_incident_key": str(
            decision["incident_key"]
        ),
        "automatic_quality_pause_reason": pause_reason,
        "autonomy_recovery_strategy": strategy,
        "autonomy_budget_epoch": int(decision.get("budget_epoch") or 0),
        "autonomy_no_progress_cycles": int(
            decision.get("no_progress_cycles") or 0
        ),
    })
    repair_stage.instruction = "\n\n".join(
        value
        for value in (
            str(repair_stage.instruction or "").strip(),
            {
                "targeted_repair": (
                    "Autonomy strategy: make the smallest evidence-grounded "
                    "repair to the cited failing dimensions; preserve every "
                    "passing decision."
                ),
                "structural_replan": (
                    "Autonomy strategy: the prior issue did not converge. "
                    "Change the story, conversion, shot, or delivery structure "
                    "responsible for the repeated issue instead of paraphrasing "
                    "the same candidate."
                ),
                "alternate_candidate": (
                    "Autonomy strategy: produce a materially different candidate "
                    "from the signed user intent and authoritative facts. Do not "
                    "reuse the rejected mechanism, scene progression, or repair "
                    "wording."
                ),
            }[strategy],
        )
        if value
    )
    if inherited_instruction:
        repair_input["inherited_operator_instruction"] = True
        repair_input["inherited_operator_instruction_source"] = (
            inherited_instruction_source
        )
        if inherited_instruction_source == "paused_stage":
            repair_input[
                "inherited_operator_instruction_source_stage_id"
            ] = (
                int(paused_stage.id)
                if paused_stage is not None and paused_stage.id is not None
                else None
            )
        elif inherited_instruction_source == "project_last_restart":
            repair_input[
                "inherited_operator_instruction_restart_stage"
            ] = str(last_restart.get("stage") or "").strip().upper() or None
    if (
        target_stage == "PRODUCTION_PLAN"
        and production_plan_contract_errors
    ):
        repair_input.update({
            "automatic_quality_source_stage_id": (
                int(paused_stage.id)
                if paused_stage is not None and paused_stage.id is not None
                else None
            ),
            "automatic_quality_prior_contract_errors": (
                production_plan_contract_errors
            ),
        })
    if director_replan_feedback:
        repair_input["director_replan_feedback"] = director_replan_feedback
        repair_input["director_replan_source_stage_id"] = (
            director_replan_source_stage_id
        )
        state = dict(project.state_json or {})
        state["automatic_quality_upstream_replan"] = {
            "from_stage": director_replan_from_stage or "PRODUCTION_PLAN",
            "to_stage": "DIRECTOR",
            "source_stage_id": repair_input[
                "director_replan_source_stage_id"
            ],
            "feedback": director_replan_feedback,
            "at": now.isoformat(),
        }
        project.state_json = state
    repair_stage.input_json = repair_input
    db.add(project)
    db.add(repair_stage)
    db.flush()
    return repair_stage, decision


def _final_video_quality_failed_task_ids(
    project: HermesContentFactoryProject,
) -> list[int]:
    """Extract only the provider tasks named by the active final-QA incident."""

    state = dict(project.state_json or {})
    failure = dict(state.get("final_video_quality_failure") or {})
    message = "\n".join((
        str(failure.get("message") or ""),
        str(state.get("pause_note") or ""),
        str(project.last_error or ""),
    ))
    task_ids = [
        int(value)
        for value in re.findall(
            r"CONTENT_(?:PRODUCT_VIDEO_VISUAL_QA|VOICE_CONTINUITY_QA|"
            r"SEGMENT_EXECUTION_QA)_FAILED_TASK_(\d+)",
            message,
            flags=re.IGNORECASE,
        )
    ]
    task_ids.extend(
        int(value)
        for value in list(failure.get("task_ids") or [])
        if str(value).strip().isdigit()
    )
    # The final guardian reviews a composed video and can name more affected
    # segments than the exception that happened to trigger the pause.  The
    # structured verdict is the immutable routing evidence for that incident;
    # omitting its task ids leaves one visibly defective segment in the next
    # composition even though the multimodal reviewer explicitly requested its
    # replacement.
    final_intent_report = _final_intent_quality_failure_report(project)
    task_ids.extend(
        int(value)
        for value in list(
            final_intent_report.get("affected_task_ids") or []
        )
        if str(value).strip().isdigit()
    )
    return list(dict.fromkeys(task_ids))


def _scope_final_intent_repair_tasks(
    tasks: list[KieTask],
    report: dict[str, Any],
) -> list[KieTask]:
    """Map the guardian's repair scope to paid provider work.

    ``affected_task_ids`` identifies the media evidence used to judge a
    continuity break and can legitimately include both sides of that break.
    When the multimodal guardian also returns explicit segment indices, those
    indices are the authoritative regeneration scope.  Never broaden an
    explicit scope merely because another task contributed review evidence.
    """

    if (
        str(report.get("repair_scope") or "").strip().lower()
        != "segment_regeneration"
    ):
        return list(tasks)
    raw_segment_indices = (
        report.get("regenerate_segment_indices")
        if "regenerate_segment_indices" in report
        else report.get("affected_segment_indices")
    )
    segment_indices = {
        int(value)
        for value in list(raw_segment_indices or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    if not segment_indices:
        return list(tasks)
    try:
        video_index = int(report.get("video_index") or 0)
    except (TypeError, ValueError):
        video_index = 0
    scoped: list[KieTask] = []
    for task in tasks:
        params = dict(task.input_json or {})
        try:
            task_segment_index = int(
                params.get("content_factory_segment_index") or 0
            )
            task_video_index = int(
                params.get("content_factory_video_index")
                or params.get("content_factory_variant_index")
                or 0
            )
        except (TypeError, ValueError):
            continue
        if task_segment_index not in segment_indices:
            continue
        if video_index > 0 and task_video_index != video_index:
            continue
        scoped.append(task)
    return scoped


def _final_intent_quality_failure_report(
    project: HermesContentFactoryProject,
) -> dict[str, Any]:
    """Recover the multimodal final-intent verdict from a quality pause.

    New pauses persist the structured report directly.  Historical rows may
    contain only a bounded diagnostic string, so recover the small routing
    fields independently when the tail of the JSON was truncated.  The report
    remains model-authored evidence; this parser decides no creative outcome.
    """

    state = dict(project.state_json or {})
    failure = dict(state.get("final_video_quality_failure") or {})
    structured = failure.get("final_intent_report")
    if isinstance(structured, dict) and structured:
        return _recover_historical_final_intent_evidence(
            project,
            dict(structured),
        )
    message = "\n".join((
        str(failure.get("message") or ""),
        str(state.get("pause_note") or ""),
        str(project.last_error or ""),
    ))
    marker = "CONTENT_FINAL_INTENT_QA_FAILED "
    marker_at = message.find(marker)
    if marker_at < 0:
        return {}
    report_text = message[marker_at + len(marker):].lstrip()
    try:
        decoded, _end = json.JSONDecoder().raw_decode(report_text)
        if isinstance(decoded, dict):
            return _recover_historical_final_intent_evidence(
                project,
                decoded,
            )
    except (TypeError, ValueError, json.JSONDecodeError):
        pass

    recovered: dict[str, Any] = {"truncated": True}
    for key in (
        "affected_segment_indices",
        "affected_task_ids",
        "blocking_reasons",
        "blocking_requirement_ids",
    ):
        match = re.search(
            rf'"{re.escape(key)}"\s*:\s*(\[[^\]]*\])',
            report_text,
        )
        if match is None:
            continue
        try:
            value = json.loads(match.group(1))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if isinstance(value, list):
            recovered[key] = value
    for key in ("policy_version", "repair_scope", "repair_instruction"):
        match = re.search(
            rf'"{re.escape(key)}"\s*:\s*("(?:[^"\\]|\\.)*")',
            report_text,
        )
        if match is None:
            continue
        try:
            recovered[key] = json.loads(match.group(1))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
    video_match = re.search(r'"video_index"\s*:\s*(\d+)', report_text)
    if video_match is not None:
        recovered["video_index"] = int(video_match.group(1))
    return _recover_historical_final_intent_evidence(project, recovered)


def _quality_incident_repair_report(
    db,
    project: HermesContentFactoryProject,
    task_ids: list[int],
) -> dict[str, Any]:
    """Translate scoped segment QA evidence into the common repair protocol.

    Product, voice, spoken-copy, and segment-execution reviewers predate the
    composed final-intent report. They still own durable pixel/audio evidence,
    and must be able to reach the same multimodal escalation path when a local
    repair compiler exhausts its semantic attempts.
    """

    for task_id in task_ids[:64]:
        task = db.get(KieTask, int(task_id))
        if task is None or int(task.workspace_id) != int(project.workspace_id):
            continue
        if (
            project.user_id is not None
            and int(task.created_by_user_id or 0) != int(project.user_id)
        ):
            continue
        params = dict(task.input_json or {})
        if int(params.get("content_factory_project_id") or 0) != int(project.id):
            continue
        meta = dict(get_task_local_meta(task) or {})
        incident = dict(meta.get("content_quality_incident") or {})
        code = str(incident.get("code") or "").strip().lower()
        if code not in {
            SEGMENT_EXECUTION_QA_FAIL_CODE,
            PRODUCT_VISUAL_QA_FAIL_CODE,
            VOICE_CONTINUITY_FAIL_CODE,
            SPOKEN_COPY_FAIL_CODE,
        }:
            continue
        review_key = {
            PRODUCT_VISUAL_QA_FAIL_CODE: "provider_product_video_review",
            SEGMENT_EXECUTION_QA_FAIL_CODE: "segment_execution_review",
            VOICE_CONTINUITY_FAIL_CODE: "voice_continuity_review",
            SPOKEN_COPY_FAIL_CODE: "spoken_copy_review",
        }[code]
        review = dict(meta.get(review_key) or {})
        contact_sheet_path = str(
            review.get("contact_sheet_path")
            or dict(incident.get("evidence") or {}).get("contact_sheet_path")
            or ""
        ).strip()
        if not contact_sheet_path:
            continue
        try:
            segment_index = int(
                params.get("content_factory_segment_index") or 0
            )
            video_index = int(
                params.get("content_factory_video_index")
                or params.get("content_factory_variant_index")
                or 0
            )
        except (TypeError, ValueError):
            continue
        blocking_reasons = [
            str(value).strip()
            for value in list(review.get("blocking_reasons") or [])
            if str(value).strip()
        ]
        message = str(incident.get("message") or "").strip()
        if not blocking_reasons and message:
            blocking_reasons = [message[:1200]]
        return {
            "policy_version": str(
                review.get("policy_version") or SELF_HEAL_POLICY_VERSION
            ),
            "repair_scope": "segment_regeneration",
            "video_index": video_index,
            "affected_segment_indices": (
                [segment_index] if segment_index > 0 else []
            ),
            "affected_task_ids": [int(task.id)],
            "blocking_reasons": blocking_reasons[:8],
            "repair_instruction": str(
                review.get("repair_instruction")
                or "Create a materially different executable segment that fixes "
                "the evidenced quality defect while preserving signed user intent."
            )[:2000],
            "contact_sheet_path": contact_sheet_path,
            "quality_incident_code": code,
            "source": "scoped_content_quality_incident",
        }
    return {}


def _recover_historical_final_intent_evidence(
    project: HermesContentFactoryProject,
    report: dict[str, Any],
) -> dict[str, Any]:
    """Recover exact review pixels for pauses created before evidence v2.

    Older quality exceptions deliberately serialized only the verdict fields.
    The contact sheet was nevertheless written durably before the multimodal
    review.  Each result sheet is immediately followed by task-specific
    segment sheets, so the nearest preceding result sheet to an affected task
    is the exact composed artifact reviewed in that transaction.  All paths
    remain confined to this project's final-review directory.
    """

    normalized = dict(report or {})
    existing_path = str(normalized.get("contact_sheet_path") or "").strip()
    if existing_path:
        return normalized
    review_dir = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
        / "generated"
        / "final_intent_reviews"
    )
    try:
        resolved_review_dir = review_dir.resolve(strict=True)
    except OSError:
        return normalized
    task_ids = [
        int(value)
        for value in list(normalized.get("affected_task_ids") or [])
        if str(value).strip().isdigit() and int(value) > 0
    ]
    segment_rows: list[tuple[float, Path]] = []
    for task_id in task_ids:
        for candidate in review_dir.glob(f"segment-*-task-{task_id}-*.jpg"):
            try:
                resolved = candidate.resolve(strict=True)
                if not resolved.is_relative_to(resolved_review_dir):
                    continue
                if resolved.stat().st_size <= 1024:
                    continue
                segment_rows.append((resolved.stat().st_mtime, resolved))
            except OSError:
                continue
    if not segment_rows:
        return normalized
    # A task can have more than one historical execution.  The pause refers to
    # the newest persisted review for that task.
    segment_mtime, segment_sheet = max(segment_rows, key=lambda row: row[0])
    result_rows: list[tuple[float, Path]] = []
    for candidate in review_dir.glob("result-*.jpg"):
        try:
            resolved = candidate.resolve(strict=True)
            if not resolved.is_relative_to(resolved_review_dir):
                continue
            stat = resolved.stat()
            if stat.st_size <= 1024 or stat.st_mtime > segment_mtime:
                continue
            result_rows.append((stat.st_mtime, resolved))
        except OSError:
            continue
    evidence_path = (
        max(result_rows, key=lambda row: row[0])[1]
        if result_rows
        else segment_sheet
    )
    normalized["contact_sheet_path"] = str(evidence_path)
    normalized["evidence_recovered_from_legacy_pause"] = True
    return normalized


def _premature_cross_deliverable_quality_pause(
    db,
    project: HermesContentFactoryProject,
) -> dict[str, Any] | None:
    """Recognize a series-level verdict raised before the series exists."""

    state = dict(project.state_json or {})
    failure = dict(state.get("final_video_quality_failure") or {})
    message = "\n".join((
        str(failure.get("message") or ""),
        str(state.get("pause_note") or ""),
        str(project.last_error or ""),
    ))
    marker = "CONTENT_FINAL_INTENT_QA_FAILED "
    marker_at = message.find(marker)
    if marker_at < 0:
        return None
    report_text = message[marker_at + len(marker):].lstrip()
    try:
        report, _end = json.JSONDecoder().raw_decode(report_text)
    except (TypeError, ValueError, json.JSONDecodeError):
        # Historical pause_note/last_error fields are bounded and can contain
        # the start of a valid guardian report with its long repair text cut
        # off at the tail.  Recover only the independently parseable blocking
        # ID array; the signed project contract below remains the authority
        # for deciding whether those IDs are series-level.
        report = {"truncated": True}
        blocking_match = re.search(
            r'"blocking_requirement_ids"\s*:\s*(\[[^\]]*\])',
            report_text,
        )
        if blocking_match is not None:
            try:
                report["blocking_requirement_ids"] = json.loads(
                    blocking_match.group(1)
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                pass
    if not isinstance(report, dict):
        return None
    blocking_ids = {
        str(value).strip()
        for value in list(report.get("blocking_requirement_ids") or [])
        if str(value).strip()
    }
    if not blocking_ids:
        return None
    requirement_by_id: dict[str, dict[str, Any]] = {}
    for group in list(state.get("ai_video_groups") or []):
        if not isinstance(group, dict):
            continue
        for requirement in list(group.get("intent_requirements") or []):
            if not isinstance(requirement, dict):
                continue
            requirement_id = str(
                requirement.get("requirement_id") or ""
            ).strip()
            if requirement_id:
                requirement_by_id[requirement_id] = dict(requirement)
    if any(
        requirement_id not in requirement_by_id
        or not _is_cross_deliverable_intent_requirement(
            requirement_by_id[requirement_id]
        )
        for requirement_id in blocking_ids
    ):
        return None
    pipeline = _variant_pipeline(project)
    target = int(
        pipeline.get("target_count") or _target_video_count(project)
    )
    completed = len(_completed_video_assets_by_index(db, project))
    if completed >= target:
        return None
    return {
        "blocking_requirement_ids": sorted(blocking_ids),
        "completed_count": int(completed),
        "target_count": int(target),
        "failure": report,
    }


def _resume_final_video_quality_pause(
    db,
    project: HermesContentFactoryProject,
    *,
    now: datetime,
) -> tuple[list[int], dict[str, Any]]:
    """Regenerate only evidenced failed final-QA segments, never the full project."""

    config = dict(project.config_json or {})
    state = dict(project.state_json or {})
    reason = str(state.get("pause_reason_code") or "").strip().lower()
    task_ids = _final_video_quality_failed_task_ids(project)
    decision: dict[str, Any] = {
        "eligible": False,
        "recovered": False,
        "pause_reason_code": reason,
        "failed_task_ids": task_ids,
        "retry_task_ids": [],
        "status": "ineligible",
    }
    if (
        str(project.status or "").strip().lower() != "paused"
        or reason != FINAL_VIDEO_QUALITY_RECOVERY_REASON
        or bool(config.get("manual_paused", False))
        or not bool(config.get("auto_run", True))
    ):
        return [], decision
    decision["eligible"] = True
    existing_recovery = dict(
        state.get("final_video_quality_recovery") or {}
    )
    try:
        existing_recovery_at = datetime.fromisoformat(
            str(existing_recovery.get("at") or "").replace("Z", "+00:00")
        ).replace(tzinfo=None)
    except (TypeError, ValueError):
        existing_recovery_at = None
    if (
        str(existing_recovery.get("status") or "").strip().lower()
        == "planning"
        and existing_recovery_at is not None
        and existing_recovery_at
        >= now - timedelta(seconds=VIDEO_WAIT_STALE_SECONDS)
    ):
        decision["status"] = "recovery_in_progress"
        return [], decision
    # A prior guardian policy could accidentally use whole-series completion
    # and post-publication analytics as evidence gates while reviewing the
    # first composed video.  Re-run the exact media under the current scoped
    # multimodal policy; this is a policy migration, not a quality bypass.
    quality_failure_text = "\n".join((
        str(dict(state.get("final_video_quality_failure") or {}).get("message") or ""),
        str(state.get("pause_note") or ""),
        str(project.last_error or ""),
    ))
    if (
        "CONTENT_FINAL_INTENT_QA_FAILED" in quality_failure_text
        and FINAL_INTENT_REVIEW_POLICY_VERSION not in quality_failure_text
    ):
        failure_evidence = dict(state.get("final_video_quality_failure") or {})
        for key in (
            "pause_reason_code",
            "automatic_quality_paused_at",
            "paused_at",
            "pause_note",
            "final_video_quality_failure",
        ):
            state.pop(key, None)
        state["obsolete_final_intent_review_requeued"] = {
            "policy_version": FINAL_INTENT_REVIEW_POLICY_VERSION,
            "at": now.isoformat(),
            "failure_evidence": failure_evidence,
        }
        project.state_json = state
        project.status = "generating_video"
        project.current_stage = "WAITING_VIDEO_INPUT"
        project.last_error = (
            "旧版单条成片验收范围已失效；Hermes 正在使用当前多模态验收范围"
            "重新审查同一成片并继续剩余视频。"
        )
        db.add(project)
        db.flush()
        wait_task_id = _schedule_video_wait(
            db,
            project,
            countdown=5,
            reason="re-review final video under current scoped intent policy",
        )
        decision.update({
            "recovered": True,
            "retry_task_ids": [],
            "wait_task_id": wait_task_id,
            "status": "obsolete_final_intent_policy_requeued",
            "policy_version": FINAL_INTENT_REVIEW_POLICY_VERSION,
        })
        return [], decision
    premature_series_review = _premature_cross_deliverable_quality_pause(
        db,
        project,
    )
    if premature_series_review is not None:
        failure_evidence = dict(
            state.get("final_video_quality_failure") or {}
        )
        for key in (
            "pause_reason_code",
            "automatic_quality_paused_at",
            "paused_at",
            "pause_note",
            "final_video_quality_failure",
        ):
            state.pop(key, None)
        state["cross_deliverable_quality_review_deferred"] = {
            "policy_version": FINAL_INTENT_REVIEW_POLICY_VERSION,
            "at": now.isoformat(),
            **premature_series_review,
            "failure_evidence": failure_evidence,
        }
        project.state_json = state
        project.status = "generating_video"
        project.current_stage = "WAITING_VIDEO_INPUT"
        project.last_error = (
            "检测到整批差异化要求被单条成片验收提前触发；Hermes 已将整批验收延后到"
            f"目标 {premature_series_review['target_count']} 条全部完成后，"
            "并继续生成剩余视频。"
        )
        db.add(project)
        db.flush()
        wait_task_id = _schedule_video_wait(
            db,
            project,
            countdown=5,
            reason=(
                "resume after deferring cross-deliverable review until target completion"
            ),
        )
        decision.update({
            "recovered": True,
            "retry_task_ids": [],
            "wait_task_id": wait_task_id,
            "status": "deferred_cross_deliverable_review",
            **premature_series_review,
        })
        return [], decision
    final_intent_report = _final_intent_quality_failure_report(project)
    if not str(final_intent_report.get("repair_scope") or "").strip():
        incident_report = _quality_incident_repair_report(
            db,
            project,
            task_ids,
        )
        if incident_report:
            final_intent_report = incident_report
    # A composed-video guardian judges the current pixels, but cannot know
    # whether an equivalent local regeneration strategy has already failed.
    # Once the incident-bounded segment budget is exhausted, ask a separate
    # multimodal repair supervisor to choose the next repair layer using the
    # contact sheet plus the project-owned retry ledger. This keeps escalation
    # creative and evidence-driven instead of encoding one product, hook, or
    # story pattern in Python.
    if (
        str(final_intent_report.get("repair_scope") or "").strip().lower()
        == "segment_regeneration"
        and str(existing_recovery.get("status") or "").strip().lower()
        == "bounded_retry_exhausted"
    ):
        try:
            video_index = int(final_intent_report.get("video_index") or 0)
        except (TypeError, ValueError):
            video_index = 0
        retry_rows = [
            dict(item)
            for item in list(state.get("ai_video_retry_history") or [])[-100:]
            if isinstance(item, dict)
            and (
                video_index <= 0
                or str(item.get("video_segment") or "").startswith(
                    f"{video_index}:"
                )
            )
        ]
        local_repair_compiler_errors: list[dict[str, Any]] = []
        for raw_task_id in list(
            final_intent_report.get("affected_task_ids") or task_ids
        )[:64]:
            if not str(raw_task_id or "").strip().isdigit():
                continue
            failed_task = db.get(KieTask, int(raw_task_id))
            if failed_task is None or int(
                failed_task.workspace_id
            ) != int(project.workspace_id):
                continue
            failed_input = dict(failed_task.input_json or {})
            if int(failed_input.get("content_factory_project_id") or 0) != int(
                project.id
            ):
                continue
            failed_meta = dict(get_task_local_meta(failed_task) or {})
            compiler_error = str(
                failed_meta.get("content_factory_execution_replan_error") or ""
            ).strip()
            if compiler_error:
                local_repair_compiler_errors.append({
                    "task_id": int(failed_task.id),
                    "error": compiler_error[:1500],
                })
        repair_history = {
            "video_index": video_index,
            "bounded_segment_repair_exhausted": True,
            "copy_authority": (
                "user_verbatim_locked"
                if _deliverable_copy_is_user_verbatim(
                    dict(project.config_json or {})
                )
                else "director_model_editable"
            ),
            "prior_recovery": {
                key: existing_recovery.get(key)
                for key in (
                    "status",
                    "scope",
                    "failed_task_ids",
                    "retry_task_ids",
                    "at",
                )
                if existing_recovery.get(key) is not None
            },
            "local_repair_compiler_errors": local_repair_compiler_errors,
            "retry_attempts": [{
                key: row.get(key)
                for key in (
                    "video_segment",
                    "failed_task_id",
                    "retry_task_id",
                    "attempt",
                    "budget_kind",
                    "final_intent_incident_repair",
                    "reason",
                    "segment_execution_repair",
                    "prompt_rewrite_attempt",
                    "prompt_hash",
                    "selected_service_provider",
                    "at",
                )
                if row.get(key) is not None
            } for row in retry_rows[-12:]],
        }
        repair_history_hash = hashlib.sha256(
            json.dumps(
                repair_history,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()[:24]
        cached_scope_review = dict(
            state.get("final_intent_repair_scope_review") or {}
        )
        if (
            str(cached_scope_review.get("repair_history_hash") or "")
            == repair_history_hash
            and str(cached_scope_review.get("repair_scope") or "")
            in {"segment_regeneration", "director_replan"}
        ):
            scope_review = cached_scope_review
        else:
            try:
                scope_review = review_final_intent_repair_scope_api(
                    db,
                    final_intent_report=final_intent_report,
                    repair_history=repair_history,
                    execution_id=(
                        f"project-{int(project.id)}-variant-{video_index}-"
                        f"{repair_history_hash}"
                    ),
                )
            except (ContentFactoryApiError, OSError, ValueError) as exc:
                scope_review = {
                    "repair_scope": "",
                    "error": f"{type(exc).__name__}: {str(exc)[:500]}",
                }
            scope_review = {
                **dict(scope_review or {}),
                "repair_history_hash": repair_history_hash,
                "reviewed_at": now.isoformat(),
            }
            state["final_intent_repair_scope_review"] = scope_review
            project.state_json = state
            db.add(project)
            db.flush()
        if (
            str(scope_review.get("repair_scope") or "").strip().lower()
            == "director_replan"
        ):
            final_intent_report = {
                **final_intent_report,
                "repair_scope": "director_replan",
                "repair_instruction": str(
                    scope_review.get("repair_instruction")
                    or final_intent_report.get("repair_instruction")
                    or ""
                ).strip(),
                "repair_scope_review": scope_review,
            }
    if (
        str(final_intent_report.get("repair_scope") or "").strip().lower()
        == "director_replan"
    ):
        try:
            video_index = int(final_intent_report.get("video_index") or 0)
        except (TypeError, ValueError):
            video_index = 0
        if video_index <= 0:
            for task_id in list(
                final_intent_report.get("affected_task_ids") or task_ids
            ):
                if not str(task_id).strip().isdigit():
                    continue
                failed_task = db.get(KieTask, int(task_id))
                if failed_task is None:
                    continue
                params = dict(failed_task.input_json or {})
                if int(params.get("content_factory_project_id") or 0) != int(
                    project.id
                ):
                    continue
                video_index = int(
                    params.get("content_factory_video_index")
                    or params.get("content_factory_variant_index")
                    or 0
                )
                if video_index > 0:
                    break
        target_count = _target_video_count(project)
        if not 1 <= video_index <= target_count:
            decision["status"] = "director_replan_variant_missing"
            return [], decision
        source_stage = _latest_variant_stage(
            db,
            project,
            "VIDEO_PROMPTS",
            video_index,
        )
        if source_stage is None or source_stage.id is None:
            decision["status"] = "director_replan_source_missing"
            return [], decision
        superseded_source_stages: dict[int, HermesContentFactoryStage] = {
            int(source_stage.id): source_stage,
        }
        # The latest variant prompt stage may be an empty replacement that
        # froze before submitting media. Retire the prompt generations that
        # actually authorized every rejected provider task as well, otherwise
        # their late waiter can keep regenerating an obsolete visual concept
        # while the new Director plan is already running.
        for raw_task_id in list(
            final_intent_report.get("affected_task_ids") or task_ids
        )[:64]:
            if not str(raw_task_id or "").strip().isdigit():
                continue
            affected_task = db.get(KieTask, int(raw_task_id))
            if affected_task is None or int(
                affected_task.workspace_id
            ) != int(project.workspace_id):
                continue
            task_input = dict(affected_task.input_json or {})
            if int(task_input.get("content_factory_project_id") or 0) != int(
                project.id
            ):
                continue
            task_source_id = task_input.get(
                "content_factory_source_stage_id"
            )
            if not str(task_source_id or "").strip().isdigit():
                continue
            affected_source = db.get(
                HermesContentFactoryStage,
                int(task_source_id),
            )
            if (
                affected_source is None
                or int(affected_source.project_id) != int(project.id)
                or str(affected_source.stage or "").upper()
                != "VIDEO_PROMPTS"
            ):
                continue
            superseded_source_stages[int(affected_source.id)] = (
                affected_source
            )
        for retired_stage in superseded_source_stages.values():
            retired_stage.status = "superseded"
            retired_stage.error_message = (
                "Superseded by multimodal final-intent Director replan; "
                "late waiters may archive provider results but cannot submit "
                "replacement work from this prompt generation."
            )
            retired_stage.completed_at = retired_stage.completed_at or now
            db.add(retired_stage)
        blocking_reasons = [
            str(value).strip()
            for value in list(final_intent_report.get("blocking_reasons") or [])
            if str(value).strip()
        ]
        repair_instruction = str(
            final_intent_report.get("repair_instruction") or ""
        ).strip()
        feedback = [{
            "code": "FINAL_INTENT_DIRECTOR_REPLAN",
            "line_ids": [
                str(value)[:128]
                for value in list(
                    final_intent_report.get("blocking_requirement_ids") or []
                )[:64]
                if str(value).strip()
            ],
            "evidence": json.dumps(
                {
                    "video_index": video_index,
                    "blocking_reasons": blocking_reasons[:8],
                    "affected_segment_indices": list(
                        final_intent_report.get("affected_segment_indices") or []
                    )[:16],
                    "affected_task_ids": list(
                        final_intent_report.get("affected_task_ids") or []
                    )[:16],
                },
                ensure_ascii=False,
                sort_keys=True,
            )[:2000],
            "repair_instruction": (
                repair_instruction
                or "Create a materially new executable story and visual plan "
                "that resolves the multimodal final-intent review."
            )[:2000],
        }]
        pipeline = _variant_pipeline(project)
        pipeline["active_index"] = video_index
        pipeline["completed_indices"] = [
            int(value)
            for value in list(pipeline.get("completed_indices") or [])
            if str(value).strip().isdigit() and int(value) != video_index
        ]
        _set_variant_pipeline(project, pipeline)
        repair_stage = _create_repair_stage(
            db,
            project,
            "DIRECTOR",
            reason=(
                "multimodal final-intent review requested Director replan for "
                f"variant {video_index}"
            ),
        )
        repair_input = dict(repair_stage.input_json or {})
        repair_input.update({
            "force_fresh_response": True,
            "clear_stale_composer_before_send": True,
            "automatic_quality_pause_reason": (
                FINAL_VIDEO_QUALITY_RECOVERY_REASON
            ),
            "director_replan_feedback": feedback,
            "director_replan_source_stage_id": int(source_stage.id),
            "director_replan_superseded_source_stage_ids": sorted(
                superseded_source_stages
            ),
            "final_intent_replan_report": final_intent_report,
        })
        repair_stage.input_json = repair_input
        state = dict(project.state_json or {})
        failure_evidence = dict(state.get("final_video_quality_failure") or {})
        for key in (
            "pause_reason_code",
            "automatic_quality_paused_at",
            "paused_at",
            "pause_note",
            "final_video_quality_failure",
        ):
            state.pop(key, None)
        state["final_video_quality_recovery"] = {
            "policy_version": SELF_HEAL_POLICY_VERSION,
            "at": now.isoformat(),
            "video_index": video_index,
            "source_stage_id": int(source_stage.id),
            "repair_stage_id": int(repair_stage.id),
            "failure": failure_evidence,
            "scope": "director_replan",
            "status": "replanning",
        }
        project.state_json = state
        project.status = "queued"
        project.current_stage = "DIRECTOR"
        project.last_error = None
        db.add(project)
        db.add(repair_stage)
        db.flush()
        decision.update({
            "recovered": True,
            "status": "director_replanning",
            "video_index": video_index,
            "repair_stage_id": int(repair_stage.id),
        })
        return [], decision
    if not task_ids:
        decision["status"] = "missing_failed_task_evidence"
        return [], decision

    failed_tasks = (
        db.query(KieTask)
        .filter(
            KieTask.id.in_(task_ids),
            KieTask.workspace_id == int(project.workspace_id),
        )
        .order_by(KieTask.id.asc())
        .all()
    )
    failed_tasks = [
        task
        for task in failed_tasks
        if int(dict(task.input_json or {}).get("content_factory_project_id") or 0)
        == int(project.id)
        and (
            project.user_id is None
            or int(task.created_by_user_id or 0) == int(project.user_id)
        )
        and _content_task_is_final_quality_repair_candidate(task)
    ]
    if (
        str(final_intent_report.get("repair_scope") or "").strip().lower()
        == "segment_regeneration"
        and "regenerate_segment_indices" not in final_intent_report
        and failed_tasks
    ):
        candidate_segments = []
        for task in failed_tasks:
            params = dict(task.input_json or {})
            try:
                candidate_segments.append({
                    "task_id": int(task.id),
                    "video_index": int(
                        params.get("content_factory_video_index")
                        or params.get("content_factory_variant_index")
                        or 0
                    ),
                    "segment_index": int(
                        params.get("content_factory_segment_index") or 0
                    ),
                })
            except (TypeError, ValueError):
                continue
        report_digest = hashlib.sha256(
            json.dumps(
                final_intent_report,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")
        ).hexdigest()[:24]
        cached_target_review = dict(
            state.get("final_intent_repair_target_review") or {}
        )
        if (
            str(cached_target_review.get("report_digest") or "")
            == report_digest
            and list(
                cached_target_review.get("regenerate_segment_indices") or []
            )
        ):
            target_review = cached_target_review
        else:
            try:
                target_review = review_final_intent_repair_targets_api(
                    db,
                    final_intent_report=final_intent_report,
                    candidate_segments=candidate_segments,
                    execution_id=(
                        f"project-{int(project.id)}-repair-target-{report_digest}"
                    ),
                )
            except (ContentFactoryApiError, OSError, ValueError) as exc:
                decision.update({
                    "status": "repair_target_review_unavailable",
                    "repair_target_error": (
                        f"{type(exc).__name__}: {str(exc)[:500]}"
                    ),
                })
                return [], decision
            target_review = {
                **dict(target_review or {}),
                "report_digest": report_digest,
                "reviewed_at": now.isoformat(),
            }
            state = dict(project.state_json or {})
            state["final_intent_repair_target_review"] = target_review
            project.state_json = state
            db.add(project)
            db.flush()
        final_intent_report = {
            **final_intent_report,
            "evidence_segment_indices": list(
                target_review.get("evidence_segment_indices") or []
            ),
            "regenerate_segment_indices": list(
                target_review.get("regenerate_segment_indices") or []
            ),
            "affected_segment_indices": list(
                target_review.get("regenerate_segment_indices") or []
            ),
            "repair_instruction": str(
                target_review.get("repair_instruction")
                or final_intent_report.get("repair_instruction")
                or ""
            ).strip(),
            "repair_target_review": target_review,
        }
        state = dict(project.state_json or {})
        failure = dict(state.get("final_video_quality_failure") or {})
        failure["final_intent_report"] = final_intent_report
        state["final_video_quality_failure"] = failure
        project.state_json = state
        db.add(project)
        db.flush()
    failed_tasks = _scope_final_intent_repair_tasks(
        failed_tasks,
        final_intent_report,
    )
    decision["failed_task_ids"] = [int(task.id) for task in failed_tasks]
    if not failed_tasks:
        decision["status"] = (
            "explicit_segment_scope_mismatch"
            if list(
                final_intent_report.get("regenerate_segment_indices")
                or final_intent_report.get("affected_segment_indices")
                or []
            )
            else "failed_task_scope_mismatch"
        )
        return [], decision

    # Final QA is a composed-video review. Attach its immutable, scoped repair
    # packet to every explicitly named failed segment before the retry planner
    # invokes the multimodal feasibility author. This closes the project-to-
    # task evidence gap without broadening repair to an unfailed segment.
    final_intent_report = _final_intent_quality_failure_report(project)
    for failed_task in failed_tasks:
        _attach_final_intent_repair_evidence(
            failed_task,
            final_intent_report,
        )
        db.add(failed_task)

    # Claim this immutable failure incident before the retry compiler calls a
    # multimodal model.  `_retry_failed_video_segments` commits the freshly
    # created provider rows before publishing them; without this earlier
    # claim, a concurrent guardian/manual resume can enter during that commit
    # window and create a second paid replacement for the same segment.
    state = dict(project.state_json or {})
    state["final_video_quality_recovery"] = {
        **existing_recovery,
        "policy_version": SELF_HEAL_POLICY_VERSION,
        "at": now.isoformat(),
        "failed_task_ids": [int(task.id) for task in failed_tasks],
        "scope": "failed_segments_only",
        "status": "planning",
    }
    project.state_json = state
    db.add(project)
    db.commit()
    db.refresh(project)

    retry_task_ids = _retry_failed_video_segments(
        db,
        project,
        failed_tasks,
    )
    if not retry_task_ids:
        state = dict(project.state_json or {})
        recovery = dict(state.get("final_video_quality_recovery") or {})
        recovery.update({
            "policy_version": SELF_HEAL_POLICY_VERSION,
            "at": now.isoformat(),
            "failed_task_ids": [int(task.id) for task in failed_tasks],
            "retry_task_ids": [],
            "scope": "failed_segments_only",
            "status": "bounded_retry_exhausted",
        })
        state["final_video_quality_recovery"] = recovery
        project.state_json = state
        project.status = "paused"
        db.add(project)
        db.flush()
        decision["status"] = "bounded_retry_exhausted"
        return [], decision

    # _retry_failed_video_segments commits the fresh task pointers. Reload its
    # state before clearing only the active pause markers; keep the failure
    # evidence in the recovery audit record.
    state = dict(project.state_json or {})
    failure_evidence = dict(state.get("final_video_quality_failure") or {})
    for key in (
        "pause_reason_code",
        "automatic_quality_paused_at",
        "paused_at",
        "pause_note",
        "final_video_quality_failure",
    ):
        state.pop(key, None)
    state["ai_video_pending_task_ids"] = list(dict.fromkeys([
        *[
            int(value)
            for value in list(state.get("ai_video_pending_task_ids") or [])
            if str(value).strip().isdigit()
        ],
        *retry_task_ids,
    ]))
    state["final_video_quality_recovery"] = {
        "policy_version": SELF_HEAL_POLICY_VERSION,
        "at": now.isoformat(),
        "failed_task_ids": [int(task.id) for task in failed_tasks],
        "retry_task_ids": retry_task_ids,
        "failure": failure_evidence,
        "scope": "failed_segments_only",
        "status": "regenerating",
    }
    project.state_json = state
    project.status = "generating_video"
    project.current_stage = "WAITING_VIDEO_INPUT"
    project.last_error = (
        "最终成片质检发现局部画面问题；Hermes 已保留合格片段，"
        f"仅重新生成 {len(retry_task_ids)} 个失败片段并继续自动验收。"
    )
    db.add(project)
    db.flush()
    wait_task_id = _schedule_video_wait(
        db,
        project,
        countdown=20,
        reason="monitoring bounded final-video quality recovery",
    )
    decision.update({
        "recovered": True,
        "retry_task_ids": retry_task_ids,
        "wait_task_id": wait_task_id,
        "status": "regenerating_failed_segments",
    })
    return retry_task_ids, decision


def _stage_matches_variant(
    stage_row: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    variant_index: int,
) -> bool:
    row_variant = _stage_output_variant(stage_row)
    if row_variant is None:
        row_variant = 1
    try:
        return int(row_variant) == int(variant_index)
    except (TypeError, ValueError):
        return False


def _latest_variant_stage(
    db,
    project: HermesContentFactoryProject,
    stage_name: str,
    variant_index: int,
) -> HermesContentFactoryStage | None:
    rows = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == stage_name,
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .all()
    )
    for row in rows:
        if _stage_matches_variant(row, project, variant_index):
            return row
    return None


def _visual_api_recovery_epoch(stage_input: dict[str, Any] | None) -> int:
    try:
        return max(
            0,
            int(
                dict(dict(stage_input or {}).get("visual_api") or {}).get(
                    "api_recovery_epoch"
                )
                or 0
            ),
        )
    except (TypeError, ValueError):
        return 0


def _next_unsubmitted_serial_variant(project: HermesContentFactoryProject) -> int | None:
    if not _sequential_variants_enabled(project):
        return None
    pipeline = _variant_pipeline(project)
    target = int(pipeline.get("target_count") or _target_video_count(project))
    submitted = {
        int(value) for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit()
    }
    completed = {
        int(value) for value in list(pipeline.get("completed_indices") or [])
        if str(value).strip().isdigit()
    }
    active = int(pipeline.get("active_index") or 1)
    if 1 <= active <= target and active not in submitted and active not in completed:
        return active
    for index in range(1, target + 1):
        if index not in submitted and index not in completed:
            return index
    return None


def _resume_stage_for_serial_variant(
    db,
    project: HermesContentFactoryProject,
    variant_index: int,
) -> str:
    if (
        _latest_variant_stage(db, project, "VIDEO_PROMPTS", variant_index)
        and _latest_variant_stage(db, project, "VIDEO_PROMPTS", variant_index).status == "success"
    ):
        return "VIDEO_PROMPTS"
    if (
        _latest_variant_stage(db, project, "FINAL_ASSETS", variant_index)
        and _latest_variant_stage(db, project, "FINAL_ASSETS", variant_index).status == "success"
    ):
        return "VIDEO_PROMPTS"
    review_stage = _latest_variant_stage(db, project, "CREATIVE_REVIEW", variant_index)
    if review_stage and review_stage.status == "success":
        # A review row can succeed while deliberately rejecting the board and
        # requesting another VISUAL_PREVIEW.  Treating every successful review
        # as approval let the video waiter jump straight to FINAL_ASSETS and
        # split an absent/rejected board.
        review_result = dict((review_stage.output_json or {}).get("result") or {})
        if bool(review_result.get("approved_for_split")):
            return "FINAL_ASSETS"
        return "VISUAL_PREVIEW"
    if (
        _latest_variant_stage(db, project, "VISUAL_PREVIEW", variant_index)
        and _latest_variant_stage(db, project, "VISUAL_PREVIEW", variant_index).status == "success"
    ):
        return "CREATIVE_REVIEW"
    config = dict(project.config_json or {})
    state = dict(project.state_json or {})
    series_pointer = dict(state.get("approved_series_slate") or {})
    series_stage = _latest_stage(db, project, "SERIES_DIRECTOR")
    series_ready = bool(
        series_pointer.get("slate_sha256")
        and series_stage is not None
        and series_stage.status == "success"
        and int(series_pointer.get("series_director_stage_id") or 0)
        == int(series_stage.id or 0)
    )
    if config.get("director_series_brief") and not series_ready:
        return "SERIES_DIRECTOR"
    production_stage = _latest_variant_stage(
        db,
        project,
        "PRODUCTION_PLAN",
        variant_index,
    )
    if production_stage and production_stage.status == "success":
        return "VISUAL_PREVIEW"
    director_stage = _latest_variant_stage(
        db,
        project,
        "DIRECTOR",
        variant_index,
    )
    if director_stage and director_stage.status == "success":
        return "PRODUCTION_PLAN"
    return "DIRECTOR"


def _queue_serial_variant_resume_stage(
    db,
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
    reason: str,
) -> HermesContentFactoryStage | None:
    if not _sequential_variants_enabled(project):
        return None
    config = dict(project.config_json or {})
    if not bool(config.get("auto_run", True)) or bool(config.get("manual_paused", False)):
        return None
    pipeline = _variant_pipeline(project)
    target = int(pipeline.get("target_count") or _target_video_count(project))
    if int(variant_index) < 1 or int(variant_index) > target:
        return None
    if not _variant_rollout_authorized(project, int(variant_index)):
        return None
    active_project_stage = (
        db.query(HermesContentFactoryStage)
        .filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        )
        .order_by(HermesContentFactoryStage.id.desc())
        .first()
    )
    if active_project_stage is not None and _stage_owns_publish_lease(active_project_stage):
        # The video waiter and browser worker advance independently. If this
        # project already owns a live execution lease, that turn is authoritative
        # even while the waiter is committing a newly downloaded video. Waiting
        # here prevents a second stage row from superseding the valid retry.
        return None
    pipeline["active_index"] = int(variant_index)
    _set_variant_pipeline(project, pipeline)
    target_stage = _resume_stage_for_serial_variant(db, project, int(variant_index))
    stage = _latest_variant_stage(db, project, target_stage, int(variant_index))
    global_latest_for_target = _latest_stage(db, project, target_stage)
    if (
        stage is not None
        and stage.status in {"queued", "running", "retrying"}
        and _stage_owns_publish_lease(stage)
    ):
        # Completion polling and self-heal are concurrent. Only an active
        # stage with a durable publish lease proves that this exact variant is
        # advancing. A pre-created queued row without a Celery task/run token
        # is merely prepared work and must still be published; treating its
        # status alone as live strands the next serial variant forever.
        return None
    try:
        if (
            stage is not None
            and stage.status != "success"
            and global_latest_for_target is not None
            and int(global_latest_for_target.id) == int(stage.id)
        ):
            _queue_existing_stage(db, project, stage, reason=reason)
        else:
            # Stage delivery supersession is intentionally global per stage name:
            # an older VISUAL_PREVIEW row cannot become authoritative again merely
            # because it belongs to the next variant. Re-publishing that stale row
            # creates a permanent queue/reject loop. Clone its variant context into
            # a fresh row whose id is newer than every other same-name stage.
            stage = _create_repair_stage(
                db,
                project,
                target_stage,
                reason=reason,
                continue_workflow=True,
            )
    except APIError as exc:
        if (
            stage is None
            or exc.code not in {
                "CONTENT_BROWSER_BRIDGE_REQUIRED",
                "CONTENT_BROWSER_BRIDGE_OFFLINE",
                "CONTENT_BROWSER_CAPACITY_FULL",
                "CONTENT_BROWSER_LOCKED_SLOT_UNAVAILABLE",
                "CONTENT_BROWSER_LOGIN_REQUIRED",
                "CONTENT_BROWSER_DEVICE_SELECTION_REQUIRED",
            }
        ):
            raise
        # The video waiter is a media reconciler, not a browser owner.  If it
        # replenishes a serial variant whose prior API chain had already handed
        # off to an unavailable browser, the exception must not kill the waiter
        # every minute.  Let the recovery role atomically choose a cooled return
        # to the enabled API chain (or a bounded wait/pause) while preserving the
        # accepted creative artifact and every completed provider task.
        _recover_browser_fault_with_supervisor(
            db,
            project,
            stage,
            reason=f"{exc.code}: {exc.message}",
            browser_retry_exhausted=True,
        )
        return None
    stage_input = dict(stage.input_json or {})
    stage_input.update({
        "variant_index": int(variant_index),
        "variant_total": target,
        "video_variant_index": int(variant_index),
        "video_variant_total": target,
        "video_variant_mode": "serial_one_complete_video_at_a_time",
        "self_heal_action": "resume_unsubmitted_serial_variant",
        "queue_priority": max(7, int(stage_input.get("queue_priority") or 5)),
    })
    if target_stage == "VISUAL_PREVIEW":
        stage_input.update({
            "allow_visible_visual_recovery": True,
            "browser_recovery_mode": "recover_visible_visual_from_project_tabs",
            "clear_stale_composer_before_send": False,
            "force_fresh_response": False,
        })
    stage.input_json = stage_input
    project.current_stage = target_stage
    project.status = "queued"
    project.last_error = (
        f"串行裂变第 {variant_index}/{target} 条在 {target_stage} 断点恢复；"
        "Hermes 已重新排队，不再停留在等待视频输入。"
    )
    db.add(project)
    db.flush()
    return stage


def _queue_next_unsubmitted_serial_variant_if_needed(
    db,
    project: HermesContentFactoryProject,
    *,
    reason: str,
) -> HermesContentFactoryStage | None:
    if not _sequential_variants_enabled(project):
        return None
    # A terminal failed variant is a hole in the requested deliverable set,
    # not a free parallel slot for a new ordinal.  Let already-submitted API
    # work drain; the terminal completion gate will then regenerate the
    # earliest missing variant before admitting fresh work.
    if _terminal_failed_video_variant_indices(project):
        return None
    inflight = _inflight_api_video_variant_indices(project)
    parallelism = _configured_api_video_variant_parallelism(project)
    if len(inflight) >= parallelism:
        return None
    variant_index = _next_unsubmitted_serial_variant(project)
    if variant_index is None:
        return None
    return _queue_serial_variant_resume_stage(
        db,
        project,
        variant_index=int(variant_index),
        reason=reason,
    )


def _retire_superseded_stage_row(
    db,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> bool:
    """Close a stale execution lease before returning an ignored result."""
    if str(stage_row.status or "").lower() not in {"queued", "running", "retrying"}:
        return False
    stage_row.status = "failed"
    stage_row.error_message = str(reason or "Superseded stage delivery was ignored.")[:4000]
    stage_row.completed_at = _stage_now()
    db.add(stage_row)
    db.commit()
    return True


def _normalize_creative_review_repair_decision(envelope: dict[str, Any]) -> bool:
    """Treat a rejected visual as a valid routing decision, not a dead project.

    A creative reviewer returning ``approved_for_split=false`` has completed its
    job.  The workflow must preserve the rejection and route back to a freshly
    generated visual board instead of retrying the same reviewer indefinitely.
    """
    result = dict(envelope.get("result") or {})
    if bool(result.get("approved_for_split")):
        return False
    envelope["status"] = "PASS"
    evidence = dict(envelope.get("evidence") or {})
    evidence["creative_review_requested_visual_repair"] = True
    evidence["rejected_visual_was_not_accepted"] = True
    envelope["evidence"] = evidence
    return True


def _publish_stage(stage: HermesContentFactoryStage, project: HermesContentFactoryProject) -> str:
    if stage.status != "queued":
        return str(stage.celery_task_id or "")
    if project.status == "paused" or bool(dict(project.config_json or {}).get("manual_paused", False)):
        return str(stage.celery_task_id or "")
    if project.current_stage != stage.stage:
        stage.status = "failed"
        stage.error_message = (
            f"Not published because project moved to {project.current_stage}; "
            "stale queued stage was released before dispatch."
        )
        stage.completed_at = _stage_now()
        return str(stage.celery_task_id or "")
    session = object_session(stage)
    if session is not None:
        if str(session.get_bind().dialect.name or "").lower() == "postgresql":
            # Serialize publishers separately from the long-lived browser
            # execution lock. This closes the race between video completion
            # polling and periodic self-heal before either can dispatch.
            session.execute(
                sql_text("SELECT pg_advisory_xact_lock(:namespace, :project_id)"),
                {"namespace": 72432, "project_id": int(project.id)},
            )
        session.flush()
        # Another publisher may have loaded this same stage before waiting on
        # the transaction advisory lock. Refresh after acquiring the lock so
        # its newly registered task id/run token are visible here.
        session.refresh(stage)
        session.refresh(project)
        if (
            stage.status == "queued"
            and str(stage.celery_task_id or "").strip()
            and _stage_run_token(stage)
            and _stage_owns_publish_lease(stage)
        ):
            return str(stage.celery_task_id)
        active_others = session.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == stage.project_id,
            HermesContentFactoryStage.id != stage.id,
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        ).order_by(HermesContentFactoryStage.id.desc()).all()
        live_owners = [
            other for other in active_others
            if _stage_owns_publish_lease(other)
        ]
        if live_owners:
            owner = sorted(
                live_owners,
                key=lambda row: (
                    {"running": 0, "retrying": 1, "queued": 2}.get(str(row.status), 3),
                    -int(row.id),
                ),
            )[0]
            stage.status = "failed"
            stage.error_message = (
                f"Duplicate publish suppressed: active stage {int(owner.id)} "
                f"({owner.stage}) still owns the project execution lease."
            )
            stage.completed_at = _stage_now()
            project.current_stage = owner.stage
            project.status = "running" if owner.status == "running" else "queued"
            project.last_error = (
                f"{owner.stage} 阶段正在原任务中执行；重复调度已取消，继续等待原任务完成。"
            )
            return str(owner.celery_task_id or "")
        for other in active_others:
            if other.celery_task_id:
                _safe_revoke_task(str(other.celery_task_id), terminate=True, signal="SIGTERM")
            other.status = "failed"
            other.error_message = (
                f"Expired execution lease superseded by stage {int(stage.id)} ({stage.stage}); "
                "the stale delivery was revoked before dispatch."
            )
            other.completed_at = _stage_now()
    stage_input = dict(stage.input_json or {})
    if session is None:
        raise ValueError("BROWSER_BRIDGE_LOCK_MISSING: cannot publish stage without a DB session.")
    api_route = str(
        stage_input.get("api_route")
        or _content_factory_api_route(session, stage.stage, stage_input)
        or ""
    )
    execution_backend = stage_execution_backend(
        stage.stage,
        api_route=api_route,
        stage_input=stage_input,
    )
    if execution_backend != "browser":
        queue_name = project_hermes_queue(project)
        stage_input["execution_backend"] = execution_backend
        if api_route:
            stage_input["api_route"] = api_route
        else:
            stage_input.pop("api_route", None)
        for key in (
            "browser_slot", "browser_bridge_id", "browser_cdp_url", "browser_device_id",
            "browser_device_name", "browser_inbox_root",
        ):
            stage_input.pop(key, None)
    else:
        browser_slot, browser_cdp_url, queue_name = _locked_browser_routing(session, project, stage_input)
        stage_input["browser_slot"] = browser_slot
        stage_input["browser_bridge_id"] = browser_slot
        stage_input["browser_cdp_url"] = browser_cdp_url
    run_token = uuid.uuid4().hex
    celery_task_id = uuid.uuid4().hex
    stage_input["queue"] = queue_name
    stage_input["run_token"] = run_token
    stage.input_json = stage_input
    soft_time_limit, hard_time_limit = _stamp_stage_execution_budget(
        stage,
        project,
    )
    stage.celery_task_id = celery_task_id
    # The broker may deliver immediately. Persist the complete delivery
    # identity before publishing so the worker can always load the stage and
    # validate the same run token. Publishing first produced real
    # ``status=missing`` races under a warm local worker.
    session.add(stage)
    session.add(project)
    session.commit()
    task = run_content_factory_stage.apply_async(
        kwargs={"stage_id": int(stage.id), "run_token": run_token},
        queue=queue_name,
        priority=max(0, min(9, int(stage_input.get("queue_priority") or 5))),
        task_id=celery_task_id,
        soft_time_limit=soft_time_limit,
        time_limit=hard_time_limit,
    )
    return task.id


def _lock_stage_delivery_scope(
    db,
    stage_id: int,
) -> tuple[
    HermesContentFactoryStage | None,
    HermesContentFactoryProject | None,
    int | None,
]:
    """Lock one delivery in the global project-first order.

    API requests and self-heal already lock the project before inspecting its
    stages.  The worker and retry releaser previously did the reverse
    (stage->project), so a burst of stale broker deliveries could deadlock with
    queue_stage and then incorrectly mark a healthy stage failed.  Read the
    immutable FK without a lock, acquire the project row, and only then acquire
    the stage row.
    """
    identity = (
        db.query(HermesContentFactoryStage.project_id)
        .filter(HermesContentFactoryStage.id == int(stage_id))
        .one_or_none()
    )
    if identity is None:
        return None, None, None
    try:
        project_id = int(identity[0])
    except (TypeError, KeyError):
        project_id = int(identity.project_id)
    project = (
        db.query(HermesContentFactoryProject)
        .filter(HermesContentFactoryProject.id == project_id)
        .populate_existing()
        .with_for_update()
        .one_or_none()
    )
    if project is None:
        return None, None, project_id
    stage = (
        db.query(HermesContentFactoryStage)
        .filter(HermesContentFactoryStage.id == int(stage_id))
        .populate_existing()
        .with_for_update()
        .one_or_none()
    )
    return stage, project, project_id


def _is_mysql_deadlock_error(exc: Exception) -> bool:
    if not isinstance(exc, OperationalError):
        return False
    original = getattr(exc, "orig", None)
    args = tuple(getattr(original, "args", ()) or ())
    if args:
        try:
            if int(args[0]) == 1213:
                return True
        except (TypeError, ValueError):
            pass
    return "deadlock found when trying to get lock" in str(exc).lower()


def _repair_final_assets_if_needed(db, project: HermesContentFactoryProject, *, reason: str) -> tuple[HermesContentFactoryStage | None, str | None]:
    # There is nothing to repair for a first-class text-to-video project.  A
    # stale or legacy caller must not create a paid reference-image stage.
    if _configured_video_generation_mode(project) == "text_to_video":
        return None, None
    complete, expected_count, actual_count = _final_assets_are_complete(db, project)
    if complete:
        return None, None
    _clean_final_assets(db, project)
    for stage_name in ("VIDEO_PROMPTS", "EDIT_PACKAGE"):
        for stage in db.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == stage_name,
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        ).all():
            stage.status = "failed"
            stage.error_message = (
                f"Stopped by self-heal because final reference images are incomplete: "
                f"expected={expected_count}, actual={actual_count}."
            )
    final_stage = _latest_stage(db, project, "FINAL_ASSETS")
    repair_reason = f"{reason}; expected={expected_count}, actual={actual_count}"
    if final_stage is None or final_stage.status == "success":
        final_stage = _create_repair_stage(db, project, "FINAL_ASSETS", reason=repair_reason)
    else:
        _queue_existing_stage(db, project, final_stage, reason=repair_reason)
    state = dict(project.state_json or {})
    if state.get("last_split_rejected"):
        final_input = dict(final_stage.input_json or {})
        final_input["force_chatgpt_rebuild"] = True
        final_input["self_heal_action"] = "continue_chatgpt_final_assets_rebuild_after_incomplete_output"
        final_stage.input_json = final_input
    return final_stage, repair_reason


def _reset_visual_preview_after_final_asset_loop(
    db,
    project: HermesContentFactoryProject,
    *,
    reason: str,
    variant_index: int | None = None,
) -> HermesContentFactoryStage:
    if variant_index is None:
        variant_index = _active_variant_index(project)
    _clean_generated_variant_assets(db, project, ("VISUAL_PREVIEW", "FINAL_ASSETS"), variant_index=int(variant_index))
    for stage_name in ("VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS", "VIDEO_PROMPTS", "EDIT_PACKAGE"):
        for stage in db.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == stage_name,
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying", "success")),
        ).all():
            if stage.stage in VARIANT_STAGES and not _stage_matches_variant(stage, project, int(variant_index)):
                continue
            if (
                _sequential_variants_enabled(project)
                and stage.stage not in VARIANT_STAGES
                and _stage_output_variant(stage) is not None
                and not _stage_matches_variant(stage, project, int(variant_index))
            ):
                continue
            stage.status = "failed"
            stage.error_message = (
                "Superseded by final-reference rebuild circuit breaker: "
                + reason
            )[:4000]
    state = dict(project.state_json or {})
    state["last_final_asset_rebuild_circuit_breaker"] = {
        "variant_index": int(variant_index),
        "reason": reason[:1000],
        "at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
    }
    project.state_json = state
    repair_stage = _create_repair_stage(
        db,
        project,
        "VISUAL_PREVIEW",
        reason=(
            "Final reference images repeatedly failed; regenerate one contact sheet made only of native "
            f"{_configured_video_aspect_ratio(project)} panels from the creative plan. Do not create an elongated strip, "
            "product-only crops, unrelated charts, or stale visible images. Each "
            "panel must be large enough to split into an individual target-aspect video reference. "
            + reason[:800]
        ),
    )
    repair_input = dict(repair_stage.input_json or {})
    repair_input["force_fresh_response"] = True
    repair_input["self_heal_action"] = "regenerate_visual_preview_after_final_asset_rebuild_loop"
    repair_input["variant_index"] = int(variant_index)
    repair_input["variant_total"] = _target_video_count(project)
    repair_stage.input_json = repair_input
    project.current_stage = "VISUAL_PREVIEW"
    project.status = "queued"
    project.last_error = "Final reference rebuild loop was stopped; regenerating visual preview."
    return repair_stage


def _reset_production_plan_after_empty_reference_contract(
    db,
    project: HermesContentFactoryProject,
    failed_stage: HermesContentFactoryStage,
    *,
    reason: str,
) -> HermesContentFactoryStage | None:
    """Replan an accepted design that cannot authorize reference generation.

    A signed Production Plan is the sole creative authority for downstream
    media.  If an older plan was accepted with zero generated-reference rows,
    VISUAL_PREVIEW must not infer rows from shots or mutate the signed design.
    Invalidate only the active variant's unusable pointer and return control to
    PRODUCTION_PLAN.  The current author schema now requires at least one row,
    so the bounded author/critic loop either produces a usable replacement or
    enters its normal quality pause without spending image/video quota.
    """
    variant_index = _stage_variant_index(failed_stage, project)
    state = dict(project.state_json or {})
    recovery_by_variant = dict(
        state.get("production_plan_reference_contract_recovery") or {}
    )
    recovery = dict(recovery_by_variant.get(str(variant_index)) or {})
    recovery_count = int(recovery.get("count") or 0)
    if recovery_count >= 2:
        return None

    active_statuses = ("queued", "running", "retrying", "success")
    for stage_name in (
        "PRODUCTION_PLAN",
        "VISUAL_PREVIEW",
        "CREATIVE_REVIEW",
        "FINAL_ASSETS",
        "VIDEO_PROMPTS",
    ):
        rows = (
            db.query(HermesContentFactoryStage)
            .filter(
                HermesContentFactoryStage.project_id == project.id,
                HermesContentFactoryStage.stage == stage_name,
                HermesContentFactoryStage.status.in_(active_statuses),
            )
            .all()
        )
        for row in rows:
            if not _stage_matches_variant(row, project, variant_index):
                continue
            row.status = "failed"
            row.completed_at = row.completed_at or _stage_now()
            row.error_message = (
                "Superseded by source-level Production Plan reference-contract "
                f"repair: {reason}"
            )[:4000]

    pointers = dict(state.get("approved_production_plans_by_variant") or {})
    pointers.pop(str(variant_index), None)
    state["approved_production_plans_by_variant"] = pointers
    current_pointer = dict(state.get("approved_production_plan") or {})
    if int(current_pointer.get("variant_index") or 0) == int(variant_index):
        state.pop("approved_production_plan", None)
    for key in (
        "paused_at",
        "automatic_quality_paused_at",
        "pause_reason_code",
        "pause_note",
        "terminal_self_heal_error",
    ):
        state.pop(key, None)
    recovery_by_variant[str(variant_index)] = {
        "count": recovery_count + 1,
        "last_error": str(reason or "")[:1000],
        "last_replanned_at": _stage_now().isoformat(),
        "self_heal_policy_version": SELF_HEAL_POLICY_VERSION,
    }
    state["production_plan_reference_contract_recovery"] = (
        recovery_by_variant
    )
    project.state_json = state
    config = dict(project.config_json or {})
    config["manual_paused"] = False
    project.config_json = config

    repair_stage = _create_repair_stage(
        db,
        project,
        "PRODUCTION_PLAN",
        reason=(
            "The prior signed plan contained zero generated visual references. "
            "Author and independently review a complete replacement with at "
            "least one cited generated reference before media authorization."
        ),
    )
    repair_input = dict(repair_stage.input_json or {})
    repair_input.update({
        "force_fresh_response": True,
        "self_heal_action": (
            "replan_after_empty_signed_reference_contract"
        ),
        "reference_contract_recovery_count": recovery_count + 1,
        "variant_index": int(variant_index),
    })
    repair_stage.input_json = repair_input
    project.current_stage = "PRODUCTION_PLAN"
    project.status = "queued"
    project.last_error = None
    return repair_stage


def _reset_production_plan_after_invalid_media_contract(
    db,
    project: HermesContentFactoryProject,
    failed_stage: HermesContentFactoryStage,
    *,
    reason: str,
) -> HermesContentFactoryStage:
    """Atomically retire media authorized by a semantically invalid plan.

    A stricter source contract can reveal that an older accepted plan was not
    actually allowed to spend media budget (for example an unbound project
    depicting a generic substitute product).  Merely fixing future validation
    leaves queued dependency segments and later preplanned variants alive.
    Retire every unfinished ordinal from the affected one onward, preserve
    provider-visible results as a forensic/paid-result ledger, and resume from
    one fresh PRODUCTION_PLAN.  The normal serial pipeline then replenishes the
    exact requested completed-video count.
    """

    start_variant = _stage_variant_index(failed_stage, project)
    state = dict(project.state_json or {})
    pipeline = _variant_pipeline(project)
    target = int(
        pipeline.get("target_count") or _target_video_count(project)
    )
    completed = {
        int(value)
        for value in list(pipeline.get("completed_indices") or [])
        if str(value).strip().isdigit()
    }
    invalidated_variants = {
        index
        for index in range(start_variant, target + 1)
        if index not in completed
    }
    if not invalidated_variants:
        invalidated_variants = {start_variant}

    groups = [
        dict(group)
        for group in list(state.get("ai_video_groups") or [])
        if isinstance(group, dict)
    ]
    invalidated_task_ids = {
        int(segment.get("task_id") or 0)
        for group in groups
        if int(group.get("video_index") or 0) in invalidated_variants
        for segment in list(group.get("segments") or [])
        if int(segment.get("task_id") or 0) > 0
    }
    now = _stage_now()
    now_iso = now.isoformat()
    if invalidated_task_ids:
        for task in _scoped_content_video_tasks(
            db,
            project,
            invalidated_task_ids,
        ):
            task_state = str(task.state or "").strip().lower()
            provider_visible = not str(task.task_id or "").startswith(
                "local-"
            )
            if task_state in {"queued_local", "waiting_dependency"}:
                task.state = "failed"
                task.fail_code = CONTENT_FACTORY_VARIANT_SUPERSEDED_CODE
                task.fail_msg = (
                    "Superseded before provider submission because its "
                    "signed content-factory media contract was invalidated."
                )[:512]
            set_task_local_meta(
                task,
                superseded_at=now_iso,
                superseded_reason="invalid_signed_media_contract",
                drain_non_authoritative=bool(
                    provider_visible and not _is_terminal_video_task(task)
                ),
                poll_owner_task_id=None,
                poll_heartbeat_at=None,
                poll_heartbeat_provider=None,
            )
            db.add(task)

        segment_rows = (
            db.query(HermesContentSegmentRun)
            .filter(
                HermesContentSegmentRun.project_id == int(project.id),
                HermesContentSegmentRun.provider_task_row_id.in_(
                    tuple(sorted(invalidated_task_ids))
                ),
            )
            .all()
        )
        for segment_row in segment_rows:
            segment_row.state = "superseded"
            segment_row.error_class = "invalid_signed_media_contract"
            segment_row.error_message = str(reason or "")[:4000]
            segment_row.completed_at = segment_row.completed_at or now
            segment_row.meta_json = {
                **dict(segment_row.meta_json or {}),
                "superseded_at": now_iso,
                "paid_provider_result_preserved": True,
            }
            db.add(segment_row)

    variant_rows = (
        db.query(HermesContentVariantRun)
        .filter(
            HermesContentVariantRun.project_id == int(project.id),
            HermesContentVariantRun.variant_index.in_(
                tuple(sorted(invalidated_variants))
            ),
        )
        .all()
    )
    for variant_row in variant_rows:
        if str(variant_row.state or "").lower() == "composed":
            continue
        variant_row.state = "superseded"
        variant_row.error_class = "invalid_signed_media_contract"
        variant_row.error_message = str(reason or "")[:4000]
        variant_row.completed_at = variant_row.completed_at or now
        variant_row.meta_json = {
            **dict(variant_row.meta_json or {}),
            "superseded_at": now_iso,
            "replacement_starts_at_variant": int(start_variant),
        }
        db.add(variant_row)

    active_statuses = ("queued", "running", "retrying", "success", "paused")
    for stage_name in (
        "PRODUCTION_PLAN",
        "VISUAL_PREVIEW",
        "CREATIVE_REVIEW",
        "FINAL_ASSETS",
        "VIDEO_PROMPTS",
        "EDIT_PACKAGE",
    ):
        rows = (
            db.query(HermesContentFactoryStage)
            .filter(
                HermesContentFactoryStage.project_id == project.id,
                HermesContentFactoryStage.stage == stage_name,
                HermesContentFactoryStage.status.in_(active_statuses),
            )
            .all()
        )
        for row in rows:
            row_variant = _stage_variant_index(row, project)
            if row_variant not in invalidated_variants:
                continue
            row.status = "failed"
            row.completed_at = row.completed_at or now
            row.celery_task_id = None
            row.error_message = (
                "Superseded by source-level invalid signed-media-contract "
                f"repair: {reason}"
            )[:4000]
            db.add(row)

    pointers = dict(state.get("approved_production_plans_by_variant") or {})
    for variant_index in invalidated_variants:
        pointers.pop(str(variant_index), None)
    state["approved_production_plans_by_variant"] = pointers
    current_pointer = dict(state.get("approved_production_plan") or {})
    if int(current_pointer.get("variant_index") or 0) in invalidated_variants:
        state.pop("approved_production_plan", None)

    state["ai_video_groups"] = [
        group
        for group in groups
        if int(group.get("video_index") or 0) not in invalidated_variants
    ]
    state["ai_video_task_ids"] = [
        int(value)
        for value in list(state.get("ai_video_task_ids") or [])
        if str(value).strip().isdigit()
        and int(value) not in invalidated_task_ids
    ]
    for key in (
        "ai_video_failed_task_ids",
        "ai_video_pending_task_ids",
        "ai_video_group_statuses",
        "ai_video_ready_video_count",
        "ai_video_dependency_released_at",
        "ai_video_queued_local_resubmitted_at",
        "paused_at",
        "automatic_quality_paused_at",
        "pause_reason_code",
        "pause_note",
        "terminal_self_heal_error",
    ):
        state.pop(key, None)

    pipeline["active_index"] = int(start_variant)
    pipeline["completed_indices"] = sorted(completed)
    pipeline["completion_blocked_missing_indices"] = [
        index
        for index in range(1, target + 1)
        if index not in completed
    ]
    pipeline["submitted_indices"] = sorted(
        int(value)
        for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit()
        and int(value) not in invalidated_variants
    )
    pipeline["failed_indices"] = sorted(
        int(value)
        for value in list(pipeline.get("failed_indices") or [])
        if str(value).strip().isdigit()
        and int(value) not in invalidated_variants
    )
    pipeline.pop("last_submitted_variant_index", None)
    pipeline.pop("last_submitted_at", None)
    state["video_variant_pipeline"] = pipeline
    state["active_variant_index"] = int(start_variant)
    state["invalid_signed_media_contract_recovery"] = {
        "at": now_iso,
        "reason": str(reason or "")[:1000],
        "start_variant": int(start_variant),
        "invalidated_variants": sorted(invalidated_variants),
        "quarantined_task_ids": sorted(invalidated_task_ids),
        "paid_provider_results_preserved": True,
    }
    project.state_json = state
    config = dict(project.config_json or {})
    config["manual_paused"] = False
    project.config_json = config

    for variant_index in sorted(invalidated_variants):
        _clean_generated_variant_assets(
            db,
            project,
            ("VISUAL_PREVIEW", "FINAL_ASSETS"),
            variant_index=int(variant_index),
        )

    repair_stage = _create_repair_stage(
        db,
        project,
        "PRODUCTION_PLAN",
        reason=(
            "The prior signed media contract was semantically invalid and "
            "has been quarantined before composition. Author and independently "
            "review a complete replacement. "
            + str(reason or "")[:1200]
        ),
    )
    repair_input = dict(repair_stage.input_json or {})
    repair_input.update({
        "force_fresh_response": True,
        "self_heal_action": (
            "replan_after_invalid_signed_media_contract"
        ),
        "automatic_quality_prior_contract_errors": [str(reason or "")[:2000]],
        "variant_index": int(start_variant),
        "invalidated_future_variants": sorted(invalidated_variants),
    })
    repair_stage.input_json = repair_input
    project.current_stage = "PRODUCTION_PLAN"
    project.status = "queued"
    project.last_error = None
    db.add(project)
    db.add(repair_stage)
    db.flush()
    return repair_stage


def _is_production_plan_director_generation_mismatch(
    message: str | None,
) -> bool:
    """Identify a stale signed plan presented to a newer Director artifact.

    This is a deterministic authority mismatch, not a transient image-provider
    failure.  Retrying VISUAL_PREVIEW can never repair it because the media
    gate will continue selecting the same stale successful plan.
    """

    return (
        "PRODUCTION_PLAN_MEDIA_GATE_DIRECTOR_MISMATCH"
        in str(message or "").upper()
    )


def _reconcile_invalid_media_contract_task_markers(
    db,
    project: HermesContentFactoryProject,
) -> int:
    """Restore supersession markers lost to a concurrent provider commit.

    Provider polling intentionally does not hold the project row while waiting
    on an upstream. A contract repair can therefore retire a task while an
    already-running poll owns the task row; its later provider-result commit
    may replace ``result_json.__local`` from an older snapshot. The source
    VIDEO_PROMPTS stage and project group still fail closed, but restore the
    explicit task audit marker on every healer pass so terminal paid results
    remain visibly quarantined as well.
    """

    recovery = dict(
        dict(project.state_json or {}).get(
            "invalid_signed_media_contract_recovery"
        )
        or {}
    )
    task_ids = {
        int(value)
        for value in list(recovery.get("quarantined_task_ids") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    if not task_ids:
        return 0
    reconciled = 0
    now_iso = _stage_now().isoformat()
    for task in _scoped_content_video_tasks(db, project, task_ids):
        meta = dict(dict(task.result_json or {}).get("__local") or {})
        if (
            str(meta.get("superseded_reason") or "")
            == "invalid_signed_media_contract"
            and str(meta.get("superseded_at") or "").strip()
        ):
            continue
        task_state = str(task.state or "").strip().lower()
        provider_visible = not str(task.task_id or "").startswith("local-")
        if task_state in {"queued_local", "waiting_dependency"}:
            task.state = "failed"
            task.fail_code = CONTENT_FACTORY_VARIANT_SUPERSEDED_CODE
            task.fail_msg = (
                "Superseded before provider submission because its signed "
                "content-factory media contract was invalidated."
            )[:512]
        set_task_local_meta(
            task,
            superseded_at=now_iso,
            superseded_reason="invalid_signed_media_contract",
            superseded_marker_reconciled_at=now_iso,
            drain_non_authoritative=bool(
                provider_visible and not _is_terminal_video_task(task)
            ),
            poll_owner_task_id=None,
            poll_heartbeat_at=None,
            poll_heartbeat_provider=None,
        )
        db.add(task)
        reconciled += 1
    return reconciled


def _stage_run_token(stage: HermesContentFactoryStage | None) -> str:
    if stage is None:
        return ""
    return str(dict(stage.input_json or {}).get("run_token") or "").strip()


def _pause_external_input_stage(
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
    *,
    fault_class: str,
    now: datetime | None = None,
) -> str:
    """Pause only when authoritative input cannot be created by the system."""

    current = now or _stage_now()
    message = str(
        stage.error_message
        or project.last_error
        or fault_class
    )[:4000]
    values = dict(stage.input_json or {})
    values.update({
        "external_input_required": True,
        "external_input_fault_class": str(fault_class),
        "external_input_required_at": current.isoformat(),
        "self_heal_policy_version": SELF_HEAL_POLICY_VERSION,
    })
    values.pop("retry_after", None)
    values.pop("retry_release_task_id", None)
    stage.input_json = values
    stage.status = "failed"
    stage.error_message = message
    stage.celery_task_id = None
    stage.completed_at = stage.completed_at or current

    config = dict(project.config_json or {})
    config["manual_paused"] = False
    project.config_json = config
    state = dict(project.state_json or {})
    state.update({
        "paused_at": current.isoformat(),
        "pause_reason_code": "external_input_required",
        "operator_fault_class": str(fault_class),
        "missing_authority": True,
        "pause_note": message[:1000],
    })
    project.state_json = state
    project.status = "paused"
    project.current_stage = stage.stage
    project.last_error = message
    return message


def _terminal_self_heal_error_code(message: str | None) -> str | None:
    """Return the exact deterministic error code that self-heal must not retry."""
    normalized = str(message or "").upper()
    return next(
        (code for code in TERMINAL_SELF_HEAL_ERROR_CODES if code in normalized),
        None,
    )


def _pause_terminal_self_heal_stage(
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
    *,
    error_code: str,
    now: datetime | None = None,
) -> str:
    """Atomically stop a deterministic recovery loop with auditable evidence.

    This is an automatic quality pause, not an operator pause. It prevents the
    periodic healer from burning queue/provider capacity while preserving the
    failed stage and exact error needed for a code or control-plane repair.
    """
    paused_at = (now or _stage_now()).isoformat()
    message = str(
        stage.error_message
        or project.last_error
        or error_code
    )[:4000]
    values = dict(stage.input_json or {})
    values.update({
        "self_heal_terminal": True,
        "self_heal_terminal_error_code": str(error_code),
        "self_heal_terminal_paused_at": paused_at,
        "self_heal_policy_version": SELF_HEAL_POLICY_VERSION,
    })
    values.pop("retry_after", None)
    values.pop("retry_release_task_id", None)
    stage.input_json = values
    stage.status = "failed"
    stage.error_message = message
    stage.celery_task_id = None
    stage.completed_at = stage.completed_at or (now or _stage_now())

    config = dict(project.config_json or {})
    config["manual_paused"] = False
    project.config_json = config
    state = dict(project.state_json or {})
    state.update({
        "paused_at": paused_at,
        "automatic_quality_paused_at": paused_at,
        "pause_reason_code": "terminal_self_heal_contract_error",
        "pause_note": message[:1000],
        "terminal_self_heal_error": {
            "error_code": str(error_code),
            "stage": str(stage.stage),
            "stage_id": int(stage.id) if stage.id is not None else None,
            "at": paused_at,
        },
    })
    project.state_json = state
    project.status = "paused"
    project.current_stage = stage.stage
    project.last_error = message
    return message


def _loop_quality_snapshot(loop_result: Any) -> dict[str, Any]:
    """Compact the latest model review into convergence telemetry only."""

    reviews = list(getattr(loop_result, "reviews", None) or [])
    if not reviews:
        reviews = list(getattr(loop_result, "global_reviews", None) or [])
    if not reviews:
        return quality_snapshot(scores={}, issue_codes=[])
    verdict = getattr(reviews[-1], "verdict", None)
    scores = dict(getattr(verdict, "scores", None) or {})
    issues = list(getattr(verdict, "blocking_issues", None) or [])
    return quality_snapshot(
        scores=scores,
        issue_codes=[
            str(getattr(item, "code", "") or "")
            for item in issues
        ],
    )


def _automatic_quality_recovery_decision(
    project: HermesContentFactoryProject,
    *,
    now: datetime,
    generation: str,
) -> dict[str, Any]:
    """Plan the next cooled recovery epoch for a control-plane quality pause.

    Each epoch is bounded, but exhaustion is not an operator boundary.  The
    durable record tracks convergence and escalates repair scope after cooldown.
    Final-media recovery uses its own segment-scoped planner; manual pauses and
    genuinely missing external authority remain authoritative.
    """
    config = dict(project.config_json or {})
    state = dict(project.state_json or {})
    record = dict(state.get("automatic_quality_recovery") or {})
    reason = str(state.get("pause_reason_code") or "").strip().lower()
    terminal = dict(state.get("terminal_self_heal_error") or {})
    terminal_replan_recovery = bool(
        reason == "terminal_self_heal_contract_error"
        and str(project.current_stage or "").strip().upper() == "DIRECTOR"
        and str(terminal.get("error_code") or "").strip().upper()
        == "DIRECTOR_RESUME_ANCESTOR_APPROVED"
        and str(record.get("status") or "").strip().lower() == "replanning"
        and str(record.get("pause_reason_code") or "").strip().lower()
        == "content_director_quality_pause"
        and bool(_persisted_director_replan_context(project)[0])
    )
    if terminal_replan_recovery:
        # A prior recovery delivery lost its upstream authorization packet.
        # Narrowly recover that evidenced incident under a newer policy; all
        # other terminal contract failures remain non-retryable.
        reason = "content_director_quality_pause"
    pause_payload_key = {
        "series_director_quality_pause": "content_series_quality_pause",
        "content_director_quality_pause": "content_director_quality_pause",
        "production_plan_quality_pause": "production_plan_quality_pause",
        "creative_visual_replan_exhausted": "creative_visual_replan_exhausted",
    }.get(reason, "")
    pause_payload = dict(state.get(pause_payload_key) or {})
    try:
        source_stage_id = int(pause_payload.get("stage_id") or 0)
    except (TypeError, ValueError):
        source_stage_id = 0
    try:
        source_variant_index = int(pause_payload.get("variant_index") or 0)
    except (TypeError, ValueError):
        source_variant_index = 0
    paused_at = str(
        pause_payload.get("at")
        or state.get("automatic_quality_paused_at")
        or state.get("paused_at")
        or ""
    ).strip()
    current_incident_key = ":".join((
        reason,
        f"stage-{source_stage_id}" if source_stage_id else "stage-unknown",
        (
            f"variant-{source_variant_index}"
            if source_variant_index
            else "variant-series"
        ),
        paused_at or "time-unknown",
    ))
    try:
        recorded_variant_index = int(record.get("variant_index") or 0)
    except (TypeError, ValueError):
        recorded_variant_index = 0
    same_recovery_chain = (
        str(record.get("generation") or "") == str(generation)
        and str(record.get("pause_reason_code") or "").strip().lower()
        == reason
        and str(record.get("status") or "").strip().lower()
        == "replanning"
        and bool(str(record.get("incident_key") or "").strip())
        and (
            source_variant_index == 0
            or recorded_variant_index == source_variant_index
        )
    )
    incident_key = (
        str(record.get("incident_key"))
        if same_recovery_chain
        else current_incident_key
    )
    same_generation = (
        str(record.get("generation") or "") == str(generation)
        and str(record.get("pause_reason_code") or "").strip().lower()
        == reason
        and str(record.get("incident_key") or "") == incident_key
    )
    attempt_count = (
        max(0, int(record.get("attempt_count") or 0))
        if same_generation
        else 0
    )
    attempt_limit = derive_quality_recovery_limit(
        config,
        pause_reason=reason,
    )
    current_snapshot = dict(pause_payload.get("autonomy_snapshot") or {})
    previous_snapshot = (
        dict(record.get("last_quality_snapshot") or {})
        if same_generation
        else {}
    )
    convergence = convergence_state(previous_snapshot, current_snapshot)
    no_progress_cycles = (
        max(0, int(record.get("no_progress_cycles") or 0))
        if same_generation
        else 0
    )
    if current_snapshot and previous_snapshot:
        no_progress_cycles = (
            no_progress_cycles + 1
            if convergence["no_progress"]
            else 0
        )
    budget_epoch = (
        max(0, int(record.get("budget_epoch") or 0))
        if same_generation
        else 0
    )
    decision = {
        "eligible": False,
        "due": False,
        "pause_reason_code": reason,
        "attempt_count": attempt_count,
        "attempt_limit": attempt_limit,
        "budget_epoch": budget_epoch,
        "generation": str(generation),
        "incident_key": incident_key,
        "source_stage_id": source_stage_id or None,
        "variant_index": source_variant_index or None,
        "next_retry_at": None,
        "quality_snapshot": current_snapshot,
        "convergence": convergence,
        "no_progress_cycles": no_progress_cycles,
        "strategy": recovery_strategy(
            attempt_count=attempt_count + 1,
            no_progress_cycles=no_progress_cycles,
        ),
        "policy_version": AUTONOMY_POLICY_VERSION,
    }
    if (
        str(project.status or "").strip().lower() != "paused"
        or bool(config.get("manual_paused", False))
        or not bool(config.get("auto_run", True))
        or reason not in AUTOMATIC_QUALITY_RECOVERY_REASONS
    ):
        return decision
    decision["eligible"] = True
    if attempt_count >= attempt_limit:
        # A completed recovery epoch is an unattended circuit breaker, not an
        # operator boundary.  Start the next epoch only after a longer cooled
        # interval and force a materially different candidate strategy.
        epoch_retry_raw = str(record.get("next_epoch_at") or "").strip()
        try:
            epoch_retry_at = (
                datetime.fromisoformat(epoch_retry_raw)
                if epoch_retry_raw
                else datetime.fromisoformat(
                    str(record.get("last_attempt_at") or now.isoformat())
                )
            )
        except ValueError:
            epoch_retry_at = now
        if not epoch_retry_raw:
            epoch_retry_at = epoch_retry_at + timedelta(
                seconds=min(21600, 900 * (2 ** min(4, budget_epoch)))
            )
        decision["next_retry_at"] = epoch_retry_at.isoformat()
        if epoch_retry_at <= now:
            decision.update({
                "due": True,
                "attempt_count": 0,
                "budget_epoch": budget_epoch + 1,
                "strategy": "alternate_candidate",
                "epoch_reset": True,
            })
        return decision

    retry_at = None
    retry_raw = str(record.get("next_retry_at") or "").strip()
    if same_generation and retry_raw:
        try:
            retry_at = datetime.fromisoformat(retry_raw)
        except ValueError:
            retry_at = None
    if retry_at is None:
        paused_raw = str(
            state.get("automatic_quality_paused_at")
            or state.get("paused_at")
            or ""
        ).strip()
        try:
            paused_at = datetime.fromisoformat(paused_raw) if paused_raw else now
        except ValueError:
            paused_at = now
        retry_at = paused_at + timedelta(
            seconds=AUTOMATIC_QUALITY_RECOVERY_COOLDOWN_SECONDS
        )
    decision["next_retry_at"] = retry_at.isoformat()
    decision["due"] = retry_at <= now
    return decision


def _mark_automatic_quality_recovery_resolved(
    state: dict[str, Any],
    *,
    stage_name: str,
    stage_id: int,
    variant_index: int | None,
) -> dict[str, Any]:
    """Close a recovery chain only after its originally paused stage passes."""
    values = dict(state or {})
    record = dict(values.get("automatic_quality_recovery") or {})
    expected_stage = {
        "series_director_quality_pause": "SERIES_DIRECTOR",
        "content_director_quality_pause": "DIRECTOR",
        "production_plan_quality_pause": "PRODUCTION_PLAN",
        "creative_visual_replan_exhausted": "DIRECTOR",
    }.get(str(record.get("pause_reason_code") or "").strip().lower())
    if (
        str(record.get("status") or "").strip().lower() != "replanning"
        or expected_stage != str(stage_name or "").strip().upper()
    ):
        return values
    try:
        recorded_variant = int(record.get("variant_index") or 0)
    except (TypeError, ValueError):
        recorded_variant = 0
    completed_variant = int(variant_index or 0)
    if recorded_variant and recorded_variant != completed_variant:
        return values
    record.update({
        "status": "resolved",
        "resolved_at": _stage_now().isoformat(),
        "resolved_stage_id": int(stage_id),
    })
    values["automatic_quality_recovery"] = record
    return values


def _schedule_exhausted_self_heal_stage(
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
    *,
    now: datetime | None = None,
) -> datetime:
    """Open a durable circuit breaker instead of permanently failing recoverable work.

    The short retry budget protects providers and ChatGPT from hot loops. Once
    exhausted, the periodic self-healer owns the next attempt after a persisted
    per-project cooldown. A daily ceiling rolls the next attempt into the next
    day, so a transient outage cannot either burn quota forever or strand the
    project forever.
    """
    current = now or _stage_now()
    values = dict(stage.input_json or {})
    day_key = current.date().isoformat()
    stored_day = str(values.get("self_heal_cooldown_day") or "").strip()
    try:
        daily_cycle = int(values.get("self_heal_daily_cooldown_cycle") or 0)
    except (TypeError, ValueError):
        daily_cycle = 0
    if stored_day != day_key:
        daily_cycle = 0
    try:
        total_cycle = int(values.get("self_heal_total_cooldown_cycles") or 0)
    except (TypeError, ValueError):
        total_cycle = 0

    if daily_cycle >= SELF_HEAL_MAX_DAILY_COOLDOWN_CYCLES:
        retry_at = (current + timedelta(days=1)).replace(hour=0, minute=5, second=0, microsecond=0)
        next_daily_cycle = 0
        next_day_key = retry_at.date().isoformat()
    else:
        delay_index = min(daily_cycle, len(SELF_HEAL_COOLDOWN_SECONDS) - 1)
        retry_at = current + timedelta(seconds=SELF_HEAL_COOLDOWN_SECONDS[delay_index])
        next_daily_cycle = daily_cycle + 1
        next_day_key = day_key

    original_error = str(
        values.get("self_heal_original_error")
        or stage.error_message
        or project.last_error
        or "Automatic recovery limit reached"
    )[:4000]
    values.update({
        "self_heal_circuit_open": True,
        "self_heal_cooldown_day": next_day_key,
        "self_heal_daily_cooldown_cycle": next_daily_cycle,
        "self_heal_total_cooldown_cycles": total_cycle + 1,
        "self_heal_cooldown_started_at": current.isoformat(),
        "self_heal_original_error": original_error,
        "retry_after": retry_at.isoformat(),
        "automatic_retry_count": 0,
        "self_heal_policy_version": SELF_HEAL_POLICY_VERSION,
    })
    stage.input_json = values
    stage.status = "retrying"
    stage.error_message = original_error
    stage.celery_task_id = None
    stage.started_at = None
    stage.completed_at = None
    project.status = "queued"
    project.current_stage = stage.stage
    project.last_error = (
        f"{original_error[:3000]} Automatic recovery is cooling down and will resume at "
        f"{retry_at.strftime('%Y-%m-%d %H:%M:%S')}."
    )[:4000]
    return retry_at


def _prepare_visual_stage_for_fresh_retry(
    stage: HermesContentFactoryStage,
    *,
    action: str,
) -> None:
    values = dict(stage.input_json or {})
    values["force_fresh_response"] = True
    values["clear_stale_composer_before_send"] = True
    values["allow_visible_visual_recovery"] = False
    values["self_heal_action"] = action
    values["visual_grid_repair_count"] = 0
    values.pop("visual_api", None)
    values.pop("api_primary_error", None)
    stage.input_json = values


def _prepare_exhausted_self_heal_release(
    stage: HermesContentFactoryStage,
    *,
    now: datetime | None = None,
) -> None:
    """Reset only the short retry budget when a durable cooldown expires."""
    current = now or _stage_now()
    values = dict(stage.input_json or {})
    values["self_heal_circuit_open"] = False
    values["self_heal_count"] = 0
    values["automatic_retry_count"] = 0
    values["self_heal_last_cooldown_released_at"] = current.isoformat()
    values.pop("retry_after", None)
    values.pop("run_token", None)
    values.pop("visual_recovery_exhausted", None)
    values.pop("response_recovery_probe_count", None)
    values.pop("response_fresh_regeneration_count", None)
    stage.input_json = values
    if stage.stage == "VISUAL_PREVIEW":
        _prepare_visual_stage_for_fresh_retry(
            stage,
            action="regenerate_visual_after_circuit_cooldown",
        )


def _upgrade_self_heal_policy_generation(
    stage: HermesContentFactoryStage,
    *,
    now: datetime,
) -> tuple[int, dict[str, Any]]:
    """Apply a new recovery capability without inheriting an old bug budget.

    A policy bump means source code can now repair a failure that opened the
    previous generation's circuit.  Keeping its future ``retry_after`` wastes
    deployment recovery time.  Clear that circuit only for non-running rows;
    an active delivery retains its run token and lease so a deploy cannot
    duplicate an in-flight provider submission.
    """
    values = dict(stage.input_json or {})
    heal_count = int(values.get("self_heal_count") or 0)
    policy_version = int(values.get("self_heal_policy_version") or 0)
    if policy_version == SELF_HEAL_POLICY_VERSION:
        return heal_count, values
    if (
        str(stage.status or "").lower() != "running"
        and bool(values.get("self_heal_circuit_open"))
    ):
        _prepare_exhausted_self_heal_release(stage, now=now)
        values = dict(stage.input_json or {})
        values["self_heal_action"] = (
            "retry_immediately_after_source_policy_upgrade"
        )
    values["self_heal_count"] = 0
    values["self_heal_policy_version"] = SELF_HEAL_POLICY_VERSION
    stage.input_json = values
    return 0, values


def _is_transient_provider_error(message: str) -> bool:
    value = str(message or "").lower()
    return any(marker in value for marker in (
        "system_cpu_overloaded",
        "cpu overloaded",
        "http 429",
        "http 502",
        "http 503",
        "http 504",
        "temporarily unavailable",
        "upstream timeout",
        "connection reset",
    ))


def _stage_owns_publish_lease(
    stage: HermesContentFactoryStage,
    *,
    now: datetime | None = None,
) -> bool:
    """Return whether an already published stage still owns the project slot.

    Video completion polling, periodic self-heal, and the browser worker can
    observe the same transition concurrently. A fresh running/queued stage is
    authoritative even if its Celery result backend is briefly stale. Replacing
    it would terminate a valid ChatGPT turn and submit the same stage again.
    """
    current = now or _stage_now()
    status = str(stage.status or "").strip().lower()
    values = dict(stage.input_json or {})
    if status == "retrying":
        retry_after_raw = str(values.get("retry_after") or "").strip()
        try:
            retry_after = datetime.fromisoformat(retry_after_raw) if retry_after_raw else None
        except ValueError:
            retry_after = None
        if retry_after is not None:
            # A retry row is deliberately not running provider/browser work.
            # Its durable database deadline is the lease authority.  Older
            # deliveries left their execution lease on the row, which made a
            # 20-second retry wait for the full 20-minute execution window
            # before periodic self-heal could publish it again.
            return retry_after >= current - timedelta(seconds=30)
    if status not in {"queued", "running", "retrying"}:
        return False
    lease_expires_raw = str(
        values.get("execution_lease_expires_at") or ""
    ).strip()
    if lease_expires_raw:
        try:
            lease_expires = datetime.fromisoformat(
                lease_expires_raw
            ).replace(tzinfo=None)
        except ValueError:
            lease_expires = None
        if lease_expires is not None:
            return lease_expires >= current
    lease_started = stage.started_at or stage.created_at
    if lease_started is None:
        return bool(str(stage.celery_task_id or "").strip())
    return lease_started >= current - timedelta(minutes=STAGE_EXECUTION_LEASE_MINUTES)


def _completion_pointer_allows_parallel_video_lane(
    *,
    project_stage: str | None,
    task_stage: str | None,
    task_has_live_lease: bool,
    latest_same_stage_is_task: bool,
    competing_stage_has_live_lease: bool,
) -> bool:
    """Keep a valid control result when the media lane owns the UI pointer.

    ``current_stage`` is a presentation/control pointer, not an execution
    lease.  The API-video waiter may legitimately run beside the next
    Director/Plan/visual turn.  Older code changed the pointer to
    ``WAITING_VIDEO_INPUT`` during a provider cooldown; the control stage then
    discarded an expensive, valid model result at its completion fence even
    though its stage row still owned the only live execution lease.

    A non-video pointer mismatch remains fail-closed.  The narrow exception is
    safe only when this exact row is still the newest row for its stage, still
    owns its lease, and no competing control row owns another lease.
    """

    current = str(project_stage or "").strip().upper()
    expected = str(task_stage or "").strip().upper()
    if current == expected:
        return True
    return bool(
        current == "WAITING_VIDEO_INPUT"
        and task_has_live_lease
        and latest_same_stage_is_task
        and not competing_stage_has_live_lease
    )


def _stage_completion_pointer_is_authoritative(
    db,
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
) -> bool:
    latest_same_stage = _latest_stage(db, project, str(stage.stage or ""))
    competing_live = any(
        _stage_owns_publish_lease(other)
        for other in db.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == int(project.id),
            HermesContentFactoryStage.id != int(stage.id),
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        ).all()
    )
    return _completion_pointer_allows_parallel_video_lane(
        project_stage=project.current_stage,
        task_stage=stage.stage,
        task_has_live_lease=_stage_owns_publish_lease(stage),
        latest_same_stage_is_task=(
            latest_same_stage is not None
            and int(latest_same_stage.id) == int(stage.id)
        ),
        competing_stage_has_live_lease=competing_live,
    )


def _project_has_live_control_stage(
    db,
    project: HermesContentFactoryProject,
) -> bool:
    """Return whether the media waiter must leave the control pointer alone."""

    return any(
        _stage_owns_publish_lease(stage)
        for stage in db.query(HermesContentFactoryStage).filter(
            HermesContentFactoryStage.project_id == int(project.id),
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        ).all()
    )


def _is_current_stage_delivery(
    stage: HermesContentFactoryStage | None,
    *,
    request_id: str,
    run_token: str | None,
) -> bool:
    if stage is None:
        return False
    if str(stage.status or "").lower() not in {"queued", "running", "retrying"}:
        return False
    current_task_id = str(stage.celery_task_id or "").strip()
    current_run_token = _stage_run_token(stage)
    if current_task_id and request_id:
        return current_task_id == request_id
    if current_run_token:
        if bool(run_token) and str(run_token).strip() == current_run_token:
            return True
        return False
    return True


def _acquire_project_execution_guard(db, project_id: int):
    """Hold a database advisory lock for the complete stage execution.

    Production uses MySQL. Treating every non-PostgreSQL dialect as already
    locked allowed two Celery deliveries for one project to submit provider
    work concurrently. MySQL GET_LOCK gives the same fail-fast, connection-
    scoped ownership guarantee as the PostgreSQL advisory lock.
    """
    engine = db.get_bind()
    dialect = str(engine.dialect.name or "").lower()
    if dialect not in {"postgresql", "mysql", "mariadb"}:
        return True, None
    connection = engine.connect()
    try:
        if dialect == "postgresql":
            acquired = bool(connection.execute(
                sql_text("SELECT pg_try_advisory_lock(:namespace, :project_id)"),
                {"namespace": 72431, "project_id": int(project_id)},
            ).scalar())
        else:
            acquired = int(connection.execute(
                sql_text("SELECT GET_LOCK(:lock_name, 0)"),
                {"lock_name": f"gmv_cf_exec:{int(project_id)}"},
            ).scalar() or 0) == 1
        if acquired:
            return True, connection
    except Exception:
        connection.close()
        raise
    connection.close()
    return False, None


def _release_project_execution_guard(connection, project_id: int) -> None:
    if connection is None:
        return
    try:
        dialect = str(connection.dialect.name or "").lower()
        if dialect == "postgresql":
            connection.execute(
                sql_text("SELECT pg_advisory_unlock(:namespace, :project_id)"),
                {"namespace": 72431, "project_id": int(project_id)},
            )
        elif dialect in {"mysql", "mariadb"}:
            connection.execute(
                sql_text("SELECT RELEASE_LOCK(:lock_name)"),
                {"lock_name": f"gmv_cf_exec:{int(project_id)}"},
            )
        connection.commit()
    finally:
        connection.close()


def _reschedule_current_stage_after_execution_lock_collision(
    db,
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
    *,
    request_id: str,
    delivery_run_token: str,
) -> dict[str, Any] | None:
    """Keep the authoritative queued delivery alive while its predecessor exits.

    A stage publishes its successor before its outer ``finally`` releases the
    project advisory lock. A concurrent worker can consume that successor
    during this tiny interval. Reassign only the exact current delivery to a
    delayed task; stale deliveries remain ignored. Repeated collisions back
    off into a durable timer instead of producing unbounded broker churn.
    """
    stage_input = dict(stage.input_json or {})
    registered_task_id = str(stage.celery_task_id or "").strip()
    registered_run_token = _stage_run_token(stage)
    supplied_task_id = str(request_id or "").strip()
    supplied_run_token = str(delivery_run_token or "").strip()
    owns_delivery = (
        str(stage.status or "").lower() in {"queued", "retrying"}
        and project.current_stage == stage.stage
        and project.status != "paused"
        and not bool(dict(project.config_json or {}).get("manual_paused", False))
        and bool(registered_task_id)
        and registered_task_id == supplied_task_id
        and (
            not registered_run_token
            or registered_run_token == supplied_run_token
        )
    )
    if not owns_delivery:
        return None

    collision_count = int(stage_input.get("project_execution_lock_retry_count") or 0) + 1
    stage_input["project_execution_lock_retry_count"] = collision_count
    stage_input["project_execution_lock_last_at"] = _stage_now().isoformat()
    stage_input["self_heal_action"] = "defer_successor_until_predecessor_releases_project_lock"
    stage_input.pop("retry_after", None)
    stage_input.pop("retry_release_task_id", None)

    # Celery reserves ETA/countdown messages against worker QoS before they are
    # due. A few project-lock collisions could therefore occupy every Hermes
    # prefork slot for minutes while doing no work. Keep the delay durable in
    # MySQL instead; the one-minute self-heal beat publishes it only after it
    # becomes due, so waiting retries consume neither a worker slot nor a
    # long-lived Python process.
    cooldown_seconds = (
        min(30, 2 ** min(collision_count, 5))
        if collision_count <= 12
        else 300
    )
    retry_after = _stage_now() + timedelta(seconds=cooldown_seconds)
    stage_input["retry_after"] = retry_after.isoformat()
    stage_input.pop("retry_release_task_id", None)
    stage_input["retry_release_strategy"] = "database_due_at_periodic_self_heal"
    stage_input["self_heal_action"] = (
        "defer_successor_until_predecessor_releases_project_lock"
        if collision_count <= 12
        else "cooldown_after_repeated_project_execution_lock_collisions"
    )
    stage.input_json = stage_input
    stage.status = "retrying"
    stage.celery_task_id = None
    stage.error_message = (
        "Successor delivery is waiting for the preceding stage to release the project execution lock."
    )
    project.status = "queued"
    project.last_error = stage.error_message
    db.add(stage)
    db.add(project)
    db.commit()
    return {
        "status": "project_execution_lock_cooldown_scheduled",
        "stage_id": int(stage.id),
        "retry_in_seconds": cooldown_seconds,
        "collision_count": collision_count,
        "release_strategy": "periodic_self_heal",
    }


def _chmod_group_writable(path: Path) -> None:
    try:
        path.chmod(path.stat().st_mode | 0o660)
    except OSError:
        pass


def _format_srt_timestamp(seconds: float) -> str:
    total_ms = max(0, int(round(float(seconds or 0) * 1000)))
    hours, remainder = divmod(total_ms, 3_600_000)
    minutes, remainder = divmod(remainder, 60_000)
    secs, millis = divmod(remainder, 1_000)
    return f"{hours:02}:{minutes:02}:{secs:02},{millis:03}"


def _segments_to_srt_text(segments: list[dict[str, Any]]) -> str:
    lines: list[str] = []
    for index, segment in enumerate(segments or [], 1):
        text = str(segment.get("text") or "").strip()
        if not text:
            continue
        lines.extend([
            str(index),
            f"{_format_srt_timestamp(float(segment.get('start') or 0))} --> {_format_srt_timestamp(float(segment.get('end') or 0))}",
            text,
            "",
        ])
    return "\n".join(lines).strip() + "\n"


def _ffmpeg_binary() -> str:
    return FFMPEG_BIN if Path(FFMPEG_BIN).exists() else "ffmpeg"


def _ffprobe_binary() -> str:
    return FFPROBE_BIN if Path(FFPROBE_BIN).exists() else "ffprobe"


def _probe_video_duration_seconds(video_path: Path) -> float:
    try:
        output = subprocess.check_output(
            [
                _ffprobe_binary(),
                "-v", "error",
                "-show_entries", "format=duration",
                "-of", "default=noprint_wrappers=1:nokey=1",
                str(video_path),
            ],
            stderr=subprocess.STDOUT,
        ).decode("utf-8", errors="ignore").strip()
        return max(0.0, float(output)) if output else 0.0
    except Exception:
        return 0.0


def _best_contact_sheet_grid(frame_count: int) -> tuple[int, int]:
    count = max(1, int(frame_count or 1))
    best_rows, best_cols = 1, count
    best_score = abs(best_cols - best_rows)
    for rows in range(1, count + 1):
        cols = math.ceil(count / rows)
        score = abs(cols - rows)
        if score < best_score or (score == best_score and cols < best_cols):
            best_rows, best_cols, best_score = rows, cols, score
    return best_rows, best_cols


def _extract_benchmark_frames(
    video_path: Path,
    frames_dir: Path,
    *,
    interval_seconds: float = 2.0,
    max_frames: int = 12,
) -> list[Path]:
    if frames_dir.exists():
        shutil.rmtree(frames_dir, ignore_errors=True)
    frames_dir.mkdir(parents=True, exist_ok=True)
    pattern = frames_dir / "frame_%03d.png"
    cmd = [
        _ffmpeg_binary(), "-y", "-i", str(video_path),
        "-vf", f"fps=1/{max(0.5, float(interval_seconds))},scale=360:640:force_original_aspect_ratio=increase,crop=360:640",
        "-frames:v", str(max(1, int(max_frames))),
        str(pattern),
    ]
    subprocess.run(cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    frames = sorted(frames_dir.glob("frame_*.png"))
    if frames:
        return frames
    fallback = frames_dir / "frame_001.png"
    fallback_cmd = [
        _ffmpeg_binary(), "-y", "-i", str(video_path),
        "-frames:v", "1",
        "-vf", "scale=360:640:force_original_aspect_ratio=increase,crop=360:640",
        str(fallback),
    ]
    subprocess.run(fallback_cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return [fallback] if fallback.is_file() else []


def _render_benchmark_contact_sheet(
    video_path: Path,
    output_path: Path,
    *,
    interval_seconds: float = 2.0,
    max_frames: int = 12,
) -> tuple[Path, int]:
    frames_dir = output_path.parent / "frames"
    frames = _extract_benchmark_frames(video_path, frames_dir, interval_seconds=interval_seconds, max_frames=max_frames)
    if not frames:
        raise RuntimeError("No keyframes extracted from benchmark video.")
    result = _render_benchmark_frame_sheet(frames, output_path, global_start_index=1)
    shutil.rmtree(frames_dir, ignore_errors=True)
    return result


def _render_benchmark_frame_sheet(
    frames: list[Path],
    output_path: Path,
    *,
    global_start_index: int,
) -> tuple[Path, int]:
    rows, cols = _best_contact_sheet_grid(len(frames))
    thumb_w, thumb_h, margin = 360, 640, 10
    canvas = Image.new("RGB", (cols * thumb_w + (cols + 1) * margin, rows * thumb_h + (rows + 1) * margin), (245, 247, 250))
    draw = ImageDraw.Draw(canvas)
    for index, frame_path in enumerate(frames, 1):
        with Image.open(frame_path) as frame:
            thumb = frame.convert("RGB").resize((thumb_w, thumb_h), Image.Resampling.LANCZOS)
        row, col = divmod(index - 1, cols)
        x = margin + col * (thumb_w + margin)
        y = margin + row * (thumb_h + margin)
        canvas.paste(thumb, (x, y))
        draw.rectangle([x + 8, y + 8, x + 46, y + 42], fill=(0, 0, 0))
        draw.text((x + 18, y + 14), str(global_start_index + index - 1), fill=(255, 255, 255))
    output_path.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(output_path, "PNG", optimize=True)
    _chmod_group_writable(output_path)
    return output_path, len(frames)


def _render_benchmark_contact_sheets(
    video_path: Path,
    output_dir: Path,
    *,
    source_asset_id: int,
    duration_seconds: float,
    interval_seconds: float = 2.0,
    frames_per_sheet: int = 12,
) -> list[dict[str, Any]]:
    """Extract the full benchmark timeline into ordered, readable sheets."""
    # Cover the complete source, including long benchmarks. Keep the upload
    # set bounded while increasing the sampling interval when 2-second frames
    # would exceed ten readable 12-frame sheets.
    frame_budget = 120
    effective_interval = max(
        float(interval_seconds),
        float(duration_seconds) / float(max(1, frame_budget - 1)),
    )
    max_frames = max(
        1,
        min(frame_budget, int(math.ceil(max(0.0, duration_seconds) / effective_interval)) + 1),
    )
    frames_dir = output_dir / "frames"
    frames = _extract_benchmark_frames(
        video_path,
        frames_dir,
        interval_seconds=effective_interval,
        max_frames=max_frames,
    )
    if not frames:
        raise RuntimeError("No keyframes extracted from benchmark video.")
    sheets: list[dict[str, Any]] = []
    chunk_size = max(4, min(12, int(frames_per_sheet or 12)))
    for board_index, offset in enumerate(range(0, len(frames), chunk_size), 1):
        chunk = frames[offset:offset + chunk_size]
        output_path = output_dir / (
            f"benchmark-keyframes-{int(source_asset_id)}-sheet-{board_index:02d}.png"
        )
        _render_benchmark_frame_sheet(
            chunk,
            output_path,
            global_start_index=offset + 1,
        )
        sheets.append({
            "path": output_path,
            "board_index": board_index,
            "frame_start": offset + 1,
            "frame_end": offset + len(chunk),
            "start_second": round(offset * effective_interval, 2),
            "end_second": round(min(duration_seconds, (offset + len(chunk)) * effective_interval), 2),
            "frame_count": len(chunk),
            "interval_seconds": round(effective_interval, 4),
        })
    shutil.rmtree(frames_dir, ignore_errors=True)
    return sheets


def _write_benchmark_asset(
    db,
    *,
    project: HermesContentFactoryProject,
    source_asset: HermesContentFactoryAsset,
    user_id: int,
    path: Path,
    kind: str,
    mime_type: str,
    role: str,
    meta: dict[str, Any] | None = None,
) -> HermesContentFactoryAsset:
    bridge_dir = BROWSER_INBOX_ROOT / f"workspace_{project.workspace_id}" / project.project_key
    bridge_dir.mkdir(parents=True, exist_ok=True)
    bridge_name = f"benchmark-{int(source_asset.id)}-{path.name}"
    bridge_path = bridge_dir / bridge_name
    if not bridge_path.exists() or bridge_path.stat().st_size != path.stat().st_size:
        shutil.copy2(path, bridge_path)
    _chmod_group_writable(bridge_path)
    row = HermesContentFactoryAsset(
        project_id=project.id,
        workspace_id=project.workspace_id,
        user_id=user_id,
        stage=BENCHMARK_VIDEO_STAGE,
        kind=kind,
        original_name=path.name,
        file_path=str(path),
        mime_type=mime_type,
        size_bytes=path.stat().st_size,
        meta_json={
            "asset_role": role,
            "source": "benchmark_video_analysis",
            "source_asset_id": int(source_asset.id),
            "bridge_path": str(bridge_path),
            "browser_inbox_relative": f"workspace_{project.workspace_id}/{project.project_key}/{bridge_name}",
            **dict(meta or {}),
        },
    )
    db.add(row)
    db.flush()
    return row


@celery_app.task(
    name="hermes_content_factory.analyze_reference_video",
    queue=settings.HERMES_AGENT_TASK_QUEUE,
)
def analyze_content_factory_reference_video(*, asset_id: int) -> dict[str, Any]:
    """Transcribe and keyframe a benchmark/reference video for Content Factory."""
    with SessionLocal() as db:
        asset = db.query(HermesContentFactoryAsset).filter(HermesContentFactoryAsset.id == int(asset_id)).one_or_none()
        if asset is None:
            return {"status": "missing_asset", "asset_id": int(asset_id)}
        project = db.query(HermesContentFactoryProject).filter(HermesContentFactoryProject.id == int(asset.project_id)).one_or_none()
        if project is None:
            return {"status": "missing_project", "asset_id": int(asset_id)}
        video_path = Path(str(asset.file_path or ""))
        if not video_path.is_file():
            return {"status": "missing_file", "asset_id": int(asset_id), "path": str(video_path)}

        state = dict(project.state_json or {})
        state["benchmark_video_analysis"] = {
            "status": "running",
            "source_asset_id": int(asset.id),
            "started_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        }
        project.state_json = state
        asset.meta_json = {**dict(asset.meta_json or {}), "benchmark_analysis_status": "running"}
        db.commit()

        try:
            for existing in db.query(HermesContentFactoryAsset).filter(
                HermesContentFactoryAsset.project_id == int(project.id),
                HermesContentFactoryAsset.kind.in_(tuple(BENCHMARK_ASSET_KINDS)),
            ).all():
                if int(dict(existing.meta_json or {}).get("source_asset_id") or 0) != int(asset.id):
                    continue
                try:
                    existing_path = Path(str(existing.file_path or ""))
                    if existing_path.is_file():
                        existing_path.unlink()
                except OSError:
                    pass
                db.delete(existing)
            db.flush()

            os.environ["PATH"] = f"/opt/apps/bin:{os.environ.get('PATH', '')}"
            producer_analysis = dict(
                dict(asset.meta_json or {}).get("producer_benchmark_analysis")
                or {}
            )
            reuse_producer_analysis = bool(
                producer_analysis.get("transcript_status")
                in {"success", "no_speech"}
                and producer_analysis.get("multimodal_status") == "success"
                and dict(producer_analysis.get("visual_semantic_analysis") or {}).get(
                    "status"
                ) == "success"
            )
            if reuse_producer_analysis:
                segments = [
                    dict(item)
                    for item in list(producer_analysis.get("segments") or [])
                    if isinstance(item, dict)
                ]
                transcript = str(producer_analysis.get("transcript") or "")
                result = {
                    "detected_language": producer_analysis.get("detected_language"),
                    "segments": segments,
                }
            else:
                from app.features.tenants.openai_whisper import transcriber

                result = transcriber.transcribe(
                    video_path,
                    source_language=None,
                    translate=False,
                )
                segments = list(result.get("segments") or [])
                transcript = "\n".join(
                    f"{float(segment.get('start') or 0):.1f}-{float(segment.get('end') or 0):.1f}s {str(segment.get('text') or '').strip()}"
                    for segment in segments
                    if str(segment.get("text") or "").strip()
                )
            output_dir = (
                CONTENT_FACTORY_STORAGE_ROOT
                / f"workspace_{project.workspace_id}"
                / project.project_key
                / "generated"
                / "benchmark_video"
                / f"asset_{int(asset.id)}"
            )
            output_dir.mkdir(parents=True, exist_ok=True)
            srt_path = output_dir / f"benchmark-{int(asset.id)}.srt"
            srt_path.write_text(_segments_to_srt_text(segments), encoding="utf-8")
            _chmod_group_writable(srt_path)
            duration = _probe_video_duration_seconds(video_path)
            sheet_rows = _render_benchmark_contact_sheets(
                video_path,
                output_dir,
                source_asset_id=int(asset.id),
                duration_seconds=duration,
            )
            visual_semantic_analysis = (
                dict(producer_analysis["visual_semantic_analysis"])
                if reuse_producer_analysis
                else analyze_benchmark_storyboard_api(
                    db,
                    contact_sheet_paths=[str(row["path"]) for row in sheet_rows],
                    transcript=transcript,
                    project_requirement=_project_requirement_text(project),
                    transformation_contract=_project_transformation_contract(project),
                    execution_id=(
                        f"{project.project_key}:benchmark:{int(asset.id)}"
                    ),
                )
            )
            srt_asset = _write_benchmark_asset(
                db,
                project=project,
                source_asset=asset,
                user_id=int(asset.user_id or project.user_id or 0),
                path=srt_path,
                kind="benchmark_transcript",
                mime_type="text/plain",
                role="benchmark_transcript",
                meta={"detected_language": result.get("detected_language") or result.get("source_language")},
            )
            keyframe_assets: list[HermesContentFactoryAsset] = []
            keyframe_sheets: list[dict[str, Any]] = []
            for row in sheet_rows:
                keyframe_asset = _write_benchmark_asset(
                    db,
                    project=project,
                    source_asset=asset,
                    user_id=int(asset.user_id or project.user_id or 0),
                    path=Path(row["path"]),
                    kind="benchmark_keyframes",
                    mime_type="image/png",
                    role="benchmark_keyframes",
                    meta={
                        "frame_count": int(row["frame_count"]),
                        "interval_seconds": row["interval_seconds"],
                        "board_index": int(row["board_index"]),
                        "frame_start": int(row["frame_start"]),
                        "frame_end": int(row["frame_end"]),
                        "start_second": row["start_second"],
                        "end_second": row["end_second"],
                    },
                )
                keyframe_assets.append(keyframe_asset)
                keyframe_sheets.append({
                    "asset_id": int(keyframe_asset.id),
                    "board_index": int(row["board_index"]),
                    "frame_start": int(row["frame_start"]),
                    "frame_end": int(row["frame_end"]),
                    "start_second": row["start_second"],
                    "end_second": row["end_second"],
                    "interval_seconds": row["interval_seconds"],
                })
            compact_segments = [
                {
                    "index": int(segment.get("index") or idx),
                    "start": round(float(segment.get("start") or 0), 2),
                    "end": round(float(segment.get("end") or 0), 2),
                    "text": str(segment.get("text") or "").strip()[:600],
                }
                for idx, segment in enumerate(segments[:120], 1)
                if str(segment.get("text") or "").strip()
            ]
            state = dict(project.state_json or {})
            state["benchmark_video_analysis"] = {
                "status": "success",
                "source_asset_id": int(asset.id),
                "duration_seconds": round(duration, 2),
                "detected_language": result.get("detected_language") or result.get("source_language"),
                "transcript": transcript[:16000],
                "segments": compact_segments,
                "srt_asset_id": int(srt_asset.id),
                "keyframe_asset_id": int(keyframe_assets[0].id),
                "keyframe_asset_ids": [int(item.id) for item in keyframe_assets],
                "keyframe_sheets": keyframe_sheets,
                "frame_count": sum(int(item["frame_count"]) for item in sheet_rows),
                "visual_semantic_analysis": visual_semantic_analysis,
                "visual_semantic_policy_version": (
                    BENCHMARK_VISUAL_ANALYSIS_POLICY_VERSION
                ),
                "completed_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            }
            project.state_json = state
            asset.meta_json = {**dict(asset.meta_json or {}), "benchmark_analysis_status": "success"}
            db.flush()

            config = dict(project.config_json or {})
            has_source = db.query(HermesContentFactoryAsset.id).filter(
                HermesContentFactoryAsset.project_id == int(project.id),
                HermesContentFactoryAsset.kind == "source",
            ).first() is not None
            should_auto_start = (
                project.status == "draft"
                and bool(config.get("auto_start_on_upload", False))
                and not bool(config.get("manual_paused", False))
                and (has_source or not _project_uses_product(project))
            )
            if should_auto_start:
                from app.services.hermes_agent.content_factory import queue_stage

                queue_stage(
                    db,
                    project=project,
                    user_id=int(project.user_id),
                    instruction=(
                        "Use the decomposed benchmark transcript, ordered "
                        "keyframes, and pixel-grounded visual semantic analysis "
                        "as evidence while designing a complete Director-owned "
                        "video program. Preserve every explicitly requested "
                        "abstract hook mechanism without copying forbidden "
                        "source pixels."
                    ),
                    target_stage=(
                        "SERIES_DIRECTOR"
                        if dict(project.config_json or {}).get(
                            "director_series_brief"
                        )
                        else "DIRECTOR"
                    ),
                    continue_workflow=True,
                    queue_priority=8,
                )
            else:
                db.commit()
            return {"status": "success", "asset_id": int(asset.id), "project_key": project.project_key}
        except Exception as exc:  # noqa: BLE001
            db.rollback()
            asset = db.query(HermesContentFactoryAsset).filter(HermesContentFactoryAsset.id == int(asset_id)).one_or_none()
            project = db.query(HermesContentFactoryProject).filter(HermesContentFactoryProject.id == int(asset.project_id)).one_or_none() if asset else None
            if asset is not None:
                asset.meta_json = {**dict(asset.meta_json or {}), "benchmark_analysis_status": "failed", "benchmark_analysis_error": str(exc)[:1000]}
            if project is not None:
                state = dict(project.state_json or {})
                state["benchmark_video_analysis"] = {
                    "status": "failed",
                    "source_asset_id": int(asset_id),
                    "error": str(exc)[:2000],
                    "failed_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                }
                project.state_json = state
                project.last_error = f"Benchmark video analysis failed: {str(exc)[:1000]}"
            db.commit()
            return {"status": "failed", "asset_id": int(asset_id), "error": str(exc)[:1000]}


_VISUAL_API_ROUTE_WORKLOAD = "content_factory_visual"
_VISUAL_API_ADAPTERS = {
    SUB2API_PROVIDER_KEY: "sub2api_async_images",
    FLOW2API_PROVIDER_KEY: "flow2api_openai_images",
    BANDIANWA_PROVIDER_KEY: "bandianwa_async_images",
    TOAPIS_PROVIDER_KEY: "toapis_async_images",
}
_VISUAL_API_MODELS = ("gpt-image-2", "nano_banana_pro")


def _visual_api_model_from_route(api_route: str | None) -> str:
    route = str(api_route or "").strip().lower()
    _provider, separator, model = route.partition(":")
    if not separator:
        return ""
    value = str(model or "").strip().lower()
    return "gpt-image-2" if value == "gpt-image-2.0" else value


def _visual_api_route_row(db, api_route: str | None) -> AiModelRoute | None:
    """Resolve the exact admin-owned image route used by a direct adapter."""
    provider = _visual_api_provider_from_route(api_route)
    model = _visual_api_model_from_route(api_route)
    expected_adapter = _VISUAL_API_ADAPTERS.get(provider)
    if not provider or not expected_adapter or model not in _VISUAL_API_MODELS:
        return None
    return (
        db.query(AiModelRoute)
        .filter(
            AiModelRoute.workload == _VISUAL_API_ROUTE_WORKLOAD,
            AiModelRoute.logical_model_id == model,
            AiModelRoute.capability == "image",
            AiModelRoute.provider_key == provider,
            AiModelRoute.adapter_type == expected_adapter,
            AiModelRoute.is_enabled.is_(True),
            AiModelRoute.is_verified.is_(True),
        )
        .order_by(AiModelRoute.priority.asc(), AiModelRoute.id.asc())
        .first()
    )


def _visual_api_route_error(error: Exception | str) -> AiGatewayError:
    """Classify bounded visual-adapter failures for unified route health."""
    message = str(error or "")[:4000]
    lowered = message.lower()
    status = getattr(error, "status_code", None)
    if _visual_api_account_quota_exhausted("VISUAL_PREVIEW", message):
        error_class = "QUOTA"
    elif status == 429 or "rate limit" in lowered or "too many requests" in lowered:
        error_class = "RATE_LIMIT"
    elif (
        status in {401, 403}
        or re.search(r"\bhttp\s+40[13]\b", lowered)
        or "unauthorized" in lowered
        or "forbidden" in lowered
    ):
        error_class = "AUTH"
    elif (
        status in {500, 502, 503, 504, 529}
        or "temporarily unavailable" in lowered
        or "service unavailable" in lowered
    ):
        error_class = "UPSTREAM_5XX"
    elif any(
        marker in lowered
        for marker in ("timeout", "timed out", "connection", "transport")
    ):
        error_class = "NETWORK"
    elif any(
        marker in lowered
        for marker in ("content policy", "prompt policy", "moderation", "提示词违规")
    ):
        error_class = "POLICY"
    else:
        error_class = "UPSTREAM"
    return AiGatewayError(
        "Visual provider request failed",
        error_class=error_class,
        status_code=int(status) if isinstance(status, int) else None,
        retry_after_seconds=getattr(error, "retry_after_seconds", None),
    )


def _begin_visual_api_route_attempt(
    db,
    *,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    api_route: str,
) -> tuple[int | None, float]:
    """Create one metadata-only audit row per provider and recovery epoch."""
    started = time.monotonic()
    route = _visual_api_route_row(db, api_route)
    if route is None:
        return None, started
    visual_api = dict(dict(stage_row.input_json or {}).get("visual_api") or {})
    epoch = max(0, int(visual_api.get("api_recovery_epoch") or 0))
    provider = _visual_api_provider_from_route(api_route)
    model = _visual_api_model_from_route(api_route)
    request_id = (
        f"cf-image-{int(project.id)}-{int(stage_row.id)}-"
        f"e{epoch}-{provider}-{model}"
    )[:96]
    existing = (
        db.query(AiRouteAttempt)
        .filter(
            AiRouteAttempt.route_id == int(route.id),
            AiRouteAttempt.request_id == request_id,
        )
        .order_by(AiRouteAttempt.id.desc())
        .first()
    )
    if existing is not None:
        return (
            int(existing.id) if str(existing.status or "") == "STARTED" else None,
            started,
        )
    attempt = begin_ai_route_attempt(
        db,
        route=route,
        request_id=request_id,
        switched_from_route_id=None,
        metadata={
            "source": "content_factory_visual",
            "workload": _VISUAL_API_ROUTE_WORKLOAD,
            "retry_round": epoch,
            "retry_attempt": int(stage_row.attempt or 0),
        },
    )
    db.commit()
    return int(attempt.id), started


def _finish_visual_api_route_attempt(
    db,
    attempt_id: int | None,
    started: float,
    *,
    error: Exception | None,
) -> None:
    if attempt_id is None:
        return
    attempt = db.get(AiRouteAttempt, int(attempt_id))
    if attempt is None or str(attempt.status or "") != "STARTED":
        return
    route = db.get(AiModelRoute, int(attempt.route_id))
    if route is None:
        return
    latency_ms = max(0, int((time.monotonic() - started) * 1000))
    if error is None:
        mark_ai_route_success(
            route,
            attempt,
            latency_ms=latency_ms,
            usage=None,
        )
    else:
        mark_ai_route_failure(
            route,
            attempt,
            _visual_api_route_error(error),
            latency_ms=latency_ms,
        )
    db.add_all((route, attempt))
    db.commit()


def _visual_api_route_for_provider(
    provider_key: str,
    model: str = "gpt-image-2",
) -> str:
    normalized_model = str(model or "gpt-image-2").strip().lower()
    if normalized_model == "gpt-image-2.0":
        normalized_model = "gpt-image-2"
    return f"{str(provider_key).strip().lower()}:{normalized_model}"


def _visual_api_provider_from_route(api_route: str | None) -> str:
    route = str(api_route or "").strip().lower()
    provider, separator, _model = route.partition(":")
    return provider if separator and provider in _VISUAL_API_ADAPTERS else ""


def _visual_api_failed_providers(
    stage_input: dict[str, Any] | None,
) -> set[str]:
    """Return providers with real upstream failures in the current epoch."""
    visual_api = dict(dict(stage_input or {}).get("visual_api") or {})
    # New rows record failures by exact provider+model route. A depleted
    # Sub2API OpenAI account must not suppress the independent Flow2API image
    # account pool. Provider-only failures are read only for legacy
    # stage rows that predate route-aware accounting.
    if dict(visual_api.get("route_failures") or {}):
        return set()
    return {
        str(key).strip().lower()
        for key, raw in dict(visual_api.get("provider_failures") or {}).items()
        if str(key).strip()
        # Compatibility cleanup for rows persisted by the former inheritance
        # path.  This message records a local route migration, not a failed
        # request to the named provider.
        and "same visual variant already owns another api route"
        not in str(dict(raw or {}).get("error") or "").strip().lower()
    }


def _visual_api_failed_routes(
    stage_input: dict[str, Any] | None,
) -> set[str]:
    visual_api = dict(dict(stage_input or {}).get("visual_api") or {})
    return {
        str(key).strip().lower()
        for key, raw in dict(visual_api.get("route_failures") or {}).items()
        if _visual_api_provider_from_route(str(key))
        and _visual_api_model_from_route(str(key)) in _VISUAL_API_MODELS
        and "same visual variant already owns another api route"
        not in str(dict(raw or {}).get("error") or "").strip().lower()
    }


def _configured_visual_api_routes(
    db,
    stage_input: dict[str, Any] | None = None,
    *,
    include_failed: bool = False,
) -> list[str]:
    """Return enabled image routes in platform-admin priority order.

    The model route table is the production authority.  The small compatibility
    fallback keeps older installations and isolated unit tests operational until
    their route rows are created; it is not used on this deployed instance.
    """
    values = dict(stage_input or {})
    failed = _visual_api_failed_providers(values)
    failed_routes = _visual_api_failed_routes(values)
    if bool(values.get("visual_api_skip_bandianwa")):
        failed.add(BANDIANWA_PROVIDER_KEY)

    routes: list[str] = []
    now = _stage_now()
    try:
        # Load the explicit route inventory first, then apply circuit state in
        # Python.  Filtering circuits in SQL made an all-open inventory look
        # indistinguishable from an old installation with no route rows, so
        # the compatibility fallback resurrected the same broken API key and
        # left VISUAL_PREVIEW cycling in the queue.
        configured_rows = (
            db.query(AiModelRoute)
            .join(KieApiKey, KieApiKey.id == AiModelRoute.key_id)
            .filter(
                AiModelRoute.workload == _VISUAL_API_ROUTE_WORKLOAD,
                AiModelRoute.logical_model_id.in_(_VISUAL_API_MODELS),
                AiModelRoute.capability == "image",
                AiModelRoute.is_enabled.is_(True),
                AiModelRoute.is_verified.is_(True),
                KieApiKey.is_active.is_(True),
            )
            .order_by(AiModelRoute.priority.asc(), AiModelRoute.id.asc())
            .all()
        )
    except Exception:  # compatibility with small route-test DB doubles
        configured_rows = []
    for row in configured_rows:
        provider = str(row.provider_key or "").strip().lower()
        model = str(row.logical_model_id or "").strip().lower()
        route = _visual_api_route_for_provider(provider, model)
        circuit_open_until = getattr(row, "circuit_open_until", None)
        if (
            provider not in _VISUAL_API_ADAPTERS
            or model not in _VISUAL_API_MODELS
            or route in routes
            or (
                circuit_open_until is not None
                and circuit_open_until > now
            )
        ):
            continue
        if not include_failed and provider in failed:
            continue
        if not include_failed and route in failed_routes:
            continue
        routes.append(route)

    if not routes and not configured_rows:
        # Compatibility only. Production has explicit AiModelRoute rows.
        for provider in (
            SUB2API_PROVIDER_KEY,
            FLOW2API_PROVIDER_KEY,
            BANDIANWA_PROVIDER_KEY,
            TOAPIS_PROVIDER_KEY,
        ):
            if not include_failed and provider in failed:
                continue
            if has_active_key(db, provider_key=provider):
                route = _visual_api_route_for_provider(
                    provider,
                    "nano_banana_pro"
                    if provider == FLOW2API_PROVIDER_KEY
                    else "gpt-image-2",
                )
                if include_failed or route not in failed_routes:
                    routes.append(route)
    return routes


def _next_visual_api_route(
    db,
    *,
    current_route: str | None,
    stage_input: dict[str, Any],
) -> str | None:
    current = str(current_route or "").strip().lower()
    for route in _configured_visual_api_routes(db, stage_input):
        if route != current:
            return route
    return None


def _is_visual_api_route(api_route: str | None) -> bool:
    route = str(api_route or "").strip().lower()
    return bool(
        _visual_api_provider_from_route(route) in _VISUAL_API_ADAPTERS
        and _visual_api_model_from_route(route) in _VISUAL_API_MODELS
    )


def _content_factory_api_route(
    db,
    stage: str,
    stage_input: dict[str, Any] | None = None,
    *,
    allow_browser_handoff_reversal: bool = False,
) -> str | None:
    # Unit-level recovery helpers pass ``db=None`` and monkeypatch the locked
    # browser route. Production dispatch always supplies a real Session.
    if db is None:
        return None
    stage_name = str(stage or "").upper()
    values = dict(stage_input or {})
    if not allow_browser_handoff_reversal and bool(
        values.get("api_fallback_to_browser")
        or values.get("api_force_browser_fallback")
        or values.get("visual_api_force_browser_fallback")
        or str(values.get("execution_backend") or "").strip().lower()
        == "browser"
    ):
        # A forced browser handoff is durable recovery authority. Recomputing
        # an enabled API route here lets a later browser-offline incident undo
        # the handoff and reopen an already exhausted provider.
        return None
    # PRODUCTION_PLAN is executed by the same Hermes control plane as the
    # Director stages.  Its first delivery normally carries the explicit
    # route stamped by queue_stage(), but a project-lock collision clears the
    # Celery delivery identity and lets periodic self-heal rebuild routing.
    # Recomputing this stage as browser work strands the durable retry when
    # the API-first browser slot is intentionally offline.
    if stage_name in {"SERIES_DIRECTOR", "DIRECTOR", "PRODUCTION_PLAN"}:
        return "hermes:content-director"
    if stage_name == "VISUAL_PREVIEW":
        visual_api = dict(values.get("visual_api") or {})
        if (
            bool(visual_api.get("account_quota_exhausted"))
            and not allow_browser_handoff_reversal
            and not dict(visual_api.get("provider_failures") or {})
        ):
            # Provider failover clears this flag when another image API is
            # selected. If it remains set, the active/final route rejected its
            # pre-charge and must never be rediscovered merely because its key
            # is still administratively enabled.
            return None
        routes = _configured_visual_api_routes(
            db,
            values,
            include_failed=allow_browser_handoff_reversal,
        )
        if allow_browser_handoff_reversal:
            # The Recovery Supervisor grants this flag only after the current
            # API epoch is exhausted and browser fallback is unavailable.  It
            # can make that decision before browser markers are persisted, so
            # the flag itself is the new-epoch authority. Re-enter at the
            # administrator's first enabled provider rather than inheriting
            # the final provider from the exhausted epoch.
            return routes[0] if routes else None
        current_route = str(
            values.get("api_route")
            or _visual_api_route_for_provider(visual_api.get("provider") or "")
        ).strip()
        if current_route in routes:
            return current_route
        if routes:
            return routes[0]
    if stage_name in TEXT_API_STAGES and has_active_key(
        db, provider_key=TOAPIS_PROVIDER_KEY
    ):
        return "toapis:text"
    return None


def _content_factory_api_is_configured(
    db,
    stage: str,
) -> bool:
    """Return whether the stage has an administrator-enabled API inventory.

    This intentionally ignores a route's temporary circuit-open time.  It is
    used only by the recovery supervisor to distinguish "no integration was
    configured" from "configured accounts are cooling right now".
    """

    stage_name = str(stage or "").strip().upper()
    if stage_name in {"SERIES_DIRECTOR", "DIRECTOR", "PRODUCTION_PLAN"}:
        return True
    if stage_name == "VISUAL_PREVIEW":
        try:
            configured = (
                db.query(AiModelRoute.id)
                .join(KieApiKey, KieApiKey.id == AiModelRoute.key_id)
                .filter(
                    AiModelRoute.workload == _VISUAL_API_ROUTE_WORKLOAD,
                    AiModelRoute.logical_model_id.in_(_VISUAL_API_MODELS),
                    AiModelRoute.capability == "image",
                    AiModelRoute.is_enabled.is_(True),
                    AiModelRoute.is_verified.is_(True),
                    KieApiKey.is_active.is_(True),
                )
                .first()
            )
            if configured is not None:
                return True
        except Exception:  # compatibility with isolated DB doubles
            pass
        return any(
            has_active_key(db, provider_key=provider)
            for provider in (
                SUB2API_PROVIDER_KEY,
                FLOW2API_PROVIDER_KEY,
                BANDIANWA_PROVIDER_KEY,
                TOAPIS_PROVIDER_KEY,
            )
        )
    return bool(
        stage_name in TEXT_API_STAGES
        and has_active_key(db, provider_key=TOAPIS_PROVIDER_KEY)
    )


def _api_stage_failure_key(project: HermesContentFactoryProject, stage: str) -> str:
    return f"v{_active_variant_index(project):02d}:{str(stage or '').upper()}"


def _record_api_stage_failure(
    project: HermesContentFactoryProject,
    stage: str,
    error: Exception | str,
) -> int:
    state = dict(project.state_json or {})
    failures = dict(state.get("api_stage_failures") or {})
    key = _api_stage_failure_key(project, stage)
    row = dict(failures.get(key) or {})
    count = max(0, int(row.get("count") or 0)) + 1
    failures[key] = {
        "count": count,
        "last_error": str(error)[:1200],
        "last_failed_at": _stage_now().isoformat(),
    }
    state["api_stage_failures"] = failures
    project.state_json = state
    return count


def _clear_api_stage_failures(project: HermesContentFactoryProject, stage: str) -> None:
    state = dict(project.state_json or {})
    failures = dict(state.get("api_stage_failures") or {})
    if failures.pop(_api_stage_failure_key(project, stage), None) is not None:
        state["api_stage_failures"] = failures
        project.state_json = state


def _recovery_supervisor_evidence_images(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
) -> list[tuple[str, str]]:
    """Collect only tenant/project-owned visual evidence for fault diagnosis."""

    project_root = (
        CONTENT_FACTORY_STORAGE_ROOT
        / f"workspace_{int(project.workspace_id)}"
        / str(project.project_key)
    ).resolve()
    product_root = (
        CONTENT_FACTORY_STORAGE_ROOT
        / "product_library"
        / f"workspace_{int(project.workspace_id)}"
    ).resolve()

    def safe_image(path_value: Any) -> Path | None:
        raw = str(path_value or "").strip()
        if not raw:
            return None
        path = Path(raw).resolve()
        if not path.is_file() or path.suffix.lower() not in {
            ".png", ".jpg", ".jpeg", ".webp",
        }:
            return None
        if not (
            path == project_root
            or path.is_relative_to(project_root)
            or path == product_root
            or path.is_relative_to(product_root)
        ):
            return None
        return path

    evidence: list[tuple[str, str]] = []
    try:
        assets = (
            db.query(HermesContentFactoryAsset)
            .filter(
                HermesContentFactoryAsset.workspace_id == int(project.workspace_id),
                HermesContentFactoryAsset.project_id == int(project.id),
            )
            .order_by(HermesContentFactoryAsset.id.asc())
            .all()
        )
    except Exception:
        assets = []
    for row in assets:
        path = safe_image(row.file_path)
        if path is None:
            continue
        evidence.append((f"project asset {row.kind}: {row.original_name}", str(path)))
        if len(evidence) >= 5:
            break
    visual_api = dict(stage_input.get("visual_api") or {})
    for board_key, raw in sorted(dict(visual_api.get("boards") or {}).items()):
        board = dict(raw or {})
        path = safe_image(board.get("output_path"))
        if path is None:
            continue
        evidence.append((f"generated visual board {board_key}", str(path)))
        if len(evidence) >= 8:
            break
    return evidence


def _recovery_supervisor_incident(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    source_backend: str,
    reason: str,
    ambiguous_billable_submission: bool = False,
    browser_retry_exhausted: bool = False,
) -> RecoveryIncident:
    stage_input = dict(stage_row.input_json or {})
    fault_code = str(getattr(reason, "code", "") or "").strip()
    fault_class = classify_recovery_fault(str(reason), code=fault_code)
    browser_login_available: bool | None = None
    if fault_class == "BROWSER_LOGIN_REQUIRED":
        browser_login_available = False
    elif _browser_login_blocked_for_stage(db, project, stage_input):
        browser_login_available = False
    browser_reachable: bool | None = None
    try:
        browser_reachable = bool(
            _browser_bridge_fresh_for_stage(
                db,
                project,
                stage_input,
                now=_stage_now(),
            )
            and _browser_cdp_reachable_for_stage(
                db,
                project,
                stage_input,
            )
        )
    except Exception:  # compatibility with isolated DB doubles
        browser_reachable = None
    api_route = _content_factory_api_route(
        db,
        stage_row.stage,
        stage_input,
        allow_browser_handoff_reversal=(
            str(source_backend or "").strip().lower() == "browser"
            or browser_login_available is False
            or browser_reachable is False
        ),
    )
    decisions = [
        dict(value)
        for value in list(stage_input.get("recovery_supervisor_history") or [])[-12:]
        if isinstance(value, dict)
    ]
    cycle = max(
        0,
        int(stage_input.get("recovery_supervisor_cycle") or 0),
    ) + 1
    digest = hashlib.sha256(
        "|".join([
            str(project.project_key),
            str(stage_row.id),
            str(stage_row.stage),
            str(_stage_variant_index(stage_row, project)),
            str(source_backend),
            fault_class,
            str(cycle),
        ]).encode("utf-8")
    ).hexdigest()[:24]
    browser_upload_available: bool | None = None
    if (
        fault_class == "BROWSER_UPLOAD_UNAVAILABLE"
        or int(stage_input.get("browser_upload_api_return_count") or 0) >= 1
    ):
        browser_upload_available = False
    config = dict(project.config_json or {})
    project_state = dict(project.state_json or {})
    visual_api = dict(stage_input.get("visual_api") or {})
    board_attempts = []
    evidence_manifest = []
    failed_input_summaries: list[str] = []
    for board_key, raw in sorted(dict(visual_api.get("boards") or {}).items()):
        board = dict(raw or {})
        submitted_prompt_excerpt = str(
            board.get("submitted_prompt_excerpt")
            or board.get("source_prompt_excerpt")
            or ""
        )[:1600]
        board_attempts.append({
            "reference_index": str(board_key)[:16],
            "status": str(board.get("status") or "")[:48],
            "provider_task_present": bool(str(board.get("task_id") or "").strip()),
            "retry_generation": int(board.get("provider_retry_generation") or 0),
            "semantic_repair_count": int(board.get("semantic_prompt_repair_count") or 0),
            "last_error": str(board.get("last_error") or "")[:400],
            "submitted_prompt_excerpt": submitted_prompt_excerpt,
        })
        if submitted_prompt_excerpt and str(board.get("status") or "") != "completed":
            failed_input_summaries.append(
                f"reference {str(board_key)[:16]}: {submitted_prompt_excerpt}"
            )
        if str(board.get("output_path") or "").strip():
            evidence_manifest.append({
                "label": f"generated visual board {board_key}",
                "kind": "generated_visual",
                "available": Path(str(board.get("output_path"))).is_file(),
            })
    stage_fingerprint = hashlib.sha256(
        json.dumps(
            {
                "stage": str(stage_row.stage or ""),
                "instruction": str(getattr(stage_row, "instruction", "") or ""),
                "api_route": str(stage_input.get("api_route") or ""),
                "variant_index": _stage_variant_index(stage_row, project),
                "visual_boards": board_attempts,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return RecoveryIncident(
        incident_id=f"cf-recovery-{digest}",
        project_id=int(project.id),
        stage_id=int(stage_row.id),
        stage=str(stage_row.stage or "").upper(),
        variant_index=_stage_variant_index(stage_row, project),
        source_backend=str(source_backend or "api").lower(),
        fault_class=fault_class,
        fault_code=fault_code[:128],
        attempt_count=max(
            int(stage_row.attempt or 0),
            int(stage_input.get("automatic_retry_count") or 0),
            int(stage_input.get("text_api_transport_model_rotation_count") or 0),
        ),
        recovery_cycle=cycle,
        max_recovery_cycles=max(
            1,
            min(
                1000,
                int(
                    config.get("recovery_supervisor_max_cycles")
                    or os.getenv("HERMES_RECOVERY_SUPERVISOR_MAX_CYCLES", "24")
                ),
            ),
        ),
        api_available=bool(api_route),
        api_configured=_content_factory_api_is_configured(
            db,
            str(stage_row.stage or ""),
        ),
        browser_eligible=(
            str(stage_row.stage or "").upper() in ROLE_URLS
            and not browser_retry_exhausted
            and browser_login_available is not False
            and browser_reachable is not False
        ),
        browser_reachable=browser_reachable,
        browser_upload_available=browser_upload_available,
        browser_login_available=browser_login_available,
        ambiguous_billable_submission=bool(ambiguous_billable_submission),
        # ``paused`` is also used for automatic quality/recovery boundaries.
        # Only an explicit operator marker may suppress unattended recovery;
        # treating every paused project as manual stranded quality pauses
        # forever and made the Recovery Supervisor appear ineffective.
        manual_pause=bool(
            config.get("manual_paused", False)
            or str(project_state.get("pause_reason_code") or "").lower()
            == "manual"
        ),
        recent_actions=[
            str(value.get("action") or "")[:64]
            for value in decisions
            if str(value.get("action") or "").strip()
        ],
        error_summary=str(reason or "")[:1200],
        active_input_summary=(
            "\n\n".join(failed_input_summaries)
            or str(getattr(stage_row, "instruction", "") or "")
        )[:4000],
        input_fingerprint=stage_fingerprint,
        active_route=str(stage_input.get("api_route") or api_route or "")[:255],
        provider_attempts=board_attempts[:12],
        checkpoint={
            "stage_status": str(getattr(stage_row, "status", "") or ""),
            "stage_attempt": int(stage_row.attempt or 0),
            "visual_api_status": str(visual_api.get("status") or "")[:64],
            "completed_visuals": sum(
                1 for row in board_attempts if row.get("status") == "completed"
            ),
            "recent_fault_reports": [
                dict(value)
                for value in list(stage_input.get("fault_report_history") or [])[-5:]
                if isinstance(value, dict)
            ],
        },
        evidence_manifest=evidence_manifest[:12],
    )


def _persist_recovery_supervisor_decision(
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    incident: RecoveryIncident,
    decision,
) -> dict[str, Any]:
    if (
        incident.recovery_cycle > incident.max_recovery_cycles
        and decision.action
        in {
            RecoveryAction.WAIT_AND_RETRY_API,
            RecoveryAction.WAIT_FOR_BROWSER,
        }
    ):
        # Autonomy must not become a hot infinite loop. Crossing the bounded
        # active-repair budget enters a long unattended probe cadence while
        # preserving the project and all paid outputs.
        decision.wait_seconds = max(1800, int(decision.wait_seconds or 0))
    now = _stage_now().isoformat()
    audit = {
        "incident_id": incident.incident_id,
        "policy_version": RECOVERY_SUPERVISOR_POLICY_VERSION,
        "source_backend": incident.source_backend,
        "fault_class": incident.fault_class,
        "action": decision.action.value,
        "wait_seconds": int(decision.wait_seconds or 0),
        "reason_code": str(decision.reason_code or "")[:96],
        "rationale": str(decision.rationale or "")[:600],
        "confidence": float(decision.confidence or 0.0),
        "decision_source": str(decision.decision_source or "safe_fallback"),
        "model": str(decision.model or "")[:255] or None,
        "latency_ms": decision.latency_ms,
        "diagnosis": str(decision.diagnosis or "")[:1000],
        "repair_directive": str(decision.repair_directive or "")[:1600],
        "evidence_used": [str(value)[:160] for value in decision.evidence_used[:12]],
        "input_fingerprint": str(incident.input_fingerprint or "")[:64],
        "recovery_cycle": int(incident.recovery_cycle),
        "at": now,
    }
    stage_input = dict(stage_row.input_json or {})
    history = [
        dict(value)
        for value in list(stage_input.get("recovery_supervisor_history") or [])[-11:]
        if isinstance(value, dict)
    ]
    history.append(audit)
    stage_input["recovery_supervisor_history"] = history
    stage_input["recovery_supervisor_cycle"] = int(incident.recovery_cycle)
    stage_input["last_recovery_supervisor_decision"] = audit
    stage_row.input_json = stage_input

    state = dict(project.state_json or {})
    state["last_recovery_supervisor_decision"] = audit
    counters = dict(state.get("recovery_supervisor_counters") or {})
    action_key = decision.action.value
    counters[action_key] = int(counters.get(action_key) or 0) + 1
    state["recovery_supervisor_counters"] = counters
    project.state_json = state
    return audit


def _api_retry_input_after_recovery(
    stage_input: dict[str, Any] | None,
    *,
    api_route: str,
    decision_action: str,
) -> dict[str, Any]:
    values = dict(stage_input or {})
    values.update({
        "execution_backend": "api",
        "api_route": str(api_route),
        "api_fallback_to_browser": False,
        "api_force_browser_fallback": False,
        "visual_api_force_browser_fallback": False,
        "force_fresh_response": True,
        "discard_durable_response_capture": True,
        "clear_stale_composer_before_send": True,
        "self_heal_circuit_open": False,
        "self_heal_action": "recovery_supervisor_return_to_api",
        "recovery_supervisor_action": str(decision_action),
    })
    recovery_route = str(api_route or "").strip().lower()
    if (
        _visual_api_provider_from_route(recovery_route)
        and _visual_api_model_from_route(recovery_route) in _VISUAL_API_MODELS
    ):
        # Re-enter the enabled image-provider chain as a new cooled recovery
        # epoch. Provider-specific exhaustion from the prior epoch must not
        # silently force the same final/empty account again.
        values["visual_api_skip_bandianwa"] = False
        visual_api = dict(values.get("visual_api") or {})
        exhausted_failures = dict(visual_api.get("provider_failures") or {})
        if exhausted_failures:
            failure_history = [
                dict(row)
                for row in list(values.get("visual_api_failure_history") or [])[-7:]
                if isinstance(row, dict)
            ]
            failure_history.append({
                "api_recovery_epoch": max(
                    0,
                    int(visual_api.get("api_recovery_epoch") or 0),
                ),
                "providers": exhausted_failures,
                "all_providers_exhausted_at": visual_api.get(
                    "all_providers_exhausted_at"
                ),
                "archived_at": _stage_now().isoformat(),
            })
            values["visual_api_failure_history"] = failure_history
        for key in (
            "account_quota_exhausted",
            "account_quota_exhausted_at",
            "all_providers_exhausted",
            "all_providers_exhausted_at",
            "bandianwa_account_quota_exhausted",
            "bandianwa_account_quota_exhausted_at",
            "provider_failures",
            "route_failures",
            "provider_retry_generation",
            "provider_transport_retry_count",
            "task_id",
            "last_error",
            "failed_at",
        ):
            visual_api.pop(key, None)
        boards = {}
        for board_key, raw in dict(visual_api.get("boards") or {}).items():
            board = dict(raw or {})
            if str(board.get("status") or "").lower() not in {
                "success",
                "completed",
            }:
                for key in (
                    "task_id",
                    "last_failed_task_id",
                    "last_error",
                    "failed_at",
                    "provider_transport_retry_count",
                ):
                    board.pop(key, None)
                board["status"] = "pending"
            boards[str(board_key)] = board
        if boards:
            visual_api["boards"] = boards
        visual_api["status"] = "pending"
        visual_api["api_recovery_epoch"] = int(
            visual_api.get("api_recovery_epoch") or 0
        ) + 1
        values["visual_api"] = visual_api
    for stale_key in (
        "browser_slot",
        "browser_bridge_id",
        "browser_cdp_url",
        "browser_device_id",
        "browser_device_name",
        "browser_inbox_root",
        "browser_recovery_mode",
        "replayed_durable_response_capture",
        "replayed_prior_stage_capture_id",
        "retry_release_task_id",
        "retry_after",
        "run_token",
        "execution_lease_expires_at",
    ):
        values.pop(stale_key, None)
    values["api_regeneration_generation"] = int(
        values.get("api_regeneration_generation") or 0
    ) + 1
    return values


def _waiting_bridge_api_retry_input(
    db,
    *,
    stage: str,
    stage_input: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Recover an API-owned stage that was left in waiting_bridge.

    A worker can stop after selecting a newly healthy API route but before it
    replaces the project's older browser-wait status.  Periodic self-heal must
    honor the stage's current execution authority instead of waiting forever
    for a browser that this API-first stage no longer needs.
    """
    values = dict(stage_input or {})
    api_route = _content_factory_api_route(db, stage, values)
    if not api_route or stage_execution_backend(
        stage,
        api_route=api_route,
        stage_input=values,
    ) != "api":
        return None
    return _api_retry_input_after_recovery(
        values,
        api_route=api_route,
        decision_action="SELF_HEAL_SWITCH_TO_API",
    )


def _recovery_api_probe_delay(
    stage_input: dict[str, Any] | None,
    *,
    requested_wait_seconds: int = 0,
) -> int:
    values = dict(stage_input or {})
    probe_count = max(0, int(values.get("recovery_api_probe_count") or 0))
    exponential = min(1800, 60 * (2 ** min(5, probe_count)))
    requested = max(0, int(requested_wait_seconds or 0))
    return max(60, min(3600, max(exponential, requested)))


def _schedule_supervised_api_probe(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    reason: str,
) -> dict[str, Any]:
    """Persist a route-inventory probe without authorizing browser work.

    An empty eligible route set usually means every configured account is in
    cooldown.  It is not a terminal project state.  Periodic self-heal owns the
    next probe and republishes the stage only after a concrete route exists.
    """

    now = _stage_now()
    stage_input = dict(stage_row.input_json or {})
    wait_seconds = _recovery_api_probe_delay(
        stage_input,
        requested_wait_seconds=int(decision.wait_seconds or 0),
    )
    stage_input.update({
        "execution_backend": "api",
        "api_route": None,
        "api_fallback_to_browser": False,
        "api_force_browser_fallback": False,
        "visual_api_force_browser_fallback": False,
        "recovery_api_probe_pending": True,
        "recovery_api_probe_count": int(
            stage_input.get("recovery_api_probe_count") or 0
        ) + 1,
        "recovery_api_probe_reason": str(reason)[:1200],
        "retry_after": (now + timedelta(seconds=wait_seconds)).isoformat(),
        "retry_release_strategy": "database_route_probe_at_periodic_self_heal",
        "self_heal_action": "probe_configured_api_inventory_after_cooldown",
        "recovery_supervisor_action": decision.action.value,
    })
    for stale_key in (
        "browser_slot",
        "browser_bridge_id",
        "browser_cdp_url",
        "browser_device_id",
        "browser_device_name",
        "browser_inbox_root",
        "run_token",
        "execution_lease_expires_at",
        "retry_release_task_id",
    ):
        stage_input.pop(stale_key, None)
    stage_row.input_json = _restamp_stage_runtime_policy(stage_input)
    stage_row.status = "retrying"
    stage_row.celery_task_id = None
    stage_row.started_at = None
    stage_row.completed_at = None
    stage_row.error_message = (
        "Recovery Supervisor scheduled an API inventory probe: "
        f"{str(reason)[:3200]}"
    )[:4000]
    project.status = "queued"
    project.current_stage = stage_row.stage
    project.last_error = (
        f"当前 API 账号均在冷却或暂时不可用；故障调度官将在约 {wait_seconds} 秒后"
        "重新探测平台统一 API，浏览器 Slot 保持离线。"
    )
    hibernate_project_browser_slot_for_api_video(
        db,
        project=project,
        active_stage=stage_row,
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_api_probe_scheduled",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "retry_in_seconds": wait_seconds,
        "decision": decision.action.value,
        "decision_source": decision.decision_source,
    }


def _schedule_supervised_api_retry(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    allow_browser_handoff_reversal: bool = False,
) -> dict[str, Any]:
    api_route = _content_factory_api_route(
        db,
        stage_row.stage,
        dict(stage_row.input_json or {}),
        allow_browser_handoff_reversal=allow_browser_handoff_reversal,
    )
    if not api_route:
        return _schedule_supervised_api_probe(
            db,
            project,
            stage_row,
            decision=decision,
            reason=(
                "Recovery Supervisor selected API, but no route is eligible "
                "during the current provider cooldown."
            ),
        )
    wait_seconds = max(15, min(3600, int(decision.wait_seconds or 0) or 60))
    if allow_browser_handoff_reversal:
        prior_visual_api = dict(
            dict(stage_row.input_json or {}).get("visual_api") or {}
        )
        recovery_epoch = _visual_api_recovery_epoch(
            {"visual_api": prior_visual_api}
        )
        # Avoid hot API/browser ping-pong when every current image account is
        # temporarily unhealthy. Each return from an unusable browser waits a
        # little longer, while remaining bounded for unattended recovery.
        wait_seconds = max(
            wait_seconds,
            min(1800, 60 * max(1, recovery_epoch + 1)),
        )
    stage_input = _api_retry_input_after_recovery(
        dict(stage_row.input_json or {}),
        api_route=api_route,
        decision_action=decision.action.value,
    )
    stage_input["retry_after"] = (
        _stage_now() + timedelta(seconds=wait_seconds)
    ).isoformat()
    stage_input["retry_release_strategy"] = "database_due_at_periodic_self_heal"
    stage_row.input_json = _restamp_stage_runtime_policy(stage_input)
    stage_row.status = "retrying"
    stage_row.celery_task_id = None
    stage_row.started_at = None
    stage_row.completed_at = None
    stage_row.error_message = (
        "Recovery Supervisor selected a cooled API retry: "
        f"{decision.reason_code}"
    )[:4000]
    project.status = "queued"
    project.current_stage = stage_row.stage
    project.last_error = (
        f"故障调度官已选择等待 {wait_seconds} 秒后重新调用可用 API；"
        "浏览器 Slot 保持休眠。"
    )
    hibernate_project_browser_slot_for_api_video(
        db,
        project=project,
        active_stage=stage_row,
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_api_retry_scheduled",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "retry_in_seconds": wait_seconds,
        "decision": decision.action.value,
        "decision_source": decision.decision_source,
    }


def _schedule_supervised_provider_rotation(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    reason: str,
) -> dict[str, Any]:
    """Move visual work to the next configured route without losing paid boards.

    ``ROTATE_PROVIDER`` is an executable decision, not a synonym for clearing
    the current route and rediscovering the first configured provider.  The
    latter can select the same unhealthy account repeatedly and makes the
    supervisor audit trail untrue.
    """

    if str(stage_row.stage or "").upper() != "VISUAL_PREVIEW":
        return _schedule_supervised_api_retry(
            db,
            project,
            stage_row,
            decision=decision,
            allow_browser_handoff_reversal=True,
        )
    stage_input = dict(stage_row.input_json or {})
    current_provider = str(
        dict(stage_input.get("visual_api") or {}).get("provider") or ""
    ).strip().lower()
    current_route = str(
        stage_input.get("api_route")
        or (
            _visual_api_route_for_provider(current_provider)
            if current_provider
            else ""
        )
        or ""
    ).strip().lower()
    next_route = _next_visual_api_route(
        db,
        current_route=current_route,
        stage_input=stage_input,
    )
    if not next_route:
        # The pool may only expose one provider whose internal account
        # scheduler can still rotate credentials.  Re-enter it only after a
        # bounded cooldown; never wake a browser merely because the next API
        # route is temporarily absent.
        return _schedule_supervised_api_retry(
            db,
            project,
            stage_row,
            decision=decision,
            allow_browser_handoff_reversal=True,
        )
    from_provider = (
        _visual_api_provider_from_route(current_route)
        or current_provider
        or "unknown"
    )
    to_provider = _visual_api_provider_from_route(next_route)
    rotated = _prepare_visual_api_provider_failover(
        stage_input,
        from_provider=from_provider,
        to_provider=to_provider,
        error=reason,
        account_quota_exhausted=decision.reason_code in {
            "ACCOUNT_QUOTA",
            "AUTH",
            "RATE_LIMIT",
        }
        or classify_recovery_fault(reason) in {"ACCOUNT_QUOTA", "AUTH", "RATE_LIMIT"},
        from_route=current_route,
        to_route=next_route,
    )
    wait_seconds = max(15, min(600, int(decision.wait_seconds or 0) or 30))
    rotated.update({
        "retry_after": (
            _stage_now() + timedelta(seconds=wait_seconds)
        ).isoformat(),
        "retry_release_strategy": "database_due_at_periodic_self_heal",
        "recovery_supervisor_action": decision.action.value,
        "force_fresh_response": True,
    })
    for stale_key in (
        "run_token",
        "execution_lease_expires_at",
        "retry_release_task_id",
    ):
        rotated.pop(stale_key, None)
    stage_row.input_json = _restamp_stage_runtime_policy(rotated)
    stage_row.status = "retrying"
    stage_row.celery_task_id = None
    stage_row.started_at = None
    stage_row.completed_at = None
    stage_row.error_message = (
        "Recovery Supervisor rotated visual provider route from "
        f"{current_route or from_provider} to {next_route}: {decision.reason_code}"
    )[:4000]
    project.status = "queued"
    project.current_stage = stage_row.stage
    project.last_error = (
        f"故障调度官已将图片任务从 {from_provider} 切换到 {to_provider}；"
        "已完成画板会保留，未完成画板将在冷却后继续。"
    )
    hibernate_project_browser_slot_for_api_video(
        db,
        project=project,
        active_stage=stage_row,
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_provider_rotation_scheduled",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "from_route": current_route,
        "to_route": next_route,
        "retry_in_seconds": wait_seconds,
        "decision": decision.action.value,
        "decision_source": decision.decision_source,
    }


def _schedule_supervised_visual_semantic_repair(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    reason: str,
) -> dict[str, Any]:
    """Queue one new prompt identity while preserving completed paid images."""

    if str(stage_row.stage or "").upper() != "VISUAL_PREVIEW":
        return _recover_exhausted_semantic_api_stage(
            db,
            project,
            stage_row,
            reason=reason,
        )
    now = _stage_now()
    stage_input = dict(stage_row.input_json or {})
    visual_api = dict(stage_input.get("visual_api") or {})
    boards: dict[str, Any] = {}
    repairable = 0
    for board_key, raw in dict(visual_api.get("boards") or {}).items():
        board = dict(raw or {})
        if str(board.get("status") or "").lower() == "completed":
            boards[str(board_key)] = board
            continue
        board_error = str(board.get("last_error") or reason or "")[:800]
        board.update({
            "status": "semantic_repair_pending",
            "task_id": None,
            "last_error": board_error,
            "provider_retry_generation": max(
                1,
                int(board.get("provider_retry_generation") or 0),
            ),
            "semantic_prompt_repair_requested": True,
            "semantic_prompt_repair_directive": str(
                decision.repair_directive or decision.rationale or ""
            )[:1200],
            "semantic_prompt_repair_requested_at": now.isoformat(),
        })
        boards[str(board_key)] = board
        repairable += 1
    if not boards:
        visual_api["semantic_prompt_repair_source_error"] = str(reason)[:800]
    visual_api.update({
        "status": "semantic_repair_pending",
        "boards": boards,
        "semantic_prompt_repair_requested": True,
        "semantic_prompt_repair_requested_at": now.isoformat(),
        "semantic_prompt_repair_directive": str(
            decision.repair_directive or decision.rationale or ""
        )[:1200],
    })
    # A semantic rejection is request-local, not provider health evidence.
    # Archive routing history for audit, then let the repaired prompt use the
    # administrator's current priority chain without penalizing an account.
    history = [
        dict(value)
        for value in list(stage_input.get("visual_semantic_repair_history") or [])[-11:]
        if isinstance(value, dict)
    ]
    history.append({
        "at": now.isoformat(),
        "reason": str(reason)[:800],
        "diagnosis": str(decision.diagnosis or "")[:1000],
        "directive": str(decision.repair_directive or "")[:1200],
        "input_fingerprint": str(
            dict(stage_input.get("last_recovery_supervisor_decision") or {}).get(
                "input_fingerprint"
            ) or ""
        )[:64],
    })
    stage_input["visual_semantic_repair_history"] = history
    stage_input["visual_api"] = visual_api
    stage_input["execution_backend"] = "api"
    stage_input["force_fresh_response"] = True
    stage_input["self_heal_action"] = "multimodal_semantic_prompt_repair"
    stage_input["retry_after"] = (now + timedelta(seconds=15)).isoformat()
    stage_input["retry_release_strategy"] = "database_due_at_periodic_self_heal"
    for key in (
        "api_fallback_to_browser",
        "api_force_browser_fallback",
        "visual_api_force_browser_fallback",
        "run_token",
        "execution_lease_expires_at",
        "retry_release_task_id",
    ):
        stage_input.pop(key, None)
    stage_row.input_json = _restamp_stage_runtime_policy(stage_input)
    stage_row.status = "retrying"
    stage_row.celery_task_id = None
    stage_row.started_at = None
    stage_row.completed_at = None
    stage_row.error_message = (
        "Recovery Supervisor requested multimodal semantic prompt repair: "
        f"{decision.reason_code}"
    )[:4000]
    project.status = "queued"
    project.current_stage = stage_row.stage
    project.last_error = (
        "故障调度官已结合提示词和参考图发起安全语义修复；"
        "完成的图片会保留，失败图片将使用新提示词重新生成。"
    )
    hibernate_project_browser_slot_for_api_video(
        db,
        project=project,
        active_stage=stage_row,
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_semantic_repair_scheduled",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "repairable_references": repairable,
        "retry_in_seconds": 15,
        "decision": decision.action.value,
        "decision_source": decision.decision_source,
    }


def _schedule_supervised_result_reconciliation(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    reason: str,
) -> dict[str, Any]:
    """Poll the existing billable identity before authorizing new spend."""

    wait_seconds = max(30, min(900, int(decision.wait_seconds or 0) or 60))
    stage_input = dict(stage_row.input_json or {})
    stage_input.update({
        "retry_after": (_stage_now() + timedelta(seconds=wait_seconds)).isoformat(),
        "retry_release_strategy": "database_due_at_periodic_self_heal",
        "self_heal_action": "reconcile_ambiguous_billable_submission",
        "reconcile_existing_submission_only": True,
    })
    for key in ("run_token", "execution_lease_expires_at", "retry_release_task_id"):
        stage_input.pop(key, None)
    stage_row.input_json = _restamp_stage_runtime_policy(stage_input)
    stage_row.status = "retrying"
    stage_row.celery_task_id = None
    stage_row.started_at = None
    stage_row.completed_at = None
    stage_row.error_message = str(reason)[:4000]
    project.status = "queued"
    project.current_stage = stage_row.stage
    project.last_error = "故障调度官正在核对已提交任务结果，不会重复付费提交。"
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_reconciliation_scheduled",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "retry_in_seconds": wait_seconds,
    }


def _pause_supervised_recovery(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    decision,
    reason: str,
) -> dict[str, Any]:
    now = _stage_now()
    stage_row.status = "paused"
    stage_row.completed_at = now
    stage_row.error_message = str(reason or decision.rationale)[:4000]
    state = dict(project.state_json or {})
    state.update({
        "paused_at": now.isoformat(),
        "automatic_quality_paused_at": now.isoformat(),
        "pause_reason_code": "recovery_supervisor_nonretryable",
        "pause_note": str(reason or decision.rationale)[:1200],
        "browser_slot_mode": "dormant",
    })
    project.state_json = state
    project.status = "paused"
    project.current_stage = stage_row.stage
    project.last_error = (
        "故障调度官判定当前错误不可安全自动恢复，项目已暂停并保留全部已完成资产。"
    )
    from app.services.hermes_agent.content_factory import _release_bridge_for_project

    _release_bridge_for_project(db, project_id=int(project.id))
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "recovery_supervisor_paused",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "decision": decision.action.value,
        "decision_source": decision.decision_source,
    }


def _supervised_recovery_decision(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    source_backend: str,
    reason: str,
    ambiguous_billable_submission: bool = False,
    browser_retry_exhausted: bool = False,
):
    incident = _recovery_supervisor_incident(
        db,
        project,
        stage_row,
        source_backend=source_backend,
        reason=reason,
        ambiguous_billable_submission=ambiguous_billable_submission,
        browser_retry_exhausted=browser_retry_exhausted,
    )
    evidence_images = _recovery_supervisor_evidence_images(
        db,
        project,
        dict(stage_row.input_json or {}),
    )
    decision = asyncio.run(
        decide_content_recovery(
            incident,
            evidence_images=evidence_images,
        )
    )
    _persist_recovery_supervisor_decision(
        project,
        stage_row,
        incident,
        decision,
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return incident, decision


def _api_browser_fallback_input(
    stage_input: dict[str, Any] | None,
    *,
    stage: str,
) -> dict[str, Any]:
    """Persist a provider-to-browser handoff across worker and bridge restarts."""
    values = dict(stage_input or {})
    prior_route = str(values.get("api_route") or "").strip()
    if prior_route:
        values["api_primary_route"] = prior_route
    values.update({
        "execution_backend": "browser",
        "api_route": None,
        "api_fallback_to_browser": True,
        "api_force_browser_fallback": True,
        "api_browser_fallback_attempted": True,
        "force_fresh_response": True,
        "clear_stale_composer_before_send": True,
        "self_heal_action": "wait_for_browser_after_api_budget",
    })
    if str(stage or "").upper() == "VISUAL_PREVIEW":
        # Retain the old visual keys while queued projects migrate to the
        # provider-agnostic handoff contract above.
        values["visual_api_force_browser_fallback"] = True
        values["visual_grid_browser_fallback_attempted"] = True
    return values


def _queue_api_stage_to_browser(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> dict[str, Any]:
    """Close the API delivery and queue one browser delivery for the same breakpoint."""
    stage_row.status = "failed"
    stage_row.completed_at = _stage_now()
    stage_row.error_message = f"API budget exhausted; browser fallback requested: {reason}"[:4000]
    project.status = "ready"
    project.current_stage = stage_row.stage
    project.last_error = None
    state = dict(project.state_json or {})
    state["last_api_browser_fallback"] = {
        "stage": stage_row.stage,
        "stage_id": int(stage_row.id),
        "variant_index": _active_variant_index(project),
        "reason": str(reason)[:1200],
        "requested_at": _stage_now().isoformat(),
    }
    project.state_json = state
    instruction = str(stage_row.instruction or "").strip() or (
        "The API execution budget was exhausted. Continue this exact stage once through the bound browser slot, "
        "using the same project, variant, benchmark assets, and output contract."
    )
    continue_workflow = bool(dict(stage_row.input_json or {}).get("continue_workflow", True))
    db.commit()
    from app.services.hermes_agent.content_factory import queue_stage

    try:
        queued = queue_stage(
            db,
            project=project,
            user_id=int(stage_row.user_id or project.user_id),
            instruction=instruction,
            target_stage=stage_row.stage,
            continue_workflow=continue_workflow,
            queue_priority=8,
            force_browser=True,
        )
        return {
            "status": "browser_fallback_queued",
            "stage_id": int(stage_row.id),
            "fallback_stage_id": int(queued.id),
            "project_key": project.project_key,
            "stage": stage_row.stage,
        }
    except APIError as exc:
        if exc.code in {
            "CONTENT_BROWSER_BRIDGE_REQUIRED",
            "CONTENT_BROWSER_BRIDGE_OFFLINE",
            "CONTENT_BROWSER_CAPACITY_FULL",
            "CONTENT_BROWSER_LOGIN_REQUIRED",
            "CONTENT_BROWSER_DEVICE_SELECTION_REQUIRED",
        }:
            fallback_input = _api_browser_fallback_input(
                dict(stage_row.input_json or {}),
                stage=stage_row.stage,
            )
            stage_row.input_json = fallback_input
            project.status = "waiting_bridge"
            project.current_stage = stage_row.stage
            project.last_error = (
                "The bounded API retry budget is exhausted. Hermes will resume this exact "
                "stage through the project's own browser bridge when it is available."
            )
            db.add(stage_row)
            db.add(project)
            db.commit()
            return {
                "status": "waiting_bridge_fallback",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
                "stage": stage_row.stage,
                "error_code": exc.code,
            }
        raise


def _recovery_transition_fault_digest(
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> str:
    return hashlib.sha256(
        "|".join((
            str(project.project_key),
            str(stage_row.id),
            str(stage_row.stage or ""),
            str(_stage_variant_index(stage_row, project)),
            classify_recovery_fault(str(reason or "")),
            re.sub(r"\s+", " ", str(reason or "").strip().lower())[:1200],
        )).encode("utf-8")
    ).hexdigest()


def _recovery_transition_has_live_cooldown(
    stage_row: HermesContentFactoryStage,
    *,
    now: datetime,
) -> bool:
    stage_input = dict(stage_row.input_json or {})
    transition = dict(stage_input.get("last_recovery_supervisor_transition") or {})
    if not transition:
        return False
    retry_after_raw = str(stage_input.get("retry_after") or "").strip()
    try:
        retry_after = datetime.fromisoformat(retry_after_raw)
    except (TypeError, ValueError):
        retry_after = None
    if bool(
        str(stage_row.status or "").strip().lower() == "retrying"
        and retry_after is not None
        and retry_after > now
    ):
        return True
    # A browser queue, pause, or reconciliation transition may be terminal on
    # the old stage and therefore has no retry_after.  Suppress late duplicate
    # incident reports for a short audit window so they cannot create a second
    # successor or overwrite the just-committed route decision.
    recorded_at_raw = str(transition.get("recorded_at") or "").strip()
    try:
        recorded_at = datetime.fromisoformat(recorded_at_raw)
    except (TypeError, ValueError):
        recorded_at = None
    return bool(
        recorded_at is not None
        and recorded_at >= now - timedelta(minutes=5)
        and str(transition.get("result_status") or "").strip()
    )


def _legacy_reasonless_recovery_pause(
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage | None,
) -> bool:
    """Identify automatic v4 recovery pauses created without a reason code."""

    state = dict(project.state_json or {})
    if str(state.get("pause_reason_code") or "").strip():
        return False
    return bool(
        stage_row is not None
        and str(stage_row.status or "").strip().lower() == "paused"
        and (
            "RECOVERY SUPERVISOR"
            in str(stage_row.error_message or "").upper()
            or bool(state.get("last_recovery_supervisor_decision"))
        )
    )


def _run_single_writer_recovery_transition(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    source_backend: str,
    reason: str,
    execute: Callable[[], dict[str, Any] | None],
) -> dict[str, Any] | None:
    """Serialize model diagnosis and its state transition per stage.

    Recovery callers only report incidents.  This lease is the sole writer
    fence around model selection plus the executable transition, preventing
    run_stage, waiters, and periodic self-heal from overwriting one another's
    whole JSON snapshots.
    """

    if not isinstance(db, Session):
        # Isolated unit doubles exercise transition semantics without Redis.
        return execute()
    recovery_lock = RedisDistributedLock(
        key=f"gmv:content-factory:recovery-stage:{int(stage_row.id)}",
        owner_token=uuid.uuid4().hex,
        ttl_seconds=600,
        heartbeat_interval=30,
    )
    if not recovery_lock.acquire(timeout=0):
        return {
            "status": "recovery_supervisor_transition_in_progress",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
            "stage": stage_row.stage,
        }
    try:
        # Every caller commits its incident evidence before this handoff.
        # Refresh under the distributed lease so a stale ORM snapshot cannot
        # overwrite a transition committed by an earlier reporter.
        db.refresh(project)
        db.refresh(stage_row)
        now = _stage_now()
        if _recovery_transition_has_live_cooldown(stage_row, now=now):
            return {
                "status": "recovery_supervisor_transition_already_scheduled",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
                "stage": stage_row.stage,
                "transition": dict(
                    dict(stage_row.input_json or {}).get(
                        "last_recovery_supervisor_transition"
                    )
                    or {}
                ),
            }
        result = execute()
        if not recovery_lock.verify_ownership():
            # The executor already committed a bounded transition.  Do not
            # append audit metadata after losing the sole-writer lease.
            return result
        db.refresh(project)
        db.refresh(stage_row)
        recorded_at = _stage_now().isoformat()
        transition = {
            "fault_digest": _recovery_transition_fault_digest(
                project,
                stage_row,
                reason=reason,
            ),
            "source_backend": str(source_backend or "")[:16],
            "result_status": str(dict(result or {}).get("status") or "")[:96],
            "recorded_at": recorded_at,
        }
        stage_input = dict(stage_row.input_json or {})
        stage_input["last_recovery_supervisor_transition"] = transition
        stage_row.input_json = stage_input
        state = dict(project.state_json or {})
        state["last_recovery_supervisor_transition"] = transition
        project.state_json = state
        db.add(stage_row)
        db.add(project)
        db.commit()
        return result
    finally:
        recovery_lock.release()


def _handoff_api_stage_to_browser_unlocked(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> dict[str, Any]:
    """Let the recovery role choose API cooldown, browser, or safe pause."""

    incident, decision = _supervised_recovery_decision(
        db,
        project,
        stage_row,
        source_backend="api",
        reason=reason,
    )
    if decision.action == RecoveryAction.SEMANTIC_PROMPT_REPAIR:
        return _schedule_supervised_visual_semantic_repair(
            db,
            project,
            stage_row,
            decision=decision,
            reason=reason,
        )
    if decision.action == RecoveryAction.RECOMPILE_STAGE_INPUT:
        return _recover_exhausted_semantic_api_stage(
            db,
            project,
            stage_row,
            reason=reason,
        )
    if decision.action == RecoveryAction.RECONCILE_LATE_RESULT:
        return _schedule_supervised_result_reconciliation(
            db,
            project,
            stage_row,
            decision=decision,
            reason=reason,
        )
    if decision.action == RecoveryAction.ROTATE_PROVIDER:
        return _schedule_supervised_provider_rotation(
            db,
            project,
            stage_row,
            decision=decision,
            reason=reason,
        )
    if decision.action in {
        RecoveryAction.WAIT_AND_RETRY_API,
        RecoveryAction.SWITCH_TO_API,
    }:
        return _schedule_supervised_api_retry(
            db,
            project,
            stage_row,
            decision=decision,
            # The supervisor has explicitly selected API recovery after the
            # current provider epoch was exhausted.  Start a cooled new epoch
            # from the administrator's enabled priority chain even when the
            # browser login state is merely unknown.  Otherwise an offline
            # bridge plus three temporarily unhealthy APIs becomes a permanent
            # manual pause despite the model choosing WAIT_AND_RETRY_API.
            allow_browser_handoff_reversal=True,
        )
    if decision.action == RecoveryAction.SWITCH_TO_BROWSER:
        return _queue_api_stage_to_browser(
            db,
            project,
            stage_row,
            reason=reason,
        )
    if decision.action == RecoveryAction.WAIT_FOR_BROWSER:
        stage_row.status = "failed"
        stage_row.completed_at = _stage_now()
        stage_row.error_message = str(reason)[:4000]
        project.status = "waiting_bridge"
        project.current_stage = stage_row.stage
        project.last_error = "故障调度官正在等待当前用户的浏览器恢复后继续。"
        db.add(stage_row)
        db.add(project)
        db.commit()
        return {
            "status": "recovery_supervisor_waiting_browser",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
            "stage": stage_row.stage,
        }
    return _pause_supervised_recovery(
        db,
        project,
        stage_row,
        decision=decision,
        reason=reason,
    )


def _handoff_api_stage_to_browser(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> dict[str, Any]:
    result = _run_single_writer_recovery_transition(
        db,
        project,
        stage_row,
        source_backend="api",
        reason=reason,
        execute=lambda: _handoff_api_stage_to_browser_unlocked(
            db,
            project,
            stage_row,
            reason=reason,
        ),
    )
    return dict(result or {
        "status": "recovery_supervisor_transition_in_progress",
        "stage_id": int(stage_row.id),
    })


def _recover_browser_fault_with_supervisor_unlocked(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
    browser_retry_exhausted: bool = False,
) -> dict[str, Any] | None:
    """Return an atomic recovery result, or None for a bounded browser retry."""

    incident, decision = _supervised_recovery_decision(
        db,
        project,
        stage_row,
        source_backend="browser",
        reason=reason,
        browser_retry_exhausted=browser_retry_exhausted,
    )
    if decision.action == RecoveryAction.RECONCILE_LATE_RESULT:
        return _schedule_supervised_result_reconciliation(
            db,
            project,
            stage_row,
            decision=decision,
            reason=reason,
        )
    if decision.action == RecoveryAction.ROTATE_PROVIDER:
        return _schedule_supervised_provider_rotation(
            db,
            project,
            stage_row,
            decision=decision,
            reason=reason,
        )
    if decision.action in {
        RecoveryAction.SWITCH_TO_API,
        RecoveryAction.WAIT_AND_RETRY_API,
    }:
        stage_input = dict(stage_row.input_json or {})
        if incident.fault_class == "BROWSER_UPLOAD_UNAVAILABLE":
            stage_input["browser_upload_api_return_count"] = int(
                stage_input.get("browser_upload_api_return_count") or 0
            ) + 1
        stage_row.input_json = stage_input
        return _schedule_supervised_api_retry(
            db,
            project,
            stage_row,
            decision=decision,
            allow_browser_handoff_reversal=True,
        )
    if decision.action == RecoveryAction.RETRY_BROWSER:
        return None
    if decision.action == RecoveryAction.WAIT_FOR_BROWSER:
        wait_seconds = max(15, min(3600, int(decision.wait_seconds or 0) or 300))
        stage_input = dict(stage_row.input_json or {})
        stage_input.update({
            "retry_after": (_stage_now() + timedelta(seconds=wait_seconds)).isoformat(),
            "retry_release_strategy": "database_due_at_periodic_self_heal",
            "self_heal_action": "recovery_supervisor_wait_for_browser",
        })
        for stale_key in (
            "run_token",
            "execution_lease_expires_at",
            "retry_release_task_id",
        ):
            stage_input.pop(stale_key, None)
        stage_row.input_json = _restamp_stage_runtime_policy(stage_input)
        stage_row.status = "retrying"
        stage_row.celery_task_id = None
        stage_row.started_at = None
        stage_row.completed_at = None
        stage_row.error_message = str(reason)[:4000]
        project.status = "waiting_bridge"
        project.current_stage = stage_row.stage
        project.last_error = (
            f"故障调度官正在等待浏览器状态恢复，{wait_seconds} 秒后重新检查；"
            "不会重复提交当前任务。"
        )
        db.add(stage_row)
        db.add(project)
        db.commit()
        return {
            "status": "recovery_supervisor_browser_wait_scheduled",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
            "stage": stage_row.stage,
            "retry_in_seconds": wait_seconds,
        }
    return _pause_supervised_recovery(
        db,
        project,
        stage_row,
        decision=decision,
        reason=reason,
    )


def _recover_browser_fault_with_supervisor(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
    browser_retry_exhausted: bool = False,
) -> dict[str, Any] | None:
    return _run_single_writer_recovery_transition(
        db,
        project,
        stage_row,
        source_backend="browser",
        reason=reason,
        execute=lambda: _recover_browser_fault_with_supervisor_unlocked(
            db,
            project,
            stage_row,
            reason=reason,
            browser_retry_exhausted=browser_retry_exhausted,
        ),
    )


def _recover_exhausted_semantic_api_stage(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    *,
    reason: str,
) -> dict[str, Any]:
    """Recover content-contract failures without ever waking a browser slot."""
    now = _stage_now()
    decision = _semantic_api_exhaustion_decision(
        dict(project.state_json or {}),
        stage=stage_row.stage,
        variant_index=_active_variant_index(project),
        error_message=reason,
    )
    action = str(decision["action"])

    stage_input = dict(stage_row.input_json or {})
    stage_input.update({
        "semantic_recovery_exhausted": True,
        "semantic_exhausted_at": now.isoformat(),
        "self_heal_action": "cooldown_after_semantic_api_exhaustion",
        "force_fresh_response": True,
        "semantic_recovery_strategy": recovery_strategy(
            attempt_count=int(decision.get("attempt_count") or 1),
            no_progress_cycles=int(decision.get("no_progress_cycles") or 1),
        ),
        "autonomy_policy_version": AUTONOMY_POLICY_VERSION,
    })
    for key in (
        "browser_slot",
        "browser_bridge_id",
        "browser_cdp_url",
        "browser_device_id",
        "browser_device_name",
        "browser_inbox_root",
        "api_force_browser_fallback",
        "api_browser_fallback_attempted",
    ):
        stage_input.pop(key, None)
    stage_row.input_json = stage_input
    stage_row.error_message = (
        "Semantic API generation epoch exhausted; cooling before a fresh "
        "API-only strategy; browser fallback prohibited: "
        f"{reason}"
    )[:4000]

    state = dict(decision["state"])
    state["browser_slot_mode"] = "dormant"
    project.state_json = state
    project.current_stage = stage_row.stage

    from app.services.hermes_agent.content_factory import (
        _release_bridge_for_project,
    )

    _release_bridge_for_project(db, project_id=int(project.id))
    retry_at = _schedule_exhausted_self_heal_stage(
        project,
        stage_row,
        now=now,
    )
    state.update({
        "browser_slot_mode": "dormant",
        "semantic_api_recovery": {
            "status": "cooling",
            "retry_at": retry_at.isoformat(),
            "strategy": stage_input["semantic_recovery_strategy"],
            "policy_version": AUTONOMY_POLICY_VERSION,
        },
    })
    project.state_json = state
    project.last_error = (
        "文案结构本轮 API 重写仍未收敛，系统已切换策略并进入冷却；"
        f"将在 {retry_at.strftime('%Y-%m-%d %H:%M:%S')} 自动继续，浏览器不会被唤醒。"
    )
    db.add(stage_row)
    db.add(project)
    db.commit()
    return {
        "status": "cooling_semantic_api_contract_exhausted",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "stage": stage_row.stage,
        "retry_at": retry_at.isoformat(),
    }


def _save_generated_image(path: Path, content: bytes) -> None:
    if not content:
        raise BandianwaApiError("Bandianwa image output is empty")
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with Image.open(io.BytesIO(content)) as source:
            image = source.convert("RGBA" if "A" in source.getbands() else "RGB")
            image.save(path, format="PNG", optimize=True)
    except Exception as exc:  # noqa: BLE001
        raise BandianwaApiError(f"Bandianwa returned invalid image bytes: {exc}") from exc
    _chmod_group_writable(path)


async def _bandianwa_image_bytes(
    client: Any,
    response: dict[str, Any],
    *,
    task_id: str | None,
) -> bytes | None:
    outputs = extract_image_outputs(response)
    if outputs:
        encoded_output = next((item for item in outputs if item.get("b64_json")), None)
        if encoded_output is not None:
            try:
                return base64.b64decode(str(encoded_output["b64_json"]), validate=True)
            except Exception as exc:  # noqa: BLE001
                raise BandianwaApiError("Bandianwa returned invalid image base64") from exc
        url_output = next((item for item in outputs if item.get("url")), None)
        if url_output is not None:
            content, _ = await client.download(str(url_output["url"]))
            return content
    status = extract_bandianwa_status(response)
    if status == "failed":
        code, message = extract_bandianwa_error(response)
        raise BandianwaApiError(
            f"Bandianwa image failed: {code or 'upstream_error'} {message or ''}".strip()
        )
    if status == "completed" and task_id:
        content, content_type = await client.get_image_content(task_id=task_id)
        if "json" in content_type.lower():
            try:
                payload = json.loads(content.decode("utf-8"))
            except Exception as exc:  # noqa: BLE001
                raise BandianwaApiError("Bandianwa image content returned invalid JSON") from exc
            if isinstance(payload, dict):
                content_outputs = extract_image_outputs(payload)
                if content_outputs:
                    first = content_outputs[0]
                    if first.get("b64_json"):
                        return base64.b64decode(str(first["b64_json"]), validate=True)
                    if first.get("url"):
                        downloaded, _ = await client.download(str(first["url"]))
                        return downloaded
                code, message = extract_bandianwa_error(payload)
                raise BandianwaApiError(
                    f"Bandianwa image content contains no image: {code or ''} {message or ''}".strip()
                )
        return content
    return None


def _visual_api_model_for_packet(packet: dict[str, Any]) -> str:
    """Select the image model from the requested visual medium, not the product.

    The package reference remains authoritative whichever model is used.  The
    image backend is selected from observed prompt adherence.  `gpt-image-2`
    rejects text-only asynchronous requests in this provider integration;
    the reference-plan's first two frames are intentionally text-only.  Route
    an explicit illustrated project through the provider's Pro image model so
    all four independent frames share one stable, API-only execution path.
    """
    configured_chain = [
        str(value or "").strip().lower()
        for value in list(packet.get("visual_image_model_chain") or [])
        if str(value or "").strip()
    ]
    configured_chain = [
        "gpt-image-2" if value == "gpt-image-2.0" else value
        for value in configured_chain
    ]
    try:
        configured_index = max(
            0,
            int(packet.get("visual_image_model_index") or 0),
        )
    except (TypeError, ValueError):
        configured_index = 0
    if configured_chain:
        return configured_chain[
            min(configured_index, len(configured_chain) - 1)
        ]
    visual_requirement_text = " ".join(
        str(packet.get(key) or "")
        for key in ("user_instruction", "visual_style_requirement", "project_requirements", "brief")
    )
    return (
        "nano_banana_pro"
        if re.search(
            r"\b(?:2d|2\.5d|animated|animation|illustrat(?:ed|ion)|cartoon|graphic novel)\b|"
            r"动画|插画|卡通|美式动画",
            visual_requirement_text,
            flags=re.IGNORECASE,
        )
        else "nano_banana_2"
    )


class _SupersededVisualProviderSubmission(RuntimeError):
    """A newer stage won while an older visual worker was still alive."""


def _assert_visual_provider_submission_current(
    db: Session,
    *,
    project_id: int,
    stage_id: int,
    stage_name: str,
    expected_request_id: str = "",
    expected_run_token: str = "",
) -> None:
    """Fence every billable image POST with fresh database authority.

    A worker may pass the outer stage guard and then spend minutes rendering
    its first continuity anchor.  During that wait an operator or self-heal
    can replace the stage.  Check the row again immediately before *each*
    subsequent provider submission so a warm-shutdown/requeued worker cannot
    spend on references 2-4 after losing ownership.
    """
    fresh_stage = (
        db.query(HermesContentFactoryStage)
        .filter(HermesContentFactoryStage.id == int(stage_id))
        .populate_existing()
        .one_or_none()
    )
    fresh_project = (
        db.query(HermesContentFactoryProject)
        .filter(HermesContentFactoryProject.id == int(project_id))
        .populate_existing()
        .one_or_none()
    )
    latest_stage_id = (
        db.query(func.max(HermesContentFactoryStage.id))
        .filter(
            HermesContentFactoryStage.project_id == int(project_id),
            HermesContentFactoryStage.stage == str(stage_name),
        )
        .filter(
            or_(
                HermesContentFactoryStage.status != "failed",
                HermesContentFactoryStage.error_message.is_(None),
                ~HermesContentFactoryStage.error_message.like(
                    "Duplicate publish suppressed:%"
                ),
            )
        )
        .scalar()
    )
    if (
        fresh_stage is None
        or fresh_project is None
        or str(fresh_stage.status or "").lower() not in {"queued", "running", "retrying"}
        or str(getattr(fresh_project, "status", "") or "").lower() == "paused"
        or bool(dict(getattr(fresh_project, "config_json", None) or {}).get("manual_paused", False))
        or str(fresh_project.current_stage or "") != str(stage_name)
        or int(latest_stage_id or 0) != int(stage_id)
        or (
            bool(str(expected_request_id or "").strip())
            and str(fresh_stage.celery_task_id or "").strip()
            != str(expected_request_id or "").strip()
        )
        or (
            bool(str(expected_run_token or "").strip())
            and _stage_run_token(fresh_stage)
            != str(expected_run_token or "").strip()
        )
    ):
        raise _SupersededVisualProviderSubmission(
            f"visual stage {stage_id} lost provider-submit authority "
            f"(latest_stage={latest_stage_id or 'none'}, "
            f"registered_task={str(getattr(fresh_stage, 'celery_task_id', '') or '')}, "
            f"expected_task={str(expected_request_id or '')})"
        )


def _visual_continuity_reference_instruction() -> str:
    """Lock cast identity without accidentally cloning the anchor composition."""
    return (
        "\nMANDATORY CHARACTER CONTINUITY: input 1 is the nearest approved preceding continuity frame. "
        "Use it only to preserve each adult's identity (face, hair, skin tone and wardrobe) and the "
        "illustration style. Preserve room design only when the current beat remains in that same location. "
        "The current segment's written location is authoritative; when it changes location, render the new "
        "location and do not copy the input room. Render the current segment as a genuinely new shot. "
        "DO NOT copy input 1's pose, gesture, body direction, character placement, camera angle, framing, "
        "foreground/background arrangement, or departure action. The current segment's action and spatial "
        "blocking are authoritative even when they conflict with input 1's composition."
    )


def _repair_continuity_anchor_paths(
    preserved_paths: dict[int, Path],
    failed_indices: set[int],
    *,
    preferred_anchor_indices: set[int] | None = None,
) -> dict[int, Path]:
    """Bind the AI reviewer's accepted continuity anchors to repair calls.

    The multimodal reviewer chooses which accepted frames are valid anchors.
    The runtime only resolves those indices to durable local files and picks
    the nearest one for each repair.  This supports a reverse anchor when the
    first frame failed instead of silently issuing a text-only redraw.
    """
    anchors: dict[int, Path] = {}
    available = sorted(
        index
        for index, path in preserved_paths.items()
        if index > 0 and path.is_file()
    )
    preferred = {
        int(index)
        for index in set(preferred_anchor_indices or set())
        if int(index) in available
    }
    if preferred:
        available = sorted(preferred)
    for failed_index in sorted(failed_indices):
        if not available:
            continue
        anchor_index = min(
            available,
            key=lambda index: (
                abs(index - failed_index),
                0 if index < failed_index else 1,
                index,
            ),
        )
        anchors[failed_index] = preserved_paths[anchor_index]
    return anchors


def _repair_continuity_anchor_for_spec(
    spec: dict[str, Any],
    repair_anchor_paths: dict[int, Path],
) -> Path | None:
    """Return the continuity anchor for a native or shared repair board.

    Sparse repair may combine non-adjacent failed references into one board to
    preserve identity and reduce image cost.  That shared board still needs
    the nearest accepted frame for its first repaired reference; otherwise a
    text-only retry can consistently redraw the wrong cast across every new
    cell while looking internally coherent.
    """
    raw_indices = list(spec.get("global_reference_indices") or [])
    if not raw_indices:
        raw_indices = [
            spec.get("global_start_index") or spec.get("board_index") or 0
        ]
    for raw in raw_indices:
        try:
            index = int(raw or 0)
        except (TypeError, ValueError):
            continue
        anchor = repair_anchor_paths.get(index)
        if anchor is not None and anchor.is_file():
            return anchor
    return None


def _commit_visual_api_progress(
    db,
    *,
    stage_row: HermesContentFactoryStage,
    stage_input: dict[str, Any],
    api_state: dict[str, Any],
) -> None:
    """Persist nested provider progress with a fresh JSON object identity.

    SQLAlchemy does not track mutations inside ordinary JSON dictionaries.
    Reusing the same ``stage_input`` object across a submit/poll/recursive
    retry cycle persisted the initial ``queued`` state but silently discarded
    later ``completed`` transitions.  A deep JSON copy makes every progress
    checkpoint an explicit column assignment and keeps monitoring truthful.

    A repair stage can inherit a checkpoint created under an older worker
    policy.  Provider progress is not policy authority, so every durable
    checkpoint must also restamp the currently loaded policy versions.  Doing
    this at the single persistence boundary prevents later submit/poll writes
    from reintroducing stale audit metadata.
    """
    stage_input.update(_restamp_stage_runtime_policy(stage_input))
    stage_input["visual_api"] = api_state
    stage_row.input_json = json.loads(json.dumps(stage_input))
    db.commit()


def _restamp_stage_runtime_policy(values: dict[str, Any] | None) -> dict[str, Any]:
    """Return a fresh stage payload carrying current worker policy authority."""
    current = dict(values or {})
    current["self_heal_policy_version"] = SELF_HEAL_POLICY_VERSION
    current["hermes_learning_policy_version"] = HERMES_LEARNING_POLICY_VERSION
    return current


def _should_seed_generated_continuity_anchor(
    packet: dict[str, Any],
    *,
    has_uploaded_character_anchor: bool,
    reference_count: int,
) -> bool:
    """Use segment 1 as the cast/room seed whenever no uploaded anchor exists.

    Targeted repair must preserve more than filenames: a replacement late
    frame still needs the exact approved adult identity, wardrobe, illustration
    medium, and room architecture.  Text-only repair proved insufficient and
    produced a different person and location.  The continuity instruction
    explicitly forbids copying pose, framing, or action, so keep the durable
    segment-1 image attached while the current segment prompt owns composition.
    """
    return (
        not has_uploaded_character_anchor
        and int(reference_count) > 1
    )


def _completed_individual_visual_checkpoint_reusable(
    board_state: dict[str, Any],
    spec: dict[str, Any],
    *,
    source_prompt: str,
) -> bool:
    """Reject contact-sheet/stale checkpoints that collide with a frame key."""
    try:
        index = int(spec.get("board_index") or 0)
        start = int(board_state.get("global_start_index") or 0)
        end = int(board_state.get("global_end_index") or 0)
        panels = int(board_state.get("expected_panels") or 0)
    except (TypeError, ValueError):
        return False
    completed_path = Path(str(board_state.get("output_path") or ""))
    expected_source_digest = hashlib.sha256(
        str(source_prompt or "").encode("utf-8")
    ).hexdigest()
    stored_source_digest = str(
        board_state.get("source_prompt_sha256")
        or board_state.get("prompt_digest")
        or ""
    )
    return bool(
        str(board_state.get("status") or "").lower() == "completed"
        and panels == 1
        and start == index
        and end == index
        and stored_source_digest == expected_source_digest
        and completed_path.is_file()
        and completed_path.stat().st_size > 0
    )


def _generate_individual_visual_references_via_api(
    db,
    *,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    packet: dict[str, Any],
    prompt_specs: list[tuple[str, dict[str, Any]]],
    client: Any,
    provider_key: str,
    visual_model: str,
    output_dir: Path,
    execution_id: str,
    stage_input: dict[str, Any],
    api_state: dict[str, Any],
    provider_retry_generation: int,
    expected_request_id: str,
    expected_run_token: str,
    continuity_anchor_path: Path | None = None,
    continuity_anchor_paths: dict[int, Path] | None = None,
    suppress_generated_continuity_seed: bool = False,
) -> tuple[list[str], dict[str, Any]]:
    """Submit one native reference per segment before polling any of them.

    Each single-frame provider job is independent.  Waiting for one image to
    finish before submitting the next made four 10-second segments take roughly
    four provider runtimes and unnecessarily blocked the variant pipeline.  We
    persist every submission first, then poll the durable task ids together so
    a worker restart resumes without duplicate renders.
    """
    boards_state = dict(api_state.get("boards") or {})
    total_reference_count = max(
        len(prompt_specs),
        int(api_state.get("expected_reference_count") or 0),
        max(
            (
                int(spec.get("board_count") or 0)
                for _prompt, spec in prompt_specs
            ),
            default=0,
        ),
    )

    # With no user-supplied character anchor, four independent image calls
    # cannot reliably preserve face/hair/wardrobe.  Establish segment 1 as a
    # durable cast anchor, then fan the remaining segments out in parallel
    # against that exact frame.  This keeps most of the parallel throughput
    # while making continuity a real provider input rather than a wish in text.
    has_uploaded_character_anchor = any(
        isinstance(asset, dict)
        and str(asset.get("role") or asset.get("asset_role") or "").strip().lower() == "character_reference"
        for asset in list(packet.get("browser_assets") or [])
    )
    ordered_specs = sorted(prompt_specs, key=lambda item: int(item[1].get("board_index") or 0))
    if (
        continuity_anchor_path is None
        and not continuity_anchor_paths
        and not suppress_generated_continuity_seed
        and _should_seed_generated_continuity_anchor(
            packet,
            has_uploaded_character_anchor=has_uploaded_character_anchor,
            reference_count=len(ordered_specs),
        )
    ):
        first_paths, first_meta = _generate_individual_visual_references_via_api(
            db,
            project=project,
            stage_row=stage_row,
            packet=packet,
            prompt_specs=[ordered_specs[0]],
            client=client,
            provider_key=provider_key,
            visual_model=visual_model,
            output_dir=output_dir,
            execution_id=execution_id,
            stage_input=stage_input,
            api_state=api_state,
            provider_retry_generation=provider_retry_generation,
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
            continuity_anchor_path=Path(str(api_state.get("continuity_anchor_path") or first_paths[0])) if api_state.get("continuity_anchor_path") else None,
            continuity_anchor_paths=None,
            suppress_generated_continuity_seed=False,
        )
        first_anchor = Path(str(first_paths[0]))
        if not first_anchor.is_file():
            raise BandianwaApiError("first visual reference did not persist as a continuity anchor")
        api_state["continuity_anchor_path"] = str(first_anchor)
        _commit_visual_api_progress(
            db,
            stage_row=stage_row,
            stage_input=stage_input,
            api_state=api_state,
        )
        rest_paths, rest_meta = _generate_individual_visual_references_via_api(
            db,
            project=project,
            stage_row=stage_row,
            packet=packet,
            prompt_specs=ordered_specs[1:],
            client=client,
            provider_key=provider_key,
            visual_model=visual_model,
            output_dir=output_dir,
            execution_id=execution_id,
            stage_input=stage_input,
            api_state=api_state,
            provider_retry_generation=provider_retry_generation,
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
            continuity_anchor_path=first_anchor,
            continuity_anchor_paths=None,
            suppress_generated_continuity_seed=False,
        )
        merged = sorted(
            list(first_meta.get("boards") or []) + list(rest_meta.get("boards") or []),
            key=lambda item: int(item["board_index"]),
        )
        return [str(item["output_path"]) for item in merged], {
            "provider": provider_key,
            "model": visual_model,
            "board_count": len(ordered_specs),
            "boards": merged,
            "prompt_chars": int(first_meta.get("prompt_chars") or 0) + int(rest_meta.get("prompt_chars") or 0),
            "reference_count": sum(int(item.get("reference_count") or 0) for item in merged),
            "expected_panels": len(ordered_specs),
            "generated_continuity_anchor": str(first_anchor),
        }
    jobs: dict[str, dict[str, Any]] = {}
    output_paths: list[str] = []
    board_meta: list[dict[str, Any]] = []
    submission_failures: list[str] = []

    def _meta(job: dict[str, Any], *, recovered: bool = False) -> dict[str, Any]:
        spec = dict(job["spec"])
        value = {
            "board_index": int(spec["board_index"]),
            "board_count": int(spec["board_count"]),
            "output_path": str(job["output_path"]),
            "task_id": str(job.get("task_id") or ""),
            "expected_panels": 1,
            "global_start_index": int(spec["global_start_index"]),
            "global_end_index": int(spec["global_end_index"]),
            "size": str(spec["size"]),
            "reference_count": int(job.get("reference_count") or 0),
        }
        if recovered:
            value["recovered_existing_file"] = True
        return value

    # Phase 1: make every submission durable before waiting on provider work.
    for base_prompt, raw_spec in prompt_specs:
        _assert_visual_provider_submission_current(
            db,
            project_id=int(project.id),
            stage_id=int(stage_row.id),
            stage_name=str(stage_row.stage),
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
        )
        spec = dict(raw_spec)
        board_index = int(spec["board_index"])
        board_key = str(board_index)
        board_state = dict(boards_state.get(board_key) or {})
        source_prompt = str(base_prompt)
        # Each reference owns its own render generation. A failed sibling (or
        # a resumed in-flight sibling) must not advance this board's
        # idempotency key and create an unrelated paid generation. Legacy
        # boardless checkpoints still start safely at generation zero.
        board_retry_generation = max(
            0,
            int(board_state.get("provider_retry_generation") or 0),
        )
        completed_path = Path(str(board_state.get("output_path") or ""))
        if _completed_individual_visual_checkpoint_reusable(
            board_state,
            spec,
            source_prompt=source_prompt,
        ):
            job = {
                "spec": spec,
                "prompt_digest": str(board_state.get("prompt_digest") or ""),
                "output_path": completed_path,
                "reference_count": int(board_state.get("reference_count") or 0),
                "task_id": str(board_state.get("task_id") or "").strip(),
            }
            output_paths.append(str(completed_path))
            board_meta.append(_meta(job, recovered=True))
            continue
        semantic_override = str(
            board_state.get("semantic_prompt_override") or ""
        ).strip()
        repair_error = str(board_state.get("last_error") or "")
        repair_status = str(
            board_state.get("semantic_prompt_repair_status") or ""
        ).lower()
        repair_attempt_count = int(
            board_state.get("semantic_prompt_repair_attempt_count") or 0
        )
        # Assemble the exact ordered visual authorities before asking Hermes
        # to repair semantics.  A text-only repair cannot tell whether a word
        # conflicts with the actual character, scene, or product reference.
        reference_paths = visual_generation_reference_paths(
            packet,
            plan=list(spec["plan"]),
            include_product=True,
        )
        current_continuity_anchor = (
            dict(continuity_anchor_paths or {}).get(board_index)
            or continuity_anchor_path
        )
        repair_reference_paths = [str(value) for value in reference_paths]
        if (
            current_continuity_anchor is not None
            and current_continuity_anchor.is_file()
        ):
            repair_reference_paths = [
                str(current_continuity_anchor)
            ] + repair_reference_paths
        if (
            board_retry_generation > 0
            and not semantic_override
            and repair_attempt_count < 2
            and _visual_prompt_semantic_rejection(repair_error)
        ):
            # Persist the repair lease before calling Hermes. A worker crash
            # replays the same stateless idempotency key instead of creating a
            # second model turn or a second image task.
            if repair_status != "running":
                repair_attempt_count += 1
            board_state.update({
                "semantic_prompt_repair_status": "running",
                "semantic_prompt_repair_attempt_count": repair_attempt_count,
                "semantic_prompt_repair_started_at": _stage_now().isoformat(),
                "semantic_prompt_repair_source_error": repair_error[:800],
                "semantic_prompt_repair_source_sha256": hashlib.sha256(
                    source_prompt.encode("utf-8")
                ).hexdigest(),
            })
            boards_state[board_key] = board_state
            api_state.update({
                "status": "repairing_prompt",
                "boards": boards_state,
                "board_count": total_reference_count,
            })
            _commit_visual_api_progress(
                db,
                stage_row=stage_row,
                stage_input=stage_input,
                api_state=api_state,
            )
            try:
                repaired, repair_meta = asyncio.run(
                    repair_rejected_visual_prompt(
                        current_prompt=source_prompt,
                        provider_error=repair_error,
                        project_key=str(project.project_key),
                        stage_id=int(stage_row.id),
                        reference_index=board_index,
                        provider_key=provider_key,
                        visual_model=visual_model,
                        reference_paths=repair_reference_paths,
                    )
                )
            except Exception as repair_exc:
                # The ordinary provider failover remains available if the
                # isolated repair model is temporarily unavailable. Keep the
                # failure auditable but never open a browser solely for this.
                board_state.update({
                    "semantic_prompt_repair_status": "failed",
                    "semantic_prompt_repair_error": str(repair_exc)[:800],
                    "semantic_prompt_repair_failed_at": _stage_now().isoformat(),
                })
            else:
                semantic_override = repaired.repaired_prompt
                board_state.update({
                    "semantic_prompt_repair_status": "completed",
                    "semantic_prompt_repair_count": int(
                        board_state.get("semantic_prompt_repair_count") or 0
                    ) + 1,
                    "semantic_prompt_override": semantic_override,
                    "semantic_prompt_override_sha256": str(
                        repair_meta.get("repaired_prompt_sha256") or ""
                    ),
                    "semantic_prompt_repair_diagnosis": repaired.diagnosis,
                    "semantic_prompt_repair_change_summary": (
                        repaired.change_summary
                    ),
                    "semantic_prompt_repair_model": str(
                        repair_meta.get("model") or ""
                    ),
                    "semantic_prompt_repair_request_id": str(
                        repair_meta.get("request_id") or ""
                    ),
                    "semantic_prompt_repair_completed_at": (
                        _stage_now().isoformat()
                    ),
                })
            boards_state[board_key] = board_state
            api_state.update({
                "status": (
                    "prompt_repaired"
                    if semantic_override
                    else "partial_failed"
                ),
                "boards": boards_state,
                "board_count": total_reference_count,
            })
            _commit_visual_api_progress(
                db,
                stage_row=stage_row,
                stage_input=stage_input,
                api_state=api_state,
            )
        prompt = semantic_override or source_prompt
        if board_retry_generation and not semantic_override:
            prompt += (
                f"\nPROVIDER RETRY: Render this one native {_configured_video_aspect_ratio(project)} reference only. Keep the requested beat, "
                "simplify poses/background, use no text, and do not reuse the prior failed composition. "
                f"Retry generation {board_retry_generation}."
            )
        # Product-visible frames receive the authoritative package as a model
        # reference.  The provider renders it naturally in scene perspective;
        # no local paste/composite path is allowed.
        images = [image_file_data_url(path) for path in reference_paths if Path(str(path)).is_file()]
        if (
            current_continuity_anchor is not None
            and current_continuity_anchor.is_file()
        ):
            images = [
                image_file_data_url(str(current_continuity_anchor))
            ] + images
            prompt += _visual_continuity_reference_instruction()
        # Prompt identity is calculated after every semantic and continuity
        # instruction is present.  Previously the continuity line was added
        # after hashing, so materially different provider payloads could share
        # one idempotency key and silently replay the wrong request.
        prompt_digest = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
        digest = hashlib.sha256(
            f"{execution_id}:b{board_index}:{visual_model}:{prompt_digest}:r{board_retry_generation}".encode("utf-8")
        ).hexdigest()[:16]
        output_path = output_dir / f"visual-preview-api-reference-{board_index:02d}-{digest}.png"
        job = {
            "spec": spec,
            "prompt_digest": prompt_digest,
            "output_path": output_path,
            "reference_count": len(images),
            "task_id": str(board_state.get("task_id") or "").strip(),
        }
        if output_path.is_file() and output_path.stat().st_size > 0:
            output_paths.append(str(output_path))
            board_meta.append(_meta(job, recovered=True))
            continue
        if board_state.get("prompt_digest") != prompt_digest:
            semantic_retry_state = {
                key: board_state[key]
                for key in (
                    "product_scene_repair_count",
                    "product_scene_last_error",
                    "product_scene_repair_policy",
                    "semantic_prompt_repair_status",
                    "semantic_prompt_repair_attempt_count",
                    "semantic_prompt_repair_count",
                    "semantic_prompt_override",
                    "semantic_prompt_override_sha256",
                    "semantic_prompt_repair_source_error",
                    "semantic_prompt_repair_source_sha256",
                    "semantic_prompt_repair_diagnosis",
                    "semantic_prompt_repair_change_summary",
                    "semantic_prompt_repair_model",
                    "semantic_prompt_repair_request_id",
                    "semantic_prompt_repair_completed_at",
                )
                if key in board_state
            }
            board_state = {
                "prompt_digest": prompt_digest,
                "source_prompt_sha256": hashlib.sha256(
                    source_prompt.encode("utf-8")
                ).hexdigest(),
                "source_prompt_excerpt": source_prompt[:2400],
                "submitted_prompt_excerpt": prompt[:3200],
                "provider_retry_generation": board_retry_generation,
                **semantic_retry_state,
            }
            job["task_id"] = ""
        else:
            # Persist the real provider input even for a resumed checkpoint.
            # Fault Hermes needs this evidence to distinguish transport faults
            # from prompt/reference conflicts without guessing or repeating a
            # paid request.
            board_state.update({
                "source_prompt_excerpt": source_prompt[:2400],
                "submitted_prompt_excerpt": prompt[:3200],
            })
        if not job["task_id"]:
            _assert_visual_provider_submission_current(
                db,
                project_id=int(project.id),
                stage_id=int(stage_row.id),
                stage_name=str(stage_row.stage),
                expected_request_id=expected_request_id,
                expected_run_token=expected_run_token,
            )
            try:
                response = asyncio.run(
                    client.create_image_task(
                        prompt=prompt,
                        size=str(spec["size"]),
                        model=visual_model,
                        images=images,
                        idempotency_key=(
                            f"{execution_id}:reference-{board_index}:{visual_model}:{prompt_digest[:16]}:r{board_retry_generation}"
                        ),
                    )
                )
            except (
                BandianwaApiError,
                Flow2ApiError,
                Sub2ApiApiError,
                ToApisApiError,
            ) as exc:
                # One transport failure must not discard already-submitted
                # sibling references or inherit another provider's historical
                # failure count. Persist this exact reference as a new bounded
                # generation, then continue submitting the remaining refs.
                # The next delivery reuses the same idempotency key first, so a
                # POST whose response was lost is recovered rather than billed
                # twice.
                transport_retry_count = int(
                    board_state.get("provider_transport_retry_count") or 0
                ) + 1
                failure = f"reference {board_index}: {exc}"
                board_state.update({
                    "status": "failed",
                    "task_id": None,
                    "last_error": str(exc)[:800],
                    "failed_at": _stage_now().isoformat(),
                    # A disconnected POST did not prove that the image model
                    # rejected or even received the job. Reuse the exact same
                    # provider idempotency key on retry; advancing generation
                    # here previously risked duplicate billing and eventually
                    # regenerated every successful frame with the expensive
                    # fallback model.
                    "provider_retry_generation": board_retry_generation,
                    "provider_transport_retry_count": transport_retry_count,
                })
                boards_state[board_key] = board_state
                api_state.update({
                    "provider": provider_key,
                    "model": visual_model,
                    "execution_id": execution_id,
                    "status": "partial_failed",
                    "board_count": total_reference_count,
                    "boards": boards_state,
                    "provider_retry_generation": max(
                        int(api_state.get("provider_retry_generation") or 0),
                        board_retry_generation,
                    ),
                    "provider_transport_retry_count": max(
                        int(api_state.get("provider_transport_retry_count") or 0),
                        transport_retry_count,
                    ),
                    "last_error": failure[:800],
                    "failed_at": _stage_now().isoformat(),
                })
                _commit_visual_api_progress(
                    db,
                    stage_row=stage_row,
                    stage_input=stage_input,
                    api_state=api_state,
                )
                submission_failures.append(failure)
                continue
            immediate_content = asyncio.run(
                _bandianwa_image_bytes(client, response, task_id=None)
            )
            if immediate_content is not None:
                # Gemini image generation through Sub2API completes in the
                # submit response. Save it before persisting a pseudo task id;
                # a later worker must never poll that id through the unrelated
                # OpenAI async task endpoint.
                # A synchronous image response can arrive after an operator
                # pause or a newer visual stage has taken ownership.  Fence
                # the local persistence just like the asynchronous polling
                # path so late paid results never become project authority.
                _assert_visual_provider_submission_current(
                    db,
                    project_id=int(project.id),
                    stage_id=int(stage_row.id),
                    stage_name=str(stage_row.stage),
                    expected_request_id=expected_request_id,
                    expected_run_token=expected_run_token,
                )
                _save_generated_image(output_path, immediate_content)
                job["task_id"] = extract_bandianwa_task_id(response)
                board_state.update({
                    "task_id": None,
                    "provider_result_id": job["task_id"],
                    "status": "completed",
                    "completed_at": _stage_now().isoformat(),
                    "output_path": str(output_path),
                    "prompt_chars": len(prompt),
                    "size": str(spec["size"]),
                    "expected_panels": 1,
                    "global_start_index": int(spec["global_start_index"]),
                    "global_end_index": int(spec["global_end_index"]),
                    "reference_count": len(images),
                    "provider_retry_generation": board_retry_generation,
                    "provider_transport_retry_count": 0,
                })
                boards_state[board_key] = board_state
                output_paths.append(str(output_path))
                board_meta.append(_meta(job))
                api_state.update({
                    "provider": provider_key,
                    "model": visual_model,
                    "execution_id": execution_id,
                    "status": "running",
                    "board_count": total_reference_count,
                    "boards": boards_state,
                })
                _commit_visual_api_progress(
                    db,
                    stage_row=stage_row,
                    stage_input=stage_input,
                    api_state=api_state,
                )
                continue
            job["task_id"] = extract_bandianwa_task_id(response)
            if not job["task_id"]:
                raise BandianwaApiError(
                    f"{provider_key} did not return an image task id for reference {board_index}"
                )
            board_state.update({
                "task_id": job["task_id"],
                "status": extract_bandianwa_status(response) or "submitted",
                "submitted_at": _stage_now().isoformat(),
                "prompt_chars": len(prompt),
                "size": str(spec["size"]),
                "expected_panels": 1,
                "global_start_index": int(spec["global_start_index"]),
                "global_end_index": int(spec["global_end_index"]),
                "reference_count": len(images),
                "provider_retry_generation": board_retry_generation,
                "provider_transport_retry_count": 0,
            })
            boards_state[board_key] = board_state
            api_state.update({
                "provider": provider_key,
                "model": visual_model,
                "execution_id": execution_id,
                "provider_retry_generation": max(
                    int(api_state.get("provider_retry_generation") or 0),
                    int(board_state.get("provider_retry_generation") or 0),
                ),
                "status": "submitted",
                "board_count": total_reference_count,
                "boards": boards_state,
            })
            _commit_visual_api_progress(
                db,
                stage_row=stage_row,
                stage_input=stage_input,
                api_state=api_state,
            )
        jobs[board_key] = job

    # Phase 2: poll every submitted provider task.  The upstream jobs run in
    # parallel; round-robin polling keeps one slow reference from hiding a
    # completed later segment.
    deadline = time.monotonic() + 720
    pending = dict(jobs)
    failed_references: list[str] = list(submission_failures)

    def _record_failed_reference(board_key: str, task_id: str, failure: str) -> None:
        """Persist one failed segment while allowing sibling jobs to finish."""
        state = dict(boards_state.get(board_key) or {})
        next_retry_generation = int(state.get("provider_retry_generation") or 0) + 1
        if str(state.get("semantic_prompt_override") or "").strip():
            # One terminal task already tested Hermes' semantically repaired
            # prompt. Repeating that exact paid render cannot add information;
            # exhaust this provider/model generation and let the existing
            # provider/model failover chain take over.
            maximum = max(
                1,
                int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")),
            )
            next_retry_generation = max(next_retry_generation, maximum + 1)
            state["semantic_prompt_repaired_render_failed"] = True
        state.update({
            "status": "failed",
            "task_id": None,
            "last_failed_task_id": task_id,
            "last_error": failure[:800],
            "failed_at": _stage_now().isoformat(),
            "provider_retry_generation": next_retry_generation,
        })
        boards_state[board_key] = state
        pending.pop(board_key, None)
        failed_references.append(failure)
        api_state.update({
            "status": "partial_failed",
            "boards": boards_state,
            "board_count": total_reference_count,
            "provider_retry_generation": max(
                int(api_state.get("provider_retry_generation") or 0),
                next_retry_generation,
            ),
            "last_error": failure[:800],
            "failed_at": _stage_now().isoformat(),
        })
        _commit_visual_api_progress(
            db,
            stage_row=stage_row,
            stage_input=stage_input,
            api_state=api_state,
        )

    while pending and time.monotonic() < deadline:
        progress = False
        for board_key, job in list(pending.items()):
            task_id = str(job["task_id"])
            try:
                response = asyncio.run(client.get_image_task(task_id=task_id))
                if extract_bandianwa_status(response) == "failed":
                    code, message = extract_bandianwa_error(response)
                    failure = (
                        f"reference {board_key}: {code or 'upstream_error'} {message or ''}"
                    ).strip()
                    _record_failed_reference(board_key, task_id, failure)
                    progress = True
                    continue
                content = asyncio.run(_bandianwa_image_bytes(client, response, task_id=task_id))
            except (
                BandianwaApiError,
                Flow2ApiError,
                Sub2ApiApiError,
                ToApisApiError,
            ) as exc:
                if _visual_provider_task_reusable_after_error(
                    task_id,
                    str(exc),
                ):
                    # The provider accepted and billed this immutable task.
                    # A failed GET/download must retain its task id and resume
                    # polling rather than opening a new paid generation.
                    state = dict(boards_state.get(board_key) or {})
                    transport_count = int(
                        state.get("provider_transport_retry_count") or 0
                    ) + 1
                    state.update({
                        "status": "poll_retrying",
                        "task_id": task_id,
                        "last_error": str(exc)[:800],
                        "last_transport_error_at": _stage_now().isoformat(),
                        "provider_transport_retry_count": transport_count,
                    })
                    boards_state[board_key] = state
                    api_state.update({
                        "status": "poll_retrying",
                        "boards": boards_state,
                        "board_count": total_reference_count,
                        "provider_transport_retry_count": max(
                            int(api_state.get("provider_transport_retry_count") or 0),
                            transport_count,
                        ),
                        "last_error": str(exc)[:800],
                    })
                    _commit_visual_api_progress(
                        db,
                        stage_row=stage_row,
                        stage_input=stage_input,
                        api_state=api_state,
                    )
                    continue
                # A provider-declared terminal render failure needs a bounded
                # new generation; healthy sibling jobs keep polling.
                _record_failed_reference(
                    board_key,
                    task_id,
                    f"reference {board_key}: {exc}",
                )
                progress = True
                continue
            if content is None:
                continue
            # A manual pause or newer stage may arrive while the remote image
            # task is polling. Revalidate after the provider response and
            # before persisting any file/state so late results cannot advance
            # a paused or superseded project.
            _assert_visual_provider_submission_current(
                db,
                project_id=int(project.id),
                stage_id=int(stage_row.id),
                stage_name=str(stage_row.stage),
                expected_request_id=expected_request_id,
                expected_run_token=expected_run_token,
            )
            _save_generated_image(job["output_path"], content)
            state = dict(boards_state.get(board_key) or {})
            state.update({
                "status": "completed",
                "completed_at": _stage_now().isoformat(),
                "output_path": str(job["output_path"]),
                "task_id": task_id,
                "provider_transport_retry_count": 0,
            })
            boards_state[board_key] = state
            output_paths.append(str(job["output_path"]))
            board_meta.append(_meta(job))
            pending.pop(board_key, None)
            progress = True
            api_state.update({
                "status": "partial_failed" if failed_references else ("running" if pending else "completed"),
                "completed_at": _stage_now().isoformat() if not pending and not failed_references else None,
                "boards": boards_state,
                "board_count": total_reference_count,
                "provider_retry_generation": max(
                    int(api_state.get("provider_retry_generation") or 0),
                    int(dict(boards_state.get(board_key) or {}).get("provider_retry_generation") or 0),
                ),
            })
            _commit_visual_api_progress(
                db,
                stage_row=stage_row,
                stage_input=stage_input,
                api_state=api_state,
            )
        if pending and not progress:
            time.sleep(5)
    if pending:
        waiting = ", ".join(sorted(pending))
        raise BandianwaApiError(
            f"{provider_key} image references did not complete before timeout: {waiting}"
        )
    if failed_references:
        raise BandianwaApiError(
            f"{provider_key} image reference failures after polling every submitted reference: "
            + "; ".join(failed_references)
        )
    board_meta.sort(key=lambda item: int(item["board_index"]))
    output_paths = [str(item["output_path"]) for item in board_meta]
    return output_paths, {
        "provider": provider_key,
        "model": visual_model,
        "board_count": len(prompt_specs),
        "boards": board_meta,
        "prompt_chars": sum(len(prompt) for prompt, _spec in prompt_specs),
        "reference_count": sum(int(item.get("reference_count") or 0) for item in board_meta),
        "expected_panels": len(prompt_specs),
    }


def _generate_visual_preview_via_api(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    packet: dict[str, Any],
    *,
    api_route: str = "bandianwa:gpt-image-2",
    expected_request_id: str,
    expected_run_token: str,
) -> tuple[list[str], dict[str, Any]]:
    prompt_specs = build_visual_api_prompts(packet)
    provider_key = _visual_api_provider_from_route(api_route)
    if provider_key not in _VISUAL_API_ADAPTERS:
        raise ValueError(f"Unsupported visual API route: {api_route}")
    visual_model = _visual_api_model_from_route(api_route)
    if visual_model not in _VISUAL_API_MODELS:
        raise ValueError(f"Unsupported visual API model route: {api_route}")
    packet["visual_image_model"] = visual_model
    output_dir = Path(str(packet["browser_output_path"]))
    stage_input = dict(stage_row.input_json or {})
    # Provider progress checkpoints can survive restarts and manual pauses,
    # but their historical stage metadata is not policy authority. Canonicalize
    # before the first nested JSON checkpoint so progress persistence cannot
    # regress a freshly deployed worker to an older self-heal policy.
    stage_input["self_heal_policy_version"] = SELF_HEAL_POLICY_VERSION
    stage_input["hermes_learning_policy_version"] = (
        HERMES_LEARNING_POLICY_VERSION
    )
    api_state = dict(stage_input.get("visual_api") or {})
    base_execution_id = str(
        packet.get("execution_id") or f"stage-{int(stage_row.id)}"
    )
    recovery_epoch = max(0, int(api_state.get("api_recovery_epoch") or 0))
    # The idempotency namespace is immutable inside one recovery epoch, but a
    # model-authorized cooled recovery must not replay a terminal task from a
    # prior epoch forever.  Keep the creative execution identity unchanged in
    # the packet and scope only provider image submissions to the epoch.
    execution_id = (
        f"{base_execution_id}:recovery-e{recovery_epoch}"
        if recovery_epoch
        else base_execution_id
    )
    api_state["expected_reference_count"] = len(prompt_specs)
    preserved_rows = list(packet.get("visual_repair_preserved_references") or [])
    failed_indices = {
        int(value)
        for value in list(packet.get("visual_repair_failed_indices") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    preserved_paths: dict[int, Path] = {}
    if preserved_rows:
        boards_state = dict(api_state.get("boards") or {})
        seeded = 0
        for raw in preserved_rows:
            if not isinstance(raw, dict):
                continue
            try:
                index = int(raw.get("index") or 0)
                asset_id = int(raw.get("asset_id") or 0)
            except (TypeError, ValueError):
                continue
            if index <= 0 or asset_id <= 0 or index in failed_indices:
                continue
            asset = (
                db.query(HermesContentFactoryAsset)
                .filter(
                    HermesContentFactoryAsset.id == asset_id,
                    HermesContentFactoryAsset.project_id == project.id,
                    HermesContentFactoryAsset.workspace_id == project.workspace_id,
                    HermesContentFactoryAsset.stage == "VISUAL_PREVIEW",
                    HermesContentFactoryAsset.kind == "generated_image",
                )
                .one_or_none()
            )
            if (
                asset is None
                or _generated_asset_variant_index(asset)
                != _stage_variant_index(stage_row, project)
                or _visual_asset_reference_index(asset) != index
                or not _asset_file_available(asset)
            ):
                continue
            path = Path(str(asset.file_path))
            preserved_paths[index] = path
            boards_state[str(index)] = {
                **dict(boards_state.get(str(index)) or {}),
                "status": "completed",
                "output_path": str(path),
                "expected_panels": 1,
                "global_start_index": index,
                "global_end_index": index,
                "reference_count": 0,
                "preserved_from_review_stage_id": int(
                    packet.get("visual_repair_source_review_stage_id") or 0
                ),
                "preserved_asset_id": asset_id,
            }
            if index == 1:
                api_state["continuity_anchor_path"] = str(path)
            seeded += 1
        if seeded:
            api_state["boards"] = boards_state
            api_state["preserved_reference_count"] = seeded
            _commit_visual_api_progress(
                db,
                stage_row=stage_row,
                stage_input=stage_input,
                api_state=api_state,
            )
    provider_retry_generation = max(0, int(api_state.get("provider_retry_generation") or 0))
    route_row = _visual_api_route_row(db, api_route)
    key = get_effective_key(
        db,
        key_id=int(route_row.key_id) if route_row is not None else None,
        provider_key=provider_key,
        require_active=True,
    )
    api_key = decrypt_api_key(key.api_key_ciphertext)
    adapter_type = str(
        getattr(route_row, "adapter_type", "") or ""
    ).strip()
    if adapter_type == "sub2api_async_images":
        client: Any = Sub2ApiImageClient(api_key=api_key)
    elif adapter_type == "flow2api_openai_images":
        client = Flow2ApiImageClient(api_key=api_key)
    elif adapter_type == "toapis_async_images":
        client = ToApisVideoClient(api_key=api_key)
    elif adapter_type == "bandianwa_async_images":
        client = BandianwaImageClient(api_key=api_key)
    else:
        raise ValueError(
            f"Unsupported visual API adapter: {adapter_type or 'missing'}"
        )
    if len(prompt_specs) > 1 and all(int(spec.get("count") or 0) == 1 for _prompt, spec in prompt_specs):
        repair_anchor_paths = _repair_continuity_anchor_paths(
            preserved_paths,
            failed_indices,
            preferred_anchor_indices={
                int(value)
                for value in list(
                    packet.get("visual_repair_continuity_anchor_indices")
                    or []
                )
                if str(value).strip().isdigit() and int(value) > 0
            },
        )
        generated_paths, generated_meta = _generate_individual_visual_references_via_api(
            db,
            project=project,
            stage_row=stage_row,
            packet=packet,
            prompt_specs=prompt_specs,
            client=client,
            provider_key=provider_key,
            visual_model=visual_model,
            output_dir=output_dir,
            execution_id=execution_id,
            stage_input=stage_input,
            api_state=api_state,
            provider_retry_generation=provider_retry_generation,
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
            continuity_anchor_paths=repair_anchor_paths or None,
        )
        if not preserved_paths:
            return generated_paths, generated_meta
        generated_boards = list(generated_meta.get("boards") or [])
        generated_indices = {
            int(dict(row).get("board_index") or 0)
            for row in generated_boards
        }
        preserved_boards = [
            {
                "board_index": index,
                "board_count": max(
                    [int(spec.get("board_count") or 0) for _prompt, spec in prompt_specs]
                    + [max(preserved_paths)],
                ),
                "output_path": str(path),
                "task_id": "",
                "expected_panels": 1,
                "global_start_index": index,
                "global_end_index": index,
                "reference_count": 0,
                "preserved_from_review_stage_id": int(
                    packet.get("visual_repair_source_review_stage_id") or 0
                ),
            }
            for index, path in preserved_paths.items()
            if index not in generated_indices
        ]
        merged_boards = sorted(
            generated_boards + preserved_boards,
            key=lambda item: int(dict(item).get("board_index") or 0),
        )
        return [str(dict(item).get("output_path") or "") for item in merged_boards], {
            **generated_meta,
            "board_count": len(merged_boards),
            "boards": merged_boards,
            "expected_panels": len(merged_boards),
            "preserved_reference_count": len(preserved_boards),
        }
    boards_state = dict(api_state.get("boards") or {})
    repair_anchor_paths = _repair_continuity_anchor_paths(
        preserved_paths,
        failed_indices,
        preferred_anchor_indices={
            int(value)
            for value in list(
                packet.get("visual_repair_continuity_anchor_indices") or []
            )
            if str(value).strip().isdigit() and int(value) > 0
        },
    )
    output_paths: list[str] = []
    board_meta: list[dict[str, Any]] = []
    for base_prompt, spec in prompt_specs:
        _assert_visual_provider_submission_current(
            db,
            project_id=int(project.id),
            stage_id=int(stage_row.id),
            stage_name=str(stage_row.stage),
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
        )
        board_index = int(spec["board_index"])
        board_key = str(board_index)
        prompt = base_prompt
        if provider_retry_generation:
            prompt += (
                "\nPROVIDER RETRY: Render a fresh board in the same required project style. Keep every requested beat, "
                "simplify poses and backgrounds, use no text, and do not reuse the prior failed composition. "
                f"Retry generation {provider_retry_generation}."
            )
        prompt_digest = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
        digest = hashlib.sha256(
            f"{execution_id}:b{board_index}:{visual_model}:{prompt_digest}:r{provider_retry_generation}".encode("utf-8")
        ).hexdigest()[:16]
        output_path = output_dir / f"visual-preview-api-board-{board_index:02d}-{digest}.png"
        board_state = dict(boards_state.get(board_key) or {})
        reference_paths = visual_generation_reference_paths(packet, plan=list(spec["plan"]))
        images = [
            image_file_data_url(path)
            for path in reference_paths
            if Path(str(path)).is_file()
        ]
        # Every sparse repair needs the nearest accepted frame as a cast/style
        # anchor. A shared board keeps its own replacement cells consistent,
        # but without an accepted input it can redraw the same wrong identity
        # across all of them.
        repair_anchor = _repair_continuity_anchor_for_spec(
            spec,
            repair_anchor_paths,
        )
        if (
            repair_anchor is not None
            and repair_anchor.is_file()
        ):
            images = [image_file_data_url(str(repair_anchor))] + images
            prompt += _visual_continuity_reference_instruction()
        if output_path.is_file() and output_path.stat().st_size > 0:
            output_paths.append(str(output_path))
            board_meta.append({
                "board_index": board_index,
                "board_count": int(spec["board_count"]),
                "output_path": str(output_path),
                "expected_panels": int(spec["count"]),
                "global_start_index": int(spec["global_start_index"]),
                "global_end_index": int(spec["global_end_index"]),
                "reference_count": len(images),
                "recovered_existing_file": True,
            })
            continue
        if board_state.get("prompt_digest") != prompt_digest:
            board_state = {"prompt_digest": prompt_digest}
        task_id = str(board_state.get("task_id") or "").strip() or None
        try:
            response: dict[str, Any]
            if task_id:
                response = asyncio.run(client.get_image_task(task_id=task_id))
            else:
                _assert_visual_provider_submission_current(
                    db,
                    project_id=int(project.id),
                    stage_id=int(stage_row.id),
                    stage_name=str(stage_row.stage),
                    expected_request_id=expected_request_id,
                    expected_run_token=expected_run_token,
                )
                response = asyncio.run(
                    client.create_image_task(
                        prompt=prompt,
                        size=str(spec["size"]),
                        model=visual_model,
                        images=images,
                        idempotency_key=(
                            f"{execution_id}:board-{board_index}:{visual_model}:{prompt_digest[:16]}:r{provider_retry_generation}"
                        ),
                    )
                )
                immediate_content = asyncio.run(
                    _bandianwa_image_bytes(client, response, task_id=None)
                )
                if immediate_content is not None:
                    # Flow2API image generation is synchronous. Persist the
                    # Persist the image immediately and retain only the
                    # provider result id as audit evidence; polling that
                    # synthetic id through the OpenAI async endpoint would
                    # otherwise turn a successful render into a false 404.
                    _assert_visual_provider_submission_current(
                        db,
                        project_id=int(project.id),
                        stage_id=int(stage_row.id),
                        stage_name=str(stage_row.stage),
                        expected_request_id=expected_request_id,
                        expected_run_token=expected_run_token,
                    )
                    _save_generated_image(output_path, immediate_content)
                    provider_result_id = extract_bandianwa_task_id(response)
                    board_state.update({
                        "task_id": None,
                        "provider_result_id": provider_result_id,
                        "status": "completed",
                        "completed_at": _stage_now().isoformat(),
                        "output_path": str(output_path),
                        "prompt_chars": len(prompt),
                        "size": str(spec["size"]),
                        "expected_panels": int(spec["count"]),
                        "global_start_index": int(spec["global_start_index"]),
                        "global_end_index": int(spec["global_end_index"]),
                        "global_reference_indices": list(
                            spec.get("global_reference_indices") or []
                        ),
                        "provider_transport_retry_count": 0,
                    })
                    boards_state[board_key] = board_state
                    output_paths.append(str(output_path))
                    board_meta.append({
                        "board_index": board_index,
                        "board_count": int(spec["board_count"]),
                        "output_path": str(output_path),
                        "task_id": provider_result_id,
                        "expected_panels": int(spec["count"]),
                        "global_start_index": int(spec["global_start_index"]),
                        "global_end_index": int(spec["global_end_index"]),
                        "global_reference_indices": list(
                            spec.get("global_reference_indices") or []
                        ),
                        "size": str(spec["size"]),
                        "reference_count": len(images),
                    })
                    api_state.update({
                        "provider": provider_key,
                        "model": visual_model,
                        "execution_id": execution_id,
                        "provider_retry_generation": provider_retry_generation,
                        "status": (
                            "running"
                            if board_index < len(prompt_specs)
                            else "completed"
                        ),
                        "completed_at": (
                            _stage_now().isoformat()
                            if board_index == len(prompt_specs)
                            else None
                        ),
                        "reference_count": len(images),
                        "board_count": len(prompt_specs),
                        "boards": boards_state,
                    })
                    _commit_visual_api_progress(
                        db,
                        stage_row=stage_row,
                        stage_input=stage_input,
                        api_state=api_state,
                    )
                    continue
                task_id = extract_bandianwa_task_id(response)
                board_state.update({
                    "task_id": task_id,
                    "status": extract_bandianwa_status(response) or "submitted",
                    "submitted_at": _stage_now().isoformat(),
                    "prompt_chars": len(prompt),
                    "size": spec["size"],
                    "expected_panels": int(spec["count"]),
                    "global_start_index": int(spec["global_start_index"]),
                    "global_end_index": int(spec["global_end_index"]),
                    "global_reference_indices": list(
                        spec.get("global_reference_indices") or []
                    ),
                })
                boards_state[board_key] = board_state
                api_state.update({
                    "provider": provider_key,
                    "model": visual_model,
                    "execution_id": execution_id,
                    "provider_retry_generation": provider_retry_generation,
                    "status": "submitted",
                    "reference_count": len(images),
                    "board_count": len(prompt_specs),
                    "boards": boards_state,
                })
                stage_input["visual_api"] = api_state
                stage_row.input_json = stage_input
                db.commit()
            content = asyncio.run(_bandianwa_image_bytes(client, response, task_id=task_id))
            deadline = time.monotonic() + 720
            while content is None and task_id and time.monotonic() < deadline:
                time.sleep(5)
                response = asyncio.run(client.get_image_task(task_id=task_id))
                content = asyncio.run(_bandianwa_image_bytes(client, response, task_id=task_id))
        except (
            BandianwaApiError,
            Flow2ApiError,
            Sub2ApiApiError,
            ToApisApiError,
        ) as exc:
            failed_input = dict(stage_row.input_json or {})
            failed_state = dict(failed_input.get("visual_api") or api_state)
            failed_boards = dict(failed_state.get("boards") or boards_state)
            failed_board = dict(failed_boards.get(board_key) or board_state)
            preserve_task = _visual_provider_task_reusable_after_error(
                task_id,
                str(exc),
            )
            transport_count = int(
                failed_board.get("provider_transport_retry_count") or 0
            ) + (1 if preserve_task else 0)
            failed_board.update({
                "status": "poll_retrying" if preserve_task else "failed",
                "task_id": task_id if preserve_task else None,
                "last_failed_task_id": task_id,
                "last_error": str(exc)[:800],
                "failed_at": _stage_now().isoformat(),
                "provider_transport_retry_count": transport_count,
            })
            failed_boards[board_key] = failed_board
            failed_state.update({
                "status": "poll_retrying" if preserve_task else "failed",
                "task_id": task_id if preserve_task else None,
                "boards": failed_boards,
                "last_failed_board_index": board_index,
                "last_error": str(exc)[:800],
                "failed_at": _stage_now().isoformat(),
                "provider_retry_generation": (
                    provider_retry_generation
                    if preserve_task
                    else provider_retry_generation + 1
                ),
                "provider_transport_retry_count": max(
                    int(failed_state.get("provider_transport_retry_count") or 0),
                    transport_count,
                ),
            })
            failed_input["visual_api"] = failed_state
            stage_row.input_json = failed_input
            db.commit()
            raise
        if content is None:
            raise BandianwaApiError(
                f"{provider_key} image board {board_index} did not complete before timeout: "
                f"{task_id or 'no task id'}"
            )
        _assert_visual_provider_submission_current(
            db,
            project_id=int(project.id),
            stage_id=int(stage_row.id),
            stage_name=str(stage_row.stage),
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
        )
        _save_generated_image(output_path, content)
        board_state.update({
            "status": "completed",
            "completed_at": _stage_now().isoformat(),
            "output_path": str(output_path),
            "task_id": task_id,
            "provider_transport_retry_count": 0,
        })
        boards_state[board_key] = board_state
        output_paths.append(str(output_path))
        board_meta.append({
            "board_index": board_index,
            "board_count": int(spec["board_count"]),
            "output_path": str(output_path),
            "task_id": task_id,
            "expected_panels": int(spec["count"]),
            "global_start_index": int(spec["global_start_index"]),
            "global_end_index": int(spec["global_end_index"]),
            "global_reference_indices": list(
                spec.get("global_reference_indices") or []
            ),
            "size": spec["size"],
            "reference_count": len(images),
        })
        api_state.update({
            "status": "running" if board_index < len(prompt_specs) else "completed",
            "completed_at": _stage_now().isoformat() if board_index == len(prompt_specs) else None,
            "boards": boards_state,
            "board_count": len(prompt_specs),
            "provider_retry_generation": provider_retry_generation,
        })
        stage_input["visual_api"] = api_state
        stage_row.input_json = stage_input
        db.commit()
    generated_meta = {
        "provider": provider_key,
        "model": visual_model,
        "board_count": len(prompt_specs),
        "boards": board_meta,
        "prompt_chars": sum(len(prompt) for prompt, _spec in prompt_specs),
        "reference_count": sum(int(item.get("reference_count") or 0) for item in board_meta),
        "expected_panels": sum(int(spec["count"]) for _prompt, spec in prompt_specs),
    }
    # A sparse repair may contain only one failed row.  That case does not use
    # the multi-prompt native-reference helper above, but its successful stage
    # evidence must still describe the complete approved set: the regenerated
    # row plus every preserved sibling.  Returning only the new row makes
    # CREATIVE_REVIEW see five images through the repair packet while
    # FINAL_ASSETS sees one file through stage evidence and rejects the same
    # approved set as incomplete.
    if preserved_paths:
        generated_indices = {
            int(dict(row).get("board_index") or 0)
            for row in board_meta
        }
        preserved_boards = [
            {
                "board_index": index,
                "board_count": max(
                    [int(spec.get("board_count") or 0) for _prompt, spec in prompt_specs]
                    + [max(preserved_paths)],
                ),
                "output_path": str(path),
                "task_id": "",
                "expected_panels": 1,
                "global_start_index": index,
                "global_end_index": index,
                "reference_count": 0,
                "preserved_from_review_stage_id": int(
                    packet.get("visual_repair_source_review_stage_id") or 0
                ),
            }
            for index, path in preserved_paths.items()
            if index not in generated_indices
        ]
        merged_boards = sorted(
            board_meta + preserved_boards,
            key=lambda item: int(dict(item).get("board_index") or 0),
        )
        return [str(dict(item).get("output_path") or "") for item in merged_boards], {
            **generated_meta,
            "board_count": len(merged_boards),
            "boards": merged_boards,
            "expected_panels": len(merged_boards),
            "preserved_reference_count": len(preserved_boards),
        }
    return output_paths, generated_meta


def _generate_visual_preview_with_failover(
    db,
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
    packet: dict[str, Any],
    *,
    api_route: str,
    expected_request_id: str,
    expected_run_token: str,
) -> tuple[list[str], dict[str, Any]]:
    """Try one route and atomically follow the admin-prioritized API chain.

    A provider keeps its own bounded retry budget. Explicit quota exhaustion or
    a spent provider budget records that provider as failed, preserves completed
    boards, and selects the next enabled verified route. Browser fallback stays
    unreachable until this function has no API route left.
    """
    route_attempt_id, route_started = _begin_visual_api_route_attempt(
        db,
        project=project,
        stage_row=stage_row,
        api_route=api_route,
    )
    try:
        generated = _generate_visual_preview_via_api(
            db,
            project,
            stage_row,
            packet,
            api_route=api_route,
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
        )
        _finish_visual_api_route_attempt(
            db,
            route_attempt_id,
            route_started,
            error=None,
        )
    except Exception as exc:  # noqa: BLE001
        _finish_visual_api_route_attempt(
            db,
            route_attempt_id,
            route_started,
            error=exc,
        )
        quota_exhausted = _visual_api_account_quota_exhausted(
            stage_row.stage,
            str(exc),
        )
        retry_budget_exhausted = _visual_api_provider_budget_exhausted(
            stage_row.stage,
            dict(stage_row.input_json or {}),
        )
        submission_transport_exhausted = (
            _visual_api_submission_transport_budget_exhausted(
                stage_row.stage,
                dict(stage_row.input_json or {}),
            )
        )
        if not (
            quota_exhausted
            or retry_budget_exhausted
            or submission_transport_exhausted
        ):
            raise
        current_provider = _visual_api_provider_from_route(api_route)
        if not current_provider:
            raise
        failed_input = dict(stage_row.input_json or {})
        failed_state = dict(failed_input.get("visual_api") or {})
        failures = dict(failed_state.get("provider_failures") or {})
        failures[current_provider] = {
            "account_quota_exhausted": bool(quota_exhausted),
            "retry_budget_exhausted": bool(retry_budget_exhausted),
            "submission_transport_exhausted": bool(
                submission_transport_exhausted
            ),
            "error": str(exc)[:800],
            "failed_at": _stage_now().isoformat(),
        }
        failed_state["provider_failures"] = failures
        route_failures = dict(failed_state.get("route_failures") or {})
        route_failures[str(api_route).strip().lower()] = {
            "account_quota_exhausted": bool(quota_exhausted),
            "retry_budget_exhausted": bool(retry_budget_exhausted),
            "submission_transport_exhausted": bool(
                submission_transport_exhausted
            ),
            "error": str(exc)[:800],
            "failed_at": _stage_now().isoformat(),
        }
        failed_state["route_failures"] = route_failures
        failed_input["visual_api"] = failed_state
        next_route = _next_visual_api_route(
            db,
            current_route=api_route,
            stage_input=failed_input,
        )
        if not next_route:
            failed_state["all_providers_exhausted"] = True
            failed_state["all_providers_exhausted_at"] = (
                _stage_now().isoformat()
            )
            failed_input["visual_api"] = failed_state
            stage_row.input_json = failed_input
            db.commit()
            raise
        next_provider = _visual_api_provider_from_route(next_route)
        failover_input = _prepare_visual_api_provider_failover(
            failed_input,
            from_provider=current_provider,
            to_provider=next_provider,
            error=str(exc),
            account_quota_exhausted=quota_exhausted,
            from_route=api_route,
            to_route=next_route,
        )
        stage_row.input_json = failover_input
        db.commit()
        # Re-enter the same bounded decision layer. This matters for an
        # immediate balance rejection: it must continue to the third API route
        # rather than escaping to browser after only two providers.
        generated = _generate_visual_preview_with_failover(
            db,
            project,
            stage_row,
            packet,
            api_route=next_route,
            expected_request_id=expected_request_id,
            expected_run_token=expected_run_token,
        )
    # The provider output is the final generated scene reference.  The
    # uploaded product image has already been supplied to product-visible
    # requests as identity authority; never paste its pixels over this scene.
    return generated


def _refresh_profile_director_brief_from_facts(
    project: HermesContentFactoryProject,
    *,
    product_truth: dict[str, Any],
) -> bool:
    """Replace the provisional brief with normalized FACTS-stage truth.

    Legacy ``product_brief`` text often mixes product facts with a campaign
    mother template. The universal Director receives the normalized FACTS
    envelope plus explicit project settings, never that mixed legacy text.
    """
    from app.services.hermes_agent.content_director_profile import (
        refresh_project_director_brief_from_facts,
    )

    return refresh_project_director_brief_from_facts(
        project,
        product_truth=product_truth,
    )


def _series_director_stage_configuration(
    db,
    project: HermesContentFactoryProject,
):
    """Load the explicit project-owned whole-series contract."""
    from app.services.hermes_agent.content_capabilities import (
        validate_brief_capabilities_against_registry,
    )
    from app.services.hermes_agent.content_director import DirectorSeriesBrief
    from app.services.hermes_agent.content_director_runtime import (
        DirectorLoopPolicy,
    )
    from app.services.hermes_agent.content_director_profile import (
        default_director_loop_policy,
    )

    config = dict(project.config_json or {})
    if (
        str(config.get("director_series_brief_source") or "").strip()
        == "universal_profile"
    ):
        state = dict(project.state_json or {})
        if _refresh_profile_director_brief_from_facts(
            project,
            product_truth=dict(state.get("product_knowledge") or {}),
        ):
            # Persist the profile-derived contract before any remote Director
            # request so retries never replay an older impossible schema.
            db.add(project)
            db.commit()
            config = dict(project.config_json or {})
    mode = str(config.get("content_director_mode") or "").strip().lower()
    if mode != "enforce":
        raise ValueError(
            "SERIES_DIRECTOR_MODE_INVALID: formal series planning requires "
            "content_director_mode=enforce"
        )
    raw_brief = config.get("director_series_brief")
    if not isinstance(raw_brief, dict):
        raise ValueError(
            "SERIES_DIRECTOR_BRIEF_MISSING: director_series_brief is not "
            "configured"
        )
    raw_policy = config.get("director_loop_policy")
    if not isinstance(raw_policy, dict):
        raise ValueError(
            "DIRECTOR_LOOP_POLICY_MISSING: the project must explicitly bound "
            "revisions and contract repairs"
        )

    brief = DirectorSeriesBrief.model_validate(raw_brief)
    benchmark_evidence = _benchmark_visual_director_evidence(project)
    if benchmark_evidence:
        truth_payload = dict(brief.truth_payload or {})
        truth_payload["benchmark_visual_evidence"] = benchmark_evidence
        brief = brief.model_copy(update={
            "truth_payload": truth_payload,
            "creative_constraints": list(dict.fromkeys([
                *list(brief.creative_constraints),
                (
                    "Use benchmark_visual_evidence as pixel-grounded authority "
                    "for the explicitly requested abstract hook force, ordered "
                    "visual escalation, pacing, and conversion timing. Never "
                    "flatten a multi-state opening into one calm generic frame; "
                    "never copy source-specific actors, props, UI, captions, "
                    "watermarks, wording, or items under must_not_copy."
                ),
            ]))[:128],
        })
    # Add newly introduced, role-specific bounds without overwriting any
    # project-owned choices. This lets existing projects inherit a separate
    # series-planning budget while their copy revision budget stays unchanged.
    policy = DirectorLoopPolicy.model_validate({
        **default_director_loop_policy(
            target_count=int(config.get("video_count") or 1),
            has_reference_transfer=bool(
                dict(config.get("producer_intent_spec") or {})
                .get("intent_manifest", {})
                .get("transformation_contract")
            ),
            has_locked_script=bool(
                dict(config.get("creative_copy_contract") or {})
                .get("required_verbatim_voiceovers")
            ),
            product_required=bool(project.product_id),
        ),
        **raw_policy,
    })
    if brief.locale != _configured_video_language(project):
        raise ValueError(
            "SERIES_DIRECTOR_LOCALE_MISMATCH: brief locale must match the "
            "project video language"
        )
    config_count = max(1, int(config.get("video_count") or 1))
    if brief.target_count != config_count:
        raise ValueError(
            "SERIES_DIRECTOR_COUNT_MISMATCH: target_count must match the "
            "project video_count"
        )
    copy_contract = dict(config.get("creative_copy_contract") or {})
    if (
        _deliverable_copy_is_user_verbatim(config)
        and str(copy_contract.get("script_reuse_mode") or "")
        == "distinct_per_deliverable"
    ):
        locked_deliverables = [
            dict(item)
            for item in list(
                copy_contract.get("required_verbatim_voiceovers") or []
            )
            if isinstance(item, dict)
        ]
        locked_ordinals = [
            int(item.get("deliverable_ordinal") or 0)
            for item in locked_deliverables
        ]
        if locked_ordinals != list(range(1, config_count + 1)):
            raise ValueError(
                "SERIES_DIRECTOR_DELIVERABLE_SCRIPT_MISMATCH: distinct "
                "locked scripts must map exactly to every requested output"
            )
        for item in locked_deliverables:
            script_text = str(item.get("text") or "").strip()
            expected_sha = str(item.get("sha256") or "").strip()
            actual_sha = hashlib.sha256(script_text.encode("utf-8")).hexdigest()
            if not script_text or expected_sha != actual_sha:
                raise ValueError(
                    "SERIES_DIRECTOR_DELIVERABLE_SCRIPT_INTEGRITY: every "
                    "locked deliverable script must be present and hash-bound"
                )
    completed_indices = sorted(
        _completed_video_assets_by_index(db, project)
    )
    planned_variant_indices = [
        index
        for index in range(1, config_count + 1)
        if index not in set(completed_indices)
    ]
    completed_history = _completed_series_content_history(
        db,
        project,
        completed_indices=completed_indices,
    )
    if planned_variant_indices:
        continuation_truth = dict(brief.truth_payload or {})
        continuation_truth["completed_content_history"] = completed_history
        continuation_truth["continuation_plan"] = {
            "total_target_count": config_count,
            "completed_variant_indices": completed_indices,
            "planned_variant_indices": planned_variant_indices,
            "planning_ordinal_to_variant_index": {
                str(ordinal): actual_index
                for ordinal, actual_index in enumerate(
                    planned_variant_indices,
                    1,
                )
            },
        }
        remaining_count = len(planned_variant_indices)
        brief = brief.model_copy(update={
            "target_count": remaining_count,
            "truth_payload": continuation_truth,
            "diversity_requirements": [
                requirement.model_copy(update={
                    "minimum_unique_values": min(
                        int(requirement.minimum_unique_values),
                        remaining_count,
                    ),
                })
                for requirement in brief.diversity_requirements
            ],
        })
    validate_brief_capabilities_against_registry(brief)
    duration_range = _configured_video_duration_range(project)
    duration_min = duration_range["min"]
    duration_max = duration_range["max"]
    if (
        brief.minimum_duration_seconds < duration_min
        or brief.maximum_duration_seconds > duration_max
    ):
        raise ValueError(
            "SERIES_DIRECTOR_DURATION_MISMATCH: brief duration range must "
            "stay inside the project duration range"
        )
    product_required = bool(config.get("product_required", True))
    if brief.conversion.product_required != product_required:
        raise ValueError(
            "SERIES_DIRECTOR_PRODUCT_MODE_MISMATCH: brief conversion mode "
            "does not match the project"
        )
    if product_required:
        configured_product = str(project.product_name or "").strip().casefold()
        brief_product = str(
            brief.conversion.product_name or ""
        ).strip().casefold()
        if configured_product and configured_product not in brief_product:
            raise ValueError(
                "SERIES_DIRECTOR_PRODUCT_IDENTITY_MISMATCH: conversion "
                "product does not match the project product"
            )
    history_sha256 = hashlib.sha256(
        json.dumps(
            completed_history,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    return (
        brief,
        policy,
        planned_variant_indices,
        history_sha256,
    )


def _locked_script_segment_units(
    script_text: str,
    *,
    segment_durations: list[float],
    baseline_rate_wpm: float,
    maximum_rate_wpm: float,
) -> tuple[float, list[str], list[int], list[dict[str, Any]]] | None:
    """Compile immutable narration into lossless provider splice units.

    Provider clips are transport containers, not independent copywriting
    prompts.  A simple even word split used to strand prepositions such as
    ``from`` or ``to`` at the end of a clip, after which the deterministic
    gate correctly rejected an allocation that the model was not allowed to
    rewrite.  Choose every cut with a deterministic boundary score instead:
    complete sentences first, then operator-authored line breaks, then clause
    punctuation, and only then ordinary whitespace.  The words and order are
    never changed.
    """

    matches = list(
        re.finditer(
            r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)?|[\u3400-\u9fff]",
            str(script_text or ""),
        )
    )
    if not matches or not segment_durations:
        return None
    total_words = len(matches)
    total_seconds = sum(float(value) for value in segment_durations)
    first_rate = max(
        int(math.ceil(float(baseline_rate_wpm))),
        int(math.ceil(total_words * 60.0 / max(0.5, total_seconds))),
    )
    for rate in range(first_rate, int(math.floor(maximum_rate_wpm)) + 1):
        if int(total_seconds * rate / 60.0) < total_words:
            continue
        capacities: list[int] = []
        for duration in segment_durations:
            target = int(float(duration) * rate / 60.0)
            capacities.append(target + max(1, int(math.floor(target * 0.05))))
        if sum(capacities) < total_words:
            continue
        dangling_tokens = {
            "a", "an", "and", "as", "at", "because", "but", "by",
            "for", "from", "if", "in", "no", "of", "on", "only", "or",
            "one", "so", "than", "that", "the", "then", "to", "when",
            "while", "who", "which", "with", "your",
        }

        def boundary_score(word_index: int) -> tuple[float, str]:
            if word_index >= total_words:
                return 0.0, "complete_script"
            prior_end = matches[word_index - 1].end()
            next_start = matches[word_index].start()
            gap = script_text[prior_end:next_start]
            boundary_text = script_text[:next_start].rstrip()
            if re.search(r"[.!?。！？][\"')\]]*$", boundary_text):
                score, kind = 0.0, "sentence"
            elif "\n" in gap:
                score, kind = 6.0, "authored_line"
            elif re.search(
                r"[,;:，；：—–-][\"')\]]*$",
                boundary_text,
            ):
                score, kind = 10.0, "clause"
            else:
                score, kind = 28.0, "word"
            if matches[word_index - 1].group(0).casefold() in dangling_tokens:
                score += 45.0
                kind = f"dangling_{kind}"
            return score, kind

        paths: dict[int, tuple[float, list[int], list[str]]] = {
            0: (0.0, [], [])
        }
        for segment_position, capacity in enumerate(capacities, 1):
            remaining_segments = len(capacities) - segment_position
            next_paths: dict[
                int,
                tuple[float, list[int], list[str]],
            ] = {}
            for start, (cost, cuts, kinds) in paths.items():
                maximum_end = min(
                    total_words - remaining_segments,
                    start + capacity,
                )
                if maximum_end <= start:
                    continue
                ideal_end = start + min(
                    capacity,
                    int(round(
                        (total_words - start)
                        / (remaining_segments + 1)
                    )),
                )
                for end in range(start + 1, maximum_end + 1):
                    boundary_cost, boundary_kind = boundary_score(end)
                    candidate_cost = (
                        cost
                        + boundary_cost
                        + abs(end - ideal_end) * 0.1
                    )
                    prior = next_paths.get(end)
                    if prior is None or candidate_cost < prior[0]:
                        next_paths[end] = (
                            candidate_cost,
                            [*cuts, end],
                            [*kinds, boundary_kind],
                        )
            paths = next_paths
        selected_path = paths.get(total_words)
        if selected_path is None:
            continue
        _, cuts, boundary_kinds = selected_path
        units: list[str] = []
        cursor_word = 0
        cursor_char = 0
        boundaries: list[dict[str, Any]] = []
        feasible = True
        for segment_index, (end_word, boundary_kind) in enumerate(
            zip(cuts, boundary_kinds, strict=True),
            1,
        ):
            end_char = (
                matches[end_word].start()
                if end_word < total_words
                else len(script_text)
            )
            unit = re.sub(
                r"\s+",
                " ",
                script_text[cursor_char:end_char],
            ).strip()
            if not unit:
                feasible = False
                break
            units.append(unit)
            boundaries.append({
                "segment_index": segment_index,
                "word_end_index": end_word,
                "boundary_kind": boundary_kind,
                "terminal_token": matches[end_word - 1].group(0),
            })
            cursor_word = end_word
            cursor_char = end_char
        if not feasible:
            continue
        if re.sub(r"\s+", " ", " ".join(units)).strip() != re.sub(
            r"\s+", " ", script_text
        ).strip():
            continue
        return (
            float(rate),
            units,
            list(range(1, len(units) + 1)),
            boundaries,
        )
    return None


def _apply_locked_deliverable_script_to_director_brief(
    generated_brief: dict[str, Any],
    *,
    locked_deliverable: dict[str, Any],
    deliverable_ordinal: int,
    minimum_duration_seconds: int | None = None,
    maximum_duration_seconds: int | None = None,
    baseline_speech_rate_wpm: float | None = None,
    maximum_speech_rate_wpm: float | None = None,
) -> dict[str, Any]:
    """Bind one confirmed script to exactly one materialized Director brief."""
    from app.services.hermes_agent.content_director import (
        VideoProductionContract,
        production_segment_durations,
    )

    generated = dict(generated_brief)
    truth_payload = dict(generated.get("truth_payload") or {})
    script_text = str(locked_deliverable.get("text") or "").strip()
    script_sha256 = hashlib.sha256(script_text.encode("utf-8")).hexdigest()
    if not script_text or script_sha256 != str(
        locked_deliverable.get("sha256") or ""
    ):
        raise ValueError(
            "SERIES_DIRECTOR_DELIVERABLE_SCRIPT_INTEGRITY: selected "
            f"deliverable {deliverable_ordinal} changed after confirmation"
        )
    word_count = len(
        re.findall(
            r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)?|[\u3400-\u9fff]",
            script_text,
        )
    )
    contract_payload = generated.get("production_contract")
    contract = (
        VideoProductionContract.model_validate(contract_payload)
        if isinstance(contract_payload, dict) and contract_payload
        else None
    )
    requested_target = (
        locked_deliverable.get("requested_target_duration_seconds")
        if locked_deliverable.get("requested_target_duration_seconds") is not None
        else locked_deliverable.get("target_duration_seconds")
    )
    try:
        requested_value = float(requested_target)
    except (TypeError, ValueError):
        requested_value = float(generated.get("target_duration_seconds") or 0.0)
    lower = int(
        minimum_duration_seconds
        if minimum_duration_seconds is not None
        else math.floor(min(requested_value, float(generated.get("target_duration_seconds") or requested_value)))
    )
    upper = int(
        maximum_duration_seconds
        if maximum_duration_seconds is not None
        else math.ceil(max(requested_value, float(generated.get("target_duration_seconds") or requested_value)))
    )
    baseline_rate = float(
        baseline_speech_rate_wpm
        if baseline_speech_rate_wpm is not None
        else generated.get("speech_rate_wpm") or 145.0
    )
    maximum_rate = float(
        maximum_speech_rate_wpm
        if maximum_speech_rate_wpm is not None
        else 220.0
    )
    legal_candidates: list[tuple[float, list[float]]] = []
    if contract is None:
        fallback_duration = max(float(lower), min(float(upper), requested_value))
        legal_candidates.append((fallback_duration, [fallback_duration]))
    else:
        for duration in range(max(1, lower), max(1, upper) + 1):
            try:
                segment_durations = production_segment_durations(
                    contract,
                    float(duration),
                )
            except (TypeError, ValueError):
                continue
            legal_candidates.append((float(duration), segment_durations))
    legal_candidates.sort(
        key=lambda item: (
            abs(item[0] - requested_value),
            0 if item[0] >= requested_value else 1,
            item[0],
        )
    )
    selected: tuple[
        float,
        float,
        list[int],
        list[float],
        list[str],
    ] | None = None
    for duration, segment_durations in legal_candidates:
        if contract is None:
            from app.services.hermes_agent.content_director_profile import (
                _locked_voiceover_blocks,
            )

            fallback_blocks = _locked_voiceover_blocks(script_text)
            fallback_rate = max(
                int(math.ceil(baseline_rate)),
                int(math.ceil(word_count * 60.0 / max(0.5, duration))),
            )
            if fallback_rate <= maximum_rate:
                selected = (
                    duration,
                    float(fallback_rate),
                    [1] * len(fallback_blocks),
                    list(segment_durations),
                    fallback_blocks,
                )
                break
        feasible = _locked_script_segment_units(
            script_text,
            segment_durations=segment_durations,
            baseline_rate_wpm=baseline_rate,
            maximum_rate_wpm=maximum_rate,
        )
        if feasible is not None:
            selected = (
                duration,
                float(feasible[0]),
                list(feasible[2]),
                list(segment_durations),
                list(feasible[1]),
            )
            compiled_boundaries = list(feasible[3])
            break
    if selected is None:
        raise ValueError(
            "DIRECTOR_DELIVERABLE_SCRIPT_SEGMENT_BUDGET_EXCEEDED: "
            f"deliverable {deliverable_ordinal} has {word_count} words and "
            f"cannot fit a provider-supported duration from {lower} to "
            f"{upper} seconds at or below {maximum_rate:g} WPM"
        )
    (
        selected_duration,
        selected_rate,
        allocation,
        segment_durations,
        blocks,
    ) = selected
    generated["target_duration_seconds"] = selected_duration
    generated["edit_headroom_seconds"] = 0.0
    generated["speech_rate_wpm"] = selected_rate
    truth_payload["requested_target_duration_seconds"] = requested_value
    truth_payload["normalized_target_duration_seconds"] = selected_duration
    truth_payload["locked_voiceover_feasible_allocation"] = {
        "speech_rate_wpm": selected_rate,
        "segment_indices": allocation,
        "segment_durations_seconds": segment_durations,
        "authority": "runtime_verified_reference_for_director",
    }
    truth_payload["locked_voiceover_segment_boundary_policy"] = {
        "mode": "runtime_compiled_continuation",
        "authority": "runtime_lossless_compiler",
        "segment_boundaries": (
            compiled_boundaries
            if contract is not None
            else []
        ),
        "instruction": (
            "Treat adjacent provider clips as one continuous narration. "
            "Internal line endings are immutable splice coordinates, not "
            "standalone sentence endings; do not rewrite or add words."
        ),
    }
    truth_payload.update({
        "required_verbatim_voiceover": script_text,
        "required_verbatim_voiceover_lines": [
            {
                "line_id": f"LOCKED-VO-{index:03d}",
                "delivery_mode": "spoken",
                "text": block,
            }
            for index, block in enumerate(blocks, 1)
        ],
        "locked_script_variant_policy": {
            "mode": "distinct_copy_per_deliverable",
            "copy_reuse_required": False,
            "semantic_copy_diversity_required": True,
            "visual_execution_diversity_required": True,
            "deliverable_ordinal": deliverable_ordinal,
            "script_sha256": script_sha256,
        },
        "deliverable_requirements": {
            "label": str(locked_deliverable.get("label") or "")[:255],
            "objective": str(locked_deliverable.get("objective") or "")[:1000],
            "must_preserve": list(
                locked_deliverable.get("must_preserve") or []
            )[:32],
            "differentiation": list(
                locked_deliverable.get("differentiation") or []
            )[:32],
        },
    })
    generated["audio_mode_hint"] = "spoken"
    generated["truth_payload"] = truth_payload
    return generated


def _deliverable_copy_is_user_verbatim(
    config: dict[str, Any],
) -> bool:
    """Return whether per-deliverable scripts carry user verbatim authority.

    Legacy projects did not persist ``copy_authority``.  They remain safely
    recognizable only when the Producer classified a real multi-script
    package and every script row cites the user message that supplied it.
    Requirements-mode scripts with no source coordinates are AI planning
    drafts and must remain editable by the Director/Critic loop.
    """

    contract = dict(config.get("creative_copy_contract") or {})
    authority = str(contract.get("copy_authority") or "").strip().lower()
    if authority:
        return authority == "user_verbatim"
    intent = dict(config.get("producer_intent_spec") or {})
    if str(intent.get("source_material_mode") or "").strip() != (
        "multi_script_package"
    ):
        return False
    rows = [
        dict(item)
        for item in list(intent.get("deliverables") or [])
        if isinstance(item, dict) and str(item.get("script_text") or "").strip()
    ]
    return bool(rows) and all(
        int(item.get("source_message_id") or 0) > 0 for item in rows
    )


def _editable_seed_deliverables(
    config: dict[str, Any],
) -> list[dict[str, Any]]:
    contract = dict(config.get("creative_copy_contract") or {})
    explicit = [
        dict(item)
        for item in list(contract.get("director_seed_voiceovers") or [])
        if isinstance(item, dict)
    ]
    if explicit:
        return explicit
    if _deliverable_copy_is_user_verbatim(config):
        return []
    return [
        dict(item)
        for item in list(contract.get("required_verbatim_voiceovers") or [])
        if isinstance(item, dict)
    ]


def _sanitize_editable_director_brief(
    raw_brief: dict[str, Any],
    *,
    seed_deliverable: dict[str, Any] | None,
) -> dict[str, Any]:
    """Remove a stale verbatim lock while preserving its editable seed.

    This is deliberately an authority migration, not a prose rewrite.  The
    multimodal Director still decides the final audience copy and the Critic
    still reviews it; the runtime merely stops restoring an AI-authored first
    draft after each revision.
    """

    generated = copy.deepcopy(dict(raw_brief))
    truth = dict(generated.get("truth_payload") or {})
    for key in (
        "required_verbatim_voiceover",
        "required_verbatim_voiceover_lines",
        "locked_voiceover_feasible_allocation",
        "locked_voiceover_segment_boundary_policy",
        "locked_script_variant_policy",
        "deliverable_script_manifest",
    ):
        truth.pop(key, None)
    copy_contract = dict(truth.get("creative_copy_contract") or {})
    copy_contract.pop("required_verbatim_voiceover", None)
    copy_contract.pop("required_verbatim_voiceovers", None)
    copy_contract.pop("script_reuse_mode", None)
    if seed_deliverable is not None:
        copy_contract["director_seed_voiceover"] = {
            key: value
            for key, value in dict(seed_deliverable).items()
            if key != "sha256"
        }
    copy_contract["copy_authority"] = "producer_draft_editable"
    truth["creative_copy_contract"] = copy_contract

    series_intent = copy.deepcopy(dict(truth.get("series_intent") or {}))
    strategy = dict(series_intent.get("creative_strategy") or {})
    strategy["script_preservation"] = (
        "Use the Producer copy only as an editable seed. Rewrite it whenever "
        "needed to satisfy the signed user intent and independent Critic."
    )
    series_intent["creative_strategy"] = strategy
    differentiation = dict(series_intent.get("differentiation") or {})
    audio_strategy = str(differentiation.get("audio_strategy") or "")
    differentiation["audio_strategy"] = re.sub(
        r"^Protected\s+",
        "Consistent ",
        audio_strategy,
        flags=re.IGNORECASE,
    )
    series_intent["differentiation"] = differentiation
    truth["series_intent"] = series_intent
    generated["truth_payload"] = truth

    cleaned_constraints: list[str] = []
    for raw in list(generated.get("creative_constraints") or []):
        text = str(raw or "").strip()
        lowered = text.casefold()
        if (
            "required verbatim voiceover exactly" in lowered
            or "preserve immutable locked voiceover exactly" in lowered
        ):
            continue
        text = re.sub(
            r"\balready locked\b\s*",
            "",
            text,
            flags=re.IGNORECASE,
        )
        cleaned_constraints.append(text)
    generated["creative_constraints"] = list(
        dict.fromkeys(cleaned_constraints)
    )[:128]
    return generated


def _run_content_series_director_stage(
    db,
    *,
    stage_row: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    request_id: str,
    delivery_run_token: str,
    release_guard_before_successor: Callable[[], None] | None = None,
) -> dict[str, Any]:
    """Plan and independently approve the complete series before copy work."""
    from app.services.hermes_agent.content_director import (
        materialize_series_director_briefs,
    )
    from app.services.hermes_agent.content_series_runtime import (
        run_content_series_slate_loop,
    )
    from app.services.hermes_agent.content_series_store import (
        persist_approved_series_slate,
    )

    (
        brief,
        policy,
        planned_variant_indices,
        completed_history_sha256,
    ) = _series_director_stage_configuration(db, project)
    operator_instruction = str(stage_row.instruction or "").strip()
    if operator_instruction:
        instruction_truth = dict(brief.truth_payload or {})
        instruction_truth["operator_stage_instruction"] = (
            operator_instruction
        )
        brief = brief.model_copy(
            update={"truth_payload": instruction_truth}
        )
    if not planned_variant_indices:
        stage_row.status = "success"
        stage_row.completed_at = _stage_now()
        stage_row.error_message = None
        project.status = "complete"
        project.current_stage = "COMPLETE"
        project.last_error = None
        db.commit()
        return {
            "status": "already_complete",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    plan_signature = hashlib.sha256(
        json.dumps(
            {
                "brief": brief.model_dump(mode="json"),
                "planned_variant_indices": planned_variant_indices,
                "completed_history_sha256": completed_history_sha256,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    stage_input = dict(stage_row.input_json or {})
    if str(stage_input.get("series_director_plan_signature") or "") != plan_signature:
        # A continuation slate is invalid as soon as the durable completed set
        # changes.  Never resume an old page checkpoint against a new history
        # or a different missing-index map.
        stage_input.pop("series_director_page_checkpoint", None)
        stage_input["series_director_plan_signature"] = plan_signature
        stage_input["series_director_planned_variant_indices"] = list(
            planned_variant_indices
        )
        stage_input["completed_content_history_sha256"] = (
            completed_history_sha256
        )
        stage_row.input_json = stage_input
        db.commit()
    resume_checkpoint = dict(
        stage_input.get("series_director_page_checkpoint") or {}
    )

    def _persist_page_checkpoint(
        checkpoint: dict[str, Any] | None,
    ) -> None:
        locked_stage, locked_project, _ = _lock_stage_delivery_scope(
            db,
            int(stage_row.id),
        )
        if locked_stage is None or locked_project is None:
            raise RuntimeError(
                "SERIES_DIRECTOR_CHECKPOINT_SCOPE_MISSING"
            )
        if not _is_current_stage_delivery(
            locked_stage,
            request_id=request_id,
            run_token=delivery_run_token,
        ):
            raise RuntimeError(
                "SERIES_DIRECTOR_CHECKPOINT_DELIVERY_SUPERSEDED"
            )
        stage_input = dict(locked_stage.input_json or {})
        if checkpoint is None:
            stage_input.pop(
                "series_director_page_checkpoint",
                None,
            )
        else:
            stage_input["series_director_page_checkpoint"] = (
                dict(checkpoint)
            )
        locked_stage.input_json = stage_input
        db.commit()

    loop_result = asyncio.run(
        run_content_series_slate_loop(
            brief=brief,
            policy=policy,
            resume_page_checkpoint=resume_checkpoint,
            page_checkpoint_callback=_persist_page_checkpoint,
        )
    )

    completion_stage, completion_project, _ = _lock_stage_delivery_scope(
        db,
        int(stage_row.id),
    )
    if completion_stage is None or completion_project is None:
        return {
            "status": "missing_completion_scope",
            "stage_id": int(stage_row.id),
        }
    stage_row = completion_stage
    project = completion_project
    if not _is_current_stage_delivery(
        stage_row,
        request_id=request_id,
        run_token=delivery_run_token,
    ):
        return {
            "status": "ignored_superseded_at_completion_fence",
            "stage_id": int(stage_row.id),
        }
    if not _stage_completion_pointer_is_authoritative(db, project, stage_row):
        return {
            "status": "ignored_stage_changed_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_stage": str(project.current_stage or ""),
        }
    latest_stage = _latest_stage(db, project, "SERIES_DIRECTOR")
    if latest_stage is not None and int(latest_stage.id) != int(stage_row.id):
        _retire_superseded_stage_row(
            db,
            stage_row,
            reason=(
                "Superseded at series-director completion fence by stage "
                f"{int(latest_stage.id)}."
            ),
        )
        return {
            "status": "ignored_superseded_stage_at_completion_fence",
            "stage_id": int(stage_row.id),
            "latest_stage_id": int(latest_stage.id),
        }

    final_slate = loop_result.final_slate
    result_payload = {
        "series_id": brief.series_id,
        "series_version": int(brief.series_version),
        "loop_status": loop_result.status,
        "series_slate": (
            final_slate.model_dump(mode="json")
            if final_slate is not None
            else None
        ),
        "director_attempt_count": len(loop_result.attempts),
        "review_count": len(loop_result.reviews),
        "coverage_review_count": len(loop_result.coverage_reviews),
        "page_review_count": len(loop_result.page_reviews),
        "contract_errors": list(loop_result.contract_errors),
        "reason": loop_result.reason,
    }
    evidence = {
        "execution_backend": "hermes_content_control_plane",
        "director_endpoint_role": "content_director",
        "critic_endpoint_role": "content_critic",
        "media_authorized": False,
        "attempts": [
            item.model_dump(mode="json")
            for item in loop_result.attempts
        ],
        "reviews": [
            item.model_dump(mode="json")
            for item in loop_result.reviews
        ],
        "coverage_reviews": [
            item.model_dump(mode="json")
            for item in loop_result.coverage_reviews
        ],
        "page_reviews": [
            item.model_dump(mode="json")
            for item in loop_result.page_reviews
        ],
    }
    envelope = {
        "schema_version": "1.0",
        "project_id": project.project_key,
        "stage": "SERIES_DIRECTOR",
        "status": (
            "PASS"
            if loop_result.status == "approved"
            else "QUALITY_PAUSE"
        ),
        "result": result_payload,
        "evidence": evidence,
        "issues": (
            []
            if loop_result.status == "approved"
            else [{
                "code": "SERIES_DIRECTOR_QUALITY_PAUSE",
                "message": loop_result.reason,
            }]
        ),
        "repair_brief": None,
        "next_stage": (
            "DIRECTOR"
            if loop_result.status == "approved"
            else None
        ),
    }
    stage_row.output_json = envelope
    stage_row.response_text = (
        json.dumps(
            final_slate.model_dump(mode="json"),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        if final_slate is not None
        else None
    )
    stage_row.completed_at = _stage_now()

    manual_pause = (
        str(project.status or "").lower() == "paused"
        or bool(dict(project.config_json or {}).get("manual_paused", False))
    )
    if manual_pause:
        stage_row.status = "paused"
        stage_row.error_message = (
            "Paused manually while whole-series review was in flight; the "
            "review evidence was preserved and no per-video work was queued."
        )
        db.commit()
        return {
            "status": "paused_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    if loop_result.status != "approved" or final_slate is None:
        stage_row.status = "failed"
        stage_row.error_message = loop_result.reason[:4000]
        config = dict(project.config_json or {})
        config["manual_paused"] = False
        project.config_json = config
        state = dict(project.state_json or {})
        paused_at = _stage_now().isoformat()
        state.update({
            "paused_at": paused_at,
            "automatic_quality_paused_at": paused_at,
            "pause_reason_code": "series_director_quality_pause",
            "quality_pause_source_code": "series_director_quality_pause",
            "pause_note": loop_result.reason[:1000],
            "content_series_quality_pause": {
                "stage_id": int(stage_row.id),
                "series_id": brief.series_id,
                "series_version": int(brief.series_version),
                "autonomy_snapshot": _loop_quality_snapshot(loop_result),
                "at": paused_at,
            },
        })
        project.state_json = state
        project.status = "paused"
        project.current_stage = "SERIES_DIRECTOR"
        project.last_error = loop_result.reason[:4000]
        from app.services.hermes_agent.content_factory import (
            _record_project_transition,
            _release_bridge_for_project,
        )

        _record_project_transition(
            project,
            stage="SERIES_DIRECTOR",
            status="paused",
            reason="series_director_quality_pause",
        )
        _release_bridge_for_project(db, project_id=int(project.id))
        db.commit()
        return {
            "status": "quality_pause",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    audit_row = persist_approved_series_slate(
        db,
        project=project,
        brief=brief,
        result=loop_result,
    )
    generated_briefs = materialize_series_director_briefs(
        brief,
        final_slate,
    )
    remapped_briefs: dict[str, dict[str, Any]] = {}
    project_config = dict(project.config_json or {})
    copy_contract = dict(project_config.get("creative_copy_contract") or {})
    deliverable_scripts = {
        int(item.get("deliverable_ordinal") or 0): dict(item)
        for item in list(
            copy_contract.get("required_verbatim_voiceovers") or []
        )
        if isinstance(item, dict)
        and int(item.get("deliverable_ordinal") or 0) > 0
    } if _deliverable_copy_is_user_verbatim(project_config) else {}
    editable_seed_scripts = {
        int(item.get("deliverable_ordinal") or 0): dict(item)
        for item in _editable_seed_deliverables(project_config)
        if int(item.get("deliverable_ordinal") or 0) > 0
    }
    for planning_ordinal, actual_variant_index in enumerate(
        planned_variant_indices,
        1,
    ):
        generated = dict(
            generated_briefs.get(str(planning_ordinal)) or {}
        )
        if not generated:
            raise ValueError(
                "SERIES_DIRECTOR_MATERIALIZATION_MISSING: planning ordinal "
                f"{planning_ordinal} has no generated brief"
            )
        generated["brief_id"] = (
            f"{brief.series_id}.variant-{actual_variant_index:03d}."
            f"v{brief.series_version}"
        )
        truth_payload = dict(generated.get("truth_payload") or {})
        # Whole-series planning and the independent critics have already used
        # the full completed-content registry.  Per-video Directors need the
        # approved intent and the signed history identity, not another 40KB
        # copy of every old script on every model call.
        truth_payload.pop("completed_content_history", None)
        truth_payload["completed_content_history_sha256"] = (
            completed_history_sha256
        )
        series_intent = dict(truth_payload.get("series_intent") or {})
        series_intent.update({
            "planning_ordinal": planning_ordinal,
            "variant_index": actual_variant_index,
        })
        truth_payload["series_intent"] = series_intent
        locked_deliverable = deliverable_scripts.get(actual_variant_index)
        if locked_deliverable is not None:
            generated["truth_payload"] = truth_payload
            duration_range = _configured_video_duration_range(project)
            minimum_rate, maximum_rate = (
                _configured_locked_script_speech_rate_range(project)
            )
            generated = _apply_locked_deliverable_script_to_director_brief(
                generated,
                locked_deliverable=locked_deliverable,
                deliverable_ordinal=actual_variant_index,
                minimum_duration_seconds=duration_range["min"],
                maximum_duration_seconds=duration_range["max"],
                baseline_speech_rate_wpm=minimum_rate,
                maximum_speech_rate_wpm=maximum_rate,
            )
        else:
            generated["truth_payload"] = truth_payload
            generated = _sanitize_editable_director_brief(
                generated,
                seed_deliverable=editable_seed_scripts.get(
                    actual_variant_index
                ),
            )
        remapped_briefs[str(actual_variant_index)] = generated
    config = dict(project.config_json or {})
    existing_briefs = dict(
        config.get("director_briefs_by_variant") or {}
    )
    existing_briefs.update(remapped_briefs)
    config["director_briefs_by_variant"] = existing_briefs
    config["approved_series_slate_sha256"] = final_slate.slate_sha256
    project.config_json = config
    state = dict(project.state_json or {})
    state["approved_series_slate"] = {
        "series_id": brief.series_id,
        "series_version": int(brief.series_version),
        "slate_sha256": final_slate.slate_sha256,
        "audit_row_id": int(audit_row.id),
        "series_director_stage_id": int(stage_row.id),
        "intent_count": len(final_slate.intents),
        "total_target_count": _target_video_count(project),
        "planned_variant_indices": list(planned_variant_indices),
        "completed_history_count": len(
            list(
                dict(brief.truth_payload or {}).get(
                    "completed_content_history"
                )
                or []
            )
        ),
        "completed_content_history_sha256": completed_history_sha256,
    }
    state = _mark_automatic_quality_recovery_resolved(
        state,
        stage_name="SERIES_DIRECTOR",
        stage_id=int(stage_row.id),
        variant_index=None,
    )
    project.state_json = state
    stage_row.status = "success"
    stage_row.error_message = None
    result_payload["audit_row_id"] = int(audit_row.id)
    result_payload["materialized_brief_count"] = len(remapped_briefs)
    evidence["media_authorized"] = False
    project.current_stage = "DIRECTOR"
    project.status = "ready"
    project.last_error = None
    from app.services.hermes_agent.content_factory import _record_project_transition

    _record_project_transition(
        project,
        stage="DIRECTOR",
        status="ready",
        reason="series_director_approved",
    )
    continue_workflow = bool(
        dict(stage_row.input_json or {}).get("continue_workflow", True)
    )
    db.commit()
    if continue_workflow:
        from app.services.hermes_agent.content_factory import queue_stage

        pipeline = _variant_pipeline(project)
        active_variant = int(pipeline.get("active_index") or 1)
        next_variant = (
            active_variant
            if active_variant in planned_variant_indices
            and _variant_rollout_authorized(project, active_variant)
            else next(
                (
                    index
                    for index in planned_variant_indices
                    if _variant_rollout_authorized(project, index)
                ),
                None,
            )
        )
        if next_variant is None:
            project.status = "ready"
            project.last_error = (
                "Whole-series continuation plan is approved, but the rollout "
                "gate currently authorizes none of its missing variants."
            )
            db.commit()
            return {
                "status": "awaiting_rollout_authorization",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
                "planned_variant_indices": planned_variant_indices,
            }
        pipeline["active_index"] = int(next_variant)
        _set_variant_pipeline(project, pipeline)
        db.commit()

        # SERIES_DIRECTOR runs through a dedicated control-plane branch and
        # does not reach the common stage-success publisher below. Release the
        # outer project advisory guard here as well, after all approved slate
        # state is durable but before the successor can reach another worker.
        # Otherwise every series-to-director transition collides with its own
        # predecessor and waits for periodic self-heal.
        if release_guard_before_successor is not None:
            release_guard_before_successor()
        queue_stage(
            db,
            project=project,
            user_id=int(project.user_id or stage_row.user_id or 1),
            instruction=(
                f"Write variant {int(next_variant)} from its approved series "
                "intent. Preserve "
                "the project truth, conversion contract, and diversity axis."
            ),
            target_stage="DIRECTOR",
            continue_workflow=True,
        )
        db.commit()
    return {
        "status": "success",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "next_stage": "DIRECTOR",
        "slate_sha256": final_slate.slate_sha256,
    }


def _remove_unbound_product_visual_requirements(
    raw_brief: dict[str, Any],
    *,
    product_required: bool,
) -> dict[str, Any]:
    """Bind product-free truth without heuristically rewriting user prose."""
    brief = dict(raw_brief or {})
    if product_required:
        return brief
    constraints = [
        str(value).strip()
        for value in list(brief.get("creative_constraints") or [])
        if str(value).strip()
    ]
    constraints.append(
        "Authoritative project truth: product_required=false. This supersedes "
        "any inherited visible-product request. The multimodal Director and "
        "independent Critic must reconcile the complete brief without depicting "
        "or inventing a product, package, contents, serving, or brand mark."
    )
    brief["creative_constraints"] = list(dict.fromkeys(constraints))[:128]
    truth_payload = dict(brief.get("truth_payload") or {})
    truth_payload["unbound_product_visual_constraint_repair"] = {
        "server_semantic_filtering_used": False,
        "preserved_inherited_constraint_count": len(constraints) - 1,
        "authority": "project_product_required_false",
    }
    brief["truth_payload"] = truth_payload
    return brief


def _bind_latest_operator_instruction_to_director_brief(
    brief,
    *,
    project: HermesContentFactoryProject,
):
    """Carry the newest user-authorized project instruction into Director.

    A full-series restart instruction is durable project intent, not merely a
    queue note for the first SERIES_DIRECTOR delivery.  Later variants can be
    authored hours after that delivery.  Re-reading the project-owned value at
    execution time keeps every AI role on the same current instruction without
    converting creative choices into deterministic server rules.
    """

    state = dict(project.state_json or {})
    restart = dict(state.get("last_restart") or {})
    instruction = str(restart.get("instruction") or "").strip()
    if not instruction:
        return brief

    truth_payload = dict(brief.truth_payload or {})
    truth_payload["operator_stage_instruction"] = instruction[:16000]
    truth_payload["operator_stage_instruction_authority"] = {
        "source": "project_last_restart",
        "restart_stage": (
            str(restart.get("stage") or "").strip().upper() or None
        ),
        "restart_generation": int(state.get("restart_count") or 0),
        "replace_completed": bool(restart.get("replace_completed", False)),
        "issued_at": str(restart.get("at") or "").strip() or None,
    }
    binding_constraint = (
        "Newest user-authorized project instruction. Treat it as binding "
        "across copy, visual planning, prompt compilation, semantic review, "
        "and delivery while preserving product truth and policy boundaries: "
        f"{instruction[:12000]}"
    )
    return brief.model_copy(update={
        "truth_payload": truth_payload,
        "creative_constraints": list(dict.fromkeys([
            *list(brief.creative_constraints),
            binding_constraint,
        ]))[:128],
    })


def _director_stage_configuration(
    project: HermesContentFactoryProject,
    *,
    variant_index: int,
    stage_input: dict[str, Any] | None = None,
):
    """Load only an explicit, project-owned director contract."""
    from app.services.hermes_agent.content_capabilities import (
        validate_brief_capabilities_against_registry,
    )
    from app.services.hermes_agent.content_director import DirectorProjectBrief
    from app.services.hermes_agent.content_director_runtime import (
        DirectorLoopPolicy,
    )

    config = dict(project.config_json or {})
    mode = str(config.get("content_director_mode") or "").strip().lower()
    if mode != "enforce":
        raise ValueError(
            "DIRECTOR_STAGE_MODE_INVALID: formal director stages require "
            "content_director_mode=enforce"
        )
    briefs = config.get("director_briefs_by_variant")
    if not isinstance(briefs, dict):
        raise ValueError(
            "DIRECTOR_BRIEF_MISSING: director_briefs_by_variant is not configured"
        )
    raw_brief = briefs.get(str(int(variant_index)))
    if raw_brief is None:
        raw_brief = briefs.get(int(variant_index))
    if not isinstance(raw_brief, dict):
        raise ValueError(
            f"DIRECTOR_BRIEF_MISSING: variant {int(variant_index)} has no "
            "explicit project brief"
        )
    raw_policy = config.get("director_loop_policy")
    if not isinstance(raw_policy, dict):
        raise ValueError(
            "DIRECTOR_LOOP_POLICY_MISSING: the project must explicitly bound "
            "revisions and contract repairs"
        )

    project_product_required = bool(config.get("product_required", True))
    normalized_raw_brief = _remove_unbound_product_visual_requirements(
        dict(raw_brief),
        product_required=project_product_required,
    )
    copy_contract = dict(config.get("creative_copy_contract") or {})
    locked_deliverable = next(
        (
            dict(item)
            for item in list(
                copy_contract.get("required_verbatim_voiceovers") or []
            )
            if isinstance(item, dict)
            and int(item.get("deliverable_ordinal") or 0)
            == int(variant_index)
        ),
        None,
    ) if _deliverable_copy_is_user_verbatim(config) else None
    if locked_deliverable is not None:
        duration_range = _configured_video_duration_range(project)
        minimum_rate, maximum_rate = (
            _configured_locked_script_speech_rate_range(project)
        )
        normalized_raw_brief = (
            _apply_locked_deliverable_script_to_director_brief(
                normalized_raw_brief,
                locked_deliverable=locked_deliverable,
                deliverable_ordinal=int(variant_index),
                minimum_duration_seconds=duration_range["min"],
                maximum_duration_seconds=duration_range["max"],
                baseline_speech_rate_wpm=minimum_rate,
                maximum_speech_rate_wpm=maximum_rate,
            )
        )
    else:
        editable_seed = next(
            (
                dict(item)
                for item in _editable_seed_deliverables(config)
                if int(item.get("deliverable_ordinal") or 0)
                == int(variant_index)
            ),
            None,
        )
        normalized_raw_brief = _sanitize_editable_director_brief(
            normalized_raw_brief,
            seed_deliverable=editable_seed,
        )
    brief = DirectorProjectBrief.model_validate(normalized_raw_brief)
    # Per-variant briefs are durable project artifacts and can outlive a
    # profile correction.  Bind this execution-time surface rule so an old
    # generic critic criterion cannot reinterpret a signed visual-intensity
    # requirement as a demand for painful audience-facing copy.  The model
    # still evaluates the copy; this only preserves the Producer's typed
    # ownership boundary between copy and final multimodal media.
    copy_surface_instructions = {
        "objective_fit": (
            "Judge whether the exact spoken or displayed copy fulfills the copy "
            "role assigned to it by the signed Producer intent and the current "
            "episode. Do not require the words to narrate visual action, camera "
            "movement, performance, escalation, or payoff that belongs to the "
            "later production plan and multimodal media review."
        ),
        "audience_comprehension": (
            "Judge whether the audience can understand the exact words on one "
            "hearing or viewing and whether those words can work with their "
            "assigned visual beat. Do not require one short line to verbally "
            "describe the complete visual premise, progression, and payoff."
        ),
        "complete_coherence": (
            "Judge the ordered spoken and displayed copy as copy: it must be "
            "internally coherent, non-fragmentary, and compatible with the "
            "assigned beat. Do not fail it because ungenerated visual execution "
            "is not repeated in the words."
        ),
    }
    scoped_review_criteria = []
    for criterion in brief.copy_review_criteria:
        if criterion.criterion_id in copy_surface_instructions:
            scoped_review_criteria.append(criterion.model_copy(update={
                "instruction": copy_surface_instructions[
                    criterion.criterion_id
                ],
            }))
            continue
        if criterion.criterion_id != "requested_stakes_strength":
            scoped_review_criteria.append(criterion)
            continue
        scoped_review_criteria.append(criterion.model_copy(update={
            "instruction": (
                "Match intensity on the exact audience-facing copy surface "
                "specified by the signed Producer intent. A requirement typed "
                "kind=visual belongs to multimodal media review and must not "
                "be converted into a demand for painful, high-stakes, or "
                "consequence-heavy wording. Require concrete valued loss, "
                "identity conflict, relationship or professional cost, "
                "repeated consequence, missed life moment, or fear of no "
                "longer feeling like oneself only when the signed requirement "
                "and observable checks explicitly assign that job to spoken "
                "or displayed words. When intensity is assigned to visual "
                "action, camera, performance, escalation, or payoff, judge "
                "whether the copy supports rather than obstructs it; do not "
                "manufacture pain."
            ),
        }))
    brief = brief.model_copy(update={
        "copy_review_criteria": scoped_review_criteria,
    })
    brief = _bind_latest_operator_instruction_to_director_brief(
        brief,
        project=project,
    )
    benchmark_evidence = _benchmark_visual_director_evidence(project)
    if benchmark_evidence:
        truth_payload = dict(brief.truth_payload or {})
        truth_payload["benchmark_visual_evidence"] = benchmark_evidence
        brief = brief.model_copy(update={
            "truth_payload": truth_payload,
            "creative_constraints": list(dict.fromkeys([
                *list(brief.creative_constraints),
                (
                    "Execute benchmark_visual_evidence as pixel-grounded "
                    "authority for every explicitly requested abstract opening "
                    "mechanism. Preserve its ordered visual-state escalation "
                    "and attention contrast while inventing new source-safe "
                    "actors, props, setting, actions, and imagery."
                ),
            ]))[:128],
        })
    # The project-level confirmed offer is the current conversation-owned
    # commercial truth.  Materialized per-variant briefs can predate a policy
    # fix or a confirmed offer update, so bind this small mutable authority at
    # execution time without regenerating the approved visual intent.
    confirmed_offer = re.sub(
        r"\s+",
        " ",
        str(config.get("confirmed_promotions") or ""),
    ).strip()
    if confirmed_offer:
        truth_payload = dict(brief.truth_payload or {})
        truth_payload["confirmed_promotions"] = confirmed_offer
        truth_payload["confirmed_promotion_policy"] = confirmed_offer
        brief = brief.model_copy(update={
            "conversion": brief.conversion.model_copy(
                update={"offer_text": confirmed_offer}
            ),
            "truth_payload": truth_payload,
        })

    replan_feedback = [
        dict(item or {})
        for item in list(
            dict(stage_input or {}).get("director_replan_feedback") or []
        )
        if isinstance(item, dict)
    ]
    effective_feedback: list[dict[str, Any]] = []
    for item in replan_feedback:
        code = str(item.get("code") or "").strip().upper()
        # A critic produced under the old truncated-offer contract may call a
        # shipping qualifier unsupported.  The current project truth wins;
        # do not tell Director to violate the now-authoritative locked copy.
        if (
            code == "UNCONFIRMED_SHIPPING_CLAIM"
            and "shipped" in confirmed_offer.casefold()
        ):
            continue
        effective_feedback.append(item)
    if effective_feedback:
        truth_payload = dict(brief.truth_payload or {})
        truth_payload["upstream_production_plan_replan_feedback"] = (
            effective_feedback
        )
        constraints = list(brief.creative_constraints)
        if _deliverable_copy_is_user_verbatim(config):
            constraints.append(
                "Repair the structured upstream production-plan feedback "
                "using only current project truth. Preserve immutable locked "
                "voiceover exactly; replan only Director-owned story, beat, "
                "capability, or conversion-bridge fields."
            )
        else:
            truth_payload["director_replan_copy_authority"] = {
                "mode": "model_editable",
                "authority": "user_did_not_lock_verbatim_copy",
                "instruction": (
                    "A segment-level provider execution may call its current "
                    "dialogue signed or exact because the provider must not "
                    "rewrite an approved Director script. That local lock "
                    "does not survive an authorized Director replan. The "
                    "Director may replace model-authored copy when needed to "
                    "satisfy the signed Producer intent."
                ),
            }
            constraints.append(
                "Repair the structured upstream production-plan feedback "
                "using only current project truth. The Producer draft is "
                "editable: revise the audience-facing copy when the Critic's "
                "evidence shows that copy is the failing dimension. Any "
                "segment-level instruction to preserve current signed or exact "
                "dialogue applies only to provider execution and is superseded "
                "at this authorized Director replan; only user-verbatim copy "
                "remains immutable."
            )
        brief = brief.model_copy(update={
            "truth_payload": truth_payload,
            "creative_constraints": list(dict.fromkeys(constraints))[:128],
        })
    policy = DirectorLoopPolicy.model_validate(raw_policy)
    validate_brief_capabilities_against_registry(brief)
    if brief.locale != _configured_video_language(project):
        raise ValueError(
            "DIRECTOR_BRIEF_LOCALE_MISMATCH: brief locale must match the "
            "project video language"
        )
    duration_range = _configured_video_duration_range(project)
    duration_min = duration_range["min"]
    duration_max = duration_range["max"]
    if not duration_min <= brief.target_duration_seconds <= duration_max:
        raise ValueError(
            "DIRECTOR_BRIEF_DURATION_MISMATCH: brief duration is outside the "
            "project video duration range"
        )
    if brief.conversion.product_required != project_product_required:
        raise ValueError(
            "DIRECTOR_BRIEF_PRODUCT_MODE_MISMATCH: brief conversion mode does "
            "not match the project"
        )
    if project_product_required:
        configured_product = str(project.product_name or "").strip().casefold()
        brief_product = str(
            brief.conversion.product_name or ""
        ).strip().casefold()
        if configured_product and configured_product not in brief_product:
            raise ValueError(
                "DIRECTOR_BRIEF_PRODUCT_IDENTITY_MISMATCH: conversion product "
                "does not match the project product"
            )
    return mode, brief, policy


def _latest_director_ancestor_for_brief(
    db,
    *,
    project: HermesContentFactoryProject,
    variant_index: int,
    artifact_id: str,
    brief,
) -> HermesContentDirectorArtifact | None:
    """Return only a complete immutable ancestry for this exact brief.

    A variant number and artifact key are intentionally stable across series
    replans.  They are therefore not sufficient ancestry boundaries.  A new
    series brief must never resume rejected copy from an older brief merely
    because both belong to the same output slot.

    Technical retries may persist consecutive revisions under different
    execution rows, so ancestry is matched by the immutable brief identity
    and content hash rather than one database ``brief_id``.  Every parent in
    the chain must have the same identity/hash and the immediately preceding
    revision; a historically contaminated cross-brief chain is ignored and
    the new brief starts at revision one.
    """
    normalized_variant = int(variant_index)
    brief_payload = brief.model_dump(mode="json")
    brief_sha256 = _canonical_content_digest(brief_payload)
    matching_rows = (
        db.query(HermesContentDirectorArtifact)
        .join(
            HermesContentDirectorBrief,
            HermesContentDirectorBrief.id
            == HermesContentDirectorArtifact.brief_id,
        )
        .filter(
            HermesContentDirectorArtifact.project_id == int(project.id),
            HermesContentDirectorArtifact.workspace_id
            == int(project.workspace_id),
            HermesContentDirectorArtifact.variant_index
            == normalized_variant,
            HermesContentDirectorArtifact.artifact_key == artifact_id,
            HermesContentDirectorBrief.project_id == int(project.id),
            HermesContentDirectorBrief.workspace_id
            == int(project.workspace_id),
            HermesContentDirectorBrief.variant_index == normalized_variant,
            HermesContentDirectorBrief.brief_key == str(brief.brief_id),
            HermesContentDirectorBrief.brief_version
            == int(brief.brief_version),
            HermesContentDirectorBrief.brief_sha256 == brief_sha256,
        )
        .order_by(
            HermesContentDirectorArtifact.revision.desc(),
            HermesContentDirectorArtifact.id.desc(),
        )
        .all()
    )
    by_sha256 = {
        str(row.artifact_sha256): row
        for row in matching_rows
    }
    for candidate in matching_rows:
        cursor = candidate
        expected_revision = int(candidate.revision)
        seen: set[str] = set()
        valid = True
        while True:
            cursor_sha256 = str(cursor.artifact_sha256)
            if cursor_sha256 in seen:
                valid = False
                break
            seen.add(cursor_sha256)
            if int(cursor.revision) != expected_revision:
                valid = False
                break
            parent_sha256 = str(
                cursor.parent_artifact_sha256 or ""
            ).strip()
            if expected_revision == 1:
                valid = not parent_sha256
                break
            if not parent_sha256:
                valid = False
                break
            parent = by_sha256.get(parent_sha256)
            if parent is None:
                valid = False
                break
            cursor = parent
            expected_revision -= 1
        if valid:
            return candidate
    return None


def _explicit_director_restart_allows_new_revision(
    project: HermesContentFactoryProject,
    stage_row: HermesContentFactoryStage,
) -> bool:
    """Distinguish an operator restart from an automatic Director resume.

    Accepted copy remains immutable during delivery retries and self-heal. An
    explicit restart from DIRECTOR is different: the operator has authorized a
    new audited revision, so it may use the accepted artifact as lineage while
    starting a fresh author/critic loop instead of trying to resume that copy.
    """
    stage_input = dict(stage_row.input_json or {})
    state = dict(project.state_json or {})
    restart = dict(state.get("last_restart") or {})
    restart_generation = int(stage_input.get("restart_generation") or 0)
    current_generation = int(state.get("restart_count") or 0)
    automatic_upstream_replan = bool(
        stage_input.get("force_fresh_response")
        and str(
            stage_input.get("automatic_quality_pause_reason") or ""
        ).strip().lower()
        in {
            "creative_visual_replan_exhausted",
            "production_plan_quality_pause",
            "final_video_quality_gate",
        }
        and list(stage_input.get("director_replan_feedback") or [])
        and int(stage_input.get("director_replan_source_stage_id") or 0) > 0
    )
    return bool(
        automatic_upstream_replan
        or (
            stage_input.get("force_fresh_response")
            and restart_generation > 0
            and restart_generation == current_generation
            and str(restart.get("stage") or "").strip().upper() == "DIRECTOR"
        )
    )


def _run_content_director_stage(
    db,
    *,
    stage_row: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    request_id: str,
    delivery_run_token: str,
    release_guard_before_successor: Callable[[], None] | None = None,
) -> dict[str, Any]:
    """Run and persist the author/critic gate before any media-capable stage."""
    from app.services.hermes_agent.content_director_runtime import (
        run_content_director_copy_loop,
    )
    from app.services.hermes_agent.content_director import (
        CopyPreflightReport,
        DirectedContentArtifact,
        IndependentCopyCriticVerdict,
    )
    from app.services.hermes_agent.content_director_store import (
        persist_content_director_loop,
    )

    variant_index = _stage_variant_index(stage_row, project)
    mode, brief, policy = _director_stage_configuration(
        project,
        variant_index=variant_index,
        stage_input=dict(stage_row.input_json or {}),
    )
    artifact_id = (
        f"{project.project_key}.variant-{int(variant_index):03d}.content"
    )
    latest_ancestor = _latest_director_ancestor_for_brief(
        db,
        project=project,
        variant_index=variant_index,
        artifact_id=artifact_id,
        brief=brief,
    )
    initial_revision = int(latest_ancestor.revision) + 1 if latest_ancestor is not None else 1
    parent_artifact_sha256 = (
        str(latest_ancestor.artifact_sha256)
        if latest_ancestor is not None
        else None
    )
    resume_artifact = None
    resume_preflight = None
    resume_verdict = None
    pending_review_artifact = None
    resume_execution_key = None
    explicit_director_restart = (
        _explicit_director_restart_allows_new_revision(project, stage_row)
    )
    if latest_ancestor is not None:
        latest_review = (
            db.query(HermesContentDirectorReview)
            .filter(
                HermesContentDirectorReview.artifact_id
                == int(latest_ancestor.id),
            )
            .order_by(
                HermesContentDirectorReview.review_round.desc(),
                HermesContentDirectorReview.id.desc(),
            )
            .first()
        )
        if latest_review is None:
            if bool(latest_ancestor.accepted):
                raise ValueError(
                    "DIRECTOR_RESUME_EVIDENCE_MISSING: accepted immutable "
                    "ancestor has no independent review"
                )
            pending_review_artifact = DirectedContentArtifact.model_validate(
                latest_ancestor.artifact_json
            )
            ancestor_brief = db.get(
                HermesContentDirectorBrief,
                int(latest_ancestor.brief_id),
            )
            resume_execution_key = (
                str(ancestor_brief.execution_key)
                if ancestor_brief is not None
                else None
            )
        ancestor_approved = bool(latest_ancestor.accepted) or bool(
            latest_review.approved if latest_review is not None else False
        )
        if latest_review is not None and ancestor_approved and not explicit_director_restart:
            raise ValueError(
                "DIRECTOR_RESUME_ANCESTOR_APPROVED: accepted copy cannot be "
                "silently rewritten by a resumed Director stage"
            )
        if latest_review is not None and not ancestor_approved:
            resume_artifact = DirectedContentArtifact.model_validate(
                latest_ancestor.artifact_json
            )
            resume_preflight = CopyPreflightReport.model_validate(
                latest_review.preflight_json
            )
            resume_verdict = IndependentCopyCriticVerdict.model_validate(
                latest_review.verdict_json
            )
    loop_result = asyncio.run(
        run_content_director_copy_loop(
            brief=brief,
            artifact_id=artifact_id,
            policy=policy,
            initial_revision=initial_revision,
            parent_artifact_sha256=parent_artifact_sha256,
            resume_artifact=resume_artifact,
            resume_preflight=resume_preflight,
            resume_verdict=resume_verdict,
            pending_review_artifact=pending_review_artifact,
            allow_fresh_revision_from_accepted_ancestor=(
                explicit_director_restart
                and latest_ancestor is not None
                and resume_artifact is None
            ),
            request_idempotency_namespace=(
                f"{project.project_key}:variant:{int(variant_index)}:"
                f"director:stage:{int(stage_row.id)}:run:"
                f"{str(delivery_run_token or request_id)}"
            ),
        )
    )

    completion_stage, completion_project, _ = _lock_stage_delivery_scope(
        db,
        int(stage_row.id),
    )
    if completion_stage is None or completion_project is None:
        return {
            "status": "missing_completion_scope",
            "stage_id": int(stage_row.id),
        }
    stage_row = completion_stage
    project = completion_project
    if not _is_current_stage_delivery(
        stage_row,
        request_id=request_id,
        run_token=delivery_run_token,
    ):
        return {
            "status": "ignored_superseded_at_completion_fence",
            "stage_id": int(stage_row.id),
        }
    if not _stage_completion_pointer_is_authoritative(db, project, stage_row):
        return {
            "status": "ignored_stage_changed_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_stage": str(project.current_stage or ""),
        }
    latest_stage = _latest_stage(db, project, "DIRECTOR")
    if latest_stage is not None and int(latest_stage.id) != int(stage_row.id):
        _retire_superseded_stage_row(
            db,
            stage_row,
            reason=(
                f"Superseded at director completion fence by stage "
                f"{int(latest_stage.id)}."
            ),
        )
        return {
            "status": "ignored_superseded_stage_at_completion_fence",
            "stage_id": int(stage_row.id),
            "latest_stage_id": int(latest_stage.id),
        }

    audit_brief = persist_content_director_loop(
        db,
        project=project,
        variant_index=variant_index,
        mode=mode,
        brief=brief,
        result=loop_result,
        # A technical retry may legitimately execute the same durable stage
        # row again with a new delivery token. Bind the immutable audit
        # generation to both identities: broker redelivery of the same token
        # remains idempotent, while a new bounded run cannot collide with the
        # prior run's author/critic evidence.
        execution_key=(
            resume_execution_key
            or (
                f"director-stage-{int(stage_row.id)}-run-"
                f"{str(delivery_run_token or request_id).strip()}"
            )[:128]
        ),
    )
    final_artifact = loop_result.final_artifact
    result_payload = {
        "brief_id": brief.brief_id,
        "brief_version": int(brief.brief_version),
        "audit_brief_row_id": int(audit_brief.id),
        "loop_status": loop_result.status,
        "director_artifact": (
            final_artifact.model_dump(mode="json")
            if final_artifact is not None
            else None
        ),
        "artifact_count": len(loop_result.artifacts),
        "director_attempt_count": len(loop_result.director_attempts),
        "review_count": len(loop_result.reviews),
        "contract_errors": list(loop_result.contract_errors),
        "reason": loop_result.reason,
    }
    evidence = {
        "execution_backend": "hermes_content_control_plane",
        "director_endpoint_role": "content_director",
        "critic_endpoint_role": "content_critic",
        "variant_index": int(variant_index),
        "content_factory_variant_index": int(variant_index),
        "director_attempts": [
            attempt.model_dump(mode="json")
            for attempt in loop_result.director_attempts
        ],
        "reviews": [
            {
                "artifact_sha256": review.artifact_sha256,
                "preflight": review.preflight.model_dump(mode="json"),
                "verdict": review.verdict.model_dump(mode="json"),
                "critic_latency_ms": int(review.critic_latency_ms),
                "critic_response_sha256": review.critic_response_sha256,
            }
            for review in loop_result.reviews
        ],
    }
    envelope = {
        "schema_version": "1.0",
        "project_id": project.project_key,
        "stage": "DIRECTOR",
        "status": "PASS" if loop_result.status == "approved" else "QUALITY_PAUSE",
        "result": result_payload,
        "evidence": evidence,
        "issues": (
            []
            if loop_result.status == "approved"
            else [{"code": "DIRECTOR_QUALITY_PAUSE", "message": loop_result.reason}]
        ),
        "repair_brief": None,
        "next_stage": (
            "PRODUCTION_PLAN"
            if loop_result.status == "approved"
            else None
        ),
        "content_factory_variant_index": int(variant_index),
    }
    stage_row.output_json = envelope
    stage_row.response_text = (
        json.dumps(
            final_artifact.model_dump(mode="json"),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        if final_artifact is not None
        else None
    )
    stage_row.completed_at = _stage_now()

    manual_pause = (
        str(project.status or "").lower() == "paused"
        or bool(dict(project.config_json or {}).get("manual_paused", False))
    )
    if manual_pause:
        stage_row.status = "paused"
        stage_row.error_message = (
            "Paused manually while director review was in flight; the audited "
            "result was preserved but no media-capable stage was authorized."
        )
        db.commit()
        return {
            "status": "paused_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    if loop_result.status != "approved" or final_artifact is None:
        stage_row.status = "failed"
        stage_row.error_message = loop_result.reason[:4000]
        config = dict(project.config_json or {})
        config["manual_paused"] = False
        project.config_json = config
        state = dict(project.state_json or {})
        paused_at = _stage_now().isoformat()
        state.update(
            {
                "paused_at": paused_at,
                "automatic_quality_paused_at": paused_at,
                "pause_reason_code": "content_director_quality_pause",
                "quality_pause_source_code": "content_director_quality_pause",
                "pause_note": loop_result.reason[:1000],
                "content_director_quality_pause": {
                    "variant_index": int(variant_index),
                    "stage_id": int(stage_row.id),
                    "brief_id": brief.brief_id,
                    "audit_brief_row_id": int(audit_brief.id),
                    "autonomy_snapshot": _loop_quality_snapshot(loop_result),
                    "at": paused_at,
                },
            }
        )
        project.state_json = state
        project.status = "paused"
        project.current_stage = "DIRECTOR"
        project.last_error = loop_result.reason[:4000]
        from app.services.hermes_agent.content_factory import (
            _record_project_transition,
            _release_bridge_for_project,
        )

        _record_project_transition(
            project,
            stage="DIRECTOR",
            status="paused",
            reason="content_director_quality_pause",
        )
        _release_bridge_for_project(db, project_id=int(project.id))
        db.commit()
        return {
            "status": "quality_pause",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
            "audit_brief_row_id": int(audit_brief.id),
        }

    stage_row.status = "success"
    stage_row.error_message = None
    project.current_stage = "PRODUCTION_PLAN"
    project.status = "ready"
    project.last_error = None
    state = dict(project.state_json or {})
    approved_pointer = {
        "variant_index": int(variant_index),
        "brief_id": brief.brief_id,
        "brief_version": int(brief.brief_version),
        "artifact_sha256": final_artifact.artifact_sha256,
        "script_sha256": final_artifact.script.canonical_text_sha256,
        "audit_brief_row_id": int(audit_brief.id),
        "director_stage_id": int(stage_row.id),
    }
    approved_by_variant = dict(
        state.get("approved_director_artifacts_by_variant") or {}
    )
    approved_by_variant[str(int(variant_index))] = approved_pointer
    state["approved_director_artifacts_by_variant"] = approved_by_variant
    # Keep the legacy active-variant pointer only as a compatibility view.
    # Media authorization reads the variant map first so parallel Director
    # approvals cannot invalidate an earlier variant still preparing media.
    state["approved_director_artifact"] = approved_pointer
    state = _mark_automatic_quality_recovery_resolved(
        state,
        stage_name="DIRECTOR",
        stage_id=int(stage_row.id),
        variant_index=int(variant_index),
    )
    project.state_json = state
    from app.services.hermes_agent.content_factory import _record_project_transition

    _record_project_transition(
        project,
        stage="PRODUCTION_PLAN",
        status="ready",
        reason="content_director_approved",
    )
    continue_workflow = bool(
        dict(stage_row.input_json or {}).get("continue_workflow", True)
    )
    db.commit()
    if continue_workflow:
        from app.services.hermes_agent.content_factory import queue_stage

        if release_guard_before_successor is not None:
            release_guard_before_successor()
        queue_stage(
            db,
            project=project,
            user_id=int(project.user_id or stage_row.user_id or 1),
            instruction=(
                "Direct the provider-independent visual, audio, reference, "
                "and exact copy-delivery plan for the approved script."
            ),
            target_stage="PRODUCTION_PLAN",
            continue_workflow=True,
        )
        db.commit()
    return {
        "status": "success",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "next_stage": "PRODUCTION_PLAN",
        "artifact_sha256": final_artifact.artifact_sha256,
    }


def _production_plan_asset_authority(
    db,
    project: HermesContentFactoryProject,
) -> tuple[
    dict[str, dict[str, Any]],
    list[str],
    list[str],
]:
    """Return project-scoped semantic asset IDs without leaking file paths."""

    rows = (
        db.query(HermesContentFactoryAsset)
        .filter(
            HermesContentFactoryAsset.project_id == int(project.id),
            HermesContentFactoryAsset.mime_type.like("image/%"),
            HermesContentFactoryAsset.kind.in_((
                "source",
                "character_reference",
            )),
        )
        .order_by(HermesContentFactoryAsset.id.asc())
        .all()
    )
    registry: dict[str, dict[str, Any]] = {}
    product_refs: list[str] = []
    for asset in rows:
        if not _asset_file_available(asset):
            continue
        role = _asset_role(asset)
        asset_ref = f"asset:{int(asset.id)}"
        is_product = (
            asset.kind == "source" and role == "product_visual"
        )
        registry[asset_ref] = {
            "asset_id": int(asset.id),
            "kind": str(asset.kind or ""),
            "role": role,
            "original_name": str(asset.original_name or ""),
            "mime_type": str(asset.mime_type or ""),
            "authoritative_product_asset": is_product,
        }
        if is_product:
            product_refs.append(asset_ref)
    if _project_uses_product(project) and not product_refs:
        raise ValueError(
            "PRODUCTION_PLAN_PRODUCT_AUTHORITY_MISSING: the project has no "
            "available uploaded product_visual image"
        )
    return registry, list(registry), product_refs


def _run_content_production_plan_stage(
    db,
    *,
    stage_row: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    request_id: str,
    delivery_run_token: str,
    release_guard_before_successor: Callable[[], None] | None = None,
) -> dict[str, Any]:
    """Direct, review, sign, and persist the only media production plan."""

    from app.services.hermes_agent.content_capabilities import (
        load_content_capability_manifest,
    )
    from app.services.hermes_agent.content_director_profile import (
        load_universal_director_profile,
    )
    from app.services.hermes_agent.content_production_compiler import (
        compile_production_plan_for_media,
    )
    from app.services.hermes_agent.content_production_plan_runtime import (
        run_content_production_plan_loop,
    )
    from app.services.hermes_agent.content_production_plan import (
        ProductionPlanReviewCriterion,
    )
    from app.services.hermes_agent.content_production_plan_store import (
        persist_content_production_plan_loop,
    )

    variant_index = _stage_variant_index(stage_row, project)
    artifact = _approved_director_artifact_for_variant(
        db,
        project,
        variant_index=variant_index,
    )
    _mode, _brief, policy = _director_stage_configuration(
        project,
        variant_index=variant_index,
    )
    asset_registry, authorized_refs, product_refs = (
        _production_plan_asset_authority(db, project)
    )
    manifest = load_content_capability_manifest()
    capability_catalog = [
        item.model_dump(mode="json")
        for item in manifest.capabilities
        if item.capability in {
            "visual.plan",
            "audio.design",
            "copy.delivery.plan",
        }
    ]
    selected_video_policy = _video_model_policy(project)
    for capability in capability_catalog:
        capability_name = str(capability.get("capability") or "")
        capability_policy = dict(capability.get("policy") or {})
        if capability_name == "visual.plan":
            capability_policy.update({
                "selected_video_model_id": str(selected_video_policy["id"]),
                "human_face_reference_mode": str(
                    selected_video_policy.get("human_face_reference_mode")
                    or "allowed"
                ),
                "allows_human_face_references": bool(
                    selected_video_policy.get("allows_human_face_references")
                ),
                "selected_model_hard_rules": list(
                    selected_video_policy.get("hard_rules") or []
                ),
                "reference_medium_rule": (
                    "Every generated reference containing a person must use "
                    "an unmistakably fictional adult 2D, 2.5D, or 3D animated "
                    "medium. The visual style_language and every human "
                    "generation_brief must say this explicitly and must not "
                    "request photorealistic, hyperreal, live-action, "
                    "photographic, or real-person-looking faces. Product "
                    "packaging remains materially faithful to its uploaded "
                    "authority."
                    if str(
                        selected_video_policy.get("human_face_reference_mode")
                        or ""
                    ) == "stylized_animation_only"
                    else "Use the user-confirmed visual medium."
                ),
            })
            capability["policy"] = capability_policy
            continue
        if capability_name != "audio.design":
            continue
        capability_policy.update({
            "selected_video_model_id": str(selected_video_policy["id"]),
            "supports_native_spoken_audio": bool(
                selected_video_policy.get("supports_native_spoken_audio")
            ),
            "preferred_spoken_delivery": str(
                selected_video_policy.get("preferred_spoken_delivery")
                or "local_voiceover"
            ),
            "native_spoken_audio_notes": str(
                selected_video_policy.get("native_spoken_audio_notes") or ""
            ),
            "local_voiceover_is_fallback_only": bool(
                selected_video_policy.get("supports_native_spoken_audio")
                and str(
                    selected_video_policy.get("preferred_spoken_delivery")
                    or ""
                ) == "provider_dialogue"
            ),
        })
        capability["policy"] = capability_policy
        break
    profile = load_universal_director_profile()
    stage_input = dict(stage_row.input_json or {})
    production_plan_external_repair = bool(
        stage_input.get("production_plan_external_repair")
    )
    if production_plan_external_repair:
        latest_director_stage_id = db.query(
            func.max(HermesContentFactoryStage.id)
        ).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "DIRECTOR",
            HermesContentFactoryStage.status == "success",
        ).scalar()
        latest_successful_plan_stage_id = db.query(
            func.max(HermesContentFactoryStage.id)
        ).filter(
            HermesContentFactoryStage.project_id == project.id,
            HermesContentFactoryStage.stage == "PRODUCTION_PLAN",
            HermesContentFactoryStage.status == "success",
        ).scalar()
        from app.services.hermes_agent.content_factory import (
            _production_plan_repair_matches_current_director_generation,
        )

        production_plan_external_repair = (
            _production_plan_repair_matches_current_director_generation(
                latest_director_stage_id=latest_director_stage_id,
                latest_successful_plan_stage_id=(
                    latest_successful_plan_stage_id
                ),
            )
        )
        if not production_plan_external_repair:
            stage_input["production_plan_external_repair"] = False
            stage_input.pop("production_plan_repair_instruction", None)
            stage_input["self_heal_action"] = (
                "generate_fresh_plan_for_new_director_generation"
            )
            stage_row.input_json = stage_input
            db.flush()
    recovery_attempt = int(
        stage_input.get("automatic_quality_recovery_attempt") or 0
    )
    recovery_generation = str(
        stage_input.get("automatic_quality_recovery_generation") or ""
    ).strip()
    recovery_idempotency_namespace = None
    if recovery_attempt > 0 and recovery_generation:
        recovery_idempotency_namespace = (
            f"{project.project_key}:variant:{int(variant_index)}:"
            f"production-plan:{recovery_generation}:attempt:{recovery_attempt}"
        )
    current_plan = None
    external_repair_brief = None
    if production_plan_external_repair:
        prior_bundle = _approved_production_plan_bundle_for_variant(
            db,
            project,
            variant_index=variant_index,
        )
        if prior_bundle is None:
            raise ValueError(
                "PRODUCTION_PLAN_EXTERNAL_REPAIR_SOURCE_MISSING: no accepted "
                "current plan exists for the requested visual repair"
            )
        current_plan = prior_bundle["plan"]
        external_repair_brief = str(
            stage_input.get("production_plan_repair_instruction")
            or stage_row.instruction
            or ""
        ).strip()
        if not external_repair_brief:
            raise ValueError(
                "PRODUCTION_PLAN_EXTERNAL_REPAIR_BRIEF_MISSING: visual repair "
                "requires pixel-grounded instructions"
            )
    production_plan_review_criteria = list(
        profile.production_plan_review_criteria
    )
    if bool(selected_video_policy.get("supports_native_spoken_audio")):
        production_plan_review_criteria.append(
            ProductionPlanReviewCriterion(
                criterion_id="native_spoken_performance_delivery",
                instruction=(
                    "Independently judge whether the plan uses the selected "
                    "video model's native expressive speech for approved spoken "
                    "copy. Provider dialogue is the default because voice emotion, "
                    "visible performance, and lip-sync or protagonist voiceover "
                    "must be generated together. Accept local_voiceover only when "
                    "the user explicitly requested post-dubbing or the plan cites "
                    "a concrete declared provider limitation."
                ),
                minimum_score=100,
                blocking=True,
            )
        )
    if _project_forbids_local_display_overlays(project):
        production_plan_review_criteria.append(
            ProductionPlanReviewCriterion(
                criterion_id="project_no_watermark_cover_overlays",
                instruction=(
                    "The saved project explicitly forbids top/bottom caption "
                    "bands, search bars, platform UI, and any overlay used to "
                    "imitate or cover a benchmark watermark. Keep all required "
                    "meaning in the approved spoken delivery or in physical "
                    "action/product pixels. Reject every local_overlay delivery "
                    "and every generated visual dependency on such bands."
                ),
                minimum_score=100,
                blocking=True,
            )
        )
    benchmark_hook_contract = _benchmark_opening_hook_contract(project)
    if benchmark_hook_contract:
        production_plan_review_criteria.append(
            ProductionPlanReviewCriterion(
                criterion_id="benchmark_multimodal_opening_hook_transfer",
                instruction=(
                    "The user explicitly requires the source video's abstract "
                    "opening-hook effectiveness to survive transformation. Compare "
                    "the production plan with the signed reference-transfer "
                    "observable_checks and transformation success_checks. Treat "
                    "the pixel-derived benchmark states as evidence only. Do not "
                    "turn benchmark suggestions into extra requirements, and never "
                    "require a mechanism named by must_not_reuse or "
                    "excluded_source_artifacts. Decide semantically whether the "
                    "plan's opening is strong and original, then choose the smallest "
                    "sufficient reference topology; do not demand a fixed number of "
                    "stills or require final-video motion/local copy inside one still. "
                    "hook_authority_and_evidence="
                    + json.dumps(
                        benchmark_hook_contract,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    )
                )[:2000],
                minimum_score=100,
                blocking=True,
            )
        )
    loop_result = asyncio.run(
        run_content_production_plan_loop(
            artifact=artifact,
            plan_id=(
                f"{project.project_key}.variant-"
                f"{int(variant_index):03d}.production"
            ),
            policy=policy,
            review_criteria=production_plan_review_criteria,
            capability_catalog=capability_catalog,
            authorized_asset_refs=authorized_refs,
            authoritative_product_asset_refs=product_refs,
            video_generation_mode=_configured_video_generation_mode(project),
            current_plan=current_plan,
            external_repair_brief=external_repair_brief,
            recovery_idempotency_namespace=(
                recovery_idempotency_namespace
            ),
            recovery_contract_errors=list(
                stage_input.get(
                    "automatic_quality_prior_contract_errors"
                )
                or []
            ),
        )
    )

    completion_stage, completion_project, _ = _lock_stage_delivery_scope(
        db,
        int(stage_row.id),
    )
    if completion_stage is None or completion_project is None:
        return {
            "status": "missing_completion_scope",
            "stage_id": int(stage_row.id),
        }
    stage_row = completion_stage
    project = completion_project
    if not _is_current_stage_delivery(
        stage_row,
        request_id=request_id,
        run_token=delivery_run_token,
    ):
        return {
            "status": "ignored_superseded_at_completion_fence",
            "stage_id": int(stage_row.id),
        }
    if not _stage_completion_pointer_is_authoritative(db, project, stage_row):
        return {
            "status": "ignored_stage_changed_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_stage": str(project.current_stage or ""),
        }
    latest_stage = _latest_stage(db, project, "PRODUCTION_PLAN")
    if latest_stage is not None and int(latest_stage.id) != int(stage_row.id):
        _retire_superseded_stage_row(
            db,
            stage_row,
            reason=(
                "Superseded at production-plan completion fence by stage "
                f"{int(latest_stage.id)}."
            ),
        )
        return {
            "status": "ignored_superseded_stage_at_completion_fence",
            "stage_id": int(stage_row.id),
            "latest_stage_id": int(latest_stage.id),
        }

    final_plan = loop_result.final_plan
    compiled_media_design = (
        compile_production_plan_for_media(
            artifact,
            final_plan,
            asset_registry=asset_registry,
            product_allowed=_project_uses_product(project),
        )
        if final_plan is not None
        else None
    )
    # Opening-hook quality is a semantic comparison between signed Producer
    # intent, the Director artifact, benchmark evidence and the proposed
    # visual plan.  The independent AI Critic now receives all four.  Do not
    # re-judge that decision here with a fixed reference-count heuristic: it
    # previously converted a model-approved, original hook into a quality
    # pause merely because it used fewer still anchors than the benchmark.
    audit_row = (
        persist_content_production_plan_loop(
            db,
            project=project,
            stage=stage_row,
            variant_index=variant_index,
            artifact=artifact,
            result=loop_result,
        )
        if final_plan is not None
        else None
    )
    result_payload = {
        "loop_status": loop_result.status,
        "production_plan": (
            final_plan.model_dump(mode="json")
            if final_plan is not None
            else None
        ),
        "compiled_media_design": compiled_media_design,
        "asset_registry": asset_registry,
        "audit_row_id": int(audit_row.id) if audit_row is not None else None,
        "plan_count": len(loop_result.plans),
        "director_attempt_count": len(loop_result.attempts),
        "critic_attempt_count": len(loop_result.critic_attempts),
        "review_count": len(loop_result.reviews),
        "contract_errors": list(loop_result.contract_errors),
        "reason": loop_result.reason,
    }
    evidence = {
        "execution_backend": "hermes_content_control_plane",
        "director_endpoint_role": "content_director",
        "critic_endpoint_role": "content_critic",
        "variant_index": int(variant_index),
        "content_factory_variant_index": int(variant_index),
        "director_artifact_sha256": artifact.artifact_sha256,
        "media_authorized": False,
        "attempts": [
            item.model_dump(mode="json") for item in loop_result.attempts
        ],
        "critic_attempts": [
            item.model_dump(mode="json")
            for item in loop_result.critic_attempts
        ],
        "reviews": [
            item.model_dump(mode="json") for item in loop_result.reviews
        ],
    }
    approved_next_stage = _configured_next_stage(project, "PRODUCTION_PLAN")
    stage_row.output_json = {
        "schema_version": "2.0",
        "project_id": project.project_key,
        "stage": "PRODUCTION_PLAN",
        "status": (
            "PASS"
            if loop_result.status == "approved"
            else "QUALITY_PAUSE"
        ),
        "result": result_payload,
        "evidence": evidence,
        "issues": (
            []
            if loop_result.status == "approved"
            else [{
                "code": "PRODUCTION_PLAN_QUALITY_PAUSE",
                "message": loop_result.reason,
            }]
        ),
        "repair_brief": None,
        "next_stage": (
            approved_next_stage
            if loop_result.status == "approved"
            else None
        ),
        "content_factory_variant_index": int(variant_index),
    }
    stage_row.response_text = (
        json.dumps(
            final_plan.model_dump(mode="json"),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        if final_plan is not None
        else None
    )
    stage_row.completed_at = _stage_now()

    manual_pause = (
        str(project.status or "").lower() == "paused"
        or bool(dict(project.config_json or {}).get("manual_paused", False))
    )
    if manual_pause:
        stage_row.status = "paused"
        stage_row.error_message = (
            "Paused manually while production planning was in flight; the "
            "signed plan and review evidence were preserved and no media "
            "stage was queued."
        )
        db.commit()
        return {
            "status": "paused_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    if loop_result.status != "approved" or final_plan is None:
        stage_row.status = "failed"
        stage_row.error_message = loop_result.reason[:4000]
        config = dict(project.config_json or {})
        config["manual_paused"] = False
        project.config_json = config
        state = dict(project.state_json or {})
        paused_at = _stage_now().isoformat()
        state.update({
            "paused_at": paused_at,
            "automatic_quality_paused_at": paused_at,
            "pause_reason_code": "production_plan_quality_pause",
            "quality_pause_source_code": "production_plan_quality_pause",
            "pause_note": loop_result.reason[:1000],
            "production_plan_quality_pause": {
                "variant_index": int(variant_index),
                "stage_id": int(stage_row.id),
                "autonomy_snapshot": _loop_quality_snapshot(loop_result),
                "at": paused_at,
            },
        })
        project.state_json = state
        project.status = "paused"
        project.current_stage = "PRODUCTION_PLAN"
        project.last_error = loop_result.reason[:4000]
        from app.services.hermes_agent.content_factory import (
            _record_project_transition,
            _release_bridge_for_project,
        )

        _record_project_transition(
            project,
            stage="PRODUCTION_PLAN",
            status="paused",
            reason="production_plan_quality_pause",
        )
        _release_bridge_for_project(db, project_id=int(project.id))
        db.commit()
        return {
            "status": "quality_pause",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    stage_row.status = "success"
    stage_row.error_message = None
    project.current_stage = approved_next_stage
    project.status = "ready"
    project.last_error = None
    state = dict(project.state_json or {})
    pointer = {
        "variant_index": int(variant_index),
        "plan_id": final_plan.plan_id,
        "plan_sha256": final_plan.plan_sha256,
        "director_artifact_sha256": artifact.artifact_sha256,
        "production_plan_stage_id": int(stage_row.id),
        "audit_row_id": int(audit_row.id),
    }
    by_variant = dict(
        state.get("approved_production_plans_by_variant") or {}
    )
    by_variant[str(int(variant_index))] = pointer
    state["approved_production_plans_by_variant"] = by_variant
    state["approved_production_plan"] = pointer
    state = _mark_automatic_quality_recovery_resolved(
        state,
        stage_name="PRODUCTION_PLAN",
        stage_id=int(stage_row.id),
        variant_index=int(variant_index),
    )
    project.state_json = state
    from app.services.hermes_agent.content_factory import _record_project_transition

    _record_project_transition(
        project,
        stage=approved_next_stage,
        status="ready",
        reason="production_plan_approved",
    )
    continue_workflow = bool(
        dict(stage_row.input_json or {}).get("continue_workflow", True)
    )
    db.commit()
    if continue_workflow:
        from app.services.hermes_agent.content_factory import queue_stage

        if release_guard_before_successor is not None:
            release_guard_before_successor()
        queue_stage(
            db,
            project=project,
            user_id=int(project.user_id or stage_row.user_id or 1),
            instruction=(
                "Compile and submit the approved production plan directly "
                "as text-to-video segments without generating, extracting, "
                "uploading, or attaching reference media."
                if approved_next_stage == "VIDEO_PROMPTS"
                else
                "Generate only the approved production plan's declared "
                "visual reference intents."
            ),
            target_stage=approved_next_stage,
            continue_workflow=True,
        )
        db.commit()
    return {
        "status": "success",
        "stage_id": int(stage_row.id),
        "project_key": project.project_key,
        "next_stage": approved_next_stage,
        "plan_sha256": final_plan.plan_sha256,
    }


def _run_content_segment_compile_stage(
    db,
    *,
    stage_row: HermesContentFactoryStage,
    project: HermesContentFactoryProject,
    request_id: str,
    delivery_run_token: str,
) -> dict[str, Any]:
    """Compile one accepted plan locally and submit its provider segments.

    ``VIDEO_PROMPTS`` remains the historical database checkpoint during the
    bounded migration, but it is no longer a model-authoring stage for
    Director-enforced projects.  No text API, browser, or fourth creative
    authority is allowed on this path.
    """

    from app.services.hermes_agent.content_production_compiler import (
        compile_production_plan_to_video_result,
    )

    variant_index = _stage_variant_index(stage_row, project)
    bundle = _approved_production_plan_bundle_for_variant(
        db,
        project,
        variant_index=variant_index,
    )
    if bundle is None:
        raise ValueError(
            "SEGMENT_COMPILE_SIGNED_PLAN_MISSING: an enforced Director "
            "project cannot compile media from a legacy creative payload"
        )
    artifact = bundle["artifact"]
    plan = bundle["plan"]
    video_policy = _video_model_policy(project)
    result = compile_production_plan_to_video_result(
        artifact,
        plan,
        variant_index=variant_index,
        resolution=_configured_video_resolution(project),
        language_label=_video_language_label(project),
        reference_image_limit=int(video_policy["reference_limit"]),
        product_allowed=_project_uses_product(project),
    )
    envelope = {
        "schema_version": "3.0",
        "project_id": project.project_key,
        "stage": "VIDEO_PROMPTS",
        "status": "PASS",
        "result": result,
        "evidence": {
            "execution_backend": "local_signed_segment_compiler",
            "creative_authority": "content_showrunner",
            "compiler_authority": "runtime",
            "model_authoring_used": False,
            "browser_used": False,
            "variant_index": int(variant_index),
            "content_factory_variant_index": int(variant_index),
            "director_artifact_sha256": artifact.artifact_sha256,
            "director_script_sha256": (
                artifact.script.canonical_text_sha256
            ),
            "production_plan_sha256": plan.plan_sha256,
            "production_plan_stage_id": int(
                bundle["production_plan_stage_id"]
            ),
            "production_plan_audit_id": int(
                bundle["production_plan_audit_id"]
            ),
        },
        "issues": [],
        "repair_brief": None,
        "next_stage": "WAITING_VIDEO_INPUT",
        "content_factory_variant_index": int(variant_index),
    }

    # Reuse the downstream transport validator before a single billable task
    # is created.  This proves exact segment count, local timing, script lock,
    # and reference-index bounds against the real project configuration.
    _normalize_video_plan(
        project,
        envelope,
        variant_index=variant_index,
    )

    completion_stage, completion_project, _ = _lock_stage_delivery_scope(
        db,
        int(stage_row.id),
    )
    if completion_stage is None or completion_project is None:
        return {
            "status": "missing_completion_scope",
            "stage_id": int(stage_row.id),
        }
    stage_row = completion_stage
    project = completion_project
    if not _is_current_stage_delivery(
        stage_row,
        request_id=request_id,
        run_token=delivery_run_token,
    ):
        return {
            "status": "ignored_superseded_at_completion_fence",
            "stage_id": int(stage_row.id),
        }
    if str(project.current_stage or "") != "VIDEO_PROMPTS":
        return {
            "status": "ignored_stage_changed_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_stage": str(project.current_stage or ""),
        }
    if str(project.status or "").lower() == "deleted":
        return {
            "status": "ignored_deleted_at_completion_fence",
            "stage_id": int(stage_row.id),
        }
    latest_stage = _latest_stage(db, project, "VIDEO_PROMPTS")
    if latest_stage is not None and int(latest_stage.id) != int(stage_row.id):
        _retire_superseded_stage_row(
            db,
            stage_row,
            reason=(
                "Superseded at segment-compile completion fence by stage "
                f"{int(latest_stage.id)}."
            ),
        )
        return {
            "status": "ignored_superseded_stage_at_completion_fence",
            "stage_id": int(stage_row.id),
            "latest_stage_id": int(latest_stage.id),
        }

    manual_pause = (
        str(project.status or "").lower() == "paused"
        or bool(dict(project.config_json or {}).get("manual_paused", False))
    )
    stage_row.output_json = envelope
    stage_row.response_text = json.dumps(
        envelope,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    if manual_pause:
        stage_row.status = "paused"
        stage_row.completed_at = _stage_now()
        stage_row.error_message = (
            "Paused manually at the segment-compile completion fence; no "
            "provider task was created."
        )
        db.commit()
        return {
            "status": "paused_at_completion_fence",
            "stage_id": int(stage_row.id),
            "project_key": project.project_key,
        }

    _record_stage_quality_learning(
        db,
        project,
        stage_row,
        envelope,
        [],
    )
    # Keep the project visibly inside its running VIDEO_PROMPTS delivery while
    # the multimodal provider-prompt authoring pass is in flight.  Routing
    # telemetry may commit on the shared session; exposing a successful stage
    # and WAITING_VIDEO_INPUT here would let self-heal mistake normal authoring
    # latency for a lost provider submission.  _queue_ai_video_tasks publishes
    # the successful source row together with the first durable task ledger.
    stage_row.error_message = None
    project.last_error = None
    task_ids = _queue_ai_video_tasks(
        db,
        project,
        envelope,
        variant_index=variant_index,
        source_stage_id=int(stage_row.id),
    )
    return {
        "status": "success",
        "project_key": project.project_key,
        "next_stage": "WAITING_VIDEO_INPUT",
        "ai_video_task_ids": task_ids,
        "execution_backend": "local_signed_segment_compiler",
    }


@celery_app.task(
    bind=True,
    name="hermes_content_factory.run_stage",
    queue=settings.HERMES_AGENT_TASK_QUEUE,
    max_retries=3,
    soft_time_limit=CONTENT_FACTORY_TASK_FALLBACK_SOFT_LIMIT,
    time_limit=CONTENT_FACTORY_TASK_FALLBACK_HARD_LIMIT,
)
def run_content_factory_stage(self, *, stage_id: int, run_token: str | None = None):
    db = SessionLocal()
    request_id = str(getattr(self.request, "id", "") or "")
    delivery_run_token = str(run_token or "").strip()
    execution_guard = None
    # Pre-routing integrity gates run before ``stage_execution_backend`` is
    # resolved.  Their failure must enter the normal bounded retry/recovery
    # path instead of raising a second UnboundLocalError in the exception
    # classifier.
    execution_backend = "unresolved"
    guarded_project_id = 0
    claim_committed = False
    try:
        stage_row, project, scoped_project_id = _lock_stage_delivery_scope(
            db,
            int(stage_id),
        )
        if scoped_project_id is not None:
            guarded_project_id = int(scoped_project_id)
        if scoped_project_id is None:
            return {"status": "missing"}
        if project is None:
            return {"status": "missing_project"}
        if stage_row is None:
            return {"status": "missing_stage"}
        if str(project.status or "").lower() == "deleted":
            if str(stage_row.status or "").lower() in {
                "queued", "running", "retrying",
            }:
                stage_row.status = "failed"
                stage_row.error_message = (
                    "Project was deleted before this delivery started."
                )
                stage_row.completed_at = _stage_now()
                db.commit()
            return {
                "status": "ignored_deleted_project",
                "stage_id": int(stage_row.id),
            }
        guarded_project_id = int(project.id)
        guard_acquired, execution_guard = _acquire_project_execution_guard(db, guarded_project_id)
        if not guard_acquired:
            deferred = _reschedule_current_stage_after_execution_lock_collision(
                db,
                project,
                stage_row,
                request_id=request_id,
                delivery_run_token=delivery_run_token,
            )
            if deferred is not None:
                return deferred
            return {
                "status": "ignored_project_execution_locked",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
            }
        current_run_token = _stage_run_token(stage_row)
        registered_task_id = str(stage_row.celery_task_id or "")
        if current_run_token and delivery_run_token != current_run_token:
            if registered_task_id and request_id and registered_task_id == request_id:
                pass
            else:
                return {
                    "status": "ignored_superseded_token",
                    "stage_id": int(stage_row.id),
                    "registered_run_token": current_run_token,
                    "request_run_token": delivery_run_token,
                    "registered_task_id": registered_task_id,
                    "request_id": request_id,
                }
        if registered_task_id and request_id and registered_task_id != request_id:
            claim_input = dict(stage_row.input_json or {})
            retry_release_id = str(claim_input.get("retry_release_task_id") or "").strip()
            has_retry_timer = bool(str(claim_input.get("retry_after") or "").strip())
            if stage_row.status in {"queued", "retrying"} and (
                registered_task_id == retry_release_id or has_retry_timer
            ):
                stage_row.celery_task_id = request_id
                registered_task_id = request_id
            else:
                return {
                    "status": "ignored_superseded",
                    "stage_id": int(stage_row.id),
                    "registered_task_id": registered_task_id,
                    "request_id": request_id,
                }
        resume_registered_running = (
            stage_row.status == "running"
            and bool(registered_task_id)
            and bool(request_id)
            and registered_task_id == request_id
        )
        if stage_row.status not in {"queued", "retrying"} and not resume_registered_running:
            return {"status": "ignored_stale", "stage_id": int(stage_row.id), "stage_status": stage_row.status}
        if project.status == "paused" or bool(dict(project.config_json or {}).get("manual_paused", False)):
            return {"status": "ignored_paused", "stage_id": int(stage_row.id), "project_key": project.project_key}
        if (
            stage_row.stage in VARIANT_STAGES
            and not _variant_rollout_authorized(
                project,
                _stage_variant_index(stage_row, project),
            )
        ):
            now = _stage_now()
            variant_index = _stage_variant_index(stage_row, project)
            stage_row.status = "paused"
            stage_row.completed_at = now
            stage_row.error_message = (
                "CONTENT_ROLLOUT_GATE_VARIANT_NOT_AUTHORIZED: "
                f"variant {variant_index} is outside the current project release manifest"
            )
            state = dict(project.state_json or {})
            state.update({
                "paused_at": now.isoformat(),
                "automatic_quality_paused_at": now.isoformat(),
                "pause_reason_code": "variant_rollout_not_authorized",
                "pause_note": stage_row.error_message,
                "browser_slot_mode": "dormant",
            })
            project.state_json = state
            project.status = "paused"
            project.last_error = stage_row.error_message
            from app.services.hermes_agent.content_factory import (
                _release_bridge_for_project,
            )

            _release_bridge_for_project(db, project_id=int(project.id))
            db.commit()
            return {
                "status": "paused_variant_not_authorized",
                "stage_id": int(stage_row.id),
                "variant_index": int(variant_index),
                "project_key": project.project_key,
            }
        if project.status == "running" and not resume_registered_running:
            return {
                "status": "ignored_project_locked",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
                "project_status": project.status,
            }
        if project.current_stage != stage_row.stage:
            return {
                "status": "ignored_stale",
                "stage_id": int(stage_row.id),
                "project_stage": project.current_stage,
                "task_stage": stage_row.stage,
            }
        latest_stage = _latest_stage(db, project, project.current_stage)
        if latest_stage is not None and int(latest_stage.id) != int(stage_row.id):
            stage_row.status = "failed"
            stage_row.error_message = (
                f"Superseded by newer {project.current_stage} stage {int(latest_stage.id)}; "
                "old broker delivery ignored before touching the browser."
            )
            db.commit()
            return {
                "status": "ignored_superseded_stage",
                "stage_id": int(stage_row.id),
                "latest_stage_id": int(latest_stage.id),
                "stage": stage_row.stage,
            }
        if stage_row.stage in {"VIDEO_PROMPTS", "EDIT_PACKAGE"}:
            complete, expected_count, actual_count = _final_assets_are_complete(db, project)
            if not complete:
                raise ValueError(
                    f"FINAL_ASSETS_INVALID: expected {expected_count} final reference images, "
                    f"found {actual_count}. Rebuild final assets before continuing."
                )
        # Retry rows may have been published by an older worker or restored
        # from a durable response capture.  Canonicalize policy authority
        # before any routing, replay, provider, or cooldown decision.
        stage_input = _restamp_stage_runtime_policy(stage_row.input_json)
        if stage_row.stage == "VISUAL_PREVIEW":
            director_media_authorization = (
                _assert_director_media_authorization(
                    db,
                    project,
                    variant_index=_stage_variant_index(stage_row, project),
                )
            )
            if director_media_authorization is not None:
                stage_input["director_media_authorization"] = (
                    director_media_authorization
                )
        stage_row.input_json = stage_input
        db.commit()
        stage_input = clear_external_retry_barriers_for_local_stage(
            stage_row.stage,
            stage_input,
        )
        stage_row.input_json = stage_input
        db.commit()
        local_final_assets_split = is_local_worker_stage(
            stage_row.stage,
            stage_input,
        )
        if local_final_assets_split:
            # FINAL_ASSETS normally materializes the already-approved native
            # references on local RAID.  It neither needs an AI route nor a
            # browser slot.  Sending a retry through provider cooldown
            # selection can strand complete local evidence behind an unrelated
            # upstream outage and makes the Recovery Supervisor wait for an API
            # that this stage will never call.
            api_route = None
            execution_backend = "local_reference_split"
        else:
            api_route = _content_factory_api_route(
                db,
                stage_row.stage,
                stage_input,
            )
            execution_backend = stage_execution_backend(
                stage_row.stage,
                api_route=api_route,
                stage_input=stage_input,
            )
            if execution_backend == "browser":
                api_route = None
        if stage_row.stage == "VISUAL_PREVIEW":
            inherited_route = _visual_variant_api_route(
                db,
                project,
                variant_index=_stage_variant_index(stage_row, project),
                default_route=api_route,
            )
            inherited_provider = _visual_api_provider_from_route(
                inherited_route
            )
            current_provider_failures = _visual_api_failed_providers(
                stage_input
            )
            if (
                inherited_route
                and inherited_route != api_route
                and inherited_provider
                and inherited_provider not in current_provider_failures
                and inherited_route
                in _configured_visual_api_routes(
                    db, stage_input, include_failed=True
                )
                and _visual_api_recovery_epoch(stage_input) <= 0
            ):
                # Older queued rows may have been created before provider
                # inheritance was deployed. Migrate them at the final
                # pre-submit boundary so a same-variant concept replan cannot
                # spend on the provider whose circuit was already exhausted.
                stage_input = _prepare_visual_api_provider_inheritance(
                    stage_input,
                    to_provider=inherited_provider,
                    to_route=inherited_route,
                )
                stage_row.input_json = stage_input
                api_route = inherited_route
                execution_backend = "api"
                db.commit()
            provider_budget_exhausted = _visual_api_provider_budget_exhausted(
                stage_row.stage,
                stage_input,
            )
            next_route = (
                _next_visual_api_route(
                    db,
                    current_route=api_route,
                    stage_input=stage_input,
                )
                if provider_budget_exhausted
                else None
            )
            if provider_budget_exhausted and next_route:
                current_provider = _visual_api_provider_from_route(api_route)
                next_provider = _visual_api_provider_from_route(next_route)
                stage_input = _prepare_visual_api_provider_failover(
                    stage_input,
                    from_provider=current_provider,
                    to_provider=next_provider,
                    error=(
                        f"{current_provider} image API exhausted its bounded "
                        "provider retry budget."
                    ),
                    account_quota_exhausted=False,
                    from_route=api_route,
                    to_route=next_route,
                )
                stage_row.input_json = stage_input
                api_route = next_route
                execution_backend = "api"
                db.commit()
            elif (
                bool(stage_input.get("visual_api_force_browser_fallback"))
                or provider_budget_exhausted
            ):
                # Route exhaustion is an incident, not authority to select a
                # browser.  The recovery supervisor owns that decision and may
                # instead wait for a configured API inventory to cool down.
                # Do not persist the former force-browser marker here: it
                # poisoned later probes by making the API router look disabled.
                return _handoff_api_stage_to_browser(
                    db,
                    project,
                    stage_row,
                    reason="Every available image API exhausted its bounded provider retry budget.",
                )
        needs_browser = execution_backend == "browser" and stage_row.stage in set(ROLE_URLS.keys())
        if needs_browser and not _browser_cdp_reachable_for_stage(db, project, stage_input):
            recovery = _recover_browser_fault_with_supervisor(
                db,
                project,
                stage_row,
                reason=(
                    "Browser bridge CDP is not reachable; the selected "
                    "browser route cannot execute this stage."
                ),
            )
            if recovery is not None:
                return recovery
            # Only an explicit RETRY_BROWSER decision can reach this fallback.
            stage_row.status = "failed"
            stage_row.completed_at = _stage_now()
            stage_row.error_message = (
                "Browser bridge CDP is not reachable; waiting for this user's local bridge to reconnect."
            )
            project.status = "waiting_bridge"
            project.current_stage = stage_row.stage
            project.last_error = (
                "Browser bridge is offline or stale; Hermes will resume after this user's local bridge reconnects."
            )
            db.commit()
            return {
                "status": "waiting_bridge",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
                "stage": stage_row.stage,
            }
        stage_row.status = "running"
        stage_row.error_message = None
        stage_row.started_at = _stage_now()
        _stamp_stage_execution_budget(
            stage_row,
            project,
            now=stage_row.started_at,
        )
        if request_id:
            stage_row.celery_task_id = request_id
        project.status = "running"
        db.commit()
        claim_committed = True

        def _release_dedicated_successor_guard() -> None:
            nonlocal execution_guard
            _release_project_execution_guard(
                execution_guard,
                guarded_project_id,
            )
            execution_guard = None

        if stage_row.stage == "SERIES_DIRECTOR":
            return _run_content_series_director_stage(
                db,
                stage_row=stage_row,
                project=project,
                request_id=request_id,
                delivery_run_token=delivery_run_token,
                release_guard_before_successor=(
                    _release_dedicated_successor_guard
                ),
            )
        if stage_row.stage == "DIRECTOR":
            return _run_content_director_stage(
                db,
                stage_row=stage_row,
                project=project,
                request_id=request_id,
                delivery_run_token=delivery_run_token,
                release_guard_before_successor=(
                    _release_dedicated_successor_guard
                ),
            )
        if stage_row.stage == "PRODUCTION_PLAN":
            return _run_content_production_plan_stage(
                db,
                stage_row=stage_row,
                project=project,
                request_id=request_id,
                delivery_run_token=delivery_run_token,
                release_guard_before_successor=(
                    _release_dedicated_successor_guard
                ),
            )
        if (
            stage_row.stage == "VIDEO_PROMPTS"
            and _content_director_enforced(project)
        ):
            return _run_content_segment_compile_stage(
                db,
                stage_row=stage_row,
                project=project,
                request_id=request_id,
                delivery_run_token=delivery_run_token,
            )

        direct_files: list[str] = []
        direct_chat_url = None
        api_meta: dict[str, Any] = {}
        final_asset_capture_origin = (
            "assistant_generated_final_assets"
            if stage_row.stage == "FINAL_ASSETS" and bool(stage_input.get("force_chatgpt_rebuild"))
            else "validated_preview_split"
        )
        if stage_row.stage == "FINAL_ASSETS" and not bool(stage_input.get("force_chatgpt_rebuild")):
            direct_files = _split_approved_preview(
                db,
                project,
                variant_index=_stage_variant_index(stage_row, project),
            )
            text = ""
        else:
            try:
                packet = _stage_packet(
                    db,
                    project,
                    stage_row,
                    prepare_browser=execution_backend == "browser",
                )
            except _CreativeReviewReferencesIncomplete as reference_exc:
                # This is a local dependency failure, not a text-provider
                # failure.  Do not call the review model with only the product
                # anchor, do not consume API/browser retry budgets, and do not
                # activate a browser slot.  Rebuild the missing current-variant
                # visual references directly.
                stage_row.status = "failed"
                stage_row.completed_at = _stage_now()
                stage_row.error_message = str(reference_exc)[:4000]
                repair_stage = _create_repair_stage(
                    db,
                    project,
                    "VISUAL_PREVIEW",
                    reason=str(reference_exc),
                )
                repair_input = dict(repair_stage.input_json or {})
                repair_input.update({
                    "force_fresh_response": True,
                    "self_heal_action": (
                        "rebuild_missing_visual_references_before_creative_review"
                    ),
                    "creative_review_preflight_blocked_stage_id": int(stage_row.id),
                })
                repair_stage.input_json = repair_input
                db.commit()
                # The failed stage is already durable.  Its replacement must
                # not be published while this delivery still owns the project
                # advisory lock, otherwise the successor is consumed
                # immediately, collides with us, and waits for the next
                # one-minute healer pass despite a two-second cooldown.
                _release_project_execution_guard(
                    execution_guard,
                    guarded_project_id,
                )
                execution_guard = None
                task_id = _publish_stage(repair_stage, project)
                db.commit()
                return {
                    "status": "self_healed_missing_review_references",
                    "stage_id": int(repair_stage.id),
                    "stage": repair_stage.stage,
                    "task_id": task_id,
                }
            packet, authoritative_previous_variant_briefs = (
                _prepare_stage_packet_for_execution(packet, stage_row.stage)
            )
            db.commit()
            persisted_response = None
            replay_source_stage_id = None
            previous_replay_context_digest = str(
                stage_input.get("replay_context_digest") or ""
            )
            replay_context_digest = _stage_replay_context_digest(
                packet,
                stage_row.stage,
            )
            stage_input["replay_context_digest"] = replay_context_digest
            stage_row.input_json = stage_input
            db.commit()
            # A stage may be superseded while this worker was compiling its
            # packet or waiting on its DB commit.  Do the ownership check
            # immediately before any remote request, not only after a remote
            # result returns.  Otherwise stale retry deliveries can keep
            # spending API calls after a manual/automatic replacement stage
            # has already won the project lease.
            db.refresh(stage_row)
            db.refresh(project)
            if (
                not _is_current_stage_delivery(
                    stage_row,
                    request_id=request_id,
                    run_token=delivery_run_token,
                )
                or project.current_stage != stage_row.stage
            ):
                return {
                    "status": "ignored_superseded_before_remote_execution",
                    "stage_id": int(stage_row.id),
                    "stage_status": str(stage_row.status),
                    "project_stage": project.current_stage,
                    "task_stage": stage_row.stage,
                }
            if (
                not bool(stage_input.get("discard_durable_response_capture"))
                and not bool(stage_input.get("force_fresh_response"))
            ):
                if (
                    not previous_replay_context_digest
                    or previous_replay_context_digest == replay_context_digest
                ):
                    persisted_response = _recover_completed_stage_response(
                        stage_row.response_text,
                        project.project_key,
                        stage_row.stage,
                    )
                if persisted_response is None:
                    prior_capture = _recover_prior_stage_attempt_response(
                        db,
                        project,
                        stage_row,
                        replay_context_digest=replay_context_digest,
                    )
                    if prior_capture is not None:
                        persisted_response, prior_chat_url, replay_source_stage_id = prior_capture
                        stage_row.response_text = persisted_response
                        stage_row.chat_url = prior_chat_url or stage_row.chat_url
            if persisted_response is not None:
                text = persisted_response
                direct_chat_url = stage_row.chat_url
                direct_files = []
                stage_input["replayed_durable_response_capture"] = True
                if replay_source_stage_id is not None:
                    stage_input["replayed_prior_stage_capture_id"] = replay_source_stage_id
                    stage_input["self_heal_action"] = "revalidate_prior_complete_response_without_resubmission"
                stage_row.input_json = stage_input
                db.commit()
            elif _is_visual_api_route(api_route):
                try:
                    direct_files, api_meta = _generate_visual_preview_with_failover(
                        db,
                        project,
                        stage_row,
                        packet,
                        api_route=api_route,
                        expected_request_id=request_id,
                        expected_run_token=delivery_run_token,
                    )
                    text = ""
                    _clear_api_stage_failures(project, stage_row.stage)
                    db.commit()
                except _SupersededVisualProviderSubmission as stale_exc:
                    db.rollback()
                    return {
                        "status": "ignored_superseded_before_provider_submit",
                        "stage_id": int(stage_row.id),
                        "reason": str(stale_exc),
                    }
                except Exception as api_exc:  # noqa: BLE001
                    stage_input = dict(stage_row.input_json or {})
                    failure_route = str(stage_input.get("api_route") or api_route)
                    stage_input["api_primary_error"] = {
                        "route": failure_route,
                        "message": str(api_exc)[:1600],
                        "at": _stage_now().isoformat(),
                    }
                    stage_row.input_json = stage_input
                    failure_count = _record_api_stage_failure(project, stage_row.stage, api_exc)
                    db.commit()
                    if _visual_api_account_quota_exhausted(
                        stage_row.stage,
                        str(api_exc),
                    ):
                        # The image generator has already persisted the failed
                        # reference and cleared its unusable provider task id.
                        # Mark the API budget terminal now so retry release
                        # cannot reacquire an API-only route for the same empty
                        # account. Approved partial references remain intact.
                        quota_input = dict(stage_row.input_json or stage_input)
                        quota_state = dict(quota_input.get("visual_api") or {})
                        maximum = max(
                            1,
                            int(os.getenv("HERMES_VISUAL_API_PROVIDER_MAX_RETRIES", "3")),
                        )
                        quota_state.update({
                            "status": "failed",
                            "task_id": None,
                            "provider_retry_generation": maximum + 1,
                            "account_quota_exhausted": True,
                            "account_quota_exhausted_at": _stage_now().isoformat(),
                            "last_error": str(api_exc)[:800],
                        })
                        quota_input["visual_api"] = quota_state
                        quota_input["self_heal_action"] = (
                            "browser_fallback_after_visual_api_account_quota"
                        )
                        stage_row.input_json = quota_input
                        db.commit()
                        return _handoff_api_stage_to_browser(
                            db,
                            project,
                            stage_row,
                            reason=str(api_exc),
                        )
                    visual_api_state = dict(stage_input.get("visual_api") or {})
                    has_failed_individual_reference = any(
                        str(dict(value or {}).get("status") or "").lower() == "failed"
                        for value in dict(visual_api_state.get("boards") or {}).values()
                        if isinstance(value, dict)
                    )
                    if (
                        has_failed_individual_reference
                        or str(visual_api_state.get("task_id") or "").strip()
                    ):
                        # A billable provider task already exists. Keep polling
                        # successful individual tasks and retry only failed
                        # references; never send this mixed state to browser.
                        raise
                    # Generic project/stage failure history includes the
                    # provider we already left behind. It is diagnostic only:
                    # browser fallback is legal here solely when the currently
                    # selected final image API has exhausted its own persisted
                    # per-reference retry generations.
                    if _visual_api_final_provider_budget_exhausted(
                        stage_row.stage,
                        dict(stage_row.input_json or stage_input),
                        api_route=failure_route,
                        db=db,
                    ):
                        return _handoff_api_stage_to_browser(
                            db, project, stage_row, reason=str(api_exc)
                        )
                    raise
            elif api_route == "toapis:text":
                try:
                    text, api_meta = execute_text_stage_api(
                        db,
                        packet,
                        stage_row.stage,
                    )
                    direct_chat_url = None
                    direct_files = []
                    _clear_api_stage_failures(project, stage_row.stage)
                    db.commit()
                except Exception as api_exc:  # noqa: BLE001
                    if (
                        stage_row.stage == "CREATIVE_REVIEW"
                        and any(
                            marker in str(api_exc)
                            for marker in (
                                "CREATIVE_REVIEW reference_checks contract incomplete",
                                "CREATIVE_REVIEW benchmark_hook_transfer contract incomplete",
                            )
                        )
                    ):
                        # The reviewer returned a structurally incomplete
                        # envelope.  This is a semantic response-regeneration
                        # request handled by the outer bounded retry path, not
                        # evidence that the text API is unhealthy and not a
                        # reason to redraw already-generated references.
                        raise
                    stage_input = dict(stage_row.input_json or {})
                    stage_input["api_primary_error"] = {
                        "route": api_route,
                        "message": str(api_exc)[:1600],
                        "at": _stage_now().isoformat(),
                    }
                    stage_input.update(
                        _text_api_transport_retry_plan(stage_input)
                    )
                    stage_input["self_heal_action"] = (
                        "rotate_text_api_model_after_transport_failure"
                    )
                    stage_input["self_heal_policy_version"] = (
                        SELF_HEAL_POLICY_VERSION
                    )
                    stage_row.input_json = stage_input
                    _record_api_stage_failure(project, stage_row.stage, api_exc)
                    db.commit()
                    if _text_api_transport_budget_exhausted(stage_input):
                        return _handoff_api_stage_to_browser(
                            db, project, stage_row, reason=str(api_exc)
                        )
                    raise
            else:
                try:
                    text, direct_chat_url, direct_files = execute_chatgpt_stage(packet)
                except Exception as browser_exc:
                    recovered_text = _recover_completed_text_from_browser_error(
                        browser_exc,
                        project.project_key,
                        stage_row.stage,
                    )
                    if recovered_text is not None:
                        text = recovered_text
                        direct_chat_url = str(getattr(browser_exc, "chat_url", "") or "") or None
                        direct_files = []
                    else:
                        # Every semantic artifact must come from the routed model.
                        # Transport recovery may retry or change provider, but it may
                        # not synthesize a creative deliverable on the server.
                        raise
        db.refresh(stage_row)
        db.refresh(project)
        if str(project.status or "").lower() == "deleted":
            return {
                "status": "ignored_deleted_after_provider",
                "stage_id": int(stage_row.id),
            }
        if not _is_current_stage_delivery(stage_row, request_id=request_id, run_token=delivery_run_token):
            return {
                "status": "ignored_superseded_after_browser",
                "stage_id": int(stage_row.id),
                "registered_task_id": str(stage_row.celery_task_id or ""),
                "request_id": request_id,
                "registered_run_token": _stage_run_token(stage_row),
                "request_run_token": delivery_run_token,
            }
        latest_after_browser = _latest_stage(db, project, project.current_stage)
        if latest_after_browser is not None and int(latest_after_browser.id) != int(stage_row.id):
            _retire_superseded_stage_row(
                db,
                stage_row,
                reason=(
                    f"Superseded after provider return by stage {int(latest_after_browser.id)} "
                    f"({latest_after_browser.stage}); stale result was ignored."
                ),
            )
            return {
                "status": "ignored_superseded_stage_after_browser",
                "stage_id": int(stage_row.id),
                "latest_stage_id": int(latest_after_browser.id),
                "stage": stage_row.stage,
            }
        if project.status == "paused" or bool(dict(project.config_json or {}).get("manual_paused", False)):
            stage_row.status = "paused"
            stage_row.error_message = "Paused manually after browser returned; result was not advanced."
            db.commit()
            return {"status": "paused_after_browser", "stage_id": int(stage_row.id), "project_key": project.project_key}
        registered_task_id = str(stage_row.celery_task_id or "")
        if registered_task_id and request_id and registered_task_id != request_id:
            return {
                "status": "ignored_superseded_after_browser",
                "stage_id": int(stage_row.id),
                "registered_task_id": registered_task_id,
                "request_id": request_id,
            }
        if project.current_stage != stage_row.stage:
            return {
                "status": "ignored_stage_changed_after_browser",
                "stage_id": int(stage_row.id),
                "project_stage": project.current_stage,
                "task_stage": stage_row.stage,
            }
        captured_response = _persist_completed_stage_capture(
            db,
            stage_row,
            project_key=project.project_key,
            stage=stage_row.stage,
            response_text=text,
            chat_url=direct_chat_url,
            replace_with_incoming_complete=bool(
                stage_input.get("force_fresh_response")
                or int(stage_input.get("api_regeneration_generation") or 0) > 0
            ),
        )
        if captured_response is not None:
            text = captured_response

        # ``_persist_completed_stage_capture`` deliberately commits the raw
        # completed response before semantic validation so a validation error
        # can be repaired without paying for another model turn.  That commit
        # also ends the transaction used by the first post-provider pause
        # check.  Reacquire and refresh project->stage locks here, then keep
        # them through validation, asset import, and the workflow transition.
        # A manual pause racing this boundary therefore always wins:
        #
        # * pause commits first -> this fresh fence observes it and stops;
        # * stage commits first -> pause waits, then overwrites the completed
        #   transition and pauses any successor that was queued.
        completion_stage, completion_project, _completion_project_id = (
            _lock_stage_delivery_scope(db, int(stage_row.id))
        )
        if completion_stage is None or completion_project is None:
            return {
                "status": "missing_completion_scope",
                "stage_id": int(stage_row.id),
            }
        stage_row = completion_stage
        project = completion_project
        if not _is_current_stage_delivery(
            stage_row,
            request_id=request_id,
            run_token=delivery_run_token,
        ):
            return {
                "status": "ignored_superseded_at_completion_fence",
                "stage_id": int(stage_row.id),
                "stage_status": str(stage_row.status or ""),
                "registered_task_id": str(stage_row.celery_task_id or ""),
                "request_id": request_id,
            }
        if (
            str(project.status or "").lower() == "paused"
            or bool(dict(project.config_json or {}).get("manual_paused", False))
        ):
            stage_row.status = "paused"
            stage_row.error_message = (
                "Paused manually after provider return; captured response was "
                "preserved but workflow state was not advanced."
            )
            db.commit()
            return {
                "status": "paused_at_completion_fence",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
            }
        if not _stage_completion_pointer_is_authoritative(db, project, stage_row):
            return {
                "status": "ignored_stage_changed_at_completion_fence",
                "stage_id": int(stage_row.id),
                "project_stage": str(project.current_stage or ""),
                "task_stage": str(stage_row.stage or ""),
            }
        latest_at_completion = _latest_stage(
            db,
            project,
            str(stage_row.stage or ""),
        )
        if (
            latest_at_completion is not None
            and int(latest_at_completion.id) != int(stage_row.id)
        ):
            _retire_superseded_stage_row(
                db,
                stage_row,
                reason=(
                    "Superseded at final completion fence by stage "
                    f"{int(latest_at_completion.id)} "
                    f"({latest_at_completion.stage}); stale result was ignored."
                ),
            )
            return {
                "status": "ignored_superseded_stage_at_completion_fence",
                "stage_id": int(stage_row.id),
                "latest_stage_id": int(latest_at_completion.id),
                "stage": stage_row.stage,
            }
        try:
            envelope = _extract_envelope(text, project.project_key, stage_row.stage)
        except ValueError:
            if not direct_files:
                raise
            if stage_row.stage == "VISUAL_PREVIEW":
                envelope = {
                    "schema_version": "1.0", "project_id": project.project_key,
                    "stage": stage_row.stage, "status": "PASS",
                    "result": {
                        "preview_canvas": {"files": direct_files, "chatgpt_response": text},
                        "asset_manifest": [{"path": path, "kind": "visual_preview"} for path in direct_files],
                        "self_check": {"generated": True, "promotion_used": False, "requires_compliance_qa": True},
                    },
                    "evidence": {
                        "chat_url": direct_chat_url,
                        "screenshots": direct_files,
                        "files": direct_files,
                        "capture_origin": "assistant_generated",
                    },
                    "issues": [], "repair_brief": None, "next_stage": "CREATIVE_REVIEW",
                }
            elif stage_row.stage == "FINAL_ASSETS" and direct_files:
                if final_asset_capture_origin == "assistant_generated_final_assets":
                    if len(direct_files) != 1:
                        raise ValueError(
                            f"FINAL_ASSETS_BOARD_INVALID: expected one generated reference board, got {len(direct_files)} files"
                        )
                    direct_files = _split_approved_preview(
                        db,
                        project,
                        source_path=direct_files[0],
                        require_verified_preview=False,
                        variant_index=_stage_variant_index(stage_row, project),
                    )
                split_manifest = list(dict(project.state_json or {}).get("last_split_manifest") or [])
                split_by_path = {str(item.get("path") or ""): item for item in split_manifest}
                fallback_reference_plan = _reference_plan_for_project(
                    db,
                    project,
                    len(direct_files),
                    variant_index=_stage_variant_index(stage_row, project),
                )
                envelope = {
                    "schema_version": "1.0", "project_id": project.project_key,
                    "stage": stage_row.stage, "status": "PASS",
                    "result": {
                        "reference_images": [
                            {
                                "path": path,
                                "index": index,
                                "kind": "final_reference",
                                "segment": (
                                    dict(split_by_path.get(path) or {}).get("segment")
                                    or fallback_reference_plan[index - 1]["segment"]
                                ),
                                "description": (
                                    dict(split_by_path.get(path) or {}).get("description")
                                    or fallback_reference_plan[index - 1]["description"]
                                ),
                                "semantic_roles": list(
                                    dict(split_by_path.get(path) or {}).get("roles")
                                    or fallback_reference_plan[index - 1]["roles"]
                                    or []
                                ),
                                "product_render_mode": "provider_reference",
                            }
                            for index, path in enumerate(direct_files, 1)
                        ],
                        "continuity_manifest": {
                            "source_stage": "FINAL_ASSETS", "count": len(direct_files),
                            "qa_approved_source": True,
                            "layout": dict(project.state_json or {}).get("last_split_layout"),
                            "capture_origin": final_asset_capture_origin,
                        },
                    },
                    "evidence": {
                        "chat_url": direct_chat_url,
                        "files": direct_files,
                        "capture_origin": final_asset_capture_origin,
                    },
                    "issues": [], "repair_brief": None, "next_stage": "VIDEO_PROMPTS",
                }
            else:
                raise
        if (
            stage_row.stage == "VISUAL_PREVIEW"
            and direct_files
            and not api_meta
        ):
            # Browser fallback follows the same product-reference contract as
            # API generation: the model renders the attached authoritative
            # package naturally in-scene.  No local pixel composite follows.
            api_meta.update({
                "execution_backend": "browser",
                "product_render_mode": "provider_reference",
            })
        envelope = _normalize_envelope_shape(envelope)
        if api_meta:
            evidence = dict(envelope.get("evidence") or {})
            evidence["execution_backend"] = str(
                api_meta.get("execution_backend") or "api"
            )
            evidence["api"] = api_meta
            envelope["evidence"] = evidence
        if direct_files:
            evidence = dict(envelope.get("evidence") or {})
            evidence["files"] = list(dict.fromkeys(list(evidence.get("files") or []) + direct_files))
            if direct_chat_url:
                evidence["chat_url"] = direct_chat_url
            if stage_row.stage == "VISUAL_PREVIEW":
                evidence["capture_origin"] = "assistant_generated"
                specs = visual_board_specs(packet)
                evidence["visual_boards"] = [
                    {
                        "board_index": int(spec.get("board_index") or position),
                        "board_count": int(spec.get("board_count") or len(specs) or 1),
                        "expected_panels": int(spec.get("count") or 1),
                        "global_start_index": int(spec.get("global_start_index") or 1),
                        "global_end_index": int(spec.get("global_end_index") or spec.get("count") or 1),
                        "global_reference_indices": list(
                            spec.get("global_reference_indices") or []
                        ),
                        "output_path": path,
                    }
                    for position, (path, spec) in enumerate(zip(direct_files, specs), 1)
                ]
            elif stage_row.stage == "FINAL_ASSETS":
                evidence["capture_origin"] = final_asset_capture_origin
            envelope["evidence"] = evidence
        result = envelope.get("result") or {}
        if stage_row.stage == "CREATIVE_REVIEW":
            # API and browser reviewers share one multimodal contract. The
            # server checks its structure but never reinterprets review prose.
            envelope = _apply_creative_review_reference_gate(envelope, packet)
            result = dict(envelope.get("result") or {})
            if not str(result.get("creative_review") or "").strip():
                raise ValueError(
                    "CREATIVE_REVIEW structured multimodal contract is missing creative_review"
                )
            if not isinstance(result.get("approved_for_split"), bool):
                raise ValueError(
                    "CREATIVE_REVIEW structured multimodal contract is missing approved_for_split"
                )
            if not isinstance(result.get("reference_image_count"), int):
                raise ValueError(
                    "CREATIVE_REVIEW structured multimodal contract is missing reference_image_count"
                )
            envelope["result"] = result
            _normalize_creative_review_repair_decision(envelope)
        if stage_row.stage == "EDIT_PACKAGE":
            result = _normalize_edit_package_result(dict(result), project)
            result = _ensure_edit_package_promotion(project, result)
            envelope["result"] = result
        if stage_row.stage == "FACTS" and _is_product_facts_project(project):
            envelope = _sanitize_product_facts_envelope(envelope)
            result = envelope.get("result") or {}
        if stage_row.stage == "VIDEO_PROMPTS":
            result = _canonicalize_video_prompt_result(dict(result))
            envelope["result"] = result
        if stage_row.stage == "VIDEO_PROMPTS" and (result.get("videos") or result.get("prompts")):
            marketing = _marketing_authorization(project)
            confirmed_promotion = _localized_promotion_cta(
                str(marketing.get("promotion_cta") or marketing.get("confirmed_promotions") or ""),
                _configured_video_language(project),
            )
            if (
                bool(marketing.get("allow_promotional_cta"))
                and confirmed_promotion
                and not _result_contains_confirmed_promotion(result, confirmed_promotion)
            ):
                # Preserve ChatGPT's segment plan. The queue layer injects the
                # explicit project-authorized CTA into the final segment only;
                # replacing the whole plan here destroys story/timeline data.
                evidence = dict(envelope.get("evidence") or {})
                evidence.update({
                    "server_will_inject_missing_confirmed_promotion": True,
                    "omitted_promotion": confirmed_promotion,
                    "original_chatgpt_result_was_preserved": True,
                })
                envelope["evidence"] = evidence
        missing = [name for name in REQUIRED_FIELDS[stage_row.stage] if name not in result]
        if stage_row.stage == "VIDEO_PROMPTS" and "videos" in missing and result.get("prompts"):
            missing = [name for name in missing if name != "videos"]
        if missing:
            raise ValueError("Missing result fields: " + ", ".join(missing))
        qa_decision_complete = False
        if envelope.get("status") != "PASS" and not qa_decision_complete:
            raise ValueError("ChatGPT stage returned FAIL: " + json.dumps(envelope.get("issues") or [], ensure_ascii=False))
        expected_next = _configured_next_stage(project, stage_row.stage)
        creative_replan_exhausted = False
        if not envelope.get("next_stage"):
            envelope["next_stage"] = expected_next
        if stage_row.stage == "CREATIVE_REVIEW" and not bool(result.get("approved_for_split")):
            variant_index = _stage_variant_index(stage_row, project)
            state = dict(project.state_json or {})
            recovery_epoch_limit = derive_quality_recovery_limit(
                dict(project.config_json or {}),
                pause_reason="creative_visual_replan_exhausted",
            )
            decision = _creative_review_rejection_policy(
                state,
                variant_index=variant_index,
                repair_limit=max(2, min(4, recovery_epoch_limit - 1)),
                replan_limit=max(2, min(3, recovery_epoch_limit // 2)),
                replan_stage="PRODUCTION_PLAN",
            )
            expected_next = str(decision["next_stage"])
            creative_replan_exhausted = bool(decision["exhausted"])
            evidence = dict(envelope.get("evidence") or {})
            evidence.update({
                "visual_repair_count_for_current_concept": int(decision["repair_count"]),
                "visual_repair_limit_for_current_concept": int(decision["repair_limit"]),
                "production_plan_repair_count_for_variant": int(decision["replan_count"]),
                "production_plan_repair_limit_for_variant": int(decision["replan_limit"]),
            })
            if expected_next == "VISUAL_PREVIEW":
                targeted_repair = _targeted_visual_repair_brief(result)
                if targeted_repair:
                    result["repair_brief"] = targeted_repair
                    evidence["pixel_grounded_targeted_visual_repair"] = True
            if expected_next == "PRODUCTION_PLAN":
                # Repeating the same visual request after several explicit
                # review rejections only burns image quota. Re-plan the current
                # variant with a simpler, concrete visual plan, then generate a
                # new board from that signed plan.
                result["repair_brief"] = (
                    _production_plan_visual_repair_brief(result)
                )
                evidence["visual_retry_loop_broken_by_production_replan"] = True
                if creative_replan_exhausted:
                    result["repair_brief"] = (
                        "Hermes stopped this variant after the bounded creative/visual repair budget was exhausted. "
                        "Review the latest board or project requirement, then resume from a fresh Director plan."
                    )
                    evidence["creative_visual_replan_exhausted"] = True
            project.state_json = dict(decision["state"])
            envelope["result"] = result
            envelope["evidence"] = evidence
            envelope["next_stage"] = expected_next
        if envelope.get("next_stage") != expected_next:
            raise ValueError(f"Invalid next_stage: expected {expected_next}")
        variant_index = _stage_variant_index(stage_row, project)
        if stage_row.stage in VARIANT_STAGES:
            evidence = dict(envelope.get("evidence") or {})
            evidence["variant_index"] = variant_index
            evidence["content_factory_variant_index"] = variant_index
            envelope["evidence"] = evidence
            envelope["content_factory_variant_index"] = variant_index
        if stage_row.stage == "CREATIVE_REVIEW" and not bool(result.get("approved_for_split")):
            # Compute the pixel-grounded failed/passed manifest even when the
            # bounded policy moves to PRODUCTION_PLAN or pauses.  It is not an
            # instruction to spend more media automatically; it is durable
            # review evidence needed by a later operator-approved resume so a
            # rejected downloaded frame cannot masquerade as resumable work.
            partial_repair: dict[str, Any] = (
                _visual_partial_repair_descriptor(
                    db,
                    project,
                    stage_row,
                    result,
                    variant_index=variant_index,
                )
            )
            state = dict(project.state_json or {})
            if partial_repair and expected_next == "VISUAL_PREVIEW":
                partial_repair["repair_brief"] = str(
                    result.get("repair_brief") or ""
                )[:4000]
                state["pending_visual_partial_repair"] = partial_repair
            else:
                state.pop("pending_visual_partial_repair", None)
            project.state_json = state
            if _creative_review_asset_cleanup_allowed(
                creative_replan_exhausted=creative_replan_exhausted,
            ):
                _clean_generated_variant_assets(
                    db,
                    project,
                    ("VISUAL_PREVIEW", "FINAL_ASSETS"),
                    variant_index=variant_index,
                    preserve_asset_ids={
                        int(item.get("asset_id") or 0)
                        for item in list(partial_repair.get("preserved_references") or [])
                        if int(item.get("asset_id") or 0) > 0
                    },
                )
            else:
                # An automatic quality pause is an operator inspection
                # boundary, not another regeneration transition.  Preserve
                # the latest rejected board and its asset rows so review can
                # be resumed without destroying the very evidence that caused
                # the pause.
                preserved_asset_ids = [
                    int(asset.id)
                    for asset in db.query(HermesContentFactoryAsset)
                    .filter(
                        HermesContentFactoryAsset.project_id == project.id,
                        HermesContentFactoryAsset.stage.in_(
                            ("VISUAL_PREVIEW", "FINAL_ASSETS")
                        ),
                    )
                    .all()
                    if int(asset.id or 0) > 0
                    and _generated_asset_variant_index(asset) == int(variant_index)
                    and _asset_file_available(asset)
                ]
                state = dict(project.state_json or {})
                state["quality_pause_preserved_visual_asset_ids"] = (
                    preserved_asset_ids
                )
                project.state_json = state

        imported_assets = _import_generated_assets(
            db,
            project,
            stage_row.stage,
            envelope,
            expected_panel_count=_visual_expected_panel_count(
                dict(stage_row.input_json or {})
            ),
        )
        if stage_row.stage == "FINAL_ASSETS" and not [asset for asset in imported_assets if str(asset.mime_type or "").startswith("image/")]:
            raise ValueError("FINAL_ASSETS did not persist any generated reference images")
        if stage_row.stage == "FINAL_ASSETS":
            complete, expected_count, actual_count = _final_assets_are_complete(db, project)
            if not complete:
                raise ValueError(
                    f"FINAL_ASSETS_INVALID: expected {expected_count} final reference images, "
                    f"found {actual_count}. The split result was discarded and will be rebuilt."
                )

        _record_stage_quality_learning(db, project, stage_row, envelope, imported_assets)
        _record_project_chatgpt_recovery(project, now=_stage_now())
        _clear_api_stage_failures(project, stage_row.stage)

        # Persist the policy actually executing this successful delivery.
        # Older retry/restart payloads can legitimately carry an earlier
        # policy stamp; leaving that stale value on a successful row makes
        # later self-heal passes treat freshly produced work as obsolete.
        completed_input = dict(stage_row.input_json or {})
        completed_input["self_heal_policy_version"] = SELF_HEAL_POLICY_VERSION
        completed_input["hermes_learning_policy_version"] = (
            HERMES_LEARNING_POLICY_VERSION
        )
        stage_row.input_json = completed_input
        stage_row.status = "success"
        stage_row.response_text = text
        stage_row.output_json = envelope
        stage_row.chat_url = str((envelope.get("evidence") or {}).get("chat_url") or "") or None
        stage_row.completed_at = _stage_now()
        if stage_row.stage == "CREATIVE_REVIEW":
            state = dict(project.state_json or {})
            partial_repair = dict(state.get("pending_visual_partial_repair") or {})
            if bool(result.get("approved_for_split")):
                state.pop("pending_visual_partial_repair", None)
                partial_repair = {}
            state["last_creative_review"] = {
                "approved_for_split": bool(result.get("approved_for_split")),
                "reference_image_count": result.get("reference_image_count"),
                "repair_brief": result.get("repair_brief"),
                "partial_repair": partial_repair,
            }
            project.state_json = state
        if stage_row.stage == "FACTS":
            state = dict(project.state_json or {})
            config = dict(project.config_json or {})
            from app.services.hermes_agent.content_factory import (
                create_product,
                normalize_product_attribute_brief,
                sanitize_product_facts_json,
            )

            product = None
            product_id = int(config.get("product_id") or project.product_id or 0)
            if product_id:
                from app.data.models.hermes_agent import HermesContentProduct
                product = (
                    db.query(HermesContentProduct)
                    .filter(HermesContentProduct.workspace_id == project.workspace_id, HermesContentProduct.id == product_id)
                    .one_or_none()
                )
            if product is None:
                product = create_product(
                    db,
                    workspace_id=int(project.workspace_id),
                    user_id=int(project.user_id or stage_row.user_id or 1),
                    brand_name=str(config.get("brand_name") or ""),
                    product_name=project.product_name,
                    market=project.market,
                    product_brief=project.product_brief,
                    facts_json=envelope,
                )
                project.product_id = int(product.id)
            else:
                product.facts_json = sanitize_product_facts_json(envelope)
                if project.product_brief:
                    product.product_brief = normalize_product_attribute_brief(
                        project.product_brief
                    )
            product.meta_json = {
                **dict(product.meta_json or {}),
                "facts_status": "success",
                "facts_project_key": project.project_key,
                "facts_stage_id": int(stage_row.id),
                "facts_updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                "facts_error": None,
            }
            config["product_id"] = int(product.id)
            config["product_library_key"] = product.product_key
            state["product_knowledge"] = {
                "product_library_key": product.product_key,
                "product_id": int(product.id),
                "brand_name": product.brand_name,
                "product_name": product.product_name,
                "market": product.market,
                "source": "product_library",
                "source_project_key": project.project_key,
                "source_stage_id": int(stage_row.id),
                "facts_envelope": envelope,
                "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            }
            state["product_facts_source"] = "manual_refresh"
            project.state_json = state
            config["uses_product_library"] = True
            project.config_json = config
            _refresh_profile_director_brief_from_facts(
                project,
                product_truth=dict(state["product_knowledge"]),
            )
        project.current_stage = expected_next
        project.status = "waiting_approval" if expected_next.startswith("WAITING_") else ("complete" if expected_next == "COMPLETE" else "ready")
        project.last_error = None
        if creative_replan_exhausted:
            config = dict(project.config_json or {})
            config["manual_paused"] = False
            project.config_json = config
            state = dict(project.state_json or {})
            automatic_paused_at = _stage_now().isoformat()
            state["creative_visual_replan_exhausted"] = {
                "variant_index": int(variant_index),
                "stage_id": int(stage_row.id),
                "at": automatic_paused_at,
            }
            state["paused_at"] = automatic_paused_at
            state["automatic_quality_paused_at"] = automatic_paused_at
            state["pause_reason_code"] = "creative_visual_replan_exhausted"
            state["pause_note"] = "Creative and visual bounded repair budget exhausted."
            project.state_json = state
            project.status = "paused"
            project.last_error = (
                "创意与视觉画板已达到本变体的有界修复上限，项目已暂停以避免继续消耗图片额度；"
                "检查最新复核意见后可手动恢复，并从新的创意方案继续。"
            )
            from app.services.hermes_agent.content_factory import _release_bridge_for_project

            _release_bridge_for_project(db, project_id=int(project.id))
        if expected_next == "COMPLETE":
            from app.services.hermes_agent.content_factory import _release_bridge_for_project

            _release_bridge_for_project(db, project_id=int(project.id))

        if stage_row.stage == "VIDEO_PROMPTS":
            # Queue creation is part of the VIDEO_PROMPTS transaction. If
            # reference preparation fails, keep this stage retryable instead
            # of first committing success and then rewriting it as failed.
            task_ids = _queue_ai_video_tasks(
                db,
                project,
                envelope,
                source_stage_id=int(stage_row.id),
            )
            return {"status": "success", "project_key": project.project_key, "next_stage": "WAITING_VIDEO_INPUT", "ai_video_task_ids": task_ids}

        # Variant authoring is allowed to overlap provider polling and final
        # video QA.  Preserve any media-ledger/retry update committed while
        # this control stage was running; otherwise a successful
        # FINAL_ASSETS/CREATIVE_REVIEW turn can overwrite the waiter's newer
        # segment replacement pointers with its stale project snapshot.
        _merge_latest_video_runtime_before_control_commit(db, project)
        db.commit()
        if stage_row.stage in {"VISUAL_PREVIEW", "FINAL_ASSETS"}:
            try:
                _cleanup_persisted_browser_chat(db, stage_row)
            except Exception:
                # Chat-history cleanup is housekeeping. The generated image
                # and stage result are already durable and must stay successful.
                db.rollback()
        continue_workflow = bool(dict(stage_row.input_json or {}).get("continue_workflow", True))
        if (
            project.status == "ready"
            and continue_workflow
            and not bool(dict(project.config_json or {}).get("manual_paused", False))
        ):
            # Stage output and the project transition were committed above.
            # Release the outer delivery guard before the successor reaches a
            # worker.  Publishing under the guard forced every normal stage
            # transition through the database cooldown and added up to one
            # minute of idle time per stage.
            _release_project_execution_guard(
                execution_guard,
                guarded_project_id,
            )
            execution_guard = None
            from app.services.hermes_agent.content_factory import queue_stage
            next_instruction = None
            if (
                stage_row.stage == "CREATIVE_REVIEW"
                and expected_next == "PRODUCTION_PLAN"
                and not creative_replan_exhausted
            ):
                next_instruction = (
                    str(result.get("repair_brief") or "").strip()
                    or (
                        "Revise the current signed Production Plan from the "
                        "pixel-grounded review evidence while preserving the "
                        "approved Director script and truth boundaries."
                    )
                )
            queue_stage(
                db,
                project=project,
                user_id=int(project.user_id),
                instruction=next_instruction,
            )
            db.commit()
        return {"status": "success", "project_key": project.project_key, "next_stage": expected_next}
    except Exception as exc:
        soft_time_limit_exceeded = isinstance(exc, SoftTimeLimitExceeded)
        if soft_time_limit_exceeded:
            exc = RuntimeError(
                "ChatGPT stage soft time limit exceeded; recover the existing "
                "assistant response before any fresh submission"
            )
        db.rollback()
        if _is_mysql_deadlock_error(exc) and not claim_committed:
            retry_number = int(getattr(self.request, "retries", 0) or 0)
            if retry_number < 3:
                raise self.retry(
                    exc=exc,
                    countdown=min(4, retry_number + 1),
                    max_retries=3,
                )
            # Leave the durable stage queued. The periodic recovery publisher
            # can issue a fresh lease after the bounded delivery-level retries
            # without converting lock contention into a business failure.
            return {
                "status": "db_deadlock_retry_exhausted",
                "stage_id": int(stage_id),
                "retries": retry_number,
            }
        will_retry = False
        retry_delay = None
        self_healed_stage: HermesContentFactoryStage | None = None
        # The provider call above can run for minutes while an operator pauses
        # the project in another transaction.  ``Session.get`` may return the
        # identity-map copy loaded before that pause, allowing this late error
        # path to overwrite the newer manual authority.  Re-enter the common
        # project-first lock scope with ``populate_existing`` so every recovery
        # decision is made from committed database state.
        stage_row, project, _ = _lock_stage_delivery_scope(
            db,
            int(stage_id),
        )
        if stage_row:
            if project is not None and str(project.status or "").lower() == "deleted":
                return {
                    "status": "ignored_deleted_after_error",
                    "stage_id": int(stage_row.id),
                    "project_key": project.project_key,
                }
            if (
                project is not None
                and (
                    str(project.status or "").lower() == "paused"
                    or bool(dict(project.config_json or {}).get("manual_paused", False))
                )
            ):
                # An operator pause is newer authority than a provider error
                # returned by an already-running delivery.  Preserve the
                # pause instead of allowing this stale exception path to
                # rewrite the project as queued/failed and arm another retry.
                if str(stage_row.status or "").lower() in {"queued", "running", "retrying"}:
                    stage_row.status = "paused"
                    stage_row.error_message = (
                        "Paused manually while provider work was in flight; "
                        "the late provider error did not resume the project."
                    )
                    stage_row.completed_at = None
                db.commit()
                return {
                    "status": "ignored_paused_after_error",
                    "stage_id": int(stage_row.id),
                    "project_key": project.project_key,
                }
            if not _is_current_stage_delivery(stage_row, request_id=request_id, run_token=delivery_run_token):
                db.rollback()
                return {
                    "status": "ignored_superseded_error",
                    "stage_id": int(stage_row.id),
                    "registered_task_id": str(stage_row.celery_task_id or ""),
                    "request_id": request_id,
                    "registered_run_token": _stage_run_token(stage_row),
                    "request_run_token": delivery_run_token,
                }
            latest_after_error = _latest_stage(db, project, project.current_stage) if project is not None else None
            if latest_after_error is not None and int(latest_after_error.id) != int(stage_row.id):
                db.rollback()
                return {
                    "status": "ignored_superseded_stage_error",
                    "stage_id": int(stage_row.id),
                    "latest_stage_id": int(latest_after_error.id),
                    "stage": stage_row.stage,
                }
            registered_task_id = str(stage_row.celery_task_id or "")
            if registered_task_id and request_id and registered_task_id != request_id:
                db.rollback()
                return {
                    "status": "ignored_superseded_error",
                    "stage_id": int(stage_row.id),
                    "registered_task_id": registered_task_id,
                    "request_id": request_id,
                }
            if soft_time_limit_exceeded and stage_row.stage == "SERIES_DIRECTOR":
                checkpointed_input = dict(stage_row.input_json or {})
                checkpoint = checkpointed_input.get(
                    "series_director_page_checkpoint"
                )
                if isinstance(checkpoint, dict) and checkpoint:
                    resume_count = int(
                        checkpointed_input.get(
                            "series_director_timeout_resume_count"
                        )
                        or 0
                    ) + 1
                    resume_limit = _positive_int(
                        dict(project.config_json or {}).get(
                            "series_director_timeout_resume_limit"
                        ),
                        4,
                    )
                    now = _stage_now()
                    if resume_count > resume_limit:
                        checkpointed_input[
                            "series_director_timeout_resume_count"
                        ] = resume_count
                        checkpointed_input.pop(
                            "execution_lease_expires_at",
                            None,
                        )
                        stage_row.input_json = checkpointed_input
                        stage_row.status = "paused"
                        stage_row.celery_task_id = None
                        stage_row.completed_at = None
                        stage_row.error_message = (
                            "SERIES_DIRECTOR_CHECKPOINT_RESUME_EXHAUSTED: "
                            "the bounded execution-window resume budget was "
                            "exhausted without approving the whole series"
                        )
                        state = dict(project.state_json or {})
                        state.update({
                            "automatic_quality_paused_at": now.isoformat(),
                            "pause_reason_code": (
                                "series_director_checkpoint_resume_exhausted"
                            ),
                            "pause_note": stage_row.error_message,
                        })
                        project.state_json = state
                        project.status = "paused"
                        project.current_stage = "SERIES_DIRECTOR"
                        project.last_error = stage_row.error_message
                        db.commit()
                        return {
                            "status": "series_director_quality_paused",
                            "stage_id": int(stage_row.id),
                            "checkpoint_progress": dict(
                                checkpoint.get("progress") or {}
                            ),
                            "resume_count": resume_count,
                        }
                    retry_after = now + timedelta(seconds=60)
                    checkpointed_input.update({
                        "series_director_timeout_resume_count": resume_count,
                        "retry_after": retry_after.isoformat(),
                        "retry_release_strategy": (
                            "database_due_at_periodic_self_heal"
                        ),
                        "self_heal_action": (
                            "resume_series_director_from_durable_checkpoint"
                        ),
                    })
                    for stale_key in (
                        "run_token",
                        "execution_lease_expires_at",
                    ):
                        checkpointed_input.pop(stale_key, None)
                    stage_row.input_json = checkpointed_input
                    stage_row.status = "retrying"
                    stage_row.celery_task_id = None
                    stage_row.started_at = None
                    stage_row.completed_at = None
                    stage_row.error_message = (
                        "SERIES_DIRECTOR_CHECKPOINTED_WINDOW_COMPLETE: "
                        "resume the same bounded series plan from its durable "
                        "checkpoint"
                    )
                    project.status = "queued"
                    project.current_stage = "SERIES_DIRECTOR"
                    project.last_error = stage_row.error_message
                    db.commit()
                    return {
                        "status": "series_director_checkpoint_resume_scheduled",
                        "stage_id": int(stage_row.id),
                        "checkpoint_progress": dict(
                            checkpoint.get("progress") or {}
                        ),
                        "resume_count": resume_count,
                        "retry_after": retry_after.isoformat(),
                    }
            # Provider progress can commit after the outer delivery captured
            # its initial payload. Never let that older snapshot become policy
            # authority when the exception path records retry metadata.
            stage_input = _restamp_stage_runtime_policy(stage_row.input_json)
            api_route_on_failure = str(stage_input.get("api_route") or "").strip()
            if _text_api_fault_needs_recovery_supervisor(
                api_route=api_route_on_failure,
                stage=stage_row.stage,
                error=exc,
            ):
                stage_row.error_message = str(exc)[:4000]
                db.add(stage_row)
                db.add(project)
                db.commit()
                return _handoff_api_stage_to_browser(
                    db,
                    project,
                    stage_row,
                    reason=str(exc),
                )
            replayed_response_validation = bool(
                stage_input.get("replayed_durable_response_capture")
                or stage_input.get("replayed_prior_stage_capture_id")
            )
            api_output_validation_failure = _is_text_api_output_validation_failure(
                api_route=api_route_on_failure,
                stage=stage_row.stage,
                replayed_response=replayed_response_validation,
                error=exc,
            )
            # A valid API envelope can still fail only our local timing/copy
            # normalizer.  That is a regeneration request, not evidence that
            # the API route is unhealthy; do not consume the API->browser
            # fallback budget for it.
            semantic_api_payload_failure = _is_semantic_text_payload_failure(
                api_route=api_route_on_failure,
                stage=stage_row.stage,
                error=exc,
            )
            if api_output_validation_failure and not semantic_api_payload_failure:
                failure_count = _record_api_stage_failure(project, stage_row.stage, exc)
                db.commit()
                maximum = max(
                    1,
                    int(os.getenv("HERMES_TEXT_API_MAX_FAILURES_BEFORE_BROWSER", "3")),
                )
                if failure_count >= maximum:
                    return _handoff_api_stage_to_browser(
                        db,
                        project,
                        stage_row,
                        reason=str(exc),
                    )
            # A captured response can be replayed after a deployment changes a
            # normalizer, but it cannot become valid when its own copy or
            # timeline exceeds the configured segment budget.  Regenerate this
            # category of API payload instead of repeatedly validating the same
            # immutable response and opening a cooldown circuit.
            bridge_route_error = any(
                marker in (str(getattr(exc, "code", "") or "") + " " + str(exc))
                for marker in (
                    "CONTENT_BROWSER_BRIDGE_REQUIRED",
                    "CONTENT_BROWSER_BRIDGE_OFFLINE",
                    "CONTENT_BROWSER_CAPACITY_FULL",
                    "CONTENT_BROWSER_LOGIN_REQUIRED",
                    "BROWSER_BRIDGE_LOCK_MISSING",
                    "请先在当前电脑创建并连接浏览器桥",
                    "浏览器桥不",
                    "slot",
                )
            )
            if bridge_route_error:
                stage_input = _release_degraded_project_bridge(
                    db,
                    project,
                    stage_input,
                    reason=str(exc),
                )
                stage_row.input_json = stage_input
                if execution_backend == "browser":
                    supervised_browser_recovery = (
                        _recover_browser_fault_with_supervisor(
                            db,
                            project,
                            stage_row,
                            reason=str(exc),
                        )
                    )
                    if supervised_browser_recovery is not None:
                        return supervised_browser_recovery
                stage_row.status = "failed"
                stage_row.completed_at = _stage_now()
                stage_row.error_message = str(exc)[:4000]
                project.current_stage = stage_row.stage
                project.status = "waiting_bridge"
                project.last_error = (
                    "Browser bridge is unavailable for this user's device; "
                    "Hermes will resume after this user's local bridge reconnects."
                )
                db.commit()
                return {
                    "status": "waiting_bridge",
                    "stage_id": int(stage_row.id),
                    "project_key": project.project_key,
                    "stage": stage_row.stage,
                }
            stage_row.error_message = str(exc)[:4000]
            fault_reports = [
                dict(value)
                for value in list(stage_input.get("fault_report_history") or [])[-11:]
                if isinstance(value, dict)
            ]
            fault_reports.append({
                "at": _stage_now().isoformat(),
                "stage": str(stage_row.stage or "")[:64],
                "source_backend": (
                    execution_backend
                    if execution_backend in {"api", "browser"}
                    else "api"
                ),
                "fault_class": classify_recovery_fault(
                    str(exc),
                    code=str(getattr(exc, "code", "") or ""),
                ),
                "fault_code": str(getattr(exc, "code", "") or "")[:128],
                "error_summary": str(exc)[:1200],
                "delivery_id": request_id[:96],
            })
            stage_input["fault_report_history"] = fault_reports
            stage_row.input_json = stage_input
            if isinstance(exc, ChatGPTStageError):
                stage_row.response_text = _prefer_chatgpt_response_snapshot(
                    stage_row.response_text,
                    getattr(exc, "raw_text", ""),
                    project.project_key,
                    stage_row.stage,
                )
                stage_row.chat_url = str(getattr(exc, "chat_url", "") or "") or stage_row.chat_url
                stage_meta = dict(stage_row.output_json or {})
                stage_meta["chatgpt_stage_error"] = {
                    "type": "non_json_or_incomplete_response",
                    "message": str(exc)[:1000],
                    "raw_text_saved": bool(stage_row.response_text),
                    "chat_url": stage_row.chat_url,
                }
                stage_row.output_json = stage_meta
            if "BROWSER_INBOX_SYNC_INCOMPLETE" in str(exc):
                stage_row.status = "failed"
                stage_row.completed_at = _stage_now()
                if project:
                    project.current_stage = stage_row.stage
                    project.status = "waiting_bridge"
                    project.last_error = (
                        "Browser bridge file sync is incomplete; Hermes will resume after this user's local bridge syncs files."
                    )
                db.commit()
                return {
                    "status": "waiting_bridge_file_sync",
                    "stage_id": int(stage_row.id),
                    "project_key": project.project_key if project else None,
                    "stage": stage_row.stage,
                }
            browser_fault_class = classify_recovery_fault(
                str(exc),
                code=str(getattr(exc, "code", "") or ""),
            )
            if (
                execution_backend == "browser"
                and browser_fault_class in {
                    "BROWSER_UPLOAD_UNAVAILABLE",
                    "BROWSER_LOGIN_REQUIRED",
                    "BROWSER_OFFLINE",
                }
            ):
                supervised_browser_recovery = (
                    _recover_browser_fault_with_supervisor(
                        db,
                        project,
                        stage_row,
                        reason=str(exc),
                    )
                )
                if supervised_browser_recovery is not None:
                    return supervised_browser_recovery
            retry_number = int(stage_input.get("automatic_retry_count") or 0) + 1
            retry_delay = _stage_retry_delay(exc, retry_number)
            durable_response = _recover_completed_stage_response(
                stage_row.response_text,
                project.project_key,
                stage_row.stage,
            )
            durable_replay_count = int(stage_input.get("durable_response_replay_count") or 0)
            if (
                durable_response is not None
                and durable_replay_count < 1
                and not semantic_api_payload_failure
            ):
                # One local replay is enough to recover from a deployment that
                # added a new normalizer.  It never sends another browser/API
                # request because the preflight above consumes the capture.
                will_retry = True
                retry_delay = 10
                stage_input["durable_response_replay_count"] = durable_replay_count + 1
                stage_input["browser_recovery_mode"] = "recover_existing_response_from_durable_capture"
                stage_input["force_fresh_response"] = False
                stage_input["clear_stale_composer_before_send"] = False
                stage_input["self_heal_action"] = "revalidate_durable_response_without_resubmission"
            if project and _is_chatgpt_rate_limit_error(str(exc)):
                learned_rate_limit_wait = _record_project_rate_limit(
                    project,
                    stage_input,
                    message=str(exc),
                    now=_stage_now(),
                )
                retry_delay = _bounded_rate_limit_retry_delay(
                    str(exc),
                    learned_rate_limit_wait,
                    entropy_key=f"{project.project_key}:{stage_row.stage}:{retry_number}",
                )
                stage_input["rate_limit_wait_seconds"] = retry_delay
            will_retry = retry_delay is not None
            browser_interaction_failure = _is_browser_interaction_error(str(exc))
            recoverable_response_failure = _is_recoverable_chatgpt_response_error(str(exc))
            cdp_unresponsive = bool(project and _is_cdp_unresponsive_error(str(exc)))
            browser_route_unavailable = bool(project and _is_browser_route_unavailable_error(str(exc)))
            visual_empty_response = _is_visual_empty_response_error(stage_row.stage, str(exc))
            response_retry_plan = (
                _recoverable_response_retry_plan(stage_input)
                if recoverable_response_failure and not visual_empty_response
                else None
            )
            visual_retry_plan = (
                _recoverable_visual_retry_plan(stage_input)
                if visual_empty_response
                and not browser_route_unavailable
                and not _is_chatgpt_rate_limit_error(str(exc))
                else None
            )
            if recoverable_response_failure and not visual_empty_response:
                # Do not consume the generic widening retry schedule forever on
                # one malformed assistant turn. Alternate one late-response
                # probe with one fresh generation, bounded by project-local
                # counters so duplicate sends and infinite rereads are both
                # impossible.
                will_retry = response_retry_plan is not None
                retry_delay = (
                    int(response_retry_plan["delay"])
                    if response_retry_plan is not None
                    else None
                )
            if (
                durable_response is not None
                and durable_replay_count < 1
                and not semantic_api_payload_failure
            ):
                will_retry = True
                retry_delay = 10
            elif semantic_api_payload_failure:
                # Explicitly bypass the captured response on the next API
                # turn; leaving its replay marker in place would cause the
                # preflight to reconsume the same invalid text.
                semantic_retry_plan = _semantic_api_retry_plan(
                    stage_input,
                    error_message=str(exc),
                )
                rejected_response = str(stage_row.response_text or "")
                stage_input["semantic_validation_last_error"] = str(exc)[:1200]
                stage_input["semantic_validation_last_response_sha256"] = (
                    hashlib.sha256(rejected_response.encode("utf-8")).hexdigest()
                    if rejected_response
                    else None
                )
                if semantic_retry_plan is None:
                    stage_input["semantic_api_retry_limit"] = (
                        MAX_SEMANTIC_API_REGENERATION_CYCLES
                    )
                    stage_input["semantic_recovery_exhausted"] = True
                    stage_input["self_heal_action"] = (
                        "recover_api_only_after_semantic_budget"
                    )
                    stage_row.input_json = stage_input
                    db.commit()
                    return _recover_exhausted_semantic_api_stage(
                        db,
                        project,
                        stage_row,
                        reason=(
                            "semantic API regeneration budget exhausted after "
                            f"{MAX_SEMANTIC_API_REGENERATION_CYCLES} fresh responses: {exc}"
                        ),
                    )
                stage_input.update(semantic_retry_plan)
                will_retry = True
                retry_delay = min(int(retry_delay or 20), 20)
                stage_input["force_fresh_response"] = True
                stage_input["browser_recovery_mode"] = "fresh_api_response_after_semantic_validation_failure"
                stage_input["clear_stale_composer_before_send"] = True
                stage_input["self_heal_action"] = "regenerate_api_payload_with_segment_budget"
                stage_input["self_heal_policy_version"] = (
                    SELF_HEAL_POLICY_VERSION
                )
                stage_input["api_regeneration_generation"] = int(
                    stage_input.get("api_regeneration_generation") or 0
                ) + 1
                stage_input.pop("replayed_durable_response_capture", None)
                stage_input.pop("replayed_prior_stage_capture_id", None)
            if cdp_unresponsive:
                bridge_reacquire_count = int(stage_input.get("bridge_reacquire_count") or 0) + 1
                stage_input["bridge_reacquire_count"] = bridge_reacquire_count
                stage_input = _release_degraded_project_bridge(
                    db,
                    project,
                    stage_input,
                    reason=str(exc),
                )
                if bridge_reacquire_count <= int(os.getenv("HERMES_MAX_BRIDGE_REACQUIRE_RETRIES", "3")):
                    will_retry = True
                    retry_delay = min(int(retry_delay or 20), 20)
            if browser_route_unavailable:
                stage_input = _release_degraded_project_bridge(
                    db,
                    project,
                    stage_input,
                    reason=str(exc),
                )
                if (
                    not _browser_bridge_fresh_for_stage(db, project, stage_input, now=_stage_now())
                    or not _browser_cdp_reachable_for_stage(db, project, stage_input)
                ):
                    stage_row.input_json = stage_input
                    if execution_backend == "browser":
                        supervised_browser_recovery = (
                            _recover_browser_fault_with_supervisor(
                                db,
                                project,
                                stage_row,
                                reason=str(exc),
                                browser_retry_exhausted=True,
                            )
                        )
                        if supervised_browser_recovery is not None:
                            return supervised_browser_recovery
                    stage_row.input_json = stage_input
                    stage_row.status = "failed"
                    stage_row.completed_at = _stage_now()
                    stage_row.error_message = str(exc)[:4000]
                    project.current_stage = stage_row.stage
                    project.status = "waiting_bridge"
                    project.last_error = (
                        "Browser bridge is unavailable for this user's device; "
                        "Hermes will resume after this user's local bridge reconnects."
                    )
                    db.commit()
                    return {
                        "status": "waiting_bridge",
                        "stage_id": int(stage_row.id),
                        "project_key": project.project_key,
                        "stage": stage_row.stage,
                    }
            if (
                visual_empty_response
                and not browser_route_unavailable
                and not _is_chatgpt_rate_limit_error(str(exc))
            ):
                will_retry = visual_retry_plan is not None
                retry_delay = (
                    int(visual_retry_plan["delay"])
                    if visual_retry_plan is not None
                    else None
                )
            provider_retry_delay = _visual_api_provider_retry_delay(
                stage_row.stage,
                stage_input,
                str(exc),
            )
            if provider_retry_delay is not None:
                # Explicitly failed provider jobs already had their task id
                # cleared. Resubmit with the next generation even when this
                # stage's much older generic retry budget is exhausted.
                will_retry = True
                retry_delay = provider_retry_delay
                stage_input["self_heal_action"] = "resubmit_failed_visual_api_task"
                stage_input["visual_api_provider_retry_count"] = int(
                    dict(stage_input.get("visual_api") or {}).get("provider_retry_generation") or 0
                )
            browser_local_recovery_exhausted = bool(
                execution_backend == "browser"
                and (
                    (
                        recoverable_response_failure
                        and not visual_empty_response
                        and response_retry_plan is None
                    )
                    or (
                        visual_empty_response
                        and visual_retry_plan is None
                    )
                    or (
                        cdp_unresponsive
                        and int(stage_input.get("bridge_reacquire_count") or 0)
                        > int(os.getenv("HERMES_MAX_BRIDGE_REACQUIRE_RETRIES", "3"))
                    )
                )
            )
            if browser_local_recovery_exhausted:
                stage_row.input_json = stage_input
                supervised_browser_recovery = (
                    _recover_browser_fault_with_supervisor(
                        db,
                        project,
                        stage_row,
                        reason=(
                            "BROWSER_RESPONSE_RECOVERY_EXHAUSTED: "
                            + str(exc)
                        ),
                        browser_retry_exhausted=True,
                    )
                )
                if supervised_browser_recovery is not None:
                    return supervised_browser_recovery
            if (
                replayed_response_validation
                and not semantic_api_payload_failure
                and isinstance(exc, (ValueError, ContentFactoryApiError))
                and not _is_chatgpt_rate_limit_error(str(exc))
            ):
                # A complete response was already captured and has just failed
                # local business normalization. Revalidating it every few
                # seconds cannot improve the payload and previously created an
                # unbounded API->browser fallback stage cascade. Keep the same
                # stage/capture and open a project-local cooldown circuit. A
                # deployment or manual resume can then revalidate it without a
                # second provider/browser submission.
                will_retry = True
                retry_delay = max(
                    300,
                    int(os.getenv("HERMES_CAPTURE_VALIDATION_COOLDOWN_SECONDS", "900")),
                )
                stage_input["self_heal_circuit_open"] = True
                stage_input["self_heal_action"] = (
                    "cooldown_complete_response_after_local_validation_failure"
                )
                stage_input["captured_response_validation_error"] = str(exc)[:1200]
                stage_input["captured_response_validation_failed_at"] = _stage_now().isoformat()
            stage_row.status = "retrying" if will_retry else "failed"
            stage_row.completed_at = None if will_retry else _stage_now()
            if will_retry:
                stage_input["automatic_retry_count"] = retry_number
                stage_input["retry_after"] = (_stage_now() + timedelta(seconds=retry_delay)).isoformat()
                for stale_key in (
                    "retry_release_task_id",
                    "run_token",
                    "execution_lease_expires_at",
                ):
                    stage_input.pop(stale_key, None)
                stage_input["retry_release_strategy"] = "database_due_at_periodic_self_heal"
                # The active Celery delivery ends when this transaction is
                # committed.  A database-timed retry must not retain that
                # delivery's identity or start time, otherwise self-heal sees
                # a phantom live worker until the old execution lease expires.
                stage_row.celery_task_id = None
                stage_row.started_at = None
                if (
                    visual_empty_response
                    and not browser_route_unavailable
                    and not _is_chatgpt_rate_limit_error(str(exc))
                ):
                    for key, value in dict(visual_retry_plan or {}).items():
                        if key != "delay":
                            stage_input[key] = value
                    stage_input["self_heal_action"] = str(
                        (visual_retry_plan or {}).get("browser_recovery_mode") or ""
                    )
                if browser_interaction_failure:
                    if recoverable_response_failure and response_retry_plan is not None:
                        for key, value in response_retry_plan.items():
                            if key != "delay":
                                stage_input[key] = value
                        stage_input["self_heal_action"] = str(
                            response_retry_plan.get("browser_recovery_mode") or ""
                        )
                    elif not recoverable_response_failure:
                        stage_input["force_fresh_response"] = True
                        stage_input["browser_recovery_mode"] = "fresh_composer_sequential_upload"
                        stage_input["clear_stale_composer_before_send"] = True
                    if cdp_unresponsive:
                        stage_input["browser_recovery_mode"] = "reacquire_bridge_after_cdp_timeout"
                        stage_input["force_reacquire_browser_bridge"] = True
                        stage_input["automatic_retry_count"] = 0
                if "VIDEO_PROMPTS_CONFIRMED_PROMOTION_MISSING" in str(exc):
                    stage_input["force_fresh_response"] = True
                    stage_input["self_heal_action"] = "regenerate_with_confirmed_project_promotion"
                # Retry branches merge several historical payload fragments.
                # Restamp at the final persistence boundary so none of them
                # can downgrade the running worker's policy authority.
                stage_input = _restamp_stage_runtime_policy(stage_input)
                stage_row.input_json = stage_input
            elif visual_empty_response and visual_retry_plan is None:
                stage_input["visual_recovery_exhausted"] = True
                stage_input["self_heal_action"] = "visual_recovery_budget_exhausted"
                stage_row.input_json = stage_input
            if project:
                project.current_stage = stage_row.stage
                project.status = "queued" if will_retry else "failed"
                project.last_error = str(exc)[:4000]
                if browser_interaction_failure:
                    project_state = dict(project.state_json or {})
                    runtime_learning = dict(project_state.get("hermes_runtime_learning") or {})
                    browser_learning = dict(runtime_learning.get("browser_interaction") or {})
                    browser_learning.update({
                        "failure_count": int(browser_learning.get("failure_count") or 0) + 1,
                        "last_failure": str(exc)[:800],
                        "last_failure_stage": stage_row.stage,
                        "recovery_mode": "fresh_composer_sequential_upload",
                        "clipboard_input_disabled": True,
                        "workspace_relative_inbox_paths": True,
                        "updated_at": _stage_now().isoformat(),
                    })
                    runtime_learning["browser_interaction"] = browser_learning
                    project_state["hermes_runtime_learning"] = runtime_learning
                    project.state_json = project_state
                if _is_visual_grid_error(str(exc)):
                    variant_index = _stage_variant_index(stage_row, project)
                    _clean_generated_variant_assets(
                        db,
                        project,
                        ("VISUAL_PREVIEW", "FINAL_ASSETS"),
                        variant_index=variant_index,
                    )
                    grid_repair_count, max_grid_repairs = _visual_grid_repair_budget(stage_input)
                    if grid_repair_count < max_grid_repairs:
                        repair_reason = str(exc)[:500]
                        self_healed_stage = _create_repair_stage(
                            db,
                            project,
                            "VISUAL_PREVIEW",
                            reason=repair_reason,
                        )
                        repair_input = dict(self_healed_stage.input_json or {})
                        repair_input["force_fresh_response"] = True
                        repair_input["clear_stale_composer_before_send"] = True
                        repair_input["allow_visible_visual_recovery"] = False
                        repair_input["self_heal_action"] = "regenerate_visual_preview_with_strict_target_aspect_grid"
                        repair_input["visual_grid_repair_count"] = grid_repair_count + 1
                        repair_input["visual_repair_instruction"] = _visual_grid_repair_instruction(
                            db,
                            project,
                            expected_panel_count=_visual_expected_panel_count(repair_input),
                            repair_attempt=grid_repair_count + 1,
                        )
                        self_healed_stage.input_json = repair_input
                        project.current_stage = "VISUAL_PREVIEW"
                        project.status = "queued"
                        project.last_error = "Hermes is regenerating the visual preview with strict target-aspect grid geometry."
                        will_retry = False
                        stage_row.status = "failed"
                    else:
                        will_retry = False
                        if _visual_grid_failure_needs_browser_fallback(stage_input):
                            # Report exhaustion to the sole recovery writer.
                            # The old branch pre-authorized a browser before
                            # Hermes saw the incident, which could strand the
                            # project when API accounts were merely cooling.
                            return _handoff_api_stage_to_browser(
                                db,
                                project,
                                stage_row,
                                reason=str(exc),
                            )
                        stage_input["visual_recovery_exhausted"] = True
                        stage_input["self_heal_action"] = (
                            "visual_grid_recovery_budget_exhausted"
                        )
                        stage_row.input_json = stage_input
                elif "VISUAL_PREVIEW_PROVENANCE_INVALID" in str(exc):
                    _clean_final_assets(db, project)
                    self_healed_stage = _create_repair_stage(
                        db,
                        project,
                        "VISUAL_PREVIEW",
                        reason="self-heal rejected a non-assistant visual preview source",
                    )
                    will_retry = False
                    stage_row.status = "failed"
                elif "FINAL_ASSETS_SPLIT_UNSAFE" in str(exc):
                    _clean_final_assets(db, project)
                    repair_reason = str(exc)[:500]
                    final_rebuild_loop = (
                        stage_row.stage == "FINAL_ASSETS"
                        and (
                            bool(stage_input.get("force_chatgpt_rebuild"))
                            or int(stage_row.attempt or 0) >= 3
                            or int(stage_input.get("self_heal_count") or 0) >= 2
                        )
                    )
                    if final_rebuild_loop:
                        self_healed_stage = _reset_visual_preview_after_final_asset_loop(
                            db,
                            project,
                            reason=repair_reason,
                            variant_index=_stage_variant_index(stage_row, project),
                        )
                    else:
                        final_stage = _latest_stage(db, project, "FINAL_ASSETS")
                        if final_stage is None:
                            final_stage = _create_repair_stage(
                                db,
                                project,
                                "FINAL_ASSETS",
                                reason=repair_reason,
                            )
                        else:
                            _queue_existing_stage(db, project, final_stage, reason=repair_reason)
                        final_input = dict(final_stage.input_json or {})
                        final_input["force_chatgpt_rebuild"] = True
                        final_input["self_heal_action"] = "rebuild_final_assets_with_chatgpt_image_generation"
                        final_stage.input_json = final_input
                        self_healed_stage = final_stage
                    will_retry = False
                elif "FINAL_ASSETS_INVALID" in str(exc):
                    repair_reason = str(exc)[:500]
                    # A count/index mismatch after FINAL_ASSETS import is a
                    # local manifest/persistence failure.  The visual set has
                    # already passed CREATIVE_REVIEW, so paid image generation
                    # cannot improve it.  Rebuild only the local final-asset
                    # manifest from the approved preview, regardless of the
                    # retry count.  Structural split failures have their own
                    # bounded visual-rebuild circuit above.
                    self_healed_stage, _ = _repair_final_assets_if_needed(
                        db,
                        project,
                        reason=repair_reason,
                    )
                if stage_row.stage == "FACTS" and not will_retry:
                    config = dict(project.config_json or {})
                    product_id = int(config.get("product_id") or project.product_id or 0)
                    if product_id:
                        from app.data.models.hermes_agent import HermesContentProduct
                        product = (
                            db.query(HermesContentProduct)
                            .filter(
                                HermesContentProduct.workspace_id == project.workspace_id,
                                HermesContentProduct.id == product_id,
                            )
                            .one_or_none()
                        )
                        if product is not None:
                            product.meta_json = {
                                **dict(product.meta_json or {}),
                                "facts_status": "failed",
                                "facts_project_key": project.project_key,
                                "facts_error": str(exc)[:1000],
                            }
                if (
                    not will_retry
                    and self_healed_stage is None
                    and str(project.status or "").lower() == "failed"
                ):
                    # Local stage-specific repair code has no remaining
                    # action.  Do not strand the project in a generic failed
                    # state: normalize the complete incident and let the
                    # recovery role choose the next executable transition.
                    # This is the single terminal handoff used by every
                    # content role; deterministic/manual authority checks ran
                    # before reaching it.
                    stage_row.input_json = _restamp_stage_runtime_policy(
                        stage_input
                    )
                    db.add(stage_row)
                    db.add(project)
                    db.commit()
                    terminal_backend = (
                        execution_backend
                        if execution_backend in {"api", "browser"}
                        else "api"
                    )
                    if terminal_backend == "api":
                        return _handoff_api_stage_to_browser(
                            db,
                            project,
                            stage_row,
                            reason=str(exc),
                        )
                    supervised_browser_recovery = (
                        _recover_browser_fault_with_supervisor(
                            db,
                            project,
                            stage_row,
                            reason=str(exc),
                            browser_retry_exhausted=True,
                        )
                    )
                    if supervised_browser_recovery is not None:
                        return supervised_browser_recovery
            db.commit()
        if self_healed_stage is not None:
            healed_project = db.get(HermesContentFactoryProject, int(self_healed_stage.project_id))
            if healed_project is None:
                return {"status": "self_heal_project_missing", "stage_id": int(self_healed_stage.id)}
            task_id = _publish_stage(self_healed_stage, healed_project)
            db.commit()
            return {
                "status": "self_healed_requeued",
                "stage_id": int(self_healed_stage.id),
                "stage": self_healed_stage.stage,
                "task_id": task_id,
            }
        if will_retry:
            # ``retry_after`` was committed above. Do not publish an ETA task:
            # Celery reserves countdown deliveries against QoS immediately,
            # which can silently reduce a concurrency=4 worker to one active
            # process. Periodic self-heal releases the row after its durable
            # database deadline and publishes only runnable work.
            return {
                "status": "retry_scheduled",
                "stage_id": int(stage_id),
                "retry_in_seconds": int(retry_delay),
                "release_strategy": "periodic_self_heal",
            }
        return {"status": "failed", "error": str(exc)}
    finally:
        _release_project_execution_guard(execution_guard, guarded_project_id)
        db.close()


@celery_app.task(
    name="hermes_content_factory.release_stage_retry",
    queue=settings.HERMES_AGENT_TASK_QUEUE,
)
def release_content_factory_stage_retry(*, stage_id: int, release_token: str | None = None):
    """Consume legacy retry timers created before database-only cooldowns."""
    db = SessionLocal()
    try:
        stage_row, project, _project_id = _lock_stage_delivery_scope(
            db,
            int(stage_id),
        )
        if stage_row is None or stage_row.status != "retrying":
            return {"status": "ignored_stale", "stage_id": int(stage_id)}
        stage_input = dict(stage_row.input_json or {})
        registered_release_token = str(stage_input.get("retry_release_task_id") or "").strip()
        supplied_release_token = str(release_token or "").strip()
        # A timer is authoritative only while its exact lease token remains
        # attached to a retrying row.  An empty token means another recovery
        # path already cleared/replaced this timer; never release it anyway.
        if not registered_release_token or not supplied_release_token or supplied_release_token != registered_release_token:
            return {
                "status": "ignored_superseded_retry_timer",
                "stage_id": int(stage_id),
                "registered_release_token": registered_release_token,
                "supplied_release_token": supplied_release_token,
            }
        if project is None or project.current_stage != stage_row.stage:
            return {"status": "ignored_stale", "stage_id": int(stage_id)}
        if project.status == "paused" or bool(dict(project.config_json or {}).get("manual_paused", False)):
            return {"status": "ignored_paused", "stage_id": int(stage_id)}
        stage_input.pop("retry_after", None)
        stage_input.pop("retry_release_task_id", None)
        stage_input.pop("run_token", None)
        try:
            browser_slot, browser_cdp_url, queue_name = _retry_release_routing(
                db,
                project,
                stage_row,
                stage_input,
            )
        except Exception as exc:
            message = str(exc)
            if not (
                _is_browser_route_unavailable_error(message)
                or "BROWSER_BRIDGE_LOCK_CONFLICT" in message
                or "CONTENT_BROWSER_CAPACITY_FULL" in message
            ):
                raise
            recovery = _recover_browser_fault_with_supervisor(
                db,
                project,
                stage_row,
                reason=message,
            )
            if recovery is not None:
                return recovery
            # RETRY_BROWSER is the only decision without an immediate durable
            # transition.  Preserve the old bounded wait only in that explicit
            # case; never infer browser authority from the exception itself.
            stage_input.pop("retry_after", None)
            stage_input.pop("retry_release_task_id", None)
            stage_input["self_heal_action"] = (
                "recovery_supervisor_retry_project_browser_slot"
            )
            stage_row.input_json = stage_input
            stage_row.status = "failed"
            stage_row.completed_at = _stage_now()
            stage_row.error_message = message[:4000]
            project.status = "waiting_bridge"
            project.last_error = (
                "故障调度官已批准一次浏览器 Slot 重试；连接恢复后自动继续。"
            )
            db.add(stage_row)
            db.add(project)
            db.commit()
            return {
                "status": "recovery_supervisor_retry_browser_wait",
                "stage_id": int(stage_row.id),
                "project_key": project.project_key,
            }
        stage_input.pop("force_reacquire_browser_bridge", None)
        if browser_slot:
            stage_input["browser_slot"] = browser_slot
            stage_input["browser_bridge_id"] = browser_slot
        if browser_cdp_url:
            stage_input["browser_cdp_url"] = browser_cdp_url
        stage_input["queue"] = queue_name
        stage_row.input_json = stage_input
        stage_row.status = "queued"
        stage_row.celery_task_id = None
        stage_row.started_at = None
        stage_row.completed_at = None
        project.status = "queued"
        task_id = _publish_stage(stage_row, project)
        db.commit()
        return {"status": "released", "stage_id": int(stage_row.id), "task_id": task_id}
    finally:
        db.close()


def _bridge_cdp_url_for_stage(db, project: HermesContentFactoryProject, stage: HermesContentFactoryStage | None, stage_input: dict[str, Any]) -> str:
    state = dict(project.state_json or {})
    bridge_id = str(stage_input.get("browser_bridge_id") or state.get("browser_bridge_id") or "").strip()
    cdp_url = str(stage_input.get("browser_cdp_url") or state.get("browser_cdp_url") or "").strip()
    query = db.query(HermesBrowserBridge).filter(
        HermesBrowserBridge.workspace_id == int(project.workspace_id),
        HermesBrowserBridge.user_id == int(project.user_id or 0),
    )
    bridge = None
    if bridge_id:
        bridge = query.filter(HermesBrowserBridge.bridge_id == bridge_id).one_or_none()
    if bridge is None and cdp_url:
        bridge = query.filter(HermesBrowserBridge.cdp_url == cdp_url).order_by(HermesBrowserBridge.updated_at.desc()).first()
    if bridge is None:
        bridge = query.filter(HermesBrowserBridge.active_project_id == int(project.id)).order_by(HermesBrowserBridge.updated_at.desc()).first()
    if bridge is None:
        return ""
    if bridge.active_project_id not in (None, int(project.id)):
        return ""
    return str(getattr(bridge, "cdp_url", "") or "").strip()


def _browser_bridge_fresh_for_stage(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
    *,
    now: datetime,
    max_age_seconds: int = 180,
) -> bool:
    bridge_id = str(stage_input.get("browser_bridge_id") or dict(project.state_json or {}).get("browser_bridge_id") or "").strip()
    cdp_url = str(stage_input.get("browser_cdp_url") or "").strip()
    query = db.query(HermesBrowserBridge).filter(
        HermesBrowserBridge.workspace_id == project.workspace_id,
        HermesBrowserBridge.user_id == int(project.user_id or 0),
    )
    bridge = None
    if bridge_id:
        bridge = query.filter(HermesBrowserBridge.bridge_id == bridge_id).one_or_none()
    if bridge is None and cdp_url:
        bridge = query.filter(HermesBrowserBridge.cdp_url == cdp_url).order_by(HermesBrowserBridge.updated_at.desc()).first()
    if bridge is None or bridge.status != "active" or bridge.last_seen_at is None:
        return False
    return bridge.last_seen_at >= (now - timedelta(seconds=max(30, int(max_age_seconds))))


def _bridge_login_blocked(bridge: HermesBrowserBridge | None) -> bool:
    if bridge is None:
        return False
    meta = dict(getattr(bridge, "meta_json", None) or {})
    load = dict(getattr(bridge, "load_json", None) or {})
    status = str(
        meta.get("chatgpt_auth_status")
        or load.get("chatgpt_auth_status")
        or ""
    ).strip().lower()
    return status in {"login_required", "logged_out", "auth_required"}


def _browser_login_blocked_for_stage(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
) -> bool:
    state = dict(project.state_json or {})
    bridge_id = str(
        stage_input.get("browser_bridge_id")
        or state.get("browser_bridge_id")
        or ""
    ).strip()
    cdp_url = str(
        stage_input.get("browser_cdp_url")
        or state.get("browser_cdp_url")
        or ""
    ).strip()
    query = db.query(HermesBrowserBridge).filter(
        HermesBrowserBridge.workspace_id == int(project.workspace_id),
        HermesBrowserBridge.user_id == int(project.user_id or 0),
    )
    bridge = None
    if bridge_id:
        bridge = query.filter(
            HermesBrowserBridge.bridge_id == bridge_id,
        ).one_or_none()
    if bridge is None and cdp_url:
        bridge = query.filter(
            HermesBrowserBridge.cdp_url == cdp_url,
        ).order_by(HermesBrowserBridge.updated_at.desc()).first()
    return _bridge_login_blocked(bridge)


def _browser_cdp_reachable_for_stage(
    db,
    project: HermesContentFactoryProject,
    stage_input: dict[str, Any],
) -> bool:
    cdp_url = _bridge_cdp_url_for_stage(db, project, None, stage_input).rstrip("/")
    if not cdp_url:
        return False
    try:
        with urllib.request.urlopen(f"{cdp_url}/json/version", timeout=2) as response:
            return 200 <= int(response.status) < 500
    except Exception:
        return False


def _running_stage_browser_idle(
    db,
    project: HermesContentFactoryProject,
    stage: HermesContentFactoryStage,
    stage_input: dict[str, Any],
    *,
    now: datetime,
) -> tuple[bool, str | None]:
    if stage.status != "running" or stage.stage not in set(ROLE_URLS.keys()):
        return False, None
    api_route = _content_factory_api_route(db, stage.stage, stage_input)
    if stage_execution_backend(
        stage.stage,
        api_route=api_route,
        stage_input=stage_input,
    ) != "browser":
        # API-first stages must not create a local agent-browser daemon merely
        # because an old stage row still carries browser metadata.
        return False, None
    started = stage.started_at or stage.updated_at or stage.created_at
    if not started or started > now - timedelta(minutes=BROWSER_IDLE_RECOVERY_MINUTES):
        return False, None
    if (
        not _browser_bridge_fresh_for_stage(db, project, stage_input, now=now)
        or not _browser_cdp_reachable_for_stage(db, project, stage_input)
    ):
        # The lightweight HTTP checks do not start agent-browser.  Never use a
        # full DOM probe to discover that a stale/offline bridge is stale.
        return False, "browser_probe_skipped: bridge is stale or unreachable"
    cdp_url = _bridge_cdp_url_for_stage(db, project, stage, stage_input)
    if not cdp_url:
        return False, None
    previous_cdp = direct_browser_runtime.CDP_URL
    probe_session = ""
    try:
        direct_browser_runtime.CDP_URL = cdp_url
        probe_session = direct_browser_runtime._session_name()
        page_state = direct_browser_runtime._page_state()
        attachment_state = direct_browser_runtime._attachment_upload_state()
        text_length = direct_browser_runtime._composer_text_length()
    except Exception as exc:
        return False, f"browser_probe_failed:{exc}"
    finally:
        try:
            if probe_session:
                direct_browser_runtime.close_agent_browser_session_best_effort(
                    probe_session,
                )
        finally:
            direct_browser_runtime.CDP_URL = previous_cdp
    url = str(page_state.get("url") or "")
    text = str(page_state.get("text") or "")
    busy = bool(page_state.get("busy") or attachment_state.get("pending"))
    generated_count = int(page_state.get("generatedImageCount") or 0)
    image_count = int(page_state.get("imageCount") or 0)
    attachment_count = int(attachment_state.get("attachmentCount") or 0)
    sendable = bool(attachment_state.get("sendable"))
    if busy:
        return False, None
    if text_length > 0 and attachment_count == 0 and sendable:
        return True, (
            f"browser prompt stuck before send: cdp={cdp_url}, url={url}, "
            f"text_length={text_length}, attachments={attachment_count}, sendable={sendable}"
        )
    if text_length > 0 or text.strip() or attachment_count > 0:
        return False, None
    if stage.stage in {"VISUAL_PREVIEW", "FINAL_ASSETS"} and generated_count > 0:
        return False, None
    if "chatgpt.com" not in url:
        return False, None
    return True, (
        f"browser idle while stage running: cdp={cdp_url}, url={url}, "
        f"text_length={text_length}, attachments={attachment_count}, images={image_count}, generated={generated_count}"
    )


def _video_wait_heartbeat_is_stale(
    heartbeat: datetime | None,
    *,
    now: datetime,
) -> bool:
    """Use the waiter's own lease duration for every recovery path.

    Stage staleness is intentionally measured in minutes, but the video waiter
    renews every 20 seconds and owns a much shorter lease.  Reusing the stage
    cutoff here can strand already-downloaded provider results for the full
    stage timeout after a local QA/composition exception.
    """
    return heartbeat is None or heartbeat < now - timedelta(
        seconds=VIDEO_WAIT_STALE_SECONDS
    )


def _content_video_wait_lock_name(project_id: int) -> str:
    """Return the database-session lock that serializes one project's waiter.

    The heartbeat is a crash-recovery signal, not a mutual-exclusion primitive.
    Multimodal review and local composition can legitimately run longer than
    the heartbeat lease, so self-heal may publish a replacement while the
    original delivery is still working.  A MySQL named lock keeps those
    deliveries from reviewing and writing the same paid task rows at once.
    """
    return f"gmv:content-video-wait:{int(project_id)}"


def _content_video_wait_project_is_complete(
    project: HermesContentFactoryProject,
) -> bool:
    return (
        str(project.status or "").strip().lower() == "complete"
        and str(project.current_stage or "").strip().upper() == "COMPLETE"
    )


def _acquire_content_video_wait_lock(
    db,
    *,
    project_id: int,
) -> tuple[bool, Any | None]:
    """Acquire the waiter lock on a dedicated, pinned DB connection.

    A SQLAlchemy ``Session.commit()`` may return its current connection to the
    pool.  MySQL named locks are connection-owned, so acquiring through the
    session and later releasing through that same session can silently use two
    different pooled connections.  The original connection then sleeps in the
    pool while still owning the lock and every recovery waiter is rejected.

    Keep one engine connection checked out for the complete waiter lifetime
    and return it to the caller for same-connection release.
    """
    bind = db.get_bind()
    if str(getattr(getattr(bind, "dialect", None), "name", "")) != "mysql":
        # SQLite is used by the isolated regression suite and already
        # serializes writes.  Production MySQL receives the explicit lock.
        return True, None
    connection = bind.connect()
    try:
        acquired = connection.execute(
            sql_text("SELECT GET_LOCK(:lock_name, 0)"),
            {"lock_name": _content_video_wait_lock_name(project_id)},
        ).scalar()
    except Exception:
        connection.close()
        raise
    if int(acquired or 0) != 1:
        connection.close()
        return False, None
    return True, connection


def _release_content_video_wait_lock(
    lock_connection,
    *,
    project_id: int,
) -> None:
    if lock_connection is None:
        return
    try:
        lock_connection.execute(
            sql_text("SELECT RELEASE_LOCK(:lock_name)"),
            {"lock_name": _content_video_wait_lock_name(project_id)},
        ).scalar()
    finally:
        lock_connection.close()


def _content_video_wait_lock_is_owned(db, *, project_id: int) -> bool:
    """Return whether a live waiter currently owns the project lock."""
    bind = db.get_bind()
    if str(getattr(getattr(bind, "dialect", None), "name", "")) != "mysql":
        return False
    owner_id = db.execute(
        sql_text("SELECT IS_USED_LOCK(:lock_name)"),
        {"lock_name": _content_video_wait_lock_name(project_id)},
    ).scalar()
    return owner_id is not None


def _video_wait_recovery_publish_allowed(
    db,
    *,
    project_id: int,
    heartbeat_stale: bool,
    all_terminal: bool,
    wait_task_missing: bool,
) -> bool:
    """Return whether self-heal may publish one recovery waiter.

    Heartbeat age identifies a possibly lost delivery; the connection-owned
    project lock proves whether that delivery is actually still executing.
    Keeping this decision in one helper prevents a stage-specific recovery
    branch from accidentally ignoring the stronger liveness signal.
    """
    recovery_needed = bool(
        heartbeat_stale or (all_terminal and wait_task_missing)
    )
    if not recovery_needed:
        return False
    return not _content_video_wait_lock_is_owned(
        db,
        project_id=int(project_id),
    )


def _should_recover_global_video_waiter(
    project: HermesContentFactoryProject,
    video_state: dict[str, Any],
    video_task_ids: list[int],
    video_heartbeat: datetime | None,
    *,
    now: datetime,
    terminal_reconcile_needed: bool = False,
) -> bool:
    """Decide whether self-heal may recreate a project-global video waiter.

    Terminally failed projects retain their task ids for auditability. Those
    ids are not live work: recreating their waiter every minute only produces
    another immediate failure plus queue, worker, and journal churn.
    """
    if str(project.status or "").lower() in {"failed", "paused"}:
        return False
    if str(video_state.get("ai_video_terminal_failure") or "").strip():
        return False
    return bool(video_task_ids or terminal_reconcile_needed) and (
        _video_wait_heartbeat_is_stale(video_heartbeat, now=now)
    )


def _terminal_video_reconcile_needed(
    project: HermesContentFactoryProject,
    video_state: dict[str, Any],
    recorded_task_ids: list[int],
) -> bool:
    """Keep local composition recoverable after every provider task is terminal.

    A waiter can fail during contact-sheet review, ffmpeg composition, or guide
    creation after the last paid segment has downloaded.  Active-task-only
    recovery then sees an empty set and strands the project forever.  The
    submitted/completed variant ledger is the durable authority for remaining
    local work.
    """
    if not recorded_task_ids:
        return False
    if str(project.status or "").lower() in {"failed", "paused", "complete", "deleted"}:
        return False
    if str(video_state.get("ai_video_terminal_failure") or "").strip():
        return False
    pipeline = dict(video_state.get("video_variant_pipeline") or {})
    submitted = {
        int(value)
        for value in list(pipeline.get("submitted_indices") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    completed = {
        int(value)
        for value in list(pipeline.get("completed_indices") or [])
        if str(value).strip().isdigit() and int(value) > 0
    }
    return bool(submitted - completed)


def _active_video_task_ids_for_waiter(
    db,
    project: HermesContentFactoryProject,
    recorded_task_ids: list[int],
) -> list[int]:
    """Resolve waiter work from task state without loading provider JSON blobs.

    Historical task ids remain in the project audit ledger after completion.
    They must not be mistaken for active polling work. Missing rows remain
    active so the waiter can surface the existing integrity error instead of
    silently declaring the project drained.
    """
    unique_ids = sorted({
        int(value)
        for value in recorded_task_ids
        if str(value).strip().isdigit() and int(value) > 0
    })
    if not unique_ids:
        return []
    rows = (
        db.query(KieTask.id, KieTask.state)
        .filter(
            KieTask.id.in_(unique_ids),
            KieTask.workspace_id == int(project.workspace_id),
            KieTask.created_by_user_id == project.user_id,
        )
        .all()
    )
    terminal_ids = {
        int(task_id)
        for task_id, state in rows
        if str(state or "").strip().lower()
        in _TERMINAL_VIDEO_TASK_STATES
    }
    return [task_id for task_id in unique_ids if task_id not in terminal_ids]


def _normalize_completed_project_statuses(db, *, limit: int = 100) -> int:
    """Repair inconsistent terminal project and state-machine state.

    A late bridge reconciliation used to overwrite a completed project's
    status with ``waiting_bridge``.  Since the normal healer excludes the
    terminal stage, that label could survive forever.  Older completion paths
    also updated the project columns without recording the matching terminal
    state-machine transition.  The durable deliverable stage is authoritative:
    release any stale lease and normalize both representations without
    starting work or deleting user data.
    """
    from app.services.hermes_agent.content_factory import (
        _record_project_transition,
        _release_bridge_for_project,
    )

    machine_stage = (
        HermesContentFactoryProject.state_json["state_machine"]["stage"]
        .as_string()
    )
    machine_status = (
        HermesContentFactoryProject.state_json["state_machine"]["status"]
        .as_string()
    )
    rows = (
        db.query(HermesContentFactoryProject)
        .filter(
            HermesContentFactoryProject.current_stage == "COMPLETE",
            HermesContentFactoryProject.status != "deleted",
            or_(
                HermesContentFactoryProject.status != "complete",
                machine_stage.is_(None),
                machine_stage != "COMPLETE",
                machine_status.is_(None),
                machine_status != "complete",
            ),
        )
        .order_by(
            HermesContentFactoryProject.updated_at.asc(),
            HermesContentFactoryProject.id.asc(),
        )
        .with_for_update(skip_locked=True)
        .limit(max(1, int(limit)))
        .all()
    )
    for project in rows:
        prior_status = str(project.status or "").strip().lower()
        project.status = "complete"
        if prior_status != "complete":
            project.last_error = None
        _record_project_transition(
            project,
            stage="COMPLETE",
            status="complete",
            reason="terminal_project_reconciliation",
        )
        _release_bridge_for_project(db, project_id=int(project.id))
        db.add(project)
    if rows:
        db.flush()
    return len(rows)


def _retire_active_stages_for_completed_projects(db, *, limit: int = 500) -> int:
    """Close nonterminal stage rows whose owning project is already complete.

    A late retry delivery can persist after the project reaches ``COMPLETE``.
    The delivery must remain in the audit ledger, but it no longer represents
    executable work.  Retire it idempotently instead of letting monitoring or
    a future recovery pass mistake it for an active stage.
    """
    rows = (
        db.query(HermesContentFactoryStage)
        .join(
            HermesContentFactoryProject,
            HermesContentFactoryProject.id
            == HermesContentFactoryStage.project_id,
        )
        .filter(
            HermesContentFactoryProject.current_stage == "COMPLETE",
            HermesContentFactoryProject.status != "deleted",
            HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
        )
        .order_by(
            HermesContentFactoryStage.updated_at.asc(),
            HermesContentFactoryStage.id.asc(),
        )
        .with_for_update(skip_locked=True)
        .limit(max(1, int(limit)))
        .all()
    )
    completed_at = _stage_now()
    for stage in rows:
        stage.status = "superseded"
        stage.completed_at = completed_at
        stage.celery_task_id = None
        stage.error_message = (
            "Superseded by terminal project reconciliation: the owning project "
            "was already complete."
        )
        db.add(stage)
    if rows:
        db.flush()
    return len(rows)


@celery_app.task(
    name="hermes_content_factory.self_heal",
    queue=settings.HERMES_AGENT_TASK_QUEUE,
)
def self_heal_content_factory_projects(*, stale_minutes: int = 20, limit: int = 100) -> dict[str, Any]:
    """Repair interrupted content-factory projects and continue from the correct breakpoint."""
    # Beat publishes this sweep every minute, while multimodal reconciliation
    # can legitimately take several minutes.  Let exactly one delivery own the
    # global scan.  Without this lease, overlapping healers can read different
    # project generations and later overwrite a newer sibling video group's
    # state even though every per-project mutation is otherwise scoped.
    self_heal_lock = RedisDistributedLock(
        key="gmv:content_factory:self_heal:v1",
        owner_token=uuid.uuid4().hex,
        ttl_seconds=600,
        heartbeat_interval=30,
    )
    if not self_heal_lock.acquire(timeout=0):
        return {
            "status": "skipped_overlapping_self_heal",
            "checked": 0,
            "skipped": 1,
            "errors": [],
        }
    db = SessionLocal()
    stats: dict[str, Any] = {
        "checked": 0,
        "requeued": 0,
        "final_assets_rebuilt": 0,
        "stale_running_recovered": 0,
        "browser_idle_recovered": 0,
        "active_running_skipped": 0,
        "failed_stage_recovered": 0,
        "cooldown_scheduled": 0,
        "cooldown_released": 0,
        "ready_stage_released": 0,
        "video_wait_recovered": 0,
        "video_cooldown_retry_recovered": 0,
        "video_dependency_terminalized": 0,
        "expired_tasks_terminated": 0,
        "waiting_slot_started": 0,
        "retired_stage_skipped": 0,
        "terminal_status_repaired": 0,
        "terminal_stage_repaired": 0,
        "automatic_quality_recovered": 0,
        "automatic_quality_waiting": 0,
        "automatic_quality_epoch_cooling": 0,
        "final_video_quality_recovered": 0,
        "final_video_quality_waiting": 0,
        "invalid_contract_markers_reconciled": 0,
        "orphan_local_tasks_superseded": 0,
        "deleted_projects_finalized": 0,
        "deleted_projects_pending": 0,
        "bridge_leases_reconciled": {},
        "skipped": 0,
        "errors": [],
    }
    stages_to_publish: list[int] = []
    waiting_stages = ["COMPLETE"]
    now = _stage_now()
    stale_cutoff = now - timedelta(minutes=max(1, int(stale_minutes)))
    queued_cutoff = now - timedelta(minutes=2)
    dispatched_queue_cutoff = now - timedelta(
        seconds=QUEUED_DELIVERY_RECOVERY_SECONDS,
    )
    try:
        from app.services.hermes_agent.content_factory import (
            finalize_deleted_project,
            reconcile_bridge_project_leases,
        )

        deleted_project_ids = [
            int(project_id)
            for (project_id,) in (
                db.query(HermesContentFactoryProject.id)
                .filter(HermesContentFactoryProject.status == "deleted")
                .order_by(
                    HermesContentFactoryProject.updated_at.asc(),
                    HermesContentFactoryProject.id.asc(),
                )
                .limit(max(1, int(limit)))
                .all()
            )
        ]
        for deleted_project_id in deleted_project_ids:
            try:
                tombstone = db.get(
                    HermesContentFactoryProject,
                    int(deleted_project_id),
                )
                if tombstone is None:
                    continue
                finalized = finalize_deleted_project(db, tombstone)
                db.commit()
                if finalized:
                    stats["deleted_projects_finalized"] += 1
                else:
                    stats["deleted_projects_pending"] += 1
            except Exception as exc:
                db.rollback()
                stats["errors"].append({
                    "project_id": int(deleted_project_id),
                    "error": f"deleted project cleanup failed: {str(exc)[:420]}",
                })

        stats["terminal_status_repaired"] = _normalize_completed_project_statuses(
            db,
            limit=limit,
        )
        stats["terminal_stage_repaired"] = (
            _retire_active_stages_for_completed_projects(
                db,
                limit=max(1, int(limit)) * 5,
            )
        )
        stats["bridge_leases_reconciled"] = reconcile_bridge_project_leases(db)
        db.commit()
        project_ids = [
            int(project_id)
            for (project_id,) in (
            db.query(HermesContentFactoryProject)
            .with_entities(HermesContentFactoryProject.id)
            .filter(HermesContentFactoryProject.current_stage.notin_(waiting_stages))
            .filter(HermesContentFactoryProject.status.in_(("draft", "queued", "running", "ready", "failed", "waiting_bridge", "generating_video", "paused")))
            .order_by(HermesContentFactoryProject.updated_at.asc(), HermesContentFactoryProject.id.asc())
            .limit(max(1, int(limit)))
            .all()
            )
        ]
        for project_id in project_ids:
            project = (
                db.query(HermesContentFactoryProject)
                .filter(HermesContentFactoryProject.id == int(project_id))
                .populate_existing()
                .with_for_update(skip_locked=True)
                .one_or_none()
            )
            if project is None:
                stats["skipped"] += 1
                continue
            stats["checked"] += 1
            try:
                stats["invalid_contract_markers_reconciled"] += (
                    _reconcile_invalid_media_contract_task_markers(
                        db,
                        project,
                    )
                )
                orphan_task_ids = (
                    _supersede_untracked_local_content_video_tasks(
                        db,
                        project,
                    )
                )
                if orphan_task_ids:
                    stats["orphan_local_tasks_superseded"] += len(
                        orphan_task_ids
                    )
                    db.commit()
                    db.refresh(project)
                config = dict(project.config_json or {})
                if bool(config.get("manual_paused", False)):
                    stats["skipped"] += 1
                    continue
                if not bool(config.get("auto_run", True)):
                    stats["skipped"] += 1
                    continue
                # Dependency cleanup must not depend on an old video waiter
                # being delivered.  Reconcile every auto-run project during
                # the periodic sweep so deployment restarts and failed parent
                # chains cannot leave orphan waiting_dependency tasks behind.
                dependency_state = dict(project.state_json or {})
                dependency_task_ids = [
                    int(value)
                    for value in list(
                        dependency_state.get("ai_video_task_ids") or []
                    )
                    if str(value).strip().isdigit()
                ]
                if dependency_task_ids:
                    dependency_tasks = _scoped_content_video_tasks(
                        db,
                        project,
                        dependency_task_ids,
                    )
                    terminalized_ids = (
                        _fail_unreleasable_segment_dependencies(
                            db,
                            project,
                            dependency_tasks,
                        )
                    )
                    if terminalized_ids:
                        stats["video_dependency_terminalized"] += len(
                            terminalized_ids
                        )
                        db.commit()
                        db.refresh(project)
                if project.status == "paused":
                    paused_state = dict(project.state_json or {})
                    pause_reason_code = str(
                        paused_state.get("pause_reason_code")
                        or ""
                    ).strip().lower()
                    paused_stage = _latest_stage(
                        db,
                        project,
                        str(project.current_stage or ""),
                    )
                    legacy_reasonless_recovery_pause = (
                        _legacy_reasonless_recovery_pause(
                            project,
                            paused_stage,
                        )
                    )
                    if (
                        pause_reason_code
                        == "recovery_supervisor_nonretryable"
                        or legacy_reasonless_recovery_pause
                    ):
                        # Migrate pauses produced by the former no-route
                        # branch.  An empty eligible API set is a temporary
                        # inventory state, not missing human authority.  Feed
                        # the preserved incident back through the single
                        # recovery writer so the model can choose the current
                        # executable action and the scheduler can establish a
                        # durable API probe.
                        if paused_stage is not None:
                            recovery_result = _handoff_api_stage_to_browser(
                                db,
                                project,
                                paused_stage,
                                reason=str(
                                    paused_stage.error_message
                                    or project.last_error
                                    or "configured API inventory temporarily unavailable"
                                ),
                            )
                            if str(recovery_result.get("status") or "") in {
                                "recovery_supervisor_transition_in_progress",
                                "recovery_supervisor_transition_already_scheduled",
                            }:
                                stats["skipped"] += 1
                            else:
                                stats["failed_stage_recovered"] += 1
                            continue
                    if pause_reason_code == "operator_required":
                        legacy_state = dict(project.state_json or {})
                        fault_class = str(
                            legacy_state.get("operator_fault_class") or ""
                        )
                        if is_external_operator_blocker(
                            fault_class=fault_class,
                            missing_authority=bool(
                                legacy_state.get("missing_authority")
                            ),
                            irreconcilable_user_choice=bool(
                                legacy_state.get("irreconcilable_user_choice")
                            ),
                        ):
                            stats["skipped"] += 1
                            continue
                        # Migrate historical quality pauses created before the
                        # autonomy policy.  They were never true human-only
                        # blockers; preserve their evidence and let the normal
                        # final-quality recovery path choose a new layer.
                        legacy_task_ids = [
                            int(value)
                            for value in list(
                                legacy_state.get("operator_required_task_ids")
                                or []
                            )
                            if str(value).strip().isdigit()
                        ]
                        legacy_state.update({
                            "pause_reason_code": (
                                FINAL_VIDEO_QUALITY_RECOVERY_REASON
                            ),
                            "automatic_quality_paused_at": now.isoformat(),
                            "final_video_quality_failure": {
                                "at": now.isoformat(),
                                "message": "migrated legacy operator quality pause",
                                "task_ids": legacy_task_ids,
                                "evaluations": list(
                                    legacy_state.get(
                                        "operator_required_evaluations"
                                    ) or []
                                ),
                            },
                            "legacy_operator_pause_migrated_at": now.isoformat(),
                        })
                        project.state_json = legacy_state
                        db.add(project)
                        db.flush()
                    final_retry_ids, final_quality_decision = (
                        _resume_final_video_quality_pause(
                            db,
                            project,
                            now=now,
                        )
                    )
                    if final_retry_ids or bool(
                        final_quality_decision.get("recovered")
                    ):
                        repair_stage_id = int(
                            final_quality_decision.get("repair_stage_id") or 0
                        )
                        if repair_stage_id > 0:
                            stages_to_publish.append(repair_stage_id)
                        stats["final_video_quality_recovered"] += 1
                        continue
                    if bool(final_quality_decision.get("eligible")):
                        stats["final_video_quality_waiting"] += 1
                        continue
                    paused_stage = _latest_stage(
                        db,
                        project,
                        str(project.current_stage or ""),
                    )
                    paused_message = str(
                        (
                            paused_stage.error_message
                            if paused_stage is not None
                            else None
                        )
                        or project.last_error
                        or ""
                    )
                    if (
                        paused_stage is not None
                        and str(project.current_stage or "").upper()
                        == "VISUAL_PREVIEW"
                        and "PRODUCTION_PLAN_REFERENCE_CONTRACT_EMPTY"
                        in paused_message.upper()
                    ):
                        repaired_plan_stage = (
                            _reset_production_plan_after_empty_reference_contract(
                                db,
                                project,
                                paused_stage,
                                reason=paused_message,
                            )
                        )
                        if repaired_plan_stage is not None:
                            stages_to_publish.append(
                                int(repaired_plan_stage.id)
                            )
                            stats["failed_stage_recovered"] += 1
                            continue
                    recovered_stage, quality_decision = (
                        _resume_automatic_quality_pause(
                            db,
                            project,
                            now=now,
                        )
                    )
                    if recovered_stage is not None:
                        stages_to_publish.append(int(recovered_stage.id))
                        stats["automatic_quality_recovered"] += 1
                    elif bool(quality_decision.get("eligible")):
                        if (
                            int(quality_decision.get("attempt_count") or 0)
                            >= int(quality_decision.get("attempt_limit") or 0)
                        ):
                            stats["automatic_quality_epoch_cooling"] += 1
                        else:
                            stats["automatic_quality_waiting"] += 1
                    else:
                        stats["skipped"] += 1
                    continue
                # Video polling is project-global while the next variant may
                # already be advancing through DIRECTOR/PRODUCTION_PLAN. A
                # worker restart or an expired delayed Celery delivery must
                # not leave those in-flight segments stranded merely because
                # current_stage is no longer WAITING_VIDEO_INPUT.
                video_state = dict(project.state_json or {})
                recorded_video_task_ids = [
                    int(value) for value in list(video_state.get("ai_video_task_ids") or [])
                    if str(value).strip().isdigit()
                ]
                video_task_ids = _active_video_task_ids_for_waiter(
                    db,
                    project,
                    recorded_video_task_ids,
                )
                heartbeat_raw = str(video_state.get("ai_video_wait_heartbeat_at") or "")
                try:
                    video_heartbeat = datetime.fromisoformat(heartbeat_raw).replace(tzinfo=None)
                except (TypeError, ValueError):
                    video_heartbeat = None
                should_recover_video_waiter = _should_recover_global_video_waiter(
                    project,
                    video_state,
                    video_task_ids,
                    video_heartbeat,
                    now=now,
                    terminal_reconcile_needed=_terminal_video_reconcile_needed(
                        project,
                        video_state,
                        recorded_video_task_ids,
                    ),
                )
                active_video_waiter_owns_lock = (
                    should_recover_video_waiter
                    and _content_video_wait_lock_is_owned(
                        db,
                        project_id=int(project.id),
                    )
                )
                if should_recover_video_waiter and not active_video_waiter_owns_lock:
                    wait_task = wait_for_content_factory_videos.apply_async(
                        kwargs={"project_id": int(project.id)},
                        queue=project_hermes_queue(project),
                        priority=9,
                    )
                    video_state["ai_video_wait_task_id"] = wait_task.id
                    video_state["ai_video_wait_heartbeat_at"] = now.isoformat()
                    video_state["ai_video_wait_reason"] = "self-heal recovered stale global video waiter"
                    project.state_json = video_state
                    db.add(project)
                    db.flush()
                    stats["video_wait_recovered"] += 1
                elif active_video_waiter_owns_lock:
                    # A multimodal review/composition pass may exceed the
                    # heartbeat window.  The pinned advisory lock is the
                    # authoritative liveness signal; do not create one
                    # guaranteed-to-be-rejected recovery delivery per minute.
                    stats["active_running_skipped"] += 1
                if project.status == "draft":
                    request_state = dict(project.state_json or {})
                    if not str(request_state.get("browser_slot_requested_at") or "").strip():
                        stats["skipped"] += 1
                        continue
                    project.status = "waiting_bridge"
                    project.last_error = (
                        "Waiting for this user's requested browser slot to become available."
                    )
                    db.add(project)
                    db.flush()
                if (
                    project.current_stage in {"FINAL_ASSETS", "VIDEO_PROMPTS", "WAITING_VIDEO_INPUT", "EDIT_PACKAGE"}
                    and _latest_creative_review_auto_approved(project, db)
                ):
                    _clean_generated_stage_assets(db, project, ("VISUAL_PREVIEW", "FINAL_ASSETS"))
                    for stale_stage in db.query(HermesContentFactoryStage).filter(
                        HermesContentFactoryStage.project_id == project.id,
                        HermesContentFactoryStage.stage.in_((
                            "VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS",
                            "VIDEO_PROMPTS", "EDIT_PACKAGE",
                        )),
                        HermesContentFactoryStage.status.in_(("queued", "running", "retrying", "success", "failed")),
                    ).all():
                        stale_stage.status = "failed"
                        stale_stage.error_message = (
                            "Superseded by self-heal: creative review was auto-approved by fallback "
                            "without explicit image-content approval."
                        )
                    repair_stage = _create_repair_stage(
                        db,
                        project,
                        "VISUAL_PREVIEW",
                        reason="self-heal rejected fallback-approved creative review",
                    )
                    state = dict(project.state_json or {})
                    state["last_creative_review"] = {
                        "approved_for_split": False,
                        "repair_brief": "Regenerate visual preview; previous review was fallback-approved.",
                    }
                    project.state_json = state
                    project.current_stage = "VISUAL_PREVIEW"
                    project.status = "queued"
                    project.last_error = "Hermes detected a fallback-approved creative review and is regenerating the visual preview."
                    stages_to_publish.append(int(repair_stage.id))
                    stats["failed_stage_recovered"] += 1
                    continue

                if project.current_stage == "WAITING_VIDEO_INPUT":
                    state = dict(project.state_json or {})
                    resumed_variant_stage = _queue_next_unsubmitted_serial_variant_if_needed(
                        db,
                        project,
                        reason="self-heal resumed an unsubmitted serial video variant from WAITING_VIDEO_INPUT",
                    )
                    if resumed_variant_stage is not None:
                        stages_to_publish.append(int(resumed_variant_stage.id))
                        stats["requeued"] += 1
                        continue
                    stale_cross_stage_rows = db.query(HermesContentFactoryStage).filter(
                        HermesContentFactoryStage.project_id == project.id,
                        HermesContentFactoryStage.stage != project.current_stage,
                        HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
                    ).all()
                    for stale_cross_stage in stale_cross_stage_rows:
                        next_variant = _next_unsubmitted_serial_variant(project)
                        if (
                            next_variant is not None
                            and stale_cross_stage.stage in VARIANT_STAGES
                            and _stage_matches_variant(stale_cross_stage, project, int(next_variant))
                        ):
                            continue
                        stale_task_id = str(stale_cross_stage.celery_task_id or "").strip()
                        if stale_task_id:
                            if _safe_revoke_task(stale_task_id, terminate=True, signal="SIGTERM"):
                                stats["expired_tasks_terminated"] += 1
                        stale_cross_stage.status = "failed"
                        stale_cross_stage.completed_at = _stage_now()
                        stale_cross_stage.error_message = (
                            "Superseded by WAITING_VIDEO_INPUT; self-heal released stale browser-stage lock."
                        )
                    if stale_cross_stage_rows:
                        db.commit()
                        stats["stale_running_recovered"] += len(stale_cross_stage_rows)
                    task_ids = [int(value) for value in state.get("ai_video_task_ids") or []]
                    tasks = _scoped_content_video_tasks(db, project, task_ids)
                    if project.status == "failed" and state.get("ai_video_terminal_failure"):
                        failed_video_tasks = [
                            task for task in tasks if _is_failed_video_task(task)
                        ]
                        recovered_task_ids = _retry_failed_video_segments(
                            db,
                            project,
                            failed_video_tasks,
                            allow_exhausted_cooldown_retry=True,
                        )
                        if recovered_task_ids:
                            _schedule_video_wait(
                                db,
                                project,
                                countdown=20,
                                reason=(
                                    "self-heal resumed one exhausted Bandianwa video "
                                    "retry after the instability cooldown"
                                ),
                            )
                            stats["video_cooldown_retry_recovered"] += len(
                                recovered_task_ids
                            )
                            continue
                        active_provider_task_ids = [
                            int(task.id)
                            for task in tasks
                            if str(task.state or "").strip().lower()
                            in {
                                "queued_local", "queued", "pending", "waiting",
                                "waiting_dependency", "in_progress", "processing",
                                "generating", "downloading",
                            }
                        ]
                        if not failed_video_tasks and active_provider_task_ids:
                            resumed_state = dict(project.state_json or {})
                            resumed_state.pop("ai_video_terminal_failure", None)
                            resumed_state["ai_video_pending_task_ids"] = active_provider_task_ids
                            resumed_state["ai_video_terminal_drain_recovered_at"] = (
                                _stage_now().isoformat()
                            )
                            project.state_json = resumed_state
                            project.status = "generating_video"
                            project.last_error = (
                                "Hermes detected provider work still in flight after a stale "
                                "terminal delivery and resumed asynchronous draining."
                            )
                            db.add(project)
                            db.commit()
                            _schedule_video_wait(
                                db,
                                project,
                                countdown=20,
                                reason=(
                                    "self-heal resumed provider work left in flight by a "
                                    "late terminal delivery"
                                ),
                            )
                            stats["video_wait_recovered"] += 1
                            continue
                        stats["skipped"] += 1
                        continue
                    heartbeat_raw = str(state.get("ai_video_wait_heartbeat_at") or "")
                    try:
                        heartbeat = datetime.fromisoformat(heartbeat_raw).replace(tzinfo=None)
                    except (TypeError, ValueError):
                        heartbeat = None
                    heartbeat_stale = _video_wait_heartbeat_is_stale(
                        heartbeat,
                        now=now,
                    )
                    all_terminal = bool(task_ids) and len(tasks) == len(task_ids) and all(
                        _is_terminal_video_task(task) for task in tasks
                    )
                    wait_task_missing = not str(state.get("ai_video_wait_task_id") or "").strip()
                    recovery_candidate = bool(
                        task_ids
                        and (
                            heartbeat_stale
                            or (all_terminal and wait_task_missing)
                        )
                    )
                    if recovery_candidate:
                        # The project-global recovery branch above already
                        # treats the pinned MySQL advisory lock as the
                        # authoritative liveness signal.  WAITING_VIDEO_INPUT
                        # used to repeat the same heartbeat-only decision a
                        # second time without checking that lock.  A legitimate
                        # multimodal review can run longer than 45 seconds, so
                        # this second branch published one rejected waiter per
                        # minute and overwrote the registered successor id.
                        # Never publish a recovery delivery while the active
                        # waiter still owns the project lock.
                        if not _video_wait_recovery_publish_allowed(
                            db,
                            project_id=int(project.id),
                            heartbeat_stale=heartbeat_stale,
                            all_terminal=all_terminal,
                            wait_task_missing=wait_task_missing,
                        ):
                            stats["active_running_skipped"] += 1
                            stats["skipped"] += 1
                            continue
                        _schedule_video_wait(
                            db,
                            project,
                            countdown=0,
                            reason=(
                                "self-heal resumed terminal video results"
                                if all_terminal
                                else "self-heal recovered missing video wait heartbeat"
                            ),
                        )
                        stats["video_wait_recovered"] += 1
                        continue
                    if not task_ids:
                        stage = _create_repair_stage(
                            db,
                            project,
                            "VIDEO_PROMPTS",
                            reason="self-heal found WAITING_VIDEO_INPUT without AI video task ids",
                        )
                        stages_to_publish.append(int(stage.id))
                        stats["requeued"] += 1
                        continue
                    stats["skipped"] += 1
                    continue

                if project.current_stage in {"VIDEO_PROMPTS", "EDIT_PACKAGE"}:
                    repair_stage, _ = _repair_final_assets_if_needed(
                        db,
                        project,
                        reason="periodic self-heal detected incomplete final reference images before downstream stage",
                    )
                    if repair_stage is not None:
                        stages_to_publish.append(int(repair_stage.id))
                        stats["final_assets_rebuilt"] += 1
                        continue

                stage = _authoritative_self_heal_stage(
                    db,
                    project,
                    project.current_stage,
                    now=now,
                )
                if stage is None:
                    try:
                        stage = _create_repair_stage(
                            db,
                            project,
                            project.current_stage,
                            reason="periodic self-heal created missing current stage after browser slot became available",
                        )
                    except APIError as exc:
                        if exc.code not in {
                            "CONTENT_BROWSER_BRIDGE_REQUIRED",
                            "CONTENT_BROWSER_BRIDGE_OFFLINE",
                            "CONTENT_BROWSER_CAPACITY_FULL",
                            "CONTENT_BROWSER_LOGIN_REQUIRED",
                        }:
                            raise
                        wait_state = dict(project.state_json or {})
                        wait_state["browser_slot_requested_at"] = _stage_now().isoformat()
                        wait_state["browser_slot_request_stage"] = str(project.current_stage or "DIRECTOR")
                        wait_state["browser_slot_wait_error_code"] = str(exc.code)
                        wait_state["browser_slot_wait_error_at"] = _stage_now().isoformat()
                        project.state_json = wait_state
                        project.status = "waiting_bridge"
                        project.last_error = str(exc.message or "Waiting for an available browser slot.")[:4000]
                        db.add(project)
                        stats["skipped"] += 1
                        continue
                    stages_to_publish.append(int(stage.id))
                    stats["waiting_slot_started"] += 1
                    stats["requeued"] += 1
                    continue

                stage_error_message = str(
                    stage.error_message or project.last_error or ""
                )
                if (
                    str(stage.stage or "").upper() == "VISUAL_PREVIEW"
                    and str(stage.status or "").lower()
                    in {"failed", "retrying"}
                    and _is_production_plan_director_generation_mismatch(
                        stage_error_message
                    )
                ):
                    # A newer accepted Director artifact invalidates every
                    # older signed plan for this unfinished variant.  Reusing
                    # or retrying the visual row is both impossible and
                    # wasteful: the deterministic media gate will reject it
                    # before any provider call.  Quarantine the stale plan and
                    # all of its unfinished downstream media atomically, then
                    # author one replacement plan against the current
                    # Director generation.
                    repaired_plan_stage = (
                        _reset_production_plan_after_invalid_media_contract(
                            db,
                            project,
                            stage,
                            reason=stage_error_message,
                        )
                    )
                    repair_input = dict(
                        repaired_plan_stage.input_json or {}
                    )
                    repair_input["self_heal_action"] = (
                        "replan_after_director_generation_mismatch"
                    )
                    repair_input[
                        "director_generation_mismatch_stage_id"
                    ] = int(stage.id)
                    repaired_plan_stage.input_json = repair_input
                    stages_to_publish.append(int(repaired_plan_stage.id))
                    stats["failed_stage_recovered"] += 1
                    continue

                stale_cross_stage_rows = db.query(HermesContentFactoryStage).filter(
                    HermesContentFactoryStage.project_id == project.id,
                    HermesContentFactoryStage.stage != project.current_stage,
                    HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
                ).all()
                for stale_cross_stage in stale_cross_stage_rows:
                    stale_task_id = str(stale_cross_stage.celery_task_id or "").strip()
                    if stale_task_id:
                        if _safe_revoke_task(stale_task_id, terminate=True, signal="SIGTERM"):
                            stats["expired_tasks_terminated"] += 1
                    stale_cross_stage.status = "failed"
                    stale_cross_stage.completed_at = _stage_now()
                    stale_cross_stage.error_message = (
                        f"Superseded by project current stage {project.current_stage}; "
                        "self-heal released stale cross-stage lock."
                    )
                if stale_cross_stage_rows:
                    db.commit()

                stale_same_stage_rows = db.query(HermesContentFactoryStage).filter(
                    HermesContentFactoryStage.project_id == project.id,
                    HermesContentFactoryStage.stage == project.current_stage,
                    HermesContentFactoryStage.id != stage.id,
                    HermesContentFactoryStage.status.in_(("queued", "running", "retrying")),
                ).all()
                protected_same_stage_rows: list[HermesContentFactoryStage] = []
                for stale_same_stage in stale_same_stage_rows:
                    # A higher-id repair row can be created while the original
                    # browser delivery is still inside its valid execution
                    # lease. Never revoke that owner merely because it is not
                    # the newest row. _publish_stage will suppress the newer
                    # duplicate and keep the original owner authoritative.
                    # Revoking the owner first and then suppressing the newer
                    # row leaves both failed while the project still says
                    # running, which used to strand an otherwise healthy run.
                    if _stage_owns_publish_lease(stale_same_stage, now=now):
                        protected_same_stage_rows.append(stale_same_stage)
                        continue
                    stale_task_id = str(stale_same_stage.celery_task_id or "").strip()
                    if stale_task_id:
                        if _safe_revoke_task(stale_task_id, terminate=True, signal="SIGTERM"):
                            stats["expired_tasks_terminated"] += 1
                    stale_same_stage.status = "failed"
                    stale_same_stage.error_message = (
                        f"Superseded by latest {project.current_stage} stage {int(stage.id)}; "
                        "self-heal cleaned duplicate broker delivery."
                    )
                if len(protected_same_stage_rows) != len(stale_same_stage_rows):
                    db.commit()

                prior_policy_version = int(
                    dict(stage.input_json or {}).get(
                        "self_heal_policy_version"
                    )
                    or 0
                )
                heal_count, stage_input = (
                    _upgrade_self_heal_policy_generation(
                        stage,
                        now=now,
                    )
                )
                if (
                    stage.status == "running"
                    and prior_policy_version != SELF_HEAL_POLICY_VERSION
                ):
                    db.add(stage)
                    db.commit()
                # Keep auditing a running stage in this same self-heal pass. A
                # policy stamp mismatch is metadata, not proof that the task is
                # alive; continuing here can still recover an expired lease.
                running_expired = (
                    stage.status == "running"
                    and not _stage_owns_publish_lease(stage, now=now)
                )
                browser_idle, browser_idle_reason = _running_stage_browser_idle(
                    db,
                    project,
                    stage,
                    stage_input,
                    now=now,
                )
                browser_probe_failed = str(browser_idle_reason or "").startswith("browser_probe_failed:")
                if browser_probe_failed and stage.status == "running" and running_expired:
                    failed_probe_task_id = str(stage.celery_task_id or "").strip()
                    if failed_probe_task_id:
                        if _safe_revoke_task(failed_probe_task_id, terminate=True, signal="SIGTERM"):
                            stats["expired_tasks_terminated"] += 1
                    _queue_existing_stage(
                        db,
                        project,
                        stage,
                        reason=f"periodic self-heal recovered browser probe failure: {browser_idle_reason}",
                    )
                    stages_to_publish.append(int(stage.id))
                    stats["stale_running_recovered"] += 1
                    stats["browser_idle_recovered"] += 1
                    continue
                if browser_idle and not running_expired:
                    # The registered delivery still owns its execution lease.
                    # Its internal timeout/retry path is the only component
                    # allowed to replace it during this window.
                    stats["active_running_skipped"] += 1
                    continue
                if browser_idle:
                    idle_task_id = str(stage.celery_task_id or "").strip()
                    if idle_task_id:
                        if _safe_revoke_task(idle_task_id, terminate=True, signal="SIGTERM"):
                            stats["expired_tasks_terminated"] += 1
                    _queue_existing_stage(
                        db,
                        project,
                        stage,
                        reason=f"periodic self-heal recovered idle browser running stage: {browser_idle_reason}",
                    )
                    stages_to_publish.append(int(stage.id))
                    stats["stale_running_recovered"] += 1
                    stats["browser_idle_recovered"] += 1
                    continue

                if running_expired:
                    expired_task_id = str(stage.celery_task_id or "").strip()
                    if expired_task_id:
                        if _safe_revoke_task(expired_task_id, terminate=True, signal="SIGTERM"):
                            stats["expired_tasks_terminated"] += 1
                    reason = (
                        f"periodic self-heal recovered idle browser running stage: {browser_idle_reason}"
                        if browser_idle
                        else "periodic self-heal recovered stale running stage"
                    )
                    _queue_existing_stage(db, project, stage, reason=reason)
                    stages_to_publish.append(int(stage.id))
                    stats["stale_running_recovered"] += 1
                    if browser_idle:
                        stats["browser_idle_recovered"] += 1
                    continue

                if (
                    project.status == "failed"
                    and stage.status == "failed"
                    and bool(stage_input.get("force_reacquire_browser_bridge"))
                ):
                    message = str(stage.error_message or project.last_error or "")
                    stage_input = _release_degraded_project_bridge(
                        db,
                        project,
                        stage_input,
                        reason=message or "self-heal released bridge after failed reacquire",
                    )
                    stage.input_json = stage_input
                    project.status = "waiting_bridge"
                    project.last_error = (
                        "Browser bridge is unavailable for this user's device; "
                        "Hermes will resume after this user's local bridge reconnects."
                    )
                    db.commit()
                    stats["skipped"] += 1
                    continue

                if project.status == "waiting_bridge":
                    waiting_api_input = _waiting_bridge_api_retry_input(
                        db,
                        stage=stage.stage,
                        stage_input=stage_input,
                    )
                    if waiting_api_input is not None:
                        stage.input_json = _restamp_stage_runtime_policy(
                            waiting_api_input
                        )
                        _queue_existing_stage(
                            db,
                            project,
                            stage,
                            reason=(
                                "periodic self-heal restored API authority "
                                "for a stale waiting_bridge stage"
                            ),
                        )
                        stages_to_publish.append(int(stage.id))
                        stats["failed_stage_recovered"] += 1
                        continue
                    login_blocked = _browser_login_blocked_for_stage(
                        db,
                        project,
                        stage_input,
                    )
                    bridge_ready = (
                        _browser_bridge_fresh_for_stage(db, project, stage_input, now=now)
                        and _browser_cdp_reachable_for_stage(db, project, stage_input)
                        and not login_blocked
                    )
                    if login_blocked:
                        supervised_browser_recovery = (
                            _recover_browser_fault_with_supervisor(
                                db,
                                project,
                                stage,
                                reason="CHATGPT_SESSION_LOGIN_REQUIRED",
                            )
                        )
                        if supervised_browser_recovery is not None:
                            stats["failed_stage_recovered"] += 1
                        else:
                            stats["skipped"] += 1
                        continue
                    if not bridge_ready:
                        # Keep the demand visible to the local Agent while this
                        # project waits. Without refreshing this request, the
                        # Agent drops the retired sticky slot from its desired
                        # set and self-heal can only observe the outage forever.
                        wait_state = dict(project.state_json or {})
                        wait_state["browser_slot_requested_at"] = now.isoformat()
                        wait_state["browser_slot_request_stage"] = str(
                            project.current_stage or stage.stage
                        )
                        wait_state["browser_slot_wait_error_code"] = (
                            "CONTENT_BROWSER_BRIDGE_OFFLINE"
                        )
                        wait_state["browser_slot_wait_error_at"] = now.isoformat()
                        project.state_json = wait_state
                        db.add(project)

                        try:
                            browser_slot, browser_cdp_url, queue_name = _locked_browser_routing(
                                db,
                                project,
                                stage_input,
                            )
                        except APIError as exc:
                            if exc.code not in {
                                "CONTENT_BROWSER_BRIDGE_REQUIRED",
                                "CONTENT_BROWSER_BRIDGE_OFFLINE",
                                "CONTENT_BROWSER_LOCKED_SLOT_UNAVAILABLE",
                                "CONTENT_BROWSER_CAPACITY_FULL",
                                "CONTENT_BROWSER_LOGIN_REQUIRED",
                                "CONTENT_BROWSER_DEVICE_SELECTION_REQUIRED",
                            }:
                                raise
                            project.status = "waiting_bridge"
                            project.last_error = str(
                                exc.message
                                or "Waiting for this project's browser slot to recover."
                            )[:4000]
                            stage.input_json = stage_input
                            db.add(stage)
                            db.commit()
                            stats["skipped"] += 1
                            continue
                        except (RuntimeError, ValueError) as exc:
                            message = str(exc)
                            if not (
                                _is_browser_route_unavailable_error(message)
                                or "BROWSER_BRIDGE_LOCK_CONFLICT" in message
                                or "BROWSER_BRIDGE_LOCK_MISSING" in message
                            ):
                                raise
                            project.status = "waiting_bridge"
                            project.last_error = message[:4000]
                            stage.input_json = stage_input
                            db.add(stage)
                            db.commit()
                            stats["skipped"] += 1
                            continue
                        else:
                            stage_input["browser_slot"] = browser_slot
                            stage_input["browser_bridge_id"] = browser_slot
                            stage_input["browser_cdp_url"] = browser_cdp_url
                            stage_input["queue"] = queue_name
                            stage.input_json = stage_input
                            db.add(stage)
                            bridge_ready = True

                    if bridge_ready:
                        _queue_existing_stage(db, project, stage, reason="periodic self-heal resumed after browser bridge became reachable")
                        stages_to_publish.append(int(stage.id))
                        stats["failed_stage_recovered"] += 1
                    else:
                        stats["skipped"] += 1
                    continue

                queued_since = stage.updated_at or stage.created_at
                queue_recovery_cutoff = (
                    dispatched_queue_cutoff
                    if str(stage.celery_task_id or "").strip()
                    else queued_cutoff
                )
                if stage.status == "retrying":
                    message = str(stage.error_message or project.last_error or "")
                    if is_local_worker_stage(stage.stage, stage_input):
                        # A server-local retry must not remain behind an API
                        # inventory cooldown or a browser-login wait left by an
                        # older worker.  Re-publish it through the same durable
                        # stage identity; the worker's idempotent claim still
                        # prevents duplicate files or downstream stages.
                        stage_input = clear_external_retry_barriers_for_local_stage(
                            stage.stage,
                            stage_input,
                        )
                        stage.input_json = stage_input
                        _queue_existing_stage(
                            db,
                            project,
                            stage,
                            reason=(
                                "periodic self-heal released server-local stage "
                                "from stale external retry barriers"
                            ),
                        )
                        stages_to_publish.append(int(stage.id))
                        stats["ready_stage_released"] += 1
                        continue
                    if (
                        _is_visual_grid_error(message)
                        and _visual_grid_repair_budget_exhausted(stage_input)
                        and not _stage_owns_publish_lease(stage, now=now)
                    ):
                        if _visual_grid_failure_needs_browser_fallback(stage_input):
                            _handoff_api_stage_to_browser(
                                db,
                                project,
                                stage,
                                reason=message,
                            )
                            stats["failed_stage_recovered"] += 1
                            continue
                        stage_input["visual_recovery_exhausted"] = True
                        stage_input["self_heal_action"] = (
                            "visual_grid_recovery_budget_exhausted"
                        )
                        stage.input_json = stage_input
                        _schedule_exhausted_self_heal_stage(
                            project,
                            stage,
                            now=now,
                        )
                        db.add(stage)
                        db.add(project)
                        db.commit()
                        stats["cooldown_scheduled"] += 1
                        continue
                    if _is_browser_route_unavailable_error(message):
                        stage_input = _release_degraded_project_bridge(
                            db,
                            project,
                            stage_input,
                            reason=message or "self-heal released unavailable browser route",
                        )
                        stage.input_json = stage_input
                        if (
                            not _browser_bridge_fresh_for_stage(db, project, stage_input, now=now)
                            or not _browser_cdp_reachable_for_stage(db, project, stage_input)
                        ):
                            stage.status = "failed"
                            stage.completed_at = _stage_now()
                            project.current_stage = stage.stage
                            project.status = "waiting_bridge"
                            project.last_error = (
                                "Browser bridge is unavailable for this user's device; "
                                "Hermes will resume after this user's local bridge reconnects."
                            )
                            db.commit()
                            stats["failed_stage_recovered"] += 1
                            continue
                    retry_after_raw = str(stage_input.get("retry_after") or "").strip()
                    if retry_after_raw:
                        try:
                            retry_after_at = datetime.fromisoformat(retry_after_raw)
                        except ValueError:
                            retry_after_at = None
                        if retry_after_at is not None and retry_after_at > now:
                            if _is_chatgpt_rate_limit_error(message):
                                last_dialog_probe_raw = str(stage_input.get("rate_limit_dialog_probe_at") or "").strip()
                                try:
                                    last_dialog_probe = datetime.fromisoformat(last_dialog_probe_raw)
                                except (TypeError, ValueError):
                                    last_dialog_probe = None
                                if last_dialog_probe is None or last_dialog_probe < now - timedelta(seconds=60):
                                    cdp_url = str(stage_input.get("browser_cdp_url") or "").strip()
                                    probe = direct_browser_runtime.dismiss_chatgpt_rate_limit_dialogs_best_effort(
                                        cdp_url=cdp_url,
                                    )
                                    stage_input["rate_limit_dialog_probe_at"] = now.isoformat()
                                    stage_input["rate_limit_dialog_probe_result"] = probe
                                    stage.input_json = stage_input
                                    db.add(stage)
                                    db.commit()
                            stats["skipped"] += 1
                            continue
                    if bool(stage_input.get("recovery_api_probe_pending")):
                        recovered_route = _content_factory_api_route(
                            db,
                            stage.stage,
                            stage_input,
                            allow_browser_handoff_reversal=True,
                        )
                        if not recovered_route:
                            wait_seconds = _recovery_api_probe_delay(stage_input)
                            stage_input["recovery_api_probe_count"] = int(
                                stage_input.get("recovery_api_probe_count") or 0
                            ) + 1
                            stage_input["retry_after"] = (
                                now + timedelta(seconds=wait_seconds)
                            ).isoformat()
                            stage_input["recovery_api_last_probe_at"] = now.isoformat()
                            stage_input["retry_release_strategy"] = (
                                "database_route_probe_at_periodic_self_heal"
                            )
                            stage.input_json = _restamp_stage_runtime_policy(
                                stage_input
                            )
                            stage.status = "retrying"
                            stage.celery_task_id = None
                            project.status = "queued"
                            project.current_stage = stage.stage
                            project.last_error = (
                                f"平台统一 API 暂无可用账号；故障调度官将在约 {wait_seconds} 秒后"
                                "继续自动探测，不会启动浏览器或重复提交。"
                            )
                            db.add(stage)
                            db.add(project)
                            db.commit()
                            stats["cooldown_scheduled"] += 1
                            continue
                        stage_input = _api_retry_input_after_recovery(
                            stage_input,
                            api_route=recovered_route,
                            decision_action="SELF_HEAL_API_PROBE_RECOVERED",
                        )
                        for key in (
                            "recovery_api_probe_pending",
                            "recovery_api_probe_reason",
                            "recovery_api_last_probe_at",
                        ):
                            stage_input.pop(key, None)
                        stage.input_json = _restamp_stage_runtime_policy(
                            stage_input
                        )
                        project.status = "queued"
                        project.current_stage = stage.stage
                        project.last_error = None
                        db.add(stage)
                        db.add(project)
                        db.flush()
                    if bool(stage_input.get("self_heal_circuit_open")):
                        variant_index = _stage_variant_index(stage, project)
                        if stage.stage == "VISUAL_PREVIEW":
                            _clean_generated_variant_assets(
                                db,
                                project,
                                ("VISUAL_PREVIEW", "FINAL_ASSETS"),
                                variant_index=variant_index,
                            )
                        _prepare_exhausted_self_heal_release(stage, now=now)
                        _queue_existing_stage(
                            db,
                            project,
                            stage,
                            reason="periodic self-heal resumed project after circuit cooldown",
                        )
                        stages_to_publish.append(int(stage.id))
                        stats["cooldown_released"] += 1
                        continue
                    _queue_existing_stage(db, project, stage, reason="periodic self-heal released due retry")
                    stages_to_publish.append(int(stage.id))
                    stats["ready_stage_released"] += 1
                    continue
                if stage.status in {"queued", "retrying"} and queued_since < queue_recovery_cutoff:
                    _queue_existing_stage(db, project, stage, reason="periodic self-heal republished queued stage")
                    stages_to_publish.append(int(stage.id))
                    stats["requeued"] += 1
                    continue

                terminal_error_code = _terminal_self_heal_error_code(
                    str(stage.error_message or project.last_error or "")
                )
                if (
                    project.status == "failed"
                    and stage.status == "failed"
                    and stage.stage == "VISUAL_PREVIEW"
                    and terminal_error_code
                    == "PRODUCTION_PLAN_REFERENCE_CONTRACT_EMPTY"
                ):
                    repaired_plan_stage = (
                        _reset_production_plan_after_empty_reference_contract(
                            db,
                            project,
                            stage,
                            reason=str(
                                stage.error_message
                                or project.last_error
                                or terminal_error_code
                            ),
                        )
                    )
                    if repaired_plan_stage is not None:
                        stages_to_publish.append(int(repaired_plan_stage.id))
                        stats["failed_stage_recovered"] += 1
                        continue
                if (
                    project.status == "failed"
                    and stage.status == "failed"
                    and terminal_error_code is not None
                ):
                    _pause_terminal_self_heal_stage(
                        project,
                        stage,
                        error_code=terminal_error_code,
                        now=now,
                    )
                    db.add(stage)
                    db.add(project)
                    db.commit()
                    stats["skipped"] += 1
                    continue

                if (
                    project.status == "failed"
                    and stage.status == "failed"
                    and stage.stage == "VISUAL_PREVIEW"
                    and _is_visual_grid_error(str(stage.error_message or project.last_error or ""))
                ):
                    stage_input = dict(stage.input_json or {})
                    grid_repair_count, max_grid_repairs = _visual_grid_repair_budget(stage_input)
                    if grid_repair_count < max_grid_repairs:
                        variant_index = _stage_variant_index(stage, project)
                        _clean_generated_variant_assets(
                            db,
                            project,
                            ("VISUAL_PREVIEW", "FINAL_ASSETS"),
                            variant_index=variant_index,
                        )
                        repair_stage = _create_repair_stage(
                            db,
                            project,
                            "VISUAL_PREVIEW",
                            reason=str(stage.error_message or project.last_error or "")[:500],
                        )
                        repair_input = dict(repair_stage.input_json or {})
                        repair_input["force_fresh_response"] = True
                        repair_input["clear_stale_composer_before_send"] = True
                        repair_input["allow_visible_visual_recovery"] = False
                        repair_input["self_heal_action"] = "regenerate_visual_preview_with_strict_target_aspect_grid"
                        repair_input["visual_grid_repair_count"] = grid_repair_count + 1
                        repair_input["visual_repair_instruction"] = _visual_grid_repair_instruction(
                            db,
                            project,
                            expected_panel_count=_visual_expected_panel_count(repair_input),
                            repair_attempt=grid_repair_count + 1,
                        )
                        repair_stage.input_json = repair_input
                        project.current_stage = "VISUAL_PREVIEW"
                        project.status = "queued"
                        project.last_error = "Hermes is regenerating the visual preview with strict target-aspect grid geometry."
                        stages_to_publish.append(int(repair_stage.id))
                        stats["failed_stage_recovered"] += 1
                        continue

                if project.status == "ready" and stage.status in {"failed", "success"}:
                    if stage.status == "success":
                        stage = _create_repair_stage(
                            db,
                            project,
                            project.current_stage,
                            reason="periodic self-heal continued ready project from current breakpoint",
                        )
                    else:
                        _queue_existing_stage(db, project, stage, reason="periodic self-heal retried ready failed current stage")
                    stages_to_publish.append(int(stage.id))
                    stats["ready_stage_released"] += 1
                    continue

                if (
                    project.status == "failed"
                    and stage.status == "failed"
                    and heal_count >= SELF_HEAL_FAST_RETRY_LIMIT
                ):
                    message = str(stage.error_message or project.last_error or "")
                    if "CONTENT_PRODUCT_ASSETS_REQUIRED" in message:
                        _pause_external_input_stage(
                            project,
                            stage,
                            fault_class=(
                                "MISSING_AUTHORITATIVE_PRODUCT_ASSET"
                            ),
                            now=now,
                        )
                        db.add(stage)
                        db.add(project)
                        db.commit()
                        stats["skipped"] += 1
                        continue
                    cdp_disconnected = any(
                        marker in message.lower()
                        for marker in (
                            "all cdp discovery methods failed",
                            "failed to connect to cdp",
                            "websocket connect failed",
                            "connection refused",
                            "cdp command timed out",
                            "browser command timed out",
                        )
                    )
                    if cdp_disconnected and (
                        not _browser_bridge_fresh_for_stage(db, project, stage_input, now=now)
                        or not _browser_cdp_reachable_for_stage(db, project, stage_input)
                    ):
                        project.status = "waiting_bridge"
                        project.last_error = (
                            "Browser bridge is offline or stale; Hermes will resume after this user's local bridge reconnects."
                        )
                        db.commit()
                        stats["skipped"] += 1
                        continue
                    _schedule_exhausted_self_heal_stage(project, stage, now=now)
                    stats["cooldown_scheduled"] += 1
                    continue

                if project.status == "failed" and stage.status == "failed":
                    message = str(stage.error_message or project.last_error or "")
                    if bool(stage_input.get("visual_recovery_exhausted")):
                        _schedule_exhausted_self_heal_stage(
                            project,
                            stage,
                            now=now,
                        )
                        db.add(stage)
                        db.add(project)
                        db.commit()
                        stats["cooldown_scheduled"] += 1
                        continue
                    if _visual_api_provider_budget_exhausted(stage.stage, stage_input):
                        # Legacy code forced every exhausted API epoch into a
                        # browser wait.  That bypassed the fault role and made
                        # an offline maintenance Slot override configured API
                        # accounts.  Report the incident to the sole recovery
                        # writer; it can rotate, cool/probe, or choose browser
                        # only when the browser is actually eligible.
                        stage.input_json = stage_input
                        db.add(stage)
                        db.add(project)
                        db.commit()
                        recovery_result = _handoff_api_stage_to_browser(
                            db,
                            project,
                            stage,
                            reason=(
                                message
                                or "Every available image API exhausted its bounded provider retry budget."
                            ),
                        )
                        if str(recovery_result.get("status") or "") in {
                            "recovery_supervisor_transition_in_progress",
                            "recovery_supervisor_transition_already_scheduled",
                        }:
                            stats["skipped"] += 1
                        else:
                            stats["failed_stage_recovered"] += 1
                        continue
                    force_reacquire_failed = bool(stage_input.get("force_reacquire_browser_bridge"))
                    cdp_disconnected = any(
                        marker.lower() in message.lower()
                        for marker in (
                            "all cdp discovery methods failed",
                            "failed to connect to cdp",
                            "websocket connect failed",
                            "connection refused",
                            "cdp command timed out",
                            "browser command timed out",
                            "int() argument must be a string",
                        )
                    )
                    if force_reacquire_failed:
                        stage_input = _release_degraded_project_bridge(
                            db,
                            project,
                            stage_input,
                            reason=message or "self-heal released bridge after failed reacquire",
                        )
                        stage.input_json = stage_input
                        project.status = "waiting_bridge"
                        project.last_error = (
                            "Browser bridge is unavailable for this user's device; "
                            "Hermes will resume after this user's local bridge reconnects."
                        )
                        db.commit()
                        stats["skipped"] += 1
                        continue
                    if cdp_disconnected and (
                        not _browser_bridge_fresh_for_stage(db, project, stage_input, now=now)
                        or not _browser_cdp_reachable_for_stage(db, project, stage_input)
                    ):
                        project.status = "waiting_bridge"
                        project.last_error = (
                            "Browser bridge is offline or stale; Hermes will resume after this user's local bridge reconnects."
                        )
                        db.commit()
                        stats["skipped"] += 1
                        continue
                    if "CONTENT_PRODUCT_ASSETS_REQUIRED" in message:
                        _pause_external_input_stage(
                            project,
                            stage,
                            fault_class=(
                                "MISSING_AUTHORITATIVE_PRODUCT_ASSET"
                            ),
                            now=now,
                        )
                        db.add(stage)
                        db.add(project)
                        db.commit()
                        stats["skipped"] += 1
                        continue
                    if stage.stage == "VISUAL_PREVIEW" and _is_transient_provider_error(message):
                        _clean_generated_variant_assets(
                            db,
                            project,
                            ("VISUAL_PREVIEW", "FINAL_ASSETS"),
                            variant_index=_stage_variant_index(stage, project),
                        )
                        _prepare_visual_stage_for_fresh_retry(
                            stage,
                            action="regenerate_visual_after_transient_provider_failure",
                        )
                    _queue_existing_stage(db, project, stage, reason="periodic self-heal retried failed current stage")
                    stages_to_publish.append(int(stage.id))
                    stats["failed_stage_recovered"] += 1
                    continue

                stats["skipped"] += 1
            except Exception as exc:
                stats["errors"].append({"project_key": project.project_key, "error": str(exc)[:500]})

        db.commit()
        for stage_id in stages_to_publish:
            stage = db.get(HermesContentFactoryStage, int(stage_id))
            if stage is None or stage.status != "queued":
                continue
            project = db.get(HermesContentFactoryProject, int(stage.project_id))
            if project is None:
                continue
            _publish_stage(stage, project)
            stats["requeued"] += 1
        db.commit()
        return stats
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()
        self_heal_lock.release()


@celery_app.task(
    bind=True,
    name="hermes_content_factory.wait_videos",
    queue=settings.HERMES_AGENT_TASK_QUEUE,
    max_retries=0,
)
def wait_for_content_factory_videos(
    self,
    *,
    project_id: int,
    predecessor_wait_id: str | None = None,
):
    db = SessionLocal()
    waiter_lock_acquired = False
    waiter_lock_connection = None
    try:
        waiter_lock_acquired, waiter_lock_connection = _acquire_content_video_wait_lock(
            db,
            project_id=int(project_id),
        )
        if not waiter_lock_acquired:
            return {
                "status": "ignored_concurrent_waiter",
                "project_id": int(project_id),
                "request_id": str(getattr(self.request, "id", "") or ""),
            }
        project = (
            db.query(HermesContentFactoryProject)
            .filter(HermesContentFactoryProject.id == int(project_id))
            .with_for_update()
            .one_or_none()
        )
        if project is None:
            return {"status": "missing"}
        if str(project.status or "").lower() == "deleted":
            return {"status": "deleted", "project_id": int(project.id)}
        if _content_video_wait_project_is_complete(project):
            # Delayed successors may already be in RabbitMQ when another
            # waiter completes the final local merge.  They are audit-only
            # stale deliveries and must not repeat vision review, composition,
            # guide generation, or asset-row insertion.
            return {
                "status": "already_complete",
                "project_id": int(project.id),
            }
        pause_mode = _video_wait_pause_mode(project)
        if pause_mode in {"manual", "paused"}:
            return {"status": "paused", "project_id": int(project.id)}
        draining_auto_paused_video = pause_mode == "drain_submitted_video"
        if draining_auto_paused_video and str(project.status or "").lower() != "paused":
            project.status = "paused"
        # This waiter runs every 20 seconds.  It may request the same
        # controlled API-video sleep idempotently, but never releases the
        # project lease or repeatedly starts/stops Chrome.
        if project.current_stage == "WAITING_VIDEO_INPUT":
            hibernate_project_browser_slot_for_api_video(db, project=project)
        state = dict(project.state_json or {})
        request_id = str(getattr(self.request, "id", "") or "")
        registered_wait_id = str(state.get("ai_video_wait_task_id") or "")
        expected_successor = bool(
            predecessor_wait_id
            and registered_wait_id
            and str(predecessor_wait_id) == registered_wait_id
        )
        if registered_wait_id and request_id and registered_wait_id != request_id:
            heartbeat_raw = str(state.get("ai_video_wait_heartbeat_at") or "")
            try:
                heartbeat = datetime.fromisoformat(heartbeat_raw).replace(tzinfo=None)
            except (TypeError, ValueError):
                heartbeat = None
            waiter_is_fresh = (
                heartbeat is not None
                and heartbeat >= _stage_now() - timedelta(seconds=VIDEO_WAIT_STALE_SECONDS)
            )
            if waiter_is_fresh and not expected_successor:
                return {
                    "status": "ignored_superseded_waiter",
                    "project_id": int(project.id),
                    "registered_task_id": registered_wait_id,
                    "request_id": request_id,
                }
            state["ai_video_wait_takeover_from"] = registered_wait_id
            state["ai_video_wait_takeover_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            if expected_successor:
                state["ai_video_wait_recovered_stale_successor"] = True
        has_active_video_tasks = bool(list(state.get("ai_video_task_ids") or []))
        if (
            not has_active_video_tasks
            and (project.current_stage != "WAITING_VIDEO_INPUT" or project.status != "generating_video")
        ):
            return {
                "status": "ignored_stale_waiter",
                "project_id": int(project.id),
                "project_stage": project.current_stage,
                "project_status": project.status,
            }
        state["ai_video_wait_task_id"] = request_id
        state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
        state.pop("ai_video_resume_failed_task_ids", None)
        project.state_json = state
        db.commit()
        task_ids = [int(value) for value in state.get("ai_video_task_ids") or []]
        tasks = _scoped_content_video_tasks(db, project, task_ids)
        if len(tasks) != len(task_ids):
            raise ValueError("AI video task records are incomplete")
        _sync_content_segment_execution_ledger(
            db,
            project=project,
            tasks=tasks,
        )
        superseded_media_task_ids = _superseded_media_group_task_ids(
            db,
            project,
            state,
        )

        # Provider-visible work is immutable. A deployment may change prompt
        # policy for future variants, but it must never invalidate submitted,
        # running, downloaded, or successful paid tasks. The manifest frozen
        # at submission remains the authority for this task group.

        invalid_copy_delivery_ids = (
            _invalidate_successful_segments_with_nonspoken_dialogue(
                db,
                project,
                tasks,
            )
        )
        if invalid_copy_delivery_ids:
            # Commit the fail-closed verdict before the retry scheduler creates
            # a replacement task.  In particular, do not release a chained
            # successor from a contaminated predecessor's final frame.
            db.commit()

        invalid_spoken_copy_ids = (
            _invalidate_successful_segments_with_missing_spoken_copy(
                db,
                project,
                tasks,
            )
        )
        if invalid_spoken_copy_ids:
            db.commit()

        released_dependency_ids = _release_ready_segment_dependencies(db, project, tasks)
        if released_dependency_ids:
            state = dict(project.state_json or {})
            task_ids = [int(value) for value in state.get("ai_video_task_ids") or []]
            tasks = _scoped_content_video_tasks(db, project, task_ids)

        # Collapse terminal dependency chains before computing pending work or
        # returning from any provider-cooldown branch.  Previously this ran
        # after the early retry/cooldown returns, so a child of an already
        # dependency-failed segment could remain waiting_dependency forever
        # and inflate the project's pending count even though no predecessor
        # could ever release it.
        dependency_failed_ids = _fail_unreleasable_segment_dependencies(
            db,
            project,
            tasks,
        )
        if dependency_failed_ids:
            db.commit()
            state = dict(project.state_json or {})
            task_ids = [
                int(value)
                for value in state.get("ai_video_task_ids") or []
            ]
            tasks = _scoped_content_video_tasks(db, project, task_ids)

        invalid_continuity_ids = (
            _invalidate_successful_segments_missing_continuity(
                db,
                project,
                tasks,
            )
        )
        if invalid_continuity_ids:
            db.commit()

        authority_race_recovered_ids = (
            _recover_premature_authority_rejections(
                db,
                project=project,
                tasks=tasks,
            )
        )
        if authority_race_recovered_ids:
            # Publish only after the restored task state and group pointer are
            # visible to the provider worker's independent SQL transaction.
            db.commit()
            state = dict(project.state_json or {})
            task_ids = [
                int(value)
                for value in state.get("ai_video_task_ids") or []
            ]
            tasks = _scoped_content_video_tasks(db, project, task_ids)

        queued_local_ids = _enqueue_queued_local_video_tasks(
            project,
            tasks,
            exclude_task_ids={
                *{int(value) for value in released_dependency_ids},
                *superseded_media_task_ids,
            },
        )
        if queued_local_ids:
            state = dict(project.state_json or {})
            state["ai_video_queued_local_resubmitted_at"] = _stage_now().isoformat()
            state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
            project.state_json = state
            if not draining_auto_paused_video:
                project.status = "generating_video"
            db.commit()
            next_task_id = _schedule_video_wait(
                db,
                project,
                countdown=20,
                reason=f"re-enqueued {len(queued_local_ids)} local video tasks before stale recovery was needed",
            )
            return {
                "status": "re_enqueued_queued_local_video_tasks",
                "task_ids": queued_local_ids,
                "next_wait_task_id": next_task_id,
            }

        is_segmented = dict(project.state_json or {}).get("ai_video_mode") == "segmented"
        quality_repair_task_ids = {
            *{int(value) for value in invalid_copy_delivery_ids},
            *{int(value) for value in invalid_spoken_copy_ids},
            *{int(value) for value in invalid_continuity_ids},
        }
        failed = [
            task
            for task in tasks
            if (
                _is_failed_video_task(task)
                or int(task.id) in quality_repair_task_ids
            )
            and int(task.id) not in superseded_media_task_ids
        ]
        pending = [
            task
            for task in tasks
            if not _is_terminal_video_task(task)
            and int(task.id) not in superseded_media_task_ids
        ]

        # Reconcile every locally downloaded complete group before waiting on
        # an unrelated provider failure.  The old order returned from the
        # cooldown branch first, so one 502 in variant 1 prevented an already
        # downloaded variant 2 from being reviewed, composed, counted and
        # replaced in the bounded parallel window.
        final_assets: list[HermesContentFactoryAsset] = []
        ready_assets: list[HermesContentFactoryAsset] = []
        completed_during_recovery: set[int] = set()
        if is_segmented and any(
            str(task.state or "").strip().lower() == "success"
            for task in tasks
        ):
            final_assets = _compose_segmented_videos(db, project, tasks)
            if final_assets:
                ready_assets = _bridge_video_assets(
                    db,
                    project,
                    final_assets,
                )
                state = dict(project.state_json or {})
                pipeline = _variant_pipeline(project)
                completed_during_recovery = set(
                    _authoritative_completed_variant_indices(
                        _completed_video_assets_by_index(
                            db,
                            project,
                        ).keys(),
                        target=int(
                            pipeline.get("target_count")
                            or _target_video_count(project)
                        ),
                    )
                )
                pipeline["completed_indices"] = sorted(
                    completed_during_recovery
                )
                pipeline["completion_blocked_missing_indices"] = [
                    index
                    for index in range(
                        1,
                        int(
                            pipeline.get("target_count")
                            or _target_video_count(project)
                        ) + 1,
                    )
                    if index not in completed_during_recovery
                ]
                pipeline["last_completed_at"] = _stage_now().isoformat()
                state["video_variant_pipeline"] = pipeline
                state["ai_video_ready_video_count"] = len(
                    completed_during_recovery
                )
                project.state_json = state
                db.add(project)
                db.commit()

        retry_task_ids = (
            _retry_failed_video_segments(
                db,
                project,
                failed,
                allow_exhausted_cooldown_retry=True,
            )
            if failed
            else []
        )
        if retry_task_ids:
            resumed_variant_stage = None
            if completed_during_recovery and not draining_auto_paused_video:
                resumed_variant_stage = (
                    _queue_next_unsubmitted_serial_variant_if_needed(
                        db,
                        project,
                        reason=(
                            "bounded API parallel pipeline replenished a "
                            "locally composed sibling while another provider "
                            "segment entered bounded recovery"
                        ),
                    )
                )
                if resumed_variant_stage is not None:
                    _publish_stage(resumed_variant_stage, project)
                    db.commit()
            next_task_id = _schedule_video_wait(
                db,
                project,
                countdown=20,
                reason=f"monitoring {len(retry_task_ids)} Hermes replacement segment attempts",
            )
            return {
                "status": "retrying_failed_segments",
                "retry_task_ids": retry_task_ids,
                "pending_existing": len(pending),
                "completed_during_recovery": sorted(
                    completed_during_recovery
                ),
                "queued_parallel_variant_stage_id": (
                    int(resumed_variant_stage.id)
                    if resumed_variant_stage is not None
                    else None
                ),
                "next_wait_task_id": next_task_id,
            }

        exhausted_quality_tasks = [
            task
            for task in failed
            if dict(
                dict(get_task_local_meta(task) or {}).get(
                    "content_quality_incident"
                )
                or {}
            )
        ]
        if exhausted_quality_tasks:
            now = _stage_now()
            state = dict(project.state_json or {})
            state.update({
                "ai_video_wait_task_id": None,
                "ai_video_wait_heartbeat_at": now.isoformat(),
                "pause_reason_code": FINAL_VIDEO_QUALITY_RECOVERY_REASON,
                "automatic_quality_paused_at": now.isoformat(),
                "paused_at": now.isoformat(),
                "final_video_quality_failure": {
                    "at": now.isoformat(),
                    "message": "segment quality repair epoch exhausted",
                    "task_ids": [
                        int(task.id) for task in exhausted_quality_tasks
                    ],
                    "evaluations": [
                        dict(
                            dict(get_task_local_meta(task) or {}).get(
                                "content_quality_incident"
                            )
                            or {}
                        )
                        for task in exhausted_quality_tasks
                    ],
                },
            })
            project.state_json = state
            project.status = "paused"
            project.last_error = (
                "供应商任务已成功并下载到本地，但独立质量评估的局部重做预算已用尽。"
                "Hermes 已停止本轮新增付费任务，冷却后将自动切换修复层级继续。"
            )
            db.add(project)
            db.commit()
            return {
                "status": "automatic_quality_cooldown",
                "reason_code": "quality_repair_budget_exhausted",
                "task_ids": [
                    int(task.id) for task in exhausted_quality_tasks
                ],
            }

        transient_retry_wait = _content_factory_transient_retry_wait_seconds(
            project,
            failed,
            now=_stage_now(),
        ) if failed else None
        if transient_retry_wait is not None:
            video_lane_message = (
                "视频供应商暂时不可用；Hermes 保留已完成片段和已审批文案，"
                f"将在约 {transient_retry_wait} 秒后按 API 管理优先级重试，"
                "不会退回编导或重复生成已完成片段。"
            )
            state = dict(project.state_json or {})
            state["ai_video_provider_cooldown_until"] = (
                _stage_now() + timedelta(seconds=transient_retry_wait)
            ).isoformat()
            state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
            state["ai_video_lane_status_message"] = video_lane_message
            state["ai_video_lane_status_updated_at"] = _stage_now().isoformat()
            project.state_json = state
            if not _project_has_live_control_stage(db, project):
                project.current_stage = "WAITING_VIDEO_INPUT"
                project.status = "generating_video"
                project.last_error = video_lane_message
            db.commit()
            resumed_variant_stage = None
            if completed_during_recovery and not draining_auto_paused_video:
                resumed_variant_stage = (
                    _queue_next_unsubmitted_serial_variant_if_needed(
                        db,
                        project,
                        reason=(
                            "bounded API parallel pipeline replenished a "
                            "locally composed sibling during provider cooldown"
                        ),
                    )
                )
                if resumed_variant_stage is not None:
                    _publish_stage(resumed_variant_stage, project)
                    db.commit()
            next_task_id = _schedule_video_wait(
                db,
                project,
                countdown=transient_retry_wait,
                reason="waiting for the next bounded provider-priority recovery round",
            )
            return {
                "status": "waiting_provider_recovery_cooldown",
                "failed_task_ids": [int(task.id) for task in failed],
                "retry_in_seconds": transient_retry_wait,
                "completed_during_recovery": sorted(
                    completed_during_recovery
                ),
                "queued_parallel_variant_stage_id": (
                    int(resumed_variant_stage.id)
                    if resumed_variant_stage is not None
                    else None
                ),
                "next_wait_task_id": next_task_id,
            }

        if is_segmented:
            _sync_content_segment_execution_ledger(
                db,
                project=project,
                tasks=tasks,
            )
            final_assets = _compose_segmented_videos(db, project, tasks)
            if final_assets:
                ready_assets = _bridge_video_assets(db, project, final_assets)
                db.commit()

        # Local composition and product-surface review can outlive an operator
        # pause request.  ``_compose_segmented_videos`` refreshes the project at
        # its final merge fence; re-evaluate pause ownership from that fresh
        # row before scheduling another waiter or another creative variant.
        # Already-submitted provider work remains durable and is picked up on
        # resume, but a manual pause must never be converted into an automatic
        # drain by a stale pre-review snapshot.
        post_media_pause_mode = _video_wait_pause_mode(project)
        if post_media_pause_mode in {"manual", "paused"}:
            db.commit()
            return {
                "status": "paused_after_media_reconcile",
                "project_id": int(project.id),
                "completed_local_video_count": len(final_assets),
            }
        draining_auto_paused_video = (
            post_media_pause_mode == "drain_submitted_video"
        )

        if pending:
            state = dict(project.state_json or {})
            state, authoritative_guides = _reconcile_editor_guidance_state(
                db,
                project,
                state,
            )
            pipeline = _variant_pipeline(project)
            completed = set(_authoritative_completed_variant_indices(
                _completed_video_assets_by_index(db, project).keys(),
                target=int(pipeline.get("target_count") or _target_video_count(project)),
            ))
            pipeline["completed_indices"] = sorted(completed)
            pipeline["completion_blocked_missing_indices"] = [
                index
                for index in range(
                    1,
                    int(
                        pipeline.get("target_count")
                        or _target_video_count(project)
                    ) + 1,
                )
                if index not in completed
            ]
            pipeline["last_completed_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
            state["video_variant_pipeline"] = pipeline
            completed_video_count = len(_completed_video_assets_by_index(db, project))
            state["ai_video_ready_video_count"] = completed_video_count
            state["ai_video_pending_task_ids"] = [int(task.id) for task in pending]
            state["ai_video_failed_task_ids"] = [int(task.id) for task in failed]
            project.state_json = state
            if project.current_stage == "WAITING_VIDEO_INPUT" and not draining_auto_paused_video:
                project.status = "generating_video"
            if final_assets:
                guide_count = len(authoritative_guides)
                if draining_auto_paused_video:
                    quality_note = str(state.get("pause_note") or "").strip()
                    project.last_error = (
                        f"质量暂停正在排空已提交任务：已合成 {completed_video_count} 个完整视频，"
                        f"并生成 {guide_count} 个剪辑发布指导；仍有 {len(pending)} 个片段在生成或下载。"
                        + (f" 原因：{quality_note}" if quality_note else "")
                    )[:4000]
                else:
                    project.last_error = (
                        f"已合成 {completed_video_count} 个完整视频，并生成 {guide_count} 个剪辑发布指导；仍有 {len(pending)} 个片段在生成或下载；"
                        "后台会继续合成，不会重新生成已完成视频。"
                    )
            rollout_checkpoint = _pause_at_variant_rollout_checkpoint(
                db,
                project,
                completed_variant_indices=completed,
            )
            if rollout_checkpoint is not None:
                db.commit()
                next_task_id = _schedule_video_wait(
                    db,
                    project,
                    countdown=20,
                    reason=(
                        "draining already-submitted provider work after variant "
                        "rollout checkpoint"
                    ),
                )
                return {
                    "status": "variant_rollout_checkpoint_draining",
                    "checkpoint": rollout_checkpoint,
                    "pending": len(pending),
                    "completed_videos": completed_video_count,
                    "next_wait_task_id": next_task_id,
                }
            resumed_variant_stage = None
            if not draining_auto_paused_video:
                resumed_variant_stage = _queue_next_unsubmitted_serial_variant_if_needed(
                    db,
                    project,
                    reason=(
                        "bounded API parallel pipeline replenished a completed variant "
                        "while other provider tasks are still downloading"
                    ),
                )
            db.commit()
            if resumed_variant_stage is not None:
                _publish_stage(resumed_variant_stage, project)
                db.commit()
            next_task_id = _schedule_video_wait(
                db,
                project,
                countdown=20,
                reason=f"waiting for {len(pending)} video tasks",
            )
            return {
                "status": "pending",
                "pending": len(pending),
                "completed_videos": completed_video_count,
                "queued_parallel_variant_stage_id": (
                    int(resumed_variant_stage.id) if resumed_variant_stage is not None else None
                ),
                "next_wait_task_id": next_task_id,
            }

        if failed and (not is_segmented or not final_assets):
            message = "; ".join(f"#{task.id}: {task.fail_msg or task.fail_code or task.state}" for task in failed)
            segment_execution_failure = any(
                str(task.fail_code or "").strip().lower()
                == SEGMENT_EXECUTION_QA_FAIL_CODE
                for task in failed
            )
            if is_segmented and _project_has_live_control_stage(db, project):
                retired = (
                    _retire_terminal_failed_video_groups_from_active_ledger(
                        project,
                        failed_task_ids=[int(task.id) for task in failed],
                    )
                )
                if retired is not None:
                    _record_hermes_observation(
                        db,
                        project,
                        category="video_variant_terminal_failure",
                        outcome="deferred_to_complete_video_target_gate",
                        provider=str(
                            _video_model_policy(project).get("provider_key")
                            or ""
                        ),
                        details={
                            "message": message[:600],
                            "retired_video_indices": retired["video_indices"],
                            "retired_task_ids": retired["task_ids"],
                            "control_stage": str(project.current_stage or ""),
                            "prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
                            "segment_execution_failure": (
                                segment_execution_failure
                            ),
                        },
                    )
                    db.commit()
                    next_wait_task_id = None
                    if retired["remaining_task_ids"]:
                        next_wait_task_id = _schedule_video_wait(
                            db,
                            project,
                            countdown=20,
                            reason=(
                                "draining remaining provider work after an "
                                "older variant exhausted execution QA"
                            ),
                        )
                    return {
                        "status": (
                            "draining_after_terminal_variant_failure"
                            if next_wait_task_id
                            else "terminal_variant_failure_deferred"
                        ),
                        "retired_video_indices": retired["video_indices"],
                        "retired_task_ids": retired["task_ids"],
                        "next_wait_task_id": next_wait_task_id,
                        "control_stage": str(project.current_stage or ""),
                    }
            reference_policy_failure = any(
                any(marker in str(task.fail_msg or task.fail_code or "").lower() for marker in (
                    "sy_err:8881",
                    "reference upload failed",
                    "previously flagged by content policy",
                    "image reference",
                ))
                for task in failed
            )
            if reference_policy_failure:
                state = dict(project.state_json or {})
                repair_counts = dict(state.get("repair_counts") or {})
                count = int(repair_counts.get("provider_reference_policy") or 0)
                if count < 5:
                    repair_counts["provider_reference_policy"] = count + 1
                    learning = dict(state.get("hermes_learning") or {})
                    model_learning = dict(learning.get("omni_flash") or {})
                    model_learning.update({
                        "avoid_provider_flagged_reference_composition": True,
                        "avoid_direct_neck_chest_or_restraining_contact": True,
                        "preserve_high_intensity_with_non_contact_actions": True,
                        "preferred_intensity_actions": [
                            "shouting", "door slamming", "forceful gestures",
                            "thrown pillow", "object impact", "abrupt movement",
                        ],
                        "last_failure": "provider_reference_image_content_policy_block",
                        "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                    })
                    learning["omni_flash"] = model_learning
                    state["repair_counts"] = repair_counts
                    state["hermes_learning"] = learning
                    state["last_video_generation_error"] = message[:1000]
                    state["ai_video_task_ids"] = []
                    state["ai_video_groups"] = []
                    state["ai_video_pending_task_ids"] = []
                    state["ai_video_failed_task_ids"] = [int(task.id) for task in failed]
                    state["ai_video_wait_task_id"] = None
                    state.pop("ai_video_terminal_failure", None)
                    project.state_json = state
                    _persist_hermes_learning(db, project, learning)
                    _clean_generated_stage_assets(db, project, ("VISUAL_PREVIEW", "FINAL_ASSETS"))
                    for stage in db.query(HermesContentFactoryStage).filter(
                        HermesContentFactoryStage.project_id == project.id,
                        HermesContentFactoryStage.stage.in_((
                            "VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS",
                            "VIDEO_PROMPTS", "EDIT_PACKAGE",
                        )),
                        HermesContentFactoryStage.status.in_(("queued", "running", "retrying", "success")),
                    ).all():
                        stage.status = "failed"
                        stage.error_message = "Superseded by provider reference-policy self-repair."
                    project.current_stage = "VISUAL_PREVIEW"
                    project.status = "ready"
                    project.last_error = (
                        "视频供应商封禁了参考图，Hermes 正在自动重做高强度但供应商可接受的视觉画板。"
                    )
                    db.commit()
                    from app.services.hermes_agent.content_factory import queue_stage
                    queue_stage(
                        db,
                        project=project,
                        user_id=int(project.user_id),
                        instruction=(
                            "The video provider permanently blocked the prior reference image by MD5. Regenerate one ordered visual board "
                            "with the same explosive relationship-conflict hook and fictional adult characters. Keep shouting, door slamming, "
                            "forceful gestures, thrown pillows, object impact, abrupt movement, and strong facial emotion. Do not soften the pacing or stakes. "
                            "However, every panel must be provider-safe as an isolated reference image: no hands on neck/chest, no grabbing, no pinning, "
                            "no restraining contact, no direct assault pose, no visible injury, no blood, no weapon-like object, no scared victim composition, "
                            "and no nested picture-in-picture. Use non-contact staging, clear spatial separation, objects hitting furniture, door slams, "
                            "fast gestures, phone glow, messy bedding, and product/bedside anchors so every split reference can pass upload screening. Continue unattended."
                        ),
                    )
                    db.commit()
                    return {
                        "status": "self_healed_requeued_provider_safe_visual_preview",
                        "project_id": int(project.id),
                    }
            real_person_failure = any(
                "volc_real_person" in str(task.fail_code or "").lower()
                or "真人" in str(task.fail_msg or "")
                or "人脸" in str(task.fail_msg or "")
                for task in failed
            )
            if real_person_failure and _video_model_policy(project).get("id") == "seedance_2_0":
                state = dict(project.state_json or {})
                repair_counts = dict(state.get("repair_counts") or {})
                count = int(repair_counts.get("seedance_real_person_reference") or 0)
                if count < 2:
                    repair_counts["seedance_real_person_reference"] = count + 1
                    learning = dict(state.get("hermes_learning") or {})
                    seedance_learning = dict(learning.get("seedance_2_0") or {})
                    seedance_learning.update({
                        "avoid_human_face_reference_images": True,
                        "prefer_product_hands_room_and_prop_anchors": True,
                        "last_failure": "volc_real_person_reference_rejected",
                        "updated_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
                    })
                    learning["seedance_2_0"] = seedance_learning
                    state["repair_counts"] = repair_counts
                    state["hermes_learning"] = learning
                    state["last_video_generation_error"] = message[:1000]
                    state["ai_video_task_ids"] = []
                    state["ai_video_groups"] = []
                    project.state_json = state
                    _persist_hermes_learning(db, project, learning)
                    _clean_generated_stage_assets(db, project, ("VISUAL_PREVIEW", "FINAL_ASSETS"))
                    for stage in db.query(HermesContentFactoryStage).filter(
                        HermesContentFactoryStage.project_id == project.id,
                        HermesContentFactoryStage.stage.in_(("VISUAL_PREVIEW", "CREATIVE_REVIEW", "FINAL_ASSETS", "VIDEO_PROMPTS", "EDIT_PACKAGE")),
                        HermesContentFactoryStage.status.in_(("queued", "running", "retrying", "success")),
                    ).all():
                        stage.status = "failed"
                        stage.error_message = "Superseded by Seedance no-face self-repair."
                    project.current_stage = "VISUAL_PREVIEW"
                    project.status = "ready"
                    project.last_error = (
                        "Seedance rejected human/face references; automatically regenerating "
                        "a no-face visual reference board and continuing from the breakpoint."
                    )
                    db.commit()
                    from app.services.hermes_agent.content_factory import queue_stage
                    queue_stage(
                        db,
                        project=project,
                        user_id=int(project.user_id),
                        instruction=(
                            "Seedance rejected visible human/face references. Regenerate the visual preview as one "
                            "single board with no visible faces: product/package, hands-only, room, prop, "
                            "cropped-below-chin, back-of-head, and face-hidden action anchors only. Continue unattended."
                        ),
                    )
                    db.commit()
                    return {"status": "self_healed_requeued_no_face_visual_preview", "project_id": int(project.id)}
            project.status = "failed"
            project.last_error = "AI video generation failed: " + message
            state = dict(project.state_json or {})
            state["ai_video_wait_task_id"] = None
            state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
            state["ai_video_terminal_failure"] = message[:2000]
            project.state_json = state
            _record_hermes_observation(
                db,
                project,
                category="video_provider_failure",
                outcome="failure",
                provider=str(_video_model_policy(project).get("provider_key") or ""),
                details={
                    "message": message[:600],
                    "failed_task_ids": [int(task.id) for task in failed],
                    "prompt_policy_version": VIDEO_PROMPT_POLICY_VERSION,
                },
            )
            db.commit()
            return {"status": "failed", "error": message}

        if is_segmented:
            if not final_assets:
                state = dict(project.state_json or {})
                failed_groups = list(state.get("ai_video_failed_groups") or [])
                remote_links = [
                    url
                    for group in failed_groups
                    for url in group.get("remote_result_urls", [])
                    if url
                ]
                project.status = "failed"
                project.last_error = (
                    "AI video generation finished but no complete video could be composed."
                    + (f" Remote result links: {'; '.join(remote_links[:10])}" if remote_links else "")
                )
                db.commit()
                return {"status": "failed", "error": project.last_error}
            if not ready_assets:
                ready_assets = _bridge_video_assets(db, project, final_assets)
        else:
            if failed:
                successful_tasks = [task for task in tasks if str(task.state or "").lower() == "success"]
                if not successful_tasks:
                    message = "; ".join(f"#{task.id}: {task.fail_msg or task.fail_code or task.state}" for task in failed)
                    project.status = "failed"
                    project.last_error = "AI video generation failed: " + message
                    db.commit()
                    return {"status": "failed", "error": message}
                tasks = successful_tasks
            ready_assets = _prepare_video_assets_from_tasks(db, project, tasks)
        if not ready_assets:
            raise ValueError("No complete video asset is ready for the publishing package")
        state = dict(project.state_json or {})
        state, authoritative_guides = _reconcile_editor_guidance_state(
            db,
            project,
            state,
        )
        state["ai_video_pending_task_ids"] = []
        state["ai_video_failed_task_ids"] = [int(task.id) for task in failed]
        state["ai_video_ready_video_count"] = len(ready_assets)
        state["ai_video_wait_task_id"] = None
        state["ai_video_wait_heartbeat_at"] = _stage_now().isoformat()
        pipeline = _variant_pipeline(project)
        completed = set(_authoritative_completed_variant_indices(
            _completed_video_assets_by_index(db, project).keys(),
            target=int(pipeline.get("target_count") or _target_video_count(project)),
        ))
        pipeline["completed_indices"] = sorted(completed)
        pipeline["completion_blocked_missing_indices"] = [
            index
            for index in range(
                1,
                int(
                    pipeline.get("target_count")
                    or _target_video_count(project)
                ) + 1,
            )
            if index not in completed
        ]
        pipeline["failed_indices"] = sorted({
            int(value)
            for value in list(pipeline.get("failed_indices") or [])
            if str(value).strip().isdigit() and int(value) not in completed
        })
        pipeline["last_completed_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        state["video_variant_pipeline"] = pipeline
        completed_video_count = len(_completed_video_assets_by_index(db, project))
        state["ai_video_ready_video_count"] = completed_video_count
        project.state_json = state
        rollout_checkpoint = _pause_at_variant_rollout_checkpoint(
            db,
            project,
            completed_variant_indices=completed,
        )
        if rollout_checkpoint is not None:
            state = dict(project.state_json or {})
            state["ai_video_wait_task_id"] = None
            project.state_json = state
            db.commit()
            return {
                "status": "variant_rollout_checkpoint",
                "checkpoint": rollout_checkpoint,
                "completed_variants": sorted(completed),
                "target": int(
                    pipeline.get("target_count")
                    or _target_video_count(project)
                ),
                "editor_guidance_assets": len(authoritative_guides),
            }
        if _sequential_variants_enabled(project):
            target = int(pipeline.get("target_count") or _target_video_count(project))
            submitted = {
                int(value) for value in list(pipeline.get("submitted_indices") or [])
                if str(value).strip().isdigit()
            }
            resumed_variant_stage = None
            if len(completed) < target:
                project.state_json = state
                if draining_auto_paused_video:
                    state["auto_paused_video_drain_completed_at"] = (
                        datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
                    )
                    project.state_json = state
                    project.status = "paused"
                    guide_count = len(authoritative_guides)
                    project.last_error = (
                        f"已完成自动暂停前提交的 {len(completed)}/{target} 条完整视频，"
                        f"并生成 {guide_count} 个对应剪辑发布指导；未自动开启新的创意变体。"
                    )
                    db.commit()
                    return {
                        "status": "drained_submitted_video_while_quality_paused",
                        "completed_variants": sorted(completed),
                        "submitted_variants": sorted(submitted),
                        "target": target,
                        "editor_guidance_assets": guide_count,
                    }
                if len(submitted) < target:
                    # Replenish a terminal hole before admitting a fresh
                    # ordinal.  Otherwise one exhausted variant can cause the
                    # pipeline to spend through every later variant and only
                    # repair the missing deliverable at the very end.
                    terminal_failed_variants = (
                        _terminal_failed_video_variant_indices(project)
                    )
                    if terminal_failed_variants:
                        resumed_variant_stage = _queue_missing_serial_video_variant_if_needed(
                            db,
                            project,
                            reason=(
                                "complete-video target gate prioritized the first "
                                "terminal failed variant before new variant admission"
                            ),
                        )
                    if resumed_variant_stage is None:
                        resumed_variant_stage = _queue_next_unsubmitted_serial_variant_if_needed(
                            db,
                            project,
                            reason=(
                                "video waiter resumed the next unsubmitted serial "
                                "variant after completed downloads"
                            ),
                        )
                else:
                    resumed_variant_stage = _queue_missing_serial_video_variant_if_needed(
                        db,
                        project,
                        reason="complete-video target gate requeued the first missing variant",
                    )
                if resumed_variant_stage is not None:
                    task_id = _publish_stage(resumed_variant_stage, project)
                    db.commit()
                    return {
                        "status": "queued_remaining_or_missing_serial_variant",
                        "stage_id": int(resumed_variant_stage.id),
                        "stage": resumed_variant_stage.stage,
                        "celery_task_id": task_id,
                        "completed_variants": sorted(completed),
                        "submitted_variants": sorted(submitted),
                        "target": target,
                    }
                guide_count = len(authoritative_guides)
                _set_serial_variant_progress_message(
                    project,
                    completed_count=len(completed),
                    target_count=target,
                    guide_count=guide_count,
                )
                db.commit()
                return {
                    "status": "waiting_for_remaining_serial_variants",
                    "completed_variants": sorted(completed),
                    "submitted_variants": sorted(submitted),
                    "target": target,
                }
        guide_count = len(authoritative_guides)
        state = _finalize_variant_pipeline_state(
            state,
            completed_indices=completed,
            target=int(
                pipeline.get("target_count")
                or _target_video_count(project)
            ),
        )
        state["edit_package_mode"] = "per_video_server_generated"
        state["edit_package_completed_at"] = datetime.now(timezone.utc).replace(tzinfo=None).isoformat()
        project.state_json = state
        project.current_stage = "COMPLETE"
        project.status = "complete"
        from app.services.hermes_agent.content_factory import (
            _record_project_transition,
            _release_bridge_for_project,
        )

        _record_project_transition(
            project,
            stage="COMPLETE",
            status="complete",
            reason="target_deliverables_completed",
        )
        project.last_error = (
            f"{len(failed)} 个视频片段失败，已用 {completed_video_count} 个完整视频生成 {guide_count} 个剪辑发布指导。"
            if failed
            else f"已完成 {completed_video_count} 个完整视频，并生成 {guide_count} 个对应剪辑发布指导。"
        )
        _release_bridge_for_project(db, project_id=int(project.id))
        db.commit()
        return {"status": "success", "next_stage": "COMPLETE", "editor_guidance_assets": guide_count}
    except MaxRetriesExceededError:
        project = db.get(HermesContentFactoryProject, int(project_id))
        if project:
            project.status = "failed"
            project.last_error = "Timed out waiting for AI video downloads"
            db.commit()
        return {"status": "timeout"}
    except ValueError as exc:
        message = str(exc)
        segment_failure = re.search(
            r"CONTENT_SEGMENT_EXECUTION_QA_FAILED_TASK_(\d+)",
            message,
        )
        if (
            not message.startswith("CONTENT_FINAL_QUALITY_GATE_FAILED:")
            and segment_failure is None
        ):
            raise
        db.rollback()
        project = (
            db.query(HermesContentFactoryProject)
            .filter(HermesContentFactoryProject.id == int(project_id))
            .with_for_update()
            .one_or_none()
        )
        if project is None:
            return {"status": "missing"}
        if segment_failure is not None:
            failed_task_id = int(segment_failure.group(1))
            failed_task = (
                db.query(KieTask)
                .filter(
                    KieTask.id == failed_task_id,
                    KieTask.workspace_id == int(project.workspace_id),
                )
                .with_for_update()
                .one_or_none()
            )
            failed_params = (
                dict(failed_task.input_json or {}) if failed_task else {}
            )
            if (
                failed_task is None
                or int(
                    failed_params.get("content_factory_project_id") or 0
                ) != int(project.id)
                or (
                    project.user_id is not None
                    and int(failed_task.created_by_user_id or 0)
                    != int(project.user_id)
                )
            ):
                raise ValueError(
                    "Segment execution failure did not belong to the locked "
                    "content-factory project"
                )
            review: dict[str, Any] = {
                "blocking": True,
                "status": "fail",
                "policy_version": (
                    SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
                ),
                "blocking_reasons": [
                    message.split(" || REVIEW_JSON ", 1)[0]
                ],
            }
            if " || REVIEW_JSON " in message:
                try:
                    decoded = json.loads(
                        message.split(" || REVIEW_JSON ", 1)[1]
                    )
                    if isinstance(decoded, dict):
                        review = decoded
                except (TypeError, ValueError, json.JSONDecodeError):
                    pass
            set_task_local_meta(
                failed_task,
                segment_execution_review=review,
                segment_execution_qa_failed_at=_stage_now().isoformat(),
            )
            _set_content_quality_incident(
                failed_task,
                code=SEGMENT_EXECUTION_QA_FAIL_CODE,
                message=message,
                evidence=review,
            )
            record_content_evaluation(
                db,
                project=project,
                task=failed_task,
                evaluation_kind="segment_execution",
                policy_version=str(
                    review.get("policy_version")
                    or SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
                ),
                status="repair_required",
                blocking=True,
                input_sha256=_quality_evaluation_sha256(
                    failed_task,
                    review,
                ),
                evidence=review,
            )
            db.add(failed_task)
            db.flush()
            retry_task_ids = _retry_failed_video_segments(
                db,
                project,
                [failed_task],
            )
            if retry_task_ids:
                next_task_id = _schedule_video_wait(
                    db,
                    project,
                    countdown=20,
                    reason="monitoring multimodal segment execution repair",
                )
                return {
                    "status": "retrying_segment_execution",
                    "failed_task_id": failed_task_id,
                    "retry_task_ids": retry_task_ids,
                    "next_wait_task_id": next_task_id,
                    "segment_execution_review": review,
                }
            db.commit()
            return {
                "status": "segment_execution_retry_exhausted",
                "failed_task_id": failed_task_id,
                "segment_execution_review": review,
            }
        final_intent_report: dict[str, Any] = {}
        final_intent_marker = "CONTENT_FINAL_INTENT_QA_FAILED "
        final_intent_at = message.find(final_intent_marker)
        if final_intent_at >= 0:
            report: dict[str, Any] = {}
            try:
                decoded, _end = json.JSONDecoder().raw_decode(
                    message[
                        final_intent_at + len(final_intent_marker):
                    ].lstrip()
                )
                if isinstance(decoded, dict):
                    report = decoded
            except (TypeError, ValueError, json.JSONDecodeError):
                report = {}
            final_intent_report = dict(report)
            affected_task_ids = [
                int(value)
                for value in list(report.get("affected_task_ids") or [])
                if str(value).isdigit() and int(value) > 0
            ]
            if (
                str(report.get("repair_scope") or "").strip().lower()
                == "segment_regeneration"
                and affected_task_ids
            ):
                failed_intent_tasks: list[KieTask] = []
                execution_review = {
                    "blocking": True,
                    "status": "fail",
                    # The retry prompt compiler validates visual-execution
                    # repair prose against this policy before allowing it into
                    # the provider's small text lane.  The composition review
                    # has its own version below and owns the retry budget key;
                    # putting that version here silently dropped the actual
                    # repair instruction from Doubao's 495-character payload.
                    "policy_version": (
                        SEGMENT_EXECUTION_VIDEO_REVIEW_POLICY_VERSION
                    ),
                    "final_intent_policy_version": report.get(
                        "policy_version"
                    ),
                    "failed_requirement_ids": list(
                        report.get("blocking_requirement_ids") or []
                    ),
                    "blocking_reasons": list(
                        report.get("blocking_reasons") or []
                    ),
                    "repair_instruction": str(
                        report.get("repair_instruction") or ""
                    )[:1200],
                    "requirement_evidence": dict(
                        report.get("requirement_evidence") or {}
                    ),
                }
                for failed_task_id in affected_task_ids:
                    failed_task = (
                        db.query(KieTask)
                        .filter(
                            KieTask.id == failed_task_id,
                            KieTask.workspace_id == int(project.workspace_id),
                        )
                        .with_for_update()
                        .one_or_none()
                    )
                    if failed_task is None:
                        continue
                    failed_params = dict(failed_task.input_json or {})
                    if (
                        int(
                            failed_params.get("content_factory_project_id")
                            or 0
                        )
                        != int(project.id)
                        or (
                            project.user_id is not None
                            and int(failed_task.created_by_user_id or 0)
                            != int(project.user_id)
                        )
                    ):
                        continue
                    set_task_local_meta(
                        failed_task,
                        segment_execution_review=execution_review,
                        final_intent_qa_failed_at=_stage_now().isoformat(),
                        final_intent_qa_failure=report,
                    )
                    _set_content_quality_incident(
                        failed_task,
                        code=SEGMENT_EXECUTION_QA_FAIL_CODE,
                        message=message,
                        evidence=report,
                    )
                    record_content_evaluation(
                        db,
                        project=project,
                        task=failed_task,
                        evaluation_kind="final_intent",
                        policy_version=str(
                            report.get("policy_version")
                            or FINAL_INTENT_REVIEW_POLICY_VERSION
                        ),
                        status="repair_required",
                        blocking=True,
                        input_sha256=_quality_evaluation_sha256(
                            failed_task,
                            report,
                        ),
                        evidence=report,
                    )
                    db.add(failed_task)
                    failed_intent_tasks.append(failed_task)
                db.flush()
                retry_task_ids = _retry_failed_video_segments(
                    db,
                    project,
                    failed_intent_tasks,
                )
                if retry_task_ids:
                    next_task_id = _schedule_video_wait(
                        db,
                        project,
                        countdown=20,
                        reason=(
                            "monitoring final-intent evidence segment retries"
                        ),
                    )
                    return {
                        "status": "retrying_final_intent_segments",
                        "retry_task_ids": retry_task_ids,
                        "next_wait_task_id": next_task_id,
                        "final_intent_review": report,
                    }
        voice_failure = re.search(
            r"CONTENT_VOICE_CONTINUITY_QA_FAILED_TASKS_([0-9_]+)",
            message,
        )
        if voice_failure is not None:
            failed_task_ids = [
                int(value)
                for value in voice_failure.group(1).split("_")
                if value.isdigit()
            ]
            report: dict[str, Any] = {}
            report_start = message.find("{")
            if report_start >= 0:
                try:
                    parsed_report = json.loads(message[report_start:])
                    if isinstance(parsed_report, dict):
                        report = parsed_report
                except (TypeError, ValueError, json.JSONDecodeError):
                    report = {}
            repair_by_task_id = dict(report.get("repair_by_task_id") or {})
            failed_voice_tasks: list[KieTask] = []
            for failed_task_id in failed_task_ids:
                failed_task = (
                    db.query(KieTask)
                    .filter(
                        KieTask.id == failed_task_id,
                        KieTask.workspace_id == int(project.workspace_id),
                    )
                    .with_for_update()
                    .one_or_none()
                )
                if failed_task is None:
                    continue
                failed_params = dict(failed_task.input_json or {})
                if (
                    int(failed_params.get("content_factory_project_id") or 0)
                    != int(project.id)
                    or (
                        project.user_id is not None
                        and int(failed_task.created_by_user_id or 0)
                        != int(project.user_id)
                    )
                ):
                    continue
                repair = dict(
                    repair_by_task_id.get(str(failed_task_id)) or {}
                )
                set_task_local_meta(
                    failed_task,
                    voice_continuity_qa_failed_at=_stage_now().isoformat(),
                    voice_continuity_repair=repair,
                )
                voice_evidence = {**dict(report or {}), "repair": repair}
                _set_content_quality_incident(
                    failed_task,
                    code=VOICE_CONTINUITY_FAIL_CODE,
                    message=message,
                    evidence=voice_evidence,
                )
                record_content_evaluation(
                    db,
                    project=project,
                    task=failed_task,
                    evaluation_kind="voice_continuity",
                    policy_version=VOICE_CONTINUITY_QA_POLICY_VERSION,
                    status="repair_required",
                    blocking=True,
                    input_sha256=_quality_evaluation_sha256(
                        failed_task,
                        voice_evidence,
                    ),
                    evidence=voice_evidence,
                )
                db.add(failed_task)
                failed_voice_tasks.append(failed_task)
            db.flush()
            retry_task_ids = _retry_failed_video_segments(
                db,
                project,
                failed_voice_tasks,
            )
            if retry_task_ids:
                next_task_id = _schedule_video_wait(
                    db,
                    project,
                    countdown=20,
                    reason="monitoring speaker acoustic continuity retries",
                )
                return {
                    "status": "retrying_voice_continuity_segments",
                    "retry_task_ids": retry_task_ids,
                    "next_wait_task_id": next_task_id,
                    "voice_continuity": report,
                }
        product_failure = re.search(
            r"CONTENT_PRODUCT_VIDEO_VISUAL_QA_FAILED_TASK_(\d+)",
            message,
        )
        if product_failure is not None:
            failed_task_id = int(product_failure.group(1))
            failed_task = (
                db.query(KieTask)
                .filter(
                    KieTask.id == failed_task_id,
                    KieTask.workspace_id == int(project.workspace_id),
                )
                .with_for_update()
                .one_or_none()
            )
            failed_params = dict(failed_task.input_json or {}) if failed_task else {}
            if (
                failed_task is not None
                and int(failed_params.get("content_factory_project_id") or 0)
                == int(project.id)
                and (
                    project.user_id is None
                    or int(failed_task.created_by_user_id or 0)
                    == int(project.user_id)
                )
            ):
                set_task_local_meta(
                    failed_task,
                    product_visual_qa_failed_at=_stage_now().isoformat(),
                    product_visual_qa_failure=message[:3000],
                )
                product_evidence = {
                    "message": message[:3000],
                    "provider_product_video_review": dict(
                        dict(get_task_local_meta(failed_task) or {}).get(
                            "provider_product_video_review"
                        )
                        or {}
                    ),
                }
                _set_content_quality_incident(
                    failed_task,
                    code=PRODUCT_VISUAL_QA_FAIL_CODE,
                    message=message,
                    evidence=product_evidence,
                )
                record_content_evaluation(
                    db,
                    project=project,
                    task=failed_task,
                    evaluation_kind="product_identity",
                    policy_version=str(
                        product_evidence[
                            "provider_product_video_review"
                        ].get("policy_version")
                        or PRODUCT_REFERENCE_VIDEO_REVIEW_POLICY_VERSION
                    ),
                    status="repair_required",
                    blocking=True,
                    input_sha256=_quality_evaluation_sha256(
                        failed_task,
                        product_evidence,
                    ),
                    evidence=product_evidence,
                )
                db.add(failed_task)
                db.flush()
                retry_task_ids = _retry_failed_video_segments(
                    db,
                    project,
                    [failed_task],
                )
                if retry_task_ids:
                    next_task_id = _schedule_video_wait(
                        db,
                        project,
                        countdown=20,
                        reason=(
                            "monitoring product-identity visual QA segment "
                            "retry"
                        ),
                    )
                    return {
                        "status": "retrying_product_visual_segment",
                        "retry_task_ids": retry_task_ids,
                        "next_wait_task_id": next_task_id,
                    }
        now = _stage_now()
        state = dict(project.state_json or {})
        state.update({
            "ai_video_wait_task_id": None,
            "ai_video_wait_heartbeat_at": now.isoformat(),
            "pause_reason_code": "final_video_quality_gate",
            "automatic_quality_paused_at": now.isoformat(),
            "paused_at": now.isoformat(),
            "pause_note": message[:3000],
            "browser_slot_mode": "dormant",
            "final_video_quality_failure": {
                "at": now.isoformat(),
                "message": message[:3000],
                "final_intent_report": final_intent_report,
                "task_ids": [
                    int(value)
                    for value in list(
                        final_intent_report.get("affected_task_ids") or []
                    )
                    if str(value).strip().isdigit()
                ],
            },
        })
        project.state_json = state
        project.status = "paused"
        project.last_error = (
            "成片未通过最终质量门，已停止新增创意和付费任务："
            + message.removeprefix(
                "CONTENT_FINAL_QUALITY_GATE_FAILED:"
            ).strip()
        )[:4000]
        from app.services.hermes_agent.content_factory import (
            _release_bridge_for_project,
        )

        _release_bridge_for_project(db, project_id=int(project.id))
        db.commit()
        return {
            "status": "quality_paused",
            "reason_code": "final_video_quality_gate",
            "error": message,
        }
    finally:
        if waiter_lock_acquired:
            try:
                _release_content_video_wait_lock(
                    waiter_lock_connection,
                    project_id=int(project_id),
                )
            except Exception:
                # Closing an invalidated connection also releases MySQL named
                # locks, so lock cleanup must never mask the original result.
                pass
        db.close()
